window.QUESTIONS = [
  // ==================== 概述 ====================
  { id: 1, cat: "概述", q: "《民用无人驾驶航空器实名制登记管理规定》适用于（）的无人机。", opts: ["空机重量超过 250 克", "最大起飞重量不高于 7 公斤的视距内运行", "最大起飞重量不低于 250 克"], ans: 2, exp: "《民用无人驾驶航空器实名制登记管理规定》1.2 适用范围本管理规定适用于在中华 人民共和国境内最大起飞重量为 250 克以上（含 250 克）。" },
  { id: 2, cat: "概述", q: "Ⅰ类无人机是指（）", opts: ["空机质量＞0kg，起飞全重≤1.5kg", "空机质量≤0.5kg，起飞全重≤1.5kg", "空机质量≤1kg，起飞全重≤2kg"], ans: 0, exp: "根据无人机空机质量和起飞全重的分类标准，无人机可以分为： Ⅰ类无人机：空机质量＞0kg，起飞全重≤1.5kg 的无人机。这类无人机通常用于娱乐和非 商业用途。 Ⅱ类无人机：1.5kg＜空机质量<4kg，1.5kg<起飞全重<7kg 的无人机。这类无人机可能用 于商业摄影、农业监测等。 Ⅲ类无人机：4kg＜空机质量≤15kg，7kg＜起飞全重<25kg 的无人机。这类无人机可能用 于更专业的应用，如工业检查或安全监控。 Ⅳ类无人机：15kg＜空机质量≤116kg, 25kg~起飞全重<150kg 的无人机。这类无人机通常 用于更重的商业和工业应用。 Ⅵ类无人机：116kg＜空机质量<5700kg 的无人机。这类无人机属于大型无人机，可能用于 货运、军事或其他专业用途。 Ⅻ类无人机：空机质量＞5700kg 的无人机。" },
  { id: 3, cat: "概述", q: "Ⅱ类无人机是指（）", opts: ["1kg≤空机质量≤7kg，2kg≤起飞全重≤15kg", "0.5kg<空机质量<7kg, 1.5kg≤起飞全重≤15kg", "1.5kg＜空机质量≤4kg，1.5kg≤起飞全重≤7kg"], ans: 2, exp: "根据无人机空机质量和起飞全重的分类标准，无人机可以分为： Ⅰ类无人机：空机质量＞0kg，起飞全重≤1.5kg 的无人机。这类无人机通常用于娱乐和非 商业用途。 Ⅱ类无人机：1.5kg＜空机质量<4kg，1.5kg<起飞全重<7kg 的无人机。这类无人机可能用 于商业摄影、农业监测等。 Ⅲ类无人机：4kg＜空机质量≤15kg，7kg＜起飞全重<25kg 的无人机。这类无人机可能用 于更专业的应用，如工业检查或安全监控。 Ⅳ类无人机：15kg＜空机质量≤116kg, 25kg~起飞全重<150kg 的无人机。这类无人机通常 用于更重的商业和工业应用。 Ⅵ类无人机：116kg＜空机质量<5700kg 的无人机。这类无人机属于大型无人机，可能用于 货运、军事或其他专业用途。 Ⅻ类无人机：空机质量＞5700kg 的无人机。" },
  { id: 4, cat: "概述", q: "Ⅲ类无人机是指（）", opts: ["7kg≤空机质量≤10kg，10kg≤起飞全重≤20kg", "4kg＜空机质量≤15kg，7kg＜起飞全重≤25kg", "5kg≤空机质量≤10kg，15kg≤起飞全重≤25kg"], ans: 1, exp: "根据无人机空机质量和起飞全重的分类标准，无人机可以分为： Ⅰ类无人机：空机质量＞0kg，起飞全重≤1.5kg 的无人机。这类无人机通常用于娱乐和非 商业用途。 Ⅱ类无人机：1.5kg＜空机质量<4kg，1.5kg<起飞全重<7kg 的无人机。这类无人机可能用 于商业摄影、农业监测等。 Ⅲ类无人机：4kg＜空机质量≤15kg，7kg＜起飞全重<25kg 的无人机。这类无人机可能用 于更专业的应用，如工业检查或安全监控。 Ⅳ类无人机：15kg＜空机质量≤116kg, 25kg~起飞全重<150kg 的无人机。这类无人机通常 用于更重的商业和工业应用。 Ⅵ类无人机：116kg＜空机质量<5700kg 的无人机。这类无人机属于大型无人机，可能用于 货运、军事或其他专业用途。 Ⅻ类无人机：空机质量＞5700kg 的无人机。" },
  { id: 5, cat: "概述", q: "Ⅳ类无人机是指（）", opts: ["0<空机重量≤1.5kg，7kg＜起飞全重≤25kg", "15kg ＜空机重量≤116kg，25kg＜起飞全重≤150kg", "1.5kg ＜空机重量≤4kg, 25kg<起飞全重≤150kg"], ans: 1, exp: "根据无人机空机质量和起飞全重的分类标准，无人机可以分为： Ⅰ类无人机：空机质量＞0kg，起飞全重≤1.5kg 的无人机。这类无人机通常用于娱乐和非 商业用途。 Ⅱ类无人机：1.5kg＜空机质量<4kg，1.5kg<起飞全重<7kg 的无人机。这类无人机可能用 于商业摄影、农业监测等。 Ⅲ类无人机：4kg＜空机质量≤15kg，7kg＜起飞全重<25kg 的无人机。这类无人机可能用 于更专业的应用，如工业检查或安全监控。 Ⅳ类无人机：15kg＜空机质量≤116kg, 25kg~起飞全重<150kg 的无人机。这类无人机通常 用于更重的商业和工业应用。 Ⅵ类无人机：116kg＜空机质量<5700kg 的无人机。这类无人机属于大型无人机，可能用于 货运、军事或其他专业用途。 Ⅻ类无人机：空机质量＞5700kg 的无人机。" },
  { id: 6, cat: "概述", q: "Ⅺ类无人机是指（）", opts: ["W> 5700kg", "15kg <W≤116kg", "116kg <W≤5700kg"], ans: 2, exp: "Ⅺ类无人机指的是起飞全重在 116kg 至 5700kg 之间的无人机。根据民航局发布的 《特定类无人机试运行管理规程（暂行）》中的定义，特定类民用无人机运行包括起飞全重 在 25 公斤至 150 公斤的无人机运行，也包括 7 公斤至 25 公斤、运行风险较大的特定种类无 人机运行，以及 150 公斤以上、运行风险较小的特定种类无人机运行。" },
  { id: 7, cat: "概述", q: "Ⅻ类无人机是指（）", opts: ["W > 5700kg", "W≥5700kg", "W<5700kg"], ans: 0, exp: "根据无人机空机质量和起飞全重的分类标准，无人机可以分为： Ⅰ类无人机：空机质量＞0kg，起飞全重≤1.5kg 的无人机。这类无人机通常用于娱乐和非 商业用途。 Ⅱ类无人机：1.5kg＜空机质量<4kg，1.5kg<起飞全重<7kg 的无人机。这类无人机可能用 于商业摄影、农业监测等。 Ⅲ类无人机：4kg＜空机质量≤15kg，7kg＜起飞全重<25kg 的无人机。这类无人机可能用 于更专业的应用，如工业检查或安全监控。 Ⅳ类无人机：15kg＜空机质量≤116kg, 25kg~起飞全重<150kg 的无人机。这类无人机通常 用于更重的商业和工业应用。 Ⅵ类无人机：116kg＜空机质量<5700kg 的无人机。这类无人机属于大型无人机，可能用于 货运、军事或其他专业用途。 Ⅻ类无人机：空机质量＞5700kg 的无人机。" },
  { id: 8, cat: "概述", q: "超低空无人机任务高度一般在（）之间。", opts: ["0-100m", "100-1000m", "0-50m"], ans: 0, exp: "题目考查的是无人机按飞行高度的分类。依据中国民航局《民用无人驾驶航空器运行管理规 定》：根据飞行高度的不同，无人机可以分为以下几类： 超低空无人机：任务高度 0-100m。 低空无人机：任务高度 100-1000m。 中空无人机：任务高度 1000-6000m。 高空无人机：任务高度 6000-18000m。 超高空无人机：任务高度大于 18000m。" },
  { id: 9, cat: "概述", q: "超近程无人机活动半径一般在（）以内。", opts: ["15km", "15-50km", "50-200km"], ans: 0, exp: "根据无人机活动半径的分类标准，无人机可以分为超近程、近程、短程、中程和远程 五个类别。其中，超近程无人机的活动半径通常在 15km 以内，近程无人机活动半径在 15~50km 之间，短程无人机活动半径在 50～200km 之间，中程无人机活动半径在 200～800km 之间，远程无人机活动半径大于 800km。" },
  { id: 10, cat: "概述", q: "多旋翼飞行器属于以下哪个概念的范畴？（）", opts: ["轻于空气的航空器", "直升机", "旋翼机"], ans: 2, exp: "多旋翼飞行器属于旋翼机的概念范畴。轻于空气的航空器主要是指依靠空气浮力升空的，比 如气球、飞艇等，多旋翼飞行器不是依靠浮力升空。直升机通常有较大的主旋翼和复杂的机 械传动结构等，多旋翼飞行器虽然和直升机有一些相似之处，比如都是依靠旋翼产生升力，但多旋翼飞行器的结构和工作原理与直升机有很大不同。而多旋翼飞行器具有多个旋翼，通 过调整不同旋翼的转速来实现飞行控制，与旋翼机概念更接近。" },
  { id: 11, cat: "概述", q: "多旋翼上有几片桨叶？（）", opts: ["2", "3", "桨叶数量不固定"], ans: 2, exp: "多旋翼上染叶数量不固定。多旋翼飞行器有不同的类型和规格，桨叶的数量可以有两 叶、三叶、四叶甚至更多。常见的有四旋翼（四个桨叶）、六旋翼（六个染叶）、八旋翼（八 个染叶）等。所以不能确定多旋翼上具体有几片桨，数量是不固定的。" },
  { id: 12, cat: "概述", q: "近程无人机活动半径在（）", opts: ["小于 15km", "15-50km", "200-800km"], ans: 1, exp: "根据无人机活动半径的分类标准，无人机可以分为超近程、近程、短程、中程和远程五个类 别。其中，超近程无人机的活动半径通常在 15km 以内，近程无人机活动半径在 15~50km 之间，短程无人机活动半径在 50～200km 之间，中程无人机活动半径在 200～800km 之间，远程无人机活动半径大于 800km。" },
  { id: 13, cat: "概述", q: "民用无人机的空机重量（）", opts: ["不包含载荷的无人机重量", "不包含载荷、电池和燃料的无人机重量", "不包含载荷、燃料的无人机重量"], ans: 2, exp: "民用无人机的空机重量是指无人机在没有任何 负载和燃料的情况下的重量，即只计算无人机本身的构造和组件的总重量。这一参数对无人 机的性能和能力有重要影响，因为它涉及到飞行稳定性、飞行时间、航程、载荷能力等多个 方面。" },
  { id: 14, cat: "概述", q: "轻型无人机是指（）", opts: ["空机质量大于等于 7 千克，但小于 116 千克的无人机，且全马力平飞中，校准空速小于 100 千米/小时（55 海里/小时），升限小于 3000 米", "空机质量大于 7 千克，但小于等于 116 千克的无人机，且全马力平飞中，校准空速大于 100 千米/小时（55 海里/小时），升限大于 3000 米", "空机质量大于 7 千克，但小于等于 116 千克的无人机，且全马力平飞中，校准空速小于 100 千米/小时（55 海里/小时），升限小于 3000 米"], ans: 2, exp: "根据国际民航组织（ICAO）的定义，轻型无人机通常指的是那些空机质量大于 7 千克但小于 等于 116 千克的无人机。这类无人机在全马力平飞中，校正空速小于 100 千米/小时（55 海 里/小时），升限小于 3000 米。这些参数使得轻型无人机适合于多种民用和商业应用，同时 由于其相对较小的尺寸和重量，也更容易受到监管。" },
  { id: 15, cat: "概述", q: "微型无人机是指（）", opts: ["空机重量小于等于 7 千克的无人机", "重量小于 7 千克的无人机", "重量小于等于 7 千克的无人机"], ans: 0, exp: "微型无人机是指空机重量小于等于 7 千克的无人机。根据民航法规，无人机按尺度可 分为微型、轻型、小型和大型等类别： 1、微型无人机：空机重量<7kg。 2、轻型无人机：空机重量在 7 至 116kg 之间，校正空速小于 100km/h，升限低于 3000m。 3、小型无人机：空机重量<5700kg（排除微型和轻型）。 4、大型无人机：空机重量>5700kg。 此外，按照任务高度分类，无人机还可分为超低空、低空、中空、高空和超高空五类。" },
  { id: 16, cat: "概述", q: "无人机飞艇属于（）无人机", opts: ["Ⅻ类", "Ⅺ类", "Ⅵ类"], ans: 2, exp: "无人飞艇属于Ⅵ类无人机。根据《轻小无人机运行规定（试行）》的分类，无人飞艇为Ⅵ类无人机。" },
  { id: 17, cat: "概述", q: "无人机的英文缩写是（）", opts: ["UVS", "UAS", "UAV"], ans: 2, exp: "无人机的英文缩写是 UAV，全称为 Unmanned Aerial Vehicle. “UVS”一般不是无人机的标准英文缩写； “UAS”是“Unmanned Aircraft System”，无人航空器系统，范围比单纯的无人机（UAv）要 大一些。在明确这几个常见缩写的具体含义后，就能准确判断出无人机的英文缩写是“UAV”。" },
  { id: 18, cat: "概述", q: "无人机系统的英文缩写是（）", opts: ["UVS", "UAS", "UAV"], ans: 1, exp: "无人机系统的英文缩写是 UAS，“Unmanned Aircraft System”" },
  { id: 19, cat: "概述", q: "无人机系统飞行器平台主要使用的是（）空气的动力驱动航空器。", opts: ["轻于", "重于", "等于"], ans: 1, exp: "无人机和有人驾驶飞机一样，主要使用的是重于空气的动力驱动的航空器。这是因为 重于空气的航空器是依靠空气动力克服自身重力来飞行的，而无人机系统的飞行器平台也遵 循这个原理。轻于空气的航空器主要是指飞艇等，其依靠浮力 飞行。等于空气一般情况下 没有这样的航空器分类。" },
  { id: 20, cat: "概述", q: "植保机的重量和飞行高度为（）", opts: ["150kg，30 米", "5700kg，20 米", "5700kg，15 米"], ans: 2, exp: "植保机的重量和飞行高度限制为：5700kg,15 米。 重量限制：植保机的最大起飞重量不得超过 5700kg，这一规定确保了操作安全，并避免对 其他空域用户造成干扰。 飞行高度限制：植保机的飞行高度需控制在 15 米以内。这是基于作业需求（如作物高度、环境因素）设定的，既保证了作业效果，又降低潜在风险。" },
  { id: 21, cat: "概述", q: "植保机属于（）无人机", opts: ["3 类", "5 类", "7 类"], ans: 1, exp: "植保无人机属于无人机的一种分类。根据《轻小无人机运行规定（试行）》中的分类，植保类无人机为Ⅴ类无人机。这类无人机专门用于农林植物保护作业，包括喷洒农药、种子、粉剂等。" },
  { id: 22, cat: "概述", q: "中程无人机活动半径为（）", opts: ["50-200km", "200-800km", ">800km"], ans: 1, exp: "中程无人机的活动半径是指无人机在一次飞行任务中能够覆盖的最大范围。根据无人 机的分类标准，中程无人机的活动半径被定义为 200 至 800 公里之间。这个范围使得中程无 人机能够在较远的距离执行任务，适用于需要较大覆盖面积的侦察、监视或其他任务。" },
  { id: 23, cat: "概述", q: "大型无人机是指（）", opts: ["空机重量≥5700kg 的无人机", "重量>5700kg 的无人机", "空机重量>5700kg 的无人机"], ans: 2, exp: "1、微型无人机：空机重量<7kg。 2、轻型无人机：空机重量在 7 至 116kg 之间，校正空速小于 100km/h，升限低于 3000m。 3、小型无人机：空机重量<5700kg（排除微型和轻型）。 4、大型无人机：空机重量>5700kg。 此外，按照任务高度分类，无人机还可分为超低空、低空、中空、高空和超高空五类。" },
  { id: 24, cat: "概述", q: "任务高度一般在 0-100m 之间的无人机为（）", opts: ["超低空无人机", "低空无人机", "中空无人机"], ans: 0, exp: "超低空无人机：飞行高度一般在 0~100 米之间。 低空无人机：飞行高度一般在 100~1000 米之间。 中空无人机：飞行高度一般在 1000~6000 米之间。" },
  { id: 25, cat: "概述", q: "远程无人机活动半径在（）以上", opts: ["800km", "50-200km", "200-800km"], ans: 0, exp: "根据《无人驾驶航空器飞行管理暂行条例》及相关行业标准，远程无人机的活动半径 定义为 800 公里以上，属于大型无人机的典型性能指标。这类无人机通常用于长距离巡检、物流配送或军事任务，需满足严格的适航审批和空域管理要求。" },
  { id: 26, cat: "概述", q: "短程无人机活动半径在（）", opts: ["15km", "15-50km", "50-200km"], ans: 2, exp: "根据无人机活动半径的分类标准，无人机可以分为超近程、近程、短程中程和远程五 个类别。其中，超近程无人机的活动半径通常在 15km 内，近程无人机活动半径在 15~50km 之间，短程无人机活动半径在 50～200km 之间，中程无人机活动半径在 200～800km 之间，远程无人机活动半径大于 800km。" },
  { id: 27, cat: "概述", q: "超高空无人机任务高度一般在（）之间", opts: ["0-100m", "6000-12000m", "大于 18000m"], ans: 2, exp: "超低空无人机：任务高度 0-100m。 低空无人机：任务高度 100-1000m。 中空无人机：任务高度 1000-6000m。 高空无人机：任务高度 6000-18000m。 超高空无人机：任务高度大于 18000m。" },
  { id: 28, cat: "概述", q: "低空无人机任务高度一般是（）", opts: ["0-100m", "100-1000m", "1000-6000m"], ans: 1, exp: "超低空无人机：任务高度 0-100m。 低空无人机：任务高度 100-1000m。 中空无人机：任务高度 1000-6000m。 高空无人机：任务高度 6000-18000m。 超高空无人机：任务高度大于 18000m。" },
  { id: 29, cat: "概述", q: "中空无人机高度一般在（）", opts: ["0-100m", "100-1000m", "1000-6000m"], ans: 2, exp: "超低空无人机：任务高度 0-100m。 低空无人机：任务高度 100-1000m。 中空无人机：任务高度 1000-6000m。 高空无人机：任务高度 6000-18000m。 超高空无人机：任务高度大于 18000m。" },
  { id: 30, cat: "概述", q: "高空无人机任务高度一般在（）", opts: ["0-100m", "100-1000m", "6000-18000m"], ans: 2, exp: "超低空无人机：任务高度 0-100m。 低空无人机：任务高度 100-1000m。 中空无人机：任务高度 1000-6000m。 高空无人机：任务高度 6000-18000m。 超高空无人机：任务高度大于 18000m。" },
  { id: 31, cat: "概述", q: "小型无人机，是指空机重量不超过（）kg 的无人机，微型和轻型无人机除外。", opts: ["150", "15", "4"], ans: 1, exp: "微型无人机：空机重量＜0.25kg 轻型无人机：空机重量<4kg，最大起飞重量 57kg 小型无人机：空机重量<15kg，最大起飞重量 325kg 中型无人机：最大起飞重量<150kg 大型无人机：最大起飞重量＞150kg 因此，小型无人机的空机重量上限是 15kg。" },
  { id: 32, cat: "概述", q: "轻型无人机，是指空机重量（）", opts: ["≤15kg，最大起飞重量≤15kg", "≤4kg，最大起飞重量≤7kg", "<0.25kg"], ans: 1, exp: "微型无人机：空机重量＜0.25kg 轻型无人机：空机重量≤4kg，最大起飞重量≤7kg 小型无人机：空机重量≤15kg，最大起飞重量=25kg 中型无人机：最大起飞重量≤150kg 大型无人机：最大起飞重量＞150kg" },
  { id: 33, cat: "概述", q: "关于固定翼垂直起飞错误的是（）", opts: ["飞机在起飞时，以垂直姿态安置在发生场上，由飞机尾支座支撑飞机，在机上发动机作用 下起飞", "机上配备垂直启用发动机，在该发动机推力作用下，飞机垂直起飞", "美国的格鲁门公司设计的 754 型无人机，它保留普通起落架装置，机尾有尾支座可采用起 落架滑跑方式起飞，也可以垂直姿态起飞"], ans: 2, exp: "格鲁门 754 型无人机是传统固定翼飞机，仅能通过滑跑起飞，不具备垂直起飞能力。 因此该选项是错误描述。 其他正确的选项分析如下： 1：固定翼飞机在垂直起飞时，确实是以垂直姿态安置在起飞场上，由尾支座支撑，并在发 动机推力作用下起飞。 2：部分固定翼飞机配备垂直起飞发动机，利用其推力实现垂直起飞。" },
  { id: 34, cat: "概述", q: "空气流过一组粗细不等的管子时，在管道变粗处，气流速度将（）", opts: ["增大", "减小", "不变"], ans: 1, exp: "根据流体力学中的连续性方程，空气流过管道时，流量保持不变。流量 Q 可以表示为： Q=A×v，其中：A 是管道的横截面积，v 是气流速度 当管道变粗时，横截面积增大。为了保持流量 Q 不变，气流速度 v 必须减小。" },
  // ==================== 系统组成 ====================
  { id: 35, cat: "系统组成", q: "（）传感器是飞行控制系统的基本传感器之一，用以改善系统的阻尼力矩。", opts: ["空速", "迎角、侧滑角", "角速率"], ans: 2, exp: "角速率传感器是飞行控制系统的基本传感器之一，用以改善系统的阻尼力矩。传感器 分为角速率传感器、姿态传感器、空速传感器以及位置传感器，其中角速率传感器用以改善 系统的阻尼特性。" },
  { id: 36, cat: "系统组成", q: "（）的功能是向无人机各用电气系统或设备提供满足预定设计要求的电能。", opts: ["供电系统", "配电系统", "电源"], ans: 0, exp: "无人机的供电系统是其运行的核心部分，它包括电源和配电系统，负责为无人机的所 有电气系统或设备提供所需的电能。这个系统确保无人机在飞行过程中，各个部件如电机、传感器、飞行控制器等都能获得稳定和符合设计要求的电力供应。" },
  { id: 37, cat: "系统组成", q: "（）功能通常包括指挥调度、任务规划、操作控制、显示记录等功能。", opts: ["数据链路分系统", "无人机地面站系统", "飞控与导航系统"], ans: 1, exp: "地面站系统的功能通常包括指挥调度、任务规划、操作控制、显示记录等。这些功能 确保了无人机任务的顺利执行和下行安全。 无人机地面站系统是无人机任务执行的关键组成部分，它作为整个无人机系统的作战指挥中 心，负责对无人机的飞行过程、飞行航迹、有效载荷的任务功能、通讯链路的正常工作以及 无人机的发射和回收进行全面控制。" },
  { id: 38, cat: "系统组成", q: "（）航空器平台结构通常包括机翼、机身、尾翼和起落架等。", opts: ["多旋翼", "单旋翼", "固定翼"], ans: 2, exp: "固定翼航空器是指那些通过固定在机身上的翅膀产生升力的航空器，其结构通常包括 机翼、机身、尾翼和起落架等关键部件。这些部件共同协作，使固定翼航空器能够在空中飞 行。" },
  { id: 39, cat: "系统组成", q: "（）两者组合统称为供电系统。", opts: ["电源和电缆", "电缆和配电", "电源和配电"], ans: 2, exp: "供电系统通常由电源和配电两部分组成。电源是指提供电能的设备，而配电则是指将 电源产生的电能分配到各个用电设备的系统。这两者共同确保了电力的供应和合理分配。" },
  { id: 40, cat: "系统组成", q: "（）频段可用于无人机系统下行链路，该无线电台工作时不得对其他合法无线电业务造 成影响，也不能寻求无线电干扰保护。", opts: ["840.5-845MHz", "2408-2440MHz", "1430-1446MHz"], ans: 1, exp: "《无人机系统频率使用事宜》的相关规定： 1、840.5-845MHz 可用于无人机系统的上行遥控链路，其中，841-845MHz 也可采用时分方式 用于无人机系统的上行遥控和下行遥测信息传输链路。 2、1430-1446MHz 频段可用于无人机系统下行遥测与信息传输链路，其中 1430-1434MHIz 频 段应优先保证警用无人机和直升机视频传输使用，必要时 1434-1442MHLz 也可以用于警用直 升机视频传输。无人机在市区部署时，应使用 1442MHz 以下频段。 3、2408-2440MHz 频段可用于无人机系统下行链路，该无线电台工作时不得对其他合法无线 电业务造成影响，也不能寻求无线电干扰保护。" },
  { id: 41, cat: "系统组成", q: "（）是无人机完成起飞、空中飞行、执行任务、返场回收等整个飞行过程的核心系统，对无人机实现全权控制与管理，因此该子系统之于无人机相当于驾驶员之于有人机，是无人 机执行任务的关键。", opts: ["飞控计算机", "导航子系统", "飞控子系统"], ans: 2, exp: "飞控子系统是无人机完成起飞、空中飞行、执行任务、返场回收等整个飞行过程的核 心系统。它通过整合各种传感器（如姿态传感器、高度传感器等）的数据，经过飞控计算机 的计算处理，生成控制指令发送给执行机构（如电机、舵机等），对无人机实现全权控制与 管理。" },
  { id: 42, cat: "系统组成", q: "（）是由控制站上的操纵杆直接控制无人机的舵面，遥控无人机的飞行。", opts: ["舵面遥控", "姿态遥控", "指令控制"], ans: 0, exp: "舵面遥控是一种无人机操控方式，其中无人机的飞行控制是通过操纵杆直接控制无人 机的舵面来实现的。这种控制方式允许操纵者通过改变舵面的角度来控制无人机的飞行方向 和姿态，实现对无人机的精确操控。舵面遥控通常用于无人机的起飞、着陆以及飞行过程中 的机动控制。" },
  { id: 43, cat: "系统组成", q: "（）与无人机控制站的功能类似，但只能控制无人机的机载任务设备，不能进行无人机的 飞行控制。", opts: ["指挥处理中心", "无人机控制站", "载荷控制站"], ans: 2, exp: "载荷控制站是无人机地面站系统的一部分，其主要功能是控制无人机所携带的任务载 荷设备。与无人机控制站相比，载荷控制站缺少对无人机飞行平台的直接控制能力，即不能 进行飞行操纵，只能对机载任务设备进行控制。这种分工有助于提高无人机操作的专业性，确保飞行安全和任务执行的效率。" },
  { id: 44, cat: "系统组成", q: "（）主要是由飞行操纵、任务载荷控制、数据链路控制和通信指挥等组成，可完成对无 人机机载任务载荷等的操纵控制。", opts: ["指挥处理中心", "无人机控制站", "载荷控制站"], ans: 1, exp: "无人机控制站主要是由飞行操纵、任务载荷控制、数据链路控制和通信指挥等组成。 无人机控制站可以对无人机的飞行进行操控，包括起飞、降落、航线规划等飞行操纵；同时 可以控制无人机搭载的任务载荷，如相机、传感器等；还能通过数据链路与无人机进行通信，接收和发送各种指令和数据；并且起到通信指挥的作用，协调无人机与其他设备或人员的配 合。" },
  { id: 45, cat: "系统组成", q: "（）主要是制定无人机飞行任务、完成无人机载荷数据的处理和应用，指挥中心/数据 处理中心一般都是通过无人机控制站等间接地实现对无人机的控制和数据接收。", opts: ["无人机控制站", "指挥处理中心", "载荷控制站"], ans: 1, exp: "指挥处理中心主要是制定无人机飞行任务、完成无人机载荷数据的处理和应用。指挥 中心数据处理中心一般都是通过无人机控制站等间接地实现对无人机的控制和数据接收。" },
  { id: 46, cat: "系统组成", q: "不属于抵消旋翼机反转力矩的方法有（）", opts: ["尾桨", "共轴旋翼", "增大旋翼半径"], ans: 2, exp: "旋翼机运行时，主旋翼转动产生升力同时伴生反转力矩，若不抵消会致机身失衡失控。 增大旋翼半径只是改变旋翼尺寸规格，影响的多是升力大小、能耗等，和反转力矩抵消机制 毫无关联，如同给车轮加大尺寸，改变的是行驶性能而非刹车平衡原理，所以它不属于抵消 反转力矩之法" },
  { id: 47, cat: "系统组成", q: "不属于无人机的是（）", opts: ["塞纳斯", "侦察兵", "捕食者"], ans: 0, exp: "无人机（Unmanned Aerial Vehicle, UAV）是指不需要驾驶员在机舱内操作的飞机，可以远程控制或自主飞行。塞纳斯（Cessna）是一种通用航空飞机品牌，主要生产小型飞 机，并不特指无人机，因此不属于无人机。而“侦察兵”和“捕食者”都是知名的无人机型 号，分别用于侦察和打击任务。" },
  { id: 48, cat: "系统组成", q: "不属于无人机回收方式的是（）", opts: ["伞降", "横滚", "气囊回收"], ans: 1, exp: "本题考查的是无人机的回收方式。无人机的回收方式包括伞降、气囊回收、滑跑着陆、拦阻网回收等。其中，伞降是一种通过降落伞减速降落的方式，气囊回收则是利用气囊吸收 着陆冲击力来实现软着陆的方式。而横滚并不是无人机回收的一种方式，因此不属于无人机 回收方式。" },
  { id: 49, cat: "系统组成", q: "不属于无人机起飞方式的是（）", opts: ["弹射", "滑跑", "滑翔"], ans: 2, exp: "滑翔通常指的是飞行器（如滑翔机、滑翔伞等）利用空气动力在空中无动力飞行的状 态，而不是无人机的起飞方式。" },
  { id: 50, cat: "系统组成", q: "不属于无人机系统的是（）", opts: ["飞行器平台", "飞行员", "导航飞控系统"], ans: 1, exp: "本题考查的是无人机系统的基本组成部分。无人机系统通常包括飞行器平台、导航飞 控系统、通信链路、任务载荷（如相机、传感器等）以及地面控制站等。其中，飞行器平台 是指无人机的主体结构，导航飞控系统负责无人机的飞行控制和导航。而飞行员是有人驾驶 飞机的操作人员，无人机不需要飞行员进行操作，因此不属于无人机系统的组成部分。" },
  { id: 51, cat: "系统组成", q: "不属于无人机飞控计算机任务范畴的是（）", opts: ["数据中继", "姿态稳定与控制", "自主飞行控制"], ans: 0, exp: "无人机飞控计算机系统主要负责无人机的飞行控制和任务管理，包括无人机姿态稳定 与控制、自主飞行控制等功能。而数据中继通常是指无人机与地面控制站之间或者无人机与 其他设备之间的数据传输，这并不是飞控计算机的直接任务范畴。" },
  { id: 52, cat: "系统组成", q: "从应用上说，涡桨发动机适用于（）", opts: ["中高空长航时无人机", "高空长航时无人机/无人战斗机", "中低空、低速短距/垂直起降固定翼"], ans: 0, exp: "涡桨发动机适用于特定的飞行环境和任务需求。涡桨发动机结合了螺旋桨和涡轮喷气 发动机的优点，适合于中高空长航时的飞行任务，因为它们在这些高度和速度下可以提供良 好的推力。" },
  { id: 53, cat: "系统组成", q: "大型无人机计算装载重量和重心的方法主要有：计算法、图表法和（）", opts: ["试凑法", "查表法", "约去法"], ans: 1, exp: "本题考查的是大型无人机计算装载重量和重心的方法。大型无人机计算装载重量和重 心的方法主要有计算法、图表法和查表法。这三种方法可以根据不同的情况和需求来进行选 择和应用，以确保无人机的装载重量和重心位置的准确性。" },
  { id: 54, cat: "系统组成", q: "导航子系统功能是向无人机提供（）信息，引导无人机沿指定航线安 全、准时、准确地飞行。", opts: ["角速度", "角加速度", "高度、速度、位置"], ans: 2, exp: "导航子系统的主要任务是向无人机提供高度、速度和位置等关键信息，以确保无人机 能够沿指定航线安全、准时、准确地飞行。这些信息对于无人机的飞行控制和路径规划至关 重要。" },
  { id: 55, cat: "系统组成", q: "地面控制站飞行参数综合显示的内容包括（）", opts: ["飞行与导航信息、数据链状态信息、设备状态信息、指令信息", "导航信息显示、航迹绘制显示以及地理信息的显示", "告警信息、地图航迹显示信息"], ans: 0, exp: "地面控制站是无人机系统中的重要组成部分，负责监控和控制无人机的飞行。飞行参 数综合显示的内容应该全面反映无人机的实时状态和操作需求，包括飞行与导航信息、数据 链状态信息、设备状态信息和指令信息。这些信息对于操作人员来说至关重要，有助于他们 做出正确的决策和操作。" },
  { id: 56, cat: "系统组成", q: "地面站地图航迹显示系统可为无人机驾驶员提供飞行器（）等信息。", opts: ["位置", "飞行姿态", "飞控姿态"], ans: 0, exp: "地面站地图航迹显示系统主要是通过在地图上显示无人机的位置变化轨迹来为无人机 驾驶员提供飞行器的位置信息。飞行姿态和飞控姿态通常是通过其他专门的仪表或显示界面 来展示，而不是在地图航迹显示系统中呈现。" },
  { id: 57, cat: "系统组成", q: "电动动力系统主要由动力电机、动力电源和（）组成。", opts: ["调速系统", "电池", "无刷电机"], ans: 0, exp: "电动动力系统主要由动力电机、动力电源和调速系统组成。调速系统负责控制电机的 转速和功率输出，以适应不同的飞行条件和要求。" },
  { id: 58, cat: "系统组成", q: "对于在大风天伞降回收的无人机，以下说法错误的是（）", opts: ["尽量在高高度开伞", "尽量在上风区开伞", "尽量在有技术条件的情况下，接地后切断主伞连接"], ans: 0, exp: "本题考核的是对大风天伞降回收无人机的操作理解和判断。在大风天进行伞降回收无 人机时，需要考虑的因素包括开伞的高度、开伞的位置以及降落后的操作。 尽量在高高度开伞——这是错误的。在大风天气中，高高度开伞会增加无人机被风吹离预定降落 区域的风险，因为高空的风力通常更强。" },
  { id: 59, cat: "系统组成", q: "多旋翼飞行器的飞控指的是（）", opts: ["机载任务系统", "机载遥控接收机", "机载导航飞控系统"], ans: 2, exp: "飞控系统（Flight Control System, FCs）是控制多旋翼飞行器飞行的大脑，它包括传感 器、控制算法和执行机构，负责维持飞行器的稳定飞行和执行飞行任务。是其核心组成部分，负责控制飞行器的飞行状态和轨迹。" },
  { id: 60, cat: "系统组成", q: "二冲程活塞汽油发动机应使用何种润滑油？（）", opts: ["4T 机油", "2T 机油", "汽车机油"], ans: 1, exp: "二冲程活塞汽油发动机应使用 2T 机油。这是因为 2T 机油是二冲程发动机专用机油，对机油的低温流动性和冷启动性要求不高，主要用于二冲程摩托车、割草机、切割机、电锯 等农具设备上。而 4T 机油是四冲程发动机专用机油，在润滑、散热、清洁等性能方面比较 优越，主要应用于二冲程摩托车、高档大排摩托车上。" },
  { id: 61, cat: "系统组成", q: "二冲程汽油发动机中，燃料箱加注的是（）", opts: ["润滑油", "汽油", "汽油与润滑油的混合物"], ans: 2, exp: "二冲程汽油发动机中，燃料箱加注的是汽油与润滑油的混合物。这是因为二冲程发动 机的润滑方式与四冲程发动机不同，润滑油需要与汽油混合后一起进入发动机燃烧室，以实 现润滑和冷却功能。" },
  { id: 62, cat: "系统组成", q: "飞控子系统必须具备的功能为（）", opts: ["无人机姿态稳定与控制，无人机飞行管理，应急控制", "无人机飞行管理，与导航子系统协调完成航迹控制，信息收集与传递", "无人机起飞与着陆控制，无人机飞行管理，信息收集与传递"], ans: 0, exp: "飞控子系统最主要的功能之一就是保证无人机姿态的稳定与控制，让无人机在飞行过 程中保持平稳的姿态，不会出现剧烈晃动或失控的情况。同时，飞控子系统要对无人机的飞 行进行管理，包括飞行高度、速度、航线等方面的控制。此外，在出现紧急情况时，飞控子 系统还需要具备应急控制能力，以确保无人机的安全。" },
  { id: 63, cat: "系统组成", q: "飞控子系统可以不具备如下功能（）", opts: ["任务分配与航迹规划", "导航与制导控制", "姿态稳定与控制"], ans: 0, exp: "这道题目考察的是飞控子系统的功能组成。飞控子系统主要负责无人机的姿态稳定与 控制、导航与制导控制等，以确保无人机能够按照预定的航线安全飞行。任务分配与航迹规 划虽然对于无人机的飞行至关重要，但它们通常是由地面控制站或指挥处理中心来完成的，而不是飞控子系统直接执行的功能。" },
  { id: 64, cat: "系统组成", q: "飞行控制是指采用（）在空中整个飞行过程的控制。", opts: ["遥感方式", "遥测方式", "遥控方式"], ans: 2, exp: "飞行控制主要是通过遥控方式对无人机在空中整个飞行过程进行控制。遥控是指从远 距离对无人机进行操作和控制，包括起飞、飞行、降落等各个阶段。 而遥感主要是获取目标的信息，遥测主要是对无人机的状态参数等进行测量，但这两者通常 不是直接对无人机飞行过程进行控制。" },
  { id: 65, cat: "系统组成", q: "固定翼无人机配平主要考虑的是（）沿纵轴的前后位置。", opts: ["气动焦点", "发动机", "重心"], ans: 2, exp: "固定翼无人机配平主要考虑的是重心沿纵轴的前后位置。重心位置对飞机的稳定性 和操纵性有重要影响，通过调整重心位置可以使飞机在飞行中保持平衡。 而气动焦点是飞机空气动力作用点，发动机主要提供动力，它们不是配平主要考虑的对象是 重心沿纵轴的前后位置。" },
  { id: 66, cat: "系统组成", q: "固定翼无人机在姿态遥控状态下，如出现动力失效则正确的处理方法是（）", opts: ["保持略大于平飞速度的速度建立下滑航线飞回本场或迫降无人区", "势能转换动能，低头俯冲", "仅剩的动能转换势能，保持上仰姿态与安全高度"], ans: 0, exp: "固定翼无人机在姿态遥控状态下，如果出现动力失效，正确的处理方法应该是保持飞 机的滑翔状态，并尝试安全返回或迫降。这是因为固定翼无人机依赖于发动机提供动力来维 持飞行，一旦动力失效，飞机将失去推力，但仍然可以利用其机翼的升力进行滑翔。" },
  { id: 67, cat: "系统组成", q: "活塞发动机的爆震最易发生在（）", opts: ["发动机处于高功率状态下工作时", "发动机处于小转速和大进气压力状态工作", "发动机处于大转速和小进气压力"], ans: 1, exp: "爆震易在小转速、大进气压力时。活塞发动机的爆震是一种不正常的工作状态，通常 由于混合气在非正常点火的情况下造成的突发非长时间持续的震动。发动机处于小转速和大 进气压力状态工作时，由于进气压力增大，混合气体被压缩得更厉害，温度和压力上升，增 加了自燃的风险。" },
  { id: 68, cat: "系统组成", q: "活塞发动机混合气过富油燃烧将引起（）的问题。", opts: ["发动机工作平稳，但燃油消耗量变大", "电嘴积炭", "发动机过热"], ans: 1, exp: "活塞发动机混合气过富油燃烧将引起电嘴积炭的问题。这是因为过富油燃烧会导致燃 烧不完全，产生大量的碳残留物，其中电喷雾嘴（电嘴）是喷油系统的一部分，如果碳残留 物堆积在电嘴上，会影响喷油的正常工作，可能导致喷油不均匀甚至堵塞，影响发动机的燃 烧效率和工作稳定性。" },
  { id: 69, cat: "系统组成", q: "活塞发动机系统常采用的增压技术主要是用来（）", opts: ["提高功率", "减少废气量", "增加转速"], ans: 0, exp: "增压技术，尤其是涡轮增压和机械增压，主要用于提高发动机的进气量，从而增加发 动机的功率输出。通过增压，发动机可以在相同的排量下产生更多的动力，提高效率和性能。" },
  { id: 70, cat: "系统组成", q: "活塞式发动机中，CDI 系统属于（）的一部分。", opts: ["进气系统", "排气系统", "点火系统"], ans: 2, exp: "CDI 系统，即电容放电式点火系统（Capacitor Discharge Ignition），是电子点火系 统的一种，广泛应用于摩托车、电锯、涡轮动力飞行器和一些汽车上。CDI 系统的主要功能 是产生高压电，触发火花塞点火，以实现发动机的点火。因此，CDI 系统属于点火系统的一 部分。" },
  { id: 71, cat: "系统组成", q: "民用无人机上的舵机一般输出行程为（）", opts: ["正负 60°", "正负 20°", "正负 120°"], ans: 1, exp: "在民用无人机领域，舵机的偏转角度行程通常设计为正负 20°范围，这一参数能够 覆盖升降舵、副翼和方向舵等控制面的常规操作需求。 这种设计考量主要基于以下因素：首先，正负 20°的行程已能满足绝大多数飞行控制场景； 其次，过大的偏转角度不仅会增加系统能耗，还可能影响飞行稳定性。因此，在民用无人机 舵机选型时，适度的行程范围设计更符合实际。" },
  { id: 72, cat: "系统组成", q: "目前民用无人机上多用的舵机属于哪种伺服执行机构类型？（）", opts: ["电动伺服执行机构", "电液伺服执行机构", "气动伺服执行机构"], ans: 0, exp: "目前民用无人机上多用的舵机属于电动伺服执行机构。电动伺服执行机构具有控制精 度高、响应速度快、体积小、重量轻、可靠性高、成本低等优点，非常适合在民用无人机上 使用。" },
  { id: 73, cat: "系统组成", q: "目前世界上无人机的频谱使用主要集中在 UHF、L 和（）波段。", opts: ["任意", "C", "VHF"], ans: 1, exp: "目前世界上无人机的频谱使用主要集中在 UHF（超高频）、L（低频）和 C（高频）波段。UHF 波段具有一定的穿透性和较远的传输距离；L 波段适用于某些特定的应用场景；C 波段也被广泛应用于无人机通信和控制等方面。" },
  { id: 74, cat: "系统组成", q: "目前主流的民用无人机所采用的动力系统通常为活塞式发动机和（）两种。", opts: ["涡扇发动机", "电动机", "火箭发动机"], ans: 1, exp: "这道题目考察的是民用无人机常用的动力系统类型。目前，民用无人机主要采用的动 力系统有两种：活塞式发动机和电动机。活塞式发动机因其结构简单、成本较低而被广泛应 用，而电动机则因其运行安静、维护简单、易于控制等优点，在小型和中型无人机中得到了 广泛的应用。" },
  { id: 75, cat: "系统组成", q: "哪种对地拍摄或成像的无人机任务设备基本不会受到云层与雾霾的影响？（）", opts: ["合成孔径雷达", "可见光 CCD", "红外摄像机"], ans: 0, exp: "合成孔径雷达（SAR）是一种主动式的对地观测系统，它利用合成孔径原理、脉冲压缩 技术和信号处理技术，获得方位向的高分辨率。 SAR 的工作波长较长，因此不易受云雾和光照条件的影响，具有全天时、全天候的工作能力。 因此，对于对地拍摄或成像的无人机任务设备来说，合成孔径雷达（SAR）基本不会受到云层 与雾霾的影响。" },
  { id: 76, cat: "系统组成", q: "农用无人机按机型结构通常分为（）、单旋翼无人机、多旋翼无人机。", opts: ["电动无人机", "油动无人机", "固定翼无人机"], ans: 2, exp: "农用无人机按机型结构分类，主要考虑的是无人机的飞行方式和结构特点。固定翼无 人机、单旋翼无人机和多旋翼无人机是三种常见的结构类型。" },
  { id: 77, cat: "系统组成", q: "气垫着陆，（）。", opts: ["气垫着陆的最大缺点是，不能在未经平整的地面，泥地，冰雪或水上着陆", "优点是不受无人机大小，重量限制，且回收效率高", "空中回收则是 1 分钟 1 架次"], ans: 1, exp: "气垫着陆是一种无人机回收方式。其具有独特的优势，不受无人机大小和重量的限制，意味着各种不同规格的无人机都可以采用这种方式进行回收。同时，回收效率高可以减少回 收过程中所耗费的时间和资源，提高无人机的使用效率。" },
  { id: 78, cat: "系统组成", q: "气化器式活塞发动机在何时容易出现气化器回火现象？（）", opts: ["热发动机起动时", "油门收的过猛", "寒冷天气第一次起动时"], ans: 2, exp: "在寒冷天气第一次起动时，气化器式活塞发动机容易出现气化器回火现象。这是因为 在寒冷天气下，燃油的挥发性变差，混合气浓度可能会出现问题。第一次启动时，发动机温 度低，燃油雾化效果不好，容易导致混合气过稀或不均匀，从而可能引 1 发气化器回火。" },
  { id: 79, cat: "系统组成", q: "如果无人机数据链路上行中断，会发生的后果（）", opts: ["无人机退出地面站控制模式", "不能获取无人机状态信息", "无法在线重规划航线航点及发送、任务指令"], ans: 2, exp: "无人机数据链是无人机与地面控制站之间进行指令交互、信息传递的无线通信链路，对无人机的控制和状态信息的获取至关重要。当无人机数据链路上行中断时，会直接影响到 地面控制站对无人机的控制能力，包括无法发送遥控指令、无法在线重规划航线航点及发送 任务指令。" },
  { id: 80, cat: "系统组成", q: "属于无人机飞控子系统功能的是（）", opts: ["导航控制", "任务信息收集与传递", "无人机姿态稳定与控制"], ans: 2, exp: "无人机姿态稳定与控制是飞控子系统的核心功能，主要负责无人机的飞行控制和稳定 性，通过传感器数据的采集和处理，对无人机的姿态进行调整和控制。" },
  { id: 81, cat: "系统组成", q: "不属于无人机飞控子系统所需要信息的是（）", opts: ["空速", "经/纬度", "姿态角"], ans: 1, exp: "飞控子系统主要负责无人机的飞行控制，包括无人机的速度（空速）、姿态（姿态角）等信息，以确保无人机能够稳定飞行并执行预定动作。而经/纬度信息虽然对于无人机的导 航很重要，但它们通常是由导航子系统提供，而不是直接由飞控子系统所需的信息。" },
  { id: 82, cat: "系统组成", q: "四冲程汽油发动机中，燃料箱加注的是（）", opts: ["汽油", "汽油与润滑油的混合物", "润滑油"], ans: 0, exp: "在四冲程汽油发动机中，燃料箱主要加注的是汽油，用于提供发动机燃烧所需的燃料。 润滑油有专门的润滑系统进行添加和循环，不是加注在燃料箱中。而汽油与润滑油的混合物 一般不是正常情况下加注在燃料箱里的。" },
  { id: 83, cat: "系统组成", q: "位置传感器用于感受无人机的位置，是飞行国际控制的必要前提，（）是典型的位置传 感器。", opts: ["角速率传感器", "加速度传感器", "GPS 卫星导航接收机"], ans: 2, exp: "GPS 卫星导航接收机能够接收卫星信号，确定无人机的位置信息，是典型的位置传感 器。角速率传感器主要用于测量无人机的角速度，不是直接感受位置。加速度传感器主要测 量加速度，不能直接确定位置。" },
  { id: 84, cat: "系统组成", q: "无人机搭载任务设备重量主要受限制于（）", opts: ["最大起飞重量", "空重", "载重能力"], ans: 2, exp: "无人机搭载任务设备重量主要受限制于载重能力。载重能力是无人机能够承载的额外 重量的限度，任务设备的重量不能超过无人机的载重能力，否则无人机将无法正常起飞或飞 行。" },
  { id: 85, cat: "系统组成", q: "无人机地面站系统不包括（）", opts: ["载荷控制站", "无人机控制站", "机载电台"], ans: 2, exp: "机载电台是安装在无人机上的通信设备，用于无人机与地面站之间的数据传输，因此 它不属于地面站系统的组成部分。无人机地面站系统通常包括无人机控制站和载荷控制站。 无人机控制站主要用于对无人机的飞行进行控制和监控，包括航线规划、飞行参数设置、实 时飞行状态显示等。载荷控制站主要用于对无人机搭载的任务设备进行控制和操作。" },
  { id: 86, cat: "系统组成", q: "无人机地面站显示系统应能显示（）信息。", opts: ["飞行器状态及链路、载荷状态", "飞行空域信息", "无人机飞行员状态"], ans: 0, exp: "无人机地面站显示系统主要是为了让操作人员能够实时了解无人机的各种状态，以便 进行有效的操控和管理。飞行器状态及链路、载荷状态对于无人机的操作至关重要。飞行器 状态包括飞行高度、速度、姿态、位置等信息，链路状态可以反映通信是否正常，载荷状态 则能让操作人员知道搭载的设备工作情况如何。" },
  { id: 87, cat: "系统组成", q: "无人机的发动机采用重力供油系统但装有增压泵，主要为了（）。", opts: ["保证爬升、下降及其他特殊情况下的正常供油", "保证大速度巡航的用油", "减少油箱的剩余燃油"], ans: 0, exp: "无人机的发动机采用重力供油系统时，在一些特殊情况下，比如爬升、下降过程中，由于飞机姿态的变化等原因，单纯依靠重力供油可能会出现供油不稳定或不足的情况。而装 上增压泵后，可以在这些特殊情况下确保有足够的压力来保证正常供油。" },
  { id: 88, cat: "系统组成", q: "无人机电气系统一般包括（）3 个部分。", opts: ["电源、电缆、接插件", "电源、配电系统、用电设备", "电缆、供电系统、用电设备"], ans: 1, exp: "无人机电气系统就如同一个小型的电力供应和使用体系。电源是整个电气系统的能量 来源，就像一个发电站，为无人机提供电力。配电系统则负责将电源产生的电能合理地分配 到各个用电设备上，它就像是一个电力调度中心，确保各个设备都能得到合适的电量供应。 用电设备包括电机、传感器、控制系统等各种需要电力才能正常工作的部件，它们是无人机 实现各种功能的具体执行者。" },
  { id: 89, cat: "系统组成", q: "无人机电气系统中电源和（）者组合统称为供电系统。", opts: ["配电系统", "供电线路", "用电设备"], ans: 0, exp: "电源加配电，组成供电系统。无人机电气系统一般包括电源、配电系统、用电设备三 个部分，电源和配电系统两者的组合统称为供电系统。供电系统的功能是向无人机各用电系 统或设备提供满足预定设计要求的电能。" },
  { id: 90, cat: "系统组成", q: "无人机驾驶航空器系统必要的组成部分是（）", opts: ["飞行器平台、控制站", "飞行器平台、控制站、通讯链路", "飞行器平台、通讯链路"], ans: 1, exp: "无人机驾驶航空器系统由飞行器平台、控制站和通讯链路三个必要部分组成。飞行器 平台是执行飞行任务的主体；控制站用于对无人机进行操控和监控；通讯链路则保证飞行器 平台与控制站之间能够进行信息的传递和交互。" },
  { id: 91, cat: "系统组成", q: "无人机配平的主要考虑是（）纵轴的前后位置。", opts: ["发动机", "气动焦点", "重心"], ans: 2, exp: "无人机配平是指调整无人机的重心位置，以确保无人机在飞行中保持平衡和稳定性。 配平的主要考虑是无人机的重心沿纵轴的前后位置，这直接影响到无人机的飞行性能和操控 性。" },
  { id: 92, cat: "系统组成", q: "无人机燃油箱通气目的之一是（）", opts: ["通气增大供油流量", "保证向发动机正常供油", "通气减小供油流量"], ans: 1, exp: "无人机燃油箱通气的目的之一是保证向发动机正常供油。如果燃油箱不通气，随着燃 油的消耗，油箱内会形成负压，影响燃油的正常流动，导致供油不畅甚至无法供油。通气不 是为了增大或减小供油流量。" },
  { id: 93, cat: "系统组成", q: "无人机数据链路下行中断会（）", opts: ["无人机退出地面站控制模式", "不能获取无人机状态信息", "无法在线重新规划航线航点及发送任务指令"], ans: 1, exp: "无人机数据链路下行中断意味着从无人机到地面站的信息传输被阻断。下行链路的主 要功能是传递无人机的状态信息和传感器数据到地面站。如果下行链路中断，地面站将无法 接收到无人机的状态信息，包括空速、发动机转速、载荷状态等关键数据。" },
  { id: 94, cat: "系统组成", q: "无人机通过（）控制舵面和发动机节风门来实现无人机控制。", opts: ["伺服执行机构控制舵面和发动", "操纵杆", "脚蹬"], ans: 0, exp: "伺服执行机构，也称舵机，是飞控系统的执行部件。其作用在于接收飞行控制指令，进行功率放大，并驱动舵面或发动机节风门偏转，从而达到控制无人机姿态和轨迹的目的。 因此，无人机通过伺服执行机构控制舵面和发动机节 风门来实现无人机控制。" },
  { id: 95, cat: "系统组成", q: "无人机系统通讯链路主要包括：指挥与控制（C&C），（），感知和规避（S&A）。", opts: ["无线电侦察", "空中交通管制（ATC）", "电子干扰"], ans: 1, exp: "无人机系统通讯链路是无人机与地面控制站之间进行数据交换的重要部分，它包括指 挥与控制（C&C）、空中交通管制（ATC）以及感知和规避（S&A）。空中交通管制（ATC）是 确保无人机在空域中安全飞行的关键环节，它负责协调无人机与其他飞行器的飞行路径，以 免冲突。" },
  { id: 96, cat: "系统组成", q: "无人机相对有人机的优势，以下哪个条件不正确？（）", opts: ["无需生命支持系统", "训练可多依赖于模拟器", "可靠性指标高"], ans: 2, exp: "无人机相对于有人机的优势主要体现在以下几个方面： 无需生命支持系统-这是正确的。无人机不需要为飞行员提供生命支持系统，如氧气供应、温度控制等，这可以减轻无人机的载荷和设计复杂性；训练可多依赖于模拟器-这也是正确 的。无人机的操作训练可以在模拟器上进行；可靠性指标高-这不正确。有人机比无人机更 具优势是因为有飞行员的判断和处理能力。" },
  { id: 97, cat: "系统组成", q: "无人机在增稳飞行控制模式下，飞控子系统（）控制。", opts: ["不参与", "不确定", "参与"], ans: 2, exp: "增稳模式飞控参。无人机在增稳飞行控制模式下，飞控子系统是参与控制的。增稳模 式（Stabilize 模式）下，飞控系统会根据遥控器的输入来控制无人机的倾斜角度和转向速 率，同时在松开遥控器摇杆时，无人机将自动保持水平姿态。这表明飞控子系统在增稳模式 下是积极参与工作的，以确保无人机的稳定飞行。" },
  { id: 98, cat: "系统组成", q: "无线电视距内通讯的无人机多数机载安装（），需要进行无线电超视距通讯的无人机一 般采用自跟踪抛物面卫星天线。", opts: ["定向天线", "蘑菇头天线", "全向天线"], ans: 2, exp: "无线电视距内通讯的无人机多数机载安装的是全向天线，因为全向天线能够在水平方 向上均匀辐射或接收电磁波，适用于无人机与地面站之间的全方位通信。" },
  { id: 99, cat: "系统组成", q: "下列哪项是飞行控制的方式之一？（）", opts: ["指令控制", "陀螺控制", "载荷控制"], ans: 0, exp: "飞行：控制指令控制。飞行控制的方式主要有指令控制，通过地面站或其他控制设备 向无人机发送指令来控制其飞行。陀螺控制一般是用于测量和稳定飞行器姿态等方面，不是 主要的飞行控制方式。载荷控制主要是对无人机所搭载的任务载荷进行控制，而非对飞行进 行控制。" },
  { id: 100, cat: "系统组成", q: "下述哪类民用无人机动力系统的运转不需要大气中的氧气？（）", opts: ["涡轮喷气发动机", "外转子无刷电动机", "二冲程活塞式汽油机"], ans: 1, exp: "外转子无刷电动机，作为一种电力驱动系统，其运转不需要氧气，因为它们通过电能 转换为机械能来工作。" },
  { id: 101, cat: "系统组成", q: "以下不是导航飞控系统组成部分的是（）", opts: ["电台", "执行机构", "传感器"], ans: 0, exp: "导航飞控系统通常包括传感器、执行机构和控制单元等部分。传感器用于收集无人机 的状态信息，执行机构则根据控制指令进行相应的操作以调整无人机的姿态和轨迹，而控制 单元负责处理传感器数据并生成控制指令。电台是用于通信的设备，虽然在无人机系统中很 重要，但它不是导航飞控系统的直接组成部分。" },
  { id: 102, cat: "系统组成", q: "以下不属于航空器的是（）", opts: ["卫星", "直升机", "飞艇"], ans: 0, exp: "航空器是指在大气层中飞行的飞行器，直升机和飞艇都是在大气层中依靠空气动力飞 行的，属于航空器。而卫星是在太空轨道运行，主要依靠万有引力等天体力学规律运行，不 属于在大气层中飞行的航空器。" },
  { id: 103, cat: "系统组成", q: "以下地面链路天线哪一种是定向天线？（）", opts: ["八木天线", "鞭状天线", "三叶草天线"], ans: 0, exp: "八木天线是一种定向天线，它通过使用反射器和指向器元件来形成辐射方向图，主要 将其聚焦在指向器的方向上，从而实现定向性" },
  { id: 104, cat: "系统组成", q: "在下列参数中，影响涡桨发动机工作寿命的主要是（）", opts: ["发动机的排气温度", "发动机滑油温度", "发动机转速"], ans: 0, exp: "影响涡桨发动机工作寿命的主要参数是发动机的排气温度。排气温度是衡量发动机热 负荷的重要指标，高温排气对发动机的材料和结构造成热应力，长期运行在高温状态下会加 速材料的老化和损伤，从而影响发动机的使用寿命。" },
  { id: 105, cat: "系统组成", q: "指挥控制与（）是无人机地面站的主要功能。", opts: ["任务规划", "导航", "飞行视角显示"], ans: 0, exp: "无人机地面站的主要功能包括指挥控制和任务规划。指挥控制涉及到对无人机的实时 操控和监控，而任务规划则是在飞行前对无人机的飞行路径、任务载荷操作等进行预先设置 和安排。" },
  { id: 106, cat: "系统组成", q: "视距内无人机通讯链路采用哪种天线？（）", opts: ["定向天线", "全向天线或鞭状天线", "卫星天线"], ans: 1, exp: "视距内（VLOS，VisualLineofSight）无人机通讯链路通常采用全向天线或鞭状天 线。这些天线能够向各个方向均匀辐射和接收信号，适用于短距离通信。 而定向天线通常用于视距外（BVLOS，BeyondVisualLineofSight）通信，因为它们能够将信 号集中在特定方向上，提高信号强度和传输距离。卫星天线则用于超视距通信，通过卫星中 继实现更长距离的通信。" },
  { id: 107, cat: "系统组成", q: "视距外无人机通讯链路采用哪种天线？（）", opts: ["抛物面卫星通讯天线", "定向天线", "全向天线"], ans: 1, exp: "视距外（BVLOS）无人机通讯链路通常采用定向天线，因为其高增益和窄波束宽度能 有效提高远距离通信的信号强度，减少信号损耗和干扰，适合超视距飞行需求。" },
  { id: 108, cat: "系统组成", q: "高效混合循环（HEHC）是一个（）循环，燃料/空气混合气通过转子进入内燃机，被压 缩和点燃，利用定体积燃烧提高效率。", opts: ["二冲程", "四冲程", "六冲程"], ans: 1, exp: "高效混合循环（HEHC）是一种四冲程循环。四冲程发动机的工作过程包括四个阶段： 进气、压缩、做功和排气。在 HEHC 中，燃料/空气混合气通过转子进入内燃机，被压缩和点 燃，利用定体积燃烧提高效率。这种循环方式在四冲程发动机中实现，能够有效提高燃烧效 率和减少排放。" },
  { id: 109, cat: "系统组成", q: "增压器是一种用于（）的辅助装置", opts: ["涡喷发动机", "活塞式发动机", "电动机"], ans: 1, exp: "增压器（Supercharger）主要用于活塞式发动机，通过增加进入发动机气缸的空气量，从而提高发动机的功率和效率。增压器通常通过压缩空气，使其在进入气缸前的压力增加，从而提高燃烧效率和动力输出。" },
  { id: 110, cat: "系统组成", q: "对于四冲程活塞发动机，曲轴每旋转四圈，点火会发生（）次。", opts: ["1", "2", "3"], ans: 1, exp: "四冲程活塞发动机的工作过程包括四个阶段：进气、压缩、做功和排气。每个工作循 环中，曲轴旋转两圈，点火发生一次。因此，曲轴每旋转四圈，点火会发生两次。" },
  { id: 111, cat: "系统组成", q: "飞控设备与飞机安装时要：（）", opts: ["特别紧固", "螺钉、减震器或双面胶", "很松动"], ans: 1, exp: "飞控设备与飞机安装时要：螺钉、减震器或者双面胶。这是因为高频振动会对飞控系 统的 IMIU（惯性测量单元）各传感器干扰最为严重，所以在安装飞控，特别是各传感器时，一定要注意防震。使用螺钉、减震器或者双面胶可以有效减少振动对飞控设备的影响，从而 提高飞行的稳定性和安全性。" },
  { id: 112, cat: "系统组成", q: "某活塞式化油器发动机增加油门时熄火则应（）。", opts: ["调整高速油针", "调整低速油针", "飞行时不加油门"], ans: 0, exp: "当增加油门时发动机熄火，通常是因为高速油针调整不当，导致高负荷时油气混合比 过稀。调整高速油针可以确保在高负荷时发动机能够获得足够的燃油，从而保持正常运转。" },
  { id: 113, cat: "系统组成", q: "某活塞式化油器发动机减小油门时熄火则应（）。", opts: ["调整高速油针", "调整低速油针", "飞行时不加油门"], ans: 1, exp: "当发动机减小油门时熄火，通常是因为低速油针调整不当，导致怠速时油气混合比过 稀。低速油针用于控制发动机在低负荷情况下的燃油供应，如果调整不当，可能会导致燃油 供应不稳定，从而引起熄火。因此，应该调整低速油针来解决这个问题。" },
  { id: 114, cat: "系统组成", q: "发动机火花塞出问题则会（）", opts: ["无法启动", "突然熄火", "以上皆有可能"], ans: 2, exp: "火花塞是发动机的关键部件，负责产生电火花点燃混合气，推动发动机运转。火花塞 故障（如积炭、电极烧蚀、间隙异常等）会导致点火失效，可能引发以下问题： 无法启动：若火花塞完全损坏，发动机无法点火； 突然熄火：若火花塞间歇性失火，运行中可能突然停机； 其他症状（如动力下降、抖动等）也可能出现，需综合判断。" },
  { id: 115, cat: "系统组成", q: "螺旋桨如果受损则可能（）", opts: ["高速运转中断裂", "引起发动机过度抖动损坏发动机", "以上皆有可能"], ans: 2, exp: "螺旋桨受损可能导致多种严重后果，具体包括但不限于以下几点： 1.高速运转中断裂：螺旋桨叶片受损后，可能在高速旋转时产生应力集中，导致叶片断裂。 2.引起发动机过度抖动损坏发动机：受损的螺旋桨会导致旋转不平衡，产生异常振动，进而 影响发动机的正常运行，甚至损坏发动机。 3.其他影响：螺旋桨损伤还可能导致效率降低、燃油浪费、航行性能下降等问题。 因此，螺旋桨受损时，上述情况皆有可能发生。" },
  // ==================== 空域 ====================
  { id: 116, cat: "空域", q: "除等待空域外，一个飞行空域，在同一个时间内，只允许安排（）航空器飞行。各批航 空器飞行活动的高度范围之间，通常应当保持（）以上的高度差。", opts: ["一至三批，2000 米", "一至两批，2000 米", "一至两批，1000 米"], ans: 0, exp: "根据《无人驾驶航空器飞行管理暂行条例》规定，划设无人驾驶航空器飞行空域应当 遵循统筹配置、安全高效原则，以隔离飞行为主，兼顾融合飞行需求，充分考虑飞行安全和 公众利益。划设无人驾驶航空器飞行空域应当明确水平、垂直范围和使用时间。在同一个飞 行空域内，通常只允许一批航空器飞行，以确保飞行安全和有效管理空域资源。因此，在一 个飞行空域内，只允许安排一至三批航空器飞行，且各批航空器飞行活动的高度范围之间，通常应当保持 2000 米以上的高度差，以确保飞行安全。" },
  { id: 117, cat: "空域", q: "穿越航路和航线的飞行，应当明确（），穿越时还应当保证与航路和航线飞行的航空器 有规定的飞行间隔。", opts: ["穿越的地段、高度和时间", "穿越的地段、方法、高度和时间", "穿越的地段、进出点、高度和时间"], ans: 0, exp: "根据《无人驾驶航空器飞行管理暂行条例》的规定，飞行活动已获得批准的单位或者 个人组织无人驾驶航空器飞行活动的，应当在计划起飞 1 小时前向空中交通管理机构报告预 计起飞时刻和准备情况，经空中交通管理机构确认后方可起飞。因此，穿越航路和航线的飞 行需要明确穿越的地段、高度和时间，以确保飞行安全和避免与其他航空器发生冲突。" },
  { id: 118, cat: "空域", q: "等待空域的最低高度层，距地面最高障碍物的真实高度不得小于（）。", opts: ["300 米", "600 米", "平原地区不小于 300 米，丘陵山区不小于 600 米"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》的规定，等待空域的最低高度层，距离地面最 高障碍物的真实高度不得小于 600 米。因此，当无人机需要在等待空域飞行时，必须确保其 飞行高度层符合这一规定，以保证飞行安全。" },
  { id: 119, cat: "空域", q: "对于备降的航空器，空中交通管制员，飞行指挥员或者航空公司签派员及其代理人，应 当立即通知备降机场准备接受航空器降落，同时指示航空器（）。", opts: ["飞往备降机场的航向和通知备降机场的天气情况", "飞往备降机场的航向，飞行高度和通知备降机场的天气情况", "飞行备降机场的航向，飞行高度，油量和通知备降机场的天气情况"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》的规定，当航空器因故不能在预定机场降落时，空中交通管制员、飞行指挥员或者航空公司签派员及其代理人应当立即通知备降机场准备接 受航空器降落，同时指示航空器飞往备降机场的航向、飞行高度和通知备降机场的天气情况。 这一规定确保了飞行安全和有效的应急响应措施。" },
  { id: 120, cat: "空域", q: "对于空中走廊的宽度，下列说法正确的是（）。", opts: ["通常为 8 公里，受条件限制时宽度不小于 5 公里", "通常为 10 公里，受条件限制时宽度不小于 8 公里", "通常为 15 公里，受条件限制时宽度不小于 10 公里"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》的规定，空中走廊通常划设在机场密集的大、中城市附近地区上空，其宽度通常为 10 公里，其中心线两侧各 5 公里。如果由于条件限制，空中走廊的宽度可以减小，但不得小于 8 公里。" },
  { id: 121, cat: "空域", q: "对于民用无人机实验飞行，以下正确的是（）。", opts: ["禁止无人机在未获得特殊批准下试验飞行", "试验飞行可经批准于人口稠密区、集镇或居住区的上空或者任何露天公众集会上空进行", "应在空中交通不繁忙的开阔水面或人口稀少区域上空实施"], ans: 2, exp: "根据《无人驾驶航空器飞行管理暂行条例》和《民用无人驾驶航空器运行安全管理规 则》的规定，无人机试验飞行应当在非人口稠密区、集镇或居住区的上空或者任何露天公众 集会上空进行，以确保飞行安全和公共安全。同时，飞行活动应当在空中交通不繁忙的开阔 水面或人口稀少区域上空实施，避免对地面人员和设施造成潜在威胁。此外，还应当遵守相 关的飞行高度限制和飞行间隔规定，确保无人机飞行活动不会干扰正常的空中交通秩序。" },
  { id: 122, cat: "空域", q: "飞行的安全高度是避免航空器与地面障碍物相撞的（）。", opts: ["航图网格最低飞行高度", "最低飞行安全高度", "最低飞行高度"], ans: 2, exp: "飞行的安全高度是指为了避免航空器与地面障碍物相撞而规定的最低飞行高度。这个 高度是航空器在特定区域飞行时必须遵守的最低高度限制，以确保飞行安全和避免与地面障 碍物发生碰撞。最低飞行高度通常由航空管理机构根据地形、障碍物分布和飞行规则设定，并在航图上标明。" },
  { id: 123, cat: "空域", q: "飞行高度层应当根据（）计算。", opts: ["标准大气压条件下平均平面", "标准大气压条件下假定海平面", "实际大气压条件下假定海平面"], ans: 1, exp: "飞行高度层是为了确保飞机在飞行过程中有秩序、安全地运行而设定的不同高度范围。 标准大气压条件下假定海平面是一个统一的参考平面，以这个平面为基准来计算飞行高度层，可以使不同地点、不同条件下的飞行高度有一个统一的标准和规范。" },
  { id: 124, cat: "空域", q: "飞行高度应当根据（）配备。", opts: ["航线或航路走向、航空器性能、飞行区域以及航线的地形、天气和飞行情况等", "飞行任务的性质、航空器等级、飞行区域以及航线的地形、天气和飞行情况等", "飞行任务的性质、航空器性能、飞行区域以及航线的地形、天气和飞行情况等"], ans: 2, exp: "根据《民用航空空中交通管理规则》的规定，飞行高度层应当根据飞行任务的性质、航空器性能、飞行区域以及航线的地形、天气和飞行情况等配备。这意味着在为航空器配备 飞行高度层时，需要综合考虑多种因素，以确保飞行安全和效率。" },
  { id: 125, cat: "空域", q: "飞行人员（），必须同空中交通管制员或者飞行指挥员保持无线电通信联络，并且严格 遵守通信纪律。", opts: ["在整个起飞阶段", "自起飞开车起到着陆后关车止", "进入驾驶舱后到飞行结束离开驾驶舱"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》的规定，飞行人员自起飞前开车起到着陆后关 车止，必须同空中交通管制员或者飞行指挥员保持无线电通信联络，并且严格遵守通信纪律。 这一规定强调了飞行人员在飞行过程中与空中交通管制员或飞行指挥员保持通信的重要性，以确保飞行安全和有效协调。" },
  { id: 126, cat: "空域", q: "飞行申请的内容包括（）。", opts: ["任务性质、航空器型别、装载情况、飞行范围、起止时间、飞行高度和飞行条件", "任务性质、航空器型别、飞行范围、起止时间、飞行高度和飞行条件", "任务性质、航空器型别、装载情况、起止时间、飞行高度和飞行条件"], ans: 1, exp: "飞行申请主要是为了让相关部门了解飞行的基本情况，以便进行管理和保障安全。任 务性质决定了飞行的目的和重要程度；航空器型别关系到飞机的性能和特点；飞行范围明确 了飞机活动的区域；起止时间确定了飞行的时段；飞行高度决定了飞机在空中的位置层次； 飞行条件包括天气等因素，这些都对飞行安全和管理至关重要。" },
  { id: 127, cat: "空域", q: "高空空域是指标准海平面气压多少米（不含）以上空域？", opts: ["6000", "7000", "8000"], ans: 0, exp: "根据《民用航空使用空域办法》第十三条的规定，在我国境内标准大气压高度 6000 米以上的空间，可以划设高空管制空域。这意味着高空空域是指标准海平面气压 6000 米（不 含）以上的空域。因此，高空空域的最低高度层是 6000 米以上，即 6000 米是高空空域的起 始高度。" },
  { id: 128, cat: "空域", q: "关于“飞行管理”不正确的是（）。", opts: ["在一个划定的管制空域内，可由两个空中交通管制单位负责空中交通管制", "通常情况下，民用航空器不得飞入禁区和限制区", "民用航空器未经批准不得飞出中华人民共和国领空"], ans: 0, exp: "1、飞行管理要求在一个划定的管制空域内，只能由一个空中交通管制单位负责空中 交通管制，以确保空中交通的统一指挥和协调，避免出现指挥混乱和安全隐患。因此，该选 项是不正确的。 2、通常情况下，民用航空器不得进入禁区和限制区。这是正确的，因为禁区和限制区通常 是为了飞行安全、国家安全或其他特殊原因而设立的，民用航空器在没有特殊许可的情况下 不得进入这些区域。 3、民用航空器未经批准不得飞出中华人民共和国领空。这也是正确的，根据国际航空法和 国内相关法规，民用航空器在飞出国境前需要获得相应的批准和许可。" },
  { id: 129, cat: "空域", q: "关于民用航空器使用禁区的规定是（）。", opts: ["绝对不得飞入", "符合目视气象条件方可飞入", "按照国家规定经批准后方可飞入"], ans: 2, exp: "根据《民用航空法》的规定，民用航空器除按照国家规定经特别批准外，不得飞入禁 区；除遵守规定的限制条件外，不得飞入限制区。这意味着，任何航空器，包括无人机，都 必须遵守国家的相关规定，除非获得特别的批准，否则不能进入禁区或限制区。因此，对于 民用无人机而言，它们必须遵守这些规定，以确保飞行安全和合法性。" },
  { id: 130, cat: "空域", q: "航空器飞离机场加入航路、航线和脱离航路、航线飞向机场，应当（）规定的航线和高 度上升或者下降。", opts: ["按照该机场使用细则", "公布的进离场程序", "按照该机场使用细则或者进离场程序"], ans: 2, exp: "根据《民用航空空中交通管理规则》的规定，航空器离机场加入航路、航线和脱离航 路、航线飞向机场，应当按照该机场使用细则或者进离场飞行程序规定的航线和高度上升或 者下降。" },
  { id: 131, cat: "空域", q: "航空器进行空域飞行时，应当按照规定的（）进入空域或者脱离空域，并且保持在规定 的空域和高度范围内飞行。", opts: ["航线（航向）、高度、次序和进出点", "航线（航向）、高度、次序", "航线（航向）、高度"], ans: 1, exp: "航空器在进行空域飞行时，必须遵循严格的规定以确保飞行安全和空中交通的有序。 这些规定包括按照指定的航线（航向）飞行、保持特定的高度层以及遵守空中交通管制规定 的次序。这些因素共同确保了航空器能够安全、高效地进入和脱离空域，并且在规定的空域 和高度范围内飞行。" },
  { id: 132, cat: "空域", q: "航空器可否飞入空中危险区或临时空中危险区？（）", opts: ["不行", "可以，但必须得到相关部门的批准", "可以，但必须在规定时限以外"], ans: 2, exp: "根据《中华人民共和国飞行基本规则》的规定，位于机场、航路、航线附近的对空射 击场或者发射场等，根据其射向、射高、范围，可以在上空划设空中危险区或者临时空中危 险区。在规定时限内，禁止无关航空器飞入空中危险区或者临时空中危险区。" },
  { id: 133, cat: "空域", q: "航空器使用航线和航路，应当经（）同意。", opts: ["负责该航路和航线的飞行管制部门", "空中交通管理局下属区域管制部门", "中国人民解放军空军"], ans: 0, exp: "根据《中华人民共和国飞行基本规则》的规定，航空器使用航路和航线，应当经负责 该航路和航线的飞行管制部门同意。这一规定明确指出，任何航空器在进行航路和航线飞行 前，都必须获得相应飞行管制部门的批准，以确保飞行安全和空中交通秩序。" },
  { id: 134, cat: "空域", q: "航空器与 ATC 进行第一次无线电联络时，应当首先呼叫（）。", opts: ["所需联系的 ATC 的名称", "航空器的注册号", "航空器的机型"], ans: 0, exp: "首次联络 ATC，先呼管制部门名。当航空器与空中交通管制（ATC）进行第一次无线 电联络时，按照标准操作程序，首先应当呼叫所需联系的空中交通管制部门的名称。这样做 是为了确保通信的准确性，让 ATC 知道是哪架航空器正在尝试建立联系，并准备进行后续的 通信和管制指令。" },
  { id: 135, cat: "空域", q: "航路，航线地带和民用机场区域设置（）。", opts: ["高空管制区，中低空管制区，机场塔台管制区", "航路管制区，终端（进近）管制区，机场塔台管制区", "高空管制区，中低空管制区，终端（进近）管制区，机场塔台管制区"], ans: 2, exp: "在航路、航线地带和民用机场区域需要设置不同层级的管制区域以确保空中交通的安 全有序。高空管制区主要负责高空空域的交通管理；中低空管制区管理中低空的航空器飞行； 终端（进近）管制区负责航空器进出机场附近空域的管制；机场塔台管制区则直接管理机场 跑道及附近空域的航空器起降等活动。" },
  { id: 136, cat: "空域", q: "航路的宽度为（）。", opts: ["10 公里", "20 公里", "25 公里"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》的规定，空中交通管制航路的宽度为 20 千米，其中心线两侧各 10 千米。这意味着航路的总宽度是 20 公里，每侧各 10 公里。因此，航路 的宽度是 20 公里。" },
  { id: 137, cat: "空域", q: "航路的某一段受到条件限制时，可以较小宽度，但不得小于（）。", opts: ["8 公里", "10 公里", "15 公里"], ans: 0, exp: "根据《中华人民共和国飞行基本规则》的规定，空中交通管制航路的宽度为 20 公里，其中心线两侧各 10 公里；航路的某一段受到条件限制的，可以减少宽度，但不得小于 8 公 里。" },
  { id: 138, cat: "空域", q: "获准飞出或者飞入中华人民共和国领空的航空器，实施飞出或者飞入中华人民共和国领 空的飞行和各飞行管制区间的飞行（）。", opts: ["必须经相关管制单位批准", "必须经中国人民解放军空军批准", "必须经由国务院、中央军委空中交通管制委员会批准"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》的规定，获准飞出或者飞入中华人民共和国领 空的航空器，实施飞出或者飞入中华人民共和国领空的飞行和各飞行管制区间的飞行，必须 经中国人民解放军空军批准。这一规定明确指出，任何航空器在飞入或飞出中国领空时，都 需要得到中国人民解放军空军的批准，以确保飞行活动的安全和合规性。" },
  { id: 139, cat: "空域", q: "机场的跑道长度，必须满足（）。", opts: ["顺风起降", "逆风起降", "侧风起降"], ans: 0, exp: "机场跑道长度的设计主要基于飞机的起降性能、机场的海拔高度、地形坡度、气温和 风等因素。跑道长度必须满足飞机在顺风起降条件下的需求，这是因为顺风起降时，飞机需 要更长的滑跑距离来达到足够的速度。 因此，机场跑道长度必须满足以下条件：顺风起降：跑道长度需足够长，以确保飞机在顺风 条件下仍能安全起飞和降落。" },
  { id: 140, cat: "空域", q: "机场区域的界线通常与（）的界线相同。", opts: ["区域低空管制区", "机场进近管制区", "机场飞行（塔台）管制区"], ans: 2, exp: "本题考查的是机场区域界线的相关知识。机场区域的界线通常与机场飞行（塔台）管制区的 界线相同。机场飞行（塔台）管制区主要负责对机场附近一定范围内的航空器进行管制指挥，其范围通常与机场区域范围较为一致。" },
  { id: 141, cat: "空域", q: "空域管理的具体办法由（）制定。", opts: ["民用航空局", "中央军委会", "国务院和中央军事委员会"], ans: 2, exp: "空域管理是指对国家领空内飞行活动的组织与管理，以确保飞行安全和有效利用空域 资源。根据《中华人民共和国飞行基本规则》和相关法律法规，空域管理的具体办法是由国 务院和中央军事委员会共同制定的。" },
  { id: 142, cat: "空域", q: "空域是航空器运行的环境，也是宝贵的国家资源。国务院、中央军委十分重视我国民用 航空交通管制的建设工作，目前正在推进空域管理改革，预计划分三类空域，为（）。", opts: ["管制空域、监视空域和报告空域", "管制空域、非管制空域和报告空域", "管制空域、非管制空域和特殊空域"], ans: 0, exp: "目前我国正在推进空域管理改革，预计划分三类空域，分别是管制空域、监视空域和 报告空域。 管制空域是指在该空域内飞行的航空器必须接受空中交通管制服务，以确保飞行安全和有序。 监视空域是指在该空域内飞行的航空器只需接受监视，以便空中交通管制部门了解其位置和 飞行状态，但不一定需要具体的管制指令。 报告空域是指在该空域内飞行的航空器只需向空中交通管制部门报告其位置和飞行意图等 信息即可。" },
  { id: 143, cat: "空域", q: "空域通常划分为：①机场飞行空域；②航路、航线③空中禁区、空中限制区和空中危险 区。（）", opts: ["①②", "①③", "①②③"], ans: 2, exp: "空域通常划分为以下几类： 机场飞行空域：供飞机起飞、降落和训练使用。 航路与航线：飞机按照规定的路径飞行的空中通道。 空中禁区：未经许可禁止进入的区域，如重要政治或军事目标上空。 空中限制区：特定时间内限制航空器飞入的区域，可能因军事活动等原因设置。 空中危险区：存在潜在危险（如对空射击）的区域，在规定时间禁止无关航空器进入。 因此，正确答案是①②③。" },
  { id: 144, cat: "空域", q: "空中交通管制单位为飞行中的民用航空器提供的空中交通服务中含有（）。", opts: ["飞行情报服务", "机场保障服务", "导航服务"], ans: 0, exp: "空中交通管制单位为飞行中的民用航空器提供的空中交通服务中含有飞行情报服务。 飞行情报服务主要向飞行员和有关的空中交通服务单位及时提供关于航行要素变化的信息，如机场状况、气象条件、航路及导航设施的变化等。" },
  { id: 145, cat: "空域", q: "空中交通管制员或者飞行指挥员允许航空器飞入机场区域时，应当及时向飞行员通报（）。", opts: ["机场区域内有关的飞行情况、气象条件", "进入的飞行高度、机场区域内有关的飞行情况、气象条件", "进入的飞行高度、气象条件"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》第五十八条的规定，空中交通管制员或者飞行 指挥员允许航空器飞入机场区域时，应当及时向飞行员通报包括以下情况： 1、进入的飞行高度； 2、机场区域内有关的飞行情况； 3、水平能见度或者跑道视程、天气现象和机场上空的云底高度，地面和穿云高度上的风向、风速，场面气压或者修正海平面气压，或者零点高度，以及地面大气温度； 4、仪表进场或者穿云方法和着陆航向。 因此，选项（进入的飞行高度、机场区域内有关的飞行情况、气象条件）是正确的，因为它 涵盖了上述规定中的主要内容，包括飞行高度、飞行情况和气象条件。" },
  { id: 146, cat: "空域", q: "民用航空器因故确需偏离指定的航路或者改变飞行高度飞行时，应当首先（）。", opts: ["得到机长允许", "取得机组的一致同意", "取得空中交通管制单位的许可"], ans: 2, exp: "根据《中华人民共和国飞行基本规则》的规定，民用航空器应当按照空中交通管制单 位指定的航路和飞行高度飞行；因故确需偏离指定的航路或者改变飞行高度飞行的，应当取 得空中交通管制单位的许可。这意味着，如果民用航空器在飞行过程中需要偏离原定的航路 或改变飞行高度，必须首先获得空中交通管制单位的批准，以确保飞行安全和遵守空中交通 规则。" },
  { id: 147, cat: "空域", q: "民用航空器在管制空域内飞行，（）。", opts: ["可以自由飞行", "可以按 VFR 自由飞行", "必须取得空中交通管制单位的许可"], ans: 2, exp: "民用航空器在管制空域内飞行，必须取得空中交通管制单位的许可。管制空域是由空 中交通管制单位进行管理和控制的空域，为了确保飞行安全和有序，民用航空器在该空域内 飞行不能自由飞行，也不能仅按 VFR（目视飞行规则）自由飞行，必须得到空中交通管制单 位的许可，包括飞行航线、高度、速度等方面的许可。" },
  { id: 148, cat: "空域", q: "民用无人驾驶航空器系统视距内运行是指航空器处于驾驶员或观测员目视视距内半径 （）米，相对高度低于（）米的区域内。", opts: ["120、500", "500、120", "100、50"], ans: 1, exp: "民用无人驾驶航空器系统视距内运行的定义是明确的。视距内运行是指无人机操控员 或无人机观测员与无人机保持直接目视视觉接触的范围内运行，且该范围为目视视距内半径 不大于 500 米，无人机相对高度不大于 120 米。" },
  { id: 149, cat: "空域", q: "农业作业飞行的最低天气标准，平原地区是（）。", opts: ["云高不低于 100 米，能见度不小于 3 公里", "云高不低于 150 米，能见度不小于 5 公里", "云高不低于 200 米，能见度不小于 5 公里"], ans: 1, exp: "对于农业作业飞行，平原地区的最低天气标准是云高不低于 150 米，能见度不小于 5 公里。这是因为农业作业飞行通常在相对较低的高度进行，需要有一定的云高保证飞机与云 层之间有足够的安全距离，避免飞机飞入云中遭遇危险情况。同时，足够的能见度可以让飞 行员清晰地看到地面目标和周围的障碍物，确保飞行安全和作业的准确性。" },
  { id: 150, cat: "空域", q: "申请飞行计划通常应当于飞行前一日什么时间向空中交通管制部门提出申请，并通知有 关单位？（）", opts: ["15 时前", "16 时前", "17 时前"], ans: 0, exp: "根据《中国民用航空空中交通管理规则》的规定，航空器的经营人、所有人或者航空 器驾驶员，应当于飞行实施前一日 15 时前，向当地机场空中交通服务报告室提交飞行预报 申请。" },
  { id: 151, cat: "空域", q: "为了安全，飞机飞行时常开什么灯（）", opts: ["防撞灯", "航行灯", "着陆灯"], ans: 1, exp: "飞机在飞行时常开航行灯。国际航空法规强制要求，航行灯是飞行中必须常开的基础 灯光。航行灯主要作用是在夜间或能见度不良的情况下，向其他飞机和地面人员显示飞机的 位置、方向和运动状态，有助于避免空中相撞等危险情况。 而防撞灯一般在飞机起飞、降落和飞行中可能发生碰撞危险的特定阶段开启；着陆灯主要在 飞机着陆阶段使用，照亮跑道，但并非全程飞行中常开。" },
  { id: 152, cat: "空域", q: "我国管制空域包括 ABCD 四类空中交通服务空域。每一个空域都是一个划定范围的三维空间，其中（）空域是中、低空管制空域，为 6000m（含）以下至最低高度层以上空间。", opts: ["A 类", "B 类", "C 类", "D 类"], ans: 1, exp: "根据《中国民用航空空中交通管理规则》的规定，B 类空域为中低空管制空域。在我 国境内标准大气压高度 6000 米（含）至其下某指定高度的空间，可以划设中低空管制空域。 在此类空域内飞行的航空器，可以按照仪表飞行规则飞行，并接受空中交通管制服务；对符 合目视气象条件的，经航空器驾驶员申请，并经过相应的管制单位批准，也可以按照目视飞 行规则飞行，并接受空中交通管制服务。" },
  { id: 153, cat: "空域", q: "无识别标志的航空器因特殊情况需要飞行的，（）。", opts: ["必须经相关管制单位批准", "必须经中国人民解放军空军批准", "必须经中国民用航空总局空中交通管理局批准"], ans: 1, exp: "无标飞行找空军，特殊情况需批准。根据《中华人民共和国飞行基本规则》的规定，在中华人民共和国领空飞行的航空器，必须标明明显的识别标志，禁止无识别标志的航空器 飞行。无识别标志的航空器因特殊情况需要飞行的，必须经中国人民解放军空军批准。" },
  { id: 154, cat: "空域", q: "下列哪种情况下，无人机系统驾驶员由局方实施管理？（）", opts: ["在融合空域运行的 Ⅱ类无人机", "在融合空域运行的 Ⅺ类无人机", "在隔离空域内超视距运行的无人机"], ans: 1, exp: "根据《民用无人驾驶航空器系统驾驶员管理暂行规定》Ⅺ类无人机在融合空域运行时，其驾驶员由局方实施管理。Ⅰ类无人机在融合空域运行时，其驾驶员由行业协会实施管理。 隔离空域内超视距运行的无人机驾驶员由行业协会实施管理。" },
  { id: 155, cat: "空域", q: "下列哪种情况下，无人机系统驾驶员由行业协会实施管理？（）", opts: ["在融合空域运行的小型无人机", "充气体积在 4600 立方米以上的遥控飞艇", "在隔离空域内超视距运行的无人机"], ans: 2, exp: "根据《民用无人驾驶航空器系统驾驶员管理暂行规定》，在隔离空域内超视距运行的 无人机系统驾驶员由行业协会实施管理。" },
  { id: 156, cat: "空域", q: "下面哪个单位领导全国的飞行管制工作？（）", opts: ["国务院", "民航局", "国务院、中央军委空中交通管制委员会"], ans: 2, exp: "国务院、中央军委空中交通管制委员会简称国家空管委，负责领导全国的飞行管制工 作。" },
  { id: 157, cat: "空域", q: "相邻机场距离过近的（）。", opts: ["可以合划一个机场区域", "不能合划一个区域", "不能在其他空域划定机场区域"], ans: 0, exp: "根据《中华人民共和国飞行基本规则》的规定，相邻机场距离过近的，可以合划一个 机场区域。这一规定明确了在特定情况下，相邻机场可以共享一个机场区域，以优化空域资 源的使用。" },
  { id: 158, cat: "空域", q: "沿（）应当设有备降机场。", opts: ["国际、国内干线航路和固定航线", "国际航路和固定航线", "航路和固定航线"], ans: 2, exp: "根据《中华人民共和国飞行基本规则》的规定，沿航路和固定航线应当有备降机场。 备降机场应当有必备的设备和良好的通信、导航、气象保障。" },
  { id: 159, cat: "空域", q: "仪表（云中）飞行空域的边界距离航路，空中走廊以及其他空域的边界，不得小于（）。", opts: ["5 公里", "10 公里", "15 公里"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》的规定，仪表（云中）飞行空域的边界距离航 路、空中走廊以及其他空域的边界，均不得小于 10 公里。" },
  { id: 160, cat: "空域", q: "在管制机场附近的所有航空器，以及在地面的航空器都服从（）的指令。", opts: ["管制员", "机务人员", "机长"], ans: 0, exp: "在管制机场附近，为了确保空中交通的安全、有序和高效，所有航空器以及在地面的 航空器都必须服从管制员的指令。管制员负责对该区域内的航空器进行指挥和调配，包括起 飞、降落、航线安排等，以避免航空器之间的冲突和危险接近。" },
  { id: 161, cat: "空域", q: "在广阔水域上空进行各种渔业飞行的最低天气标准是（）。", opts: ["云高不得低于 100 米，水平能见度不得小于 2 公里", "云高不得低于 150 米，水平能见度不得小于 3 公里", "云高不得低于 200 米，水平能见度不得小于 3 公里"], ans: 2, exp: "这道题目考察的是无人机在广阔水域上空进行渔业飞行时的最低天气标准。在水域上 空飞行，由于缺乏紧急着陆点，对能见度和云高的要求更为严格，以确保无人机的安全飞行 和操作。正确答案是：云高不得低于 200 米，水平能见度不得小于 3 公里。这是为了保证在 水域上空飞行时，无人机操作员有足够的空间进行操作，并能在遇到紧急情况时有足够的时 间和距离做出反应。" },
  { id: 162, cat: "空域", q: "在丘陵、山区、高原进行农业作业飞行的最低天气标准是（）。", opts: ["云高不得低于 100 米，水平能见度不得小于 2 公里", "云高不得低于 150 米，水平能见度不得小于 3 公里", "云高不得低于 300 米，水平能见度不得小于 5 公里"], ans: 2, exp: "在丘陵、山区、高原地区进行农业作业，地形更加复杂，存在山体、沟壑等障碍物，对飞行安全的要求更高。云高不得低于 300 米，这样可以确保飞机与云层保持足够的安全距 离，避免飞机在复杂地形中飞入云层遭遇危险情况，如低云可能带来的撞山风险等。水平能 见度不得小于 5 公里，较高的能见度能让飞行员在复杂地形环境下更好地观察周围的地形地 貌、障碍物以及其他飞行器等，以便及时做出正确的判断和操作，确保飞行安全。" },
  { id: 163, cat: "空域", q: "在融合空域 3000 米以上运行的 Ⅺ级别无人机驾驶员，应至少持有飞机或直升机等级的 （）。", opts: ["航线运输执照", "私照", "商照"], ans: 2, exp: "根据《民用无人驾驶航空器系统驾驶员管理规定》，具体要求如下： Ⅺ类无人机： 在 3000 米以下运行的驾驶员需持有运动或私用驾驶员执照，并带有相似类别等级； 在 3000 米以上运行的驾驶员则需持有带飞机或直升机等级的商用驾驶员执照。 Ⅻ类无人机： 驾驶员需持有带飞机或直升机等级的商用驾驶员执照及仪表等级； 机长需持有航线运输执照。" },
  { id: 164, cat: "空域", q: "在融合空域 3000 米以下运行的 Ⅺ类无人机驾驶员，应至少持有（）。", opts: ["运动或私用驾驶员执照", "商照", "私照"], ans: 0, exp: "根据《民用无人驾驶航空器系统驾驶员管理规定》，具体要求如下： Ⅺ类无人机： 在 3000 米以下运行的驾驶员需持有运动或私用驾驶员执照，并带有相似类别等级； 在 3000 米以上运行的驾驶员则需持有带飞机或直升机等级的商用驾驶员执照。 Ⅻ类无人机： 驾驶员需持有带飞机或直升机等级的商用驾驶员执照及仪表等级； 机长需持有航线运输执照。" },
  { id: 165, cat: "空域", q: "在融合空域运行的 Ⅻ级别无人机驾驶员，应至少持有（）。", opts: ["商照和仪表等级", "航线运输执照", "商照"], ans: 0, exp: "题目问的是驾驶员。根据《民用航空器驾驶员合格审定规则》（CCAR61）和相关法 规，对于在融合空域运行的 Ⅻ级别无人机驾驶员，执照要求如下： 在融合空域运行的 Ⅻ级别无人机驾驶员，应至少持有带有飞机或直升机类别等级的商用驾 驶员执照和仪表等级。 在融合空域运行的 Ⅻ级别无人机机长，应至少持有航线运输驾驶员执照。" },
  { id: 166, cat: "空域", q: "下列哪种情况下民用航空器可以飞越城市上空？（）", opts: ["指定的航路必须飞越城市上空时", "能见地标的目视飞行时", "夜间飞行时"], ans: 0, exp: "这道题目考察的是民用航空器在什么情况下可以飞越城市上空的法律规定。根据《中 华人民共和国民用航空法》的规定，民用航空器原则上不得飞越城市上空，但存在几种例外 情况。因此，“指定的航路必须飞越城市上空时”是民用航空器可以飞越城市上空的情形之 一。" },
  { id: 167, cat: "空域", q: "在一个划定的管制空域内，由（）负责该空域内的航空器的空中交通管制。", opts: ["军航或民航的一个空中交通管制单位", "军航和民航的各一个空中交通管制单位", "军航的一个空中交通管制单位"], ans: 0, exp: "这道题目考察的是在划定的管制空域内，谁负责该空域内航空器的空中交通管制。根 据相关规定，在一个划定的管制空域内，只有一个空中交通管制单位负责该空域内的航空器 的空中交通管制。" },
  { id: 168, cat: "空域", q: "在中华人民共和国境内，按照飞行管制责任划分为（）", opts: ["飞行管制区、飞行管制分区、机场飞行管制区", "飞行管制区、飞行情报区、机场飞行管制区", "航路飞行管制区、空域飞行管制区、机场飞行管制区"], ans: 0, exp: "根据《中华人民共和国飞行基本规则》的规定，在中华人民共和国境内，按照飞行管 制责任划分为飞行管制区、飞行管制分区、机场飞行管制区。" },
  { id: 169, cat: "空域", q: "在中华人民共和国境内飞行的航空器必须遵守统一的飞行规则，该飞行规则应当由（）制定。", opts: ["民用航空局和中央军委", "中央军委", "国务院和中央军委"], ans: 2, exp: "在中华人民共和国境内飞行的航空器必须遵守统一的飞行规则，而这些飞行规则应当 由国务院和中央军委制定。国务院负责国家的行政管理事务，包括民用航空领域的部分管理 职能；中央军委则对国家的军事航空以及涉及国防安全的航空活动进行领导和管理。两者共 同制定飞行规则可以确保民用航空和军事航空的协调统一，保障国家空域的安全和有序使用。" },
  { id: 170, cat: "空域", q: "执行紧急救护、抢险救灾或者其它紧急任务，飞行计划申请最迟应在飞行前（）提出。", opts: ["30 分钟", "1 小时", "2 小时"], ans: 1, exp: "根据《通用航空飞行管制条例》的规定，执行紧急救护、抢险救灾、人工影响天气或 者其他紧急任务的，可以提出临时飞行计划申请。临时飞行计划申请最迟应当在拟飞行 1 小时前提出。" },
  { id: 171, cat: "空域", q: "执行昼间专业任务的航空器，在平原、丘陵地区进行作业飞行时，起飞时间最早不得早 于日出前（）。", opts: ["15 分钟", "20 分钟", "30 分钟"], ans: 2, exp: "这道题目考察的是执行昼间专业任务的航空器在平原、丘陵地区进行作业飞行时的起 飞时间规定。根据《中国民用航空飞行规则》第七章通用航空飞行第 122 条的规定，在昼间 和拂晓进行作业飞行时，应当根据任务性质、作业地区地形确定每天开始和结束飞行的时间。 只有在能够清楚地看到地标和能够目视判断作业飞行高度的情况下，方可起飞，但不得早于 日出前 30 分钟（山区日出前 20 分钟）；着陆时间不得晚于日落时间（山区日落前 15 分钟）。" },
  { id: 172, cat: "空域", q: "执行昼间专业任务的航空器，在山区进行作业飞行时，起飞时间最早不得早于日出前（）。", opts: ["10 分钟", "15 分钟", "20 分钟"], ans: 2, exp: "这道题目考察的是执行昼间专业任务的航空器在山区进行作业飞行时的起飞时间规定。 根据《中国民用航空飞行规则》第七章通用航空飞行第 122 条的规定，在昼间和拂晓进行作 业飞行时，应当根据任务性质、作业地区地形确定每天开始和结束飞行的时间。只有在能够 清楚地看到地标和能够目视判断作业飞行高度的情况下，方可起飞，但不得早于日出前 30 分钟（山区日出前 20 分钟）；着陆时间不得晚于日落时间（山区日落前 15 分钟）。" },
  { id: 173, cat: "空域", q: "执行昼间专业任务的航空器，在山区进行作业飞行时，着陆时间最晚不得晚于日落（）。", opts: ["10 分钟", "15 分钟", "20 分钟"], ans: 1, exp: "根据《中国民用航空飞行规则》第七章通用航空飞行第 122 条的规定，在昼间和拂晓 进行作业飞行时，应当根据任务性质、作业地区地形确定每天开始和结束飞行的时间。只有 在能够清楚地看到地标和能够目视判断作业飞行高度的情况下，方可起飞，但不得早于日出 前 30 分钟（山区日出前 20 分钟）；着陆时间不得晚于日落时间（山区日落前 15 分钟）。" },
  { id: 174, cat: "空域", q: "无人机上的仪表、压力计管路和所有承压软管，应能承受（）规定最高工作压力的 1.5 倍的压力而无渗漏。", opts: ["不大于", "等于", "不小于"], ans: 2, exp: "无人机上仪表、压力计管路和承压软管的耐压要求。根据相关标准，这些部件应能承 受不小于规定最高工作压力的 1.5 倍的压力，且在此压力下无渗漏。这是为了确保无人机在 极端条件下仍能安全运行。" },
  { id: 175, cat: "空域", q: "气象台发布的风向标有 SE，为（）。", opts: ["西南风", "东南风", "西北风"], ans: 1, exp: "题目考查的是风向标的解读。气象台发布的风向标中，“SE”代表东南风，即风从东 南方向吹来。这一表示方法遵循国际通用标准：E 为东、W 为西、S 为南、N 为北；NE 为东 北风、SW 为西南风等。" },
  { id: 176, cat: "空域", q: "在融合空域运行的大型无人机机长，至少持有（）。", opts: ["航线运输执照", "商照", "商照和仪表等级"], ans: 0, exp: "根据《民用无人驾驶航空器系统驾驶员管理规定》，具体要求如下： Ⅺ类无人机：在 3000 米以下运行的驾驶员需持有运动或私用驾驶员执照，并带有相似类别 等级；在 3000 米以上运行的驾驶员则需持有带飞机或直升机等级的商用驾驶员执照。 Ⅻ类无人机：驾驶员需持有带飞机或直升机等级的商用驾驶员执照及仪表等级；机长需持 有航线运输执照。" },
  { id: 177, cat: "空域", q: "在融合空域（）以下运行的小型无人机驾驶员，应至少持有私用驾驶员执照。", opts: ["2000 米", "3000 米", "4000 米"], ans: 1, exp: "根据《民用无人驾驶航空器系统驾驶员管理暂行规定》，在融合空域 3000 米以下运 行的小型无人机驾驶员，应至少持有私用驾驶员执照（仅带有轻于空气航空器等级的除外）。" },
  { id: 178, cat: "空域", q: "以下哪个空域属于进近管制空域？通常是指在一个或几个机场附近的航路汇合处划设的，便于进场和离场航空器飞行的管制空域。", opts: ["A 类空域", "B 类空域", "C 类空域", "D 类空域"], ans: 2, exp: "题目考查的是进近管制空域的分类。进近管制空域通常是指在一个或几个机场附近的 航路汇合处划设的便于进场和离场的航空器飞行的管制空域。根据国际民航组织（ICAO）的 空域分类标准： C 类空域：属于进近管制空域，适用于机场附近的航路汇合处，主要用于管理进场和离场的 航空器。 A 类空域：通常用于高空航路，仅允许仪表飞行规则（IFR）飞行。 B 类空域：通常用于繁忙机场周围的终端管制区，管理高密度交通。 因此，C 类空域是正确答案。" },
  { id: 179, cat: "空域", q: "在融合空域运行的充气体积在 4600 立方米以上的遥控飞艇驾驶员，应至少持有（）。", opts: ["飞艇私照", "飞艇商照", "热气球商照"], ans: 1, exp: "根据《民用无人驾驶航空器系统驾驶员管理暂行 规定》，在融合空域运行的充气体积在 4600 立方米以上的遥控飞艇驾驶员，应至少持有带 有飞艇等级的商用驾驶员执照。" },
  { id: 180, cat: "空域", q: "在融合空域 3000 米以下运行的小型无人机驾驶员，应至少持有（）。", opts: ["航线运输执照", "私照", "商照"], ans: 1, exp: "根据《民用无人驾驶航空器系统驾驶员管理暂行规定》第七条，在融合空域 3000 米 以下运行的小型无人机驾驶员，应至少持有私用驾驶员执照。" },
  { id: 181, cat: "空域", q: "负责一个或几个机场的航空器进、离场管制工作的是（）。", opts: ["塔台管制室", "进近管制室", "区域塔台管制室"], ans: 1, exp: "进近管制室负责一个或几个机场的航空器进、离场管制工作，包括引导飞机进入和离 开机场的终端区。 其他选项分析如下： 1、塔台管制室：错误。塔台管制室主要负责机场跑道和滑行道的直接管制，包括起飞、降 落和地面滑行的指挥。 2、区域塔台管制室：错误。区域塔台管制室并不存在，区域管制室负责高空管制，而不是 机场的进离场管制。" },
  { id: 182, cat: "空域", q: "空中走廊内高度层的间隔为（）。", opts: ["600 米", "300 米", "150 米"], ans: 1, exp: "根据《民用航空空中交通管理规则》的相关规定，空中走廊内高度层的间隔为 300 米。" },
  { id: 183, cat: "空域", q: "无人机飞行员向前推杆，飞机的迎角（）。", opts: ["增大", "减小", "先减小后增大"], ans: 1, exp: "向前推杆会使飞机的机头下压，从而减小飞机的迎角。迎角是指飞机机翼弦线与相对 气流方向之间的夹角，机头下压时，相对气流方向与机翼弦线的夹角减小，因此迎角减小。" },
  { id: 184, cat: "空域", q: "航线规划一般分两步：首先是飞行前（），其次是飞行中（）。", opts: ["预先规划，在线规划", "预先规划，实时规划", "预规划，重规划"], ans: 2, exp: "航线规划通常分为两个阶段： 预规划：在飞行前进行，包括对任务区域的分析、航线设计、飞行参数设置等。 重规划：在飞行中进行，根据实时情况（如天气变化、障碍物等）对预规划的航线进行调整 和优化。" },
  { id: 185, cat: "空域", q: "（）是指综合考虑无人机系统本身的约束条件、目标任务需求和应急情况设定，合理设 置地面站与无人机的配比关系，科学部署工作地域内的各种无人机地面站，制定突发情况下 的无人机工作方案。", opts: ["系统保障与维护预案规划", "系统保障与安全措施规划", "系统保障与应急预案规划"], ans: 2, exp: "系统保障与应急预案规划是指综合考虑无人机系统本身的约束条件、目标任务需求和 应急情况设定，合理设置地面站与无人机的配比关系，科学部署工作地域内的各种无人机地 面站，制定突发情况下的无人机工作方案。" },
  // ==================== 法律法规 ====================
  { id: 186, cat: "法律法规", q: "《一般运行和飞行规则》的颁布目的是：①为了维护国家领空主权；②为了规范民用航 空器的运行；③保证飞行的正常与安全。（）", opts: ["①②③", "①②", "②③"], ans: 2, exp: "《一般运行和飞行规则》（CCAR-91 部）的立法目的是规范民用航空器的运行、保证飞行的正常与安全（②③）。'维护国家领空主权'不属于该规则的颁布目的，相关主权与空域管辖事项由其他法律法规规定，故①不选。正确答案为 C（②③）。" },
  { id: 187, cat: "法律法规", q: "《中国民用航空法》的颁布目的：①为了维护国家的领空主权和民用航空权利；②保 障民用航空活动安全和有秩序地进行；③保护民用航空活动当事人各方的合法权益；④促 进民用航空事业的发展。（）", opts: ["③④", "①②", "①②③④"], ans: 2, exp: "《中国民用航空法》的颁布目的涵盖了多个方面。为了维护国家的领空主权和民用航 空权利，体现了国家对领空的管辖和对民用航空领域的主权维护；保障民用航空活动安全和 有秩序地进行，这是确保航空活动顺利开展的基础；保护民用航空活动当事人各方的合法权 益，包括旅客、货主、航空公司等各方的权益；促进民用航空事业的发展，推动民用航空产 业不断进步。所以①②③④全选。" },
  { id: 188, cat: "法律法规", q: "《中国民用航空法》中“飞行人员”是指（）", opts: ["在飞行中直接操纵航空器和航空器上航行、通信等设备的人员", "机长和副驾驶", "机组"], ans: 0, exp: "《中华人民共和国民用航空法》定义的“飞行人员”特指直接操作航空器及航行设备 的人员，不包括其他机组。A 项准确对应法条规定，B、C 范围过宽。" },
  { id: 189, cat: "法律法规", q: "《中国民用航空法》中“航空人员”是指从事民用航空活动的（）", opts: ["空勤人员", "空勤人员和地面人员", "飞行人员和地面人员"], ans: 1, exp: "根据《中华人民共和国民用航空法》的规定，本法所称航空人员，是指下列从事民用 航空活动的空勤人员和地面人员：（一）空勤人员，包括驾驶员、飞行机械人员、乘务员； （二）地面人员，包括民用航空器维修人员、空中交通管制员、飞行签派员、航空电台通信 员。" },
  { id: 190, cat: "法律法规", q: "《中华人民共和国民用航空法》自（）起施行", opts: ["1996 年 1 月 1 日", "1996 年 3 月 1 日", "1997 年 1 月 1 日"], ans: 1, exp: "《中华人民共和国民用航空法》自 1996 年 3 月 1 日起施行。这部法律的实施对于规范 民用航空活动，保障民用航空安全，促进民用航空事业的发展具有重大意义。" },
  { id: 191, cat: "法律法规", q: "CCAR61 部授权的执照或合格证持有人在理论考试中作弊或发生其他禁止行为，局方（授 权方）拒绝其任何执照、合格证或等级申请期限为（）", opts: ["一年", "半年", "视其违规的情节轻重而定"], ans: 0, exp: "CCAR61 部授权的执照或合格证持有人在理论考试中作弊或发生其他禁止行为，局方 （授权方）将撤销相应的执照等级，并责令当事人立即停止飞行运行，同时要求当事人交回 已取得的执照或合格证。此外，局方还将拒绝其任何执照、合格证或等级申请，期限为一年。" },
  { id: 192, cat: "法律法规", q: "CCAR61 部授权的执照或合格证持有人在理论考试中作弊或发生其他禁止行为，局方（授 权方）撤销相应的执照等级，责令当事人立即停止飞行运行并交回其已取得的执照或合格证，（）年内不得申请按照 CCAR61 颁发的执照、合格证或等级以及考试。", opts: ["一", "三", "视其违规的情节轻重而定"], ans: 1, exp: "CCAR61 部授权的执照或合格证持有人在理论考试中作弊或发生其他禁止行为，局方 （授权方）撤销相应的执照等级，责令当事人立即停止飞行运行并交回其已取得的执照或合 格证，三年内不得申请按照 CCAR61 颁发的执照、合格证或等级以及考试。" },
  { id: 193, cat: "法律法规", q: "飞行任务书是许可飞行人员进行转场飞行和民用航空飞行的基本文件，由（）签发。", opts: ["驻机场航空单位或者航空公司的运行管理部", "驻机场航空单位或者航空公司的负责人", "驻机场航空单位或者航空公司的调度或签派"], ans: 1, exp: "根据《中华人民共和国飞行基本规则》的规定，飞行任务书是许可飞行人员进行转场 飞行和民用航空飞行的基本文件。飞行任务书由驻机场航空单位或者航空公司的负责人签发。" },
  { id: 194, cat: "法律法规", q: "飞行时间的含义是指（）", opts: ["自航空器开始起飞滑跑至着陆滑跑终止的时间", "从航空器起飞进入跑道至着陆脱离跑道的时间", "从航空器自装载地点开始滑行直到飞行结束到达卸载地点停止运动时为止的时间"], ans: 2, exp: "飞行时间的准确含义是从航空器自装载地点开始滑行直到飞行结束到达卸载地点停止 运动时为止的时间，这个时间段涵盖了起飞前的滑行、空中飞行以及着陆后的滑行等整个过 程。其他选项分析如下： 1、自航空器开始起飞滑跑至着陆滑跑终止的时间（错误：仅包含跑道滑行阶段，未涵盖完 整飞行过程） 2、从航空器起飞进入跑道至着陆脱离跑道的时间（错误：同样未包含全部飞行阶段）" },
  { id: 195, cat: "法律法规", q: "颁发国内三个层次航空法规的部门分别是：①全国人大或全国人大常委会；②国务院、中央军委；③民航局；④民航地区管理局。", opts: ["①②③", "①②④", "③④"], ans: 0, exp: "颁发国内三个层次航空法规的部门分别是： 1.全国人大或全国人大常委会：这是最高层次的航空法规颁发机构，负责制定和修订国家层 面的航空法规。 2.国务院、中央军委：这两个机构负责制定和颁布与航空相关的行政法规，对航空行业进行 管理和规范。 3.民航局：作为中国民用航空的主管部门，民航局负责制定和颁布与民用航空相关的法规和 规章，对民用航空活动进行管理和监督。" },
  { id: 196, cat: "法律法规", q: "参加理论考试或实践考试的申请人在参加考试前（）", opts: ["应当具有地面教员或飞行教员签注的已完成有关地面理论或飞行训练的证明", "应当具有地面教员和飞行教员推荐其参加考试的证明", "以上二者缺一不可"], ans: 2, exp: "参加理论考试或实践考试的申请人在参加考试前必须具有地面教员或飞行教员签注的 已完成有关地面理论或飞行训练的证明，同时，还应当具有地面教员和飞行教员推荐其参加 考试的证明，二者缺一不可。" },
  { id: 197, cat: "法律法规", q: "从事飞行的民用航空器不需要携带的文件是（）", opts: ["飞行人员相应的执照或合格证", "飞行记录簿", "民用航空器适航证书"], ans: 1, exp: "飞行必备执照证，适航证书不可少，记录簿非必带物。根据《中华人民共和国民用航 空法》的规定，从事飞行的民用航空器应当携带的文件包括民用航空器国籍登记证书、民用 航空器适航证书、机组人员相应的执照等。其中并未提及飞行记录簿作为必须携带的文件之 一。" },
  { id: 198, cat: "法律法规", q: "从事通用航空飞行活动的单位、个人违反本条例规定，在下列哪些情形下，由有关部门 按照职责分工责令改正，给予警告；情节严重的，处 2 万元以上 10 万元以下罚款，并可给 予责令停飞 1 个月至 3 个月、暂扣直至吊销经营许可证、飞行执照的处罚；造成重大事故或 者严重后果的，依照刑法关于重大飞行事故罪或者其他罪的规定，依法追究刑事责任：① 未经批准擅自飞行的；②未按批准的飞行计划飞行的；③不及时报告或者漏报飞行动态的； ④未经批准飞入空中限制区、空中危险区的。（）", opts: ["①②④", "①③④", "①②③④"], ans: 2, exp: "违规飞行四情形，警告罚款加处罚，严重后果追刑责。根据《通用航空飞行管制条例》 的规定，从事通用航空飞行活动的单位、个人违反本条例规定，有下列情形之一的，由有关 部门按照职责分工责令改正，给予警告；情节严重的，处 2 万元以上 10 万元以下罚款，并 可给予责令停飞 1 个月至 3 个月、暂扣直至吊销经营许可证、飞行执照的处罚；造成重大事 故或者严重后果的，依照刑法关于重大飞行事故罪或者其他罪的规定，依法追究刑事责任。 具体情形包括： 1.未经批准擅自飞行的； 2.未按批准的飞行计划飞行的； 3.不及时报告或者漏报飞行动态的； 4.未经批准飞入空中限制区、空中危险区的。" },
  { id: 199, cat: "法律法规", q: "当前使用的航空法是在哪一年修正的？（）", opts: ["2021 年 4 月 29 日", "2017 年 11 月 4 日", "2016 年 11 月 7 日"], ans: 0, exp: "2021 年 4 月 29 日，十三届全国人大常委会第二十八次会议表决通过了《全国人民代 表大会常务委员会关于修改〈中华人民共和国道路交通安全法〉等八部法律的决定》，对包 括《中华人民共和国民用航空法》在内的八部法律进行了修改。" },
  { id: 200, cat: "法律法规", q: "电子围栏，是指在特定地区周围划设的为保障特定地区安全的电子隔离装置，其功能包 括：①阻挡即将侵入该地区的航空器；②阻挡即将离开该地区的航空器；③报警功能。", opts: ["①②③", "①③", "①②"], ans: 1, exp: "电子围栏是一种智能化的安全设备，其主要功能包括阻挡即将侵入特定地区的航空器、报警功能等。电子围栏的功能主要包括： 1.阻挡即将侵入该地区的航空器。 2.报警功能，当有人入侵或破坏前端围栏时，系统会自动发出声、光报警，并可以与其他安 防系统联动。" },
  { id: 201, cat: "法律法规", q: "对飞行教员合格申请人的知识要求为（）", opts: ["教学原理，所申请飞行教员合格证航空器类别的警驶员、驾驶员机长合格证要求的航空 知识，及所申请飞行教员合格证等级要求的航空知识", "教学原理，所申请飞行教员合格证航空器类别的驾驶员、商用和航线驾驶员执照要求的 航空知识，及所申请飞行教员执照航空器类别的仪表等级要求的航空知识", "教学原理，所申请飞行教员执照航空器类别的私用、商用和航线驾驶员执照要求的航空 知识"], ans: 0, exp: "对飞行教员合格证申请人的知识要求包括教学原理，这是因为作为飞行教员需要掌握 正确的教学方法和理念，才能有效地传授知识和技能。同时，需要了解所申请行教员合格证 航空器类别的驾驶员、驾驶员机长合格证要求的航空知识，因为飞行教员要能够教授学员达 到相应的标准。 此外，还需掌握所申请飞行教员合格证等级要求的航空知识，以确保能够全面地指导学员在 不同等级的飞行训练中掌握所需知识。" },
  { id: 202, cat: "法律法规", q: "对于 Ⅰ、Ⅱ类无人机系统驾驶员（）", opts: ["人员资质由行业协会负责管理", "人员资质由局方负责管理", "无须证照管理，自行负责"], ans: 2, exp: "《民用无人机驾驶员管理规定》，对于Ⅰ、Ⅱ类无人机系统驾驶员的管理有明确的规定。 该规定指出，在下列情况下，无人机系统驾驶员自行负责，无须执照管理： 1.在室内运行的无人机。 2. Ⅰ、Ⅱ类无人机（分类等级见第 6 条 C 款。如运行需要，驾驶员可在无人机云交换系统进 行备案。备案内容应包括驾驶员真实身份信息、所使用的无人机型号，并通过在线法规测试）。" },
  { id: 203, cat: "法律法规", q: "对于接入无人机云系统的用户，必须：①向相关部门了解限制区域的划设情况，包括机 场障碍物控制面、飞行禁区、未经批准的限制区及危险区等；②机身需有明确的标识，注 明该无人机的型号、编号、所有者、联系方式等信息，以便出现坠机情况时能迅速查找到无 人机所有者或操作者信息；③运行前需要提前向管制部门提出申请，并提供有效监视手段； ④运营人按照 CCAR-91 部的要求，进行合格审定。（）", opts: ["①③④", "①②③", "①②③④"], ans: 2, exp: "对于接入无人机云系统的用户，必须遵守以下规定： ①：正确。了解限制区域的划设情况是确保飞行安全和合规的重要步骤。 ②：正确。机身标识有助于在发生事故时快速找到所有者或操作者。 ③：正确。提前向管制部门提出申请并提供有效监视手段，是确保飞行合规和安全的必要措 施。 ④：正确。按照 CCAR-91 部的要求进行合格审定，是确保运营人符合法规要求的重要环节。 因此，①②③④均正确。" },
  { id: 204, cat: "法律法规", q: "对于民用无人机运行的仪表、设备和标识要求中，用于记录、回放和分析飞行过程的飞 行数据记录系统，且数据信息至少保存（）", opts: ["一个月", "三个月", "半年"], ans: 1, exp: "《民用无人机运行的仪表、设备和飞行文件》规定，用于记录、回放和分析飞行过程 的飞行数据记录系统，且数据信息至少保存三个月（适用于Ⅲ、Ⅰ、Ⅳ、Ⅵ和Ⅴ类）。" },
  { id: 205, cat: "法律法规", q: "对于涉及酒精或药物的违禁行为，按照规定可以给予警告，暂扣执照或合格证（）或吊 销执照。", opts: ["3-6 个月", "1-6 个月", "1-3 个月"], ans: 1, exp: "无人机驾驶证考试中，涉及酒精或药物的违禁行为的处罚是一个重要的知识点。根据 中国民用航空局令（第 224 号）《民用航空器驾驶员和地面教员合格审定规则》（CCAR-61-R4）的规定，对于涉及酒精或药物的违禁行为，局方可以给予警告，暂扣执照或合格证 1 到 6 个月，并可给予责令停飞 1 个月至 3 个月、暂扣直至吊销经营许可证、飞行执照的处罚；造 成重大事故或者严重后果的，依照刑法关于重大飞行事故罪或其他罪的规定，依法追究刑事 责任。因此，正确答案是 1 到 6 个月。" },
  { id: 206, cat: "法律法规", q: "对于涉及酒精或药物的违禁行为处罚的人员，自其违禁行为发生之日起（）内，局方将 不接受该人员提出的任何按本规则颁发执照或等级的申请。", opts: ["半年", "一年", "两年"], ans: 1, exp: "这道题目考察的是涉及酒精或药物违禁行政处罚的人员，在违禁行为发生后多久内局 方将不接受其提出的任何按本规则颁发执照或等级的申请。 根据《民用航空人员体检合格证管理规则》（CCAR-67FS）的规定，涉及酒精或药物违禁行为 的人员，自其违禁行为发生之日起一年内，局方将不接受该人员提出的任何按本规则颁发执 照或等级的申请。" },
  { id: 207, cat: "法律法规", q: "对于无人机植保作业，运营人指定的一个或多个作业负责人有何要求？（）", opts: ["持有民用无人机驾驶员合格证并具有相应等级", "接受了相应理论知识及飞行技能的培训或具备相应的经验，并向局方或局方授权部门展 示了其能力", "以上都有"], ans: 2, exp: "根据民航局的规定，对于无人机植保作业，运营人指定的一个或多个作业负责人的要 求如下： 1.持有民用无人机驾驶员合格证并具有相应等级：这是确保作业负责人具备合法资质的基本 要求。 2.接受了相应理论知识及飞行技能的培训或具备相应的经验，并向局方或局方授权部门展示 了其能力：这是确保作业负责人具备实际操作能力和理论知识的重要条件。" },
  { id: 208, cat: "法律法规", q: "飞行的组织与实施包括（）", opts: ["飞行预先准备、飞行直接准备、飞行实施和飞行讲评四个阶段", "飞行直接准备、飞行实施和飞行讲评三个阶段", "飞行预先准备、飞行准备和飞行实施三个阶段"], ans: 0, exp: "这道题目考察的是飞行的组织与实施包含哪些阶段。飞行的组织与实施是一个完整的 流程，包括飞行预先准备、飞行直接准备、飞行实施和飞行讲评四个阶段。这四个阶段分别 对应飞行前的准备工作、飞行前的最后准备、实际飞行操作以及飞行结束后的总结和评估。" },
  { id: 209, cat: "法律法规", q: "飞行教员不需要在飞行教员记录本或单独文件中记录的内容为（）", opts: ["由该教员在飞行记录本或者在学生驾驶员执照上签字而被授予单飞权利的每个人的姓名，包括每次签字的日期以及所涉及的航空器型号", "教学的内容、课时，日期和航空器型号", "由该教员签字推荐参加理论考试或者实践考试的每个人的姓名，包括考试的种类，日期 和考试结果"], ans: 1, exp: "根据《民用航空器驾驶员和地面教员合格审定规则》第 61.209 条的规定，飞行教员 在飞行教员记录本或单独文件中必须记录的内容具体包括： 1.由该教员在飞行经历记录本或者在学生驾驶员执照上签字而被授予单飞权利的每个人的 姓名，记录应当包括每次签字的日期以及所涉及的航空器型号。 2.由该教员签字推荐参加理论考试或者实践考试的每个人的姓名，记录还应当包括考试的种 类、日期和考试结果。 因此（教学的内容、课时，日期和航空器型号）是正确的。" },
  { id: 210, cat: "法律法规", q: "飞行教员应当接受其飞行或地面教学的每个人的飞行经历记录本上签字，并注明（）", opts: ["教学的内容、课时和日期", "教学的内容、日期和机型", "教学的内容、课时、日期和机型"], ans: 0, exp: "根据《民用航空器驾驶员和飞行教员合格审定规则》的规定，飞行教员在接受其飞行 或地面教学的每个人的飞行经历记录本上签字时，需要注明提供教学的内容、课时和日期。 同时，飞行教员还需在飞行教员记录本或单独文件中记录其他特定内容，包括授予单飞权利 的每个人的姓名、签字的日期以及所涉及的航空器型号，以及推荐参加理论考试或实践考试 的每个人的姓名、考试的种类、日期和考试结果。" },
  { id: 211, cat: "法律法规", q: "飞行教员执照/合格证申请人必须年满（）", opts: ["18 周岁", "20 周岁", "21 周岁"], ans: 0, exp: "教员执照十八岁，飞行教学有保障。这道题目考察的是飞行教员执照/合格证申请人 必须年满的年龄要求。根据《民用航空器驾驶员和地面教员合格审定规则》（CCAR-61）的相 关规定，飞行教员执照/合格证申请人必须年满 18 周岁。" },
  { id: 212, cat: "法律法规", q: "飞行人员未按中华人民共和国基本规则规定履行职责的，由有关部门依法给予行政处分 或者纪律处分情节严重的，依法给予吊扣执照或合格证（）的处罚，或者责令停飞（）", opts: ["半年，一至三个月", "一至三个月，半年", "一至六个月，一至三个月"], ans: 2, exp: "根据《中华人民共和国飞行基本规则》，飞行人员未按规定履行职责的，相关部门将 依法给予行政处分或纪律处分。情节严重的，可能会面临吊扣执照一个月至六个月的处罚，或者责令停飞一个月至三个月的处罚。" },
  { id: 213, cat: "法律法规", q: "遥控器菜单中的 F/S 功能表示什么？（）", opts: ["失控反向", "失控保护", "航机行程量"], ans: 1, exp: "在遥控器菜单中，F/S 功能表示失控保护。失控保护功能可以在接收机接收不到信号 或接收机电压降到一定程度时，锁定或按照预设值让舵机保持在一个角度上。" },
  { id: 214, cat: "法律法规", q: "个人民用无人机拥有者在无人机实名登记系统中登记的信息包括（）", opts: ["驾驶员姓名，有效证件号码，联系方式", "拥有者姓名、有效证件号码、使用目的", "拥有者姓名、有效证件号码、工作单位、联系方式"], ans: 1, exp: "个人民用无人机拥有者在无人机实名登记系统中登记的信息包括： 1.拥有者姓名； 2.有效证件号码（如身份证号、护照号等）； 2.移动电话和电子邮箱； 4.产品型号、产品序号； 5.使用目的。 因此，（拥有者姓名、有效证件号码、使用目的）是正确的。" },
  { id: 215, cat: "法律法规", q: "关于“民用航空器国籍”正确的是（）", opts: ["民用航空器可以不进行国籍登记而投入运行", "民用航空器只能具有一国国籍", "自外国租赁的民用航空器不能申请我国国籍"], ans: 1, exp: "根据《中华人民共和国民用航空器国籍登记条例》的规定，民用航空器经依法登记，取得中华人民共和国国籍。同时，根据该条例第四条的规定，民用航空器不得具有双重国籍。 未注销外国国籍的民用航空器，不得在中华人民共和国办理国籍登记；未注销中华人民共和 国国籍的民用航空器，不得在外国办理国籍登记。" },
  { id: 216, cat: "法律法规", q: "关于通用航空的说法正确的是：①通用航空企业从事经营性通用航空活动，应当与用户 订立书面合同，但是紧急情况下的救灾飞行除外；②组织实施作业飞行时，应当采取有效 措施，保证飞行安全；③组织实施作业飞行时，保护环境和生态平衡，防止对环境、居民、作物或者牲畜等造成损害；④从事通用航空活动的，应当投保地面第三人责任险。（）", opts: ["①②③", "①②③④", "①②④"], ans: 1, exp: "根据《中华人民共和国民用航空法》的相关规定，我们可以得出以下结论： 1.通用航空企业从事经营性通用航空活动，应当与用户订立书面合同，但是紧急情况下的救 灾飞行除外。 2.组织实施作业飞行时，应当采取有效措施，保证飞行安全。 3.组织实施作业飞行时，保护环境和生态平衡，防止对环境、居民、作物或者牲畜等造成损 害。 4.从事通用航空活动的，应当投保地面第三人责任险。 因此，（①②③④）是正确的。" },
  { id: 217, cat: "法律法规", q: "何种无人机须安装使用电子围栏？（）", opts: ["Ⅲ、Ⅳ、Ⅵ、Ⅶ类无人机及在重点地区和机场净空区以下运行Ⅱ、Ⅴ类无人机", "Ⅱ、Ⅲ、Ⅰ、Ⅴ、Ⅵ、Ⅶ类无人机", "Ⅲ、Ⅰ、Ⅵ、Ⅶ类无人机"], ans: 0, exp: "依据《轻小无人机运行规定（试行）》第 14.1.1 条：对于Ⅲ、Ⅳ、Ⅵ和Ⅶ类无人机，应安装并使用电子围栏；对于在重点地区和机场净空区以下运行Ⅱ类和Ⅴ类无人机，应安装并使用电子围栏。其他选项要么范围过大要么范围过小。" },
  { id: 218, cat: "法律法规", q: "机场标高指着陆区（）的标高。", opts: ["最高点", "最低点", "平均海拔"], ans: 0, exp: "机场标高指的是机场跑道着陆区内最高点距离平均海平面（Meansealevel）的垂直距 离。" },
  { id: 219, cat: "法律法规", q: "监控系统获取民用无人机运行信息的方式包括（）", opts: ["两者都有", "被动反馈系统，是指航空器被雷达、ADS-B 系统、北斗等手段从地面进行监视的系统，该反馈信息不经过运营人", "主动反馈系统，是指运营人主动将航空器的运行信息发送给监视系统"], ans: 0, exp: "监视系统获取民用无人机运行信息的方式包括两种主要方式：被动反馈系统和主动反 馈系统。 1. 被动反馈系统：这是指航空器被雷达、ADS-B 系统、北斗等手段从地面进行监视的系统，该反馈信息不经过运营人。 2. 主动反馈系统：这是指运营人主动将航空器的运行信息发送给监视系统。" },
  { id: 220, cat: "法律法规", q: "接受转场飞行航空器降落的机场，必须在航空器到达机场（）以前，做好保障降落的各 项准备工作。", opts: ["30 分钟", "45 分钟", "1 小时"], ans: 0, exp: "降落准备，提前半小时。根据《民用航空器驾驶员和地面教员合格审定规则》的规定，接受转场飞行航空器降落的机场，必须在航空器到达机场 30 分钟以前，做好保障降落的各 项准备工作。" },
  { id: 221, cat: "法律法规", q: "每个飞行教员必须将 CCAR61 部要求的记录保存（）", opts: ["一年", "三年", "五年"], ans: 1, exp: "这道题目考察的是飞行教员根据 CCAR61 部（《民用航空器驾驶员和地面教员合格审 定规则》）需要保存记录的时间要求。根据 CCAR61 部的规定，飞行教员必须将相关的记录 至少保存三年。这一规定旨在确保飞行教员的活动和教学记录可以被追溯，以便于监管和审 计。" },
  { id: 222, cat: "法律法规", q: "民用航空飞行器实名认证规定什么时候修正？（）", opts: ["2017 年 5 月 16 日", "2015 年 12 月 29 日", "2017 年 1 月 1 日"], ans: 0, exp: "根据 2017 年 5 月 16 日民航局下发的《民用无人驾驶航空器实名制登记管理规定》，民用无人机的拥有者必须进行实名登记。这一规定是为了加强对无人机的管理，确保飞行安 全，防止无人机被用于非法活动。实名登记有助于追踪无人机的所有者，对于维护公共安全 和秩序具有重要意义。" },
  { id: 223, cat: "法律法规", q: "民用航空飞行器实名认证规定适用于什么飞机？（）", opts: ["最大起飞重量 250g（含 250g）", "最大起飞重量 250g（不含 250g）", "最大起飞重量 200g"], ans: 0, exp: "根据中国民航局发布的《民用无人驾驶航空器实名制登记管理规定》，实名认证规定 适用于在中华人民共和国境内最大起飞重量 250 克以上（含 250 克）的民用无人机。" },
  { id: 224, cat: "法律法规", q: "民用航空器必须具有民航局颁发的（）方可飞行", opts: ["适航证", "经营许可证", "机场使用许可证"], ans: 0, exp: "这道题目考察的是民用航空器进行飞行前必须持有的证件。根据《中华人民共和国民 用航空器适航管理条例》明确规定：“民用航空器必须具有民航局颁发的适航证，方可飞行。” 适航证是证明航空器符合适航标准，处于安全可用状态的官方文件。" },
  { id: 225, cat: "法律法规", q: "民用航空器的适航管理由（）负责", opts: ["民航局", "国务院", "中央军委"], ans: 0, exp: "中国民用航空局（CivilAviationAdministrationofChina，简称 CAAC）是中国负责民用 航空器适航管理的官方机构。适航管理是指对民用航空器的设计、制造、维护和运行等方面 进行监管，以确保航空器的安全性和可靠性。民航局通过制定适航标准和规定，对航空器进 行适航认证，以及对航空器的运行进行监督，从而保障民用航空的安全。" },
  { id: 226, cat: "法律法规", q: "民用航空适航管理是对哪几个方面进行管理？（）", opts: ["发动机、螺旋桨和航空器上的设备", "航空器、发动机、螺旋桨", "航空器、发动机"], ans: 0, exp: "这道题目考察的是民用航空适航管理的范围。根据相关规定，民用航空适航管理主要 是对发动机、螺旋桨及航空器上的设备进行管理，以确保其安全性和适航性。因此，正确答 案是“发动机、螺旋桨和航空器上的设备”。" },
  { id: 227, cat: "法律法规", q: "民用航空适航管理是对哪几个环节进行管理？（）", opts: ["设计、生产", "使用和维修", "设计、制造、使用和维修"], ans: 2, exp: "民用航空适航管理是对民用航空器从设计、制造、使用到维修的全过程进行管理。在 设计阶段确保航空器的设计符合安全标准；制造环节保证按照设计要求进行生产；使用过程 中监督航空器的运行安全；维修环节保障航空器持续处于适航状态。" },
  { id: 228, cat: "法律法规", q: "民用无人机超视距驾驶员的带飞时间不少于（）小时", opts: ["56", "15", "10"], ans: 1, exp: "民用无人机超视距驾驶员的带飞时间不少于 15 小时。这是为了确保超视距驾驶员在 实际操作中有足够的带飞训练，掌握超视距飞行的技能和安全要求。" },
  { id: 229, cat: "法律法规", q: "民用无人机驾驶申请人飞行时间不少于（）", opts: ["44 小时", "56 小时", "100 小时"], ans: 0, exp: "根据民用无人机驾驶员管理规定，视距内驾驶员合格证的申请人需要具有操纵有动力 的无人机至少 44 小时的飞行经历时间。这是为了确保驾驶员具备足够的操作经验和技能，以安全地操控无人机。" },
  { id: 230, cat: "法律法规", q: "《民用无人驾驶航空器实名登记管理规定》颁布于（）", opts: ["2015 年 12 月 29 日", "2017 年 7 月 1 日", "2017 年 5 月 16 日"], ans: 2, exp: "民用无人机实名登记系统由中国民航局于 2017 年 5 月 16 日正式颁布。为加强民用无 人驾驶航空器（以下简称民用无人机）的管理，民航局于 5 月 16 日下发《民用无人驾驶航 空器实名制登记管理规定》（以下简称《规定》），要求自 2017 年 6 月 1 日起，民用无人机的 拥有者必须进行实名登记。" },
  { id: 231, cat: "法律法规", q: "民用无人机用于农林喷洒作业时，以下哪些人员要求其持有民用无人机驾驶员合格证并 具有相应等级：①作业负责人；②独立喷洒作业人员；③作业高度在 15 米以上的作业人 员。（）", opts: ["①②③", "②③", "②"], ans: 0, exp: "在农林喷洒作业中，确保无人机的安全和有效运行是非常重要的。根据相关规定，作 业负责人、独立喷洒作业人员以及在较高作业高度（15 米以上）操作的人员都必须持有民 用无人机驾驶员合格证，并具有相应的等级。这样的要求是为了提高作业的安全性，确保操 作人员具备必要的技能和知识来安全地操控无人机，防止可能的事故和对环境或人员的伤害。" },
  { id: 232, cat: "法律法规", q: "民用无人驾驶航空器系统超视距驾驶员合格证申请人必须在民用无人驾驶航空器系统上 训练不少于多少小时的飞行训练时间？（）", opts: ["56", "44", "100"], ans: 0, exp: "民用无人驾驶航空器系统超视距驾驶员合格证对飞行训练时间有严格要求。申请人必 须在民用无人驾驶航空器系统上训练不少于 56 小时的飞行训练时间，这是为了确保超视距 驾驶员具备足够的操作技能和应对各种情况的能力。" },
  { id: 233, cat: "法律法规", q: "民用无人机驾驶航空器系统驾驶员合格证由哪个部门颁发？（）", opts: ["民航局下属司（局）", "中国航空器拥有者及驾驶员协会（中国 AOPA）", "地区管理局"], ans: 1, exp: "这道题目考察的是民用无人驾驶航空器系统驾驶员合格证的颁发部门。根据相关规定，中国航空器拥有者及驾驶员协会（中国 AOPA）负责颁发民用无人驾驶航空器系统驾驶员合 格证。该协会是经过国务院批准、民政部注册并由中国民用航空局主管的全国性协会，承担 无人机驾驶员的理论考试、实践飞行考试及合格证的颁发工作。" },
  { id: 234, cat: "法律法规", q: "民用无人驾驶航空器系统驾驶员执照由哪个部门颁发？（）", opts: ["民航局下属司（局）", "中国航空器拥有者及驾驶员协会（中国 AOPA）", "地区管理局"], ans: 0, exp: "民用无人驾驶航空器系统驾驶员执照是由民航局下属司（局）颁发。民航局对民用无 人驾驶航空器的管理具有权威性和专业性，负责制定相关的法规和标准，并对驾驶员进行资 格认证和管理。" },
  { id: 235, cat: "法律法规", q: "民用无人驾驶航空器系统视距内驾驶员合格证申请人必须在民用无人驾驶航空器系统上 训练不少于多少小时的飞行训练时间？（）", opts: ["56", "44", "100"], ans: 1, exp: "民用无人驾驶航空器系统视距内驾驶员合格证申请人必须在民用无人驾驶航空器系统 上训练不少于 44 小时的飞行训练时间。" },
  { id: 236, cat: "法律法规", q: "轻小型无人机运行规定试行颁布于（）", opts: ["2013 年 11 月 13 日", "2015 年 12 月 29 日", "2017 年 1 月 1 日"], ans: 1, exp: "《轻小型无人机运行规定（试行）》颁布于 2015 年 12 月 29 日。这个规定的出台是为 了规范轻小型无人机的运行，确保其在安全的前提下进行飞行活动。2015 年随着无人机技 术的快速发展和应用的日益广泛，为了加强对轻小型无人机的管理，保障公共安全，适时颁 布了该规定。" },
  { id: 237, cat: "法律法规", q: "任何单位或者个人设计民用航空器，应当向民航局申请（）", opts: ["适航证", "生产许可证", "型号合格证"], ans: 2, exp: "任何单位或者个人设计民用航空器，应当向民航局申请型号合格证。型号合格证是民 用航空器设计符合适航标准的重要凭证，确保航空器在设计阶段满足安全等各项要求。" },
  { id: 238, cat: "法律法规", q: "任何单位或者个人未取得（），均不得生产民用航空器", opts: ["适航证", "生产许可证", "型号合格证"], ans: 1, exp: "任何单位或者个人未取得生产许可证，均不得生产民用航空器。生产许可证是对民用 航空器生产单位的资质认证，确保生产过程符合相关标准和规范，保障民用航空器的质量和 安全性。" },
  { id: 239, cat: "法律法规", q: "如观察到其他飞机的灯光是右红左绿，应将该机判断为（）", opts: ["没有发生相撞的可能", "与自己顺向飞行", "与自己相向飞行"], ans: 2, exp: "航空器右红左绿灯光表示其左侧朝向观察者。当看到此灯光组合时，说明对方飞机正 朝你迎面飞来，存在相向飞行碰撞风险。" },
  { id: 240, cat: "法律法规", q: "谁对机组成员遵守飞行基本规则负责？（）", opts: ["航空单位负责人", "机长", "民航局及其地区管理局"], ans: 1, exp: "机长是航空器内的最高指挥者，在飞行过程中拥有最高权力和责任。机长负责整个飞 行任务的安全和顺利进行，这包括确保机组成员遵守飞行基本规则。" },
  { id: 241, cat: "法律法规", q: "实施农林喷洒作业的运营人应当在其主运行基地保存关于下列内容的记录：①服务对象 的名称和地址；②服务日期；③每次作业飞行所喷洒物质的数量和名称；④作业飞行任务 的驾驶员的姓名，地址和执照编号，以及按照管理规定的作业负责人通过知识和技术检查的 记录。", opts: ["②③④", "①②④", "①②③④"], ans: 2, exp: "实施农林喷洒作业的运营人应当在其主运行基地保存关于服务对象的名称和地址、服 务日期、每次作业飞行所喷洒物质的数量和名称、作业飞行任务的驾驶员的姓名，地址和执 照编号，以及按照管理规定的作业负责人通过知识和技术检查的记录。" },
  { id: 242, cat: "法律法规", q: "视距外运行使用自主模式的无人机，无人机驾驶员必须能够随时介入操控。出现无人机 失控的情况，机长应该执行相应的预案，包括：①无人机应急回收程序；②对于接入无人 机云的用户，应在系统内上报相关情况；③对于未接入无人机云的用户，联系相关空管服 务部门的程序，上报遵照以上程序的相关责任人名单。", opts: ["①②③", "②③", "①③"], ans: 0, exp: "这道题目考察的是视距外运行使用自主模式的无人机在出现失控情况时，无人机驾驶 员应执行的预案。当无人机失控时，机长应执行的预案包括：①无人机应急回收程序；②对 于接入无人机云的用户，应在系统内上报相关情况；③对于未接入无人机云的用户，联系相 关空管服务部门的程序。" },
  { id: 243, cat: "法律法规", q: "伪造、复制或篡改执照或合格证的行为，局方或授权方可视其情节轻重，给予警告、暂 扣执照或合格证（）或吊销执照或合格证的处罚。", opts: ["1 到 6 个月", "1 到 3 个月", "3 到 6 个月"], ans: 0, exp: "这道题目考察的是伪造、复制或篡改执照或合格证行为的处罚规定。根据《民用航空 器驾驶员和地面教员合格审定规则》（CCAR-61）及相关民航法规，对于此类违规行为，局方 或授权方可视其情节轻重，给予警告、暂扣执照或合格证 1 到 6 个月或吊销执照或合格证的 处罚。" },
  { id: 244, cat: "法律法规", q: "我国民航飞行使用的时间为（）", opts: ["当地的地方时", "北京时", "世界协调时"], ans: 2, exp: "我国民航飞行使用的时间为世界协调时（UTC）。这是因为民航是一个高度国际化的 行业，其飞机的飞行轨迹遍布全球，使用统一的时间标准可以确保不同国家和地区的民航部 门、机场、航空公司以及飞行员之间能够拥有统一的时间标准，这对于飞行安全和运行效率 至关重要。" },
  { id: 245, cat: "法律法规", q: "无人机飞行人员在执行飞行任务时，应当随身携带（）", opts: ["飞行记录本", "飞机适航证书", "驾驶员执照或合格证"], ans: 2, exp: "飞手任务带证飞。在执行飞行任务时，无人机飞行人员必须携带证明其资质的执照或 合格证，以确保飞行的合法性和安全性。根据《民用无人驾驶航空器运行安全管理规则》中 的规定，操控小型、中型、大型民用无人驾驶航空器飞行的人员，应当取得局方规定的相应 有效操控员执照，并且在行使相应权利时随身携带该执照。" },
  { id: 246, cat: "法律法规", q: "无人机视距内、超视距飞行执照/合格证申请人必须年满（）", opts: ["16 周岁", "18 周岁", "20 周岁"], ans: 0, exp: "根据中国民用航空局的规定，无人机驾驶员申请执照或合格证时必须满足一定的年龄 条件，以确保其具备相应的认知和操作能力。对于无人机视距内/超视距飞行执照/合格证的 申请人，必须年满 16 周岁。" },
  { id: 247, cat: "法律法规", q: "无人机系统（无人机云），是指轻小型民用无人机动态数据库系统，用于：①提供航行 服务，气象服务；②对民用无人机运行数据（包括运营信息，位置，高度和速度等）进行 实时检测；③对侵入电子围栏的无人机具有报警功能。（）", opts: ["①③", "②③", "①②③"], ans: 2, exp: "无人机系统（无人机云）作为轻小型民用无人机动态数据库系统，其作用包括提供航 行服务和气象服务，对民用无人机运行数据进行实时检测，如运营信息、位置、高度和速度 等，同时对侵入电子围栏的无人机具有报警功能。" },
  { id: 248, cat: "法律法规", q: "无人机系统的超视距驾驶员（机长）是指（）", opts: ["协助操控无人机的人", "操控无人机的人", "负责整个无人机系统运行和安全的驾驶员"], ans: 2, exp: "无人机系统的超视距驾驶员（机长）是负责整个无人机系统运行和安全的驾驶员。超 视距飞行意味着驾驶员无法通过肉眼直接观察到无人机，需要借助其他设备如地面站等进行 操控和监视。机长要对无人机的起飞、飞行、降落等整个过程负责，确保飞行安全，包括监 控无人机的状态、应对各种突发情况、遵守航空法规等。" },
  { id: 249, cat: "法律法规", q: "无人机云系统（无人机云），是指轻小型民用无人机动态数据库系统，用于：①提供航 行服务；②提供气象服务；③对民用无人机飞行数据实时监测。（）", opts: ["①③", "②③", "①②③"], ans: 2, exp: "无人机云系统作为轻小型民用无人机动态数据库系统，其主要功能包括提供航行服务，帮助无人机规划合理航线等；提供气象服务，使无人机飞行能更好地应对不同气象条件；对 民用无人机飞行数据实时监测，包括位置、高度、速度等飞行数据，以确保飞行安全和规范 管理。" },
  { id: 250, cat: "法律法规", q: "下列航空法律法规中级别最高的是（）", opts: ["《中华人民共和国飞行基本规则》", "《中华人民共和国民用航空法》", "《中华人民共和国搜寻援救民用航空器规定》"], ans: 1, exp: "在这些航空法律法规中，《中华人民共和国民用航空法》级别最高。《中华人民共和国 民用航空法》是国家为了维护国家的领空主权和民用航空权利，保障民用航空活动安全和有 秩序地进行，保护民用航空活动当事人各方的合法权益，促进民用航空事业的发展而制定的 法律，具有较高的法律效力和权威性。" },
  { id: 251, cat: "法律法规", q: "下列说法正确的是（）", opts: ["飞行教员不得为获得 CCAR61 部要求的执照、合格证、等级、运行许可、实践考试或者 理论考试权利而为自己进行任何签字", "除非具有局方委任的监察员或考试员资格，否则飞行教员不得为获得 CCAR61 部要求的 执照、合格证、等级、运行许可、实践考试或者理论考试权利而为自己进行任何签字", "当存在特殊的情况或条件限制时，在获得特别授权和批准后，飞行教员可以为获得 CCAR61 部要求的执照、合格证、等级、运行许可、实践考试或者理论考试权利而为自己进 行签字"], ans: 0, exp: "飞行教员不得获得 CCAR61 部要求的执照、合格证、等级、运行许可、实践考试或者 理论考试权利而为自己进行任何签字，这是为了确保考试和执照颁发的公正性和客观性。" },
  { id: 252, cat: "法律法规", q: "下列说法中，哪一种对无人机教员等级申请人的要求是必要的？（）", opts: ["具备无人机应急处理程序方面的技术", "在所申请的无人机上担任机长经历时间不少于 100 小时", "在所申请的无人机上飞行经历不少于 100 小时"], ans: 1, exp: "在所申请的无人机上担任机长经历时间多于 100 小时是对无人机教员合格证申请人的 必要要求之一，只有具备一定的机长经历，才能更好地指导学员。" },
  { id: 253, cat: "法律法规", q: "旋翼类无人机单飞时间不少于多少？", opts: ["5 小时", "10 小时", "15 小时"], ans: 0, exp: "对于旋翼类无人机，单飞时间不少于 5 小时。这是因为在一定的飞行小时数要求下，可以确保飞行员有足够的实际操作经验来应对各种飞行情况。5 小时的单飞时间能够让飞行 员在不同的气象条件、飞行环境中进行实践，熟悉无人机的操控性能、特点以及可能出现的 问题和应对方法。" },
  { id: 254, cat: "法律法规", q: "学生驾驶员在单飞之前必须在其飞行经历记录本上，有授权教员的签字，证明其在单飞 日期之前（）天内接受了所飞型号航空器的训练。", opts: ["90", "60", "30"], ans: 0, exp: "学生驾驶员在单飞之前必须确保其飞行经历记录本上有授权教员的签字，并且该签字 必须在单飞日期之前的 90 天内完成。根据《民用航空驾驶员和教员合格审定规则》的规定，飞行教员方可在飞行学员的飞行经历记录本上签字批准单飞，且该批准的有效期为 90 天。" },
  { id: 255, cat: "法律法规", q: "学员单飞前必须达到的要求是：①通过由授权教员实施的理论考试；②接受并记录了 单飞所用航空器的适用动作与程序的飞行训练；③经授权教员在该型号或类似航空器上检 查，认为该驾驶员熟练掌握了这些动作与程序。（）", opts: ["①②③", "①③", "②③"], ans: 0, exp: "根据《民用航空器驾驶员和地面教员合格审定规则》［第 224 号］，学员在单飞前必须 满足以下条件：①通过由授权教员实施的理论考试；②接受并记录了单飞所用航空器的适用 动作与程序的飞行训练；③经授权教员在该型号或类似航空器上检查，认为该驾驶员熟练掌 握了这些动作与程序。这些要求确保了学员在单飞时具备足够的知识和技能，以保证飞行安 全。" },
  { id: 256, cat: "法律法规", q: "训练时间，是指受训人在下列哪方面从授权教员处接受训练的时间？（）", opts: ["飞行中", "地面上、飞行模拟机或飞行训练器上", "飞行中、地面上、飞行模拟机或飞行练习器上"], ans: 2, exp: "这道题目考察的是训练时间的定义，即受训人从授权教员处接受训练的时间范围。根 据《民用航空器驾驶员和地面教员合格审定规则》（CCAR-61），训练时间包括在飞行中、地 面上、飞行模拟机或飞行训练器上的时间。这涵盖了理论知识学习、实际操作训练以及模拟 飞行等多种训练形式，确保受训人能够全面掌握所需的飞行技能和知识。" },
  { id: 257, cat: "法律法规", q: "依法取得中华人民共和国国籍的民用航空器，应当标明规定的国籍标志和（）", opts: ["公司标志", "登记标志", "机型标志"], ans: 1, exp: "根据《民用航空器国籍登记规定》，依法取得中华人民共和国国籍的民用航空器，应 当标明规定的国籍标志和登记标志。" },
  { id: 258, cat: "法律法规", q: "由授权教员签字批准单飞后的学员，单飞训练时间在其飞行经历记录本上应体现（）", opts: ["单飞时间", "机长时间", "副驾驶时间"], ans: 0, exp: "由授权教员签字批准单飞后的学员，单飞训练时间在其飞行经历记录本上应体现为单 飞时间。单飞时间能够准确地反映学员在独立操控航空器阶段的飞行经验积累，这对于评估 学员的飞行技能发展、判断其是否达到后续更高等级的飞行要求等都有着重要的意义。" },
  { id: 259, cat: "法律法规", q: "由授权教员为学员提供的带飞训练，学员飞行经历记录本上应体现为（）", opts: ["副驾驶时间", "带飞时间", "机长时间"], ans: 1, exp: "学员在航空器、飞行模拟机、飞行训练器或其他经批准训练设备上接受授权教员的飞 行训练的时间应记作飞行训练时间，包括科目和时长，该时间应当有实施训练的授权教员签 字证明。因此，由授权教员为学员提供的带飞训练，在学员飞行经历记录本上应体现“带飞 时间”。" },
  { id: 260, cat: "法律法规", q: "在飞行任务中，应当明确（）", opts: ["飞行任务、起飞时间、航线、高度、允许机长飞行的最低气象条件以及其他有关事项", "飞行任务、机组成员、起飞时间、航线、高度、允许机长飞行的最低气象条件以及其他 有关事项", "飞行任务、起飞时间、航线、允许机长飞行的最低气象条件以及其他有关事项"], ans: 0, exp: "在飞行任务中，应当明确以下内容： 1.飞行任务：明确飞行的具体任务和目标。 2.起飞时间：确定飞行的起始时间。 3.航线：规划飞行的具体路线。 4.高度：设定飞行的最高和最低高度限制。 5.允许机长飞行的最低气象条件：包括无雷暴、云底最低高度、降雨量、地面风速和高空风 速等条件。 6.其他有关事项：包括飞行过程中的特殊要求或注意事项。" },
  { id: 261, cat: "法律法规", q: "在人口稠密区上空进行农林喷洒作业飞行应当符合：①取得作业飞行区域的政府部门的 书面批准；②向对作业区域有管辖权的地方飞行标准部门递交完整的作业飞行计划并取得 批准；③通过有效的方式向公众发出作业通知。（）", opts: ["①②", "②③", "①②③"], ans: 2, exp: "人口稠密区作业，政府批准、飞标批准加通知。 根据《农林喷洒作业飞行运行规则-CAAC》的相关内容，进行农林喷洒作业飞行应当符合以 下条件：①取得作业飞行区域的政府部门的书面批准；②向对作业区域有管辖权的地方飞行 标准部门递交完整的作业飞行计划并取得批准；③通过有效的方式向公众发出作业通知。" },
  { id: 262, cat: "法律法规", q: "在什么条件下飞行教员方可在学生驾驶员飞行经历记录本上签字，批准其单飞？（）", opts: ["亲自或委托具备飞行教员资格和权限的飞行教员对该学生驾驶员提供了本规则授予单飞 权利所要求的飞行训练，确认该学生驾驶员能够遵守飞行教员出于安全考虑而在飞行经历记 录本上作出的任何限制，已经做好准备能够安全实施单飞", "亲自对该学生驾驶员提供了本规则授予单飞权利所要求的飞行训练，确认该学生驾驶员 能够遵守飞行教员出于安全考虑而在飞行经历记录本上作出的任何限制，已经做好准备能够 安全实施单飞", "亲自或委托具备飞行教员资格和权限的飞行教员对该学生驾驶员提供了本规则授予单飞 权利所要求的飞行训练，确认该学生驾驶员能够遵守飞行教员出于安全考虑而在飞行经历记 录本上作出的任何限制，已经做好准备能够安全实施单飞同时需得到检查教员的认可和批准"], ans: 1, exp: "根据《民用航空器驾驶员和地面教员合格审定规则》的规定，飞行教员在满足以下条 件后，方可在学生驾驶员执照或飞行经历记录本上签字，批准其单飞：（1）亲自对该学生驾 驶员提供了本规则授予单飞权利所要求的飞行训练；（2）确认该学生驾驶员能够遵守飞行教 员出于安全考虑而在飞行经历记录本上作出的任何限制，已经做好准备能够安全实施单飞。" },
  { id: 263, cat: "法律法规", q: "在遇到特殊情况，民用航空器的超视距驾驶员（机长），为保证民用航空器及其人员的安 全（）", opts: ["应当及时向管制单位报告，按照相关规定进行正确处置", "应当及时向签派或上级领导报告，按照相关规定进行正确处置", "有权对航空器进行处置"], ans: 2, exp: "根据《中华人民共和国飞行基本规则》的规定，飞行人员在飞行中必须服从指挥，严 格遵守纪律和操作规程，正确处置空中情况。遇到特殊情况，民用航空器的机长，为保证民 用航空器及其所载人员的安全，有权对民用航空器作出处置。" },
  { id: 264, cat: "法律法规", q: "中华人民共和国境内的飞行管制，（）", opts: ["由中国人民解放军空军统一组织实施，各有关飞行管制部门按照各自的职责分工提供空 中交通管制服务", "由国务院、中央军委空中交通管制委员会统一组织实施，各有关飞行管制部门按照各自 的职责分工提供空中交通管制服务", "由中国民用航空总局空中交通管理局统一组织实施，各有关飞行管制部门按照各自的职 责分工提供空中交通管制服务"], ans: 0, exp: "在中华人民共和国境内，飞行管制由中国人民解放军空军统一组织实施。空军作为国 家空中力量的主体，具备专业的空中管制能力和丰富的经验，能够从国防安全和空域整体规 划的高度对飞行活动进行统一管控。各有关飞行管制部门按照各自的职责分工提供空中交通 管制服务，这体现了我国飞行管制工作的协同性。" },
  { id: 265, cat: "法律法规", q: "转场航空器超过预定起飞时间（）仍未起飞，又未申请延期的，其原飞申请失效", opts: ["半小时", "一小时", "两小时"], ans: 1, exp: "在航空飞行管理中，为了确保飞行计划的有效性和空中交通的顺畅，对于转场航空器 有一个明确的时间规定。如果转场航空器在预定的起飞时间后超过一小时仍未能起飞，并且 没有提前申请延期，那么原先提交的飞行申请将被视为失效。" },
  { id: 266, cat: "法律法规", q: "最新颁布的中华人民共和国飞行基本规则从（）实施", opts: ["2001 年 8 月 1 日零时起施行", "2001 年 6 月 1 日零时起施行", "2001 年 10 月 1 日零时起施行"], ans: 0, exp: "《中华人民共和国飞行基本规则》是为了维护国家领空主权，规范境内飞行活动，保 障飞行活动安全有序进行而制定的法规。该规则由国务院和中央军事委员会共同发布，并于 2001 年 8 月 1 日零时起正式施行，取代了 1977 年 4 月 21 日颁发的旧日版规则。" },
  { id: 267, cat: "法律法规", q: "超视距考取教员执照时，在获得机长执照后飞行时间不少于（）", opts: ["100 小时", "44 小时", "56 小时"], ans: 0, exp: "题目考查的是超视距（机长）驾驶员考取教员执照的飞行小时要求。根据相关规定，超视距驾驶员在获得机长执照后，需要满足不少于 100 小时的飞行经历，才能申请教员执照。" },
  { id: 268, cat: "法律法规", q: "下列哪类固定翼无人机不能手抛起飞？（）", opts: ["2 类", "4 类", "6 类"], ans: 1, exp: "固定翼无人机的手抛起飞方式通常适用于小型、轻型无人机，这类无人机的尺寸和重 量相对较小，适合通过手抛的方式起飞。对于 4 类无人机，其起全重在 25kg 到 150kg 之间。 由于其重量较大，手抛起飞的方式并不适用，因此 4 类固定翼无人机不能通过手抛方式起飞。" },
  { id: 269, cat: "法律法规", q: "飞行教员等级申请人必须年满（）", opts: ["18 周岁", "20 周岁", "21 周岁"], ans: 0, exp: "题目考查的是飞行教员等级申请人的年龄要求。根据相关规定，飞行教员等级申请人 必须年满 18 周岁。这是申请飞行教员等级的最低年龄要求。" },
  { id: 270, cat: "法律法规", q: "对于多旋翼类别超视距等级驾驶员执照申请人，由授权教员提供不少于（）小时带飞训 练，不少于（）小时单飞训练。", opts: ["10,5", "15,10", "15,5"], ans: 2, exp: "根据《民用无人机驾驶员管理规定》和相关培训标准，对于多旋翼类别超视距等级驾 驶员执照申请人，须具备至少 56 小时的有动力无人机飞行经历，其中由授权教员提供的带 飞训练时间不少于 15 小时，单飞训练时间不少于 5 小时。计入驾驶员飞行经历的模拟训练 时间不得超过 28 小时。" },
  { id: 271, cat: "法律法规", q: "对于多旋翼类别视距内等级驾驶员执照申请人，由授 权教员提供不少于（）小时带飞训 练，不少于（）小时单飞训练。", opts: ["10,5", "15,10", "15,5"], ans: 0, exp: "根据《民用无人机驾驶员管理规定》和相关培训标准，对于多旋翼类别视距内等级驾 驶员执照申请人，须具备至少 44 小时的有动力无人机飞行经历，其中由授权教员提供的带 飞训练时间不少于 10 小时，单飞训练时间不少于 5 小时。计入驾驶员飞行经历的模拟训练 时间不得超过 22 小时。" },
  { id: 272, cat: "法律法规", q: "下列情况下，无人机系统驾驶员不实施管理的是（）", opts: ["在融合空域运行的Ⅰ类无人机", "超视距运行的Ⅰ类无人机", "视距内运行的Ⅱ类无人机"], ans: 2, exp: "在视距内运行的Ⅱ类无人机因风险较小，其驾驶员无需接受专门管理。根据《民用无 人驾驶航空器运行安全管理规则》，视距内运行的Ⅱ类无人机在驾驶员直接目视范围内操作，风险较低，因此不需要驾驶员执照。" },
  { id: 273, cat: "法律法规", q: "关于对地摄像（）", opts: ["想拍就拍", "不能拍摄", "按照国家规定经批准后方可进行"], ans: 2, exp: "对地摄像涉及隐私、安全和国家利益，因此需要严格遵守国家相关规定。未经批准擅 自进行对地摄像可能会违反法律法规，甚至引发安全问题。 因此，必须经过相关部门批准后方可进行。" },
  { id: 274, cat: "法律法规", q: "昼间飞行的含义是指（）", opts: ["从日出到日落之间的飞行", "从天黑到天亮之间的飞行", "从天亮到日落之间的飞行"], ans: 0, exp: "昼间飞行的含义是指从日出到日落之间的飞行。 根据中国民用航空规章 CCAR-91 部《一般运行和飞行规则》第 91.1311 条，昼间运行特指超 轻型飞行器在日出至日落期间的运行。" },
  { id: 275, cat: "法律法规", q: "夜间飞行的含义是指（）", opts: ["从天黑到日出之间的飞行", "从天黑到天亮之间的飞行", "从日落到日出之间的飞行"], ans: 2, exp: "夜间飞行的含义是指从日落到日出之间的飞行。 根据中国民用航空规章 CCAR-91 部《一般运行和飞行规则》第 91.1311 条，夜间运行特指超 轻型飞行器在日落至次日日出期间的运行。" },
  { id: 276, cat: "法律法规", q: "无人机使用中特别强调防止邮箱通气管堵塞，主要因为其堵塞时（）", opts: ["影响燃油气化", "无法加油", "影响空中供油"], ans: 2, exp: "油箱通气管的主要作用是平衡油箱内外的气压，确保燃油能够顺利地供应到发动机。 如果通气管堵塞，油箱内的气压无法正常调节，可能会导致燃油无法顺利流出，从而影响空 中供油。" },
  { id: 277, cat: "法律法规", q: "无人机地面加油时，必须在场的人员之一是（）", opts: ["无人机飞行员", "地面消防员", "手拿传呼机的指挥员"], ans: 1, exp: "在无人机地面加油过程中，存在一定的火灾风险。地面消防员在场可以及时应对可能 出现的意外情况，如燃油泄漏引发的火灾等，能够迅速采取灭火和救援措施，确保加油过程 的安全。根据《民用无人机加油操作规范》（CCAR-92-R1），加油现场必须配备持证消防员，以应对燃油泄漏、火灾或爆炸等突发情况。" },
  { id: 278, cat: "法律法规", q: "每天飞行结束后，应将燃油油箱加满油，其目的是（）", opts: ["尽量减少水汽进入油箱，避免油污染", "便于第二天尽快飞行", "防止油箱结冰"], ans: 0, exp: "每天飞行结束后将燃油油箱加满油，主要是为了减少油箱内的空气空间，从而降低水 汽凝结和燃油污染的风险。" },
  { id: 279, cat: "法律法规", q: "飞机地面加油前必须检查飞机塔地线是否接地，主要是（）", opts: ["使用飞机用电设备接地", "防止静电起火", "防止加油时遭雷击"], ans: 1, exp: "飞机在地面加油时，由于燃油流动和空气摩擦会产生静电。如果不将静电及时导出，积累的静电可能会产生电火花，从而引发燃油起火甚至爆炸等危险情况。因此，飞机地面加 油前必须检查飞机塔地线是否接地，主要是为了防止放电起火。" },
  { id: 280, cat: "法律法规", q: "民用无人机驾驶员多旋翼类别视距内等级申请人必须具有不少于多少小时的单飞训练时 间（）", opts: ["5", "6", "10"], ans: 0, exp: "根据《民用无人机驾驶员管理规定》（AC-61-FS-2018-20R2），民用无人机驾驶员多旋 翼类别视距内等级申请人必须具有不少于 5 小时的单飞训练时间。" },
  { id: 281, cat: "法律法规", q: "民用无人机驾驶员多旋翼类别超视距等级申请人必须具有不少于多少小时的带飞训练时 间（）", opts: ["10", "15", "56"], ans: 1, exp: "根据《民用无人机驾驶员管理规定》（AC-61-FS-2018-20R2），民用无人机驾驶员多旋 翼类别超视距等级申请人必须具有不少于 15 小时的带飞训练时间。" },
  { id: 282, cat: "法律法规", q: "民用无人机驾驶员多旋翼类别超视距等级申请人必须具有不少于多少小时的单飞训练时 间（）", opts: ["5", "6", "15"], ans: 0, exp: "根据《民用无人机驾驶员管理规定》（AC-61-FS-2018-20R2），民用无人机驾驶员多旋 翼类别超视距等级申请人必须具有不少于 5 小时的单飞训练时间。" },
  { id: 283, cat: "法律法规", q: "民用无人机驾驶员多旋翼类别视距内等级申请人必须具有不少于多少小时的带飞训练时 间（）", opts: ["44", "15", "10"], ans: 2, exp: "根据《民用无人机驾驶员管理规定》（AC-61-FS-2018-20R2），民用无人机驾驶员多旋 翼类别视距内等级申请人必须具有不少于 10 小时的带飞训练时间。" },
  { id: 284, cat: "法律法规", q: "禁止航空器着陆的辅助指挥符号是（）", opts: ["昼间在着陆地带铺设 T 字布，夜间 T 字灯", "昼间在着陆地带铺设一形灯，夜间铺设一形灯", "在着陆地带昼间铺设十字布，夜间铺设十字灯"], ans: 2, exp: "根据《民用无人机驾驶员管理规定》（AC-61-FS-2018-20R2）以及相关航空管理规定，禁止航空器着陆的辅助指挥符号是：在着陆地带昼间铺设“十”字布，夜间铺设“十”字灯。" },
  { id: 285, cat: "法律法规", q: "下列属于无人机机长训练要求的是（）", opts: ["在模拟器实施应急飞行程序指挥，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 2 小时", "在模拟器实施正常飞行程序操作，不少于 2 小时", "实物训练系统实施正常飞行程序操作，不少于 5 小时"], ans: 0, exp: "无人机机长需要具备处理各种紧急情况的能力，因此应急飞行程序的训练是机长训练 的重要组成部分。 其他选项分析如下： 1、在模拟器实施正常飞行程序操作，不少于 2 小时：错误。虽然正常飞行程序操作是必要 的训练内容，但题目中强调的是机长训练要求，应急飞行程序指挥更为关键。 2、实物训练系统实施正常飞行程序操作，不少于 5 小时：错误。同样，虽然实物训练系统 中的正常飞行程序操作是必要的，但题目中强调的是机长训练要求，应急飞行程序指挥更为 关键。" },
  { id: 286, cat: "法律法规", q: "下列不属于无人机驾驶员训练要求的是（）", opts: ["在模拟器实施应急飞行程序操作，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 2 小时", "在模拟器实施正常飞行程序，不少于 2 小时", "实物训练系统实施正常飞行程序操作，不少于 5 小时"], ans: 0, exp: "应急飞行程序操作训练是无人机“机长”的特殊训练要求，普通驾驶员训练大纲不强 制要求此类高难度应急训练。 因此，在模拟器实施应急飞行程序操作，包括规避航空器，发动机故障，链路丢失，应急回 收，迫降等，不少于 2 小时不属于无人机驾驶员训练要求。" },
  { id: 287, cat: "法律法规", q: "下列不属于无人机驾驶员训练要求的是（）", opts: ["在模拟器实施行前检查，不少于 1 小时", "在模拟器实施正常运行程序，不少于 2 小时", "在模拟器实施应急飞行程序操作，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 5 小时"], ans: 2, exp: "根据《民用无人驾驶航空器系统驾驶员管理暂行规定》，无人机驾驶员的训练要求中，应急飞行程序操作的训练时间不少于 2 小时，而不是 5 小时。" },
  { id: 288, cat: "法律法规", q: "（）是指由于无人机飞行转弯形成的弧度将受到自身飞行性能限制，它限制无人机只能 在特定的转弯半径范围内转弯。", opts: ["最大俯仰角", "最大转弯半径", "最小转弯半径"], ans: 2, exp: "最小转弯半径是指由于无人机飞行转弯形成的弧度将受到自身飞行性能限制，它限制 无人机只能在特定的转弯半径内转弯。" },
  // ==================== 飞行手册 ====================
  { id: 289, cat: "飞行手册", q: "1:50 万航图，图上 1cm 相当于地面长（）", opts: ["0.5 公里", "5 公里", "50 公里"], ans: 1, exp: "比例尺算距，五十万除厘。1:50 万航图意味着地图上的 1 单位长度代表实际地面上 的 50 万单位长度。如果地图上的单位是厘米，那么 1 厘米就代表地面上的 50 万厘米。由于 1 公里等于 10 万厘米，所以 50 万厘米等于 5 公里。因此，图上 1 厘米相当于地面长 5 公里。" },
  { id: 290, cat: "飞行手册", q: "1 海里相当于多少公里？（）", opts: ["1.85 公里", "1.15 公里", "1.61 公里"], ans: 0, exp: "1 海里是航海中常用的长度单位，它等于 1.852 公里（或者 1.8520 千米）。这个单位 起源于地球的周长，由于地球的极半径和赤道半径不同，海里的定义经过了多次修订，但目 前国际上通用的是 1 海里等于 1.852 公里。" },
  { id: 291, cat: "飞行手册", q: "北极的纬度是（）", opts: ["北纬 180°", "北纬 90°", "北纬 0°"], ans: 1, exp: "北极是地球上最北的点，其纬度为北纬 90°。纬度是用来表示地球表面上某一点与 赤道之间的角度距离，赤道的纬度 0°，北极和南极的纬度分别为北纬 90°和南纬 90°。" },
  { id: 292, cat: "飞行手册", q: "超低空飞行，按照飞行高度区分为（）", opts: ["距地面或水面 50 米以下", "距地面或水面 100 米以下", "距地面或水面 5-100 米"], ans: 1, exp: "超低空飞行通常指的是飞行器在距离地面或水面 100 米以下的高度进行飞行。这个高 度范围允许飞行器进行更加贴近地面的飞行任务，例如地形测绘、农业喷洒等。因此，按照 飞行高度区分，超低空飞行是指距地面或水面 100 米以下的飞行。" },
  { id: 293, cat: "飞行手册", q: "当给大型无人机加油时，为预防静电带来的危害应注意（）", opts: ["检查电瓶和点火电门是否关断", "油车是否接地", "将飞机、加油车和加油枪用连线接地"], ans: 2, exp: "在给大型无人机加油时，为预防静电带来的危害，非常重要的一项安全措施是确保「机、加油车和加油枪用连线接地。这样做可以有效地消除静电积累，避免因静电放电引发的火灾 或爆炸事故。" },
  { id: 294, cat: "飞行手册", q: "地表两点之间大圆航线的特点是（）", opts: ["各点航线角相等", "航线距离最短", "航线距离最长"], ans: 1, exp: "大圆航线是指地球表面上两点之间最短的路径，这条路径是沿着地球表面的大圆弧。 大圆是地球表面上任意两点之间的最短路径，因此沿着大圆航线飞行可以使得航线距离最短，节省时间和燃料。在实际的航空导航中，飞行员会尽量沿着大圆航线飞行，以优化飞行效率。" },
  { id: 295, cat: "飞行手册", q: "地球上两点之间的航线建立最短的是指（）", opts: ["两点之间的直线长度", "两点之间的等角线长度", "两点之间大圆的弧长"], ans: 2, exp: "地球上两点之间的最短航线是沿着大圆的弧长。大圆是地球表面上任意两点之间的最 短路径，这条路径是球面上两点间的大圆弧。在航空和航海中，这种航线被称为大圆航线，它确保了在地球曲面上两点间的最短距离。" },
  { id: 296, cat: "飞行手册", q: "地图比例尺有哪三种表示形式？（）", opts: ["数字、文字、分式", "数字、文字、图解", "数字、分式、图解"], ans: 1, exp: "地图比例尺是表示地图上的距离与实际地面距离缩小程度的比例关系。它有三种主要 的表示形式： 数字式：直接用数字表示比例关系，如 1:50000 表示地图上 1 单位长度代表实际地面上 50000 单位长度。 文字式：用文字描述比例关系，如“一厘米代表一公里”。 图解式（或线段式）：通过一条标有刻度的线段来表示比例关系，线段上的每个刻度代表实 际地面上相应的距离。 因此，正确答案是：数字、文字、图解。" },
  { id: 297, cat: "飞行手册", q: "地图三要素指的是（）", opts: ["地图比例尺、地图符号、地图投影小", "图比例尺、地图符号、图例", "地图符号、图例、地图投影"], ans: 1, exp: "地图的三要素包括地图比例尺、地图符号和图例。这三者共同构成了地图的基础信息 框架： 地图比例尺：表示地图上的距离与实际地面距离之间的比例关系。 地图符号：用于在地图上表示各种地理要素的图形或标记。 图例：解释地图上使用的符号和颜色的含义，帮助读者理解地图内容。 因此，正确答案是：地图比例尺、地图符号、图例。" },
  { id: 298, cat: "飞行手册", q: "对装备定距螺旋桨的活塞发动机，通常用来反映功率的仪表是（）", opts: ["进气压力表", "转速表", "燃油流量表"], ans: 1, exp: "对于装备定距螺旋桨的活塞发动机，通常用来反映功率的仪表是转速表。这是因为在 定距螺旋桨系统中，桨叶的角度是固定的，无法通过改变桨叶角度来调整推力，而是通过改 变发动机的转速来调整功率输出。转速表能够直接显示发动机的转速，从而间接反映发动机 的功率输出情况。因此，转速表是监测和控制发动机功率的关键仪表。" },
  { id: 299, cat: "飞行手册", q: "飞机过载和载荷因子是同一概念吗？（）", opts: ["是", "不确定", "不是"], ans: 0, exp: "飞机过载和载荷因子实际上是同一概念的不同称呼。在航空领域，过载（或称为载荷 因子）是指作用在飞机上的力与飞机重力的比值。它描述了飞机在机动飞行中所承受的加速 度与重力加速度的倍数关系。因此，说飞机过载和载荷因子是同一概念是正确的。" },
  { id: 300, cat: "飞行手册", q: "飞行高度的基准面是（）", opts: ["机场平面", "平均海平面", "1013hPa 气压平面"], ans: 2, exp: "飞行高度层的基准面是 1013hPa 气压平面，也称为标准大气压力面。这个气压平面是 一个理论上的参考平面，用于航空领域中定义飞行高度。在国际航空中，飞行高度层通常以 1013.25 百帕（hPa）的气压高度为准，这是因为 1013.25hPa 大约等于标准大气条件下海平面的气压。" },
  { id: 301, cat: "飞行手册", q: "飞机高度是指（）", opts: ["飞机飞行的高度", "飞机到某一基准面的垂直距离", "飞机到机场平面的垂直距离"], ans: 1, exp: "飞行高度是指飞机到某一基准面的垂直距离。在航空领域，这个基准面通常是平均海 平面（MSL,MeanSeaLevel），也就是考虑到地球曲率和地形变化后，一个理论上的海平面。" },
  { id: 302, cat: "飞行手册", q: "飞行手册中规定着陆不能刹车状态接地，主要是因为（）", opts: ["可能使刹车装置失效", "可能导致滑跑时拖胎", "使机轮起转力矩增大而损坏"], ans: 2, exp: "飞行手册中规定着陆不能刹车状态接地，主要是因为这样做会使机轮起转力矩增大而 损坏。在着陆过程中，如果飞机的刹车系统处于工作状态，那么机轮与地面接触时会产生较 大的摩擦力，这会导致机轮的起转力矩增大，可能会对机轮或者刹车系统造成损害。因此，为了保护飞机的刹车系统和机轮，确保着陆的安全，飞行手册规定在着陆时不能使用刹车。" },
  { id: 303, cat: "飞行手册", q: "高空飞行，按照飞行高度区分为（）", opts: ["6000 米（含）至 12000 米（含）", "4500 米（含）至 9000 米（含）", "8000 米（含）至 12000 米（含）"], ans: 0, exp: "根据中国民航局《一般运行和飞行规则》（CCAR-91-R2）及相关国际民航组织（ICAO）标准，高空飞行的划分如下：高空飞行（HighAltitudeFlight）：飞行高度范围：6000 米（含）至 12000 米（含）该空域通常为喷气式飞机、民航客机等高速航空器的巡航高度层。" },
  { id: 304, cat: "飞行手册", q: "关于粗猛着陆描述正确的是（）", opts: ["粗猛着陆就是使飞机接地的动作太快", "不按规定的着陆高度、速度及接地角，导致受地面撞击力超过规定", "粗猛着陆时前轮先接地"], ans: 1, exp: "粗猛着陆是指飞机在着陆过程中，由于下降速度过快或操作不当，导致飞机受到的地 面撞击力超过规定值的情况。这种情况可能会对飞机的结构造成损害，增加事故风险。因此，飞行手册中规定着陆不能刹车状态接地，主要是为了防止因粗猛着陆导致的飞机结构损伤。 记住粗猛着陆是不按规定着陆导致地面撞击力超规定，就能准确作答。" },
  { id: 305, cat: "飞行手册", q: "航空器起飞着陆时使用跑道主要取决于（）", opts: ["地面风向风速", "机型", "进场航迹与跑道中心延长线夹角大小"], ans: 0, exp: "航空器起飞和着陆时使用跑道的选择主要取决于地面风向和风速。风向和风速对飞机 的起飞和着陆性能有重要影响，特别是对起飞距离和着陆的稳定性。逆风起飞和着陆可以缩 短所需的跑道长度，因为逆风可以提供额外的升力，帮助飞机更容易离地和更平稳地降落。 因此，飞行员和空中交通管制员会根据风向和风速来选择最合适的跑道，以确保飞行安全。" },
  { id: 306, cat: "飞行手册", q: "滑行速度应当按照相应航空器的飞行手册或者飞行员驾驶守则执行，在障碍物附近滑行，速度不得超过（）", opts: ["每小时 15 公里", "每小时 20 公里", "每小时 50 公里"], ans: 0, exp: "航空器在障碍物附近滑行时的速度限制是每小时 15 公里。这一规定明确指出，滑行 速度应当按照相应航空器的飞行手册或者飞行员驾驶守则执行，在障碍物附近滑行，速度不 得超过每小时 15 公里。" },
  { id: 307, cat: "飞行手册", q: "活塞发动机过热易出现在下列哪种过程中？（）", opts: ["长时间爬升", "巡航", "下降"], ans: 0, exp: "活塞发动机过热易出现在长时间爬升过程中。这是因为在爬升过程中，发动机需要更 大的功率来克服重力，同时空气密度降低导致冷却效果下降，使得发动机更容易过热。" },
  { id: 308, cat: "飞行手册", q: "活塞发动机在慢车状态下工作时间过长，易带来的主要危害是（）", opts: ["电嘴挂油积炭", "滑油消耗量过大", "气缸头温度过高"], ans: 0, exp: "活塞发动机在慢车状态下工作时间过长，易带来的主要危害是电嘴挂油积炭。慢车状 态是指发动机以较低的转速运转，以提供较小的推力或功率输出。在这种状态下，发动机的 转速较低，燃料消耗也相对较低，但容易出现电嘴挂油积炭的问题，影响发动机的正常工作。" },
  { id: 309, cat: "飞行手册", q: "计算无人机装载重量和重心的方法不包括（）", opts: ["计算法", "坐标法", "查表法"], ans: 1, exp: "计算无人机装载重量和重心的方法主要有计算法、查表法。而坐标法一般不是用来计 算无人机装载重量和重心的方法。计算法是通过对各个装载物品的重量和其在无人机上的位 置进行精确计算，从而得出无人机的总装载重量和重心位置。查表法是对于一些常见的无人 机装载配置，可以通过查询相关的表格来确定其重量和重心位置。记住计算无人机装载重量 和重心的方法是计算法和查表法，没有坐标法，就能答对这道题。" },
  { id: 310, cat: "飞行手册", q: "降落时间的含义是指（）", opts: ["航空器接地的瞬间", "航空器着陆后前轮接地的瞬间", "航空器着陆滑跑终止的瞬间"], ans: 2, exp: "降落时间的含义是指航空器着陆滑跑终止的瞬间。这个时间点标志着整个着陆过程的 结束，即从飞机接地开始，直到飞机完全停止滑行，不再在跑道上移动。" },
  { id: 311, cat: "飞行手册", q: "经验表明无人机每飞行（）小时或者更少就需要某种类型的预防性维护，至少每（）小 时进行较小的维护", opts: ["20,50", "25,40", "30,60"], ans: 0, exp: "经验表明无人机每飞行 20 小时或者更少就需要某种类型的预防性维护。这是因为无 人机在飞行过程中会受到各种力的作用以及环境因素的影响，部件可能会出现磨损、松动等 情况，所以需要相对频繁地进行预防性维护，以便及时发现和解决潜在问题，确保飞行安全。 至少每 50 小时进行较小的维护，较小的维护可以包括检查关键部件的紧固情况、清洁机身、检查电子设备的连接等，以保持无人机的良好状态。" },
  { id: 312, cat: "飞行手册", q: "距机场（）应当打开全部障碍物标志灯", opts: ["1.5 公里", "2 公里", "3 公里"], ans: 1, exp: "距机场 2 公里应当打开全部障碍物标志灯。这是为了确保飞行安全，特别是在能见度 不佳的情况下，障碍物标志灯能够为飞行员提供关键的视觉提示，帮助他们识别地面上的障 碍物，避免飞行事故。" },
  { id: 313, cat: "飞行手册", q: "可能需要处置的紧急情况不包括（）", opts: ["控制系统故障", "上行通讯链路故障", "控制站显示系统故障"], ans: 0, exp: "紧急情况通常是指那些会对无人机的安全飞行和任务执行产生重大威胁且需要立即采 取措施进行处置的情况。而飞控系统故障并不一定属于紧急情况，因为现代无人机通常有冗 余设计和备份系统，在飞控系统出现部分故障时可能仍能保持一定的飞行能力，并且可以通 过其他方式进行控制或返航。" },
  { id: 314, cat: "飞行手册", q: "可能需要处置的危急情况不包括（）", opts: ["动力装置故障", "任务设备故障", "舵面故障"], ans: 1, exp: "动力装置故障会直接影响飞机的飞行能力，可能导致飞机失去动力而出现危机情况； 舵面故障会影响飞机的操控，也可能使飞机处于危险状态。而任务设备故障通常不会直接危 及飞行安全，一般只是影响特定任务的执行。" },
  { id: 315, cat: "飞行手册", q: "可能需要执行的应急程序不包括（）", opts: ["动力装置重启操作", "备份系统切换操作", "导航系统重启操作"], ans: 2, exp: "可能需要执行的应急程序不包括导航系统重启操作。这是因为在无人机应急处置预案 中，通常会包括动力装置重启操作和备份系统切换操作，以确保无人机在发生故障时能够迅 速恢复动力或切换到备用系统继续执行任务。而导航系统重启操作并不是一个标准的应急程 序，因为导航系统的问题通常不会立即威胁到无人机的安全，且在飞行前应已经进行了充分 的检查和校准。" },
  { id: 316, cat: "飞行手册", q: "没有角度失真的航图叫做（）", opts: ["等距投影图", "等角投影图", "等积投影图"], ans: 1, exp: "没有角度失真的航图指的是等角投影图。等角投影图是一种地图投影方式，它保持了 地图上任意两点之间的方向和角度与实际地理上的相应角度相等，即没有角度变形。这种投 影方式特别适合于需要精确方向和角度信息的地图，如航海图、航空图、风向图等。" },
  { id: 317, cat: "飞行手册", q: "民用无人机系统要求至少（）检查一次", opts: ["半年", "一年", "两年"], ans: 1, exp: "民用无人机系统要求至少一年检查一次。这是为了确保无人机系统的适航状态和安全 运行，定期检查是维护无人机性能和安全的重要环节。" },
  { id: 318, cat: "飞行手册", q: "某跑道长度 2 公里，画到 1:10 万地图上的长度是（）", opts: ["2 厘米", "4 厘米", "6 厘米"], ans: 0, exp: "1:10 万的比例尺意味着地图上 1 单位长度代表实际地面上的 10 万单位长度。如果跑 道长度为 2 公里，即 2000 米，换算成厘米就是 200000 厘米。按照 1:10 万的比例尺，200000 厘米在地图上的长度就是 200000 除以 100000，等于 2 厘米。" },
  { id: 319, cat: "飞行手册", q: "起飞时，可操纵变距螺旋桨的桨叶角到什么状态？（）", opts: ["小桨叶角及低转速", "大桨叶角及高转速", "小桨叶角及高转速"], ans: 2, exp: "在飞机起飞阶段（实际上是指螺旋桨开始转动时），我们需要采取一些措施来确保螺 旋桨能够快速达到所需转速，从而保障飞机安全起飞。具体来说，有两个关键要点： 首先，要减小螺旋桨的阻力。使用小桨叶角可以有效减小螺旋桨的迎风面积，进而降低阻力。 这样，螺旋桨在启动时就能更轻松地转动，减少启动所需的能量。 其次，要增大电机的输出功率。高转速意味着电机需要输出更多的功率，以驱动螺旋桨快速 旋转，使其迅速达到起飞所需的转速。 综上所述，飞机起飞时，通过使用小桨叶角来减小阻力，并结合高转速以增大电机输出功率，就能顺利实现安全起飞的目标。" },
  { id: 320, cat: "飞行手册", q: "起飞时间（陆上）的含义是指（）", opts: ["航空器开始起飞滑跑轮子转动的瞬间", "航空器起飞滑跑抬前轮的瞬间", "航空器进入跑道对正起飞方向的瞬间"], ans: 0, exp: "起飞时间（陆上）的含义是指航空器开始起飞滑跑轮子转动的瞬间。这个定义标志着 航空器从静止状态转变到运动状态的起点，是计算航空器起飞过程时间的重要参考点。" },
  { id: 321, cat: "飞行手册", q: "起落航线飞行开始一转弯和结束四转弯的高度一般不低于（）", opts: ["50 米", "100 米", "150 米"], ans: 1, exp: "根据《民用航空空中交通管理规则》中的相关规定，起落航线飞行的高度通常为 300 米至 500 米，低空小航线不得低于 120 米。起飞后，开始第一转弯和结束第四转弯的高度不 得低于 100 米，低空小航线不得低于 50 米。因此，对于起落航线飞行开始一转弯和结束四 转弯的高度，规定不得低于 100 米。" },
  { id: 322, cat: "飞行手册", q: "气压高度表通过测量大气的什么参数来反映飞行高度？（）", opts: ["大气密度", "大气压力", "大气温度"], ans: 1, exp: "气压高度表是通过测量大气压力参数来反映飞行高度的。它利用气压敏感元件作为传 感器感受大气压力，再根据气压与高度的函数关系确定高度值。这种高度表实质上是测量绝 对压力的压力表，通过感受大气的静压来测量高度。" },
  { id: 323, cat: "飞行手册", q: "气压式高度表的拨正 QNH，高度表指示（）", opts: ["海面气压", "修正海平面气压高度", "场压高度"], ans: 1, exp: "气压式高度表拨正 QNH 时，高度表指示的是修正海平面气压高度。QNH 是修正海平面 气压（CorrectedSeaLevelPressure），它是指将观测到的场面气压，按照标准大气压条件修 正到平均海平面的气压。" },
  { id: 324, cat: "飞行手册", q: "全球划分为多少个时区，每个时区经纬度为多少度？（）", opts: ["12 个，30°", "24 个，15°", "18 个，20°"], ans: 1, exp: "全球被划分为 24 个时区，每个时区覆盖的经度范围是 15 度。这种划分方式使得每个 时区的中央经线相隔 15 度，从而确保全球各地的时间可以协调一致。这种时区划分有助于 减少时间计算的复杂性，并帮助人们在不同地区之间旅行时更容易调整时间。" },
  { id: 325, cat: "飞行手册", q: "如果无人机制造商使用编写的细节更加详细的《无人机驾驶员操作手册》作为主要参考 （）《无人机飞行手册》", opts: ["由局方批准后可以替代", "不可替代", "一般情况下可以替代"], ans: 0, exp: "无人机制造商编写的《无人机驾驶员操作手册》在细节上如果更加详细，并且由局方 批准后，可以替代《无人机飞行手册》。这意味着在某些情况下，如果《无人机驾驶员操作 手册》提供了更为详尽的操作指导和信息，并且得到了官方的批准，它就可以作为主要的参 考手册使用。" },
  { id: 326, cat: "飞行手册", q: "如果一本《无人机飞行手册》没有注明具体的无人机序号和注册信息，则（）", opts: ["手册可以作为该机飞行的参考指导", "手册只能用于一般学习用途", "手册可以部分作为该机飞行参考指导"], ans: 1, exp: "根据《民用无人驾驶航空器运行安全管理规则》中的相关规定，无人机飞行手册中必 须注明具体的无人机序号和注册信息，这是为了确保无人机的合法飞行和适航性。如果《无 人机飞行手册》没有注明具体的无人机序号和注册信息，则不能作为该机飞行的参考指导，只能用于一般学习用途。" },
  { id: 327, cat: "飞行手册", q: "若航向、空速、风向不变，当风速减小时（）", opts: ["偏流减小，地速在顺侧风时增大", "偏流减小，地速不变", "偏流减小，地速在逆侧风时增大"], ans: 2, exp: "当航向、空速、风向不变，风速减小时，偏流（即飞行器实际飞行路径与飞行器相对 空气速度向量之间的夹角）会减小。这是因为偏流角是由风向和飞行器相对空气的速度共同 决定的，风速减小意味着飞行器相对地面的速度（地速）在逆侧风时会增加。在顺侧风的情 况下，地速减小，因为风速的减小会减少顺风对飞行器的推动作用。" },
  { id: 328, cat: "飞行手册", q: "若航向、空速、风向不变，当风速增大时（）", opts: ["偏流增大，地速在顺侧风时增大", "偏流增大，地速增大", "偏流减小，地速减小"], ans: 0, exp: "若航向、空速、风向不变，当风速增大时，偏流角（即飞行器实际飞行路径与飞行器 相对空气速度向量之间的夹角）会增大。这是因风速的增加会影响飞行器的地速，即飞行器 相对于地面的速度。在顺侧风时，风速的增加会使得顺风效应更加明显，从而使得地速增大。 而在逆侧风时，风速的增加会使得逆风效应更加明显，从而使得地速减小。" },
  { id: 329, cat: "飞行手册", q: "谁对民用无人机驾驶航空器系统的维护负责？（）", opts: ["签派", "机长", "运行人"], ans: 2, exp: "根据《民用无人驾驶航空器运行安全管理规则》中的相关规定，运行人应当对民用无 人驾驶航空器的运行控制负责，确保有效监控和管理民用无人驾驶航空器实施的飞行活动。 同时，运行人也应当对持续保持民用无人驾驶航空器系统的适航状态负责，并在实施运行时 确保民用无人驾驶航空器系统的适航证件持续有效。因此，对于民用无人驾驶航空器系统的 维护负责的是运行人。" },
  { id: 330, cat: "飞行手册", q: "世界时（UTC）是指（）", opts: ["英国伦敦的地方时", "零时区的区时", "12 时区的区时"], ans: 1, exp: "世界时（UTC,CoordinatedUniversalTime）是指零时区的区时，也就是通过格林尼治 天文台旧址的经线的地方时间。" },
  { id: 331, cat: "飞行手册", q: "水平能见度小于（）公里的，起飞时还应当打开跑道灯，着陆时还应当打开航空器着陆 方向上保障飞行的全部灯光", opts: ["3", "2", "1"], ans: 2, exp: "在无人机飞行相关规定中，水平能见度是保障飞行安全的一个重要因素。对于本题，当水平能见度小于 1 公里时，起时要打开跑道灯，着陆时还要打开航空器着陆方向（着陆反 航向）上保障飞行的全部灯光。这是因为能见度降低到这个程度时，飞行员的视觉判断会受 到较大影响，打开这些灯光有助于提高飞行的安全性。" },
  { id: 332, cat: "飞行手册", q: "为保障飞行安全，建议无论是在白天还是夜间，当发动机在运转时就打开（）", opts: ["防撞灯", "航行灯", "着陆灯"], ans: 0, exp: "为了保障飞行安全，建议无论是在白天还是夜间，当发动机在运转时就打开防撞灯。 防撞灯：红色闪烁灯，用于警示发动机运转或飞机移动。需在发动机启动至关车期间开启，以提醒其他航空器和地面人员注意飞机的存在，避免碰撞。 其他选项分析如下： 着陆灯：仅在起飞、着陆或低空飞行时使用，巡航时关闭。 航行灯：用于标示飞机轮廓和飞行方向，需全程开启，但不是专门用于发动机运转时的警示 灯。" },
  { id: 333, cat: "飞行手册", q: "为了使在航线上飞行的飞机都有相同的零点高度，应该按（）来调整高度表", opts: ["本站气压", "标准海平面气压", "修正海平面气压"], ans: 1, exp: "为了使在航线上飞行的飞机都有相同的零点高度，应该按照标准海平面气压来调整高 度表。这是因气压高度（也称 QNE 高度）是在国际标准大气条件下，以标准海平面气压 （1013.25hPa）为基准测量出来的高度。使用标准海平面气压可以为所有在高空飞行的飞机 提供一个固定的参考面，确保飞机之间的安全间隔。" },
  { id: 334, cat: "飞行手册", q: "无人机弹射发射方式主要用于（）", opts: ["Ⅲ、Ⅳ、Ⅺ级别固定翼无人机", "Ⅺ、Ⅻ级别固定翼无人机", "Ⅰ、Ⅱ、Ⅲ、Ⅳ、Ⅶ级别固定翼无人机"], ans: 2, exp: "无人机弹射发射方式有着独特优势与适配场景。 在众多无人机分类里，Ⅰ、Ⅱ、Ⅲ、Ⅳ、Ⅶ级别固定翼无人机，它们往往机体相对小巧、重 量较轻。" },
  { id: 335, cat: "飞行手册", q: "无人机的检查应当遵循（）", opts: ["制造商的最新维护手册", "随机附带维护手册", "无人机飞行员经验"], ans: 0, exp: "无人机的检查应当遵循制造商的最新维护手册。 这是因为制造商的维护手册包含了关于无人机维护和检查的最新和最准确的信息，这些信息 是基于无人机的设计和性能参数制定的，能够确保无人机的安全运行和性能。" },
  { id: 336, cat: "飞行手册", q: "无人机的注册所有者或运营人应对保持无人机有最新的适航证书和（）负责", opts: ["无人机安全飞行", "无人机注册证书", "无人机维修"], ans: 1, exp: "无人机的注册所有者或运营人应对保持无人机有最新的适航证书和无人机注册证书负 责。这是因为适航证书证明了无人机符合了特定的安全和性能标准，而注册证书则是无人机 合法飞行的必要条件。" },
  { id: 337, cat: "飞行手册", q: "无人机的注册所有者或运营人应当将永久邮寄地址的变更、无人机的销售和（）等事项 通知局方注册处", opts: ["试验试飞", "无人机注册证书丢失", "无人机维修"], ans: 1, exp: "当无人机的注册所有者或运营人永久邮寄地址发生变更、无人机进行销售以及无人机 注册证书丢失这些情况时，需要及时通知局方注册处，以便局方能够掌握无人机的最新动态 和准确信息。" },
  { id: 338, cat: "飞行手册", q: "无人机飞行前，无人机飞行员（）", opts: ["按照随机《无人机飞行手册》指导飞行", "按照积累的经验指导飞行", "重点参考《无人机所有者/信息手册》"], ans: 0, exp: "无人机飞行前，飞行员应当遵循随机附带的《无人机飞行手册》进行操作和飞行。这 本手册包含了关于无人机操作的具体指导和安全指南，是确保飞行安全和合规的重要文件。" },
  { id: 339, cat: "飞行手册", q: "无人机飞行手册中规定的过载表明（）", opts: ["飞行中允许的最大过载", "起飞时允许的最大过载", "着陆时允许的最大过载"], ans: 0, exp: "无人机飞行手册中规定的过载是指飞行中允许的最大过载。这意味着手册中会明确指 出无人机在正常飞行操作中能够承受的最大过载值，以确保飞行安全并避免对无人机结构造 成损害。" },
  { id: 340, cat: "飞行手册", q: "无人机年度检查，要求（）", opts: ["至少一年一次", "两年一次", "视无人机状态确定"], ans: 0, exp: "根据相关法规和行业标准，无人机需要进行定期的维护和检查，以确保其性能符合安 全要求。年度检查是最基本的要求，意味着无人机至少需要每年进行一次全面的检查，以评 估其技术状况并进行必要的维护。" },
  { id: 341, cat: "飞行手册", q: "无人机年度检查不可由（）进行", opts: ["飞机制造商", "认证的检查授权人员", "无人机飞行员"], ans: 2, exp: "根据民用无人驾驶航空器运行安全管理规则，无人机系统要求至少一年进行一次检查。 这项检查应当由认证的持有检查授权的人员执行，或者由制造商检查，或者由认证和正确评 估的维修站执行。因此，无人机飞行员不能自行进行年度检查，而应由具备相应资质的专业 人员或机构来完成。" },
  { id: 342, cat: "飞行手册", q: "无人机伞降回收方式一般的应用范围为（）", opts: ["Ⅲ、Ⅳ、Ⅺ级别无人机", "Ⅰ、Ⅱ、Ⅲ、Ⅳ、Ⅶ级别无人机", "Ⅰ、Ⅱ、Ⅲ、Ⅳ、Ⅴ、Ⅵ、Ⅶ级别无人机"], ans: 1, exp: "无人机伞降回收方式通常适用于轻小型无人机（重量较轻、速度较慢），以避免硬着 陆损伤机体。根据常用无人机分类标准： Ⅰ、Ⅱ级别：微型、轻型无人机，重量通常在 15kg 以下，适合伞降。 Ⅲ、Ⅳ级别：中小型无人机，部分机型重量适中，伞降可作为备选方案。 Ⅶ级别：如植保无人机（多为轻小型），常采用伞降减少降落冲击。 Ⅺ、Ⅴ、Ⅵ级别：大型无人机（如货运、固定翼长航时机型），重量大、速度高，伞降难度大，多采用滑跑或撞网回收。 因此，伞降回收主要应用于Ⅰ、Ⅱ、Ⅲ、Ⅳ、Ⅶ级别无人机。" },
  { id: 343, cat: "飞行手册", q: "无人机适航证书不可（）", opts: ["随飞机一起转让", "存放备查", "随无人机系统携带"], ans: 1, exp: "根据《民用无人驾驶航空器运行安全管理规则》（CCAR-92 部规章）的规定，无人机 适航证书是不可存放备查的。适航证书应当随无人机系统携带，以备查验。" },
  { id: 344, cat: "飞行手册", q: "无人机特殊飞行许可颁发前，由局方检查官或局方认证人员或（）进行检查以确定位于 预期的飞行是安全的", opts: ["适当认证修理站", "经验丰富无人机飞行员", "经验丰富有人机飞行员"], ans: 0, exp: "无人机特殊飞行许可颁发前，由局方检察官或局方认证人员或适当认证修理站进行检 查以确定位于预期的飞行是安全的。适当认证修理站通常具备专业的技术和设备，能够对无 人机进行全面的检查和评估，确保其在特殊飞行前处于安全状态。他们熟悉无人机的结构和 性能，能够发现潜在的问题并进行修复。" },
  { id: 345, cat: "飞行手册", q: "无人机系统无线电资源的使用（）局方无线电管理部门的许可证", opts: ["需要", "不需要", "一般情况不需要"], ans: 0, exp: "根据《民用无人驾驶航空器无线电管理暂行办法》的规定，无人机系统无线电资源的 使用需要局方无线电管理部门的许可证。" },
  { id: 346, cat: "飞行手册", q: "无人机制造商编写的随机文档《无人机所有者/信息手册》（）", opts: ["需经局方批准", "不需局方批准", "特殊飞行器需局方批准"], ans: 1, exp: "无人机制造商编写的随机文档《无人机所有者/信息手册》不需要局方批准。这本手 册通常包含有关无人机操作、维护和安全的重要信息，旨在指导无人机所有者和操作员如何 安全、合规地使用无人机。制造商负责确保手册内容的准确性和完整性，而不需要额外的局 方批准" },
  { id: 347, cat: "飞行手册", q: "无人机制造商编写的随机文档《无人机所有者/信息手册》（）", opts: ["可以替代《无人机飞行手册》", "一般情况下可以替代《无人机飞行手册》", "不能替代《无人机飞行手册》"], ans: 2, exp: "无人机制造商编写的随机文档《无人机所有者/信息手册》不能替代《无人机飞行手 册》。《无人机飞行手册》（AFM）是无人机制造商编写而由局方批准的文档，它特定于无人机 的型号和注册序号，包含操作程序和限制。《无人机所有者/信息手册》虽然提供了相关信息，但不能完全替代正式的《无人机飞行手册》，因为它不包含操作程序和限制等关键信息。" },
  { id: 348, cat: "飞行手册", q: "无人机注册证书颁发给飞机所有者作为注册证明（）", opts: ["随时随机携带", "存放备查", "作为售出证明"], ans: 0, exp: "无人机注册证书颁发给飞机所有者作为注册证明，需要随时随机携带。这是因为无人 机注册证书作为注册证明需要在飞行时能够随时提供给相关部门或人员，以证明该飞机已合 法注册。" },
  { id: 349, cat: "飞行手册", q: "旋翼机飞行时间的含义是指（）", opts: ["自旋翼机起飞离地到着陆接地的瞬间", "自旋翼机起飞滑跑至着陆滑跑终止的瞬间", "自旋翼机旋翼开始转动至旋翼停止人转动的瞬间"], ans: 2, exp: "旋翼机的飞行时间定义为从旋翼开始转动至旋翼停止转动的整个时间段。这个定义覆 盖了旋翼机从启动、起飞、执行任务到降落、旋翼完全停止的整个过程，是衡量旋翼机实际 飞行时长的标准。" },
  { id: 350, cat: "飞行手册", q: "旋翼机在停机坪上起飞和着陆时，距离其他航空器或者障碍物的水平距离不少于（）", opts: ["10 米", "20 米", "25 米"], ans: 0, exp: "旋翼机在停机坪上进行起飞和着陆操作时，需要确保有一定的安全距离，以避免与其 他航空器或障碍物发生碰撞。根据相关的安全规定，这个最小水平距离是不少于 10 米。这 样的距离可以为旋翼机提供足够的空间进行安全操作，同时也为可能出现的紧急情况提供了 一定的缓冲区域。" },
  { id: 351, cat: "飞行手册", q: "在同一航向、风向风速条件下，真空速增大，则（）", opts: ["地速增大，偏流增大", "地速增大，偏流减小", "地速增大，偏流不变"], ans: 1, exp: "在同一航向、风向风速条件下，真空速（即飞行器相对于空气的速度）增大时，地速 （即飞行器相对于地面的速度）也会增大，因为地速是真空速和风速的矢量和。同时，偏流 角（即飞行器航向与地速向量之间的角度）会减小，因为真空速的增加会使得飞行相对于风 的影响变得更加显著，从而减少偏流角。" },
  { id: 352, cat: "飞行手册", q: "在装载时，由于飞机重心偏右，可导致在巡航飞行时，飞机的阻力（）", opts: ["增大", "减小", "不变"], ans: 0, exp: "在装载时，如果飞机的重心偏右，意味着飞机的重量分布不均匀，这会影响飞机的空 气动力学性能。重心偏移会导致飞机在巡航飞行时产生额外的侧向力，为了保持飞机的平衡，飞行员可能需要调整飞机的姿态，这可能会导致飞机的迎风面积增加，从而增加阻力。因此，飞机重心偏右会导致飞机的阻力增大。" },
  { id: 353, cat: "飞行手册", q: "直升机可以用（）的飞行代替滑行", opts: ["1-5 米高度", "1-10 米高度", "1-15 米高度"], ans: 1, exp: "直升机具有垂直起降和低空悬停等特点，在某些情况下可以用在 1 米至 10 米高度的 飞行来代替滑行。这个高度范围既能够保证一定的安全性，又可以满足直升机在特定场景下 快速移动的需求。" },
  { id: 354, cat: "飞行手册", q: "中空飞行，按照飞行高度区分为（）", opts: ["100m（含）～45000m（含）", "1000m（含）~5400m（含）", "1000（含）~6000m（不含）"], ans: 2, exp: "根据中国民航局《一般运行和飞行规则》（CCAR-91 部）及国际民航组织（ICAO）标 准： 中空飞行高度层定义： 1000 米（含）至 6000 米（不含），属于中空飞行范围。 该空域主要用于民航航班、通用航空等常规飞行活动。 其他选项分析： 100m~45000m：范围过大，包含低空、中空、高空甚至太空边缘，不符合分类标准。 1000m~5400m:5400m 为过渡高度层上限，但中空实际覆盖至 6000m（不含）。" },
  { id: 355, cat: "飞行手册", q: "地图存在的三种失真是（）", opts: ["角度、长度、体积", "角度、面积、体积", "角度、长度、面积"], ans: 2, exp: "地图失真主要体现在角度、长度和面积三个方面。由于地球是一个不规则的椭球体，将其表面投影到二维平面上时，不可避免地会产生这些失真。" },
  { id: 356, cat: "飞行手册", q: "机场上吹西风时，飞机起飞着陆的最好方向是（）", opts: ["由西向东", "由东向西", "由北朝南"], ans: 1, exp: "飞机起飞和着陆时，通常需要逆风进行，以增加升力并减少地面速度。当机场上吹西 风时，飞机应从东向西起飞和着陆，这样可以利用逆风提高飞行安全性和效率。" },
  { id: 357, cat: "飞行手册", q: "100m 等于（）英尺", opts: ["300", "305", "328"], ans: 2, exp: "1 米等于 3.28084 英尺，因此 100 米等于 100×3.28084=328.084 英尺，约等于 328 英 尺。" },
  { id: 358, cat: "飞行手册", q: "气压高度表的拨正值 QFE 含义为（）", opts: ["场面气压", "场面气压高度", "海平面气压"], ans: 0, exp: "QFE 是场面气压的代名词，通过将其作为高度表的参考值，飞行员能够更准确地控制 飞机与地面之间的距离，尤其适用于低空飞行和起降过程中的高度测量。" },
  { id: 359, cat: "飞行手册", q: "气象台观测风向是 180 度，飞机起飞着陆时最佳方向是（）", opts: ["由北朝南", "由南朝北", "由西朝东"], ans: 0, exp: "风向 180°表示风是从南向北吹的。飞机起飞和着陆时应逆风进行，以增加升力并减 少地面速度，因此最佳方向是由北朝南。" },
  { id: 360, cat: "飞行手册", q: "空气组成是（）", opts: ["90%氮，6%氧和 4%其他气体", "78%氮，20%氧和 2%其他气体", "78%氮，21%氧和 1%其他气体"], ans: 2, exp: "空气的主要成分是氮气（约 78%）、氧气（约 21%）和其他气体（约 1%），如二氧化 碳、氩气等。" },
  { id: 361, cat: "飞行手册", q: "飞行时，霾对飞行能见度或观察地形地物的能力有何影响？（）", opts: ["霾使视力集中于远处", "在霾中，眼睛容易疲劳因而不容易发现相对的移动物", "所有飞行器的活动或地形地物显得比实际距离远"], ans: 2, exp: "霾会降低能见度，使飞行员难以清晰地看到远处的飞行器和地形地物，从而导致这些 物体显得比实际距离更远。 其他选项分析如下： 1.霾使视力集中于远处：错误。霾实际上会降低能见度，使飞行员难以看清远处的物体，而 不是使视力集中于远处。 2.在霾中，眼睛容易疲劳因而不容易发现相对的移动物：错误。虽然霾确实会使眼睛容易疲 劳，但题目中主要考察的是对飞行能见度和观察地形地物能力的影响，而不是眼睛疲劳。" },
  { id: 362, cat: "飞行手册", q: "能见度不好的天气，一般风力（）", opts: ["较强", "较弱", "混乱"], ans: 1, exp: "能见度不好的天气，一般风力较弱。这种情况下，空气中的颗粒物（如雾霾）不易被 吹散，导致能见度降低。" },
  { id: 363, cat: "飞行手册", q: "机场的起落航线通常为（）航线，起落航线的飞行高度通常为（）", opts: ["左，300 米-600 米", "右，300 米-500 米", "左，300 米-500 米"], ans: 2, exp: "根据《中华人民共和国飞行基本规则》第五十一条的规定，机场的起落航线通常为左 航线；若因地形、城市等条件的限制，或者为避免同邻近机场的起落航线交叉，也可以为右 航线。起落航线的飞行高度，通常为 300 米至 500 米。" },
  { id: 364, cat: "飞行手册", q: "飞机滑跑刹车时地面摩擦力变化（）", opts: ["在一定限度内随刹车力矩增大而增大", "增大阻力滚力矩就能增大地面摩擦力", "刹车越重效果越好"], ans: 0, exp: "地面摩擦力在一定限度内会随着刹车力矩的增大而增大，但超过这个限度后，摩擦力 可能会因为轮胎打滑而减小。 其他选项分析如下： 1.增大阻滚力矩就能增大地面摩擦力：错误。 虽然增大阻滚力矩可以增加摩擦力，但并不是唯一的因素，且超过一定限度后，可能会导致 轮胎打滑，反而减小摩擦力。 2.刹车越重效果越好：错误。刹车过重可能会导致轮胎打滑，失去制动力，反而降低刹车效 果。" },
  { id: 365, cat: "飞行手册", q: "空虚视野近视的主要表现是（）", opts: ["视野缩小，并产生恐惧感", "主观感觉内心空虚，视觉模糊", "眼睛会自动聚焦于前面 1-2 米处的空间某点"], ans: 2, exp: "空虚视野近视是指在缺乏视觉参照物的环境中，人眼会不自觉地聚焦在较近的距离（通 常为 1-2 米处），导致远处的物体看起来模糊。" },
  { id: 366, cat: "飞行手册", q: "小型低速飞机着陆滑跑的主要减速力是（）", opts: ["放襟翼产生的空气阻力", "刹车时增大的地面摩擦力", "发动机的反推力"], ans: 1, exp: "小型低速飞机着陆滑跑时，主要的减速力来自刹车时增大的地面摩擦力。当飞机的轮 胎与跑道接触并应用刹车时，轮胎与跑道之间的摩擦力会产生阻碍飞机滑行的力，从而减速 飞机。 其他选项分析如下： 1.放襟翼产生的空气阻力：错误。虽然放襟翼可以增加空气阻力，但在小型低速飞机的着陆 滑跑阶段，空气阻力并不是主要的减速力。 2.发动机的反推力：错误。小型低速飞机通常没有反推力装置，因此反推力不是主要的减速 力。" },
  { id: 367, cat: "飞行手册", q: "为了保证刹车减速安全高效，必须（）", opts: ["飞机主轮接地就应及时踩刹车", "滑跑速度大，刹车应重一些", "随滑跑速度减小逐渐增大刹车压力"], ans: 2, exp: "为了保证刹车减速安全高效，必须随滑跑速度减小逐渐增大刹车压力。这是因为随着 飞机滑跑速度的减小，机轮与地面的结合力会增加，此时可以逐渐增大刹车压力以充分利用 地面摩擦力，从而更有效地减速。" },
  { id: 368, cat: "飞行手册", q: "关于粗猛刹车，正确的说法是（）", opts: ["粗猛刹车是指刹车过早且过重，导致机轮严重打滑", "粗猛刹车是指操纵刹车太快", "粗猛刹车可以增大刹车效果，只是机轮磨损大一些"], ans: 0, exp: "粗猛刹车通常是指在飞机着陆后，刹车操作过于急促和用力过猛，导致机轮与地面的 摩擦力突然增大，超过了机轮与地面的结合力，从而引起机轮打滑。这种操作不仅会降低刹 车效果，还可能导致机轮损坏。" },
  { id: 369, cat: "飞行手册", q: "关于机轮卡滞，正确的说法是（）", opts: ["滑跑刹车机轮卡滞是因为地面摩擦力太大", "机轮卡滞又叫作拖胎、打滑", "严重卡滞虽然刹车效率高但不安全"], ans: 1, exp: "机轮卡滞是指在刹车过程中，机轮与地面之间发生相对滑动的现象，通常称为拖胎或 打滑。 其他选项分析如下： 1、滑跑刹车机轮卡滞是因为地面摩擦太大：错误。机轮卡滞是因为刹车压力过大，导致机 轮与地面之间的摩擦力超过了机轮与地面的结合力，从而发生打滑。 2、严重卡滞虽然刹车效率高但不安全：错误。 严重卡滞虽然在某些情况下可能看起来刹车效率高，但实际上会导致机轮过度磨损，甚至可 能损坏机轮，降低刹车效果，是非常不安全的。" },
  { id: 370, cat: "飞行手册", q: "最高刹车效率过程是（）", opts: ["始终保持较大刹车压力过程", "尽量增大阻滚力矩的刹车过程", "刹车力矩接近而不超过地面结合力矩的刹车过程"], ans: 2, exp: "最高刹车效率是指在刹车过程中，刹车力矩接近但不超过地面结合力矩，这样可以充 分利用地面摩擦力，实现最佳的减速效果，同时避免机轮打滑。" },
  { id: 371, cat: "飞行手册", q: "飞机停留刹车的目的之一是（）", opts: ["地面检查时必须刹住飞机", "地面试车增大功率时防止飞机滑动", "地面装载及检查时防止飞机晃动"], ans: 1, exp: "停留刹车（ParkingBrake）的主要作用是在发动机试车或大功率运行时防止飞机意外 移动，确保地面安全。" },
  { id: 372, cat: "飞行手册", q: "有的飞行员提出，夜间滑行时如突遇强光，可暂时闭上一只眼睛，提出这种方法理由是 （）", opts: ["可保持眼睛的对暗适应", "可增加眼睛的视敏度", "可使眼睛免受伤害"], ans: 0, exp: "在夜间飞行时，眼睛需要适应暗光环境，以保持对弱光的敏感性。如果突然遇到强光，眼睛的暗适应能力会被破坏。通过暂时闭上一只眼，可以保持这只眼睛对暗光的适应能力。 其他选项分析如下： 1.可增加眼睛的视敏度：错误。虽然保持暗适应有助于视敏度，但暂时闭上一只眼的主要目 的是保持暗适应，而不是直接增加视敏度。 2.可使眼睛免受伤害：错误。虽然闭上眼睛可以减少强光对眼睛的直接伤害，但主要目的是 保持暗适应，而不是避免伤害。" },
  { id: 373, cat: "飞行手册", q: "夜间近视产生的主要原因是（）", opts: ["夜间飞行时，可供观察的物体很少", "夜间飞行时，飞行员的视力减弱", "夜间飞行时，没有使用扫视技术"], ans: 0, exp: "夜间飞行时，由于光线不足，飞行员能够观察到的物体非常有限。这种情况下，飞行 员的眼睛会不自觉地聚焦在较近的物体上，导致远处的物体看起来模糊，从而产生夜间近视 现象。" },
  { id: 374, cat: "飞行手册", q: "最有效的搜索是使用一系列（）的眼睛运动，这样有助于将天空连续的区域反映到中央 视觉区域", opts: ["连续", "跳跃式", "短暂、固定时间间隔"], ans: 2, exp: "最有效的搜索方式是采用短暂、固定时间间隔的眼睛运动（如每 10°视野停顿 1-2 秒），确保每个区域都能被中央视觉（视网膜最敏感区域）充分处理，避免遗漏或重复扫描。" },
  { id: 375, cat: "飞行手册", q: "目视飞行时，在同一高度上超越前面飞行器应当从前面飞行器右侧超越，其间隔应保持 （）", opts: ["200m 以上", "300m 以上", "500m 以上"], ans: 2, exp: "根据《中华人民共和国飞行基本规则》的规定，目视飞行时，在同一高度上超越前面 飞行器应当从前面飞行器右侧超越，并保持 500 米以上的间隔。" },
  // ==================== 任务规划 ====================
  { id: 376, cat: "任务规划", q: "（）包括携带的传感器类型、摄像机类型和专用任务设备类型等，规划设备工作时间及 工作模式，同时需要考虑气象情况对设备的影响程度。", opts: ["任务规划", "载荷规划", "任务分配"], ans: 1, exp: "无人机的载荷规划包括携带的传感器类型、摄像机类型和专用任务设备类型等，规划 设备工作时间及工作模式，同时需要考虑气象情况对设备的影响程度。因此，正确答案是载 荷规划。" },
  { id: 377, cat: "任务规划", q: "（）包括在执行任务的过程中，需要根据环境情况的变化制定一些通信任务，调整与任 务控制站之间的通信方式等。", opts: ["链路规划", "目标分配", "通信规划"], ans: 2, exp: "无人机在执行任务的过程中，需要根据环境情况的变化制定一些通信任务，调整与任 务控制站之间的通信方式等，这属于通信规划的范畴。" },
  { id: 378, cat: "任务规划", q: "（）的内容包括出发地点、途经地点、目的地点的位置信息、飞行高度速度和需要到达 的时间段。", opts: ["航线规划", "航迹规划", "任务规划"], ans: 0, exp: "航线规划是指在飞行前对飞机的飞行路线进行详细的规划，包括出发地点、途经地点、目的地点的位置信息，以及飞行的高度、速度和预计到达的时间段等。这些信息对于确保飞 行安全和效率至关重要。" },
  { id: 379, cat: "任务规划", q: "（）即根据飞行过程中遇到的突发状况，如地形、气象变化、未知限飞禁飞因素等，局 部动态的调整行路径或改变动作任务。", opts: ["在线规划", "飞行中重规划", "飞行前预规划"], ans: 1, exp: "飞行中重规划指的是无人机在飞行过程中根据实际的飞行情况和环境变化，动态调整 飞行路径或改变动作任务的过程。这种规划能力对于无人机在复杂环境中的自主飞行和任务 执行至关重要，因为它允许无人机迅速响应未知的限飞禁飞因素、地形变化和气象条件等突 发状况。" },
  { id: 380, cat: "任务规划", q: "（）根据既定任务，结合环境限制与飞行约束条件，从整体上制定最优参考路径并装订 特殊任务。", opts: ["在线规划", "飞行中重规划", "飞行前预规划"], ans: 2, exp: "飞行前预规划是指在无人机执行任务之前，根据任务需求、环境限制和飞行约束条件，从整体上制定最优的飞行路径，并安排特殊任务。这个过程涉及到对飞行环境的分析、飞行 路径的优化以及任务的具体安排，是确保无人机任务顺利进行的重要步骤。" },
  { id: 381, cat: "任务规划", q: "（）是完成任务的一项重要的辅助性工作，细致规范的（）将大幅度提高飞行安全性和 任务完成质量。", opts: ["场地标注、场地标注", "图元标注、图元标注", "警示标注、警示标注"], ans: 1, exp: "图元标注是完成任务的一项重要的辅助性工作，细致规范的图元标注将大幅度提高飞 行安全性和任务完成质量。" },
  { id: 382, cat: "任务规划", q: "（）是在无人机飞行过程中，根据实际的飞行情况和环境的变化制定出一条可分航迹，包括对预先规划的修改，以及选择应急的方案，其特点是约束和飞行环境实时变化，任务规 划系统需综合考量威胁、航程、约束等多种条件，采用（）生成飞行器的安全飞行航迹，任 务规划系统需具备较强的信息处理能力并具有一定的辅助决策能力。", opts: ["预先规划，最优航迹规划算法", "航迹规划，最短航迹规划算法", "实时规划，快速航迹规划算法"], ans: 2, exp: "实时规划是指无人机在飞行过程中，根据实际的飞行情况和环境的变化制定出一条可 飞航迹，包括对预先规划的修改，以及选择应急的方案等。 其特点是约束和飞行环境实时变化，任务规划系统需综合考量威胁、航程、约束等多种条件，采用快速航迹规划算法生成飞行器的安全飞行航迹。任务规划系统需具备较强的信息处理能 力并具有一定的辅助决策能力。" },
  { id: 383, cat: "任务规划", q: "（）是无人机执行任务前，由地面控制站制定的，主要是综合任务要求、地理环境和无 人机任务载荷等因素进行规划，其特点是约束和飞行环境给定，规划的主要目的是通过选用 合适的算法谋求（）飞行航迹。", opts: ["实时规划，航程最短", "预先规划，全局最优", "航迹规划，航时最短"], ans: 1, exp: "预先规划是在无人机执行任务前，由地面控制站制定的，主要是综合任务要求、地理 环境和无人机任务载荷等因素进行规划。其特点是约束和飞行环境给定，规划的主要目的是 通过选用合适的算法谋求全局最优飞行航迹。" },
  { id: 384, cat: "任务规划", q: "（）是无人机从航线上的任意点转入安全返航通道或从安全返航通道转向应急迫降点或 机场。", opts: ["安全着陆策略", "航线转移策略", "安全返航策略"], ans: 1, exp: "航线转移策略是指从航线上的任意点转入安全返航通道或从安全返航通道转向应急迫 降点或机场的过程。这个策略是为了确保无人机在遇到紧急情况时能够安全地转移航线并返 回或迫降。航线转移策略是无人机应急处置规划的一部分，涉及到对突发情况的快速响应和 处理。" },
  { id: 385, cat: "任务规划", q: "（）是指侦察监测区域应当预先标注，主要包括任务区域范围、侦察监测对象等。", opts: ["场地标注", "任务区域标注", "警示标注"], ans: 1, exp: "无人机在执行侦察监测任务时，需要明确工作范围和目标，因此任务区域标注是必不 可少的步骤。这包括确定无人机需要覆盖的地理区域以及需要特别关注的对象或目标。通过 预先标注任务区域，可以确保无人机高效、有序地执行任务，同时也有助于避免对非目标区 域造成不必要的干扰或影响。" },
  { id: 386, cat: "任务规划", q: "（）应具备的功能包括：标准飞行轨道生成功能，常规的飞行航线生成、管理功能。", opts: ["航线规划", "航迹规划", "任务规划"], ans: 0, exp: "航线规划是指在无人机执行任务前，对无人机的飞行路径进行预先设计和规划的过程。 这包括生成标准飞行轨道、常规飞行航线的生成和管理等功能，以确保无人机能够按照预定 的路径安全、高效地完成任务。" },
  { id: 387, cat: "任务规划", q: "（）在无人机任务规划中的作用是显示无人机的飞行位置、画出飞行航迹、标识规划点 以及显示规划航迹等。", opts: ["电子地图", "地理位置", "飞行航迹"], ans: 0, exp: "电子地图是无人机任务规划中的关键工具，它能够显示无人机的实时飞行位置、画出 飞行航迹、标识规划点以及显示规划航迹等，为无人机的操作者提供了直观的地理信息和飞 行路径，有助于进行有效的任务规划和监控。" },
  { id: 388, cat: "任务规划", q: "（）主要包括起飞场地标注、着陆场地标注、应急场地标注，为操作员提供发射与回收 以及应急迫降区域参考。", opts: ["场地标注", "务区域标注", "警示标注"], ans: 0, exp: "场地标注在无人机任务规划中的作用是显示无人机的起飞场地、着陆场地和应急场地 的位置信息，为操作员提供发射与回收以及应急迫降区域的参考。这些信息对于确保无人机 的安全飞行和有效执行任务至关重要。" },
  { id: 389, cat: "任务规划", q: "（）主要用于飞行区域内重点目标的标注，如建筑物、禁飞区、人口密集区等易影响飞 行安全的区域。", opts: ["场地标注", "任务区域标注", "警示标注"], ans: 2, exp: "警示标注主要用于飞行区域内重点目标的标注，如建筑物、禁飞区、人口密集区等易 影响飞行安全的区域。这些标注有助于提醒无人机操作员注意这些区域，以避免潜在的安全 风险和违反飞行规定。" },
  { id: 390, cat: "任务规划", q: "（）主要指执行任务过程中实现动作的时间点、方式和方法，设定机会航点的时间节点、飞行高度、航速、飞行姿态以及配合载荷设备的工作状态与模式，当无人机到达该航点时实 施航拍、盘旋等飞行任务。", opts: ["任务分配", "载荷规划", "目标分配"], ans: 2, exp: "目标分配指的是在无人机执行任务过程中，对于特定的目标或任务点进行详细的动作 规划，包括确定动作的时间点、方式和方法。这涉及到设定航点的时间节点、飞行高度、航 速、飞行姿态，以及配合载荷设备的工作状态与模式。当无人机到达预定的航点时，将根据 目标分配执行具体的飞行任务，如航拍、盘旋等。" },
  { id: 391, cat: "任务规划", q: "（地面站）电子地图图元标注不包括下列那种信息？（）", opts: ["场地标注", "警示标注", "地形标注"], ans: 2, exp: "地面站电子地图图元标注通常包含场地标注和警示标注等，用于标识特定场地和给出 警示信息等，而地形标注一般不是以图元标注的形式存在于电子地图中。" },
  { id: 392, cat: "任务规划", q: "不属于无人机回收方式的是（）", opts: ["伞降", "飘落", "气囊回收"], ans: 1, exp: "无人机的回收方式主要包括伞降回收、空中回收、起落架滑跑着陆、拦阻网回收、气 垫着陆和垂直着陆回收等类型。飘落并不是无人机回收的一种常见方式。" },
  { id: 393, cat: "任务规划", q: "从实施时间上划分，任务规划可以分为（）", opts: ["航迹规划和任务分配规划", "航迹规划和数据链路规划", "预先规划和实时规划"], ans: 2, exp: "无人机任务规划可以从不同的角度进行分类。其中，从时间上来说，无人机任务规划 可以分为预先规划和实时规划。预先规划是在无人机执行任务前制定的，而实时规划是在飞 飞行过程中根据实际情况进行的规划。" },
  { id: 394, cat: "任务规划", q: "大型军用无人机最常用的导航方式是（）", opts: ["卫星导航", "地形匹配导航", "组合导航"], ans: 2, exp: "大型军用无人机，组合导航最常用。大型军用无人机在执行任务时，由于对导航精度 和可靠性的要求较高，通常会采用多种导航技术的组合，以提高导航的准确性和鲁棒性。根 据搜索结果，大型军用无人机最常用的导航方式是组合导航，即结合了惯性导航、卫星导航 等多种导航技术的方式。" },
  { id: 395, cat: "任务规划", q: "地面站电子地图显示的信息分为三个方面：一是（），二是（），三是其他辅助信息，如 图元标注", opts: ["无人机位置和飞行航迹，无人机航迹规划信息", "无人机地理坐标信息，无人机飞行姿态信息", "无人机飞行姿态信息，无人机航迹规划信息"], ans: 0, exp: "地面站电子地图显示的信息分为三个方面：一是无人机位置和飞行航迹，二是无人机 航迹规划信息，三是其他辅助信息，如图元标注。 地面站电子地图主要用于显示无人机的实时位置、飞行过的航迹以及预先规划好的航迹规划 信息等，以便操作人员进行监控和指挥。 无人机地理坐标信息属于无人机位置信息的一部分，飞行姿态信息一般不在电子地图中主要 显示。" },
  { id: 396, cat: "任务规划", q: "地面站显示系统警告信息主要包括（）", opts: ["触觉警告和听觉警告", "视觉警告和听觉警告", "视觉警告和触觉警告"], ans: 1, exp: "地面站显示系统警告信息主要包括视觉警告和听觉警告。视觉警告通过地面站界面上 的指示灯、图标、文字等视觉元素向操作员显示警告信息，而听觉警告则通过声音提醒操作 员注意某些紧急情况或异常状态。" },
  { id: 397, cat: "任务规划", q: "地图校准时，在命令下拉菜单中选取（）个定位点作为校准点，并在对话框左侧输入这些定位点的实际地理位置信息。", opts: ["2 个", "3 个", "4 个"], ans: 1, exp: "地图校准选三点。地图校准时，通常需要选取至少三个不共线的点来确定地图与实际 地理坐标之间的转换关系。这是因为至少需要三个点才能唯一确定一个平面的几何变换，包 括旋转、缩放和平移。" },
  { id: 398, cat: "任务规划", q: "动力系统工作恒定的情况下（）限制了航迹在垂直平面内上升和下滑的最大角度", opts: ["最小转弯半径", "最大俯仰角", "最大转弯半径"], ans: 1, exp: "动力系统工作恒定的情况下，限制了航迹在垂直平面内上升和下滑的最大角度的是最 大俯仰角。最大俯仰角是指无人机在垂直平面内进行俯仰动作时能够达到的最大角度，这个 角度受到无人机自身机动性能、飞行高度和气候状况等因素的影响。在三维空间航迹规划中，这个约束限制了无人机只能在特定角度内进行俯仰动作，要求无人机在某一航迹点的俯仰角 不大于最大俯仰角。" },
  { id: 399, cat: "任务规划", q: "惯导（INS）的优点不包括下列哪一条？（）", opts: ["无漂移", "不受干扰", "全天候"], ans: 0, exp: "惯导（INS）的优点包括隐蔽性好、全天候工作能力、提供位置、速度、航向和姿态 角数据、导航信息更新速率高等。然而，惯导系统的主要缺点之一是存在漂移现象，即导航 误差随时间发散，由于导航信息经过积分运算产生，定位误差会随时间推移而增大，长期积 累会导致精度差。因此，惯导系统的优点是不包括无漂移的。" },
  { id: 400, cat: "任务规划", q: "航迹规划需要充分考虑（）的选取、标绘，航线预先规划以及在线调整时机", opts: ["飞行航迹", "地理位置", "电子地图"], ans: 2, exp: "航迹规划时，电子地图起着至关重要的作用。电子地图可以提供丰富的地理信息，包 括地形地貌、障碍物分布等。通过电子地图可以进行飞行航迹的选取和标绘，在规划阶段可 以预先规划航线，并且在实际飞行过程中，根据实时情况利用电子地图来确定在线调整航线 的时机。" },
  { id: 401, cat: "任务规划", q: "航迹优化是指航迹规划完成后，系统根据无人机飞行的（）对航迹进行优化处理，制定 出适合无人机飞行的航迹", opts: ["最大转弯半径和最小俯仰角", "最小转弯半径和最大俯仰角", "最大转弯半径和最大俯仰角"], ans: 1, exp: "航迹优化是指航迹规划完成后，系统根据无人机飞行的最小转弯半径和最大俯仰角对 航迹进行优化处理，制定出适合无人机飞行的航迹。这是因为在无人机的实际飞行中，需要 考虑到无人机的物理限制，如转弯半径和俯仰角，以确保飞行的安全性和有效性。" },
  { id: 402, cat: "任务规划", q: "进行无人机飞行任务规划时，下列哪一项不再考虑范围内？（）", opts: ["禁飞区", "险恶地形", "飞机寿命"], ans: 2, exp: "在进行无人机飞行任务规划时，需要考虑的因素包括飞行安全、飞行效率和遵守相关 法规等。禁飞区和险恶地形都是飞行规划中必须考虑的重要因素，因为它们直接影响到飞行 安全和任务的成功执行。" },
  { id: 403, cat: "任务规划", q: "就任务规划系统具备的功能而言，任务规划可包含航迹规划、任务分配规划、数据链路 规划和系统保障与应急预案规划等，其中（）是任务规划的主体和核心。", opts: ["航迹规划", "任务分配规划", "数据链路规划"], ans: 0, exp: "配规划、数据链路规划和系统保障与应急预案规划等。其中，航迹规划是任务规划的 主体和核心，因为它直接关系到无人机的飞行路径和安全，涉及到无人机从起飞到完成任务 并返回的整个飞行过程。航迹规划需要综合考虑飞行环境、任务要求、无人机性能等多方面 因素，确保无人机能够高效、安全地完成任务。" },
  { id: 404, cat: "任务规划", q: "任务分配提供可用的无人机资源和着陆点的显示，辅助操作人员进行（）", opts: ["载荷规划、通信规划和目标分配", "链路规划、返航规划和载荷分配", "任务规划、返航规划和载荷分配"], ans: 0, exp: "题目考查的是无人机任务分配系统的功能。任务分配系统需要提供可用无人机资源和 着陆点的显示，辅助操作人员进行相关规划。“载荷规划、通信规划和目标分配”是无人机 任务分配的核心内容： 载荷规划：根据任务需求分配无人机的载荷（如摄像头、传感器等）。 通信规划：确保无人机与操作人员之间的通信链路畅通。 目标分配：为无人机分配具体的任务目标。" },
  { id: 405, cat: "任务规划", q: "任务规划的主要目标是依据地形信息和执行任务环境条件信息，综合考虑无人机的性能、到达时间、耗能、威胁以及飞行区域等约束条件，为无人机规划出一条或多条自（）的（），保证无人机高效、圆满地完成飞行任务，并安全返回基地。", opts: ["起点到终点，最短路径", "起飞点到着陆点，最佳路径", "出发点到目标点，最优或次优航迹"], ans: 2, exp: "任务规划的主要目标是在考虑无人机的性能、到达时间、耗能、威胁以及飞行区域等 约束条件的基础上，依据地形信息和执行任务的环境条件信息，为无人机规划出一条或多条 从出发点到目标点的最优或次优航迹。这样的规划确保无人机能够高效、圆满地完成飞行任 务，并安全返回基地。" },
  { id: 406, cat: "任务规划", q: "任务规划时还要考虑（），即应急航线", opts: ["紧急迫降措施", "安全返航措施", "异常应急措施"], ans: 2, exp: "任务规划系统的功能包括航迹规划、任务分配规划、数据链路规划和应急处置规划等。 其中，应急处置规划涉及到规划不同任务阶段时的突发情况处置，有针对性地规划应急航路、返航航路、备降机场及应急处置等内容。因此，任务规划时需要考虑的应急航线，即紧急情 况下的飞行路径，是任务规划的重要组成部分。" },
  { id: 407, cat: "任务规划", q: "任务规划由（）等组成", opts: ["任务接收、姿态控制、载荷分配、航迹规划、航迹调整和航迹评价", "任务理解、环境评估、任务分配、航迹规划、航迹优化和航迹评价", "任务分配、姿态控制、导航控制、航迹规划、航迹调整和航迹评价"], ans: 1, exp: "任务规划是无人机执行任务前的重要步骤，它涉及到多个组成部分。任务规划由任务 理解、环境评估、任务分配、航迹规划、航迹优化和航迹评价等组成。这些组成部分共同确 保无人机能够根据任务要求和环境条件，规划出一条或多条最优或次优的航迹，以完成飞行 任务并安全返回基地。" },
  { id: 408, cat: "任务规划", q: "图元标注主要包含以下三方面信息（）", opts: ["坐标标注、航向标注、载荷任务标注", "场地标注、警示标注、任务区域标注", "航程标注、航时标注、任务类型标注"], ans: 1, exp: "图元标注主要用于无人机或航空任务中，标注场地、警示区域和任务区域，确保飞行 安全和任务执行。B 选项准确涵盖了这三类关键信息。" },
  { id: 409, cat: "任务规划", q: "无人机（）是指根据无人机需要完成的任务、无人机的数量以及携带任务载荷的类型，对无人机制定飞行路线并进行任务分配。", opts: ["航迹规划", "任务规划", "飞行规划"], ans: 1, exp: "无人机任务规划是指根据无人机需要完成的任务、无人机的数量以及携带任务载荷的 类型，对无人机制定飞行路线并进行任务分配。任务规划的主要目标是依据地形信息和执行 任务的环境条件信息，综合考虑无人机的性能、到达时间、耗能、威胁以及飞行区域等约束 条件，为无人机规划出一条或多条自出发点到目标点的最优或次优航迹，保证无人机高效、圆满地完成飞行任务，并安全返回基地。" },
  { id: 410, cat: "任务规划", q: "无人机飞行操作员在飞行时最应关注的是哪一区域？（）", opts: ["飞行航迹", "地平仪", "遥控指令区"], ans: 1, exp: "无人机飞行操作员在飞行时最应关注的是地平仪区域。地平仪（也称为姿态指示器）是飞行操作员监控无人机姿态的关键仪表，它显示了无人机相对于水平面的姿态角度，包括 俯仰（pitch）和滚转（roll）。这些信息对于操作员来说至关重要，因为它们直接关系到无 人机的飞行安全和稳定性。" },
  { id: 411, cat: "任务规划", q: "无人机航迹规划需要综合应用（），以获得全面详细的无人机飞行现状以及环境信息，结合无人机自身技术指标特点，按照一定的航迹规划方法，制定最优或次优路径。", opts: ["导航技术、地理信息技术以及远程感知技术", "飞控技术、导航技术以及地理信息技术", "导航技术、航迹优化算法以及地理信息技术"], ans: 0, exp: "无人机航迹规划需要综合应用导航技术、地理信息技术以及远程感知技术，以获得全 面详细的无人机飞行现状以及环境信息，结合无人机自身技术指标特点，按照一定的航迹规 划方法，制定最优或次优路径。" },
  { id: 412, cat: "任务规划", q: "无人机具体执行的飞行任务主要包括到达时间和进入目标方向等，需满足如下要求（）", opts: ["航迹距离约束，固定的目标进入方向", "执行任务时间，进入目标位置", "返航时间，接近目标的飞行姿态"], ans: 0, exp: "无人机飞行任务需满足航迹距离限制和精确的目标进入方向要求，确保飞行路径和攻 击角度的准确性，A 项完整涵盖这两点核心要求。" },
  { id: 413, cat: "任务规划", q: "无人机任务规划是实现（）效途径，它在很大程度上决定了无人机执行任务的效率。", opts: ["自主导航与飞行控制", "飞行任务与载荷匹配", "航迹规划与自主导航"], ans: 0, exp: "无人机任务规划是实现自主导航与飞行控制的有效途径。任务规划不仅包括航迹规划，还涉及到无人机的飞行任务分配、飞行路径优化、飞行时间安排等多个方面。通过任务规 划，无人机可以在没有人为直接干预的情况下，根据预设的任务和环境信息，自主完成导航 和飞行控制，从而在很大程度上决定了无人机执行任务的效率和成功率。" },
  { id: 414, cat: "任务规划", q: "无人机任务规划需要考虑的因素有（），（）无人机物理限制，实时性要求。", opts: ["飞行环境限制，飞行任务要求", "飞行任务范围，飞行安全限制", "飞行安全限制，飞行任务要求"], ans: 0, exp: "无人机任务规划需要考虑的因素包括飞行环境限制和飞行任务要求，以及无人机物理 限制和实时性要求。" },
  { id: 415, cat: "任务规划", q: "无人机任务规划需要实现的功能包括（）", opts: ["自主导航功能，应急处理功能，航迹规划功能", "任务分配功能，航迹规划功能，仿真演示功能", "自主导航功能，自主起降功能，航迹规划功能"], ans: 1, exp: "无人机任务规划需要实现的功能包括任务分配功能、航迹规划功能和仿真演示功能。 任务分配功能涉及到无人机的任务指派和资源管理；航迹规划功能确保无人机按照既定路线 安全、高效地飞行；仿真演示功能则允许操作员在实际飞行前模拟和验证飞行任务，以检查 规划的合理性和可行性。" },
  { id: 416, cat: "任务规划", q: "无人机物理限制对飞行航迹有以下限制（），最小航迹长度，最低安全飞行高度", opts: ["最大转弯半径，最小俯仰角", "最小转弯半径，最小俯仰角", "最小转弯半径，最大俯仰角"], ans: 2, exp: "无人机物理限制对飞行航迹的限制主要包括最小转弯半径、最大俯仰角、最小航迹段 长度和最低安全飞行高度等。这些限制条件确保无人机在执行飞行任务时能够安全、有效地 飞行。" },
  { id: 417, cat: "任务规划", q: "无人机在特定区域内执行任务时，（）", opts: ["不需要对该区域地图进行校准", "只需首次对该区域地图进行校准", "需要每次对该区域地图进行校准"], ans: 1, exp: "无人机在特定区域内执行任务时，需要对地图进行校准以确保飞行的准确性和安全性。 无人机地图校准是一个重要的步骤，它涉及到地面控制点的设置和使用，以及影像数据的几 何校正。在校准过程中，通常需要使用地面控制点来验证测量精度，并确保无人机获取的数 据具有足够的精度。因此，无人机在特定区域内执行任务时，只需首次对该区域地图进行校 准，以确保后续飞行的准确性。" },
  { id: 418, cat: "任务规划", q: "下列哪一项是飞行重规划要考虑的内容？（）", opts: ["已知威胁区域", "未知威胁区域", "无人机自身约束条件"], ans: 1, exp: "飞行重规划要考虑未知威胁区域。当遇到未知威胁区域时，需要对飞行路径进行重新 规划以避开这些威胁。已知威胁区域在初始规划时通常就会考虑，而无人机自身约束条件在 初始规划和重规划中都会考虑，但不是飞行重规划特有的主要考虑内容。" },
  { id: 419, cat: "任务规划", q: "下列哪种感觉是无人机操纵员在操纵无人机时无法感知的？（）", opts: ["视觉", "听觉", "前庭觉"], ans: 2, exp: "无人机操纵员在操纵无人机时无法感知的是前庭觉。前庭觉与身体平衡和位置感知相 关，是内部感觉，而无人机操纵员主要通过视觉和听觉来感知无人机的状态和周围环境。" },
  { id: 420, cat: "任务规划", q: "下列哪种规划是任务规划的主体核心？（）", opts: ["任务分配规划", "航迹规划", "应急预案规划"], ans: 1, exp: "航迹规划在无人机任务规划中占据核心地位，它涉及到在无人机避开限制风险区域及 耗油最小的原则上指定无人机的起飞、着陆、接近监测点、监测区域、离开监测点、返航及 应急飞行等任务过程中的飞行航迹。规划无人机从起始点到目标点的航路，并对规划出的航 路进行检验，确保规划的航路可实现性和具备良好的安全性。" },
  { id: 421, cat: "任务规划", q: "下列哪种控制方式不属于无人机仪表飞行？（）", opts: ["自主控制", "姿态遥控", "舵面遥控"], ans: 0, exp: "无人机的仪表飞行控制方式主要包括姿态遥控和舵面遥控。自主控制不属于仪表飞行 控制方式，它通常指的是无人机根据预设程序或机载计算机指令自主执行飞行任务的能力，而不是通过遥控方式进行的飞行控制。" },
  { id: 422, cat: "任务规划", q: "下列哪种卫星导航系统是由俄罗斯构建的？（）", opts: ["GPS", "格洛纳斯", "伽利略"], ans: 1, exp: "俄罗斯构建的卫星导航系统是格洛纳斯（GLONASS）。GPS 由美国开发，伽利略由欧盟 主导。因此正确答案为 B。" },
  { id: 423, cat: "任务规划", q: "下列哪种信息不是 gps 发送的？（）", opts: ["经纬度", "高程", "空速"], ans: 2, exp: "GPS（全球定位系统）主要提供位置和时间信息，包括经纬度和高程（海拔高度）。空 速是指飞行器相对于空气的速度，这个信息通常由飞行器上其他传感器（如皮托管）测量得 到，而不是由 GPS 直接发送的。" },
  { id: 424, cat: "任务规划", q: "相比于夏天，冬天的时候飞机的飞行时间变长还是缩短？（不考虑电池原因，只看气压 对飞行时间的影响）（）", opts: ["夏天飞行时间长", "冬天飞行时间长", "一样长，气压的变化对飞机飞行时长没有影响"], ans: 1, exp: "冬天飞机的飞行时间相对夏天较长。一般来说，冬天的气压比夏天高。在较高气压环 境下，空气密度较大，飞机飞行时升力相对较大，相同情况下所需的动力可以相对减小，从 而在一定程度上可以使飞行时间变长。" },
  { id: 425, cat: "任务规划", q: "校准地图时选取的校准点（）", opts: ["不能在同一直线上", "不能在同一纬度上", "不能在同一经度上"], ans: 0, exp: "在校准地图时，选取的校准点需要能够提供足够的空间信息以确定地图的准确位置和 姿态。如果校准点都在同一直线上，那么将无法准确确定地图的旋转和倾斜，因此需要选取 不在同一直线上的点以确保能够准确校准地图。" },
  { id: 426, cat: "任务规划", q: "以下桨叶数量不属于多旋翼无人机的是哪个？（）", opts: ["两个", "三个", "四个"], ans: 0, exp: "多旋翼无人机通常指的是具有多个旋转翼的无人机，这些翼的数量通常是奇数或者至 少是四个，以确保无人机能够在空中保持稳定。两个桨叶的无人机一般属于固定翼无人机或 者单旋翼带尾桨的直升机类型，不属于多旋翼无人机范畴。多旋翼无人机是指具有三个及以 上旋翼轴的直升机。" },
  { id: 427, cat: "任务规划", q: "以下正确的任务规划流程是（）", opts: ["接受任务-任务理解-环境评估-任务分配-航迹规划-航迹优化-生产计划", "接受任务-任务理解-任务分配-环境评估-航迹规划-航迹优化-生产计划", "接受任务-任务理解-任务分配-航迹规划-环境评估-航迹优化-生产计划"], ans: 0, exp: "正确的任务规划流程应该是首先接受任务，然后对任务进行理解，接着进行环境评估 以了解执行任务时可能面临的环境因素，之后进行任务分配，确定各个任务的具体责任和要 求。接下来是航迹规划，制定无人机的飞行路线，然后进行航迹优化，以确保飞行路线的效 率和安全性。最后，生产计划，将所有信息整合并制定出最终的执行计划。" },
  { id: 428, cat: "任务规划", q: "应急航线的主要目的是确保飞机安全返航，规划一条安全返航通道和（），以及（）", opts: ["安全着陆点，安全着陆策略", "应急迫降点，航线转移策略", "应急迫降点，安全返航策略"], ans: 1, exp: "应急航线是为了在飞行过程中遇到紧急情况时，确保飞机能够安全返航而规划的备用 航线。它包括规划一条安全返航通道，以及在必要时使用应急迫降点，并采取航线转移策略 以应对突发状况。应急迫降点是预先确定的，可以在紧急情况下使用的安全降落地点，而航 线转移策略则是在遇到不可预见的情况时，如何从当前航线转移到安全航线的计划。" },
  { id: 429, cat: "任务规划", q: "由于加载的电子地图与实际操作时的地理位置信息有偏差，需要在使用前对地图进行（）", opts: ["标注", "更新", "校准"], ans: 2, exp: "由于电子地图与实际地理位置之间可能存在偏差，为了确保地图数据的准确性和可靠 性，需要对地图进行校准，以匹配实际的地理坐标系统。校准过程通常涉及调整地图的位置、旋转和缩放，以确保地图上的特征与现实世界中的位置相匹配。" },
  { id: 430, cat: "任务规划", q: "在飞行任务书中，应当明确（）", opts: ["飞行任务、起飞时间、航线、高度、允许机长飞行的最低气象条件以及其他有关事项", "飞行任务、机组成员、起飞时间、航线、高度、允许机长飞行的最低气象条件以及其他 有关事项", "飞行任务、起飞时间、航线、允许机长飞行的最低气象条件以及其他有关事项"], ans: 0, exp: "在飞行任务书中，需要包含的关键信息包括飞行任务的具体内容、起飞时间、航线、飞行高度、允许机长飞行的最低气象条件以及其他可能影响飞行安全和任务执行的相关事项。 这些信息对于确保飞行安全和任务的顺利进行至关重要。" },
  { id: 431, cat: "任务规划", q: "指令信息不包括（）", opts: ["发送代码", "发送状态", "接收状态"], ans: 0, exp: "指令信息通常包含关于发送状态和接收状态的信息，以确保信息的传递是有效的，并 且可以跟踪。发送代码本身并不是指令信息的一部分，而是用于执行特定操作的代码或指令。" },
  // ==================== 多旋翼动力飞控 ====================
  { id: 432, cat: "多旋翼动力飞控", q: "6S 4P 12000mAh 3C 锂电池最大电流是多少？（）", opts: ["36A", "3.6A", "360A"], ans: 0, exp: "对于锂电池，其最大放电电流通常可以通过容量和放电倍率（C 值）来计算。题目中 给出的是 3C 锂电池，容量为 12000mAh（12Ah）。3C 意味着最大放电电流是容量的 3 倍，即 12Ah×3=36A。" },
  { id: 433, cat: "多旋翼动力飞控", q: "KV1000 的无刷电机搭配 11.1V 电池，空载转速是（）", opts: ["1110 转/分", "1110 转/秒", "11100 转/分"], ans: 2, exp: "电机的空载转速可以通过公式“电机 KV 值×电压=空载转速”来计算。题目中电机 KV 值为 1000，电池电压为 11.1V，那么空载转速为 1000×11.1=11100 转/分。" },
  { id: 434, cat: "多旋翼动力飞控", q: "八轴飞行器安装有（）", opts: ["8 个顺时针旋转螺旋桨", "2 个顺时针旋转螺旋桨，6 个逆时针旋转螺旋桨", "4 个顺时针旋转螺旋桨，4 个逆时针旋转螺旋桨"], ans: 2, exp: "八轴飞行器，四正四反桨，稳定又可靠。八轴飞行器要保持平衡和稳定飞行，其螺旋 桨的旋转方向需要相互配合。一般来说，会安装 4 个顺时针旋转螺旋桨和 4 个逆时针旋转螺 旋桨，这样可以在飞行过程中抵消扭矩，保持飞行器的稳定。" },
  { id: 435, cat: "多旋翼动力飞控", q: "八轴飞行器某个电机发生故障时，对应做出类似停止工作的电机应是（）电机", opts: ["对角", "俯视顺时针方向下一个", "俯视顺时针方向下下一个"], ans: 0, exp: "八轴飞行器在设计时会考虑到动力系统的冗余，以确保在某个电机发生故障时，飞行 器仍然能够保持稳定飞行或安全降落。当一个电机发生故障时，为了保持飞行器的平衡，通 常会停止与其相对的对角线上的电机的工作，这样可以最大程度地减少对飞行器平衡的影响。 因此，当八轴飞行器某个电机发生故障时，对应做出类似停止工作的电机应是对角电机。" },
  { id: 436, cat: "多旋翼动力飞控", q: "标有 60A 的电调中，选用多大的电池合适？（）", opts: ["等于 60A", "小于 60A", "大于 60A <"], ans: 2, exp: "电调（电子调速器）的标称电流（如 60A）表示其可持续工作的最大电流。为确保电 调在峰值负载下稳定运行，电池的最大放电电流（即容量×放电倍率 C）应大于电调的标称 电流。" },
  { id: 437, cat: "多旋翼动力飞控", q: "部分多轴飞行器螺旋桨根部标有“CCW”字样，其意义为（）", opts: ["此螺旋桨由 CCW 公司生产", "此螺旋桨为顶视顺时针旋转", "此螺旋桨为顶视逆时针旋转"], ans: 2, exp: "在多轴飞行器中，螺旋桨的旋转方向对于飞行器的平衡和性能至关重要。“CCW”是 “CounterClockwise”的缩写，意为逆时针方向。 因此，当螺旋桨根部标有“CCW”字样时，表示该螺旋桨在顶视图下是逆时针旋转的。这对 于正确安装螺旋桨和保持飞行器的协调性非常重要。" },
  { id: 438, cat: "多旋翼动力飞控", q: "常规的电子调速器上，中等粗细的几根线是用来连接（）的", opts: ["自驾仪或遥控接收机", "电池", "电机"], ans: 2, exp: "在常规的电子调速器（ESC）上，中等粗细的几根线是用于连接电机的。这些线负责 将电调的控制信号和电源传递给电机，以控制电机的转速和方向。" },
  { id: 439, cat: "多旋翼动力飞控", q: "导线在同一处损伤导致强度损失未超过总拉断力的 5%，且截面积损伤未超过总导电部分 截面积的 7%；钢绞线或铝合金绞线断损伤截面不超过总截面的 7%：镀锌钢绞线 19 股断 1 股；OPGW 断股损伤截面不超过总截面积的 7%（光纤单元未损伤）属于（）", opts: ["其他缺陷", "一般缺陷", "重大缺陷"], ans: 1, exp: "导线损伤的程度被分为几类，其中 Ⅰ类损伤指的是导（地）线损伤占总截面积的 7% 及以下。在题目中描述的情况，导线在同一处损伤导致强度损失未超过总拉断力的 5%，且 截面积损伤未超过总导电部分截面积的 7%；钢绞线或铝合金绞线断损伤截面不超过总截面 的 7%；镀锌钢绞线 19 股断 1 股；OPGW 断股损伤截面不超过总截面积的 7%（光纤单元未损 伤），这些情况均符合 Ⅰ类损伤的定义，即一般缺陷。" },
  { id: 440, cat: "多旋翼动力飞控", q: "地线根据绞层数，断股数达到（绞层数-1）时（单层除外），属于（）", opts: ["其他缺陷", "一般缺陷", "重大缺陷"], ans: 2, exp: "当地线断股数达到（绞层数-1）时（单层除外），这种情况较为严重，属于重大缺陷。" },
  { id: 441, cat: "多旋翼动力飞控", q: "电调的作用不包括哪些？（）", opts: ["直流电变交流电", "改变电机转速", "改变电流大小"], ans: 2, exp: "【请注意：题干问的是不包括哪些？】电调调速、直流变交流，不直接改电流。电调（电子 调速器）的主要作用包括： 1.改变电机转，：通过调节输入电机的电流和电压，控制电机的转速。 2.直流电变交流电：电调可以将电池提供的直流电转换为三相交流电，驱动无刷电机工作。 而改变电流大小并不是电调的直接作用，电流大小的变化是电调在调节转速或电压时的间接 结果。因此，电调的作用不包括。" },
  { id: 442, cat: "多旋翼动力飞控", q: "电调上最粗的红线和黑线用来连接（）", opts: ["动力电池", "电动机", "机载遥控接收机"], ans: 0, exp: "电调（电子调速器，ESC）的输入线最粗的红线和黑线是用来连接动力电池的。这两 根线负责将电池的直流电能输入到电调中，电调根据飞控系统的控制信号，调节电机的转速，从而控制飞行器的动力输出。因此，电调的红线和黑线连接动力电池是其正常工作的基础。" },
  { id: 443, cat: "多旋翼动力飞控", q: "电调是多旋翼无人机最重要的部件之一，不属于飞行器电调功能的是（）", opts: ["变压供电", "调节电机转速", "实现电机反转"], ans: 2, exp: "电调（电子调速器）的主要功能包括变压供电和调节电机转速。变压供电是指电调将 电池的电压转换为适合电机工作的电压，调节电机转速是指电调根据遥控器的信号来调整电 机的转速。而实现电机反转并不是电调的直接功能，电机的转向是由电机的接线方式决定的，通过改变电机三相线圈的相序来实现反转。" },
  { id: 444, cat: "多旋翼动力飞控", q: "电子调速器英文缩写是（）", opts: ["BEC", "ESC", "MCS"], ans: 1, exp: "电子调速器的英文缩写是 ESC（Electronic Speed Controller）。它是一种用于控制电 动机转速的设备，广泛应用于遥控模型、无人机等电动驱动系统中。ESC 接收来自遥控器或 飞控系统的信号，并根据这些信号调整电动机的功率输出，从而控制电动机的转速。" },
  { id: 445, cat: "多旋翼动力飞控", q: "对于多轴飞行器，（）", opts: ["旋翼只起升力面的作用", "旋翼只充当纵横向和航向的操纵面", "旋翼既是升力面又是纵横向和航向的操纵面"], ans: 2, exp: "对于多轴飞行器，旋翼的作用不仅仅是提供升力，它们还负责飞行器的控制。在多轴 飞行器中，旋翼通过改变转速来产生不同的力和力矩，从而控制飞行器的升降、前后、左右 移动以及旋转，实现了升力面和操纵面的功能。" },
  { id: 446, cat: "多旋翼动力飞控", q: "对于多轴飞行器电源充足，以下哪种充电方法是错误的？（）", opts: ["聚合物锂电池单体充至 4.6V 满电", "聚合物锂电池单体充至 4.2V 满电", "磷酸铁锂电池单体充至 3.6V 满电"], ans: 0, exp: "对于多轴飞行器动力电源充电，错误的充电方法是将聚合物锂电池单体充至 4.6V 满 电。根据锂离子电池的充电标准，聚合物锂电池单体的满电电压通常不应超过 4.2V，而 4.6V 超出了安全电压范围，可能会导致电池过充、损坏甚至发生安全事故。" },
  { id: 447, cat: "多旋翼动力飞控", q: "对于混合燃油发电机，冬天的燃油，机油混合比针对夏天应如何调整？（）", opts: ["燃油机油混合比适量增大", "燃油机油混合比适量减小", "燃油机油混合比不变"], ans: 0, exp: "冬天气温低，汽油容易凝结，因此需要增加发动机的热效率来给机件更好的润滑、冷 却效果，使汽油保持良好汽化状态工作平稳不容易熄火。所以在冬季，混合燃油发电机的燃 油机油混合比应该适量增大，以适应低温环境，保护机器防止由于天气寒冷造成的机械磨损。" },
  { id: 448, cat: "多旋翼动力飞控", q: "多旋翼飞行器的旋翼旋转方向一般为（）", opts: ["俯视多旋翼飞行器顺时针旋翼", "俯视顺时针/逆时针旋翼相对排布", "俯视顺时针/逆时针旋翼依次相邻排布"], ans: 2, exp: "多旋翼飞行器的旋翼旋转方向通常为俯视顺时针/逆时针旋翼依次相邻排布。这种排 列方式有助于抵消旋翼旋转产生的反扭矩，保持飞行器的稳定性。在多旋翼飞行器中，相邻 的旋翼通常一个顺时针旋转，另一个逆时针旋转，以此来平衡力矩。" },
  { id: 449, cat: "多旋翼动力飞控", q: "多轴飞行器，电调和电机一般通过 3 根单色线连接，如任意调换其中 2 根与电机的连接 顺序，会出现（）", opts: ["该电机停转", "该电机出现过热并烧毁", "该电机反向运转"], ans: 2, exp: "多轴飞行器的电调和电机一般通过 3 根单色线连接。如果任意调换其中 2 根与电机的 连接顺序，会导致电机的转向改变。这是因为电机的转向是由电调输出的三相交流电的相序 决定的，改变任意两根线的连接顺序会改变相序，从而改变电机的转向。" },
  { id: 450, cat: "多旋翼动力飞控", q: "冷锋是指（）", opts: ["冷气团主动向暖气团移动形成的锋", "一侧气团温度明显低于另一侧气团温度的锋", "温度较高与温度较低的两个气团交汇时，温度低的一侧"], ans: 0, exp: "冷锋是指冷气团主动向暖气团移动形成的锋面。 在气象学中，锋面是两种不同性质的气团相遇时形成的边界，而冷锋特指冷气团推动暖气团，形成的天气现象。这种锋面过境时，通常会带来气温下降、气压上升和天气变化，如降雨或 雪。" },
  { id: 451, cat: "多旋翼动力飞控", q: "多轴飞行器常用螺旋桨的剖面形状是（）", opts: ["对称型", "凹凸型", "S 型"], ans: 1, exp: "多轴螺旋看剖面，凹凸形状最常见。多轴飞行器常用螺旋桨的剖面形状是凹凸型。这 种形状的螺旋桨在旋转时能够产生足够的升力，同时具有较好的空气动力学性能。" },
  { id: 452, cat: "多旋翼动力飞控", q: "多轴飞行器的飞控硬件尽量安装在（）", opts: ["飞行器前部", "飞行器底部", "飞行器中心"], ans: 2, exp: "多轴飞行器的飞控硬件应尽可能安装在靠近载具重力中心（CoG）的位置，以确保飞 行的稳定性和减少振动对飞控系统的影响。这是因为飞控硬件中的 IMU（惯性测量单元）对 振动非常敏感，而振动会影响 IU 的精确度，进而影响飞行器的飞行性能。" },
  { id: 453, cat: "多旋翼动力飞控", q: "多轴飞行器的螺旋桨，（）", opts: ["桨根处迎角小于桨尖处迎角", "桨根处迎角大于桨尖处迎角", "桨根处迎角等于桨尖处迎角"], ans: 1, exp: "多轴飞行器的螺旋桨设计中，桨根处的迎角大于桨尖处的迎角。这种设计主要是为了 提高多轴飞行器的稳定性和操控性。在多轴飞行器的飞行过程中，螺旋桨桨叶受到的气流作 用力是不均匀的，桨尖处的气流速度较高，而桨根处的气流速度较低。因此，如果螺旋桨桨 根处和桨尖处的迎角相同，那么桨根处的升力会比桨尖处的升力小，从而导致多轴飞行器产 生倾斜和不稳定的现象。" },
  { id: 454, cat: "多旋翼动力飞控", q: "多轴飞行器的螺旋桨，（）", opts: ["桨根处线速度小于桨尖处线速度", "桨根处线速度大于桨尖处线速度", "桨根处线速度等于桨尖处线速度"], ans: 0, exp: "在多轴飞行器的螺旋桨中，桨根（即靠近电机轴的部分）的线速度小于桨尖（即螺旋 桨的外缘）的线速度。这是因为螺旋桨的旋转是围绕中心轴进行的，所以桨尖的圆周路径比 桨根的路径要长，导致桨尖的线速度更高。这种速度分布对于螺旋桨的升力和效率是至关重 要的。" },
  { id: 455, cat: "多旋翼动力飞控", q: "多轴飞行器的螺旋桨，（）", opts: ["桨根处升力系数小于桨尖处升力系数", "桨根处升力系数大于桨尖处升力系数", "桨根处升力系数等于桨尖处升力系数"], ans: 1, exp: "多轴飞行器的螺旋桨设计中，桨根处的升力系数大于桨尖处的升力系数。这是因为螺 旋桨的螺距，即螺旋桨旋转一周上升的距离，与升力系数有关。在螺旋桨的侧面观察，桨根 处的面较高，桨尖处的面较平，这意味着较高的面旋转一周上升的距离大于较平的面，因此 桨根处的升力系数大于桨尖处的升力系数。" },
  { id: 456, cat: "多旋翼动力飞控", q: "多轴飞行器的旋翼旋转方向一般为（）", opts: ["俯视多轴飞行器顺时针旋翼", "俯视多轴飞行器逆时针旋翼", "俯视多轴飞行器两两对应"], ans: 2, exp: "多轴飞行器的旋翼旋转方向通常是两两对应的，即对面的旋翼旋转方向相反。这样的 设计是为了抵消旋翼旋转产生的反扭矩，保持飞行器的稳定性。例如，在四轴飞行器中，一 个旋翼顺时针旋转，而直接对面的旋翼逆时针旋转，另外两个旋翼的旋转方向与前两个相反。" },
  { id: 457, cat: "多旋翼动力飞控", q: "多轴飞行器动力电池充电尽量选用（）", opts: ["便携充电器", "快速充电器", "平衡充电器"], ans: 2, exp: "多轴飞行器动力电池充电尽量选用平衡充电器。 平衡充电器可以对电池组中的每一节单体电池进行独立充电管理，确保各单体电池的电压均 衡，延长电池寿命，提高电池的使用安全性。便携充电器和快速充电器可能无法做到对电池 的精细平衡充电管理。" },
  { id: 458, cat: "多旋翼动力飞控", q: "多轴飞行器动力系统主要使用（）", opts: ["无刷电机", "有刷电机", "四冲程发动机"], ans: 0, exp: "多轴飞行器动力系统主要使用无刷电机。无刷电机具有效率高、寿命长、可靠性强、功率密度大等优点，非常适合多轴飞行器这种对动力系统要求较高的飞行器。有刷电机效率 较低、寿命较短，不适合多轴飞行器。四冲程发动机体积大、重量重、结构复杂，也不适合 多轴飞行器。" },
  { id: 459, cat: "多旋翼动力飞控", q: "多轴飞行器动力系统主要使用（）", opts: ["步进电机", "内转子电机", "外转子电机"], ans: 2, exp: "多轴飞行器动力系统主要使用的是外转子电机。 外转子电机相较于内转子电机，可以提供更大的力矩，更容易驱动大螺旋桨以获得更高效率，且速度更稳定，因此更适用于多旋翼飞行器。" },
  { id: 460, cat: "多旋翼动力飞控", q: "多轴飞行器动力装置多为电动系统的最主要的原因是（）", opts: ["电动系统尺寸较小且较为廉价", "电动系统形式简单且电机速度响应快", "电动系统干净且不依赖传统生物燃料"], ans: 1, exp: "多轴飞行器动力装置多电动系统的最主要原因是电动系统形式简单且电机速度响应快。 电动系统相对结构简单，容易安装和维护。同时，电机的速度响应非常快，可以根据飞行控 制的指令迅速调整转速，满足多轴飞行器灵活飞行的要求。" },
  { id: 461, cat: "多旋翼动力飞控", q: "多轴飞行器飞控计算的功能不包括（）", opts: ["稳定飞行器姿态", "接收地面控制信号", "导航"], ans: 1, exp: "飞控计算机是多轴飞行器的核心部件，主要负责稳定飞行器姿态、实现自主导航和执 行飞行控制任务。而接收地面控制信号通常是由遥控器或地面控制站通过无线数据链完成的，这部分功能并不直接集成在飞控计算机内部，而是通过外部通信接口实现的。" },
  { id: 462, cat: "多旋翼动力飞控", q: "多轴飞行器控制电机转速的直接设备为（）", opts: ["电源", "电调", "飞控"], ans: 1, exp: "多轴飞行器中，控制电机转速的直接设备是电子调速器 （ESC,Electronic Speed Controller）。电调接收飞控计算机的控制信号，根据这些信号调整 供给电机的电能，从而精确控制电机的转速。电源仅提供电能，而飞控负责发送控制指令，但不是直接控制电机转速的设备。" },
  { id: 463, cat: "多旋翼动力飞控", q: "多轴飞行器螺旋桨从结构上说，更接近于（）", opts: ["风力发电机叶片", "直升机旋翼", "固定翼飞机螺旋桨"], ans: 2, exp: "多轴飞行器的螺旋桨从结构上说，更接近于固定翼飞机的螺旋桨。它们都是通过旋转 来产生推力或升力的装置，尽管在设计和使用上有所不同。 多轴飞行器的螺旋桨通常较轻且转速较高，而固定翼飞机的螺旋桨则更大、更重，转速较低。 相比之下，直升机旋翼在结构和工作原理上与多轴飞行器螺旋桨差异较大，直升机旋翼需要 产生升力并进行复杂的空中操控。" },
  { id: 464, cat: "多旋翼动力飞控", q: "多轴飞行器每个“轴”上，一般连接（）", opts: ["1 个电调，1 个电机", "2 个电调，1 个电机", "1 个电调，2 个电机"], ans: 0, exp: "在多轴飞行器中，每个“轴”上通常连接一个电调和一个电机。电调（电子调速器）负责控制电机的转速，而电机则负责驱动螺旋桨旋转，从而产生推力和控制力矩。这种配置 可以确保每个轴的独立控制，提高飞行器的操控性和稳定性。" },
  { id: 465, cat: "多旋翼动力飞控", q: "多轴飞行器上的电信号传播顺序一般为（）", opts: ["飞控-机载遥控接收机-电机-电调", "机载遥控接收机-飞控-电调-电机", "飞控-电调-机载遥控接收机-电机"], ans: 1, exp: "多轴飞行器上的电信号传播顺序一般为机载遥控接收机接收控制信号，将信号传播给 飞控进行处理运算，再将处理好的信号传给电调，通过电调控制电机转速，最终实现多轴飞 行器的飞行控制。因此，正确的顺序是机载遥控接收机一飞控一电调一电机。" },
  { id: 466, cat: "多旋翼动力飞控", q: "多轴飞行器的链路天线应尽量（）飞控和 GPS 天线安装", opts: ["贴合", "靠近", "远离"], ans: 2, exp: "多轴飞行器上的链路天线应尽量远离飞控和 GPS 天线安装，以避免信号干扰。飞控系 统和 GPS 天线对信号的纯净度要求较高，如果链路天线距离过近，可能会产生电磁干扰，影 响飞行控制和定位的准确性。" },
  { id: 467, cat: "多旋翼动力飞控", q: "多轴飞行器使用的电调通常被划分为（）", opts: ["有刷电调和无刷电调", "直流电调和交流电调", "有极电调和无极电调"], ans: 0, exp: "多轴飞行器使用的电调通常被划分为有刷电调和无刷电调。这是因为电调根据电机的 不同可以分为有刷电调和无刷电调，有刷电调输出直流电，而无刷电调输出三相交流电。" },
  { id: 468, cat: "多旋翼动力飞控", q: "多轴飞行器使用的电调一般为（）", opts: ["双向电调", "有刷电调", "无刷电调"], ans: 2, exp: "多轴飞行器使用的电调一般为无刷电调。无刷电调（ESC,Electronic Speed Controller）是专为无刷电机设计的，它接收飞控系统的信号来驱动电机运转，并且能够调整电机的转速。 无刷电调将直流电转化为三相交流电，通过控制电机的三相绕组的电流来实现对电机转速的 精确控制。这对于多轴飞行器的稳定飞行和操控是非常重要的。" },
  { id: 469, cat: "多旋翼动力飞控", q: "多轴飞行器使用的动力电池一般为（）", opts: ["Li-po（锂聚合物电池）", "铅酸电池", "zinc（银锌电池）"], ans: 0, exp: "多轴飞行器使用的动力电池一般为锂聚合物电池（Li-po）。锂聚合物电池因其高能量 密度、小型化和重量轻的特点，在多轴飞行器中得到广泛应用。它们可以制造成各种形状和 尺寸，非常适合空间有限和设计要求复杂的设备，如无人机。" },
  { id: 470, cat: "多旋翼动力飞控", q: "多轴飞行器使用的锂聚合物动力电池，其单体标称电压为（）", opts: ["1.2V", "11.1V", "3.7V"], ans: 2, exp: "多轴飞行器使用的锂聚合物动力电池，其单体标称电压为 3.7V。这是锂聚合物电池 的标准参数之一，对于电池的性能和使用具有重要意义。" },
  { id: 471, cat: "多旋翼动力飞控", q: "多轴飞行器中的 GPS 天线应尽量安装在（）", opts: ["飞行器顶部", "飞行器中心", "飞行器尾部"], ans: 0, exp: "GPS 天线安装，顶部无遮挡，信号接收好。多轴飞行器中的 GPS 天线应尽量安装在飞 行器顶部，无遮挡的位置。这样的安装位置有助于确保 GPS 天线能够获得最佳的天空视野，从而接收到更强、更稳定的卫星信号。" },
  { id: 472, cat: "多旋翼动力飞控", q: "多轴飞行时地面人员手里拿的“控”指的是（）", opts: ["地面遥控发射机", "导航飞控系统", "链路系统"], ans: 0, exp: "多轴飞行器中的地面人员手里拿的“控”指的是地面遥控发射机，也就是我们通常所 说的遥控器。遥控器用于发射信号，以遥控飞机的飞行动作，包括油门、航向、俯仰和横滚 等基本飞行控制功能。" },
  { id: 473, cat: "多旋翼动力飞控", q: "多轴无人机，电调上较细的白红黑 3 色排线，也叫杜邦线，用来连接（）", opts: ["电机", "机载遥控接收机", "飞控"], ans: 2, exp: "电调上的三色杜邦线用于传输控制信号，需连接飞控（飞行控制器）以接收指令。电 机直接由电调供电驱动，接收机则与遥控器通讯，均非此线连接对象。" },
  { id: 474, cat: "多旋翼动力飞控", q: "关于多旋翼使用的无刷电调和有刷电调，说法正确的是（）", opts: ["无刷电调驱动直流电机，无法调速", "三相交流电机通过交流电调将电池直流变为交流作为电机输入", "有刷电调便于调速和驱动交流电机"], ans: 1, exp: "多轴飞行器使用的无刷电调和有刷电调的主要区别在于它们驱动的电机类型和电调的 功能。无刷电调负责将直流电转换为三相交流电，并根据需要控制其电压电流大小，从而驱 动无刷电机实现需要的转速输出。而有刷电调则输出直流电，用于驱动有刷电机。因此，正 确的说法是三相交流电机通过交流电调将电池直流变为交流作为电机输入。" },
  { id: 475, cat: "多旋翼动力飞控", q: "关于多轴飞行器机桨与电机匹配描述错误的是（）", opts: ["3S 电池下，KV900-1000 的电机配", "3S 电池下，KV1200-1400 配 3 寸桨", "2S 电池下，KV1300-1500 左右用 9050 浆"], ans: 1, exp: "1.3S 电池（11.1V）+KV900-1000 电机：适合搭配 10 英寸桨（如 1060 或 1047）。正确，低 KV 值电机配大桨是常见组合，适合低速高扭矩场景。 2.3S 电池+KV1200-1400 电机：通常搭配 5-6 英寸桨（如 5045 或 6040）。而配 3 寸桨，明显 错误，是本题答案。3 寸桨（如 3040）一般用于更高 KV（3000KV 以上）的小型电机。 3.2S 电池（7.4V）+KV1300-1500 电机：适合 9 英寸桨（如 9050）。正确，低电压下中高 KV 电机配中等尺寸桨合理。" },
  { id: 476, cat: "多旋翼动力飞控", q: "关于多轴飞行器机桨与电机匹配描述正确的是（）", opts: ["大螺旋桨要用低 kv 电机", "大螺旋桨要用高 kv 电机", "小螺旋桨要用低 kv 电机"], ans: 0, exp: "多轴飞行器的机桨与电机匹配是非常重要的，它直接影响到飞行器的飞行性能和效率。 大螺旋桨需要更多的扭力来推动飞行，而低 KV 值的电机可以提供更多的扭力。因此，大螺 旋桨应该使用低 KV 值的电机，这样可以在需要较大推力时保持稳定。" },
  { id: 477, cat: "多旋翼动力飞控", q: "关于多轴飞行器使用的动力电机 KV 值描述正确的是（）", opts: ["外加 1v 电压对应的每分钟负载转速", "外加 1v 电压对应的每分钟空载转速", "额定电压值时电机每分钟空载转速"], ans: 1, exp: "动力电机的 KV 值是指电机在空载情况下，每增加 1 伏特电压，电机转速增加的 RPM （转/分钟）数。这是一个描述电机转速与电压关系的参数，它反映了电机的转速特性，而 不是在负载下的性能。" },
  { id: 478, cat: "多旋翼动力飞控", q: "关于多轴使用的无刷电机与有刷电机，说法正确的是（）", opts: ["有刷电机驱动交流电机", "无刷电机驱动交流电机", "无刷电机驱动直流电机"], ans: 1, exp: "无刷电机通过电子换相驱动交流电机，效率高寿命长；有刷电机通过电刷换向驱动直 流电机，结构简单但寿命较短。无人机多采用无刷电机。" },
  { id: 479, cat: "多旋翼动力飞控", q: "经测试，某多轴飞行器稳定飞行时，动力电池的持续输出电流为 10 安培，该多轴可以 选用（）", opts: ["50A 的电调", "15A 的电调", "10A 的电调"], ans: 0, exp: "在选择电调时，一般要预留一定的电流余量，以确保在各种工况下电调都能稳定工作 且不会因瞬间电流增大而损坏。如果仅按照稳定飞行时的电流选择相同电流值的电调，当出 现加速、阵风等情况导致电流瞬间增大时，电调可能无法承受而损坏。各选项分析如下： 1.50A 的电调电流余量较大，能满足多轴飞行器的使用需求且较为可靠。 2.15A 的电调余量相对较小，可能在某些情况下无法满足需求。 3.10A 的电调没有余量，不适合选用。" },
  { id: 480, cat: "多旋翼动力飞控", q: "经测试，某多轴飞行器稳定飞行时，动力电池的持续输出电流为 5 安培，该多轴可以选 用（）", opts: ["5A 的电调", "10A 的电调", "30A 的电调"], ans: 2, exp: "在为多轴飞行器选择电调时，通常建议选择额定电流高于飞行器实际使用电流的电调，以确保电调不会因过载而损坏，并提供一定的安全余量。虽然飞行器稳定飞行时的持续输出 电流为 5 安培，但选择一个电流额定值更大的电调可以提供额外的安全保障，尤其是在飞行 器起飞、爬升或承载较重载荷时，这些情况下电流需求可能会增加。因此，选项中的 30A 电调符合这一要求。" },
  { id: 481, cat: "多旋翼动力飞控", q: "六轴飞行器安装有（）", opts: ["6 个顺时针旋转螺旋桨", "3 个顺时针旋转螺旋桨，3 个逆时针旋转螺旋桨", "4 个顺时针旋转螺旋桨，2 个逆时针旋转螺旋桨"], ans: 1, exp: "六轴飞行器，三正三反桨，平衡扭矩稳当当。六轴飞行器通常配置为 3 个顺时针旋转 的螺旋桨和 3 个逆时针旋转的螺旋桨。这种配置有助于平衡飞行器的扭矩，确保飞行器的稳 定性和操控性。" },
  { id: 482, cat: "多旋翼动力飞控", q: "六轴飞行器某个电机发生故障时，对应做出类似停止工作的电机应是（）电机", opts: ["俯视顺时针方向下一个", "对角", "俯视逆时针方向下一个"], ans: 1, exp: "在六轴飞行器中，当某个电机发生故障时，为了保持飞行器的平衡和稳定性，通常会 停止与其相对应的对角电机的工作。这是因为在多轴飞行器中，相对的电机在动力输出上是 相互平衡的，停止工作一个电机的同时，停止其对角电机可以减少因动力失衡导致的飞行器 失控风险。" },
  { id: 483, cat: "多旋翼动力飞控", q: "民用固定翼飞行中如何起飞？（）", opts: ["直接推杆离地", "原地垂直上升离地", "加速到一定程度后拉杆离地"], ans: 2, exp: "民用固定翼飞机的起飞过程通常涉及在跑道上加速，直到达到一定的起飞速度，然后 通过拉杆（抬轮）使飞机离地起飞。这个过程需要飞机达到足够的速度以产生足够的升力来克 服重力，使飞机升空。" },
  { id: 484, cat: "多旋翼动力飞控", q: "某多轴电调上标有“30A”字样，意思是指（）", opts: ["电调所能承受的最小工作电流是 30 安培", "电调所能承受的稳定工作电流是 30 安培", "电调所能承受的最大瞬间电流是 30 安培"], ans: 2, exp: "电调（ESC, Electronic Speed Controller）是多轴无人机的重要组件，用于控制电 机的转速和方向。电调上标注的电流值通常是指其能够承受的最大瞬间电流。 其他选项分析如下： 1.稳定工作电流是 30 安培：虽然电调可以在 30A 的电流下稳定工作，但标注的电流值通常是指其能够承受的最大瞬间电流。 2.最小工作电流：电调的标注电流值通常是指其能够承受的最大电流，而不是最小电流。 因此，结合多轴无人机电调的常见标注习惯，最大瞬间电流（峰值电流）更符合实际应用 场景。" },
  { id: 485, cat: "多旋翼动力飞控", q: "某多轴电调上有 BEC 5V 字样，意思是指（）", opts: ["电调需要从较粗的红线与黑线输入 5V 的电压", "电调能从较粗的红线与黑线向外输出 5V 的电压", "电调能从较细的红线与黑线向外输出 5V 的电压"], ans: 2, exp: "BEC 是 BatteryBliminationCircuit 的缩写，中文意思是免电池电路。它是一种内置 在电调中的电路模块，可以将电调的输入电压（通常是 12V）转换为 5V，为接收机和舵机等 电子设备提供稳定的电源。因此，当电调上标有“BEC5V”字样时，意味着电调能够通过较 细的红线与黑线向外输出 5V 的电压。" },
  { id: 486, cat: "多旋翼动力飞控", q: "某多轴电机上标有 1000KV 字样，意义是指（）", opts: ["对应每 V 电压，电机提供 1000000 转/分的转速", "对应每 V 电压，电机提供 1000 转/分的转速", "电机最大耐压 1000KV"], ans: 1, exp: "某多轴电机标有 1000KV 字样，意义是指对应每 V 电压，电机提供 1000 转/分的转速。这意 味着电机的转速与电压成正比，1000KV 表示在 1 伏特电压下，电机的空载转速为 1000 转/ 分钟。" },
  { id: 487, cat: "多旋翼动力飞控", q: "某多轴电机标有 2208 字样，意思是指（）", opts: ["该电机最大承受 22V 电压，最小承受 8V 电压", "该电机转子高度为 22 毫米", "该电机转子直径为 22 毫米"], ans: 2, exp: "电机型号中的数字通常表示电机的尺寸参数，对于多轴飞行器使用的电机，前两位数 字代表转子的直径（单位为毫米），后两位数字代表转子的高度（单位为毫米）。因此，2208 型号的电机表示转子直径为 22 毫米，高度为 8 毫米。" },
  { id: 488, cat: "多旋翼动力飞控", q: "某多轴电机标有 3810 字样，意思是指（）", opts: ["该电机最大承受 38V 电压，最小承受 10V 电压", "该电机定子直径为 38 毫米", "该电机定子高度 38 毫米"], ans: 1, exp: "多轴电机型号中的数字通常表示电机的物理尺寸。在这种情况下，3810 型号的电机 表示定子的直径 38 毫米，而 10 代表定子的高度为 10 毫米。 因此，正确答案是该电机定子直径为 38 毫米。" },
  { id: 489, cat: "多旋翼动力飞控", q: "某多轴电机标有 500KV 字样，意义是指（）", opts: ["对应每 V 电压，电机提供 500000 转/分的转速", "电机最大耐压 500KV", "对应每 V 电压，电机提供 500 转/分的转速"], ans: 2, exp: "电机的 KV 值定义为“每伏特（V）电压下电机的空载转速”。某多轴电机标有 500KV 字样，意味着对应每 V 电压，电机提供 500 转/分的转速。" },
  { id: 490, cat: "多旋翼动力飞控", q: "某多轴电机转速为 3000 转，是指（）", opts: ["每分钟 3000 转", "每秒钟 3000 转", "每小时 3000 转"], ans: 0, exp: "在多轴飞行器的参数中，电机转速一般都是指每分钟的转数。所以某多轴电机转速为 3000 转，是指每分钟 3000 转。" },
  { id: 491, cat: "多旋翼动力飞控", q: "某多轴动力电池标有 3S2P 字样，代表（）", opts: ["电池由 3S2P 公司生产", "电池组先由 2 个单体串联，再将串联后的 3 组并联", "电池组先由 3 个单体串联，再将串联后的 2 组并联"], ans: 2, exp: "某多轴动力电池标有 3S2P 字样，代表电池组先由 3 个单体串联，再将串联后的 2 组 并联。这种电池配置可以提供更高的电压和容量，以满足多轴飞行器的动力需求。" },
  { id: 492, cat: "多旋翼动力飞控", q: "某多轴动力电池容量 10Ah，表示（）", opts: ["理论上，以 10mA 电流放电，可放电 1 小时", "理论上，以 10000mA 电流放电，可放电 1 小时", "理论上，以 10A 电流放电，可放电"], ans: 1, exp: "电池容量的单位是安时（Ah）。10Ah 的意思是理论上，如果以 10A 的电流放电，可以 放电 1 小时。而 1A=1000mA，所以 10Ah 可以理解为理论上以 10000mA（10A×1000）电流放 电，可放电 1 小时。" },
  { id: 493, cat: "多旋翼动力飞控", q: "某多轴动力电池容量为 6000mAh，表示（）", opts: ["理论上，以 6A 电流放电，可放电 1 小时", "理论上，以 60A 电流放电，可放电 1 小时", "理论上，以 6000A 电流放电，可放电 1 小时"], ans: 0, exp: "电池容量的单位为毫安时（mAh），1 安（A） =1000 毫安（mA）。6000mAh 的电池容量，如果以 6A （6000mA）电流放电，根据容量=电流×时间，时间=容量：电流，6000mAh=6000mA=1 小时。" },
  { id: 494, cat: "多旋翼动力飞控", q: "某多轴飞行器动力电池标有 11.1V，它是（）", opts: ["6S 锂电池", "11.1S 锂电池", "3S 锂电池"], ans: 2, exp: "多轴飞行器动力电池标有 11.1V，这表示该电池是由 3 个锂电池单体串联而成，因为 每个锂电池单体的标称电压约为 3.7V。当三个单体串联时，总电压为 3.7V×3=11.1V。因此，正确答案是 3S 锂电池。" },
  { id: 495, cat: "多旋翼动力飞控", q: "某多轴飞行器动力电池标有 22.2V，它是（）", opts: ["6S 锂电池", "22.2S 锂电池", "3S 锂电池"], ans: 0, exp: "多轴飞行器动力电池标有 22.2V，这表示该电池是由 6 个锂电池单体串联组成的，因 为每个锂电池单体的标称电压约为 3.7V，6 个单体串联后的总电压即为 22.2V。" },
  { id: 496, cat: "多旋翼动力飞控", q: "某多轴飞行器螺旋桨标有“CW”字样，表明该螺旋桨（）", opts: ["俯视多轴飞行器顺时针旋翼", "俯视多轴飞行器逆时针旋翼", "该螺旋桨为“CW”牌"], ans: 0, exp: "某多轴飞行器螺旋桨标有“CW”字样，表明该螺旋桨在俯视多轴飞行器时是顺时针旋 转的。在航空领域中，“CW”是“Clockwise”的缩写，即顺时针方向。因此，这个标识用 来指示螺旋桨的旋转方向。" },
  { id: 497, cat: "多旋翼动力飞控", q: "某多轴螺旋桨长 254 毫米，螺距 114 毫米，那么他的型号可表述为（）", opts: ["2511", "1045", "254114"], ans: 1, exp: "螺旋桨号有讲究，英寸换算别弄错。多轴飞行器螺旋桨型号通常由两组数字组成，前 两位数字代表螺旋桨直径（单位毫米换算为近似英寸值），后两位数字代表螺距（单位毫米 换算近似英寸值）。254 毫米约为 10 英寸，114 毫米约为 4.5 英寸，四舍五入后型号表示为 1045。" },
  { id: 498, cat: "多旋翼动力飞控", q: "某多轴螺旋桨长 381 毫米，螺距 127 毫米，那么他的型号可表述为（）", opts: ["3812", "15×5", "38×12"], ans: 1, exp: "多轴螺旋桨的型号通常由两部分组成，第一部分表示螺旋桨的直径（单位为英寸），第二部分表示螺距（单位为英寸）。将毫米转换为英寸，381 毫米约等于 15 英寸，127 毫米 约等于 5 英寸。因此，该螺旋桨的型号可以表述为 15×5。" },
  { id: 499, cat: "多旋翼动力飞控", q: "某螺旋桨是正桨，是指（）", opts: ["从多轴飞行器下方观察，该螺旋桨逆时针旋转", "从多轴飞行器上方观察，该螺旋桨顺时针旋转", "从多轴飞行器上方观察，该螺旋桨逆时针旋转"], ans: 2, exp: "在多轴飞行器中，螺旋桨的旋转方向通常从上方观察来确定。正桨意味着从上方观察 时，螺旋桨是逆时针旋转的。这种命名约定有助于统一描述螺旋桨的旋转方向，因为飞行器 上通常会有正桨和反桨（从上方观察时顺时针旋转）的组合，以平衡扭矩。" },
  { id: 500, cat: "多旋翼动力飞控", q: "目前多轴飞行器飞控市场上的 APM 飞控特点是（）", opts: ["可以应用于各种特种飞行器", "基于 Android 开发", "配有地面站软件，代码开源"], ans: 2, exp: "APM（ArduPilotMega）飞控的主要特点是配有地面站软件，并且代码开源，允许用户 进行二次开发和定制。它主要应用于多轴飞行器等常规无人机类型，并非各种特种飞行器； 它也不是基于 Android 开发。" },
  { id: 501, cat: "多旋翼动力飞控", q: "目前多轴飞行器飞控市场上的 KK 飞控具有的优点是（）", opts: ["功能强大，可以实现全自主飞行", "价格便宜，硬件结构简单", "配有地面站软件，代码开源"], ans: 1, exp: "KK 飞控是一种较为简单的飞控系统。优点在于价格便宜，硬件结构简单，适合初学 者入门了解多轴飞行器的基本控制原理。" },
  { id: 502, cat: "多旋翼动力飞控", q: "目前多轴飞行器飞控市场上的 MWC 飞控的特点是（）", opts: ["可以应用于各种特种飞行器", "基于 Android 开发", "配有地面站软件，代码开源"], ans: 2, exp: "MWC（MultiWiCopter）飞控配有地面站软件，并且其代码是开源的，用户可以根据 自己的需求进行修改和定制。它主要应用于常规的多轴飞行器等，并非各种特种飞行器，也 不是基于 Android 开发。" },
  { id: 503, cat: "多旋翼动力飞控", q: "目前多轴旋翼飞行器飞控市场上的 DJINAZA 飞控特点是（）", opts: ["可以应用于各种特种飞行器", "稳定，商业软件，代码不开源", "配有地面站软件，代码开源"], ans: 1, exp: "DJINAZA 飞控主要特点是稳定性高，拥有多种飞行控制模式，并且提供智能切换功能。 NAZA 飞控集成了多种传感器，如 3 轴陀螺仪、3 轴加速度计和气压计等，运用了先进的 GPS/INS 传感器融合算法技术，保证了飞行器在高震动、高机动性环境下的飞行稳定性和精 准度。此外，NAZA 飞控的代码并不开源，是 DJ 的商业软件。" },
  { id: 504, cat: "多旋翼动力飞控", q: "目前技术条件下，燃油发动机不适合作为多轴飞行器动力的原因，表述不正确的是（）", opts: ["生物燃料能量密度低于锂电池", "调速时响应较慢，且出于安全性原因需要稳定转速工作", "尺寸，重量较大"], ans: 0, exp: "生物燃料能量密度低于锂电池这个选项是不正确的。实际上，燃油发动机不适合作为 多轴飞行器动力的主要原因包括： 1.调速时响应较慢：燃油发动机在调速时响应较慢，且出于安全性原因需要稳定转速工作。 2.尺寸和重量较大：燃油发动机的尺寸和重量较大，不适合多轴飞行器的轻量化需求。 这些原因限制了燃油发动机在多轴飞行器中的应用，使得电动系统成为更优选择，因为电动 系统形式简单且电机速度响应快，同时不依赖传统生物燃料。" },
  { id: 505, cat: "多旋翼动力飞控", q: "前三点固定翼降落最佳接地方式是（）", opts: ["前机轮先着地", "后机轮先着地", "机轮同时着地"], ans: 1, exp: "前三点式固定翼飞机降落最佳接地方式是后机轮先着地，这样可以保持飞机的稳定性，避免机头下沉过快导致事故。如果前机轮先着地容易造成飞机跳跃甚至失速坠毁；机轮同时 着地较难精准控制。" },
  { id: 506, cat: "多旋翼动力飞控", q: "轻小型无人机常用定距螺旋桨的尺寸通常用 X*Y 来表示，其中 Y 代表（）", opts: ["螺距", "叶片数量", "桨径"], ans: 0, exp: "轻小型无人机使用的定距螺旋桨尺寸通常用 X*Y 来表示，其中 X 代表桨径（直径），Y 代表螺距。螺距是指螺旋桨旋转一圈所推动空气的距离，是衡量螺旋桨推力性能的一个重要 参数。" },
  { id: 507, cat: "多旋翼动力飞控", q: "请选出以下哪一只螺旋桨升力最大？（）", opts: ["18×7（两叶螺旋桨）", "16×4.5（三叶螺旋桨）", "15×4（四叶螺旋桨）"], ans: 0, exp: "螺旋桨的升力与其桨径和螺距有关，桨径越大，螺距越大，升力通常也越大。在给定 的选项中，18×7 的螺旋桨桨径最大，因此其升力最大。" },
  { id: 508, cat: "多旋翼动力飞控", q: "如不考虑结构、尺寸、安全性等其他因素，单纯从气动效率出发，同样起飞重量的 8 轴飞行器与 4 轴飞行器，（）", opts: ["4 轴效率高", "8 轴效率高", "效率一样"], ans: 0, exp: "从气动效率的角度来看，同样起飞重量的 8 轴飞行器与 4 轴飞行器相比，4 轴飞行器 的效率更高。这是因为在起飞重量相同的情况下，4 轴飞行器的每个电机需要提供的升力更 小，因此可以采用更小的螺旋桨，从而减少气动阻力和提高推进效率。此外，4 轴飞行器的 结构更简单，重量分布更均匀，有助于提高整体的气动性能。" },
  { id: 509, cat: "多旋翼动力飞控", q: "如果多轴飞行器安装的螺旋桨与电动机不匹配，桨尺寸过大，会带来的坏处不包括（）", opts: ["电机电流过大，造成损坏", "电调电流过大，造成损坏", "飞控电流过大，造成损坏"], ans: 2, exp: "如果多轴飞行器安装的螺旋桨与电动机不匹配且桨尺寸过大，会使电机负载增加，导 致电机电流过大，可能造成电机损坏；同时电机电流增大也会使电调电流增大，可能造成电 调损坏。而桨尺寸过大一般不会直接导致飞控电流过大从而造成飞控损坏。" },
  { id: 510, cat: "多旋翼动力飞控", q: "同样容量不同类型的电池，最轻的是（）", opts: ["铅酸蓄电池", "碱性电池", "Li-po（锂聚合物电池）"], ans: 2, exp: "锂聚合物电池（Li-Po）的两个主要优点：相比其他类型的电池，锂聚合物电池重量 轻且具有较大的能量密度，即在相同重量下可以提供更多的电能容量。" },
  { id: 511, cat: "多旋翼动力飞控", q: "同样重量不同类型的动力电池，容量最大的是（）", opts: ["Li-po（锂聚合物电池）", "Ni-Cd（镍镉电池）", "Ni-MH（镍氢电池）"], ans: 0, exp: "锂聚合物电池（Li-Po）的两个主要优点：相比其他类型的电池，锂聚合物电池重量 轻且具有较大的能量密度，即在相同重量下可以提供更多的电能容量。" },
  { id: 512, cat: "多旋翼动力飞控", q: "同一架多轴飞行器，在同样做好动力匹配的前提下（）", opts: ["两叶桨的效率高", "三叶桨的效率高", "两种桨效率一样高"], ans: 0, exp: "在同一架多轴飞行器且同样做好动力匹配的前提下，两叶桨的效率通常更高。这是因 为两叶桨的空气阻力相对较小，在相同的动力输入下能够产生更高的升力和推进力，同时其 转动时的能量损耗也相对较少。而三叶桨及更多叶桨虽然在某些情况下可能有其他优势，但 在效率方面一般不如两叶桨。" },
  { id: 513, cat: "多旋翼动力飞控", q: "同质量电池，单位价格最便宜的是（）", opts: ["锂聚合物电池", "镉镍电池", "镍氢电池"], ans: 1, exp: "镉镍电池价格相对较为便宜。锂聚合物电池性能较好但价格相对较高。镍氢电池价格 一般也比镉镍电池贵。" },
  { id: 514, cat: "多旋翼动力飞控", q: "无刷电机与有刷电机的区别有（）", opts: ["无刷电机效率较高", "有刷电机效率较高", "两类电机效率差不多"], ans: 0, exp: "无刷电机与有刷电机相比，无刷电机效率较高。有刷电机是通过电刷和换向器来实现 电流的换向，在工作过程中会产生电火花、电刷磨损等问题，这些都会导致能量损失，从而 降低效率。而无刷电机采用电子换向，没有电刷和换向器的摩擦损耗，所以效率更高。同时，无刷电机的运行更加平稳、噪音更低、寿命更长。" },
  { id: 515, cat: "多旋翼动力飞控", q: "下列哪种方式有可能会提高多轴飞行器的载重？（）", opts: ["电机功率不变，桨叶直径变大且桨叶总距变大", "桨叶直径不变，电机功率变小且桨叶总距变小", "梁叶总距不变，电机功率变大且桨叶直径变大"], ans: 2, exp: "多轴飞行器的载重主要取决于电机的动力和桨叶产生的升力。电机功率变大意味着能 够提供更大的动力，而桨叶直径变大通常会使桨叶产生的升力增加。当电机功率变大且桨叶 直径变大时，飞行器就更有可能提高载重。" },
  { id: 516, cat: "多旋翼动力飞控", q: "线圈匝数越高，其 KV 值（）", opts: ["越高", "越低", "无关"], ans: 1, exp: "匝数高，KV 低。KV 值是电机的一个参数，代表电机在每伏特电压下能提供的空载转 速（RPM）。线圈匝数越高，电机的电感量增加，这会限制电流的上升速度，从而降低电机的 转速，因此 KV 值会降低。" },
  { id: 517, cat: "多旋翼动力飞控", q: "向逼近的冷锋飞行时（）", opts: ["云层从低空分散逐渐向高空分散变化，大气压力不断升高", "云层从高空分散逐渐向低空分散变化，大气压力不断升高", "云层从高空分散逐渐向低空分散变化，大气压力不断降低"], ans: 2, exp: "冷锋逼近时，冷空气抬升暖空气形成高空云系逐渐下压，云层由高向低扩展；同时锋 面气压梯度增大，导致大气压力持续降低。" },
  { id: 518, cat: "多旋翼动力飞控", q: "一般锂聚合物电池上都有 2 组线。1 组是输出线（粗，红黑各 1 根）；1 组是单节锂电引 出线（细，与 s 数有关），用以监视平衡充电时的单体电压。下面说法正确的是（）", opts: ["6S 电池有 5 根红色引出线，1 根黑色引出线", "6S 电池有 7 根引出线", "6S 电池有 6 根引出线"], ans: 1, exp: "锂聚合物电池通常有两组线，一组是输出线（较粗的红线和黑线），用于连接电池的 正负极输出；另一组是单节锂电引出线（较细的线），用于监视平衡充电时的单体电压。对 于 6S 电池，意味着有 6 个锂电池单体串联，因此会有 6 根红色引出线和 1 根黑色引出线，共计 7 根引出线。" },
  { id: 519, cat: "多旋翼动力飞控", q: "一架 4 轴飞行器，在其他任何设备都不更换的前提下，安装了 4 个大得多的螺旋桨，下 面说法不一定正确的是（）", opts: ["升力变大", "转速变慢", "桨盘载荷变小"], ans: 0, exp: "首先看“转速变慢”选项，安装大得多的螺旋桨 后，由于螺旋桨的转动惯量增大，在相同的动力条件下，转速会变慢，这个说法通常是正确 的。 对于选项“桨盘载荷变小”，桨盘载荷等于飞行器重量除以螺旋桨桨盘面积，安装大螺旋桨 后桨盘面积增大，在飞行器重量不变的情况下，桨盘载荷会变小，该说法正确。 而选项“升力变大”，虽然螺旋桨变大，但在其他设备不更换的前提下，动力系统不变，有 可能因动力不足无法使大螺旋桨产生更大的升力，所以升力不一定变大。" },
  { id: 520, cat: "多旋翼动力飞控", q: "以下电池记忆效应最高的是（）", opts: ["LI-PO", "Ni-Cd", "Ni-MH"], ans: 1, exp: "Ni-Cd（镍镉电池）具有比较明显的记忆效应。 如果在不完全放电的状态下充电，容易使电池容量降低。而 LI-PO（锂聚合物电池）基本没 有记忆效应。Ni-MH（镍氢电池）的记忆效应要比镍镉电池小很多。" },
  { id: 521, cat: "多旋翼动力飞控", q: "以下关于翼型相对厚度和相对弯度正确的是（）", opts: ["翼型上下表面垂直于翼弦的距离最长的距离值称为相对厚度", "翼型相对厚度越大，相对弯度就越大，能产生的升力就越大", "翼型中弧线的最高点距弦线的最大距离与翼弦长的比值称为相对弯度"], ans: 2, exp: "翼型相对厚度是指翼型最大厚度与翼弦长之比，相对弯度是指翼型中弧线的最高点距 弦线的最大距离与翼弦长的比值。相对厚度和相对弯度是翼型的两个重要参数，它们共同影 响翼型产生的升力和阻力。" },
  { id: 522, cat: "多旋翼动力飞控", q: "以下哪种动力电池放电电流最大？（）", opts: ["2000mAh, 30C", "20000mAh, 5C", "8000mAh, 20C"], ans: 2, exp: "动力电池的放电电流大小与电池容量（mAh）和放电倍率（C）有关。放电电流=电池 容量×放电倍率。我们可以计算每个选项的放电电流： 1.2000mAh,30C： 放电电流 =2000mAh×30=60000mA=60A 2.20000mAh,5C： 放电电流 =20000mAh×5=100000mA=100A 3.8000mAh,20C：放电电流 =8000mAh×20=160000mA=160A 通过计算，我们可以看到选项（8000mAh，20C）的放电电流最大，为 160A。" },
  { id: 523, cat: "多旋翼动力飞控", q: "以下哪种动力电池放电电流最大？（）", opts: ["2Ah, 30C", "30000mAh, 5C", "20000mAh, 5C"], ans: 1, exp: "放电电流可以通过电池的容量（Ah）和放电倍率（C）来计算。放电倍率是指电池在 1 小时内可以放电的电量，因此，一个电池的放电电流可以通过其容量（Ah）乘以放电倍率 （C）来计算。 代入公式，三个选项的放电电流对比如下： 1，2Ah 电池以 30C 放电，其放电电流为 2Ah*30=60A。 2,30000mAh（即 30Ah）电池以 5C 放电，其放电电流为 30Ah*5=150A。" },
  { id: 524, cat: "多旋翼动力飞控", q: "以下哪种动力电池在没有充分放电的前提下，不能够以大电流充电？", opts: ["铅酸蓄电池", "Ni-Cd（镍镉电池）", "Li-po（锂聚合物电池）"], ans: 1, exp: "镍镉电池（Ni-Cd）具有比较明显的记忆效应，如果在没有充分放电的前提下以大电 流充电，会使电池容量降低，影响电池性能和寿命。" },
  { id: 525, cat: "多旋翼动力飞控", q: "用遥控器设置电调，需要（）", opts: ["断开电机", "接上电机", "断开动力电源"], ans: 1, exp: "用遥控器设置电调时需要接上电机，这样可以通过遥控器的操作来观察电机的响应，以确保电调的设置正确。如果断开电机则无法观察到设置的效果；而仅仅断开动力电源可能 也无法正常进行设置和调试。" },
  { id: 526, cat: "多旋翼动力飞控", q: "有 2 个输出功率相同的电机，前者型号 3508，后者型号 2820，以下表述错误的是（）", opts: ["3508 适合带动更大的螺旋桨", "2820 适用于更高的转速", "尺寸上，2820 粗一些，3508 高一些"], ans: 2, exp: "电机型号中的前两位数字表示电机定子的直径，后两位数字表示电机定子的高度。 1.3508 电机定子直径较大，适合带动更大的螺旋桨，该项正确。 2.2820 电机相对直径较小，高度也较小，通常适用于更高的转速，该项正确。 3.3508 电机定子直径为 35mm，2820 电机定子直径为 28mm，所以 3508 粗一些，同时 3508 电机定子高度为 8mm，2820 电机定子高度为 20mm，所以 2820 高一些，该项错误。" },
  { id: 527, cat: "多旋翼动力飞控", q: "在高海拔、寒冷、空气稀薄地区，飞行负载不变，飞行状态会（）", opts: ["功率损耗增大，飞行时间减少", "最大起飞重量增加", "飞行时间变长"], ans: 0, exp: "在高海拔、寒冷、空气稀薄的地区飞行时，由于空气密度降低，飞行器获得的升力减 少，导致需要更大的功率来维持飞行，这会增加功率损耗。 同时，由于发动机在稀薄空气中氧气供应不足，燃烧效率降低，发动机功率下降，这会进一 步影响飞行效率和飞行时间。因此，在这些条件下飞行，飞行器的功率损耗会增大，飞行时 间会减少。" },
  { id: 528, cat: "多旋翼动力飞控", q: "在高海拔地区，多轴飞行器出现较难离地时，最有效的应对措施是，（）", opts: ["减重", "更换大桨", "更换大容量电池"], ans: 0, exp: "在高海拔地区，空气稀薄，气压低，飞行器的升力会减小。此时如果多轴飞行器出现 较难离地的情况，最有效的应对措施是减重，因为减轻重量可以降低飞行器起飞所需的升力。" },
  { id: 529, cat: "多旋翼动力飞控", q: "在横侧操纵中，操纵杆左右活动的每一个位置，都对应着一个（）", opts: ["坡度", "滚转角速度", "旋转角度"], ans: 1, exp: "在横侧操纵中，操纵杆的左右活动控制的是飞机的横滚运动，即飞机围绕其纵轴的旋 转。操纵杆的每一个位置都对应着一个特定的滚转角速度，即飞机横滚的快慢。因此，正确 答案是滚转角速度。" },
  { id: 530, cat: "多旋翼动力飞控", q: "直接控制电机转速的是（）", opts: ["电池", "电调", "飞控"], ans: 1, exp: "直接控制电机转速的是电子调速器（ESC），简称电调。电调接收来自飞控系统的控制 信号，根据这些信号调整供给电机的电能，从而控制电机的转速。电池提供电能，飞控发出 控制指令，但直接控制电机转速的是电调。" },
  { id: 531, cat: "多旋翼动力飞控", q: "电机上印有 CCW 是指（）", opts: ["CCW 公司", "顺时针旋转", "逆时针旋转"], ans: 2, exp: "CCW 是“Counter-Clock wise”的缩写，表示电机的旋转方向为逆时针方向。因此，电机上印有 CCW 表示该电机的旋转方向为逆时针方向。" },
  { id: 532, cat: "多旋翼动力飞控", q: "无人机动力装置是属于（）种类的", opts: ["气动", "电动", "液动"], ans: 1, exp: "大多数无人机采用电动动力装置，因为电动系统具有高效、环保、易于控制等优点，适合无人机的轻量化和小型化设计。" },
  { id: 533, cat: "多旋翼动力飞控", q: "电动多旋翼的螺旋桨可以做得尽量大，从而可以用最少的旋翼数实现大载荷，是否正 确？（）", opts: ["正确", "不正确", "不一定"], ans: 2, exp: "电动多旋翼的螺旋桨尺寸与载荷能力的关系需综合考量，虽然较大的螺旋桨可以产生 更大的升力，从而在理论上减少所需的旋翼数量以实现大载荷，但实际应用中存在多个限制 因素，因此，螺旋桨的大小需要根据具体的应用场景和设计要求进行综合考虑，不能简单地 认为“越大越好”。" },
  { id: 534, cat: "多旋翼动力飞控", q: "多旋翼哪个是正桨，哪个是反桨？（）", opts: ["俯视逆时针旋转的为正桨，顺时针为反桨", "俯视顺时针旋转的为正桨，逆时针为反桨", "仰视顺时针旋转的为正桨，逆时针为反桨"], ans: 0, exp: "多旋翼飞行器采用正反桨配对设计以抵消反扭矩，其定义标准为： 正桨（CCW）：俯视时（从上方观察）逆时针旋转，桨叶螺纹为右旋（顺时针拧紧）； 反桨（CW）：俯视时顺时针旋转，桨叶螺纹为左旋（逆时针拧紧）" },
  { id: 535, cat: "多旋翼动力飞控", q: "桨叶角从桨根到桨尖是（）的", opts: ["不变", "变大", "变小"], ans: 2, exp: "桨叶角（也称迎风角或安装角）是从桨根到桨尖逐渐变小的。这是因为桨叶在旋转时，桨尖的线速度比桨根快，为了保持整个桨叶的升力分布均匀，桨叶角需要从桨根到桨尖逐渐 减小。这种设计可以确保桨叶在不同位置的升力贡献相对均衡，从而提高螺旋桨的效率和性 能。" },
  { id: 536, cat: "多旋翼动力飞控", q: "下列螺旋桨效率最高的是（）", opts: ["尼龙螺旋桨", "夹心碳纤维螺旋桨", "薄片碳纤维"], ans: 1, exp: "1.尼龙螺旋桨：尼龙材料具有轻便、价格低廉、强度和耐久性相对较高的优点，但其强度和 刚性相对较低，适用于中低端无人机。 2.夹心碳纤维螺旋桨：这种螺旋桨结合了碳纤维的高强度和轻量化特性，同时通过夹心结构 进一步提高了强度和刚性，减少了振动，提高了效率。 3.薄片碳纤维螺旋桨：虽然碳纤维材料具有高强度和轻量化的优势，但薄片设计可能在结构 强度和耐用性上略逊于夹心结构。 综合来看，夹心碳纤维螺旋桨在强度、刚性、耐用性和效率方面表现最佳，因此效率最高的 是夹心碳纤维螺旋桨。" },
  { id: 537, cat: "多旋翼动力飞控", q: "电池的放电能力是以倍率来表示的，一个 1000mAh、10C 的电池，最大放电电流可达（）", opts: ["1 安培", "10 安培", "5 安培"], ans: 1, exp: "电池放电倍率 C 表示容量放大倍数。1000mAh=1Ah, 10C 即 10×1Ah=10A，故选 B。" },
  { id: 538, cat: "多旋翼动力飞控", q: "大电流充电会对电池的性能造成一定程度的破坏，一般厂家要求用 0.1C 的电流充电，而锂聚合物电池因为性能优越在保证冷却通风的条件下可以用（）的电流充电。", opts: ["1C", "2C", "3C"], ans: 0, exp: "本题主要考查锂聚合物电池（LiPo）的充电倍率特性。锂聚合物电池的充电电流通常 建议不超过 1C。虽然一些高性能的锂聚合物电池可以承受更高的充电倍率，但在标准条件 下，为了确保电池的性能和寿命，建议使用 1C 或更低的充电倍率。因此，锂聚合物电池在 保证冷却通风的条件下，可以使用 1C 的电流充电。" },
  { id: 539, cat: "多旋翼动力飞控", q: "锂聚合物电池的标称电压是（）", opts: ["1.2V", "4.2V", "3.7V"], ans: 2, exp: "锂聚合物电池（LiPo）的电压特性是无人机动力系统的核心知识点，需重点掌握以下 电压标准的定义： 标称电压：3.7V（所有 LiPo 单体的基准参数）满电电压：4.2V（充电截止电压，非标称值）放电截止电压：通常 3.0V（防止过放损坏）" },
  { id: 540, cat: "多旋翼动力飞控", q: "无人机 ESC 部件（标称：输入电压为 12.6~25.2V、持续电流为 120A），以下两组电池 6S 10000mAh 10C 和 12S 16000mAh 15C，哪一组适用？（）", opts: ["12S 16000mAh 15C", "6S 10000mAh 10C", "都适用"], ans: 1, exp: "6S10000mAh10C: 电压：6S 电池的标称电压为 22.2V（每节 3.7V，6 节串联），在充电时最高可达 25.2V（每 节 4.2V），符合 ESC 的输入电压范围 12.6~25.2V。 电流：10C 的放电倍率意味着最大放电电流 100A（10C×10Ah），低于 ESC 的持续电流要求 120A，但接近，可以使用。 因此，6S10000mAh10C 的电池适用，而 12S16000mAh15C 的电池电压远超电调的输入电压范 围，不适用。" },
  { id: 541, cat: "多旋翼动力飞控", q: "标有 6S 的电调中，选用多大的电池合适？（）", opts: ["26V", "50V", "小于等于 25.2V"], ans: 2, exp: "6S 电池：6S 表示电池由 6 节单体电池串联组成。 每节单体电池的标称电压为 3.7V，因此 6S 电池的标称电压为 6×3.7=22.2V。在充电时，每 节单体电池的最高电压 4.2V，因此 6S 电池的最高电压为 6×4.2=25.2V。 电调输入电压：电调上标有 6S，表示其输入电压范围为 12.6V~25.2V。因此，选用的电池电 压应小于等于 25.2V。" },
  { id: 542, cat: "多旋翼动力飞控", q: "某多轴飞行器电调上标有 15A 字样，意思是指（）", opts: ["电调所能承受的稳定工作电流是", "电调所能承受的最大瞬时电流是", "电调所能承受的最小工作电流是"], ans: 1, exp: "电调上标明的 15A 指最大瞬时电流，即短时间内能承受的峰值电流，而非持续工作电 流。这关系到电调在突发情况下的安全性能。" },
  { id: 543, cat: "多旋翼动力飞控", q: "电子调速器的作用是接收飞控信息，转变电池的直流为交流，（）", opts: ["驱动无刷电机", "控制各种电机转速", "转换飞控控制信息"], ans: 0, exp: "电子调速器（ESC）的主要作用是将直流电转换为交流电，以驱动无刷电机。无刷电 机需要交流电来产生旋转磁场，从而实现高效运转。" },
  { id: 544, cat: "多旋翼动力飞控", q: "PWM 调速方式称为：（）", opts: ["变频调速", "变电压调速", "脉宽调制，占空比调速"], ans: 2, exp: "PWM（PulseWidthModulation，脉宽调制）是一种通过改变脉冲信号的占空比来控制 电机转速的方法。占空比是指脉冲信号高电平时间与整个周期时间的比例。通过调整占空比，可以控制电机的平均电压，从而实现调速。" },
  { id: 545, cat: "多旋翼动力飞控", q: "使用中如果电调损坏之后，如无原型号代替，可以用（）电调代替", opts: ["用更大功率的", "用更小功率的", "不能替代"], ans: 0, exp: "如果原电调损坏且无原型号可替代，可以使用更大功率的电调来代替。更大功率的电 调能够承受更高的电流，从而更好地保护电路，避免因电流过大导致的损坏。" },
  { id: 546, cat: "多旋翼动力飞控", q: "常规的电子调速器上中等粗细的几条线是用来连接（）的", opts: ["电池", "自驾仪或遥控接收机", "电机"], ans: 2, exp: "电子调速器（ESC）的主要功能是控制电机的转速和方向。中等粗细的几条线通常用 于连接电机的定子绕组，以提供电力并控制电机的运行。" },
  { id: 547, cat: "多旋翼动力飞控", q: "聚合物锂电池长时间储存单片电压是多少？储存容量的百分比是多少？（）", opts: ["4.2V; 40%～50%", "3.8V; 40%～50%", "3.7V, 70 ~ 80%"], ans: 1, exp: "聚合物锂电池的最佳储存电压为 3.8 至 3.9 伏，此时电池的充电电量约为 50%。这种 电压范围可以有效减少电池的自放电，延长电池寿命。" },
  { id: 548, cat: "多旋翼动力飞控", q: "串联和并联时电流、电压、容量如何变化？（）", opts: ["串联电流不变，电压变大，容量变大；并联电流变大，电压不变，容量不变", "串联电流变大，电压不变，容量不变；并联电流不变，电压变大，容量变大", "串联电流不变，电压变大，容量不变；并联电流变大，电压不变，容量变大"], ans: 2, exp: "串联： 电流：电流在串联电路中是相同的，因为电流在电路中只有一个路径。 电压：电压在串联电路中会相加，因为每个电池的电压都会累加到总电压上。 容量：容量（mAh 在串联电路中保持不变，因为电流路径是单一的，所以总容量等于单个电 池的容量。 并联： 电流：电流在并联电路中会相加，因为电流有多个路径。 电压：电压在并联电路中保持不变，因为所有电池的电压都相同。 容量：容量（mAh）在并联电路中会相加，因为电流有多个路径，所以总容量等于所有电池 容量的总和。 因此，正确答案是：串联电流不变，电压变大，容量不变；并联电流变大，电压不变，容量 变大。" },
  { id: 549, cat: "多旋翼动力飞控", q: "16000mAh 25C，25C 是什么倍率？（）", opts: ["充电倍率", "放电倍率", "额定倍率"], ans: 1, exp: "C 率（倍率）是表示电池放电速度的指标，即电池最大放电电流与电池容量的比值。 25C 表示该电池的最大放电电流是其容量的 25 倍。对于 16000mAh 的电池，25C 的放电倍率 意味着最大放电电流 400A（25C×16000mAh）。" },
  { id: 550, cat: "多旋翼动力飞控", q: "关于锂电池说法错误的是？（）", opts: ["强记忆效应", "标称电压 3.7V", "充满电压 4.2V"], ans: 0, exp: "关于锂电池说法错误的是强记忆效应。锂电池（如锂离子电池和锂聚合物电池）具有 低自放电率且无记忆效应，这是其相比镍镉电池和镍氢电池的一大优势。记忆效应是指电池 在不完全放电的情况下充电，导致电池容量逐渐减少的现象，而锂电池不会出现这种情况。" },
  { id: 551, cat: "多旋翼动力飞控", q: "常用锂聚合物电池的专用充电器，根据（）不同，主要分为串行式平衡充设备和并行 式平衡充设备", opts: ["电池电芯组合情况", "充电原理", "电量大小"], ans: 1, exp: "题目考查的是锂聚合物电池专用充电器的分类依据。平衡充电设备的设计核心差异在 于充电原理，而非电池组合或电量大小。 因此，正确答案是：充电原理。" },
  { id: 552, cat: "多旋翼动力飞控", q: "多旋翼无人机智能锂电池管理电路能够（）", opts: ["给出需要返航时间", "对电芯单体进行电压均衡管理", "给出续航时间"], ans: 1, exp: "多旋翼无人机的智能锂电池管理电路的主要功能是对电芯单体进行电压均衡管理。这 是因为锂电池管理系统（BMS）的核心功能之一是确保电池组中每个电芯的电压保持一致，从而延长电池寿命并提高安全性。 因此，正确答案是：对电芯单体进行电压均衡管理。" },
  { id: 553, cat: "多旋翼动力飞控", q: "3S2P 锂电池有（）片电芯", opts: ["4", "5", "6"], ans: 2, exp: "3S2P 表示电池组由 3 组串联（S）的电芯组成，每组有 2 片电芯并联（P）。因此，总 电芯数量为 3（组）×2（每组的电芯数）=6 片。" },
  { id: 554, cat: "多旋翼动力飞控", q: "飞控子系统应该具备以下（）功能", opts: ["姿态稳定与控制", "导航与制导系统", "任务分配与航迹规划"], ans: 0, exp: "飞控子系统是无人机的核心控制系统，其主要功能是确保无人机在飞行过程中保持稳 定和可控。飞控子系统通过传感器（如 IMU、陀螺仪、加速度计）实时监测无人机的俯仰、横滚、偏航角，结合控制算法（如 PID 控制）调整电机转速或舵面偏转，确保飞行稳定性。" },
  { id: 555, cat: "多旋翼动力飞控", q: "（）的主要功能是根据飞控计算机的指令，按规定的静态和动态的要求，通过对无人 机各控制舵面和发动机节风门等的控制，实现对无人机的飞行控制", opts: ["电源", "伺服执行机构", "数据链"], ans: 1, exp: "伺服执行机构，是无人机飞行控制系统的关键部分，其主要功能是根据飞控计算机的 指令，通过控制舵面（如副翼、升降舵、方向舵等）和发动机节风门，实现对无人机的飞行 姿态和速度的精确控制。伺服执行机构需要按照规定的静态和动态要求，快速、准确地响应 飞控指令，从而实现对无人机的飞行控制。" },
  { id: 556, cat: "多旋翼动力飞控", q: "导航子系统功能是向无人机提供相对于所选定的参考坐标系的（）引导确定航线安全、准时准确地飞行。", opts: ["位置、速度、飞行姿态", "高度、速度、飞行姿态", "俯仰、滚转、偏航"], ans: 0, exp: "导航子系统的核心功能是无人机提供其在空间中的位置、速度和飞行姿态等关键信息，从而帮助无人机确定飞行路径，确保其能够沿着预定航线安全、准时且准确地飞行。这些信 息是无人机自主飞行的基础。" },
  { id: 557, cat: "多旋翼动力飞控", q: "哪种类型的无人机在动力系统全失效的情况下，基本没有迫降的可能？（）", opts: ["固定翼", "直升机", "多旋翼"], ans: 2, exp: "多旋翼无人机依赖多个旋翼的持续旋转来提供升力和控制姿态。一旦动力系统完全失 效，旋翼将停止旋转，无人机将失去升力，无法进行滑翔或自转下降，因此基本没有迫降的 可能性。" },
  { id: 558, cat: "多旋翼动力飞控", q: "组装无人机时，一般要对飞控进行（）", opts: ["包裹锡箔纸，减小电磁干扰", "减震，并将飞控放置于飞机的旋转中心", "要进行美观处理，使飞控外围设备与飞控的连线从飞控上面经过"], ans: 1, exp: "在组装无人机时，飞控的安装和调试非常重要。 飞控是无人机的核心部件，负责控制无人机的姿态和飞行路径。为了确保飞控的稳定性和准 确性，通常需要采取减震措施，以减少飞行过程中的振动对飞控的影响。此外，将飞控放置 于机的旋转中心（通常是重心附近），可以确保飞控能够更准确地感知和控制无人机的姿态 变化。" },
  { id: 559, cat: "多旋翼动力飞控", q: "一块聚合物锂电池上标有 25C 字样，代表（）", opts: ["充电倍率", "放电倍率", "容量倍率"], ans: 1, exp: "锂电池上的“25C”字样中的“C”代表放电倍率。具体来说，放电倍率是指电池的最 大放电电流与电池容量的比值。 例如，对于一块标有“25C”的 2000mAh（2Ah）锂电池，其最大放电电流为 25 倍的容量，即 25×2A=50A" },
  { id: 560, cat: "多旋翼动力飞控", q: "螺旋桨叶本身是扭转的，因此桨叶角从毂轴到叶尖是变化的最大安装角或者最大桨距 在（）", opts: ["毂轴处", "叶尖处", "桨叶中部"], ans: 0, exp: "螺旋桨叶本身是扭转的，其桨叶角从毂轴到叶尖是逐渐变化的。最大安装角或最大桨 距位于毂轴处，而最小桨距位于叶尖。" },
  // ==================== 多旋翼综合 ====================
  { id: 561, cat: "多旋翼综合", q: "4 轴飞行器，改变航向时（）", opts: ["相邻的 2 个桨加速，另 2 个桨减速", "相对的 2 个桨加速，另 2 个桨减速", "4 个桨均加速"], ans: 1, exp: "四轴飞行器改变航向时，是通过相对的两个桨加速，另两个桨减速来实现的。这种方 法可以产生不平衡的反扭矩，从而使飞行器改变航向。因此，正确答案是相对的 2 个桨加速，另 2 个桨减速。" },
  { id: 562, cat: "多旋翼综合", q: "4 轴飞行器运动中有（）", opts: ["6 个自由度，3 个运动轴", "4 个自由度，4 个运动轴", "4 个自由度，3 个运动轴"], ans: 0, exp: "四轴飞行器 （Quadcopter）是一种具有四个旋翼的多旋翼飞行器，它在飞行运动中 具有 6 个自由度，分别是三个平移自由度（沿 X、Y、Z 轴的移动）和三个旋转自由度（绕 X、Y、Z 轴的旋转）。四轴飞行器的运动轴是 3 个，分别是俯仰（Pitch）、横滚（Roll）和偏航 （Yaw）。" },
  { id: 563, cat: "多旋翼综合", q: "4 轴飞行器有“X”模式和“+”模式两大类，其中（）", opts: ["“+”模式操纵性好", "“X”模式操纵性好", "两种模式操纵性没有区别"], ans: 1, exp: "4 轴飞行器有“X”模式和“＋”模式两大类，其中“X”模式的机头方向位于两个电 机之间，这种模式的飞行难度相对较高，但动作更加灵活。而“+”模式的机头方向则位于 某一个电机上，这种模式的飞行难度相对较低，但动作的灵活性较差。因此，表述“X”模 式操纵性好是正确的。" },
  { id: 564, cat: "多旋翼综合", q: "X 模式 4 轴飞行器，左前方的旋翼一般多为（）", opts: ["俯视顺时针旋转", "俯视逆时针旋转", "左视逆时针旋转"], ans: 0, exp: "X 模式四轴飞行器的旋翼旋转方向是：电机 1 和电机 3 逆时针旋转，电机 2 和电机 4 顺时针旋转。因此，左前方的旋翼（电机 2）一般是顺时针旋转的。" },
  { id: 565, cat: "多旋翼综合", q: "X 模式 4 轴飞行器从悬停转换到前进，哪两个轴需要加速？（）", opts: ["后方两轴", "左侧两轴", "右侧两轴"], ans: 0, exp: "在 X 模式 4 轴飞行器中，从悬停转换到前进状态时，后方两轴需要加速。这是因为飞 行器前进主要靠后方旋翼产生更大的推力，使得飞行器向前运动。而前方的旋翼主要起到平 衡和调整姿态的作用。" },
  { id: 566, cat: "多旋翼综合", q: "X 模式 6 轴飞行器从悬停转换到向左平移，哪两个轴需要减速？（）", opts: ["后方两轴", "左侧两轴", "右侧两轴"], ans: 1, exp: "X 模式 6 轴飞行器从悬停转换到向左平移时，需要减速的是左侧两轴。这是因为在 X 模式下，飞行器的左右两侧电机旋转方向相反，为了实现向左平移，右侧的电机需要加速，而左侧的电机需要减速，以产生向左侧的推力差，从而使飞行器向左移动。" },
  { id: 567, cat: "多旋翼综合", q: "保持油门持续爬升，电机功率会（）", opts: ["增加", "减小", "不变"], ans: 2, exp: "在保持油门不变的情况下，无人机持续爬升时，电机的功率输入保持不变。这是因为 油门控制的是电机的输入功率，而不是直接控制爬升速率。爬升过程中，虽然无人机需要克 服重力做功，但只要油门不变，电机的功率输入就保持恒定。" },
  { id: 568, cat: "多旋翼综合", q: "部分多轴飞行器会安装垂尾，（）", opts: ["会减小高速前飞时的稳定性，增加悬停时的稳定性", "会增加高速前飞时的稳定性，增加悬停时的稳定性", "会增加高速前飞时的稳定性，减小悬停时的稳定性"], ans: 2, exp: "多轴飞行器垂尾，高速飞行更稳定，悬停时稳定性降低。部分多轴飞行器安装垂尾后，在高速前飞时，垂尾可以增加飞行器的方向稳定性；但在悬停时，垂尾可能会产生干扰，减 小悬停时的稳定性。" },
  { id: 569, cat: "多旋翼综合", q: "部分多轴飞行器螺旋桨加有外框，其主要作用是（）", opts: ["提高螺旋桨效率", "增加外形的美观", "防止磕碰提高安全性"], ans: 2, exp: "部分多轴飞行器螺旋桨加有外框的主要作用是防止飞行操作过程中桨叶与异物的接触，从而对飞行器起到保护作用。因此，正确答案是防止磕碰提高安全性。" },
  { id: 570, cat: "多旋翼综合", q: "部分商用多轴飞行器有收放脚架功能或机体变形功能，其主要目的是（）", opts: ["改善机载任务设备视野", "调整重心增加飞行器稳定性", "减小前飞废阻力"], ans: 0, exp: "部分商用多轴飞行器的收放脚架功能或机架整体变形功能，主要目的是改善机载任务 设备视野。当脚架收起或机架变形后，可以减少对任务设备（如相机等）的遮挡，使得设备 能够更好地进行拍摄、观测等任务，获得更广阔、更清晰的视野范围。" },
  { id: 571, cat: "多旋翼综合", q: "垂直爬升时升限为海拔 1000 米的多轴飞行器，如果在 10km/h 的前飞中爬升，其升限（）", opts: ["将降低", "将升高", "将保持不变"], ans: 1, exp: "在垂直爬升时，多轴飞行器的升限为海拔 1000 米。如果在 10km/h 的前飞中爬升，由 于前飞时空气流动速度增加，可以为螺旋桨提供更多的氧气，从而提高发动机的效率，使得 飞行器在消耗相同能量的情况下能够达到更高的高度。因此，其升限将升高。" },
  { id: 572, cat: "多旋翼综合", q: "大多数多轴飞行器自主飞行过程利用（）实现高度感知", opts: ["气压高度计", "GPS", "超声波高度计"], ans: 1, exp: "大多数多轴飞行器在自主飞行过程中利用 GPS（全球定位系统）实现高度感知。GPS 可以提供较为准确的三维位置信息，包括高度信息。" },
  { id: 573, cat: "多旋翼综合", q: "大多数多轴飞行器自主飞行过程利用（）实现速度感知", opts: ["惯导", "空速管", "GPS"], ans: 2, exp: "大多数多轴飞行器在自主飞行过程中利用 GPS 实现速度感知。GPS 可以通过对位置信 息随时间的变化来计算飞行器的速度。" },
  { id: 574, cat: "多旋翼综合", q: "大多数多轴飞行器自主飞行过程利用（）实现位置感知", opts: ["平台惯导", "捷联惯导", "GPS"], ans: 2, exp: "大多数多轴飞行器在自主飞行过程中，GPS（全球定位系统）起着至关重要的作用。 GPS 可以提供飞行器的高度、速度以及位置信息。" },
  { id: 575, cat: "多旋翼综合", q: "当多轴飞行器地面站出现飞行器电压过低警报时，第一时刻采取的措施不包括（）", opts: ["迅速将油门收到", "一键返航", "控制姿态，逐渐降低高度，迫降至地面"], ans: 0, exp: "当多轴飞行器地面站出现飞行器电压过低报警时，第一时刻采取的措施不包括迅速将 油门收到 0。这是因为在飞行中的无人机旋翼将会突然停机，这是一种非常危险的情况，无 人机将失去升力和控制，会直接坠毁。一键返航可以让飞行器自动按照预设的路线返回起飞 点，是较为合理的选择。控制姿态，逐渐降低高度，迫降至地面，能最大程度保证飞行器的 安全降落。" },
  { id: 576, cat: "多旋翼综合", q: "当多轴飞行器飞远超出视线范围无法辨别机头方向时，应对方式错误的是（）", opts: ["加大油门", "一键返航", "云台复位通过图像确定机头方向"], ans: 0, exp: "当多轴飞行器飞远超出视线范围无法辨别机头方向时，加大油门是错误的应对方式。 因为盲目加大油门可能会导致飞行器失控，增加意外风险。选择一键返航是较为安全可靠的 操作，飞行器能够自动按照预设的路线返回起飞点。云台复位通过图像确定机头方向，能够 帮助操作者重新明确飞行器的姿态和机头指向，从而更好地操控飞行器返回。" },
  { id: 577, cat: "多旋翼综合", q: "电动机电子线圈圈数的多少与转速的关系，（）", opts: ["线圈圈数越多转速越快", "线圈圈数越多转速越慢", "线圈圈数与转速无关"], ans: 1, exp: "电动机的转速与电子线圈圈数成反比关系。线圈圈数越多，产生的磁场越强，但同时 也会增加电磁感应的阻力，导致转速降低；反之，线圈圈数越少，转速越快。因此，线圈圈 数的多少直接影响电动机的转速。" },
  { id: 578, cat: "多旋翼综合", q: "对于多轴飞行器，飞行速度影响航拍设备曝光，以下正确的是（）", opts: ["速度越快，需提高曝光度，保证正常曝光", "速度越快，需降低曝光度，保证正常曝光", "速度快慢，不影响拍摄曝光"], ans: 0, exp: "在多轴飞行器的航拍中，当飞行速度加快时，单位时间内飞行器经过的场景变化更快。 这意味着相同的曝光时间内，进入镜头的光线相对减少。 为了保证正常曝光，即获得合适的亮度和图像质量，需要提高曝光度。所以速度越快，需提 高曝光度，才能保证正常曝光。" },
  { id: 579, cat: "多旋翼综合", q: "对于多轴航拍飞行器云台说法正确的是（）", opts: ["云台保证无人机在云层上飞行的安全", "云台是航拍设备的增稳和操纵装置", "云台的效果与传统舵机一样"], ans: 1, exp: "多轴航拍飞行器的云台主要作用是增稳和操纵航拍设备。云台可以满足相机的三个活 动自由度：绕 X、Y、Z 轴旋转，每个轴心内都安装有电机，当无人机倾斜时，会配合陀螺仪 给相应的云台电机加强反方向的动力，防止相机跟着无人机“倾斜”，从而避免相机抖动，保证拍摄画面的稳定性。" },
  { id: 580, cat: "多旋翼综合", q: "多旋翼无人机机体一般不使用（）", opts: ["高强度工业塑料", "碳纤维材料", "玻璃纤维材料"], ans: 0, exp: "多旋翼无人机机体需要兼顾轻量化与高强度，因此普遍采用： 1、碳纤维材料：高强轻便，主流选择 2、玻璃纤维材料：成本较低，强度适中而高强度工业塑料因重量大、刚性不足，极少用于 无人机主体结构，仅可能用于非承重部件。 因此，多旋翼无人机的主体结构通常不使用高强度工业塑料。" },
  { id: 581, cat: "多旋翼综合", q: "多轴的“轴”指（）", opts: ["舵机轴", "飞行器运动坐标轴", "动力输出轴"], ans: 2, exp: "多轴飞行器中的“轴”指的是动力输出轴，即电机轴。在多轴飞行器中，每个“轴” 通常对应一个电机和螺旋桨，它们提供升力和控制力矩，使飞行器能够在空中悬停、移动和 转向。" },
  { id: 582, cat: "多旋翼综合", q: "多轴飞行器（）", opts: ["有自转下滑能力", "无自转下滑能力", "有部分自传下滑能力"], ans: 1, exp: "多轴飞行器（如四轴飞行器）与直升机或自转旋翼机不同，它们不具备自转下滑能力。 自转下滑是指在失去动力的情况下，依靠旋翼的自转使飞行器安全着陆的能力，这一特性是 直升机和自转旋翼机所具备的。而多轴飞行器在失去动力时，通常会直接坠落，除非配备有 降落伞等安全设备。" },
  { id: 583, cat: "多旋翼综合", q: "多轴飞行器 GPS 定位中，最少达到几颗星，才能在飞行中保证基本的安全？（）", opts: ["2～3 颗", "4～5 颗", "6～7 颗"], ans: 1, exp: "对于多轴飞行器的 GPS 定位来说，最少达到 4～5 颗星才能够在飞行中保证基本的安 全。GPS 定位需要一定数量的卫星信号来确定飞行器的准确位置、高度等信息。如果卫星数 量过少，定位的精度会大大降低，可能导致飞行器位置不准确、高度不稳定等问题，增加飞 行风险。一般来说，4～5 颗星可以提供较为可靠的定位信息，保证飞行器在飞行中的基本 安全。" },
  { id: 584, cat: "多旋翼综合", q: "多轴飞行器不属于以下哪个概念范围？", opts: ["自转旋翼机", "重于空气的航空器", "直升机"], ans: 0, exp: "多轴飞行器是一种重于空气的航空器，它通过多个旋翼提供升力来在空中飞行。直升 机也是一种重于空气的航空器，通过一个或两个主旋翼提供升力。而自转旋翼机（也称为自 转旋翼飞行器）是一种不同的航空器类型，它通过前飞时的相对风流驱动旋翼自转来产生升 力，与多轴飞行器的工作原理不同。" },
  { id: 585, cat: "多旋翼综合", q: "多轴飞行器的操纵不包括（）", opts: ["俯仰操纵", "航向操纵", "周期变距"], ans: 2, exp: "多轴飞行器的操纵主要包括俯仰操纵和航向操纵等。俯仰操纵可以控制多轴飞行器的 前后飞行姿态；航向操纵可以控制多轴飞行器的左右转向。而周期变距主要是直升机操纵系 统中的一种方式，通过改变旋翼桨叶的桨距角来实现不同的飞行状态控制。多轴飞行器不是 通过周期变距来进行操纵的。" },
  { id: 586, cat: "多旋翼综合", q: "多轴飞行器的飞控指的是（）", opts: ["机载导航飞控系统", "机载遥控接收机", "机载任务系统"], ans: 0, exp: "题目解析：多轴飞行器的飞控指的是机载导航飞控系统，这是飞行器中用于控制和导航的关 键系统。飞控系统负责处理来自传感器的数据，执行飞行控制算法，以及发送指令给执行机 构（如电机），以保持飞行器的稳定飞行和执行预定的飞行任务。飞控系统通常包括姿态控 制、导航、自动飞行控制等功能。" },
  { id: 587, cat: "多旋翼综合", q: "多轴飞行器的遥控一般有（）", opts: ["2 个通道", "3 个通道", "4 个及以上通道"], ans: 2, exp: "多轴飞行器的遥控器一般有 4 个及以上通道。这是因为操纵多轴至少需要 4 通道，分 别控制油门、航向、俯仰和横滚。实际上，最低配置也需要 6 通道的遥控器。更多的通道可 以用来控制云台的角度、相机的快门、开关夜航灯光或者抛下物品。因此，正确答案是 4 个及以上通道。" },
  { id: 588, cat: "多旋翼综合", q: "多轴飞行器定点半径画圆飞行时，如何能得到最佳航拍画面？（）", opts: ["平移画面", "绕圈一周", "边绕圈边上升"], ans: 2, exp: "多轴飞行器定点半径画圆飞行时，要得到最佳的航拍画面，需要考虑飞行器的稳定性、拍摄设备的选择、飞行高度的调整、拍摄角度的选择、飞行速度的调整以及天气和环境因素 等多个因素。其中，边绕圈边上升的飞行方式能够增加画面的动态感和视觉冲击力，从而获 得最佳航拍画面。" },
  { id: 589, cat: "多旋翼综合", q: "多轴飞行器都有哪些用途：①应急救灾；②军用侦查；③警用监视；④娱乐；⑤广电行 业。（）", opts: ["①④⑤", "②③④", "①②③④⑤"], ans: 2, exp: "这道题主要考查对多轴飞行器用途的了解。多轴飞行器具有多种用途： ①“应急救灾”方面，它能够快速到达灾区，获取信息、运输物资等，帮助救援工作开展。 ②“军用侦察”中，其灵活的飞行特点可执行侦察任务，获取情报。 ③“警用监视”时，能够协助警方监控特定区域，提高执法效率。 ④“娱乐”领域，如作为模型飞机供爱好者飞行娱乐。 ⑤“广电行业”里，用于拍摄视频、直播等，提供不同视角的画面。 所以综合来看，多轴飞行器的用途涵盖了①应急救灾、②军用侦察、③警用监视、④娱乐、⑤广电行业。" },
  { id: 590, cat: "多旋翼综合", q: "多轴飞行器飞控板上一般会安装（）", opts: ["1 个角速率陀螺", "6 个角速率陀螺", "3 个角速率陀螺"], ans: 2, exp: "角速率陀螺（又称角速度计或陀螺仪）用于测量飞行器绕空间三轴（滚转、俯仰、偏 航）的转动角速度。通过积分计算（角速度×时间=角度），可得到飞行器各轴的转动角度。 由于单个陀螺仪只能测量一个轴向的运动，因此需要 3 个陀螺仪来完整监测三轴姿态变化。" },
  { id: 591, cat: "多旋翼综合", q: "多轴飞行器飞控软件使用中要特别注意的事项，不包括（）", opts: ["版本", "文件大小", "各通道正反逻辑设置"], ans: 1, exp: "在多轴飞行器飞控软件的使用中，需要注意软件的版本以确保兼容性和功能的最新性，同时还需要关注各通道的正反逻辑设置，以确保遥控器的操作与飞行器的响应是正确的。文 件大小通常不是飞控软件使用中需要特别注意的事项，因为它不影响软件的功能和飞行器的 控制。" },
  { id: 592, cat: "多旋翼综合", q: "多轴飞行器飞行时，使用哪种模式，驾驶员压力最大？（）", opts: ["GPS 模式", "增稳模式", "纯手动模式"], ans: 2, exp: "在多轴飞行器飞行时，纯手动模式下，飞行器的控制完全依靠驾驶员手动操作，没有 GPS 辅助定位和稳定系统的支持，也没有增稳模式的自动平衡调节。这就要求驾驶员凭借自 身的技能和经验来精准控制飞行器的姿态、速度和方向，对驾驶员的技术和反应能力提出了 极高的要求，因此压力最大。" },
  { id: 593, cat: "多旋翼综合", q: "多轴飞行器飞行中，图像叠加 OSD 信息显示的电压一般为电池的（）", opts: ["空载电压", "负载电压", "已使用电压"], ans: 1, exp: "在多轴飞行器飞行中，图像叠加 OSD 信息显示的电压一般为电池的负载电压。当飞行 器在飞行时，电池处于放电状态，给各个部件供电，此时显示的是负载电压。" },
  { id: 594, cat: "多旋翼综合", q: "多轴飞行器航拍中，果冻效应或水波效应产生的原因是（）", opts: ["高频振动传递到摄像机", "低频振动传递到摄像机", "摄像机无云台增稳"], ans: 0, exp: "在多轴飞行器航拍中，果冻效应或水波纹效应主要是由于高频振动传递到摄像机引起 的。多轴飞行器在飞行过程中，电机的转动、螺旋桨的高速旋转等会产生一定的振动，当这 些高频振动传递到安装在飞行器上的摄像机时，就会使拍摄的画面出现果冻效应或水波纹效 应。" },
  { id: 595, cat: "多旋翼综合", q: "多轴飞行器起降时接触地面的是（）", opts: ["机架", "云台架", "脚架"], ans: 2, exp: "多轴飞行器起降时接触地面的部分通常是脚架。 脚架是专门设计来吸收着陆时的冲击，保护飞行器主体结构和关键部件的。它们通常位于飞 行器的底部，可以是固定式的或者可伸缩式的，以适应不同的起降环境。" },
  { id: 596, cat: "多旋翼综合", q: "多轴飞行器前飞时，单个旋翼（）", opts: ["前行桨叶相对气流速度小于后行桨叶相对气流速度", "前行桨叶相对气流速度大于后行桨叶相对气流速度", "前行桨叶相对气流速度等于后行桨叶相对气流速度"], ans: 1, exp: "在多轴飞行器前飞时，由于飞行器的前进运动，旋翼的前行桨叶（即旋转方向与飞行 器前进方向相同的桨叶）会与相对气流发生相对运动，其相对气流速度是旋翼旋转速度与飞 行器前进速度的矢量和。而后行桨叶（即旋转方向与飞行器前进方向相反的桨叶）的相对气 流速度则是旋翼旋转速度与飞行器前进速度的矢量差。因此，前行桨叶的相对气流速度大于 后行桨叶的相对气流速度。" },
  { id: 597, cat: "多旋翼综合", q: "多轴飞行器悬停时的平衡不包括（）", opts: ["俯仰平衡", "方向平衡", "前飞废阻力平衡"], ans: 2, exp: "多轴飞行器悬停时主要考虑的平衡状态有俯仰平衡、方向平衡等。俯仰平衡是确保飞 行器在悬停时不会出现前倾或后仰的情况；方向平衡是保证飞行器在悬停时不会发生偏航。 而前飞废阻力平衡是在飞行器前飞状态下需要考虑的，在悬停时并不涉及前飞的阻力问题。" },
  { id: 598, cat: "多旋翼综合", q: "多轴飞行器悬停转向和以 10km/h 速度前飞转向中，（）", opts: ["横滚角相同", "横滚角不同", "横滚角不确定"], ans: 1, exp: "多轴飞行器在悬停转向时，主要是通过调整各个电机的转速来实现转向，此时横滚角 相对较小。而以 10km/h 速度前飞转向时，除了调整电机转速外，还会产生一定的倾斜角度 以获得转向的向心力，横滚角会比悬停转向时大很多。所以在这两种情况下横滚角不同。" },
  { id: 599, cat: "多旋翼综合", q: "多轴飞行器在风中悬停时下列影响正确的是（）", opts: ["与无风悬停相比，逆风悬停机头稍低，且逆风速越大，机头越低", "一般情况下，多轴飞行器应尽量在顺风中悬停", "侧风的作用将使多轴飞行器沿风的去向位移，因此，侧风悬停时应向风来的反方向压杆"], ans: 0, exp: "当多轴飞行器在风中悬停时，逆风悬停会受到风的阻力。由于风从前方吹来，会给飞 行器一个向后的力，为了保持平衡，飞行器会产生一个低头的姿态，且逆风速越大，这个阻 力就越大，机头就会越低。" },
  { id: 600, cat: "多旋翼综合", q: "多轴飞行器在没有发生机械结构改变的前提下，如发生偏移，不能直线飞行时，不需要 关注的是（）", opts: ["GPS 定位", "指南针校准", "调整重心位置"], ans: 2, exp: "多轴飞行器在没有发生机械结构改变的前提下，如果发生漂移，不能直线飞行，通常 需要关注的是飞行控制系统和导航系统的问题。GPS 定位问题可能会导致飞行器位置信息不 准确，而指南针校准则是确保飞行器能够正确识别方向，避免因为磁场干扰导致的飞行偏差。 调整重心位置通常与飞行器的机械结构有关，如果机械结构没有改变，那么重心位置也不会 发生变化，因此不需要关注。" },
  { id: 601, cat: "多旋翼综合", q: "多轴飞行器在前飞中必然会产生（）变化", opts: ["偏航角", "横滚角", "俯仰角"], ans: 2, exp: "多轴飞行器在前飞中必然会产生的变化是俯仰角变化。这是因为在前飞过程中，飞行 器需要通过调整其姿态来保持稳定和控制方向，而俯仰角是描述飞行器围绕其垂直轴（y 轴）的旋转角度，决定了飞行器的前后倾斜程度。当飞行器向前倾斜时，会产生一个水平分力，从而使飞行器向前飞行，这时俯仰角会发生变化。" },
  { id: 602, cat: "多旋翼综合", q: "多轴飞行器在运输过程中的注意事项是（）", opts: ["做好减震措施，固定云台并安装云台固定支架，装箱运输", "装箱运输，也可行李箱运输", "可随意拆装运输"], ans: 0, exp: "多轴飞行器在运输过程中的注意事项是做好减震措施，固定云台并安装云台固定支架，装箱运输。这是为了确保在运输过程中飞行器及其部件不会因震动或撞击而损坏，保障运输 安全。" },
  { id: 603, cat: "多旋翼综合", q: "多轴飞行器正常作业受自然环境影响的主要因素是（）", opts: ["地表是否凹凸平坦", "风向", "温度、风力"], ans: 2, exp: "多轴飞行器在正常作业时受自然环境影响的主要因素包括温度和风力。温度的变化会 影响电池的性能和飞行器的飞行特性，而风力的大小则直接影响飞行器的稳定性和操控性。" },
  { id: 604, cat: "多旋翼综合", q: "多轴飞行器重心过高于或过低于桨平面会（）", opts: ["增加稳定性", "降低机动性", "显著影响电力消耗"], ans: 1, exp: "重心过高或过低都不利于四旋翼飞行器的飞行稳定性。在控制器不变的前提下，若重 心过高，飞行器在进行姿态控制时，容易出现类似控制上“超调”的现象；若重心过低，飞 行器在进行姿态控制时，容易出现类似控制上“滞后”的现象。此外，重心离开螺旋桨平面 越远只能增加飞行器的惰性，使动作变得缓慢迟钝，不适合机动飞行，控制变得缓慢而笨重。 因此，重心过高于或过低于桨平面会降低机动性。" },
  { id: 605, cat: "多旋翼综合", q: "多轴航拍飞行器难以完成哪种工作？（）", opts: ["测绘", "直播", "超远距离监控"], ans: 2, exp: "多轴航拍飞行器可以进行测绘工作，通过搭载相应的测绘设备，在一定范围内进行地 形、地貌等的测绘。也可以进行直播，将拍摄到的画面实时传输进行直播。但是多轴航拍飞 行器由于其续航能力、通信距离等限制，难以完成超远距离监控工作。一般多轴航拍飞行器 的飞行距离和控制距离有限，无法实现超远距离的监控。" },
  { id: 606, cat: "多旋翼综合", q: "多轴航拍中往往需要使用相机的位移补偿功能，导致使用此功能的原因是（）", opts: ["飞行器的速度", "风速", "飞行器姿态不稳"], ans: 0, exp: "在多轴航拍中，使用相机的位移补偿功能主要是为了应对飞行器在飞行过程中的速度 变化。由于飞行器在飞行时可能会因为速度的变化导致拍摄画面出现模糊或不稳定，位移补 偿功能可以帮助相机快速调整焦点和曝光，以适应飞行器速度的变化，确保拍摄出清晰稳定 的画面。" },
  { id: 607, cat: "多旋翼综合", q: "飞行中的多轴飞行器所承受的力和力矩不包括（）", opts: ["自身重力", "旋翼桨叶的铰链力矩", "旋翼的反扭矩和桨毂力矩"], ans: 1, exp: "飞行中的多轴飞行器主要承受自身重力，重力始终作用在飞行器上。多轴飞行器的旋 翼在旋转时会产生反扭矩，同时也有桨毂力矩，这些都会作用在飞行器上。而旋翼桨叶的铰 链力矩是作用在桨叶与桨毂的连接铰链处，主要影响桨叶的运动，不会直接作用在整个多轴 飞行器上。" },
  { id: 608, cat: "多旋翼综合", q: "给遥控发射机安装增益天线，在使用时一定能提高其遥控范围吗？（）", opts: ["正确", "错误", "不一定"], ans: 2, exp: "在遥控发射机安装增益天线，其遥控范围不一定能提高。这是因为遥控范围受多种因 素影响，如环境干扰、发射功率等。仅安装增益天线，不一定能完全解决所有影响遥控范围 的问题。" },
  { id: 609, cat: "多旋翼综合", q: "关于部分多轴飞行器，机臂上反角设计描述正确的是（）", opts: ["提高稳定性", "提高机动性", "减少电力损耗"], ans: 0, exp: "部分多轴飞行器机臂上反角设计的主要作用是提高飞机的侧向稳定性。上反角能产生 滚转稳定性，为保证飞机有足够的横向稳定性，且不出现“蹬舵反倾”，在机翼安装时需要 上反角或下反角。因此，描述正确的是提高稳定性。" },
  { id: 610, cat: "多旋翼综合", q: "关于多轴飞行器的反扭矩说法不正确的是（）", opts: ["单个旋翼的反扭矩会迫使多轴飞行器向旋翼旋转的反方向偏转", "单个旋翼反扭矩的大小取决于电动机转速", "多轴飞行器的俯仰运动通过改变各个旋翼的反扭矩来实现"], ans: 2, exp: "多轴飞行器的反扭矩是由旋翼旋转产生的，相邻的两个螺旋桨旋转方向相反，这样可 以使得它们产生的反扭矩相互抵消，从而保持飞行器的稳定。因此，多轴飞行器的俯仰运动 并不是通过改变各个旋翼的反扭矩来实现的，而是通过改变旋翼的转速来产生不平衡的力矩，从而实现飞行器的姿态调整。" },
  { id: 611, cat: "多旋翼综合", q: "关于多轴飞行器的优势描述不正确的是（）", opts: ["成本低廉", "气动效率高", "结构简单便携"], ans: 1, exp: "多轴飞行器相比于传统直升机存在一些性能劣势，尤其是气动效率方面。多轴飞行器 的气动效率远不如传统旋翼直升机。因此，关于多轴飞行器的优势描述不正确的是“气动效 率高”。" },
  { id: 612, cat: "多旋翼综合", q: "关于多轴飞行器定义描述正确的是（）", opts: ["具有两个及以上旋翼轴的旋翼航空器", "具有不少于四个旋翼轴的无人旋翼航空器", "具有三个及以上旋翼轴的旋翼航空器"], ans: 2, exp: "多轴飞行器，也称为多旋翼飞行器，是指具有三个或更多旋翼轴的旋翼航空器。这种 设计使得多轴飞行器能够提供稳定的悬停和飞行能力，同时减少了对复杂机械结构的依赖，如直升机所需的尾桨。多轴飞行器的每个旋翼轴通常配备有一个或多个旋翼，它们可以独立 控制，以实现精确的姿态调整和机动。" },
  { id: 613, cat: "多旋翼综合", q: "描述一个多轴无人机地面遥控发射机是“美国手”，是指（）", opts: ["右手上下动作控制油门或高度", "左手上下动作控制油门或高度", "左手左右动作控制油门或高度"], ans: 1, exp: "“美国手”遥控器的操作方式是：左手上下动作控制油门或高度，左手左右动作控制 航向（偏航）；右手上下动作控制前进后退，右手左右动作控制左右平移。" },
  { id: 614, cat: "多旋翼综合", q: "描述一个多轴无人机地面遥控发射机是“日本手”，是指（）", opts: ["右手上下动作控制油门或高度", "左手上下动作控制油门或高度", "左手左右动作控制油门或高度"], ans: 0, exp: "“日本手”是指在遥控器的操作模式中，右手的上下动作控制油门或高度，而左手控 制飞行器的前后和左右移动。这种操作模式在日本较为流行，因此被称为“日本手”" },
  { id: 615, cat: "多旋翼综合", q: "民航旅客行李中携带锂电池的额定能量超过（）严禁携带", opts: ["100Wh", "120Wh", "160Wh"], ans: 2, exp: "在民航规定中，旅客行李携带的锂电池，当额定能量超过 160Wh 时严禁携带。这是出 于安全考量，防止锂电池能量过高可能带来的风险。" },
  { id: 616, cat: "多旋翼综合", q: "民用无人机的舵机一般输出形成是多少？（）", opts: ["正负 10 度", "正负 20 度", "正负 120 度"], ans: 1, exp: "民用无人机上的舵机一般输出行程为正负 20 度。 这是无人机舵机的常见设计标准，能够满足飞行控制和姿态调整的需求。" },
  { id: 617, cat: "多旋翼综合", q: "使用多轴飞行器，航拍过程中，必须紧急返航的情况是（）", opts: ["距离过远，高度过高，超出视线范围", "监视器显示无人机电池电量过低", "图传监视器有干扰不稳定"], ans: 1, exp: "电池电量过低是必须紧急返航的首要情况，避免无人机因电量耗尽失控或坠毁。其他 选项虽需注意，但非立即返航的强制条件。安全飞行应优先保障电力充足。" },
  { id: 618, cat: "多旋翼综合", q: "使用多轴飞行器，航拍过程中，关于曝光描述错误的是（）", opts: ["全自动拍摄", "以拍摄主体为主，预先设定好曝光量", "最好用高 ISO 来拍摄"], ans: 2, exp: "在使用多轴飞行器进行航拍过程中，曝光设置是非常关键的。全自动拍摄可以让相机 自动调整曝光参数，适合快速拍摄或初学者。以拍摄主体为主，预先设定好曝光量是专业拍 摄中常用的方法，可以确保主体曝光正确。而使用高 ISO 来拍摄通常不是推荐的做法，因为 高 ISO 会增加图像的噪点，降低画质，尤其在光线充足的环境下，没有必要使用高 ISO 值。" },
  { id: 619, cat: "多旋翼综合", q: "使用多轴飞行器，航拍过程中，为了保证画面明暗稳定，相机尽量设定为（）", opts: ["光圈固定", "快门固定", "ISO 固定"], ans: 2, exp: "在多轴飞行器航拍中，为保证画面明暗稳定，相机的 ISO 固定较为关键。因为光圈固 定可能影响景深，快门固定可能影响拍摄的动态效果，而 ISO 固定能在一定程度上稳定画面 的明暗程度。" },
  { id: 620, cat: "多旋翼综合", q: "使用多轴飞行器，拍摄夜景时，应（）", opts: ["降低飞行速度，保证正常曝光", "降低飞行高度，保证正常曝光", "与白天没有明显区别"], ans: 0, exp: "在夜景拍摄中，由于光线较暗，为了保持正常曝光，需要较长的曝光时间。为了防止 拍摄时的晃动造成模糊，应该降低飞行速度，以保证飞行器在拍摄过程中相对稳定，从而获 得清晰的夜景图像。" },
  { id: 621, cat: "多旋翼综合", q: "使用多轴飞行器航拍过程中，温度对摄像机的影响描述正确的是（）", opts: ["在温差较大的环境中拍摄要注意镜头的结雾", "在温度较高的环境拍摄摄像机电池使用时间短", "在温度较低的环境拍摄相机电池使用时间长"], ans: 0, exp: "在使用多轴飞行器进行航拍过程中，温度对摄像机的影响主要体现在温差较大的环境 中，由于温差导致空气中的水汽凝结，可能会在摄像机镜头上形成雾气，影响拍摄效果。因 此，在温差较大的环境中拍摄时，需要特别注意镜头的结雾问题。" },
  { id: 622, cat: "多旋翼综合", q: "使用多轴飞行器航拍时，以下哪种方法可以改善画面的“水波纹”现象？（）", opts: ["提高飞行速度", "改善云台和电机的减震性能", "改用姿态模式飞行"], ans: 1, exp: "多轴飞行器在飞行过程中，电机的转动和云台的操作等都会产生振动，这些振动如果 传递到拍摄设备，就容易产生水波纹现象。通过改善云台和电机的减震性能，可以有效减少 振动传递到摄像机，从而改善画面质量，减少水波纹现象。" },
  { id: 623, cat: "多旋翼综合", q: "使用多轴飞行器作业，（）", opts: ["应在人员密集区，如公园、广场等", "在规定空域使用，且起飞前提醒周边人群远离", "不受环境影响"], ans: 1, exp: "使用多轴飞行器作业时，在规定空域使用可以确保飞行的合法性和安全性，起飞前提 醒周边人群远离可以避免对他人造成伤害，这是正确的做法。" },
  { id: 624, cat: "多旋翼综合", q: "围绕多轴飞行器横轴的是什么运动？（）", opts: ["滚转运动", "俯仰运动", "偏航运动"], ans: 1, exp: "围绕多轴飞行器横轴的运动是俯仰运动。俯仰运动是指飞行器绕横轴（Y 轴）的旋转，这个轴从一个翼尖延伸到另一个翼尖，抬头或低头的动作就是围绕这个轴进行的。在多轴飞 行器中，俯仰运动通常由飞行器的前后倾斜来实现，从而改变飞行器的飞行高度或进行前后 移动。" },
  { id: 625, cat: "多旋翼综合", q: "围绕多轴飞行器立轴的是什么运动？（）", opts: ["滚转运动", "俯仰运动", "偏航运动"], ans: 2, exp: "偏航运动是指飞行器围绕立轴（垂直轴）的转动，这个轴穿过飞行器的重心，且垂直 于俯仰轴和横滚轴。偏航运动由方向舵控制，方向舵偏转一定角度便会产生一定的偏航角速 度。" },
  { id: 626, cat: "多旋翼综合", q: "围绕多轴飞行器纵轴的是什么运动？（）", opts: ["滚转运动", "俯仰运动", "偏航运动"], ans: 0, exp: "围绕多轴飞行器纵轴的运动是滚转运动。滚转运动是指飞行器围绕纵轴（X 轴）的转 动，这个轴穿过飞行器的重心，且平行于飞行器的机头方向。在多轴飞行器中，滚转运动通 常由飞行器的横滚控制面（如副翼）控制，通过改变左右两侧升力的差异来实现飞行器的滚 转。" },
  { id: 627, cat: "多旋翼综合", q: "为了克服旋翼旋转产生的反作用（），常见的做法是用另一个小型旋翼，即尾桨，在机 身尾部产生抵消反向作用的力矩", opts: ["力", "力矩", "扭矩"], ans: 2, exp: "旋翼旋转会产生反扭矩，这会影响飞行器的稳定性。为了克服这一反扭矩，采用尾桨 在机身尾部产生抵消的力矩是常见且有效的做法。" },
  { id: 628, cat: "多旋翼综合", q: "无人机的轴是指（）", opts: ["舵机轴", "旋翼轴", "方向轴"], ans: 1, exp: "无人机的轴通常指的是旋翼轴。这是因为无人机的飞行主要依靠旋翼的旋转产生升力 和控制力，所以旋翼轴在其结构和工作原理中具有关键地位。" },
  { id: 629, cat: "多旋翼综合", q: "无人机飞行控制系统速率陀螺是感知飞行器平台（）的传感器", opts: ["姿态角", "角速度", "航向角"], ans: 1, exp: "无人机飞行控制系统中的速率陀螺，也称为角速度传感器，其主要功能是感知无人机 绕机体轴的转动角速率。" },
  { id: 630, cat: "多旋翼综合", q: "无人机直升机或多旋翼飞行器飞行时间的含义是指（）", opts: ["起飞离地到着陆接地的瞬间", "起飞滑跑至着陆滑跑终止的瞬间", "旋翼开始转动至旋翼停止转动的瞬间"], ans: 2, exp: "无人直升机或多旋翼飞行器的飞行时间通常指的是从旋翼开始转动至旋翼停止转动的 整个时间段。这个定义覆盖了飞行器从启动、起飞、执行任务到降落、旋翼完全停止的整个 过程。" },
  { id: 631, cat: "多旋翼综合", q: "下列哪个选项中的直升机的分类方式是相同的？（）", opts: ["3 代直升机，变模态无人旋翼机，复合无人旋翼机", "微型直升机，轻型无人直升机，四轴飞行器", "单旋翼带尾桨式无人直升机，双旋翼共轴式无人直升机，多轴无人飞行器"], ans: 2, exp: "单旋翼带尾桨式无人直升机是指有一个主旋翼和一个尾桨来抵消旋翼产生的反扭矩。 双旋翼共轴式无人直升机是指有两个旋翼上下排列，在同一个轴线上反向旋转。多轴无人飞 行器是指具有三个及以上旋翼轴的无人驾驶旋翼飞行器。这三种分类方式都是基于旋翼的配 置和布局来区分不同类型的直升机和飞行器。" },
  { id: 632, cat: "多旋翼综合", q: "下列哪个因素对多轴航拍效果影响最大？（）", opts: ["风速", "负载体积", "负载类型"], ans: 0, exp: "风速对多轴航拍效果影响最大。如果风速较大，多轴飞行器在飞行过程中会受到较大 的风力干扰，可能导致飞行不稳定，晃动明显，从而使拍摄的画面出现抖动、模糊等情况，极大地影响航拍效果。" },
  { id: 633, cat: "多旋翼综合", q: "下列哪个姿态角的变化对多轴航拍影响最大？（）", opts: ["俯仰角", "横滚角", "航向角"], ans: 2, exp: "航向角的变化对多轴航拍影响最大。航向角决定了飞行器的飞行方向，当航向角发生 变化时，航拍的视角方向会发生较大改变，直接影响到拍摄的画面内容和构图。如果航向角 变化不稳定或者突然改变，会导致拍摄的视频或照片连贯性差，难以获得理想的拍摄效果。" },
  { id: 634, cat: "多旋翼综合", q: "下列哪种方式可以使多轴飞行器搭载的摄影装备拍摄角度实现全仰拍摄且不穿帮？（）", opts: ["多轴飞行器使用折叠式脚架", "多轴飞行器搭载下沉式云台", "多轴飞行器搭载前探式云台"], ans: 2, exp: "多轴飞行器搭载前探式云台可以使摄影装备向前探出，从而实现全仰拍摄且不穿帮。 前探式云台能够将摄影设备伸出一定距离，在拍摄仰角时不会被飞行器的机身等部分遮挡。" },
  { id: 635, cat: "多旋翼综合", q: "下列哪种方式有可能提高多旋翼飞行器的载重？（）", opts: ["桨叶直径不变，电机功率变小且桨叶总距变小", "桨叶总距不变，电机功率变大且桨叶直径变大", "电机功率不变桨叶直径变大且桨叶总距变大"], ans: 1, exp: "对于多旋翼飞行器来说，要提高载重能力，需要有更大的升力。桨叶总距不变，电机 功率变大可以提供更强的动力，而桨叶直径变大也能增加升力面积，从而产生更大的升力，提高载重。" },
  { id: 636, cat: "多旋翼综合", q: "下列哪种形式的旋翼飞行器不是直升机？（）", opts: ["多轴飞行器", "共轴双旋翼式", "自转旋翼式"], ans: 2, exp: "自转旋翼式飞行器，如自转旋翼机（gyroplane），其旋翼不是由发动机直接驱动，而 是依靠飞行器前进时的气流使旋翼自转，从而产生升力，因此它不被归类为直升机。 直升机是指那些使用一个或多个旋翼提供升力和推进力的飞行器，这些旋翼可以是由发动机 驱动的。多轴飞行器和共轴双旋翼式飞行器都属于直升机的范畴。" },
  { id: 637, cat: "多旋翼综合", q: "下列属于现今多轴飞行器典型应用的是（）", opts: ["高空长航时侦查", "航拍、电影取景", "侦打一体化"], ans: 1, exp: "航拍和电影取景是现今多轴飞行器的典型应用。多轴飞行器具有灵活、稳定、可悬停 等特点，能够搭载摄影设备进行不同角度的拍摄，在航拍和电影制作中广泛应用，可以获得 高质量的画面。" },
  { id: 638, cat: "多旋翼综合", q: "下面关于多旋翼的说法错误的是（）", opts: ["本质上讲旋翼是一个能量转换部件，它把电动机传来的旋转动能转换成旋翼拉力", "旋翼的基本功能是产生旋翼拉力", "旋翼的基本功能是产生前进推力"], ans: 2, exp: "多轴旋翼飞行器的旋翼主要功能是产生拉力，以克服飞行器的重力，实现垂直起降和 悬停。旋翼并不直接产生前进推力，前进推力的产生通常是通过改变旋翼的总距或通过飞行 器的前进速度来实现的。因此，选项“旋翼的基本功能是产生前进推力”是错误的。" },
  { id: 639, cat: "多旋翼综合", q: "下面说法正确的是（）", opts: ["一般来讲，多轴飞行器反扭矩的数值是比较大的", "多轴飞行器在稳定垂直上升时，所有旋翼总的反扭之和增加", "多轴飞行器的反扭矩通过旋翼两两互相平衡"], ans: 2, exp: "多轴飞行器的反扭矩（也称为反作用扭矩）是由于旋翼旋转产生的，它会使飞行器产 生旋转的趋势。为了抵消这种旋转，多轴飞行器的设计使得旋翼两两相对，即每个顺时针旋 转的旋翼都有一个对应的逆时针旋转的旋翼，这样它们的反扭矩可以相互抵消，从而保持飞 行器的稳定。" },
  { id: 640, cat: "多旋翼综合", q: "相对于传统直升机，多轴的劣势是（）", opts: ["速度", "载重能力", "悬停能力"], ans: 0, exp: "相对于传统直升机，多轴飞行 0 器（多旋翼）的劣势主要在于速度。传统直升机由于 其独特的旋翼设计和动力系统，能够达到较高的飞行速度和较大的机动性。相比之下，多轴 飞行器由于其多个旋翼产生的阻力和动力限制，通常速度较慢，且在高速飞行时效率较低。" },
  { id: 641, cat: "多旋翼综合", q: "相对于传统直升机，多轴最大的优势是（）", opts: ["气动效率高", "载重能力强", "结构与控制简单"], ans: 2, exp: "相对于传统直升机，多轴旋翼飞行器最大的优势在于结构与控制简单。多轴旋翼飞行 器的控制完全由四个无刷马达的转速变化实现，输入功率、马达转速、旋翼升力、机体角加 速度之间的关系很简单，对整架飞机的动力学建模简洁又精确。 机械结构非常简单，指令实现为动作时没有误差，而传统直升机的周期距控制机械结构极其 复杂，误差较大。因此，选项“结构与控制简单”是正确的。" },
  { id: 642, cat: "多旋翼综合", q: "悬停状态的六轴飞行器如何实现向前移动？（）", opts: ["纵轴右侧的螺旋桨减速，纵轴左侧的螺旋桨加速", "横轴前侧的螺旋桨减速，横轴后侧的螺旋桨加速", "横轴前侧的螺旋桨加速，横轴后侧的螺旋桨减速"], ans: 1, exp: "当六轴飞行器处于悬停状态时，要实现向前移动，需要产生一个向前的倾斜角度。横 轴前侧的螺旋桨减速，横轴后侧的螺旋桨加速，会使飞行器绕横轴向前倾斜，从而产生向前 的分力，实现向前移动。" },
  { id: 643, cat: "多旋翼综合", q: "悬停状态的四轴飞行器如何实现向后移动？（）", opts: ["纵轴右侧的螺旋桨减速，纵轴左侧的螺旋桨加速", "横轴前侧的螺旋桨减速，横轴后侧的螺旋桨加速", "横轴前侧的螺旋桨加速，横轴后侧的螺旋桨减速"], ans: 2, exp: "悬停状态的四轴飞行器要实现向后移动，需要在飞行器前方产生较小的推力，后方产 生较大的推力。在四轴飞行器中，相对的两个螺旋桨旋转方向是相反的，所以当需要飞行器 向后移动时，需要让前方的螺旋桨（横轴前侧）加速以产生更大的向下推力，同时让后方的 螺旋桨（横轴后侧）减速以减少向下推力，这样飞行器就会因为后方的推力大于前方而向后 移动。" },
  { id: 644, cat: "多旋翼综合", q: "悬停状态的四轴飞行器如何实现向左移动？（）", opts: ["纵轴右侧的螺旋桨加速，纵轴左侧的螺旋桨减速", "横轴前侧的螺旋桨加速，横轴后侧的螺旋桨减速", "纵轴右侧的螺旋桨减速，纵轴左侧的螺旋桨加速"], ans: 0, exp: "四轴飞行器在悬停状态时，要实现向左移动，需要让飞行器产生向左的水平分力。通 过纵轴右侧的螺旋桨加速，纵轴左侧的螺旋桨减速，可以使飞行器右侧升力增大，左侧升力 减小，从而产生向左的水平分力，实现向左移动。" },
  { id: 645, cat: "多旋翼综合", q: "悬停状态下，多轴飞行器单个旋翼形成（）", opts: ["正锥体", "平面", "倒锥体"], ans: 2, exp: "在多轴飞行器悬停状态下，单个旋翼形成的形状是倒锥体。这是因为旋翼高速旋转时 产生的离心力导致旋翼上的叶片向外分散，而旋翼的中心是固定的，因此旋翼的形状会呈现 出倒锥体的形状。" },
  { id: 646, cat: "多旋翼综合", q: "旋翼机可以用（）的飞行代替滑行", opts: ["1 米至 5 米高度", "1 米至 10 米高度", "1 米至 15 米高度"], ans: 1, exp: "旋翼机在起飞时，通常可以在相对较低的 1 米至 10 米高度进行短距离的飞行来达到 加速和起飞的目的，从而代替传统飞机较长距离的地面滑行。" },
  { id: 647, cat: "多旋翼综合", q: "旋翼机下降过程中，正确的方法是（）", opts: ["一直保持快速垂直下降", "先慢后快", "先快后慢"], ans: 2, exp: "旋翼机在下降过程中，正确的方法是先快后慢。这是因为在下降初期，旋翼机需要较 快地减少高度以确保安全，同时减少因下降过慢而产生的漂移。当旋翼机接近地面时，应该 减缓下降速度，以实现平稳着陆，避免因下降过快而造成撞击或损坏。" },
  { id: 648, cat: "多旋翼综合", q: "一般来讲，多轴飞行器在地面风速大于（）时作业，会对飞行器安全和拍摄稳定有影响", opts: ["2 级", "4 级", "6 级"], ans: 1, exp: "多轴飞行器在进行航拍作业时，风速是影响其安全和拍摄稳定性的重要因素。一般来 讲，多轴飞行器在地面风速大于 4 级时作业，会对飞行器安全和拍摄稳定有影响。这是因为 风速过大会导致飞行器受到较大的外力干扰，影响其悬停和飞行的稳定性，增加操控难度，同时也会影响拍摄画面的稳定性。" },
  { id: 649, cat: "多旋翼综合", q: "以多轴航拍飞行器为例，是否轴数越多载重能力越大？（）", opts: ["是", "不是", "不一定"], ans: 2, exp: "多轴航拍飞行器的载重能力并不单纯由轴数决定。虽然轴数的增加可以提供更多的动 力，从而在一定程度上增强载重能力，但同时也会带来飞行器自重的增加和耗电量的提高。 因此，轴数越多并不一定意味着载重能力越大，需要综合考虑飞行器的设计、电池续航、电 机效率等多种因素。" },
  { id: 650, cat: "多旋翼综合", q: "以下不是多轴飞行器的优点的是（）", opts: ["结构简单", "成本低廉", "气动效率高"], ans: 2, exp: "多轴飞行器的优点包括结构简单和成本相对较低。而多轴飞行器的气动效率并不高，尤其是与固定翼飞机相比，因为它们的设计主要是为了提供垂直起降和悬停能力，而不是为 了高效巡航。因此，“气动效率高”不是多轴飞行器的优点。" },
  { id: 651, cat: "多旋翼综合", q: "以下飞行器不是多轴飞行器的是（）", opts: ["Phantom 精灵", "lnspire 悟", "Uh-60 黑鹰"], ans: 2, exp: "Phantom 精灵和 Inspire 悟都是多轴飞行器，它们都是由 DJI 大疆创新公司生产的四 轴飞行器。而 Uh-60 黑鹰直升机是一种常规直升机，不属于多轴飞行器。" },
  { id: 652, cat: "多旋翼综合", q: "以下说法错误的是（）", opts: ["一般来讲，常规直升机尺度较大，多轴飞行器尺度较小", "一般来讲，常规直升机以油动为主，多轴飞行器基本都是电动力", "一般来讲，常规直升机飞行中主要改变转速，多轴飞行器飞行中主要改变桨距"], ans: 2, exp: "常规直升机在飞行中主要通过改变旋翼的转速来控制升力和速度，而多轴飞行器飞行 中主要通过改变电机的转速来改变每个旋翼的升力，而不是改变桨距。桨距的改变主要用于 起飞和降落时的过渡阶段，而不是飞行中的常规操作。因此该选项的说法是错误的。" },
  { id: 653, cat: "多旋翼综合", q: "影响悬停稳定性的因素不包括（）", opts: ["起落架形式", "风的影响", "地面效应"], ans: 0, exp: "起落架形式主要影响的是起降时的稳定性和地面移动时的稳定性，对空中悬停稳定性 的影响不大。影响悬停稳定性的因素包括风的影响和地面效应。风的影响会导致无人机受到 额外的力和力矩，影响其悬停的稳定性。地面效应指的是无人机靠近地面时，由于地面的阻 碍作用，空气流动受到限制，导致无人机下方的气流变化，影响升力分布，进而影响悬停稳 定性。" },
  { id: 654, cat: "多旋翼综合", q: "在多轴飞行器航空摄影中，日出日落拍摄时，摄像机白平衡调整应调整为（）以拍出正 常白平衡画面", opts: ["高色温值", "低色温值", "闪光灯模式"], ans: 1, exp: "在多轴飞行器航空摄影中，日出日落拍摄时，摄像机白平衡调整应调整为低色温值以 拍出正常白平衡画面。这是因为日出日落时的光线属于较为柔和的光线，色温较低，呈现出 暖色调。为了拍摄出正常的白平衡画面，应当调整摄像机的白平衡设置，使其适应较低色温 的光线。" },
  { id: 655, cat: "多旋翼综合", q: "在多轴飞行任务中，触发失控返航时，应如何打断飞控当前任务，取回手动控制权？（）", opts: ["GPS 手动模式切换", "云台状态切换", "航向锁定切换"], ans: 0, exp: "在多轴飞行器航空摄影中，若触发失控返航时，需要打断飞控当前任务并取回手动控 制权，正确的操作是切换到 GPS 手动模式。这是因为在失控返航模式下，飞行器会自动执行 预设的返航程序，而切换到 GPS 手动模式可以让用户重新获得对飞行器的控制，从而可以手 动操作飞行器避开障碍物或进行其他必要的操作。" },
  { id: 656, cat: "多旋翼综合", q: "在升高与下降过程中，无人直升机与多轴飞行器表述正确的是（）", opts: ["无人直升机主要改变旋翼总距，多轴飞行器主要改变旋翼转速", "无人直升机主要改变旋翼转速，多轴飞行器主要改变旋翼总距", "无人直升机主要改变旋翼转速，多轴飞行器同样改变旋翼转速"], ans: 0, exp: "在多轴飞行器和无人直升机的升高与下降过程中，它们的操作原理有所不同。无人直 升机主要通过改变旋翼的总距来实现升高与下降，总距的变化直接影响旋翼的攻角，从而改 变升力。而多轴飞行器由于其结构特点，每个旋翼的攻角是固定的，主要通过改变旋翼的转 速来调整升力，实现升高与下降。 记住两者在升高与下降过程中的不同控制方式，就能准确答题。" },
  { id: 657, cat: "多旋翼综合", q: "WGS-84 坐标系为（）", opts: ["全球坐标系", "国家坐标系", "地方坐标系"], ans: 0, exp: "WGS-84（World Geodetic System 1984）坐标系是一种全球性的地理坐标系统，由美国 国防部开发，主要用于全球定位系统（GPS）。它是一个基于地球椭球体的三维坐标系统，能 够精确描述地球上任意一点的位置。由于其全球覆盖性和高精度，WGS-84 被广泛应用于航 空、航海、地理信息系统（GIS）和卫星导航等领域。" },
  { id: 658, cat: "多旋翼综合", q: "多轴的飞控应该尽量安装在重心位置（）", opts: ["上", "中", "下"], ans: 0, exp: "多轴无人机的飞控应该尽量安装在重心位置的上方。这是因为飞控安装在重心上方可 以减小飞行器的惯性矩，从而提高操控的敏感性和稳定性。" },
  { id: 659, cat: "多旋翼综合", q: "哪种导航系统可全天候，全时间地工作在空中、地球表面乃至水下？（）", opts: ["惯性导航", "GPS 导航", "天文导航"], ans: 0, exp: "惯性导航系统（INS）是一种自主式导航系统，通过测量运载体的加速度和角速度，经过积分运算得到速度和位置信息，从而实现导航定位。是唯一能够满足全天候、全时间在 多种环境工作的导航系统。" },
  { id: 660, cat: "多旋翼综合", q: "北纬 42°30′00″为（）", opts: ["北纬 42.3 度", "北纬 42.5 度", "北纬 42 度，东经 30 度"], ans: 1, exp: "题目考察的是经纬度单位换算，需要将度分秒（DMS）格式转换为十进制（DD）格式。 1 度等于 60 分，1 分等于 60 秒。30'00\"表示 30 分，转换为度为 30/60=0.5 度。 因此，北纬 42°30′00″等于北纬 42.5 度。" },
  { id: 661, cat: "多旋翼综合", q: "PD 控制器是一种线性控制器，它主要根据给定值和实际输出值的控制偏差，然后利用 （），给出合理的控制量。", opts: ["实际值", "偏差", "给定值"], ans: 1, exp: "PD 控制器是一种线性控制器，它主要根据给定值和实际输出值的偏差，然后利用偏 差及其变化率（即偏差的导数），给出合理的控制量。" },
  { id: 662, cat: "多旋翼综合", q: "开控前检查事项（）", opts: ["油门低位，拨杆档位是否在合适位置，天线是否纵向", "油门低位，拨杆档位是否在合适位置，天线是否横向", "油门中立，拨杆档位是否在合适位置，天线是否纵向"], ans: 1, exp: "在开启遥控器（开控）前，需要进行以下检查：1、油门低位：油门杆必须处于最低位，这是为了确保在开启遥控器时，无人机不会意外启动或突然加速。 这是飞行安全的基本要求。 2、拨杆档位是否在合适位置：检查遥控器上的各种拨杆、开关等是否处于正确的初始位置，以避免误操作导致意外。 3、天线方向： 遥控器的天线应保持横向（即与地面平行），以确保信号传输的最佳效果。天线横向放置可以 减少信号干扰，提高遥控器与无人机之间的通信稳定性。" },
  { id: 663, cat: "多旋翼综合", q: "当无人机遥控器损坏维修后，再次使用时应该（）", opts: ["要与飞控重新校准", "要与电调重新校准", "要与接收机重新校准"], ans: 2, exp: "当无人机遥控器损坏维修后，再次使用时应该要与接收机重新校准。遥控器与接收机 之间的通信是通过无线信号实现的，维修后可能会改变遥控器的信号特性或内部设置，因此 需要重新校准以确保遥控器与接收机之间的通信正常。" },
  { id: 664, cat: "多旋翼综合", q: "四轴飞行器飞行运动中有（）", opts: ["绕 4 个轴转动", "沿 3 个轴移动", "沿 3 个轴移动，绕 3 个轴转动"], ans: 2, exp: "四轴飞行器的运动可以分为两种基本类型：平移运动和旋转运动。 平移运动：四轴飞行器可以在三维空间中沿三个坐标轴（X、Y、Z）进行移动。例如，它可 以向前、后、左、右、上、下移动。 旋转运动：四轴飞行器也可以绕三个坐标轴（X、Y、z）进行旋转。例如，它可以进行俯仰 （Pitch）、滚转（Roll）和偏航（Yaw）运动。 因此，四轴飞行器的运动包括：沿 3 个轴移动（X、Y、Z 轴）和绕 3 个轴转动（俯仰、滚转、偏航）。" },
  { id: 665, cat: "多旋翼综合", q: "四轴飞行器改变航向时（）", opts: ["相邻的 2 个桨加速，另 2 个桨减速", "相对的 2 个桨加速，另 2 个桨减速", "4 个桨均加速"], ans: 1, exp: "四轴飞行器的四个螺旋桨中有两个顺时针旋转，另外两个逆时针旋转，这样可以抵消 反扭矩。当需要改变航向时，通过调整对角线上两个相同旋转方向的螺旋桨的转速来实现： 顺时针改变航向：对角线上的两个顺时针旋转的螺旋桨加速，另外两个逆时针旋转的螺旋桨 减速。 逆时针改变航向：对角线上的两个逆时针旋转的螺旋桨加速，另外两个顺时针旋转的螺旋桨 减速。" },
  { id: 666, cat: "多旋翼综合", q: "多轴旋翼无人机通过改变（）控制飞行轨迹", opts: ["总距杆", "转速", "尾桨"], ans: 1, exp: "多轴旋翼无人机通过改变电机转速来控制飞行轨迹。具体来说，多轴无人机的桨叶是 固定桨距的，无法通过改变桨距来控制升力，而是通过调整各电机的转速来改变旋翼的升力，从而实现飞行姿态和轨迹的控制。" },
  { id: 667, cat: "多旋翼综合", q: "多轴飞行器飞行运动中有（）", opts: ["6 个自由度，沿 3 轴移动，绕 3 轴转动", "4 个自由度，绕 4 个轴转动", "4 个自由度，沿 3 个轴移动"], ans: 0, exp: "多轴飞行器的运动可以分为两种基本类型：平移运动和旋转运动。 -平移运动：多轴飞行器可以在三维空间中沿三个坐标轴（X、Y、Z）进行移动。例如，它可 以向前、后、左、右、上、下移动。 -旋转运动：多轴飞行器也可以绕三个坐标轴（X、Y、z）进行旋转。例如，它可以进行俯 仰（Pitch）、滚转（Roll）和偏航（Yaw）运动。 因此，多轴飞行器的运动包括： -沿 3 个轴移动（X、Y、Z 轴） -绕 3 个轴转动（俯仰、滚转、偏航）综上所述，正确答案是：6 个自由度，沿 3 轴移动，绕 3 轴转动。" },
  { id: 668, cat: "多旋翼综合", q: "多轴飞行器在前飞中会必然产生（）变化", opts: ["螺距", "周期变距", "转速"], ans: 2, exp: "多轴飞行器在前飞中必然会调整转速来改变姿态并实现前飞。多轴飞行器的前飞原理： 1.通过调整电机转速，使前后旋翼升力不均，产生俯仰姿态，从而实现前飞。 2.前飞时：前侧电机转速降低（减少升力），后侧电机转速升高（增加升力），机身向前倾斜。" },
  { id: 669, cat: "多旋翼综合", q: "四轴做偏航运动时（）", opts: ["相邻两个桨叶转速降低", "相对两个桨叶转速降低", "转速相同"], ans: 1, exp: "四轴飞行器进行偏航运动时，需要通过调整对角线上两个相同旋转方向的螺旋桨的转速来实 现。 具体来说： -顺时针偏航：对角线上的两个顺时针旋转的螺旋桨加速，另外两个逆时针旋转的螺旋桨减 速。 -逆时针偏航：对角线上的两个逆时针旋转的螺旋桨加速，另外两个顺时针旋转的螺旋桨减 速。 这种调整方式利用了螺旋桨的反扭矩来实现飞行器绕垂直轴（Z 轴）的旋转，从而改变航向。 因此，正确答案是：相对两个桨叶转速降低。" },
  { id: 670, cat: "多旋翼综合", q: "无人机使用哪种摄像头可以不受雾霾影响？（）", opts: ["可见光摄像头", "云台摄像头", "红外摄像头"], ans: 2, exp: "红外摄像头属于热成像摄像头，能够捕捉物体发出的红外热辐射，而不依赖可见光。 因此，它不受雾霾、烟尘等环境因素的干扰，可以在雾霾天气中保持清晰的成像。" },
  { id: 671, cat: "多旋翼综合", q: "多旋翼无人机和直升机的区别，错误的是？（）", opts: ["直升机多用油动动力装置", "直升机尺寸大", "多旋翼是改变螺旋桨桨距产生升力，直升机是改变转速产生升力"], ans: 2, exp: "多旋翼是改变螺旋桨桨距产生升力，直升机是改变转速产生升力，这是错误的。实际 上，多旋翼无人机的螺旋桨是固定桨距的，它们通过改变电机的转速来控制升力。而直升机 的旋翼桨叶可以改变桨距（即桨叶的角度），通过调整桨距来控制升力和推力。" },
  { id: 672, cat: "多旋翼综合", q: "高空穿过云层摄像用以下哪个选项（）", opts: ["红外拍摄", "可见光拍摄", "超声波拍摄"], ans: 0, exp: "红外摄像头属于热成像摄像头，能够捕捉物体发出的红外热辐射，而不依赖可见光。 因此，它不受云层、雾霾等环境因素的干扰，可以在云层中清晰地拍摄地面目标。" },
  { id: 673, cat: "多旋翼综合", q: "无人机往地面拍摄，空中有云和雾霭，用什么拍摄？（）", opts: ["可见光 CCD", "红外线摄像头", "无线电雷达"], ans: 1, exp: "红外摄像头属于热成像摄像头，能够捕捉物体发出的红外热辐射，而不依赖可见光。 因此，它不受云雾等环境因素的干扰，可以在云雾天气中保持清晰的成像。" },
  { id: 674, cat: "多旋翼综合", q: "多旋翼无人机轴越多，它的载重量（）", opts: ["越大", "越小", "不一定"], ans: 2, exp: "多旋翼无人机的载重量不仅取决于轴数，还与电机功率、螺旋桨效率、机身结构等因 素有关。例如，增加轴数可能会增加升力，但如果电机功率不足或螺旋桨效率低下，载重量 可能并不会增加。因此，正确答案是：不一定。" },
  { id: 675, cat: "多旋翼综合", q: "当多轴无人机左转弯时，为了能拍出较清晰的照片（相机在同一设置情况下），相机云 台应该（）", opts: ["向左旋转", "向右旋转", "保持不动"], ans: 1, exp: "当多轴无人机左转弯时，为了拍摄清晰的照片，相机云台需要进行相应的调整。 当无人机左转时，为了保持相机拍摄方向的稳定，云台需要向右旋转，以抵消无人机的左转 动作。这样可以确保相机始终对准目标方向，从而拍摄出清晰的照片。" },
  { id: 676, cat: "多旋翼综合", q: "多轴飞行器飞行时，使用哪种模式，飞行前向和主控记录的某一时刻机头朝向一致？ （）", opts: ["GPS 模式", "返航点锁定", "航向锁定"], ans: 2, exp: "只有在航向锁定模式下，飞行前向和主控记录的某一时刻机头朝向才会一致。飞行器 记录某一时刻的机头朝向作为飞行前向。无论机头如何转动，飞行器的飞行方向始终与记录 的航向一致。" },
  { id: 677, cat: "多旋翼综合", q: "多旋翼无人机自动驾驶状态下，安全下降速率应该是哪一个？（）", opts: ["2m/s", "5m/s", "8m/s"], ans: 0, exp: "多旋翼无人机在自动驾驶状态下，安全下降速率应该是 2 米/秒。下降速率过快（如 5 米/秒或 8 米/秒）会导致螺旋桨升力不足，飞行器难以保持平衡，容易失控或翻转。2 米/ 秒是一个较为安全的下降速率，能够在自动驾驶模式下平稳地进行下降，同时避免因速度过 快而引发的问题。" },
  { id: 678, cat: "多旋翼综合", q: "现代旋翼机通常包括（）", opts: ["直升机、旋翼机和倾转旋翼机", "单旋翼和多旋翼", "直升机、多轴和旋翼机"], ans: 0, exp: "现代旋翼机通常包括以下几种类型： 直升机：通过发动机驱动旋翼旋转产生升力，能够垂直起降和悬停。 旋翼机（自转旋翼机）：利用前进时的气流推动旋翼转动来获得升力，不能垂直起降。 倾转旋翼机：结合了直升机和固定翼飞机的特点，旋翼可以在垂直位置和水平位置之间转换，兼具垂直起降和高速巡航的能力。 因此，正确答案是：直升机、旋翼机和倾转旋翼机。" },
  // ==================== 气象1 ====================
  { id: 679, cat: "气象1", q: "100 米等于多少英尺？（）", opts: ["300 英尺", "305 英尺", "328 英尺"], ans: 2, exp: "100 米等于 328 英尺。这是因为 1 米等于 3.28084 英尺，所以 100 米乘以 3.28084 等 于 328.084 英尺，四舍五入后为 328 英尺。" },
  { id: 680, cat: "气象1", q: "18000 英尺高度的大气重量仅仅是海平面时的（）", opts: ["三分之一", "四分之一", "一半"], ans: 2, exp: "在 18000 英尺（大约 5486 米）的高度，大气重量大约是海平面的一半。这是因为随 着高度的增加，大气压力和密度都会下降，导致大气重量减少。大气重量与高度的关系可以 通过气压公式来描述，其中大气压力随着高度的增加而指数衰减。" },
  { id: 681, cat: "气象1", q: "60 米大约相当于多少英尺？（）", opts: ["200 英尺", "180 英尺", "220 英尺"], ans: 0, exp: "60 米大约相当于 200 英尺。换算关系是 1 米约等于 3.28084 英尺，因此 60 米乘以 3.28084 约等于 196.85 英尺，四舍五入后约为 200 英尺。" },
  { id: 682, cat: "气象1", q: "从地球表面到外层空间，大气层依次是（）", opts: ["对流层、平流层、中间层、电离层和散逸层", "对流层、平流层、电离层、中间层和散逸层", "对流层、中间层、平流层、电离层和散落层"], ans: 0, exp: "从地球表面到外层空间，大气层依次是对流层、平流层、中间层、电离层和散逸层。 对流层是大气层的最底层，其特点是空气对流运动强烈，天气现象多发生在这一层。 平流层位于对流层之上，空气以水平运动为主，包含臭氧层。 中间层是平流层之上的一层，空气逐渐变得稀薄。 电离层位于中间层之上，因受太阳辐射而部分电离。 散逸层是大气层的最外层，空气分子极少，逐渐过渡到外太空。" },
  { id: 683, cat: "气象1", q: "从什么资料上可以预先了解到航线高度的风、云、气温及颠簸、积水等情况？", opts: ["等压面预告图", "重要天气预告图", "航路天气预告图"], ans: 2, exp: "航路天气预告图主要是针对特定的航路（航线）区域进行的天气预报，其中会包括航 线高度上的风、云、气温以及颠簸、积冰等情况，它是专门为飞行员在飞行前了解航线天气 状况而提供的重要资料。" },
  { id: 684, cat: "气象1", q: "大气是一种混合物，它由（）组成", opts: ["空气和水汽凝结物", "空气和固体微粒", "空气、水汽及液体或固体杂质"], ans: 2, exp: "大气是一种由空气、水汽以及液体或固体杂质组成的混合物。这个定义涵盖了大气中 所有成分，包括气体、水的不同状态以及悬浮在空气中的各种颗粒物。" },
  { id: 685, cat: "气象1", q: "大气是由（）", opts: ["78%的氮气，21%的氧气以及 1%的其它气体组成", "75%的氮气，24%的氧气以及 1%的其它气体组成", "78%的氮气，20%的氧气以及 2%的其它气体组成"], ans: 0, exp: "大气主要由氮气、氧气以及其他气体组成，其中氮气约占 78%，氧气约占 21%，其他 气体和杂质约占 1%。这个比例是地球大气层中各主要成分的大致分布情况。" },
  { id: 686, cat: "气象1", q: "大气系统热量的主要来源是吸收太阳辐射，下列说法哪个正确？（）", opts: ["当太阳辐射通过大气层时，有 44%被大气直接吸收", "当太阳辐射通过大气层时，有 34%被大气直接吸收", "当太阳辐射通过大气层时，有 24%被大气直接吸收"], ans: 2, exp: "大气系统热量的主要来源是吸收太阳辐射。根据大气科学的基本常识，当太阳辐射通 过大气层时，大约有 24%的能量被大气层直接吸收，其余的则被地球表面吸收或反射回太空。 这部分被大气吸收的辐射对大气的温度和气候有着重要影响。" },
  { id: 687, cat: "气象1", q: "大气中某一高度的一团空气，如受到某种外力的作用后，产生向上或向下运动时，称为 稳定状态的是（）", opts: ["移动后，加速向上或向下运动", "移动后逐渐减速，并有返回原来高度的趋势", "力作用消失后，以匀速持续运动"], ans: 1, exp: "大气中某一高度的一团空气，如果受到外力作用后产生向上或向下运动，并且在外力 作用消失后，这团空气逐渐减速，并有返回原来高度的趋势，这种情况称为稳定状态。这意 味着大气层对空气的位移产生了抵抗，使得空气倾向于回到其原始位置，保持大气的稳定性。" },
  { id: 688, cat: "气象1", q: "当机翼和尾翼积冰时，下列不正确的是（）", opts: ["翼型失真（变型）", "导致摩擦阻力减少", "压差阻力都增大"], ans: 1, exp: "当机翼和尾翼积冰时，不正确地描述是导致摩擦阻力减少。实际上，积冰会导致翼型 失真（变型），增加飞机表面的粗糙度，从而增加摩擦阻力。同时，由于积冰改变了机翼的 形状，破坏了气流的平滑流动，导致压差阻力也增大。因此，积冰对飞机的气动性能有负面 影响，增加了飞行阻力，降低了升力，可能导致飞机性能下降。" },
  { id: 689, cat: "气象1", q: "当来自北方的冷气团和来自南方的暖气团，两者势均力敌，强度相当时，它们的交锋区 很少移动，这种锋面称为（）", opts: ["静止锋", "交错锋", "融合锋"], ans: 0, exp: "当来自北方的冷气团和来自南方的暖气团势均力敌，强度相当时，它们的交锋区很少 移动，这种锋面称为静止锋。静止锋意味着锋面相对稳定，不会有明显的移动，通常与持续 的云层和降水有关。" },
  { id: 690, cat: "气象1", q: "当在山谷、山脊或山区作低空飞行时，在什么时候最容易碰到乱流造成危险？", opts: ["在山的背风面顺风飞行", "在山的背风面逆风飞行", "在山的迎风面逆风飞行"], ans: 0, exp: "在山谷、山脊或山区进行低空飞行时，最容易碰到乱流造成危险的情况是在山的背风 面顺风飞行。这是因为在山的背风面，气流受到地形的影响，容易产生下降气流和乱流，这 些乱流可能会对飞行器的稳定性和操控性造成影响，增加飞行风险。因此，在山区飞行时，应尽量避免在山的背风面顺风飞行，以确保飞行安全。" },
  { id: 691, cat: "气象1", q: "地表和潮湿物体表面的水分蒸发进入大气就形成了大气中的水汽，大气中的水汽含量平 均约占整个大气体积的 0~5%左右，并随着高度的增加而逐渐（）", opts: ["增加", "不变", "减少"], ans: 2, exp: "大气中的水汽主要来源于地表和潮湿物体表面的水分蒸发。水汽在大气中的含量相对 较少，平均约占整个大气体积的 0～5%，并且这个比例会随着海拔高度的增加而逐渐减少。 这是因为随着高度的升高，气温降低，空气的容纳水汽的能力下降，导致水汽含量减少。" },
  { id: 692, cat: "气象1", q: "地面的地形和大的建筑物会（）", opts: ["汇聚风的流向", "产生会快速改变方向和速度的阵风", "产生稳定方向和速度的阵风"], ans: 1, exp: "地面的地形和大型建筑物会对风的流动产生显著影响，特别是在城市环境中。这些障 碍物会改变风的流向，造成风速和方向的快速变化，形成阵风。阵风通常是局部的、突发的，并且方向和速度可能会迅速改变，这在航空飞行中可能导致不稳定因素，增加飞行风险。" },
  { id: 693, cat: "气象1", q: "对流层（）的空气运动受地形扰动和地表摩擦作用最大，气流混乱。", opts: ["上层", "中层", "下层"], ans: 2, exp: "对流层中，下层的空气运动受地形扰动和地表摩擦作用最大，导致气流混乱。这是因 为靠近地表的气流直接受到地面的摩擦影响，同时地形的变化也会对气流产生显著的影响，如山地、城市建筑等都会使气流产生湍流和涡流。" },
  { id: 694, cat: "气象1", q: "对流层的高度，在地球中纬度地区约为（）", opts: ["8 公里", "16 公里", "11 公里"], ans: 2, exp: "对流层是地球大气层中最低的一层，其高度在地球中纬度地区大约是 11 公里。对流 层是天气变化最复杂的一层，包含了我们日常经历的大部分天气现象，如云、雨、雪、雷暴 等。对流层的高度会随着纬度、季节和地理位置的不同而有所变化，但中纬度地区的平均高 度大约是 11 公里。" },
  { id: 695, cat: "气象1", q: "对流层的主要特征，哪个正确（）", opts: ["气温随高度不变", "气温、湿度的水平分布均匀", "空气具有强烈的垂直混合"], ans: 2, exp: "对流层是地球大气层中最低的一层，其主要特征是空气具有强烈的垂直混合。这是因 为对流层中的气温随高度增加而降低，这种温度梯度导致空气上升和下沉，形成对流运动。 同时，对流层中的湿度也随高度变化，通常随着高度的增加而降低。因此，对流层中的气温 和湿度的水平分布并不均匀，而是存在较大的差异。" },
  { id: 696, cat: "气象1", q: "对流层因为空气有强烈的对流运动而得名，它的底界为地面，上界高度随纬度、季节、天气等因素而变化，同一地区对流层上界高度（）", opts: ["冬季大于夏季", "夏季大于冬季", "冬季与夏季相同"], ans: 1, exp: "对流层是地球大气层中最接近地面的一层，其上界高度随纬度、季节、天气等因素而 变化。根据搜索结果，对流层的高度因纬度而不同，在低纬度地区平均高度为 17～18 公里，在中纬度地区平均为 10～12 公里，极地平均为 8～9 公里，并且夏季高于冬季。" },
  { id: 697, cat: "气象1", q: "对流层中，按气流和天气现象分布的特点，可分为下、中、上三个层次，代表对流层中 层气流的基本趋势是（）", opts: ["气流混乱", "气流相对平稳", "水汽含量很少"], ans: 1, exp: "对流层中层，也称为对流层中部，其气流相对平稳，天气现象不如下层那么剧烈和多 变。这一层的气流通常较为稳定，天气现象相对温和，不像低层那样经常出现雷暴、大风等 强对流天气。因此，代表对流层中层气流的基本趋势是气流相对平稳。" },
  { id: 698, cat: "气象1", q: "对流层中的平均气温垂直递减率为（）", opts: ["0.65°C/100m", "6.5°C/100m", "0.5°C/100m"], ans: 0, exp: "对流层中的平均气温垂直递减率是指气温随高度增加而降低的幅度。在对流层内，气 温直减率平均为 0.65°C/100 米，即平均每上升 100 米，气温下降约 0.65°C。这个递减率 并非固定不变，它随着离地面高度、季节、天气等条件而不同。因此，对流层中的气温随高 度增加而降低，这是由于对流层大气的主要热源是地面长波辐射，离地面越高，受热越少，气温就越低。" },
  { id: 699, cat: "气象1", q: "对于空气密度，如下说法正确的是（）", opts: ["空气密度正比于压力和绝对温度", "空气密度正比于压力，反比于绝对温度", "空气密度反比于压力，正比于绝对温度"], ans: 1, exp: "空气密度与压力和绝对温度的关系由理想气体状态方程描述，该方程为 PV=nRT，其中 P 代 表压力，V 代表体积，n 代表摩尔数，R 是理想气体常数，T 代表绝对温度。从这个方程可以 看出，空气密度（p=m/V，其中 m 是质量）与压力成正比，与绝对温度成反比。因此，当压 力增加或温度降低时，空气密度会增加；反之，当压力减少或温度增加时，空气密度会减少。" },
  { id: 700, cat: "气象1", q: "发生在低层的风切变严重影响航空器的起降，将发生在这一气层中的风切变称为低空风 切变，低空风切变距地面一般约（）", opts: ["300 米", "600 米", "800 米"], ans: 1, exp: "低空风切变是指发生在低层且对航空器起降有严重影响的风切变现象。在众多的研究 和航空规定中，普遍认定低空风切变距地面一般约为 600 米以下。所以这道题考查的就是对 低空风切变基本定义中高度这一关键要素的掌握程度。" },
  { id: 701, cat: "气象1", q: "飞机积冰的产生，主要由于云中存在（）", opts: ["大小不等的水滴", "雪花和冰晶", "过冷水滴"], ans: 2, exp: "飞机积冰的产生主要是由于云中存在过冷水滴。过冷水滴是指温度低于 0°C 而仍未 冻结的云滴和雨滴。当飞机在含有过冷水滴的云中飞行时，如果机体表面温度低于 0°C，过冷水滴就会在机体表面某些部位冻结，并聚积成冰层。因此，飞机在云中飞行时，尤其是 当云中含有大量过冷水滴时，极易发生积冰现象。" },
  { id: 702, cat: "气象1", q: "飞机结冰是指飞机机体表面某些部位聚集冰层的现象，飞机积冰主要分为（）三大种", opts: ["冰、雾凇、霜", "明冰、毛冰、白冰", "坚冰、松冰、霜冰"], ans: 0, exp: "飞机结冰是指飞机机体表面某些部位聚集冰层的现象，主要由云中过冷水滴或降水中 的过冷雨碰到飞机机体后结冰形成，也可以由水汽直接在机体表面凝华而成。根据航空气象 学，飞机积冰主要分为四种：明冰、毛冰、雾凇、霜。这四种类型覆盖了飞机结冰的大部分 情况，因此选项“冰、雾凇、霜”是正确的。" },
  { id: 703, cat: "气象1", q: "飞机在比标准大气冷的空气中飞行时，气压高度表所示高度比实际飞行高度（）", opts: ["低", "高", "相同"], ans: 1, exp: "气压高度表的工作原理是基于大气压力随高度变化的规律来测量高度的。在标准大气 条件下，气压高度表的读数与实际高度是一致的。然而，当空气温度低于标准大气温度时，空气密度增大，气压随高度的变化率也会增大。因此，气压高度表在比标准大气冷的空气中 会显示一个比实际飞行高度更高的读数。" },
  { id: 704, cat: "气象1", q: "飞机在雨层云上飞行，飞行员发现浓密的云层有向上突起的云塔，顶部伸展到 9000 米 以上的高空，被强劲的空中风吹的旬马鬃似地倒向一边，他可以断定，在层状云中一定有（）", opts: ["积雨云", "高积云", "伪卷云"], ans: 0, exp: "飞机在雨层云上飞行时，如果飞行员观察到浓密的云层中有向上突起的云塔，且顶部 伸展到 9000 米以上的高空，被强劲的空中风吹得像马鬃一样倒向一边，这种现象通常表明 在层状云中存在积雨云。积雨云是一种强烈的对流云，能够产生强烈的上升气流和下降气流，以及可能伴随的降水和雷电活动。" },
  { id: 705, cat: "气象1", q: "飞机在着陆时突然遇到逆风切变，会出现下述何种现象？（）", opts: ["飞机空速突然增大，尹力增加，飞机上仰并上升到下滑线之上", "飞机高度下降，空速减小，未到正常着陆点即提前着陆", "飞机空速突然减小，升力减小，飞机将掉至正常下滑线以下"], ans: 0, exp: "飞机在着陆过程中突然遇到逆风切变时，逆风会增加飞机的地速，导致飞机的空速（相 对于空气的速度）突然增大。由于升力与空速的平方成正比，空速的增加会导致升力增加，飞机因此会上仰并上升到下滑线之上。这种现象可能会使飞机错过正常的着陆点，增加着陆 距离，对飞行安全构成威胁。" },
  { id: 706, cat: "气象1", q: "飞机在着陆时遇到顺风切变，会出现下述何种现象？（）", opts: ["飞机空速突然增大，升力增加，飞机抬升", "飞机高度下降，空速增大，超过正常着陆点着陆", "飞机空速突然减小，升力减小，飞机将掉至正常下滑线以下"], ans: 2, exp: "飞机在着陆时遇到顺风切变，会出现飞机空速突然减小，升力也随之减小的现象。这 是因为顺风切变使飞机相对于空气的速度迅速降低，导致升力下降，飞机无法保持原有的飞 行高度而下沉。在这种情况下，飞行员需要及时采取措施，如增加油门以增大空速，同时带 杆减小下降率，以尝试回到正常的下滑线上。" },
  { id: 707, cat: "气象1", q: "飞行高度不同，飞机积冰频率也不同，以下正确的是（）", opts: ["冬季在 3000 米以下各高度上飞行时，积冰几乎占 56%", "冬季在 3000 米以上各高度上飞行时，积冰几乎占 56%", "在 6000 米以上高度上飞行时，积冰占 56%"], ans: 0, exp: "飞行高度不同，飞机积冰频率也不同。在冬季，3000 米以下（含 3000 米）各高度上 飞行时，积冰几乎占 56%。因此，正确答案是：冬季在 3000 米以下各高度上飞行时，积冰 几乎占 56%。" },
  { id: 708, cat: "气象1", q: "风切变气流常从高空极速下冲，像向下倾泻的巨型水龙头，当飞机进入该区域时（）", opts: ["先遇强逆风，后遇猛烈的下沉气流，随后又是强顺风", "先遇强顺风，后遇猛烈的上升气流，随后又是强逆风", "先遇强逆风，后遇猛烈的上升气流，随后又是强顺风"], ans: 0, exp: "风切变气流从高空急速下冲时，飞机进入该区域首先会遇到强逆风，这是因为下冲气 流在接近地面时会向四周扩散，使得飞机先感受到逆风。接着遇到猛烈的下沉气流，这是风 切变的主要特征之一。随后当飞机穿过下沉气流区域后，又会遇到强顺风。这种风的变化对 飞机的飞行安全影响极大。" },
  { id: 709, cat: "气象1", q: "根据地面天气图上分析的等压线，我们能观察出（）", opts: ["降水区域", "气压梯度", "槽线位置"], ans: 1, exp: "等压线密气压梯度大，风力强劲天气变化大。在地面天气图上分析的等压线，相邻等 压线之间的间隔反映了气压梯度的大小。等压线越密集，气压梯度越大；等压线越稀疏，气 压梯度越小。" },
  { id: 710, cat: "气象1", q: "关于飞机积冰，下列正确的是（）", opts: ["飞机积冰一般发生在-1~-15°的温度范围内", "在-2~-10°温度范围内遭遇积冰的次数最多", "强烈的积冰主要发生在-4~-8°的温度范围内"], ans: 1, exp: "飞机积冰的发生与温度范围有关。在-2~-10°C 温度范围内，飞机遭遇积冰的次数最 多。这是因为此区间过冷水滴含量高且不易冻结，易附着机体。 其他选项分析如下： （-1~-15°C）：范围过宽，包含非高发区； （-4~-8°C）：虽是强积冰核心区，但题干未限定“强烈积冰”表述不全面。" },
  { id: 711, cat: "气象1", q: "关于风切变出现的地方，下述正确的是？（）", opts: ["仅在雷暴中出现", "在气压和温度急剧下降的地方出现", "在大气中任何高度上存在风向或风速变化的地方"], ans: 2, exp: "风切变是指风速矢量或其分量沿垂直方向或某一水平方向的变化。它反映了所研究的 两点之间风速和风向的变化。风切变可以发生在大气中的任何高度上，只要存在风向或风速 的变化。" },
  { id: 712, cat: "气象1", q: "关于逆温层，下列正确的是？（）", opts: ["逆温层中空气密度小，有利于大型飞机飞行", "逆温层是稳定气层，其下能见度通常较差", "逆温层中温度随高度升高而降低"], ans: 1, exp: "1.逆温层中空气稳定但密度并非小到有利于大型飞机飞行，因为空气稳定并不意味着 空气密度适合大型飞机的最佳飞行条件（排除该选项）。 2.逆温层中的空气比较稳定，不利于空气的上下对流，使得污染物等不易扩散，所以其下能 见度通常较差（该选项正确）。 3.逆温层是一种特殊的气象现象，在逆温层中，通常温度随高度的增加而升高，而不是降低 （排除该选项）。" },
  { id: 713, cat: "气象1", q: "国际上对下列哪些能见度定义是正确的？（）", opts: ["烟雾的能见度定义为不足 1km", "薄雾的能见度为 1km~3km", "霾的能见度为 3km~5km"], ans: 0, exp: "根据国际标准，烟雾的能见度定义为不足 1km，薄雾的能见度为 1km~2km，霾的能见 度为 2km～5km。这些定义反映了不同天气现象对能见度的影响程度。" },
  { id: 714, cat: "气象1", q: "航路天气预报通常在起飞前几小时，由飞航站气象台向机组提供？（）", opts: ["1 小时", "2 小时", "3 小时"], ans: 0, exp: "航路天气预报是指在飞机起飞前，由飞行站气象台向机组提供的关于飞行航路上的天 气情况的预报。这项服务的目的是为了确保飞行安全，让飞行员能够提前了解并准备应对可 能遇到的各种天气情况。通常，这种天气预报会在起飞前 1 小时提供，以便飞行员有足够的 时间来做出相应的飞行决策。" },
  { id: 715, cat: "气象1", q: "和地面建筑物有关的流强度依赖于（），这会影响任何飞机的起飞和着陆性能，也会引 发非常严重的危险。", opts: ["障碍物的多少和风的基本速度", "障碍物的大小和风的基本方向", "障碍物的大小和风的基本速度"], ans: 2, exp: "和地面建筑物有关的湍流强度主要受到两个因素的影响。一方面，障碍物的大小很关 键，较大的障碍物会对空气流动产生更大的干扰，从而增强湍流强度。另一方面，风的基本 速度也起着重要作用，风速度越大，与障碍物相互作用后产生的湍流就可能越强。这种湍流 会对飞机的起飞和着陆性能产生影响，甚至带来非常严重的危险。" },
  { id: 716, cat: "气象1", q: "和地面建筑物有关的湍流强度依赖于障碍物的大小和风的基本速度，在山地区域时这种 情况甚至更加明显，风越过山脊时（）", opts: ["风沿着迎风侧平稳地向上流动", "风沿着迎风侧湍流逐渐增加", "风沿着背风侧平稳地向下流动"], ans: 0, exp: "风越过山脊时，风沿着迎风侧平稳地向上流动。 这是因为当风流遇到山脊时，气流被迫上升，形成所谓的“翻山风”现象。在山的迎风侧，风速通常会增加，而在背风侧，风速会迅速减小，甚至可能出现气流分离和涡流，导致湍流 的产生。这种现象在复杂地形区域尤为明显，对风力发电机组的运行和风电场的设计有着重 要影响。" },
  { id: 717, cat: "气象1", q: "机场上吹东风时，飞机起飞着陆的最好方向是（）", opts: ["由西向东", "由东向西", "由北向南"], ans: 0, exp: "东风吹，西向东，逆风起飞最稳当。当机场上吹东风时，飞机起飞着陆的最好方向应 是由西向东。这是因为飞机在起飞和着陆时逆风为最好，因为逆风能缩短滑跑距离，增加飞 机升力，利于飞机快速升空。顺风起飞着陆则很不安全，因为顺风会增加飞机起飞和着陆的 滑跑距离，影响飞机的起飞性能和着陆安全。因此，当吹东风时，飞机应选择与风向相反的 方向进行起飞和着陆，即由西向东，以利用逆风的优势。" },
  { id: 718, cat: "气象1", q: "积冰的形状主要取决于冰的种类，飞行速度和气流绕过飞行器的不同部位的情况，积冰 的形状一般分为（）", opts: ["槽状冰、楔形冰和混合冰", "凸状冰、凹状冰和混合冰", "圆形冰、方形冰和混合冰"], ans: 0, exp: "飞机在飞行过程中，尤其是在云层中飞行时，可能会遇到积冰现象。积冰的形状主要 取决于冰的种类、飞行速度以及气流绕过飞行器不同部位的情况。根据空勤人员获得的喷气 式飞机积冰统计数据，积冰的形状一般分为槽状冰、楔形冰和混合冰。其中，槽状冰约占 30%、楔形冰约占 15%，而混合冰约占 55%左右。" },
  { id: 719, cat: "气象1", q: "积冰强度可分为（）", opts: ["霜、雾凇和冰", "轻度、中度和重度", "微弱、弱、中度和强"], ans: 1, exp: "积冰强度是指飞机在云中飞行时，由于过冷水滴或冰晶与飞机表面接触而形成的冰层 的严重程度。根据国际民航组织（ICAO）的标准，积冰强度通常分为三个等级：轻度（Light）、中度（Moderate）和重度（Severe）。这些等级反映了积冰对飞机性能的影响程度，以及飞 行员需要采取的应对措施。轻度积冰可能不会立即对飞行安全构成威胁，但中度和重度积冰 则需要飞行员立即采取行动，如改变飞行高度或航向，以避免飞机性能严重下降或结构损伤。" },
  { id: 720, cat: "气象1", q: "假设其他条件不变，空气湿度大，（）", opts: ["空气密度大，起飞滑跑距离长", "空气密度小，起飞滑跑距离长", "空气密度大，起飞滑跑距离短"], ans: 1, exp: "空气湿度大意味着空气中的水汽含量较高。在相同的温度下，湿度大的空气密度相对 较小，因为水汽分子取代了一部分原先由更重的干空气分子占据的空间。空气密度小会导致 飞机机翼产生的升力下降，因为升力与空气密度成正比。因此，飞机需要更长的滑跑距离来 获得足够的升力，从而离地起飞。" },
  { id: 721, cat: "气象1", q: "空气在做水平运动时，是什么力阻止了空气直接从高压区流向低压区？（）", opts: ["惯性离心力", "地转偏向力", "摩擦力"], ans: 1, exp: "空气在作水平运动时，阻止了空气直接从高压区流向低压区的力是地转偏向力。地转 偏向力是由于地球自转产生的一种假想力，它影响着地球上水平运动物体的运动方向。在北 半球，地转偏向力使气流向右偏转；在南半球则向左偏转。这种力使得风不沿直线直接从高 压流向低压，而是形成了旋转的气流模式，如气旋和反气旋。" },
  { id: 722, cat: "气象1", q: "空气中容纳水汽的数量随气温变化，气温越高，则（）", opts: ["可以容纳的水汽就越少", "可以容纳的水汽就越多", "当空气不能再容纳更多的水汽时，温度就会变化"], ans: 1, exp: "空气中容纳水汽的数量与气温有直接关系。气温越高，空气的湿度承载能力越大，也 就是说，空气可以容纳更多的水汽。这是因为温度的升高增加了空气分子的运动速度，从而 使得更多的水分子能够在空气中保持气态，而不是凝结成液态。当空气达到其最大湿度承载 能力时，再增加水汽就会发生凝结，形成云、雾或降水。" },
  { id: 723, cat: "气象1", q: "快速移动的冷锋受实际锋面后远处的强烈压力系统推动，在快速移动的冷锋之后，（）", opts: ["可能出现乌云密布的天空和下雨", "天空通常很快放晴", "阵风减缓和温度升高"], ans: 1, exp: "快速移动的冷锋受实际锋面后远处的强烈压力系统推动。在快速移动的冷锋之后，天 空通常很快放晴，冷锋留下了狂暴的阵风和更冷的温度。这是因为冷锋过境时，会伴有大风、降温、降水等天气现象，但锋面过后，由于冷气团替代了原来暖气团的位置，气温湿度骤降，气压升高，天气转晴。" },
  { id: 724, cat: "气象1", q: "雷暴到达成熟阶段以后，随着积雨云中迅速下沉的冷空气到达地面后，风向突转，风力 迅速增大，阵风风速常在（）", opts: ["10m/s", "20m/s", "30m/s"], ans: 1, exp: "雷暴成熟阶段以后，随着积雨云中迅速下沉的冷空气到达地面，风向会突然转变，风 力迅速增大。这种强烈的下沉气流在地面形成的雷暴冷堆，并向四周流出，具有较大的水平 动量，在低空造成风向的突变，风速急增的强风，其前缘为飑锋。阵风风速常在 20m/s 左右，有时强烈的可以达到 25m/s 或以上，这种现象常常是雷雨即将来临的先兆。" },
  { id: 725, cat: "气象1", q: "雷暴对飞机产生很大危害，下列危害不确切的是（）", opts: ["雷击和冰雹袭击", "风切变和湍流", "数据链中断"], ans: 2, exp: "雷暴对飞机飞行产生的危害包括雷击、冰雹袭击、风切变和湍流等。这些天气现象会 对飞机的结构和飞行性能造成严重影响。雷击可能导致飞机结构损坏和电子设备故障；冰雹 袭击可能损坏飞机的雷达罩、机翼等部件；风切变和湍流会导致飞机颠簸，增加飞行员操纵 难度，甚至导致机失控。数据链中断并不是由雷暴直接引起的，而是可能由于雷暴产生的强 烈电磁干扰导致的通信问题。" },
  { id: 726, cat: "气象1", q: "雷暴是由强烈的积雨云产生的，形成强烈的积雨云需要三个条件（）", opts: ["深厚而明显的不稳定气层、剧烈的温差、足够的冲击力", "深厚而明显的不稳定气层、充沛的水气、足够的冲击力", "强大的风力、充沛的水气、足够的冲击力"], ans: 1, exp: "雷暴是由强烈的积雨云产生的，而形成强烈的积雨云需要三个条件：深厚而明显的不 稳定气层、充沛的水气、足够的冲击力。不稳定气层提供了上升气流，使得云层能够发展和 增长；充沛的水气是形成云和降水的基础；足够的冲击力，如强烈的上升气流，可以推动云 层迅速发展，形成雷暴云。" },
  { id: 727, cat: "气象1", q: "能够产生有一定影响的低空风切变的天气背景主要有三类（）", opts: ["大风天气、强降雨天气、寒冷天气", "强对流天气、锋面天气、辐射逆温型的低空急流天气", "山地气流、昼夜交替天气、春夏之交天气"], ans: 1, exp: "能够产生有一定影响的低空风切变的天气背景主要有三类：强对流天气、锋面天气以 及辐射逆温型的低空急流天气。" },
  { id: 728, cat: "气象1", q: "暖锋和冷锋在特性上是非常不同的，（）", opts: ["冷锋以 10~25 英里每小时速度移动", "暖锋以 20~35 英里每小时速度移动", "暖锋产生差的能见度和下雨，冷锋产生突发的阵风，紊流"], ans: 2, exp: "暖锋冷锋大不同，速度快慢不准确，暖锋差能见度和雨，冷锋突发阵风与紊流。暖锋 和冷锋是两种不同的天气系统，它们在特性上有很大的差异。暖锋通常移动速度较慢，能见 度较差，并常伴有持续的降雨。而冷锋则以较快的速度移动，通常带来突发的阵风和紊流，天气变化较为剧烈。" },
  { id: 729, cat: "气象1", q: "暖锋是指（）", opts: ["锋面在移动过程中，暖空气推动锋面向冷气团一侧移动的锋", "一侧气团温度明显高于另一侧气团温度的锋", "温度较高与温度较低的两个气团交汇时，温度高的一侧"], ans: 0, exp: "暖锋是指锋面在移动过程中，暖空气推动锋面向冷气团一侧移动的锋。在暖锋系统中，暖空气质量较轻，位于锋面的上方，推动锋面向冷气团一侧移动。这种锋通常与连续性降水 和逐渐变化的天气条件相关，与冷锋相比，暖锋的移动速度较慢，且不会产生剧烈的天气变 化。" },
  { id: 730, cat: "气象1", q: "平均而言，在对流层中每上升 100 米，大气温度的变化是（）", opts: ["下降 0.65°C", "下降 1°C", "下降 0.75°C"], ans: 0, exp: "在对流层中，随着高度的增加，大气温度通常会下降。这种现象称为温度递减率。平 均而言，每上升 100 米，大气温度下降约 0.65°C。这个数值是根据大气的平均条件得出的，实际的温度变化可能会因地理位置、季节和天气条件等因素而有所不同。" },
  { id: 731, cat: "气象1", q: "平流层对航空活动有利的方面是（）", opts: ["气流平稳、无恶劣天气、发动机推力增大", "气温低、飞机载重量增加、飞机真空速增大", "气流平稳、能见度好、空气阻力小"], ans: 2, exp: "平流层对航空活动有利的方面主要包括气流平稳、能见度好、空气阻力小。平流层的 气流通常比较稳定，没有对流层中常见的湍流和恶劣天气现象，这有助于飞机的平稳飞行。 此外，平流层的空气阻力相对较小，有助于提高飞机的燃油效率。" },
  { id: 732, cat: "气象1", q: "平流层范围从对流层顶到大约 55km 的高度上，空气热量的主要来源是臭氧吸收太阳紫 外辐射，因此（）", opts: ["平流层中气温随高度增高而升高", "平流层中气温不随高度变化而变化", "平流层中不含有水汽"], ans: 0, exp: "平流层位于对流层之上，大约从对流层顶延伸到 55 公里的高度。在平流层中，空气 热量的主要来源是臭氧层吸收太阳紫外辐射，这导致平流层中的温度随高度的增加而上升。 这种现象与对流层不同，在对流层中，随着高度的增加，气温通常会下降。因此，平流层中 气温随高度增高而升高。" },
  { id: 733, cat: "气象1", q: "平流层飞行，按照飞行高度区分为（）", opts: ["12000 米（不含）以上", "9000 米（含）以上", "12000 米（含）以上"], ans: 0, exp: "根据《无人机驾驶员-航空知识手册》飞行高度分类如下： 超低空无人机：任务高度一般在 0~100 米之间。 低空无人机：任务高度一般在 100 米~1000 米之间。 中空无人机：任务高度一般在 1000 米（含）~6000 米之间。 高空无人机：任务高度一般在 6000 米（含）~12000 米（含）（不含）之间。 超高空无人机：任务高度一般大于 12000 米。 平流层飞行：高度 12000 米（不含）以上。" },
  { id: 734, cat: "气象1", q: "气团的性质是（）", opts: ["水平范围大、垂直范围大、水平温度梯度小", "水平范围小、垂直范围大、水平温度梯度小", "水平范围大、垂直范围小、水平温度梯度小"], ans: 0, exp: "气团是指在水平方向上物理性质比较均匀的大团空气。气团通常水平范围很大，可以 覆盖数千千米甚至更大的区域；垂直范围也比较大，可延伸数千米；由于其内部物理性质比 较均匀，所以水平温度梯度很小，即温度在水平方向上变化不大。" },
  { id: 735, cat: "气象1", q: "气温对飞机最大平飞速度的影响为（）", opts: ["气温低时，空气密度大，飞机发动机的推力增大，最大平飞速度增加", "气温低时，空气密度大，空气的阻力增加，最大平飞速度减小", "气温高时，空气密度小，空气的阻力增减小，最大平飞速度增加"], ans: 0, exp: "气温对飞机最大平飞速度的影响主要体现在空气密度上。气温低时，空气密度相对较 大，这意味着飞机发动机在吸入相同体积的空气时，可以获得更多的氧气，从而提高发动机 的推力。同时，较大的空气密度也意味着飞机在飞行时需要克服的空气阻力更大，但由于发 动机推力的增加更为显著，因此最大平飞速度会增加。" },
  { id: 736, cat: "气象1", q: "气温高低，如何影响飞机滑跑距离？（）", opts: ["气温高时，空气密度小，飞机增速慢，飞机的离地速度增大，起飞滑跑距离要长", "气温低时，空气密度小，飞机增速快，飞机升力减小，起飞滑跑距离要长", "气温高时，空气密度大，飞机增速快，飞机升力增大，起飞滑跑距离要短"], ans: 0, exp: "当气温高时，空气会膨胀，密度变小。在这种情况下，飞机发动机的进气量减少，导 致飞机增速慢。同时，空气密度小使得飞机需要更高的速度（离地速度）才能产生足够的升 力起飞，所以起飞滑跑距离要长。" },
  { id: 737, cat: "气象1", q: "气象学中，能见度用气象光学视程表示，气象光学视程是指（）", opts: ["白炽灯发出色温为 3000k 的平行光束的光通量，在大气中削弱至初始值的 10%所通过的 路径长度", "白炽灯发出色温为 2700k 的平行光束的光通量，在大气中削弱至初始值的 5%所通过的路 径长度", "白炽灯发出色温 2500k 的平行光束的光通量，在大气中削弱至初始值的 5%所通过的路径 长度"], ans: 1, exp: "气象光学视程（MOR）是描述大气浑浊程度或透明程度的物理量，它定义为白炽灯发 出色温为 2700K 的平行光束的光通量，在大气中削弱至初始值的 5%所通过的路径长度。因 此，当白炽灯发出的光束在大气中的光通量减少到初始值的 5%时，该路径长度即为气象光 学视程。" },
  { id: 738, cat: "气象1", q: "气压一定时，气温露点的高低可以表示（）", opts: ["空气的饱和程度", "空气中的水汽含量", "空气中的凝结核的含量"], ans: 1, exp: "气温露点的高低可以表示空气中的水汽含量。在气压一定时，露点的高低只与空气中 的水汽含量有关，水汽含量愈多，露点愈高。因此，当气温露点较高时，表示空气中的水汽 含量较多；反之，露点较低时，表示空气中的水汽含量较少。" },
  { id: 739, cat: "气象1", q: "如果空气的实际温度低于标准温度，气压式高度表指示 2000 米，则实际高度（）", opts: ["高于 2000 米", "低于 2000 米", "等于 2000 米"], ans: 1, exp: "气压式高度表是根据气压变化来测量高度的。在标准大气条件下，高度与气压之间存 在一定的关系。当空气的实际温度低于标准温度时，空气密度会增加，导致气压随高度下降 得更快。因此，当气压式高度表指示 2000 米时，实际高度会低于 2000 米。" },
  { id: 740, cat: "气象1", q: "使用多轴飞行器在低温及潮湿环境中作业时的注意事项，不包括（）", opts: ["曝光偏差", "起飞前动力电池的保温", "飞行器与摄像器材防止冰冻"], ans: 0, exp: "低温潮湿，保温防冻，无关曝光。曝光偏差主要与光照条件、相机设置等有关，与低 温及潮湿环境关系不大。在低温及潮湿环境中作业时，起飞前对动力电池进行保温是很重要 的，因为低温会影响电池性能；同时，飞行器与摄像器材可能会出现冰冻现象，这会影响设 备的正常运行和使用寿命，需要采取防止冰冻的措施。" },
  { id: 741, cat: "气象1", q: "温度对飞机的升限有影响，关于升限，下列何种叙述是正确的？（）", opts: ["气温升高，大型飞机的升限要升高", "温度变化对喷气式飞机的升限没有影响", "气温升高，所有飞机的升限都要减小"], ans: 2, exp: "随着气温升高，空气密度会减小。飞机的升限主要取决于空气密度等因素。当空气密 度减小时，飞机需要更高的速度才能产生足够的升力来维持在较高高度，所以气温升高，所 有飞机的升限都要减小。" },
  { id: 742, cat: "气象1", q: "无人机左侧风中起飞，侧风使飞机机头向（）偏转的趋势", opts: ["左", "右", "视风速的大小不同可能左可能右"], ans: 0, exp: "无人机在左侧风中起飞时，侧风会对飞机产生一个向风方向的侧向力。由于飞机的左 侧受到风的直接吹袭，这会导致飞机的左侧升力增加，从而产生一个使飞机机头向左侧偏转 的趋势。因此，侧风使飞机机头向左侧偏转的趋势。" },
  { id: 743, cat: "气象1", q: "雾通常发生在接近地面的空气温度冷却到空气露点时，是从地表开始（）", opts: ["50 英尺内的云", "80 英尺内的云", "100 英尺内的云"], ans: 0, exp: "雾通常发生在接近地面的空气温度冷却到空气的露点时，是从地表开始形成的一种天 气现象。当空气冷却到露点温度或以下时，空气中的水汽就会凝结成微小的水滴，形成雾。 这些水滴悬浮在接近地面的空气中，导致能见度降低。" },
  { id: 744, cat: "气象1", q: "下列哪种属于动力对流冲击力？（）", opts: ["山坡迎风面对空气的抬升", "气流辐合辐散时造成的空气水平运动", "气温变化造成的空气抬升或下降"], ans: 0, exp: "动力对流冲击力通常是由地形引起的空气运动，例如山坡迎风面对空气的抬升。这种 抬升是由于地形阻挡气流，迫使空气上升，从而形成对流。 山坡迎风面的空气被迫上升，形成动力对流，这与气温变化引起的空气抬升或下降不同，后 者属于热力对流。" },
  { id: 745, cat: "气象1", q: "下列说法正确的是（）", opts: ["因为空气总是寻找低压区域，所以气流会从高压区域向低压的区域流动", "因为空气总是寻找高压区域，所以气流会从低压区域向高压的区域流动", "是风产生了压力，所以风的尽头压力高"], ans: 0, exp: "气压差推动空气流，高压向低压走。空气总是从高压区域向低压区域流动，这就像水 总是从高处流向低处一样。因为在高压区域，空气分子较为密集，会向空气分子相对稀疏的 低压区域扩散，从而形成气流。" },
  { id: 746, cat: "气象1", q: "下面大气层的主要依据哪个是正确的？（）", opts: ["气层气压的垂直分布特点", "气层气温的垂直分布特点", "气层中风的垂直变化特点"], ans: 1, exp: "大气分层的主要依据是气层气温的垂直分布特点。地球大气层按照气温随高度变化的 特征被划分为几个主要层次，包括对流层、平流层、中间层、热层和外层空间。每个层次的 气温变化特征不同，这是大气分层的主要依据。" },
  { id: 747, cat: "气象1", q: "下面关于气团的叙述哪个正确？（）", opts: ["我国地域广大，能形成各种气团", "气团离开源地，其性质将会发生变化", "气团只形成于极地和大洋地区"], ans: 1, exp: "气团离开源地后，当它移动到与源地性质不同的地区时，会受到新下垫面的影响，导 致其属性发生相应的变化。这种在移动过程中物理属性和天气特征逐渐发生变化的过程称为 气团的变性。气团的变性速度取决于多种因素，包括气团与新下垫面之间的温度差异、湿度 差异以及地形等。" },
  { id: 748, cat: "气象1", q: "下述何种天气现象是稳定大气的特征？（）", opts: ["能见度极好", "能见度较差", "有阵性降水"], ans: 0, exp: "稳定大气的特征通常包括能见度较好、风力较弱、云量较少等。在稳定大气条件下，空气不易产生强烈的对流运动，因此天气现象相对平静，能见度较好。相反，能见度较差和 阵性降水通常是不稳定大气的特征，因为它们往往与强烈的天气系统和对流活动相关。" },
  { id: 749, cat: "气象1", q: "相对湿度，是指（）", opts: ["空气中水汽含量与饱和水汽含量的百分比", "空气中水汽压与饱和水汽压的百分比", "空气中水分占空气总量的百分比"], ans: 1, exp: "相对湿度是指空气中水汽压与同温度下饱和水汽压的百分比。它反映了空气中水汽的 饱和程度，是气象学中描述大气湿度的一个重要参数。当相对湿度为 100%时，表示空气已 经达到饱和状态，此时空气不能再容纳更多的水汽，容易形成凝结水（如露、雾或云）。" },
  { id: 750, cat: "气象1", q: "形成海陆风的对流性环流的原因是因为（）", opts: ["从水面吹向陆地的空气较暖，密度小，导致空气上升", "陆地吸收和散发热量比水面快", "从水面吹向陆地的空气冷，密度大，使空气上升"], ans: 1, exp: "形成海陆风的对流性环流的原因是陆地吸收和散发热量比水面快。在白天，陆地受太 阳辐射加热的速度比海洋快，导致陆地上的空气温度升高，密度降低，从而上升形成低压区。 海洋上的空气相对较冷，密度大，因此会从海洋吹向陆地，形成海风。到了晚上，情况相反，陆地冷却得快，海洋上的空气较暖，导致陆地上的空气下沉，形成陆风。" },
  { id: 751, cat: "气象1", q: "形成雷暴的基本条件是（）", opts: ["充足的水汽和上升运动", "充足的水汽、不稳定的大气和上升运动", "浓积云、充足的水汽和锋区"], ans: 1, exp: "形成雷暴的基本条件包括三个要素：充足的水汽、不稳定的大气和上升运动。这三个 条件共同作用，为雷暴的发生提供了必要的环境和动力。 不稳定的大气层结提供了雷暴发展的能量基础，充沛的水汽为雷暴提供了物质基础，而足够 的抬升触发机制则是雷暴形成的直接触发因素。 因此，正确的叙述是雷暴的形成需要充足的水汽、不稳定的大气和上升运动。" },
  { id: 752, cat: "气象1", q: "严重危害飞行安全的冰雹，通常与下列何种云有联系？（）", opts: ["普通雷暴云", "强烈雷暴云", "堡状高积云"], ans: 1, exp: "严重危害飞行安全的冰雹，通常与强烈雷暴云有联系。强烈雷暴云，也称为超级单体 风暴，具有强烈的上升气流和复杂的云结构，能够产生大尺寸的冰雹、强烈的阵风和暴雨等 恶劣天气现象。 这种云的形成通常与不稳定大气层、充沛的水汽和足够的冲击力有关，它们在特定的气象条 件下发展，能够维持较长时间的强烈对流活动，从而形成冰雹。" },
  { id: 753, cat: "气象1", q: "夜间温度降低，低层常常出现逆温，会使得（）", opts: ["早晨天气晴朗", "早晨有雾和烟幕", "早晨有大风"], ans: 1, exp: "夜间逆温来，早晨雾烟绕。夜间温度降低时，由于地面的辐射冷却作用，近地面空气 温度下降，而上层空气温度相对较高，形成逆温现象。逆温层阻碍了空气的垂直对流，导致 水汽和污染物在近地面层积聚，从而容易形成雾和烟幕。" },
  { id: 754, cat: "气象1", q: "一般而言，气团的垂直高度可达几公里到十几公里，常常从地面伸展到对流层顶，水平 范围为（）", opts: ["十公里到几千公里", "几十公里到几百公里", "几公里到几百公里"], ans: 0, exp: "气团是指在一定区域内具有相对均匀的气象特性（如温度、湿度）的空气团。气团的 垂直高度通常可以从地面伸展到对流层顶，这个高度范围大约是几公里到十几公里。水平范 围则更广，可以从几十公里延伸到几千公里，覆盖广阔的地理区域。" },
  { id: 755, cat: "气象1", q: "一般雷暴单体的生命史根据垂直气流状况可分为三个阶段，（）", opts: ["积云阶段、成熟阶段、消散阶段", "积云阶段、成风阶段、雷雨阶段", "升温阶段、降雨阶段、消散阶段"], ans: 0, exp: "一般雷暴单体的生命史根据垂直气流状况可分为三个阶段：积云阶段、成熟阶段和消 散阶段。在积云阶段，雷暴云开始形成，云中的上升气流开始增强。成熟阶段是雷暴最强烈 的时期，此时云中的上升气流达到最强，可能出现暴雨、冰雹、大风等天气现象。消散阶段 是雷暴云逐渐减弱，上升气流开始减弱，雷暴云开始解体。" },
  { id: 756, cat: "气象1", q: "以下选项哪个不是对流层的主要特征（）", opts: ["气温随温度升高而升高", "气温、湿度的水平分布很不均匀", "空气具有强烈的垂直混合"], ans: 0, exp: "对流层是地球大气层中最低的一层，其主要特征包括气温、湿度的水平分布不均匀，以及空气具有强烈的垂直混合。然而，对流层内气温随高度升高而升高并不是其主要特征。" },
  { id: 757, cat: "气象1", q: "与逆温层相联系的大气特征是（）", opts: ["稳定的空气层", "不稳定的空气层", "高度升高温度降低"], ans: 0, exp: "逆温层是指气温随高度的升高而增加的大气层。 在逆温层中，空气比较稳定，因为正常情况下气温随高度升高而降低时，空气容易发生对流，而逆温层中这种对流受到抑制。所以与逆温层相联系的大气候特征是稳定的空气层。" },
  { id: 758, cat: "气象1", q: "云外绕飞雷雨时，航空器距离积雨云、浓积云夜间不得少于（）", opts: ["5 公里", "10 公里", "15 公里"], ans: 1, exp: "云外绕飞雷雨时，航空器距离积雨云、浓积云夜间不得少于 10 公里。这个规定是为 了确保飞机能够避开可能存在的气流扰动和雷击危险，保证飞行的安全。" },
  { id: 759, cat: "气象1", q: "在标准大气中，海平面上的气温和气压值是（）", opts: ["15°C, 1000hPa", "O°C, 760mmHg", "15°C, 1013.25hPa"], ans: 2, exp: "在标准大气中，海平面上的气温和气压值是 15°C，1013.25hPa。这个值是国际标准 大气（ISA）中定义的标准海平面条件，它是一个理论上的大气模型，用于航空、气象和其 他科学计算。这个模型假设在海平面上，标准大气压强为 1013.25 百帕斯卡（hPa），温度 15 摄氏度。" },
  { id: 760, cat: "气象1", q: "在大气层中，大气密度（）", opts: ["在同温层内随高度增加保持不变", "随高度增加而增加", "随高度增加而减小"], ans: 2, exp: "大气密度随高减，高度上升空气稀。在大气层内，随着高度的增加，大气压力逐渐减 小，而大气密度与大气压力有密切关系。通常情况下，高度越高，大气越稀薄，大气密度也 就越小。同温层内随高度增加大气密度也会减小而不是保持不变；大气密度不会随高度增加 而增加。" },
  { id: 761, cat: "气象1", q: "在对流层中，空气温度（）", opts: ["随高度增加而降低", "随高度增加而升高", "随高度增加保持不变"], ans: 0, exp: "在对流层内，空气的温度随高度增加而降低。这是因为对流层内的热源主要是地面，靠近地面的空气被加热后上升，随着高度的增加，空气与地面的接触减少，受到的加热作用 减弱，因此温度逐渐降低。" },
  { id: 762, cat: "气象1", q: "在雷暴的生存周期中，哪个阶段的特征使云中充满下降气流？（）", opts: ["积云阶段", "成熟阶段", "消散阶段"], ans: 2, exp: "【雷暴散，降气流】在雷暴的生存周期中，消散阶段的特征是云中充满下降气流。在 这个阶段，雷暴云逐渐消散，云中的水滴和冰晶开始下落，同时云中的上升气流逐渐减弱，下降气流逐渐增强。" },
  { id: 763, cat: "气象1", q: "在山地背风坡中的下降气流中飞行时，除造成飞机掉高度外，还可造成严重危害的原因 是（）", opts: ["气压式高度表读数高于实际高度", "空速表误差增大", "地速减小"], ans: 0, exp: "在山地背风坡中的下降气流中飞行时，除了会造成飞机掉高度外，还可能造成严重危 害的原因是气压式高度表读数高于实际高度。这是因为在下降气流中，空气压力随高度的降 低而增加，导致气压式高度表指示的高度比实际飞行高度要高。" },
  { id: 764, cat: "气象1", q: "在山区飞行时应当注意，最强的乱流出现在（）", opts: ["山的迎风坡", "山的背风坡", "山谷中间"], ans: 2, exp: "在山区飞行时应当注意，最强的乱流出现在山谷中间。因为山谷中间的气流受到山脉 两侧的阻挡，会形成湍流和涡流，导致飞行器的不稳定。 这种乱流可能会对飞行器造成不稳定的飞行状态，甚至危及飞行安全。" },
  { id: 765, cat: "气象1", q: "在重要天气预告图上用黑色的断线围起来的区域凹凸型，表示有（）", opts: ["晴天积云", "晴天颠簸", "西风急流"], ans: 1, exp: "在重要天气预告图上，用黑色的断线围起来的区域表示有晴空颠簸。这是因为晴空颠 簸通常与急流轴附近的湍流有关，这种颠簸可能对飞行安全造成威胁，因此在天气图中用特 定的符号进行标注，以提醒飞行员和航空人员注意。晴空颠簸区域的标注有助于飞行人员规 避可能的危险区域，确保飞行安全。" },
  { id: 766, cat: "气象1", q: "下列有关对大气温度说法正确的是（）", opts: ["随高度增高而降低", "在对流层内随高度增高而降低", "随高度增高而增大"], ans: 1, exp: "在对流层内，随着高度的增加，温度通常会降低。这是因为对流层内的热量主要来自 地面，随着高度的增加，热量逐渐减少，导致温度降低。" },
  { id: 767, cat: "气象1", q: "对流层中，按气流和天气现象分布的特点，可分为下、中、上三个层次，代表对流层气 流的基本趋势是（）", opts: ["下层，气流混乱", "中层，气流相对平稳", "上层，水汽含量很少"], ans: 1, exp: "对流层的中层通常位于对流层的中部，气流相对平稳，没有低层的强烈对流和高层的 剧烈变化。 其他选项分析如下： 1、下层，气流混乱：错误。虽然下层的气流确实较为混乱，但题目要求的是代表对流层气 流的基本趋势，中层的气流相对平稳更能体现这一趋势。 2、上层，水汽含量很少：错误。虽然上层的水汽含量确实较少，但题目要求的是气流的基 本趋势，而不是水汽含量。" },
  { id: 768, cat: "气象1", q: "对流层大气热量的直接来源主要是（）", opts: ["水汽吸收太阳辐射", "空气吸收地面辐射", "臭氧吸收太阳紫外线辐射"], ans: 1, exp: "对流层大气的主要热量来源是地面辐射。地面吸收太阳辐射后，以长波辐射的形式向 大气释放热量，这些热量被空气吸收，从而加热对流层。" },
  { id: 769, cat: "气象1", q: "气压高度通过测量大气的什么参数来反映飞行高度？（）", opts: ["大气密度", "大气压力", "大气温度"], ans: 1, exp: "气压式高度表通过测量大气压力来反映飞行高度。随着高度的增加，大气压力会逐渐 降低，因此可以通过测量大气压力来确定飞行高度。 其他选项分析如下： 1、大气密度：错误。虽然大气密度与高度有关，但气压式高度表并不直接测量大气密度。 2、大气温度：错误。气压式高度表不测量大气温度来确定高度，虽然温度会影响气压，但 高度表主要依赖气压变化。" },
  { id: 770, cat: "气象1", q: "以下哪种雾的日变化最明显？（）", opts: ["平流雾", "辐射雾", "蒸发雾"], ans: 1, exp: "辐射雾的日变化最为明显。它通常在夜间至凌晨形成，尤其是在晴朗、微风、近地面 水汽充沛且有逆温存在的条件下。辐射雾在日出前后达到最浓，随后随着太阳升起和气温升 高，雾会逐渐消散。" },
  { id: 771, cat: "气象1", q: "以下不能直接反映空气干燥潮湿程度的物理量是（）", opts: ["相对湿度", "气温露点差", "露点温度"], ans: 2, exp: "露点温度是空气中的水汽开始凝结成露珠的温度，它本身不能直接反映空气的干燥或 潮湿程度。虽然露点温度可以间接反映空气中的水汽含量，但它需要结合其他物理量（如气 温）来评估空气的干燥或潮湿程度。" },
  { id: 772, cat: "气象1", q: "气温升高，飞机起飞着陆时的滑跑距离要（）", opts: ["保持不变", "缩短", "增长"], ans: 2, exp: "气温升高时，空气密度降低，导致飞机需要更大的速度来产生足够的升力，从而增加 起飞和着陆时的滑跑距离。" },
  { id: 773, cat: "气象1", q: "在山谷飞行时，应采取的措施是（）", opts: ["靠近背风坡飞行", "靠近迎风坡飞行", "飞出山口马上转弯"], ans: 1, exp: "在山谷飞行时，靠近迎风坡飞行可以利用上升气流，减少湍流的影响，从而提高飞行 的稳定性和安全性。 其他选项分析如下： 1、靠近背风坡飞：错误。背风坡通常会有下降气流和湍流，飞行时会更加危险。 2、飞出山口马上转弯：错误。飞出山谷后不要过早转弯，以免进入因山谷地形而形成的涡 旋气流中。" },
  { id: 774, cat: "气象1", q: "地面有明显日变化的主要原因是（）", opts: ["气压的变化", "摩擦力的变化", "乱流强度的变化"], ans: 0, exp: "地面风的日变化主要受气压变化的影响。白天和夜晚的温度差异会导致气压的变化，从而影响风的强度和方向。 其他选项分析如下： 1、摩擦力的变化：错误。虽然摩擦力会影响风的强度，但它不是地面风日变化的主要原因。 2、乱流强度的变化：错误。乱流强度的变化会影响风的稳定性，但它不是地面风日变化的 主要原因。" },
  { id: 775, cat: "气象1", q: "风越过山脊，湍流（）", opts: ["加大", "减小", "不变"], ans: 0, exp: "当风越过山脊时，由于地形的阻挡，气流会加速并产生湍流，导致湍流强度增加。 其他选项分析如下： 1、减小：错误。风越过山脊时，湍流不会减小，反而会增加。 2、不变：错误。风越过山脊时，湍流强度会发生变化，不会保持不变。" },
  // ==================== 气象2 ====================
  { id: 776, cat: "气象2", q: "32 华氏度是 0 摄氏度，那么 59 华氏度是多少摄氏度？（）", opts: ["O 摄氏度", "23 摄氏度", "15 摄氏度"], ans: 2, exp: "首先，我们要知道华氏度与摄氏度的转换公式：摄氏度=（华氏度-32）=1.8。 已知 32 华氏度是 O 摄氏度，这是一个基准点。 题目要求计算 59 华氏度对应的摄氏度，我们根据公式进行计算：（59-32）-1.8=15（ 氏度）所以 59 华氏度是 15 摄氏度，答案选 15 摄氏度。" },
  { id: 777, cat: "气象2", q: "不属于云对安全飞行产生不利影响的原因是（）", opts: ["影响正常的目测", "温度低造成机翼表面结冰", "增加阻力"], ans: 2, exp: "云对安全飞行的影响主要包括：影响正常的目测、温度低造成机翼表面结冰、以及在 云中飞行会产生错觉等。这些因素都可能对飞行安全造成不利影响。而增加阻力并不是云对 飞行安全产生不利影响的常见原因，因此该选项不属于。" },
  { id: 778, cat: "气象2", q: "侧风中着陆，为了修正偏流，可以采用既修正了偏流，又使飞机的升阻比不减小的方法 是（）", opts: ["改变航向法和侧滑法相结合", "改变航向法", "侧滑法"], ans: 1, exp: "改变航向法是侧风着陆时的最佳选择，因为它既能有效修正偏流，又能保持飞机的升 阻比不变，确保飞行稳定性和安全性。相比之下，侧滑法需向侧风方向压盘形成坡度，导致 升力减小、升阻比下降，不利于着陆。" },
  { id: 779, cat: "气象2", q: "大气压力的降低对飞机性能有显著的影响，在较高的高度，伴随着降低大气压力（）", opts: ["起飞和着陆距离会增加，爬升率会减小", "起飞和着陆距离会增加，爬升率也会增加", "起飞和着陆距离会减小，爬升率也会减小"], ans: 0, exp: "在较高的高度，随着大气压力的降低，飞机的性能会受到影响。这是因为空气密度的 降低导致飞机发动机的推力减小，同时飞机的升力也会减小，这就需要飞机以更大的速度来 获得足够的升力，从而增加了起飞和着陆的距离。此外，由于空气稀薄，飞机的爬升率也会 降低。" },
  { id: 780, cat: "气象2", q: "地面天气图上填写的气压是（）", opts: ["本站气压", "海平面气压", "场面气压"], ans: 1, exp: "地面天气图上填写的气压是指海平面气压。这是因为在气象学中，为了标准化和便于 比较，通常将各地的气压值转换为海平面气压，即假设气压观测点位于海平面上时的气压值。 而本站气压是指观测点所在位置的实际气压，场面气压主要用于航空领域，与地面天气图上 填写的气压不同。" },
  { id: 781, cat: "气象2", q: "地球自转产生的地球自偏向力对风向产生影响，下列哪个是正确的？（）", opts: ["北半球，地球自转偏向力使得气流向东偏转", "北半球，地球自转偏向力使得气流向西偏转", "北半球，地球自转偏向力使得气流先向东再向西偏转"], ans: 0, exp: "地球自转产生的地球自转偏向力，也称为科里奥利力，对风向产生影响。在北半球，地球自转偏向力使得气流向右偏转，即向东偏转。" },
  { id: 782, cat: "气象2", q: "低空风切变主要形成的原因是什么？（）", opts: ["雷暴、低空急流和锋面活动", "气流经过特定环境时产生", "具体原因还不是特别明了"], ans: 0, exp: "低空风切变主要的形成原因包括雷暴、低空急流和锋面活动。这些天气现象能够产生 强烈的垂直和水平风切变，对飞行安全构成威胁。" },
  { id: 783, cat: "气象2", q: "飞机的性能主要受大气密度的影响，当实际大气密度大于标准密度时（）", opts: ["空气作用于飞机上的力要加大，发动机推力减小", "空气作用于飞机上的力要减小，发动机推力增大", "空气作用于飞机上的力要加大，发动机推力增大"], ans: 2, exp: "飞机的飞行性能确实受到大气密度的显著影响。当实际大气密度大于标准大气密度时，意味着空气分子的数量更多，因此空气作用于飞机上的力（如升力和阻力）会增大。同时，由于空气密度的增加，发动机在吸入相同体积空气时能够获得更多的氧气，这有助于燃烧更 充分，从而增大发动机的推力。" },
  { id: 784, cat: "气象2", q: "飞机外表面的冰霜雪等，（）", opts: ["会引起飞机操纵效能增加", "会出现指令仰角变化和滚转", "会使外表面变得粗糙，增加阻力，减少升力"], ans: 2, exp: "飞机外表面的冰霜雪会使飞机外表面变得粗糙。粗糙的表面会增加空气对飞机的摩擦 阻力，同时会破坏飞机表面的气流形态，导致升力减小。" },
  { id: 785, cat: "气象2", q: "飞行场当地气温的变化，主要会影响以下哪种无人机的传感器？", opts: ["磁罗盘", "气压高度计", "速率陀螺"], ans: 1, exp: "无人机上的气压高度计是利用大气压力变化来计算无人机高度的传感器。当地气温的 变化会影响大气压力，进而影响气压高度计的测量结果。因此，气温变化主要影响的是无人 机的气压高度计。" },
  { id: 786, cat: "气象2", q: "风吹来时，那种局地风向不断改变，风速一阵大一阵小的现象称为（）", opts: ["风的阵性", "风切变", "风向不定"], ans: 0, exp: "风吹来时，如果局地风向不断改变，风速一阵大一阵小，这种现象称为风的阵性。风 的阵性是指风速和风向在短时间内的突然变化，这种变化可能是由于多种气象条件引起的，如地形、温度差异、气压变化等。" },
  { id: 787, cat: "气象2", q: "风切变的仪表判断法，以下不正确的是（）", opts: ["空速表指示的非理性变化", "俯仰角指示快速变化", "发动机转速和地速快速变化"], ans: 2, exp: "风变的仪表判断法中，不正确的是发动机转速和地速快速变化。风切变的仪表判断法 主要包括空速表指示的非理性变化、俯仰角指示快速变化等。发动机转速和地速快速变化并 不是风切变的标准仪表判断方法。" },
  { id: 788, cat: "气象2", q: "风向 270 度，航向 90 度，这时无人机在（）", opts: ["顺风飞行", "逆风飞行", "侧风飞行"], ans: 0, exp: "风向是指风的来向，风向 270 度表示风从正西方向吹来。航向是指飞机或无人机前进 的方向，航向 90 度表示正向东飞行。当风从正西方向吹来，无人机向东飞行，此时无人机 与风的方向一致，所以是顺风飞行。" },
  { id: 789, cat: "气象2", q: "风向为 SE，那么风的来向为（）", opts: ["东北", "东南", "西北"], ans: 1, exp: "风向是指风吹来的方向。当风向为 SE，即东南（Southeast）时，意味着风是从东南 方向吹来的。因此，风的来向就是东南。" },
  { id: 790, cat: "气象2", q: "根据国际民航组织的规定，云满天时的云量为（）", opts: ["12", "8", "10"], ans: 1, exp: "根据国际民航组织的规定，云满天时的云量 8，即天空被云完全遮蔽时的云量表示为 8。" },
  { id: 791, cat: "气象2", q: "关于锋面，下列哪种描述正确的是？（）", opts: ["锋面就是不同方向的风交汇的界面", "锋面就是温度、湿度等物理性质不同的两种气团的交界面", "锋面就是风场与地面的交线，也简称为锋"], ans: 1, exp: "锋面是指温度、湿度等物理性质不同的两种气团相遇时形成的交界面。在锋面处，由 于两种气团的物理性质存在显著差异，通常伴随着天气变化，如云、雨、风等。锋面是气象 学中一个重要的概念，它与天气变化密切相关。" },
  { id: 792, cat: "气象2", q: "国际标准大气的定义是（）", opts: ["海平面附近常温常压下的空气的密度", "地平面附近常温常压下的空气的密度", "地表层附近常温常压下的空气的密度"], ans: 0, exp: "国际标准大气（ISA，International Standard Atmosphere）是指在海平面附近，温度 和压力处于标准参考条件下的空气状态。这个标准是为了提供一个统一的参考环境，以便在 不同地点和时间比较飞行器的性能和其他大气参数。" },
  { id: 793, cat: "气象2", q: "机场上常用风向袋来估算风速，当风向袋吹平时，风速已达（）", opts: ["10~12 米/秒", "6~10 米/秒", "5~6 米/秒"], ans: 1, exp: "根据国际民航组织（ICAO）和各国航空标准（如 FAA、中国民航）的通用判据，当风 向袋完全吹平时，风速通常在 6~10 米/秒（12~20 节）范围内。这个范围考虑了风向袋材质、长度和安装方式的差异。《民用机场飞行区技术标准》（MH5001）采用与国际接轨的标准，风 向袋吹平对应 6~10 米/秒。" },
  { id: 794, cat: "气象2", q: "机场上空高度较低的云会直接影响飞机的起降，其中，危害最大的云是（）", opts: ["对流云", "卷状云高云", "层状云中云"], ans: 0, exp: "机场上空高度较低的云会直接影响飞机的起降，其中危害最大的云是对流云。对流云 易遭到电击，使仪表失灵，油箱爆炸，或者造成强烈颠簸、结冰，使操纵失灵，发生飞行事 故。因此，危害最大的云是对流云。" },
  { id: 795, cat: "气象2", q: "接近地面的对流气流会影响驾驶员的操控能力，下列说法哪种正确？", opts: ["在最后进近时，来自全无植被的地形的下降气流有时会产生下沉效应，导致飞过预期的 着陆点", "在一大片水体或者稠密植被的区域之上进近会趋于产生一个下沉效应，导致着陆在不到 预期的着陆点", "在一大片水体或者稠密植被的区域之上进近会趋于会产生漂浮效应，导致飞过预期的着 陆点"], ans: 1, exp: "当飞机接近地面时，对流气流可能显著影响飞行操控，尤其是在特定地形条件下。例 如，在大片水体或茂密植被上方，由于地表温度较低，容易形成稳定的冷空气层，从而产生 下沉气流，导致飞机着陆在不到预期的着陆点。飞行员若不及时调整，可能会提前触地，造 成安全隐患。" },
  { id: 796, cat: "气象2", q: "进气道结冰将导致危险的后果，下列描述不正确的是（）", opts: ["使进气速度场分布不均匀和使气流发生局部分离，引起压气机叶片的振动", "冰屑脱离，进入压气机，而造成压气机的机械损伤", "结冰堵塞进气道，使得进入压气机的气流明显减少，导致发动机富油停车"], ans: 2, exp: "进气道结冰确实可能导致严重的后果，其中包括进气速度场分布不均匀、气流局部分 离，以及冰屑脱落进入压气机造成机械损伤。而结冰堵塞进气道导致发动机富油停车并不是 一个常见的直接后果。实际上，进气道结冰更可能导致发动机功率下降或喘振，而不是直接 导致富油停车。" },
  { id: 797, cat: "气象2", q: "绝对温度的零度是（）", opts: ["-273°F", "-273K", "-273°C"], ans: 2, exp: "绝对温度的零度是-273°C，这是绝对温标（开尔文温标）中的零点，也是摄氏温标中 的绝对零度。绝对零度是一个理论上的最低温度，在这个温度下，物体内部的粒子运动理论 上会停止。" },
  { id: 798, cat: "气象2", q: "雷暴处于发展阶段时（）", opts: ["地面气压持续下降", "地面气压持续上升", "地面气压保持不变"], ans: 0, exp: "雷暴处于发展阶段时，通常伴随着地面气压的持续下降。这是因为雷暴的发展伴随着 强烈的上升气流，这些上升气流在地面形成低气压区域，导致地面气压下降。" },
  { id: 799, cat: "气象2", q: "露点温度指空气在水汽含量和气压都不改变的条件下，冷却到饱和时的温度。形象地说，就是空气中的水蒸气变为露珠时候的温度叫露点温度。下述哪个正确？（）", opts: ["当空气中水汽已达到饱和时，气温与露点温度相同", "当水汽未达到饱和时，气温一定低于露点温度", "在 100%的相对湿度时，周围环境的温度高于露点温度"], ans: 0, exp: "露点温度是指在水汽含量和气压都不改变的条件下，空气冷却到饱和时的温度。当空 气中的水汽已达到饱和时，意味着空气中的水汽含量已经达到了该温度下的最大值，此时的 气温与露点温度相同。" },
  { id: 800, cat: "气象2", q: "某个风力标志箭头长得像“F”，并且两个横杠一样长，代表（）", opts: ["2 级", "3 级", "4 级"], ans: 2, exp: "风力标志中“F”形状的箭头表示风向，箭头指向即风向。风力的大小由横杠表示，其 中每一长横表示二级风，短横表示一级风。因此，如果风力标志箭头像“F”，并且两个横杠 一样长，这表示风力为 4 级。" },
  { id: 801, cat: "气象2", q: "目视判断风切变的参照物，以下不正确的是（）", opts: ["雷暴冷性外流气流的尘卷风（云）", "卷积云带来的降雨", "雷暴云体下垂的雨幡"], ans: 1, exp: "目视判断风切变时，可以依据一些自然现象或特定气象条件作参照物。雷暴冷性外流 气流的尘卷风（云）和雷暴云体下垂的雨幡都是判断风切变的重要视觉线索。尘卷风通常是 由雷暴冷性外流气流前缘的强劲气流吹起的尘土形成的，而雨幡则是雷暴云体下垂的雨滴或 冰晶，它们的存在预示着强烈的下冲气流和可能的风切变。然而，卷积云带来的降雨并不直 接指示风切变，因为降雨可能是由多种气象条件引起的，不一定与风切变直接相关。" },
  { id: 802, cat: "气象2", q: "哪一类作业的气象无人机在控制成本的情况下，允许单次使用不回收？（）", opts: ["旱涝灾害评估", "人工催化播撒降雨", "强对流云直接探测"], ans: 2, exp: "强对流云直接探测作业的气象无人机在控制成本的情况下，允许单次使用不回收。这 是因为在强对流天气下，无人机控制无法得到保障，为了得到第一手气象资料，哪怕让无人 机失控丢失，相比获取最直接的对流信息要有价值得多。因此，允许无人机失控，以获取宝 贵的气象数据。" },
  { id: 803, cat: "气象2", q: "能见度，是反映大气透明度的一个指标，测量大气能见度的错误方法是（）", opts: ["用望远镜目测", "使用大气透射仪", "使用激光能见度自动测量仪"], ans: 0, exp: "能见度是反映大气透明度的重要指标。使用大气透射仪和激光能见度自动测量仪都是 较为科学准确地测量大气能见度的方法，它们基于光学原理等进行精确测量。而用望远镜目 测能见度非常不精确且主观性强，不能做科学的测量方法。" },
  { id: 804, cat: "气象2", q: "起飞场地从北京移至拉萨，对哪类无人机的高度性能影响最严重？（）", opts: ["油动固定翼", "电动多轴", "电动固定翼"], ans: 0, exp: "拉萨地处高海拔地区，空气稀薄，含氧量低。对于油动固定翼无人机来说，发动机依 赖空气燃烧提供动力，在高海拔地区空气稀薄会使发动机功率下降严重，从而对其高度性能 影响最严重。电动多轴和电动固定翼主要依靠电池供电，受空气稀薄的影响相对较小。" },
  { id: 805, cat: "气象2", q: "气团变性的主要原因是（）", opts: ["太阳辐射的变化", "天气系统的移动", "下垫面性质发生了变化"], ans: 2, exp: "气团变性是指当气团移至新的下垫面时，其物理属性逐渐发生变化的过程。下垫面性 质不同，对气团的温度、湿度等产生影响，从而导致气团变性。" },
  { id: 806, cat: "气象2", q: "气团的分类方法正确的是（）", opts: ["冷气团和干气团", "暖气团和湿气团", "北冰洋气团、极地气团，热带气团、赤道气团"], ans: 2, exp: "气团的分类通常基于其来源区域的气候特征。正确的分类方法是根据气团形成的地理 位置和温度特性，将它们分为北冰洋气团、极地气团、热带气团和赤道气团。这些分类反映 了气团的温度和湿度特性，以及它们对天气的影响。" },
  { id: 807, cat: "气象2", q: "气团是指气象要素（主要指温度，湿度和大气静力稳定度）在水平分布上比较均匀的大 范围空气团，下列不正确的是（）", opts: ["水平范围大", "垂直范围大", "水平温度梯度大"], ans: 2, exp: "气团的特点是水平范围大，一般可达几百到几千千米；垂直范围也大，可达几千米到 十几千米。而气团在水平分布上温度、湿度等气象要素比较均匀，所以水平温度梯度小，而 不是大。" },
  { id: 808, cat: "气象2", q: "气温、气压和空气湿度的变化都会对飞机性能和仪表指示造成一定的影响，这种影响主 要通过他们对空气密度的影响而实现，下列描述哪个正确？（）", opts: ["空气密度与气压成正比，与气温也成正比", "空气密度与气压成正比，与气温成反比", "空气密度与气压成反比，与气温成正比"], ans: 1, exp: "气压高，密度高；气温高，密度低。空气密度是指单位体积空气中的质量，它受到气 温和气压的影响。在相同的气压下，气温越高，空气分子运动越剧烈，空气密度越低；而在 相同的气温下，气压越高，空气分子被压缩得越紧密，空气密度越高。因此，空气密度与气 压成正比，与气温成反比。" },
  { id: 809, cat: "气象2", q: "气温的变化，会严重影响电动无人机的哪项性能？（）", opts: ["速度性能", "续航性能", "载荷性能"], ans: 1, exp: "气温的变化对电动无人机的性能有显著影响，尤其是续航性能。电池作为电动无人机 的能源心脏，其性能受温度影响较大。在低温条件下，电池的放电效率会降低，导致续航时 间缩短，从而影响无人机的飞行时间。高温同样会对电池性能产生影响，可能导致电池过热，影响其性能和寿命。因此，气温的变化会严重影响电动无人机的续航性能。" },
  { id: 810, cat: "气象2", q: "气象上把气温垂直递减率等于零（即 y=0）的气层称为（）", opts: ["逆温层", "等温层", "不稳定气层"], ans: 1, exp: "在气象学中，当气温随高度的增加而不再下降，即气温垂直递减率等于零（y=0）时，这样的气层被称为等温层。这是因为在等温层中，温度在垂直方向上是均匀的，没有变化。" },
  { id: 811, cat: "气象2", q: "气象上的风向是指（）", opts: ["风的去向", "风的来向", "气压梯度力的方向"], ans: 1, exp: "在气象学中，风向是指风的来向，也就是风从哪个方向吹来。这是根据风的起源点来 定义的，而不是风的去向或者风最终到达的地方。" },
  { id: 812, cat: "气象2", q: "气象台观测的风向是 180，飞机起飞着陆时的最佳方向是（）", opts: ["由北朝南", "由南朝北", "由西向东"], ans: 0, exp: "气象台观测的风向是 180 度，表示风是从南方吹来的。飞机在起飞和着陆时，通常选 择与风向相反的方向，以减少风对飞机的影响，确保安全和稳定。因此，当风从南方吹来时，飞机最佳的起飞和着陆方向是由北朝南。" },
  { id: 813, cat: "气象2", q: "热雷暴的形成原因是（）", opts: ["地面水汽蒸发", "冷空气冲击暖空气而形成上升运动", "地面受热不均"], ans: 2, exp: "热雷暴的形成主要是由于地面受热不均引起的。 当地面受热不均时，会导致空气的对流运动，使得暖湿空气上升，形成雷暴云。这种雷暴通 常发生在夏季，当地面温度升高，暖湿空气上升，遇到冷空气时，会形成强烈的上升气流，从而引发雷暴。" },
  { id: 814, cat: "气象2", q: "三大气要素为（）", opts: ["气温、气压和空气湿度", "气温、风和云", "风、云和降水"], ans: 0, exp: "气温、气压和空气湿度是非常重要的气象要素。 气温决定了环境的冷热程度，对无人机的电池性能等有影响；气压的变化会影响空气密度从 而影响无人机的飞行性能；空气湿度则关系到无人机电子设备的防潮等问题。" },
  { id: 815, cat: "气象2", q: "山地对风的影响，以下描述正确的是（）", opts: ["山体本身的障碍影响，使气流被阻滞不前", "一般山顶和峡谷风口的风速更大", "一般山底和峡谷风口的风速增大"], ans: 2, exp: "山地对风有很大影响。山体本身会阻挡气流，使气流被阻滞不前。一般山顶和峡谷风 口由于地形的原因，风在通过狭窄通道或高处时会加速，风速更大。而山底通常受到山体的 遮挡，风速相对较小，不是增大。" },
  { id: 816, cat: "气象2", q: "使原来静止的空气产生垂直运动的作用力，称为（）", opts: ["对流冲击力", "气动作用力", "热力作用力"], ans: 0, exp: "使原来静止的空气产生垂直运动的作用力，称为对流冲击力。这种力通常是由地面受 热不均引起的，当地面受热时，暖空气会上升，冷空气会下沉，形成对流运动。这种垂直运 动的空气流动就是对流冲击力。" },
  { id: 817, cat: "气象2", q: "手抛电动固定翼民用无人机，一般在几级风以上，就难以自驾飞行？", opts: ["6 级", "2 级", "4 级"], ans: 2, exp: "手抛电动固定翼民用无人机在 4 级风以上就难以自驾飞行。4 级风也被称为和风，风 速在 5.5～7.9 米/秒之间。在这个风力下，无人机的飞行稳定性会受到较大影响，操作难度 增加，甚至可能对飞行安全构成威胁。 风速等级： 4 级风（5.5~7.9m/s）：树叶和树枝持续摇摆，无人机已明显颠簸，自驾飞行困难。 6 级风（10.8~13.8m/s）：大树枝摇动，电线有声，无人机几乎无法稳定飞行。 2 级风（1.6~3.3m/s）：感觉有风，树叶微响，对无人机影响较小。" },
  { id: 818, cat: "气象2", q: "四级风风速为（）", opts: ["5.5-7.9M/S", "10.8-13.8M/S", "8-10.7M/S"], ans: 0, exp: "风速的分级通常按照蒲福风级（Beaufortscale）来划分，这是一种用来描述风速的等 级系统。在蒲福风级中，四级风对应的风速范围是 5.5 到 7.9 米每秒（M/S）。这个风速范围 意味着风足够强，可以吹起尘土和纸张，小树枝也会摇摆。" },
  { id: 819, cat: "气象2", q: "天气预报可分为哪些，以下不正确的是（）", opts: ["天气形势预报", "气象要素预报", "大风降温预报"], ans: 2, exp: "天气预报主要分为两大类：天气形势预报和气象要素预报。而大风降温预报实际上是 气象要素预报中的一部分，它专门预报风速增大和气温下降的情况，因此它并不是天气预报 的一个独立分类。" },
  { id: 820, cat: "气象2", q: "同一架无人机于某日中午和傍晚进行两次 GPS 高度 200 米的巡航飞行，地面基准气压 相同的前提下，（）", opts: ["中午的气压高度高", "傍晚的气压高度高", "中午和傍晚的气压高度一样高"], ans: 0, exp: "中午高温气压高，傍晚低温气压低。无人机的 GPS 高度是根据地面基准气压和大气 压力的关系来计算的。气压高度是通过气压计测量的高度，其原理是通过大气压力随高度的 变化推算高度。气压高度受温度影响：温度越高，空气密度越低，气压随高度下降更慢，因 此气压高度会显示得比实际高度更高；反之，温度越低，气压高度显示得更低。" },
  { id: 821, cat: "气象2", q: "同一起飞重量的不同民用无人机系统航线飞行，一般（）的受风的影响小。", opts: ["巡航速度大", "巡航速度小", "巡航速度适中"], ans: 0, exp: "巡航速度快，抗风能力强。无人机在航线飞行时，受风的影响与其巡航速度有关。较 大的巡航速度意味着无人机在空中飞行时具有更高的空速，相对来说，风对其影响会相对较 小。当飞行速度较快时，风的作用相对于飞行速度来说就不会对飞行姿态产生太大影响，因 此受风影响较小。这是因为巡航速度大的情况下，无人机飞行时的惯性较大，风对其影响相 对较小。" },
  { id: 822, cat: "气象2", q: "卫星云图上下列哪个不是层云（雾）特征？", opts: ["在可见光云图上，层云（雾）表现为光滑均匀的云区", "层云（雾）边界整齐清楚，与山脉、河流、海岸线走向相一致", "在红外云图上，层云色调较亮，与地面色调相差较大"], ans: 2, exp: "层云（雾）在卫星云图上的特征包括：在可见光云图上表现为光滑均匀的云区；边界 整齐清楚，与山脉、河流、海岸线走向相一致；在红外云图上，层云色调较暗，与地面色调 相似。因此，选项“在红外云图上，层云色调较亮，与地面色调相差较大”并不是层云（雾）的特征，这是不正确的描述。" },
  { id: 823, cat: "气象2", q: "卫星云图上下列哪个不是积雨云特征？", opts: ["在卫星图像上的积雨云常是几个雷暴单体的集合", "无论可见光还是红外云图，积雨云的色调最白", "积雨云的尺度相差不大，一般，初生的较小，成熟的较大"], ans: 2, exp: "在卫星云图上，积雨云的特征包括： 1.积雨云常是几个雷暴单体的集合，它们可以合并形成较大的云团。 2.在可见光和红外云图上，积雨云的色调最白，因为它们的高度和厚度通常比其他类型的云 要大，反射和发射的辐射更多。 3.积雨云的尺度可以相差很大，初生的积雨云相对较小，而成熟的积雨云则较大，且顶部可 能发展出卷云砧，表现为椭圆形。 因此，选项“积雨云的尺度相差不大，一般，初生的较小，成熟的较大”不是积雨云的特征。" },
  { id: 824, cat: "气象2", q: "卫星云图上下列哪个不是卷状云特征？", opts: ["在可见光云图上，卷云呈灰、深灰色", "无论可见光还是红外云图，卷云没有纤维结构", "在红外云图上，卷云顶温度很低，呈白色"], ans: 1, exp: "在卫星云图上，卷状云的特征包括： 1.在可见光云图上，卷云的反照率低，通常呈灰到深灰色。 2.在红外云图上，由于卷云顶部温度很低，它们通常呈白色。 3.无论是可见光还是红外云图，卷云都具有纤维结构。 因此，无论可见光还是红外云图，卷云没有纤维结构，这是错误的。实际上，卷云在两种云 图上都有纤维结构。" },
  { id: 825, cat: "气象2", q: "卫星云图上下列哪个不是云中云特征？", opts: ["在卫星云图上，中云与天气系统相连，表现为大范围的带状、涡旋状、逗点状", "在可见光云图上，中云呈灰白色到白色，色调的差异判定云的厚度", "在红外云图上，中云呈深灰色，介于高低云之间的色调"], ans: 2, exp: "中云红外非深灰。在卫星云图上识别中云的特征时，我们可以根据其与天气系统的关 联、颜色以及在红外云图上的表现来判断。中云在卫星云图上通常与天气系统相连，表现为 大范围的带状、涡旋状、逗点状。在可见光云图上，中云呈灰白色到白色，色调的差异可以 判定云的厚度。而在红外云图上，中云的颜色应该是中等程度的灰色，介于高云和低云之间。 因此，选项“在红外云图上，中云呈深灰色”并不是中云的特征，这是不正确的描述。" },
  { id: 826, cat: "气象2", q: "卫星云图主要可分为哪两类？", opts: ["红外云图和可见光卫星云图", "红外云图和色调强化卫星云图", "色调强化卫星云图和可见光卫星云图"], ans: 0, exp: "卫星云图确实主要分为两大类： 1.红外云图：这种云图利用红外辐射来捕捉地球表面和大气层的温度差异。在红外云图上，较冷的区域（如高海拔的云层）会显示为白色，而较暖的区域（如陆地表面）则显示为黑色 或灰色。 2.可见光卫星云图：这种云图模拟人眼所看到的景象，捕捉的是太阳光在地球表面和大气层 的反射光。在可见光云图上，云层的亮度取决于它们对太阳光的反射能力，通常云层越厚，反射越强，看起来越白。" },
  { id: 827, cat: "气象2", q: "无人机飞行员在操纵飞机平飞时，遇到强烈的垂直上升气流时，为了防止过载超规定应 （）", opts: ["加大油门迅速脱离", "以最大上升率增大高度", "适当减小飞行速度"], ans: 2, exp: "当无人机飞行员在操纵飞机平飞时遇到强烈的垂直上升气流，为了防止过载超过规定，正确的操作是适当减小飞行速度。这是因为在遇到上升气流时，飞机会受到额外的上升力，如果此时增加飞行速度，飞机的升力会进一步增加，可能导致飞机超过设计的过载限制，从 而对飞机结构造成损害或失去控制。减小飞行速度可以减少升力，帮助飞机更平稳地通过上 升气流区域。" },
  { id: 828, cat: "气象2", q: "无人机在积水道上起飞，其起飞距离比正常情况下（）", opts: ["长", "短", "相等"], ans: 0, exp: "积水道上起飞距离长。无人机在积水道上起飞时，由于积水道表面可能较为光滑，摩擦 力较小，这会影响无人机的起飞性能。在起飞过程中，无人机需要足够的摩擦力来获得足够 的升力，而在光滑表面上，无人机可能需要更长的距离来达到所需的起飞速度和升力。因此，与正常起飞条件相比，无人机在积水道上的起飞距离会较长。" },
  { id: 829, cat: "气象2", q: "西北风可以表示为：（）", opts: ["135°或 SE", "200° 或 NW", "315° 或 NW"], ans: 2, exp: "西北风是指从西北方向吹来的风，我们需要找到与西北方向相对应的角度和缩写。在 气象学中，风向通常以 360 度来表示，其中 0 度或 360 度代表正北方向，90 度代表正东方 向，180 度代表正南方向，270 度代表正西方向。因此，西北风应该位于 270 度和 360 度之 间，大约在 315 度左右。同时，西北风的缩写是 NW，代表 Northwest。" },
  { id: 830, cat: "气象2", q: "下列何种情况说明了飞机从一种气团斡旋进入了另一种气团？（）", opts: ["飞过山区时碰上了扰动气流", "穿过了高空急流", "在短时间内温度和风向都有明显变化"], ans: 2, exp: "当飞机在短时间内温度和风向都有明显变化时，很可能是从一种气团进入了另一种气 团。因为不同气团的温度、湿度、风向等气象要素有较大差异。飞过山区时碰上扰动气流，这主要是地形影响，不是进入另一种气团的表现；穿过高空急流主要是遇到强风带，也不是 进入不同气团的标志。" },
  { id: 831, cat: "气象2", q: "下列何种性质描述了气团的特征？（）", opts: ["能形成结构不同的云", "能覆盖大片地区，温度和湿度等特征性相对均匀", "气团内部各地天气差异很大"], ans: 1, exp: "气团是指具有相对均匀的温度、湿度和压力等气象特性的大片空气区域。这些空气团 通常覆盖广阔的地区，并且在其内部，气象条件相对一致。因此，描述气团特征的性质是它 们能覆盖大片地区，温度和湿度等特征性相对均匀。" },
  { id: 832, cat: "气象2", q: "下面关于飞机积冰的叙述哪一个正确？（）", opts: ["高云由于高度高、温度低，大多由冰晶构成，不容易形成飞机积冰", "中云温度低于 O°C，云层较厚，水滴含量大，积冰最严重", "低云云高低于 2000 米，温度高，不含过冷水滴，所以一般不出现飞机积冰"], ans: 1, exp: "1.高云虽然高度高、温度低且大多由冰晶构成，但在特定条件下也可能形成飞机积冰，只是 相对不容易，该选项错误。 2.中云温度低于 0°C，云层较厚，水滴含量大，飞机在其中飞行时容易遇到过冷水滴，从而 积冰较为严重，该选项正确。 3.低云虽然云高较低、温度相对高一些，但也可能含有过冷水滴，在一定条件下也会出现飞 机积冰，该选项错误。" },
  { id: 833, cat: "气象2", q: "山谷风的定义（）", opts: ["白天风从山谷吹向山坡，夜晚风从山坡吹向山谷", "白天风从山坡吹向山谷，夜晚风从山谷吹向山坡", "不管是白天还是黑夜风从山谷吹向山坡"], ans: 0, exp: "山谷风是一种局部环流现象，白天山坡受热快，空气上升，形成谷风（从山谷吹向山 坡）；夜晚山坡冷却快，空气下沉，形成山风（从山坡吹向山谷）。" },
  { id: 834, cat: "气象2", q: "下面关于雾的说法不正确的是（）", opts: ["大雾会影响无人机的起降手动操作", "大雾会影响无人机的航向自主飞行", "大雾会影响无人机航拍任务设备效果"], ans: 1, exp: "大雾会影响无人机的航向自主飞行的说法不正确。大雾主要影响能见度，确实会对无 人机的起降手动操作和航拍任务设备的效果产生影响，但对于航向的自主飞行，现代无人机 通常配备有导航系统和传感器，可以在一定程度上克服能见度低的问题。因此，虽然大雾会 影响飞行的安全性，但不一定会直接影响航向的自主飞行。" },
  { id: 835, cat: "气象2", q: "下述何种情况说明飞机是在气团内部飞行？（）", opts: ["飞行了很长时间下面仍然是广阔的海洋", "飞行了很长时间气象条件变化不大", "飞行中穿过了层状云系"], ans: 1, exp: "飞机在气团内部飞行时，由于气团内部气象条件相对一致，飞行过程中的气象条件变 化不大。这意味着飞机在气团内部飞行较长时间后，下方的景象和气象条件仍然保持相对稳 定。因此，选项 B“飞行了很长时间气象条件变化不大”正确地描述了飞机在气团内部飞行的 情况。" },
  { id: 836, cat: "气象2", q: "下列物理量中，反映大气潮湿程度的是（）", opts: ["饱和水汽压", "相对湿度", "露点温度"], ans: 1, exp: "反映大气潮湿程度的物理量是相对湿度。相对湿度是指实际水气压与同温度下饱和水 汽压的百分比。它直接反映了空气中水汽的含量与该温度下空气能够容纳的最大水汽含量之 间的比例，因此是衡量大气潮湿程度的常用指标。" },
  { id: 837, cat: "气象2", q: "形成风的原动力是（）", opts: ["水平地转偏向力", "地球的旋转运动", "水平气压梯度力"], ans: 2, exp: "气压有梯度，风起动力足。形成风的原动力是水平气压梯度力。气压梯度力是风形成 的直接原因，它是由气压差异引起的，促使空气从高压区向低压区移动。这种力是风形成的 驱动力，它推动空气水平移动，形成风。" },
  { id: 838, cat: "气象2", q: "一定质量的气体具有下列特性（）", opts: ["温度不变时，压力与体积成正比", "体积不变时，压力和温度成正比", "压力不变时，体积和温度成反比"], ans: 1, exp: "一定质量的气体在特定条件下遵循理想气体定律，即 PV=nRT，其中 P 代表压力，V 代表体积，n 代表气体的摩尔数，R 是理想气体常数，T 代表绝对温度。当体积不变时，压 力和温度成正比，这意味着如果温度升高，压力也会相应升高，反之亦然。" },
  { id: 839, cat: "气象2", q: "移经暖地表的冷气团具有下述何种特征？（）", opts: ["积状云，乱流和能见度好", "层状云气流平稳和低能见度", "毛毛雨和雾"], ans: 0, exp: "移经暖地表的冷气团具有的特征是积状云、乱流和能见度好。这是因为当冷气团移动 到暖地表时，地面的加热作用会导致冷气团底层增温，变得不稳定，从而容易形成积状云和 乱流。同时，由于暖空气的湿度较高，能见度相对较好。" },
  { id: 840, cat: "气象2", q: "以下哪几种仪表可以判断和识别低空风切？（）", opts: ["空速表、油量表、升降速度表、俯仰姿态指示器", "风速表、高度表、升降速度表、俯仰姿态指示器", "空速表、高度表、升降速度表、俯仰姿态指示器"], ans: 2, exp: "低空风切变是指在低空范围内风速和风向的突然变化，对飞行安全构成威胁。以下几 种仪表可以帮助判断和识别低空风切变： 1.空速表：显示飞机相对于空气的速度，风切变可能导致空速的突然变化。 2.高度表：显示飞机相对于地面的高度，风切变可能导致飞机高度的突然变化。 3.升降速度表：显示飞机上升或下降的速度，风切变可能导致飞机上升或下降速度的突然变 化。 4.俯仰姿态指示器：显示飞机相对于地面的俯仰角度，风切变可能导致飞机俯仰姿态的突然 变化。 因此，选项“空速表、高度表、升降速度表、俯仰姿态指示器”是正确的。" },
  { id: 841, cat: "气象2", q: "以下哪种不是卫星云图种类？（）", opts: ["红外卫星云图", "可见光卫星云图", "多光谱卫星云图"], ans: 2, exp: "卫星云图主要分为红外卫星云图和可见光卫星云图。而多光谱卫星云图并不是卫星云 图的主要分类，它是一种利用多个波段进行观测的技术，但不是一种独立的卫星云图种类。" },
  { id: 842, cat: "气象2", q: "影响空气粘性力的主要因素是（）", opts: ["空气清洁度", "空气温度", "相对湿度"], ans: 1, exp: "影响空气粘性力的主要因素是空气温度。空气粘性力，也称为空气的动态黏性系数，与空气的温度有直接关系。随着温度的升高，空气分子的运动速度加快，分子间的碰撞频率 增加，因此空气的粘性力也随之增加。" },
  { id: 843, cat: "气象2", q: "在北半球，一个飞行员作一次由西向东的长途飞行，在下面何种情况下，他将有可能碰 到因气压系统而形成的顺风体？（）", opts: ["在高压系统和低压系统南侧", "在高压系统南侧和低压系统北侧", "在高压系统北侧和低压系统南侧"], ans: 2, exp: "北半球低压区，逆时针向内旋，顺风体形成。在北半球，空气从高压区流向低压区，受地转偏向力影响，风向向右偏。在高压系统北侧，风向为偏西风，从西向东飞行是顺风； 在低压系统南侧，风向为偏东风，从西向东飞行也是顺风。" },
  { id: 844, cat: "气象2", q: "在北半球，一个飞行员作由东向西的长途飞行，在下面何种情况下，他将有可能碰到因 气压系统而形成的顺风？（）", opts: ["在高压系统和低压系统北侧", "在高压系统北侧和低压系统南侧", "在高压系统南侧和低压系统北侧"], ans: 2, exp: "高压系统南侧： 气流顺时针旋转一南侧风从西向东吹（偏西风）一与东向西飞行同向一顺风。 低压系统北侧： 气流逆时针旋转一北侧风从西向东吹（偏西风）一与东向西飞行同向一顺风。 错误选项分析： 1.高压北侧+低压北侧：高压北侧为偏东风（逆风），低压北侧为偏西风（顺风），矛盾。 2.高压北侧+低压南侧：高压北侧偏东风（逆风），低压南侧偏东风（逆风），完全错误。" },
  { id: 845, cat: "气象2", q: "在北半球 6000 米的高度由高压区飞向低压区，航线上应吹成的（）", opts: ["顺风", "右侧风", "左侧风"], ans: 2, exp: "北半球高压飞低压，左侧风吹来。在北半球，由于科里奥利力的作用，风会偏向右侧。 因此，当飞机从高压区飞向低压区时，由于高压区的风向是从高压指向低压，飞机在北半球 会感受到左侧风的影响。这是因为在北半球，风向会因为科里奥利力而向右偏转，所以从高 压区飞向低压区时，风会从左侧吹来。" },
  { id: 846, cat: "气象2", q: "在北半球摩擦层中，低区层的风向为（）", opts: ["逆时针向外旋转", "逆时针向内旋转", "顺时针向内旋转"], ans: 1, exp: "在北半球的摩擦层中，低压区的风向是逆时针向内旋转。这是因为在北半球，科里奥 利力使得风在低压区域向中心汇聚时，气流会逆时针方向旋转。这种旋转方向是由地球自转 产生的科里奥利力决定的，它影响着风向，使得风在北半球倾向于向左偏转。" },
  { id: 847, cat: "气象2", q: "在北半球与低区层有关的空气环流是（）", opts: ["向内、向上和沿逆时针方向", "向外、向上和沿顺时针方向", "向外、向下和沿顺时针方向"], ans: 0, exp: "在北半球，与低压区有关的空气环流是向内、向上和沿逆时针方向。这是因为在北半 球，低压系统中的气流会因为科里奥利力的作用而逆时针旋转。" },
  { id: 848, cat: "气象2", q: "在大风中自驾飞行的固定翼民用无人机，航线左转 90 度，（）", opts: ["顺风左转 90 度，转出的弯大", "逆风左转 90 度，转出的弯大", "逆风、顺风左转 90 度，转出的弯一样大"], ans: 0, exp: "在大风中自驾飞行的固定翼民用无人机，如果航线顺风左转 90 度，由于顺风的影响，飞机的实际转弯路径会受到风的影响而变大。这是因为顺风会增加飞机的速度，使得飞机在 转弯时覆盖更大的地面距离。相反，逆风会减小飞机的速度，导致转弯路径相对较小。因此，顺风左转 90 度时，转出的弯大。" },
  { id: 849, cat: "气象2", q: "在地表的风向稍微不同于地表之上几千英尺高度的风向的原因是（）", opts: ["当地地形影响气压", "地面有较强的地转偏向力", "风和地面之间的摩擦作用"], ans: 2, exp: "在地表的风向与地表之上几千英尺高度的风向不同，主要原因是风和地面之间的摩擦 作用。地表附近的风受到地面摩擦力的影响，这种摩擦力会改变风的方向和速度，使得地表 风向与高空风向出现差异。这种现象在气象学中被称为“风切变”，特别是在地形复杂或者地 表特征变化较大的地区更为明显。" },
  { id: 850, cat: "气象2", q: "在风中全马力飞行的固定翼民用无人机，（）", opts: ["顺风飞行时空速较大", "逆风飞行时空速较大", "顺风逆风空速相同"], ans: 2, exp: "对于固定翼民用无人机而言，无论是顺风还是逆风飞行，全马力飞行时发动机提供的 推力是恒定的，因此无人机的空速（即飞机相对于空气的速度）应该是相同的。空速是由飞 机的推力和空气阻力共同决定的，与风向无关。顺风或逆风主要影响的是地速（即飞机相对 于地面的速度），而不是空速。" },
  { id: 851, cat: "气象2", q: "在锋面经过机场时，要特别注意的是（）", opts: ["可能出现高度极低的风切变", "可能出现风沙天气", "雨层云中的连续性小雨"], ans: 0, exp: "在锋面经过机场时，由于锋面两侧温差较大和移动较快，更容易产生低空风切变，这 种风切变多以水平风的水平和垂直切变为主，对飞行安全构成威胁。因此，要特别注意的是 可能出现高度极低的风切变。" },
  { id: 852, cat: "气象2", q: "在锋面两侧，下面何种气象要素的差异最大？（）", opts: ["风速", "气压", "气温"], ans: 2, exp: "在锋面两侧，气温差异最大。这是因为锋面是冷暖空气交汇的地方，冷暖气团的交界 面导致锋两侧的温度、湿度、稳定度以及风、云、气压等气象要素具有明显差异。 在气团内部，气温水平分布比较均匀，通常在 100 公里内的气温差为 1°C，最多不超过 2°C。 而锋附近区域内，在水平方向上的温度差异非常明显，100 公里的水平距离内可相差近 10°C，比气团内部的温度差异大 5-10 倍。" },
  { id: 853, cat: "气象2", q: "在可见光云图上，下面何种天气系统呈现出螺旋状云系？（）", opts: ["活跃的冷锋", "成熟的气旋", "高空槽"], ans: 1, exp: "在卫星云图上，呈现出螺旋状云系的天气系统是成熟的气旋。这种螺旋状结构明显的 云系通常与温带气旋和台风有关，它们在发展完整的过程中会展现出明显的螺旋云带，这些 云带旋向同一中心。因此，选项“成熟的气旋”是正确的。" },
  { id: 854, cat: "气象2", q: "在实际运用中，通常用气温垂直递减率，单位是（）", opts: ["氏度/1000 米", "摄氏度/500 米", "摄氏度/100 米"], ans: 2, exp: "在实际运用中，气温垂直递减率通常用来描述气温随高度变化的速率，单位是摄氏度 每百米（°C/100m）。这个指标反映了对流层内气温随高度增加而降低的变化情况，是气象 学中一个重要的概念。" },
  { id: 855, cat: "气象2", q: "在卫星云图上，表现为白色、光滑，边缘整齐的云是（）", opts: ["积云群", "中云", "积雨云"], ans: 2, exp: "在卫星云图上，表现为白色、光滑、边缘整齐的云是积雨云。这种云通常具有非常亮 的白色色调，并且云顶光滑，边缘整齐，有时呈现出砧状或马鬃状的特征。这些特征使得积 雨云在卫星云图上非常明显，且容易与其他类型的云区分开来。" },
  { id: 856, cat: "气象2", q: "在卫星云图上，红外云图的色调取决于（）", opts: ["目标反射太阳辐射的大小", "目标的温度", "目标的高低"], ans: 1, exp: "在卫星云图上，红外云图的色调取决于目标的温度。因此，红外云图实际上是一张 温度分布图。由于大气有吸收及物体发射率不完全为 1，卫星接收到的红外辐射要比实际表 面温度发射的黑体辐射要小，所以严格地说，红外云图是一张亮度温度分布图。" },
  { id: 857, cat: "气象2", q: "在卫星云图上，可见光云图的色调取决于（）", opts: ["目标反射太阳辐射的大小", "目标的温度", "目标的高低"], ans: 0, exp: "在卫星云图上，可见光云图的色调取决于目标反射太阳辐射的大小。这是因为可见光 云图是通过气象卫星上的光学相机在可见光谱范围内捕获地球表面和云层的反射光来生成 的。云层和地表的不同物质对太阳光的反射率（albedo）不同，从而形成了不同的亮度。卫 星上的传感器接收这些反射光，并将其转换为图像。因此，卫星接收到的辐射越大，就用越 白的色调表示；而接收到的辐射越小，则用越暗的色调表示。" },
  { id: 858, cat: "气象2", q: "在下述各类飞机积冰中，对飞行影响最大的是（）", opts: ["雾凇和毛冰", "明冰和毛冰", "毛冰和霜"], ans: 1, exp: "飞机积冰对飞行安全有着重大影响，其中明冰和毛冰因其结构坚实和表面粗糙不平，对飞行的影响最大。明冰通常在温度 0~-10°C 含有大的过冷水滴的云中或过冷却雨区中飞行 时形成，呈透明玻璃状，平滑而坚固。毛冰则是在温度为-6～-10°C 的大量过冷水滴、冰晶 和雪花组成的混合云中飞行时产生的，其表面粗糙而不透明，色泽如白瓷，冻结得坚固而不 透明，是最危险和最严重的一种积冰。" },
  { id: 859, cat: "气象2", q: "在夏季暖气团不稳定时，在冷锋的层状云系中可产生（）", opts: ["层状云", "锋面雾", "积雨云"], ans: 2, exp: "在夏季暖气团不稳定时，冷锋的层状云系中可以产生积雨云。这是因为当冷锋移动时，它迫使暖气团迅速抬升，如果暖气团中含有大量水汽，就会凝结成塔状积雨云，这种云常常 伴随着雷暴和降雨。" },
  { id: 860, cat: "气象2", q: "最小能见度是指（）", opts: ["能看到最近的物体距离", "能见度因方向而异时，其中最小的能见距离", "能见度因方向而异时，垂直和水平能见度最小的距离"], ans: 1, exp: "最小能见度是指在能见度因方向而异的情况下，所有方向中能见距离最小的那个值。 能见度是指在一定光照条件下，人眼能清晰地看到的最远距离。由于地形、气候等因素，不 同方向的能见度可能会有所不同。因此，最小能见度是指在所有方向中，能见度最低的那个 方向上的能见距离。" },
  { id: 861, cat: "气象2", q: "锋是三度空间的天气系统。锋的宽度同气团宽度相比显得很狭窄，因而常把锋区 看成 一个几何面，称为锋面。下面描述错误的是：（）", opts: ["锋面与地面的交线称为锋线", "锋面和锋线统称为锋", "凡伸到对流层中上层者，称为层流"], ans: 2, exp: "锋面是气象学中描述两种不同性质气团相遇时形成的边界，这个边界在空间上是一个 面，称为锋面。锋面与地面相交的线称为锋线。锋面和锋线合起来统称为锋。层流锋并不是 一个标准的气象学术语，通常我们不会根据锋伸到对流层中上层来定义锋的类型，因此，该 选项的描述是错误的。" },
  { id: 862, cat: "气象2", q: "如果气象台测得的风向是 270 度，最佳起飞和着陆方向（）", opts: ["从东往西", "从西往东", "都可以"], ans: 0, exp: "风向是指风的来向。如果气象台测得的风向是 270 度，这意味着风是从正西方吹来，吹向正东方。在航空中，为了确保飞行安全和减少燃油消耗，飞机通常会逆风起飞和着陆。 逆风起飞和着陆可以增加升力，缩短滑跑距离，同时降低飞机的速度，减少着陆时的冲击力。 因此，最佳起飞和着陆方向是从东往西。" },
  { id: 863, cat: "气象2", q: "四级风速为多少？（）", opts: ["3.4~5.4m/s", "5.5~7.9m/s", "8.0~10m/s"], ans: 1, exp: "根据风力等级标准，四级风属于和风，风速范围是 5.5~7.9m/s，能吹起地面灰尘和纸 张，小树枝摇动。因此正确答案是 B。" },
  { id: 864, cat: "气象2", q: "大雾天气对飞行活动的有影响错误的是（）", opts: ["手动行时", "自动飞行", "航拍时"], ans: 1, exp: "自动飞行系统依赖仪表导航（如盲降系统、HUD 技术），能通过无线电信号和飞行数 据实现低能见度条件下的起降，受大雾影响最小。" },
  { id: 865, cat: "气象2", q: "北半球由于地球自转偏向力产生的风向？（）", opts: ["自左向右", "自右向左", "不变"], ans: 0, exp: "在北半球，科里奥利力会使风向向右偏转。例如，当气压梯度力使风从高压区向低压 区流动时，科里奥利力会使风向向右偏转。" },
  { id: 866, cat: "气象2", q: "天气预报常用字母“F”表示风力等级，如果“F”两个横杠一样长，问是多少级风？（）", opts: ["二级", "四级", "六级"], ans: 1, exp: "在天气预报中，风力等级通常用蒲福风力等级表（BeaufortScale）来表示。在蒲福风 力等级表中，风力等级的符号“F”用横杠的长度和数量来表示：F4：两个长横杠。 因此，如果“F”有两个横杠且长度一样，这表示风力等级是 F4，即四级风。" },
  { id: 867, cat: "气象2", q: "飞机按气压式高度表指示的一定高度飞行，在飞向低压区时，飞机的实际高度将（）", opts: ["保持不变", "逐渐升高", "逐渐降低"], ans: 2, exp: "当飞机飞向低压区时，由于气压降低，气压式高度表指示的高度会比实际高度高，因 此飞机的实际高度会逐渐降低。 其他选项分析如下： 1.保持不变：错误。飞机的实际高度会随着气压的变化而变化。 2.逐渐升高：错误。当飞机飞向低压区时，实际高度会降低，而不是升高。" },
  { id: 868, cat: "气象2", q: "下面关于山谷风的叙述正确的是（）", opts: ["白天风由山谷吹向山坡", "山谷风是由于海陆差异而形成的热力环流", "气流越山而过，称为山风"], ans: 0, exp: "1.白天风由山谷吹向山坡：正确。白天，山坡受热快，空气上升，形成谷风，即风从山谷吹 向山坡。 2.山谷风是由于海陆差异而形成的热力环流： 错误。山谷风是由于山坡和山谷之间的温度差异而形成的局部热力环流，而不是由于海陆差 异形成的。海陆差异形成的热力环流称为海陆风。 3.气流越山而过，称为山风：错误。山风特指夜晚山坡冷却后冷空气下沉形成的风，而“气流越山而过”通常指过山气流或焚风效应，与山风无关。" },
  { id: 869, cat: "气象2", q: "大气对流运动是由于地球表面受热不均引起的，空气受热膨胀上升，受冷则下沉，进而 产生了强烈而比较有规则的升降运动，温度越高，大气对流运动越明显，因此对流效果最明 显的是（）", opts: ["北半球", "赤道地区", "南半球"], ans: 1, exp: "大气对流运动是由于地球表面受热不均引起的，空气受热膨胀上升，受冷则下沉，进 而产生了强烈而比较有规则的升降运动。温度越高，大气对流运动越明显。因此，对流效果 最明显的是赤道地区，因为赤道地区接受的太阳辐射能量最多，空气对流最为旺盛。" },
  { id: 870, cat: "气象2", q: "地球自转偏向力使得气流向右偏转，因此在北纬 30 度到赤道之间产生了哪个方向的信 风？（）", opts: ["东南方向", "东北方向", "西南方向"], ans: 1, exp: "在北半球，由于地球自转产生的科里奥利力，气流会向右偏转。在北纬 30 度到赤道 之间，气流从北向南流动时，会受到科里奥利力的影响，最终形成东北信风。" },
  { id: 871, cat: "气象2", q: "白天在太阳的辐射作用下沙地，城市地区比水面草地，农村升温快，其上空受热后温度 高于周围空气，因而体积膨胀，密度减小，使浮力大于重力而产生上升运动，这种现象会引 起（）", opts: ["压差作用力", "温差作用力", "热力对流冲击力"], ans: 2, exp: "这种现象是由于地面受热不均导致的热力对流。受热区域的空气上升，形成对流冲击 力。" },
  { id: 872, cat: "气象2", q: "在温暖的天气飞行在较低高度，有时会遇上湍流空气，以下描述正确的是（）", opts: ["很可能在路面和荒地上空发生上升气流", "在类似成片树林的广阔植被区域发生上升气流", "在大片水体区域发生上升气流"], ans: 0, exp: "在温暖的天气下，路面和荒地受日照加热容易形成上升气流，从而导致湍流空气。 其他选项分析如下： 1.在类似成片树林的广阔植被区域发生上升气流：错误。虽然植被区域也会因为地表受热而 产生上升气流，但不如路面和荒地明显。 2.在大片水体区域发生上升气流：错误。水体区域由于水的比热容较大，升温较慢，不容易 形成强烈的上升气流。" },
  { id: 873, cat: "气象2", q: "大气稳定度指整层空气的稳定程度，有时也称大气垂直稳定度以哪种运动来判定？（）", opts: ["以大气的气温垂直加速度运动来", "以大气的气温垂直速度运动来判定", "以大气的气压垂直速度运动来判定"], ans: 0, exp: "大气稳定度是通过观察气块在垂直方向上的运动加速度来判断的。当气块受到外力作 用后，其垂直运动的加速度方向和大小可以反映大气的稳定程度。" },
  { id: 874, cat: "气象2", q: "“露点”这一名词的意义是（）", opts: ["在这个温度下，凝结的水汽与蒸发的水汽相等", "空气一定会降低到这个温度并达到饱和", "水汽开始蒸发的温度"], ans: 0, exp: "露点温度是指空气中的水汽开始凝结成水滴的温度。在这个温度下，空气中的水汽达 到饱和，凝结的水汽与蒸发的水汽达到动态平衡。" },
  { id: 875, cat: "气象2", q: "对于露点温度，以下说法正确的是（）", opts: ["温度升高，露点温度也升高", "相对湿度达到 100%时的温度是露点温度", "露点温度下降，绝对湿度升高"], ans: 1, exp: "露点温度是指在空气中水汽含量和气压都不改变的条件下，冷却到饱和时的温度。当 相对湿度达到 100%时，空气中的水汽已经达到了该温度下的饱和状态，此时的温度就是露 点温度。" },
  { id: 876, cat: "气象2", q: "在大气层结构稳定条件下，由系统性抬升作用形成的为（）", opts: ["层状云", "波状云", "积状云"], ans: 0, exp: "在大气层结稳定条件下，由系统性抬升作用形成的云为层状云。层状云的形成主要与 大规模空气缓慢上升有关。当暖湿空气沿冷空气斜坡缓慢爬升时，因绝热冷却而凝结，最终 形成范围广、厚度大的云层。" },
  { id: 877, cat: "气象2", q: "离开源地移至与原地性质不同的下垫面时，气团的物理属性逐渐发生变化，这个过程 称为气团的变性，一般来说（）", opts: ["冷气团移到暖的地区变性快，而暖的气团移到冷的地区变性慢", "冷气团移到暖的地区变性慢，而暖的气团移到冷的地区变性快", "暖气团移到暖的地区，冷气团移到冷的地区不变性"], ans: 0, exp: "冷气团移到暖的地区时，由于温度差异大，气团的物理属性会迅速变化，变性快。而 暖气团移到冷的地区时，由于温度差异较小，变性相对较慢。" },
  { id: 878, cat: "气象2", q: "在大气层结构不稳定条件下，形成的云为（）", opts: ["层状云", "波状云", "积状云"], ans: 2, exp: "在大气层结不稳定条件下，通常会发生对流运动，形成积状云。积状云是由对流运动 形成的，具有明显的垂直发展特征，如积云、积雨云等。" },
  { id: 879, cat: "气象2", q: "下面哪种情况可能发生引起风向突变的低空风切变？（）", opts: ["在暖锋过后的暖气团中", "在飞行中穿过切变线时", "低空有逆温层"], ans: 2, exp: "逆温层是指在一定高度范围内，气温随高度增加而升高的现象。这种温度结构会阻碍 空气的垂直运动，导致风速和风向在逆温层上下发生显著变化，从而形成风切变。特别是在 逆温层下方，风速较小，而逆温层上方风速较大，这种风速的急剧变化容易引发风切变。" },
  { id: 880, cat: "气象2", q: "引起风切变的地理环境因素（）", opts: ["山地地形多少", "山地地形大小", "其他"], ans: 1, exp: "山地地形的大小对风切变有显著影响。较大的山地地形会形成明显的气流障碍，导致 气流在山体周围和上方发生显著的风速和风向变化，从而引起风变。" },
  { id: 881, cat: "气象2", q: "雷暴在积云阶段所具有的特征（）", opts: ["云中充满上升气流", "频繁的闪电", "升降气流并存"], ans: 0, exp: "在雷暴的积云阶段，云中充满了强烈的上升气流。这些上升气流将暖湿空气带到高空，形成积云，并为雷暴的发展提供动力。" },
  { id: 882, cat: "气象2", q: "飑线风暴简称飑线，它是（）", opts: ["由飑所构成的风切变线", "阵雨和冰雹天气的分界线", "由排列成带状的多个雷暴单体形成的强对流天气带"], ans: 2, exp: "飑线是由多个雷暴单体排列成带状形成的强对流天气带，通常伴随着强烈的雷暴、大 风、冰雹等天气现象。" },
  { id: 883, cat: "气象2", q: "气象部门报告的能见度通常是（）", opts: ["有效能见度", "跑道能见度", "空中能见度"], ans: 0, exp: "有效能见度是指在视野中超过一半范围都能达到的最大水平能见距离，单位为千米。 它是气象观测中的重要指标，用于描述大气透明度和天气状况。" },
  { id: 884, cat: "气象2", q: "在气象和航空上，能见度是指（）", opts: ["目标物的清晰度", "观察者能看清目标物的距离", "观察者能分辨出目标物的最大距离"], ans: 2, exp: "在气象和航空领域，能见度是指视力正常的人能够从背景中清晰识别目标物的最大距 离。这一指标对于飞行安全尤为重要。" },
  { id: 885, cat: "气象2", q: "在飞行中遇到飞机积冰时，驾驶员应注意（）", opts: ["及时有力地修正飞机姿态的偏差，尽快脱离积冰区", "调整飞机马力，严格保持飞行高度和速度，尽快脱离积冰区", "柔和操纵飞机，保持飞行高度和平飞姿态，尽快脱离积冰区"], ans: 2, exp: "在飞机遇到积冰时，驾驶员应该柔和操纵飞机，保持飞行高度和平飞姿态，尽快脱离 积冰区。这是因为积冰会增加飞机的重量和阻力，影响飞行性能，如果驾驶员过于激烈地修 正飞行姿态，可能会导致飞机失速或失控。" },
  { id: 886, cat: "气象2", q: "在处于雷暴区边缘的机场起飞或着陆时，要特别注意的危险天气是（）", opts: ["低空风切变", "冰雹和暴雨", "积冰和雷击"], ans: 0, exp: "雷暴区边缘的机场起飞或着陆时，低空风切变是一个特别需要注意的危险天气现象。 雷暴通常伴随着剧烈的气流变化，尤其是在雷暴的边缘区域，可能会形成微小击暴流或阵风 锋，导致低空风向和风速的突变。" },
  { id: 887, cat: "气象2", q: "在卫星云图上，下列何种天气系统常表现为带状云系？（）", opts: ["槽线", "切变线", "锋面"], ans: 2, exp: "锋面常表现为带状云系，这是因为在锋面附近，冷暖气团相遇，形成明显的云带。 其他选项分析如下： 1.槽线：错误。槽线在卫星云图上通常表现为逗点状或涡旋状云系。 2.切变线：错误。切变线在卫星云图上通常表现为云线或云带，但不如锋面云带明显。" },
  { id: 888, cat: "气象2", q: "在卫星云图上，下面哪个云系常表现为逗点云系？（）", opts: ["高空槽", "切变线", "锋面"], ans: 0, exp: "高空槽是唯一与逗点云系直接对应的天气系统。高空槽是一种沿东西方向延伸的低压 槽，在卫星云图上常伴随逗点云系出现。这种云系反映了高空槽前的暖湿空气上升凝结过程，是识别高空槽的重要标志。" },
  { id: 889, cat: "气象2", q: "重要的天气预报图上，波浪线围出的区域表示（）", opts: ["重要天气区", "雷暴区", "积冰区"], ans: 0, exp: "在重要天气预告图上，波浪线围出的区域表示重要天气区。这种标记用于突出航路上 的关键气象状况，帮助机组人员提前了解并规划应对措施。" },
  { id: 890, cat: "气象2", q: "在红外线云图上，积雨云团的色调表现为（）", opts: ["灰白色", "浅灰色", "浓白色"], ans: 2, exp: "在红外云图上，积雨云团的色调表现为浓白色。 这是因为积雨云顶部温度较低，在红外图像中低温区域显示为白色，而其浓厚的特性进一步 强化了这种表现。" },
  { id: 891, cat: "气象2", q: "在可见光云图上，积雨云团的色调表现为（）", opts: ["灰白色", "浅灰色", "浓白色"], ans: 2, exp: "积雨云在可见光云图上的色调表现为浓白色。这是因为积雨云内部含有大量水汽和水 滴，使得云体显得比较浓密，颜色呈现出浓白色。" },
  { id: 892, cat: "气象2", q: "侧风中着陆带偏侧接地，应该（）", opts: ["向偏侧方向打方向舵，反方向压副翼杆", "向偏侧方向压副翼杆，反方向打方向舵", "向偏侧的方向协调地压副翼杆打方向舵"], ans: 0, exp: "在侧风着陆中，飞机会受到侧风的推动，导致飞机偏离着陆轨迹。为了纠正这种偏离，应该向偏侧方向打方向舵，以保持飞机在正确的着陆轨迹上。同时，为了防止飞机翻滚或侧 翻，需要反方向压住副翼杆，以抵消风对机翼的升力影响。" },
  // ==================== 飞行原理1 ====================
  { id: 893, cat: "飞行原理1", q: "（）下发动机处于小油门状态，或怠速甚至关机", opts: ["俯冲状态", "爬升状态", "滑翔状态"], ans: 2, exp: "在滑翔状态下，飞机主要依靠其自身的势能转换为动能进行飞行，此时发动机通常处 于小油门状态，或怠速甚至关机。滑翔是指飞机在没有发动机推力的情况下，利用其机翼的 升力与重力和阻力相平衡，实现长距离的水平飞行。在这种状态下，飞机的发动机不是必需 的，因此可以减少燃油消耗，延长飞行时间。" },
  { id: 894, cat: "飞行原理1", q: "保持匀速飞行时，阻力与推力（）", opts: ["相等", "阻力大于推力", "阻力小于推力"], ans: 0, exp: "在保持匀速飞行时，阻力与推力是相等的。这是因为在匀速飞行状态下，飞行器所受 的推力与阻力达到了平衡，使得飞行器能够以恒定速度飞行而没有加速度。" },
  { id: 895, cat: "飞行原理1", q: "不稳定运动状态与稳定运动或者静止状态的情况不同之处就是多了（）", opts: ["速度", "加速度", "重力加速度"], ans: 1, exp: "不稳定运动状态与稳定运动或者静止状态的情况不同之处就是多了加速度。 稳定运动状态或静止状态下，物体的速度、加速度等物理量通常是相对稳定的或者为零。而 在不稳定运动状态下，物体的运动状态在不断变化，这意味着物体具有加速度。加速度是描 述物体运动状态变化快慢的物理量，不稳定运动状态下物体的运动状态在不断改变，所以会 有加速度。" },
  { id: 896, cat: "飞行原理1", q: "操纵无人机时，若迎角超过临界迎角，升力系数会（）", opts: ["迅速增大", "迅速减小", "缓慢增大"], ans: 1, exp: "操纵无人机时，若迎角超过临界迎角，升力系数会迅速减小。这是因为在临界迎角之 前，升力系数随迎角增大而增大；当迎角超过临界迎角之后，升力系数就下降了。" },
  { id: 897, cat: "飞行原理1", q: "常规布局的飞机，机翼升力对飞机重心的力矩常为使飞机机头的（）力矩", opts: ["上仰", "下俯", "偏转"], ans: 1, exp: "常规布局的飞机，其机翼通常设计成上反角，即机翼前缘高于后缘。这种设计使得机 翼产生的升力对飞机重心产生一个使飞机机头下俯的力矩。这是因为升力作用点通常位于重 心之前，根据力矩平衡原理，这个力矩会促使飞机机头下俯。" },
  { id: 898, cat: "飞行原理1", q: "常规布局的飞机，平尾升力对飞机重心的力矩常为使飞机机头的（）力矩", opts: ["上仰", "下俯", "偏转"], ans: 0, exp: "常规布局的飞机，平尾升力对飞机重心的力矩常为使飞机机头上仰力矩。这是因为飞 机的平尾通常设计成在产生升力时，对飞机重心产生一个上仰的力矩，以保持飞机的平衡和 稳定。" },
  { id: 899, cat: "飞行原理1", q: "常规布局飞机失速时，（）", opts: ["机翼向上的力和尾翼向下的力都降低", "机翼向上的力和尾翼向下的力都增加", "机翼向上的力和尾翼向下的力恒都为零"], ans: 0, exp: "常规布局的飞机在失速时，机翼上表面的气流紊乱，导致机翼产生的升力（即向上的 力）降低。同时，尾翼主要是通过调整飞机的姿态来保持稳定，在飞机失速状态下，尾翼的 作用也会减弱，其向下的力也会降低。" },
  { id: 900, cat: "飞行原理1", q: "从机尾向机头方向看去，顺时针旋转螺旋桨飞机的扭矩使飞机（）", opts: ["向下低头", "向左滚转", "向上抬头"], ans: 1, exp: "从机尾向机头方向看去，如果螺旋桨顺时针旋转，根据右手定则，螺旋桨产生的扭矩 会使飞机产生一个向左侧滚转的趋势。这是因内螺旋桨旋转产生的反作用力（反扭矩）会使 飞机机身产生相反方向的旋转趋势，即向左侧滚转。" },
  { id: 901, cat: "飞行原理1", q: "当恒定角速度水平转弯时空速增加，转弯半径（）", opts: ["不变", "减少", "增加"], ans: 2, exp: "在恒定角速度水平转弯时，空速的增加会导致转弯半径增加。这是因为在转弯过程中，空速越大，为了保持恒定的角速度，所需的向心力也越大，从而需要更大的转弯半径来提供 足够的向心力，以维持稳定的转弯轨迹。" },
  { id: 902, cat: "飞行原理1", q: "当速度增加而诱导阻力减少时（）", opts: ["形阻减少了", "蒙皮摩阻减少了", "蒙皮摩阻增加了"], ans: 2, exp: "当速度增加而诱导阻力减少时，蒙皮摩阻会增加。这是因为蒙皮摩阻和形阻都直接与 速度的平方成正比。所以，当速度增加时，蒙皮摩阻和形阻会增加，反之亦然。" },
  { id: 903, cat: "飞行原理1", q: "当无人机的迎角为临界迎角时（）", opts: ["飞行速度最大", "升力系数最大", "阻力最小"], ans: 1, exp: "当无人机的迎角达到临界迎角时，升力系数达到最大值。临界迎角是指机翼上表面气 流开始分离的迎角，超过这个迎角后，升力会急剧下降，同时阻力会急剧增加，导致飞机失 速。因此，在临界迎角时，升力系数是最大的。" },
  { id: 904, cat: "飞行原理1", q: "对于带襟翼无人机，放下襟翼，飞机的升力将（），阻力将（）", opts: ["增大、减小", "增大、增大", "减小、减小"], ans: 1, exp: "当无人机放下襟翼时，襟翼会改变机翼的形状，使机翼的弯度增大，从而增加机翼上 下表面的压力差，进而使飞机的升力增大。同时，由于襟翼放下后会扰乱气流，增加空气的 摩擦和紊流，所以阻力也会增大。" },
  { id: 905, cat: "飞行原理1", q: "对于带襟翼的无人机，放下襟翼，飞机的失速速度将（）", opts: ["增大", "减小", "不变"], ans: 1, exp: "放下襟翼会导致飞机的失速速度减小。这是因为襟翼改变了机翼的弯度和迎角，相当 于改变了翼型，使得飞机的最大升力系数增加。由于失速速度与升力系数有关，升力系数的 增加意味着飞机在较低的速度下就能产生足够的升力来维持飞行，因此失速速度会减小。" },
  { id: 906, cat: "飞行原理1", q: "对于下滑中的飞机来说，升力和重力关系是（）", opts: ["L=Wgcosa", "L=Wgsina", "L=Wg"], ans: 0, exp: "对于下滑中的飞机来说，升力（L）和重力（Wg）之间的关系可以用公式 L=Wgcosa 来描述。即升力等于飞机重量乘以迎角的余弦值。这里的 a 是飞机的迎角。" },
  { id: 907, cat: "飞行原理1", q: "舵面遥控状态时，平飞中向后稍拉升降舵杆量，飞行器的迎角（）", opts: ["增大", "减小", "先增大后减小"], ans: 0, exp: "当舵面遥控状态时，平飞中向后稍拉升降舵杆量，飞行器的迎角会增大。这是因为升 降舵的移动会影响飞行器的姿态，特别是俯仰姿态。向后拉动升降舵杆会增加飞行器的迎角，即机翼与水平面的夹角，从而导致升力增加。这一操作是飞行控制中调整飞行器姿态的常用 方法之一。" },
  { id: 908, cat: "飞行原理1", q: "舵面遥控状态时，平飞中向前稍推升降舵杆量，飞行器的迎角（）", opts: ["增大", "减小", "先减小后增大"], ans: 1, exp: "舵面遥控状态时，平飞中向前稍推升降舵杆量，会导致飞机的迎角减小。这是因为升 降舵的前推会导致飞机的尾部向下移动，从而产生一个低头力矩，使得飞机的迎角减小。这 种操作通常用于减小飞机的迎角，以调整飞机的飞行姿态。" },
  { id: 909, cat: "飞行原理1", q: "舵面遥控状态时，平飞中向右稍压副翼杆量，无人机（）", opts: ["右翼升力大于左翼升力", "左翼升力大于右翼升力", "左翼升力等于右翼升力"], ans: 1, exp: "在舵面遥控状态下，平飞中向右稍压副翼杆量，会导致无人机的右翼副翼向下偏转，左翼副翼向上偏转。这种偏转会使得右翼的升力减小，左翼的升力增加，从而使无人机向右 侧倾斜。因此，左翼升力大于右翼升力。" },
  { id: 910, cat: "飞行原理1", q: "放全襟翼下降，无人机能以（）", opts: ["较大的下降角，较小的速度下降", "较小的下降角，较大的速度下降", "较大的下降角，较大的速度下降"], ans: 0, exp: "放全襟翼下降时，无人机能以较大的下降角，较小的速度下降。这是因为襟翼的放下 增加了机翼的面积弯度，从而增加了升力，使得无人机可以在较小的速度下保持稳定的下降 轨迹，同时较大的下降角有助于控制下降路径。" },
  { id: 911, cat: "飞行原理1", q: "飞机从已建立的平衡状态发生偏离，若（），则飞机表现出负动安定性", opts: ["飞机振荡的振幅减小使飞机回到原来的平衡状态", "飞机振荡的振幅持续增大", "飞机振荡的振幅不增大也不减小"], ans: 1, exp: "当飞机从已建立的平衡状态发生偏离时，如果飞机振荡的振幅持续增大，则飞机表现 出负动安定性，这意味着飞机不会自动回到原来的平衡状态，而是会持续偏离并加剧。" },
  { id: 912, cat: "飞行原理1", q: "飞机从已建立的平衡状态发生偏离，若（），则飞机表现出正动安定性", opts: ["飞机振荡的振幅减小使飞机回到原来的平衡状态", "飞机振荡的振幅持续增大", "飞机振荡的振幅不增大也不减小"], ans: 0, exp: "飞机的稳定性是指飞机反抗外界扰动、保持原有飞行状态的能力。当飞机从已建立的 平衡状态发生偏离时，如果飞机表现出正动安定性，那么飞机会自然地倾向于返回其原始平 衡位置。具体来说，正动安定性意味着飞机在受到干扰后，会通过自身的气动特性和结构设 计，使得飞机的振荡振幅逐渐减小，最终使飞机回到原来的平衡状态。" },
  { id: 913, cat: "飞行原理1", q: "飞机的方向安定性过强，而横侧安定性相对过弱，飞机容易出现（）", opts: ["飘摆（荷兰滚）", "螺旋不稳定", "转弯困难"], ans: 1, exp: "飞机的方向安定性过强意味着飞机在受到扰动后，飞机的偏航稳定性过高，而横侧安 定性相对过弱则意味着飞机在受到滚转和偏航扰动后，恢复到平衡状态的能力不足。这种情 况下，飞机容易出现螺旋不稳定现象，即飞机在受到扰动后，无法有效恢复到原来的飞行状 态，而是进入一个不稳定的螺旋下降状态，这种现象在飞行中是非常危险的。" },
  { id: 914, cat: "飞行原理1", q: "飞机的横侧安定性过强，而方向安定性相对过弱，飞机容易出现（）", opts: ["飘摆（荷兰滚）", "螺旋不稳定现象", "失去纵向安定性"], ans: 0, exp: "飞机的横侧安定性过强，而方向安定性相对过弱时，飞机容易出现飘摆（荷兰滚）现 象。荷兰滚是一种飞行器在横侧方向上产生的耦合运动，表现为偏航（Yaw）和滚转（Roll）的周期性振荡。它是由飞行器侧向稳定性和滚转稳定性共同作用的结果，表现为偏航角和滚 转角的交替变化。" },
  { id: 915, cat: "飞行原理1", q: "飞机横侧安定性有助于（）", opts: ["使机翼恢复到水平状态", "使飞机保持航向", "使飞机保持迎角"], ans: 0, exp: "飞机的横侧安定性主要作用是当飞机受到侧风等扰动而发生滚转偏离时，能够产生恢 复力矩，使机翼恢复到水平状态。飞机保持航向主要是靠方向安定性；保持迎角主要与飞机 的俯仰安定性及操纵有关。" },
  { id: 916, cat: "飞行原理1", q: "飞机的理论升限（）实用升限", opts: ["等于", "大于", "小于"], ans: 1, exp: "理论升限是在理想的大气条件下，飞机能够上升的最大高度。而实用升限是飞机在实 际飞行中能够使用的最大高度，由于实际飞行中会受到各种因素的影响，比如发动机性能下 降、空气密度变化等，所以实用升限要低于理论升限。" },
  { id: 917, cat: "飞行原理1", q: "飞机的下滑角是（）", opts: ["升力与阻力的夹角", "飞行轨迹与水平面的夹角", "阻力与重力的夹角"], ans: 1, exp: "飞机的下滑角是指飞机在下降过程中，其飞行轨迹与水平面的夹角。这个角度是描述 飞机下降路径陡峭程度的重要参数，对于飞机的着陆和下滑阶段至关重要。下滑角的大小直 接影响飞机的下降速度和下降距离，是飞行员在进行下滑操作时需要精确控制的参数。" },
  { id: 918, cat: "飞行原理1", q: "飞机的压力中心是（）", opts: ["压力最低的点", "压力最高的点", "升力的着力点"], ans: 2, exp: "飞机的压力中心是指升力的着力点，也称为升力作用点。这个点是飞机升力作用的中 心位置，是飞机气动力和力矩计算的重要参考点。压力中心的位置对于飞机的稳定性和操控 性有重要影响。" },
  { id: 919, cat: "飞行原理1", q: "飞机的迎角是（）", opts: ["飞机纵轴与水平面的夹角", "飞机翼弦与水平面的夹角", "飞机翼弦与相对气流的夹角"], ans: 2, exp: "飞机的迎角是指飞机翼弦与相对气流方向之间的夹角。它是衡量飞机在飞行过程中气 流对机翼的作用角度，直接影响升力和阻力的大小。" },
  { id: 920, cat: "飞行原理1", q: "飞机的纵向安定性有利于（）", opts: ["防止飞机绕立轴偏转过快", "防止飞机绕纵轴滚转过快", "防止飞机抬头过高或低头过低"], ans: 2, exp: "飞机的纵向安定性是指飞机在受到扰动后绕横轴保持稳定的趋势。具体来说，当飞机 因为某种扰动而偏离原来的纵向平衡状态时，飞机能够自动产生抑制这种扰动的能力，使飞 机恢复到原来的飞行姿态。这种稳定性有助于保持飞机的迎角不变，从而维持飞机的纵向平 衡。因此，飞机的纵向安定性有利于防止飞机抬头过高或低头过低，保持飞机在纵向上的稳 定性。" },
  { id: 921, cat: "飞行原理1", q: "飞机发生螺旋后，最常规的制止方法是（）", opts: ["立即推杆到底改出失速", "立即向螺旋反方向打舵到底制止滚转", "立即加大油门增速"], ans: 1, exp: "飞机发生螺旋（也称为螺旋下降或螺旋不稳定）后，最常规的制止方法是立即向螺旋 反方向打舵到底制止滚转。这是因为在螺旋不稳定中，飞机会进入一个持续的、通常是急剧 的下降螺旋路径，伴随着高度的快速丧失和姿态的失控。向螺旋反方向打舵可以帮助飞机恢 复水平飞行姿态，从而制止螺旋。" },
  { id: 922, cat: "飞行原理1", q: "飞机发生螺旋现象的原因是（）", opts: ["飞行员方向舵操纵不当", "飞行员压杆过多", "飞机失速后机翼自转"], ans: 2, exp: "飞机发生螺旋现象的原因通常是飞机失速后机翼自转。螺旋现象是一种特殊的飞行不 稳定状态，通常发生在飞机失速后，由于机翼失去升力，飞机进入一种旋转下坠的状态。这 种现象是危险的，因为它可能导致飞机失控并迅速失去高度。" },
  { id: 923, cat: "飞行原理1", q: "飞机平飞遇垂直向上突风作用时（）", opts: ["阻力将增大", "升力将增大", "升力将减小"], ans: 1, exp: "当飞机在平飞中遇到垂直向上的突风时，飞机的升力会增加。这是因为风给飞机带来 了额外的向上速度分量，导致攻角（飞机与相对风之间的角度）增加，从而增加了机翼产生 的升力。" },
  { id: 924, cat: "飞行原理1", q: "飞机坡度增大，升力的垂直分量（）", opts: ["增大", "减小", "保持不变"], ans: 1, exp: "飞机的坡度是指飞机绕纵轴（即飞机的立轴）旋转的角度，它描述了飞机的侧倾状态。 当飞机的坡度增大时，飞机的升力垂直分量会减小。这是因为飞机的升力是垂直于机翼的，而坡度的增加导致升力的方向相对于水平面发生倾斜，因此升力的垂直分量（即直接抵消重 力的部分）会减少，而水平分量（即导致飞机侧滑的部分）会增加。" },
  { id: 925, cat: "飞行原理1", q: "飞机坡度增大，升力的水平分量（）", opts: ["增大", "减小", "保持不变"], ans: 0, exp: "飞机坡度增大时，飞机的飞行轨迹与水平面形成的角度增加，导致升力的方向相对于 水平面发生倾斜。在这种情况下，升力的水平分量（即与飞机前进方向相同的分量）会增大，因为飞机需要一个水平向内的力来维持圆周运动，这个力就是升力的水平分量提供的向心力。 因此，飞机坡度增大，升力的水平分量增大。" },
  { id: 926, cat: "飞行原理1", q: "飞机上升时，其迎角（）", opts: ["大于零", "小于零", "等于零"], ans: 0, exp: "飞机上升时，其迎角大于零。迎角是指飞机机翼弦线与相对风向之间的夹角。在上升 过程中，飞机需要增加升力以克服重力，因此迎角必须大于零以产生足够的升力。" },
  { id: 927, cat: "飞行原理1", q: "飞机失速的原因是（）", opts: ["飞机速度太小", "飞机速度太大", "飞机迎角超过临界迎角"], ans: 2, exp: "飞机失速的原因主要是飞机迎角超过临界迎角。当飞机的迎角增加到一定程度，即超 过失速临界迎角时，机翼上表面的气流会开始分离，导致升力急剧下降，飞机无法维持正常 飞行所需的升力，从而进入失速状态。" },
  { id: 928, cat: "飞行原理1", q: "飞机水平转弯，坡度增大，失速速度（）", opts: ["减小", "保持不变，因为临界迎角不变", "增大"], ans: 2, exp: "飞机的水平转弯或盘旋会导致飞机的坡度增大，这会影响飞机的迎角和升力。根据空 气动力学原理，当飞机的坡度增大时，飞机的升力会倾斜，升力的一个分力起向心力作用，使飞机作圆周运动。为了保持盘旋中的飞行高度不变，必须用推速度或拉杆增加迎角的方法 增加升力。因此，飞机的水平转弯或盘旋会导致失速速度增大，因为需要更大的速度来维持 所需的升力。" },
  { id: 929, cat: "飞行原理1", q: "飞机下降时，其迎角（）", opts: ["大于零", "小于零", "等于零"], ans: 0, exp: "飞机下降时，其迎角大于零。这是因为在下降过程中，飞机需要维持一定的升力以对 抗重力，保持飞机的稳定下降，而不是自由落体。迎角是飞机机翼弦线与相对气流方向之间 的夹角，为了产生足够的升力，迎角必须大于零。" },
  { id: 930, cat: "飞行原理1", q: "飞机以一定地速逆风起飞时（）", opts: ["滑跑距离将减小", "滑跑距离将增大", "滑跑距离将不变"], ans: 0, exp: "飞机逆风起飞时，风速与飞机相对空气的速度（空速）相加，使得飞机获得更大的升 力。由于升力的增加，飞机可以在更短的时间内达到起飞所需的升力，从而减少了飞机起飞 所需的滑跑距离。因此，逆风起飞有助于飞机更短距离内起飞，提高了起飞效率。" },
  { id: 931, cat: "飞行原理1", q: "飞机迎角减小，压力中心的位置会（）", opts: ["前移", "后移", "保持不变"], ans: 1, exp: "飞机迎角减小意味着飞机相对于来流的角度变小，这会导致飞机机翼上产生的升力减 小。随着迎角的减小，机翼上的压力分布也会发生变化，压力中心会相对后移。" },
  { id: 932, cat: "飞行原理1", q: "飞机迎角增大，压力中心位置会（）", opts: ["前移", "后移", "保持不变"], ans: 0, exp: "飞机的迎角增大时，压力中心的位置会前移。这是因为压力中心是翼面分布压力的合 力点，当迎角增大时，上翼面的吸力和下翼面的压力都增强，且吸力峰前移，导致压力中心 前移。因此，飞机迎角增大，压力中心的位置会前移。" },
  { id: 933, cat: "飞行原理1", q: "飞机在地面效应区时，引起的气动力变化是（）", opts: ["升力增大、阻力减小", "升力减小、阻力增大", "升力增大、阻力增大"], ans: 0, exp: "飞机在地面效应区时，引起的气动力变化是升力增大、阻力减小。这是因为当飞机接 近地面时，地面的存在限制了机翼下方的气流向下流动，从而减少了下洗的程度。这种变化 导致升力增加而阻力减少。" },
  { id: 934, cat: "飞行原理1", q: "飞机着陆进入地面效应区时，将（）", opts: ["出现短暂的机头上仰变化", "经历诱导阻力减小的过程，需要减小动力", "需要增大迎角以保持相同的升力系数"], ans: 1, exp: "飞机在着陆进入地面效应区时，由于地面效应的影响，飞机的气动特性会发生显著变 化。地面效应导致飞机升力增大、阻力减小及静安定度提高等。具体来说，地面效应使得飞 机的诱导阻力减小，这是因为地面阻碍使下洗流减小，从而使飞机的升力陡然增加。因此，飞机在进入地面效应区时，会经历诱导阻力减小的过程，需要减小动力以维持稳定的下降。" },
  { id: 935, cat: "飞行原理1", q: "飞机转弯的向心力是（）", opts: ["飞机的拉力", "方向舵上产生的气动力", "飞机升力的水平分力"], ans: 2, exp: "飞机转弯时，需要一个向心力来保持飞机沿圆周路径飞行。这个向心力是由飞机升力 的水平分量提供的。当飞机倾斜飞行时，升力不再垂直于地面，而是有一个水平分量，这个 水平分量就提供了飞机转弯所需的向心力。" },
  { id: 936, cat: "飞行原理1", q: "飞机转弯时，坡度有继续增大的倾向，原因是（）", opts: ["转弯外侧阻力比内侧的大", "转弯外侧升力比内侧的大", "转弯外侧阻力比内侧的小"], ans: 1, exp: "飞机转弯时，如果坡度有继续增大的倾向，原因是转弯外侧升力比内侧的大。在转弯 过程中，飞机的机翼会产生一个向转弯圆心方向的升力分量，这个分量提供了转弯所需的向 心力。由于转弯外侧的机翼迎角更大，因此产生的升力也更大，导致飞机有向外侧翻滚的趋 势，从而使坡度增大。" },
  { id: 937, cat: "飞行原理1", q: "飞机转弯时，为保持高度需要增大迎角，原因是（）", opts: ["保持升力垂直分量不变", "用以使机头沿转弯方向转动", "保持升力水平分量不变"], ans: 0, exp: "飞机在转弯时，为了保持飞行高度，需要增大迎角。这是因为在转弯过程中，飞机需 要额外的向心力来维持圆周运动，而这个向心力是由升力的水平分量提供的。为了产生足够 的向心力，飞机必须增加迎角，从而增加升力的水平分量，以保持飞行高度不变。因此，增 大迎角是为了保持升力的垂直分量不变，即保持飞机的高度。" },
  { id: 938, cat: "飞行原理1", q: "飞行中发现飞机非指令的时而左滚、时而右滚，同时伴随机头时而左偏、时而右偏的现 象，此迹象表明（）", opts: ["飞机进入了飘摆（荷兰滚）", "飞机进入了失速", "飞机进入了螺旋"], ans: 0, exp: "当飞机出现非指令的时而左滚、时而右滚，同时伴随机头时而左偏、时而右偏的现象 时，这是典型的荷兰滚（飘摆）表现。荷兰滚是由于飞机的横滚稳定性和航向稳定性不协调 引起的一种复合摆动现象。就好像飞机在左右摇晃和左右摆动头部一样。" },
  { id: 939, cat: "飞行原理1", q: "根据机翼的设计特点，其产生的升力来自（）", opts: ["机翼上下表面的正压强", "机翼下表面的负压和上表面的正压", "机翼下表面的正压和上表面的负压"], ans: 2, exp: "根据机翼的设计特点，其产生的升力来自机翼下表面的正压和上表面的负压。这是由 于机翼的上表面通常比下表面长，导致空气在上表面流速更快，压力更低（负压），而下表 面的流速较慢，压力较高（正压）。这种压力差产生了升力，使飞机得以在空中飞行。" },
  { id: 940, cat: "飞行原理1", q: "公式 L=Wg，（）", opts: ["适用于飞行器下滑过程", "适用于飞行器爬升过程", "都不适用"], ans: 2, exp: "公式 L=Wg 中，L 代表升力，W 代表重力，g 是重力加速度。一般情况下，升力和重力 之间的关系并不是简单的 L=Wg。在飞行器下滑过程中，升力小于重力但不是这种简单关系； 在飞行器爬升过程中，升力大于重力也不是这种关系，所以这个公式在两种情况下都不适用。" },
  { id: 941, cat: "飞行原理1", q: "保持匀速上升时，升力与重力（）", opts: ["相等", "升力小于重力", "升力大于重力"], ans: 0, exp: "在匀速上升过程中，飞机的垂直加速度为零，这意味着升力和重力在垂直方向上是平 衡的。因此，升力等于重力，以确保飞机能够保持稳定的上升状态，既不会加速上升也不会 减速下降。" },
  { id: 942, cat: "飞行原理1", q: "固定翼常规无人机飞行辅助操纵面有（）", opts: ["副翼、升降舵、方向舵、调整片", "缝翼、襟翼、调整片、全动平尾", "缝翼、襟翼、调整片"], ans: 2, exp: "固定翼常规无人机的飞行辅助操纵面主要包括襟翼、调整片等。襟翼主要用于增加升 力和控制阻力，而调整片则用于辅助操纵面的运动，以改善飞机的操纵性能。这些操纵面的 设计和使用对于无人机的飞行性能至关重要，它们共同作用以实现飞机的稳定飞行和精确操 控。" },
  { id: 943, cat: "飞行原理1", q: "固定翼常规无人机飞行操纵面有（）", opts: ["副翼、升降舵、方向舵、调整片", "副翼、升降舵（或全动平尾）、方向舵", "副翼"], ans: 1, exp: "固定翼常规无人机的主要操纵面包括副翼、升降舵（或全动平尾）、方向舵。副翼用 于控制飞机的滚转运动，升降舵（或全动平尾）用于控制飞机的俯仰运动，方向舵用于控制 飞机的偏航运动。这些操纵面共同作用，使飞行员能够操纵飞机实现各种飞行姿态和动作。" },
  { id: 944, cat: "飞行原理1", q: "关于垂直起飞和着陆回收以下错误的是（）", opts: ["垂直起降是旋翼无人机的主流发射", "部分特种固定翼无人机也可采用垂直方式发射和回收", "垂直起降的固定翼无人机均安装有专用的辅助动力系统"], ans: 2, exp: "垂直起降固定翼无人机中，并非所有机型都安装有专用的辅助动力系统。有些垂直起 降固定翼无人机的设计可以通过旋转机翼或倾转动力等方式实现垂直起降，而不需要额外的 辅助动力系统。因此，选项“垂直起降的固定翼无人机均安装有专用的辅助动力系统”是错 误的。" },
  { id: 945, cat: "飞行原理1", q: "关于拦截网或“天钩”回收，以下正确的是（）", opts: ["拦截网系统通常由拦截网、能量吸收装置组成", "用拦截网系统回收无人机是目前世界中型无人机较普遍采用的回收方式 之一", "能量吸收装置与拦截网相连，其作用是吸收无人机撞网的能量，免得无＜人机触网后在网 上弹跳不停，以致损伤"], ans: 2, exp: "能量吸收装置与拦截网相连，其作用是吸收无人机撞网时的能量，防止无人机触网后 在网上弹跳不停，从而避免损伤。 其他选项分析如下： 1.用拦截网系统回收无人机是目前世界中型无人机较普遍采用的回收方式之一错误，因为拦 截网回收主要用于小型无人机，而非中型无人机。 2.拦截网系统通常由拦截网、能量吸收装置组成-错误，拦截网系统通常由拦截网、能量吸 收装置和支撑结构组成，缺少“支撑结构”这一关键部分。" },
  { id: 946, cat: "飞行原理1", q: "关于平凸翼型的剖面形状，下面说法正确的是（）", opts: ["上下翼面的弯度相同", "机翼上表面的弯度小于下表面的弯度", "机翼上表面的弯度大于下表面的弯度"], ans: 2, exp: "平凸翼型是一种常见的翼型设计，其特点是机翼上表面的弯度大于下表面的弯度。这 种设计有助于在上表面产生更快的气流速度，从而根据伯努利原理（流速增加，压力降低）产生更大的升力。因此，选项“机翼上表面的弯度大于下表面的弯度”是正确的。" },
  { id: 947, cat: "飞行原理1", q: "关于伞降回收以下正确的是（）", opts: ["回收伞均由主伞、减速伞和阻力伞三级伞组成", "当无人机完成任务后，地面站发遥控指令给无人机或由无人机自主执行，使无人机减速，降高及发动机停车", "无人机悬挂在主伞下慢慢着陆，机下触地开关接通，使主伞收回无人机内，这是对降落伞 回收过程最简单的描述"], ans: 1, exp: "伞降回收是无人机常用的回收方式之一，它具有可靠性高、回收场地适应性强等特点。 在无人机完成任务后，地面站会发出遥控指令给无人机，使无人机减速、降高及发动机停车。 无人机进入地面效应区后，会经历一个减速和降高的过程，最终在合适的高度和速度下打开 降落伞，实现安全着陆。" },
  { id: 948, cat: "飞行原理1", q: "国际标准大气的定义是什么？（）", opts: ["海平面附近常温常压下空气的密度", "对流层附近常温常压下空气的密度", "地表层附近常温常压下空气的密度"], ans: 0, exp: "国际标准大气（ISA，International Standard Atmosphere EIRATE 附近，假定温度、压力等参数为固定标准值的大气状态。这个标准主要用于航空、航天、气象等领域，以便于 比较和计算。国际标准大气定义了海平面的压力为 1013.25 百帕，温度为 15°C（或 288.15 开尔文）。" },
  { id: 949, cat: "飞行原理1", q: "仅偏转副翼使飞机水平左转弯时，出现（）", opts: ["无侧滑", "左侧滑", "右侧滑"], ans: 1, exp: "仅偏转副翼进行左转弯时，飞机的机翼倾斜，导致飞机产生向左的侧滑。这是因为偏 转副翼改变了机翼的升力分布，使飞机产生倾斜，进而导致侧滑。" },
  { id: 950, cat: "飞行原理1", q: "具有负静安定性的飞机，当受到扰动使平衡状态变化后，有（）", opts: ["回到原平衡状态的趋势", "继续偏离原平衡状态的趋势", "保持偏离后的平衡状态的趋势"], ans: 1, exp: "具有负静安定性的飞机，当受到扰动使平衡状态变化后，会继续偏离原平衡状态的趋 势。这是因为负静安定性意味着飞机受外界扰动使其改变当前飞行状态时，飞机将继续偏离 当前状态的性质。因此，正确答案是 B、继续偏离原平衡状态的趋势。" },
  { id: 951, cat: "飞行原理1", q: "具有正静安定性的飞机，当受到扰动使平衡状态变化后，有（）", opts: ["回到原平衡状态的趋势", "继续偏离原平衡状态的趋势", "保持偏离后的平衡状态"], ans: 0, exp: "具有正静安定性的飞机意味着飞机在受到扰动后，飞机的自身稳定性会使其产生回到 原平衡状态的趋势。静安定性是飞机稳定性的一个重要方面，它描述了飞机在受到扰动后，没有飞行员输入的情况下，飞机自身恢复到原来平衡状态的能力。" },
  { id: 952, cat: "飞行原理1", q: "具有纵向安定性的飞机，飞机重心（）", opts: ["位于压力中心前", "位于压力中心后", "与压力中心重合"], ans: 0, exp: "具有纵向安定性的飞机，其飞机重心必须位于压力中心之前。这是因为飞机的纵向安 定性是由飞机的重心位置相对于压力中心（气动中心）的位置决定的。当飞机的重心位于压 力中心之前时，飞机在受到扰动后，会产生一个恢复到原来迎角的趋势，即飞机具有纵向安 定性。这种布局有助于飞机在飞行中保持稳定，减少因外界扰动引起的不稳定现象。" },
  { id: 953, cat: "飞行原理1", q: "空气动力学概念中，空气的物理性质主要包括（）", opts: ["空气的粘性", "空气的压缩性", "空气的粘性和压缩性"], ans: 2, exp: "空气动力学是研究空气与物体相对运动时作用力的学科。在空气动力学的概念中，空 气的物理性质主要包括空气的粘性和压缩性。空气的粘性影响边界层的形成和流动分离，而 空气的压缩性则影响高速流动中的压力波传播和激波的形成。这两个性质共同决定了空气流 动的特性和飞行器的气动性能。" },
  { id: 954, cat: "飞行原理1", q: "空速适度减小时，为保持高度，应实施的操纵是（）", opts: ["增大迎角，使升力的增加大于阻力的增加", "增大迎角，以保持升力不变", "减小迎角，以保持阻力不变"], ans: 1, exp: "当空速适度减小时，为了保持飞行高度，飞行员需要调整飞机的迎角。根据空气动力 学原理，升力与迎角成正比，而阻力与迎角和速度的平方成正比。因此，当空速减小时，为 了保持升力不变以维持高度，飞行员需要增大迎角，以补偿速度减小带来的升力下降。这一 操作可以确保飞机在空速降低时仍能保持原有的高度。" },
  { id: 955, cat: "飞行原理1", q: "流体的粘性系数与温度之间的关系是（）", opts: ["液体的粘性系数随温度的升高而增大", "气体的粘性系数随温度的升高而增大", "液体的粘性系数与温度无关"], ans: 1, exp: "在空气动力学中，流体的粘性与温度之间存在特定的关系。对于气体而言，随着温度 的升高，分子热运动加剧，动量交换增大，导致气体的粘性增大。而对于液体，温度升高时，分子间距离增大，分子间引力减小，导致液体的动力粘度减小，粘性力减小。" },
  { id: 956, cat: "飞行原理1", q: "偏转副翼使飞机右转弯时，为修正逆偏转的影响，应（）", opts: ["向左偏转方向舵", "向右偏转方向舵", "向左压杆"], ans: 1, exp: "在飞机进行转弯时，由于偏转副翼会产生一个逆偏转的趋势，即飞机会倾向于向相反 的方向偏转。为了修正这种逆偏转的影响，飞行员需要采取相应的操纵措施。在这种情况下，正确的操作是向右偏转方向舵，以抵消逆偏转的影响，帮助飞机保持正确的转弯方向。" },
  { id: 957, cat: "飞行原理1", q: "偏转副翼使飞机转弯时，两翼的阻力是（）", opts: ["内侧机翼阻力大", "外侧机翼阻力大", "相等"], ans: 1, exp: "当飞机转弯时，偏转副翼会导致飞机的外侧机翼相对于空气的速度增加，而内侧机翼 的速度减少。由于阻力与速度的平方成正比，因此外侧机翼的阻力会大于内侧机翼的阻力。" },
  { id: 958, cat: "飞行原理1", q: "偏转副翼使飞机左转弯时，为修正逆偏转的影响，应（）", opts: ["向左偏转方向舵", "向右偏转方向舵", "向右压杆"], ans: 0, exp: "在飞机左转弯时，如果只偏转副翼而不进行其他操作，飞机会受到逆偏转（AdverseYaw）的影响，即飞机会倾向于向转弯的相反方向（右侧）偏航。为了修正这种影响，飞行员需要 向左偏转方向舵，以产生一个向左的偏航力矩，从而抵消逆偏转的影响，保持飞机的协调转 弯。" },
  { id: 959, cat: "飞行原理1", q: "如飞机出现失速，飞行员应（）", opts: ["立即蹬舵", "立即推杆到底", "立即拉杆"], ans: 1, exp: "当飞机出现失速时，飞行员应立即采取措施以恢复飞机的升力并避免进一步的危险。 正确的操作是向前推杆到底以减小迎角，从而恢复升力。这一操作有助于打破失速状态，使 飞机从失速中恢复出来。同时，飞行员可以增加发动机推力以增加飞机的速度，帮助飞机恢 复正常飞行。" },
  { id: 960, cat: "飞行原理1", q: "如果对称机翼相对来说仰头旋转了一个仰角，驻点（）", opts: ["稍稍向前缘的上表面移动", "稍稍向前缘的下表面移动", "不会移动"], ans: 1, exp: "在空气动力学中，当对称机翼相对来流仰头旋转了一个迎角时，驻点会稍稍向前缘的 下表面移动。这是因为迎角的改变导致流经上下表面的空气流动情况发生变化，流经上表面 的空气被迫多走了一段距离，使得下表面的最高速度要小于上表面的最高速度，从而产生压 力差，形成升力。" },
  { id: 961, cat: "飞行原理1", q: "升力系数 1.3（CL=1.3）和升力系数 1.0（CL=1.0），（）", opts: ["前者产生更大升力", "后者产生更大升力", "产生升力相等"], ans: 0, exp: "升力系数是一个描述机翼或整个带翼飞行器在流体中产生升力能力的无量纲系数，它 将升力与流体密度、流体速度和相关参考面积联系起来。升力系数越大，表示在相同条件下 产生的升力越大。因此，升力系数 1.3 比升力系数 1.0 产生的升力更大，因为升力系数直接 与升力成正比。" },
  { id: 962, cat: "飞行原理1", q: "失速的直接原因是（）", opts: ["低速飞行", "高速飞行", "迎角过大"], ans: 2, exp: "失速的直接原因是迎角过大。当飞机的迎角超过临界迎角时，机翼上表面的气流会开 始分离，导致升力急剧下降，飞机无法维持正常的飞行速度和升力，从而进入失速状态。" },
  { id: 963, cat: "飞行原理1", q: "使飞机获得最大下滑距离的速度是（）", opts: ["最大下滑速度", "失速速度", "下滑有利速度"], ans: 2, exp: "下滑有利速度是能使飞机获得最大下滑距离的速度。在这个速度下，飞机的升阻比最 大，能够在下滑过程中飞行更远的距离。最大下滑速度可能会导致飞机下降过快，而失速速 度会使飞机处于危险的失速状态，都不能获得最大下滑距离。" },
  { id: 964, cat: "飞行原理1", q: "通过改变迎角，无人机驾驶员可以控制飞机的（）", opts: ["升力、空速、阻力", "升力、空速、阻力、重量", "升力、拉力、阻力"], ans: 0, exp: "通过改变迎角，无人机驾驶员可以控制飞机的升力、空速和阻力。 迎角是指机翼弦线与相对风向之间的夹角，它直接影响升力的产生。增加迎角会增加升力，但超过临界迎角后会导致失速。迎角也会影响阻力，因为较大的迎角会增加形式阻力。空速 是飞机相对于空气的速度，虽然迎角的改变不会直接改变空速，但会影响飞机的动力和性能，从而间接影响空速，……" },
  { id: 965, cat: "飞行原理1", q: "通过一个收缩管道的流体，在管道的收缩区，速度的增加必然造成收缩区压力（）", opts: ["增加", "减少", "不变"], ans: 1, exp: "根据伯努利原理，在流体流动过程中，当流体通过收缩管道时，流速增加会导致压力 降低。这是因为流体的总能量（包括动能和压力能）守恒，动能增加必然导致压力能减少。 因此，在管道的收缩区，速度的增加必然造成收缩区压力减少。" },
  { id: 966, cat: "飞行原理1", q: "外侧滑转弯是由于离心力比升力的水平分量还大，把飞机向转弯的外侧拉。下列说法错 误的是（）", opts: ["外侧滑转弯可以通过增加倾斜角修正", "为维持一个给定的角速度，倾斜角必须随离心力变化", "在高速飞机上对侧滑进行修正非常重要"], ans: 1, exp: "1.外侧滑转弯时可以通过增加倾斜角来修正这种向外侧拉的情况，增加倾斜角可以调整升力 方向，从而改善外侧滑状态。该说法正确。 2.为维持一个给定的角速度，倾斜角并非随离心力变化，因为倾斜角主要是根据转弯需求和 飞机的飞行状态来调整，而不是单纯随离心力变化。该说法错误。 3.在高速飞机上，外侧滑转弯带来的影响可能更大，所以对侧滑进行修正非常重要。该说法 正确。" },
  { id: 967, cat: "飞行原理1", q: "无人机的发射方式可归纳为手抛发射、零长发射、弹射发射、起落架滑跑起飞、母机空 中发射、容器式发射、装置发射和垂直起飞等类型。下列说法正确的是（）", opts: ["在地面发射时，无人机使用较为广泛的发射方式是母机空中发射与零长发射", "无人机安装在轨道式发射装置上，在压缩空气、橡筋或液压等弹射装置作用下起飞，无人 机飞离发射装置后，在辅助发动机作用下完成飞行任务", "容器式发射装置是一种封闭式发射装置，兼备发射与贮存无人机功能"], ans: 2, exp: "容器式发射装置是一种封闭式发射装置，兼备发射与贮存无人机的功能。它有单室式和多室 式两种类型。这种发射方式常用于发射轻型无人机，或用于军舰和潜艇上发射无人机。" },
  { id: 968, cat: "飞行原理1", q: "无人机的回收方式可归纳为伞降回收、空中回收、起落架轮式着陆、拦阻网回收、气垫 着陆和垂直着陆等类型。下列说法错误的是（）", opts: ["空中回收，在大飞机上必须有空中回收系统，在无人机上除了有阻力伞和主伞之外，还需 有钩挂伞、吊索和可旋转的脱落机构", "起落架轮式着陆，多数无人机的起落架局部被设计成较坚固，局部较脆弱", "用拦截网系统回收无人机是目前世界小型无人机采用的回收方式之一"], ans: 1, exp: "1.空中回收需要在大飞机和无人机上配备特定的回收系统，解释合理。因此该选项说法正确。 2.多数无人机的起落架通常是整体设计得较为坚固，以确保安全着陆，而不是局部坚固局部 脆弱。因此该选项说法错误。 3.拦截网系统确实是目前世界小型无人机采用的回收方式之一。因此该选项说法正确。" },
  { id: 969, cat: "飞行原理1", q: "无人机飞行员操纵方向舵时，飞行器将绕（）", opts: ["横轴运动", "纵轴运动", "立轴运动"], ans: 2, exp: "无人机飞行员操纵方向舵时，飞行器将绕立轴运动。立轴是无人机向前的轴，操纵方 向舵会使得飞行器产生偏航运动，也就是绕立轴旋转。这种运动使得飞行器可以改变其飞行 方向。" },
  { id: 970, cat: "飞行原理1", q: "无人机飞行员操纵升降舵时，飞行器将绕（）", opts: ["横轴运动", "纵轴运动", "立轴运动"], ans: 0, exp: "无人机飞行员操纵升降舵时，飞行器将绕横轴运动。横轴是飞机的左右对称轴，操纵 升降舵会改变飞机的俯仰姿态，即绕横轴进行运动。这种操作通常用于控制飞机的上升和下 降。" },
  { id: 971, cat: "飞行原理1", q: "无人机驾驶员操纵副翼时，飞行器将绕（）", opts: ["横轴运动", "纵轴运动", "立轴运动"], ans: 1, exp: "无人机驾驶员操纵副翼时，飞行器将绕纵轴运动。副翼的操纵会导致飞行器发生滚转 运动，滚转运动是绕飞行器的纵轴（即飞机的左右轴）进行的旋转运动。因此，当副翼被操 纵时，飞行器会绕纵轴进行滚转。" },
  { id: 972, cat: "飞行原理1", q: "无人机驾驶员舵面遥控操纵飞机时，（）", opts: ["拉杆飞机转入下降", "推油门飞机转入下降", "推杆飞机转入下降"], ans: 2, exp: "无人机驾驶员在舵面遥控操纵飞机时，正确的操作是推杆飞机转入下降。这是因为推 杆动作会导致飞机的升降舵向下偏转，使得飞机的机头向下俯冲，从而使飞机转入下降状态。" },
  { id: 973, cat: "飞行原理1", q: "下滑有力速度使（）", opts: ["拉杆飞机转入下降", "推油门飞机转入下降", "推杆飞机转入下降"], ans: 2, exp: "无人机驾驶员在舵面遥控操纵飞机时，正确的操作是推杆飞机转入下降。这是因为推 杆动作会导致飞机的升降舵向下偏转，使得飞机的机头向下俯冲，从而使飞机转入下降状态。" },
  { id: 974, cat: "飞行原理1", q: "下列不是影响空气粘性的因素是（）", opts: ["空气的流动位置", "气流的流速", "空气的粘性系数"], ans: 0, exp: "空气粘性是描述空气分子之间摩擦阻力的物理量，它与气流的流速和空气的粘性系数 有关。空气粘性系数是一个物质属性，它描述了空气分子之间内聚力的大小，而空气的流动 位置并不直接影响空气的粘性。因此，选项“空气的流动位置”不是影响空气粘性的因素。" },
  { id: 975, cat: "飞行原理1", q: "下列错误的选项是（）", opts: ["黏性阻力是由于空气和飞行器表面接触产生的", "形状阻力是由于空气和飞行器表面接触产生的", "蒙皮摩擦阻力是由于空气和飞行器表面接触产生的"], ans: 1, exp: "形状阻力（也称为压力阻力或波阻）是由于飞行器的形状和空气流动特性导致的压差 阻力，它主要是由于飞行器前部压缩和后部膨胀造成的气流分离所产生的阻力。形状阻力与 飞行器表面的形状和气动设计有关，而不仅仅是由于空气和飞行器表面接触产生的。而黏性 阻力是由于空气与飞行器表面接触时的摩擦产生的，蒙皮摩擦阻力也是由于空气与飞行器表 面接触产生的摩擦力。" },
  { id: 976, cat: "飞行原理1", q: "下列哪个是正确的？（）", opts: ["牛顿第三运动定律表明，要获得给定加速度所施加的力的大小取决于无人机的质量", "牛顿第二运动定律表明作用力和反作用力是大小相等方向相反的", "如果一个物体处干平衡状态，那么它就有保持这种平衡状态的趋势"], ans: 2, exp: "1.牛顿第二运动定律表明，要获得给定加速度所施加的力的大小取决于无人机的质量和加速 度，而不是牛顿第三运动定律。 2.牛顿第三运动定律表明作用力和反作用力是大小相等方向相反的，而不是牛顿第二运动定 律。 3.如果一个物体处于平衡状态，那么它就有保持这种平衡状态的趋势，这是正确的。比如静 止在桌面上的物体，如果没有外力作用，它会一直保持静止状态。" },
  { id: 977, cat: "飞行原理1", q: "下列哪种状态下飞行器会超过临界迎角？（）", opts: ["低速飞行", "高速飞行", "都会"], ans: 2, exp: "飞行器超过临界迎角的状态可以是低速飞行或高速飞行，因为无论是低速还是高速，只要迎角超过临界迎角，飞机就会失速。临界迎角是指升力系数最大时所对应的迎角，超过 这个迎角后，升力系数反而开始减小，飞机可能失速。因此，正确的选项是：都会。" },
  { id: 978, cat: "飞行原理1", q: "下列说法错误的是（）", opts: ["裕度越大，稳定性就越强", "重心的移动不会改变静稳定裕度", "配重的任何变化都将需要新的升降舵配平以维持水平飞行"], ans: 1, exp: "1.裕度通常指的是某个参数的余量，在航空中，静稳定裕度越大，飞机的稳定性就越强，这 是比较容易理解的，因为有更大的余量来应对各种干扰。该选项正确。 2.重心的移动会极大地影响飞机的静稳定裕度，重心位置的改变会改变飞机的力矩平衡，从 而改变静稳定裕度。该选项错误。 3.飞机的配重发生变化后，飞机的重心等会改变，从而影响飞机的飞行状态，需要新的升降 舵配平来维持水平飞行。该选项正确。" },
  { id: 979, cat: "飞行原理1", q: "下列说法正确的是（）", opts: ["了解飞机阻力是如何产生的并如何去减小它是很重要的", "飞行器飞行时阻力是可以避免的", "每次翼型或迎角的变化都不会改变飞机的阻力"], ans: 0, exp: "了解飞机阻力是如何产生的并如何去减小它是很重要的。飞机在飞行过程中会遇到各 种阻力，包括摩擦阻力、压差阻力、诱导阻力等。了解这些阻力的来源和特性可以帮助飞行 员和工程师采取措施减少阻力，提高飞行效率和飞行器性能。" },
  { id: 980, cat: "飞行原理1", q: "下面说法错误的是（）", opts: ["滑翔状态，一个较大的下滑角会导致一个很大的重力分量今", "在俯冲状态中，飞行轨迹可以达到完全垂直向下", "在爬升状态中，要想爬升得更陡和更快就必须有强大的推力，机翼的作用是主要的"], ans: 2, exp: "爬升主要靠推力而非机翼，机翼主要提供升力。 推力不足时，仅靠机翼无法实现陡爬升，故 C 错误。A、B 描述符合飞行原理。" },
  { id: 981, cat: "飞行原理1", q: "相同迎角，飞行速度增大一倍，阻力增加约为原来的（）", opts: ["一倍", "二倍", "四倍"], ans: 2, exp: "空气阻力与速度的平方成正比。当飞行速度增大一倍时，速度的平方就变为原来的 4 倍，所以阻力增加约为原来的四倍。比如，原来速度为 v，阻力为 f，当速度变为 2V 时，根 据阻力与速度平方的关系，此时阻力变为原来的（2v）2=V2=4 倍。" },
  { id: 982, cat: "飞行原理1", q: "一个平滑流动或流线型流动里面的空气微团，接近一个低压区时（）", opts: ["会加速", "会减速", "速度不变"], ans: 0, exp: "在平滑流动或流线型流动中，空气微团接近低压区时，由于压力差的作用，空气会从 高压向低压流动，所以空气微团会加速流向低压区。" },
  { id: 983, cat: "飞行原理1", q: "影响升力的因素，（）", opts: ["飞行器的尺寸或面积、飞行速度、空气密度", "升力系数", "都是"], ans: 2, exp: "升力的大小受到多个因素的影响。首先，飞行器的尺寸或面积越大，在相同的条件下 能够产生的升力通常也会越大。比如较大机翼面积的飞机一般比小机翼面积的飞机能产生更 大的升力。其次，飞行速度对升力有重要影响。速度越大，空气流过机翼的速度就越快，根 据伯努利原理，上下表面的压力差就会增大，从而升力也会增大。" },
  { id: 984, cat: "飞行原理1", q: "用下滑有利速度下滑，飞机的（）", opts: ["升阻比最大", "升力最大", "下滑角最大"], ans: 0, exp: "用下滑有利速度下滑时，飞机的升阻比最大。下滑有利速度是指飞机在下滑过程中能 够获得最大滑翔距离的速度，这个速度通常低于最佳升力速度。在这个速度下，飞机的升力 与阻力的比值（即升阻比）达到最大，意味着飞机可以更有效地利用升力滑翔，从而获得更 远的下滑距离。" },
  { id: 985, cat: "飞行原理1", q: "在定高直线飞行中，下面关于飞机升力说法，正确的是（）", opts: ["空速小时必须减小迎角，以产生适当的升力来保持高度", "空速大时必须减小迎角，以产生适当的升力来保持高度", "空速大时必须增大迎角，以产生适当的升力来保持高度"], ans: 1, exp: "在定高直线飞行中，飞机的升力必须等于其重量才能保持恒定的高度。升力与空速和 迎角都有关系，但主要是空速的函数。当空速增加时，为了保持升力等于飞机的重量，飞行 员需要减小迎角，因为增加空速已经增加了升力。相反，如果空速减小时，飞行员需要增加 迎角以产生更多的升力。因此，正确的做法是空速大时减小迎角，以产生适当的升力来保持 高度。" },
  { id: 986, cat: "飞行原理1", q: "在机翼上，驻点处是（）", opts: ["空气与前缘相遇的地方", "空气与后缘相遇的地方", "都不正确"], ans: 0, exp: "驻点是气流与机翼前缘相遇、速度降为零的点，是气流分离的起点。前缘是气流最先 接触的部位，故 A 正确。后缘无此现象。" },
  { id: 987, cat: "飞行原理1", q: "在涡阻力等于其他阻力和的地方（）", opts: ["阻力达到最小值", "阻力达到极小值", "阻力达到极大值"], ans: 0, exp: "当涡阻力等于其他阻力和的时候，总的阻力达到最小值。因为在这个特定状态下，各 种阻力相互作用达到一种平衡，使得整体阻力处于一个相对较低的水平。如果涡阻力小于其 他阻力和，随着涡阻力的增加，总阻力会增大；如果涡阻力大于其他阻力和，减少涡阻力能 使总阻力减小。所以在涡阻力等于其他阻力和的地方，阻力达到最小值。" },
  { id: 988, cat: "飞行原理1", q: "载荷因子是（）", opts: ["飞机拉力与阻力的比值", "飞机升力与阻力的比值", "飞机承受的载荷（除重力外）与重力的比值"], ans: 2, exp: "载荷因子（loadfactor）是指飞机承受的载荷（除重力外）与重力的比值。它描述了 飞机在机动飞行中所受到的除重力以外的力对其自身重力的影响程度。载荷因子是一个重要 的飞行性能参数，特别是在描述飞机在急剧机动时的性能时，如转弯、爬升和俯冲等。" },
  { id: 989, cat: "飞行原理1", q: "重心靠后，飞机的纵向安定性（）", opts: ["变强", "减弱", "保持不变"], ans: 1, exp: "飞机重心靠后，飞机在受到外界扰动时，恢复到原来姿态的能力变弱，所以纵向安定 性减弱。重心位置对飞机的稳定性有重要影响，重心靠后会使飞机的稳定性变差。" },
  { id: 990, cat: "飞行原理1", q: "重心靠前，飞机的纵向安定性（）", opts: ["变强", "减弱", "不受影响"], ans: 0, exp: "当飞机重心靠前时，飞机在受到外界扰动后，有使飞机恢复到原来姿态的趋势，所以 纵向安定性变强。如果重心靠后，飞机在扰动后就较难恢复到原来姿态，纵向安定性会减弱。" },
  { id: 991, cat: "飞行原理1", q: "转弯时，为保持高度和空速，应（）", opts: ["增大迎角和油门", "增大迎角、减小拉力", "减小迎角、增大拉力"], ans: 0, exp: "转弯时，为了保持高度和空速，正确的操作是增大迎角和油门。这是因为在转弯过程 中，飞机需要额外的升力来克服由于转弯引起的离心力，同时需要增加推力来克服增加的阻 力，以保持空速。" },
  { id: 992, cat: "飞行原理1", q: "常规布局的飞机主要舵面指的是（）", opts: ["升降舵、方向舵、襟翼", "方向舵、襟翼、缝翼", "升降舵、方向舵、副翼"], ans: 2, exp: "在常规布局的飞机中，主要舵面是指用于控制飞机姿态和飞行方向的关键活动部件。 升降舵用于控制飞机的俯仰（Pitch），方向舵用于控制偏航（Yaw），副翼用于控制滚转（Roll）。 这三个舵面是飞机姿态控制的关键部件。 因此，正确答案是：升降舵、方向舵、副翼。" },
  { id: 993, cat: "飞行原理1", q: "操纵飞机水平转弯时受力（）", opts: ["升力，重力，拉力，阻力，惯性力", "转弯向心力由发动机拉力提供", "转弯向心力由升力提供"], ans: 2, exp: "水平转弯靠升力，倾斜分力转飞机。飞机水平转弯时，需倾斜机翼，将升力分解为垂 直分量（平衡重力）和水平分量（提供向心力），从而完成转弯。这是航空力学的基本原理。" },
  { id: 994, cat: "飞行原理1", q: "当不可压气流连续流过一个阶梯管道时，已知其截面积 A1=2A2=4A3 则其静压为（）", opts: ["P1=P2=P3", "P1>P2>P3", "P1<P2<P3"], ans: 1, exp: "根据伯努利方程，对于不可压缩流体，流速和静压之间存在关系：在流线上的任意两 点，流速大的地方静压小，流速小的地方静压大。由于截面积 A1=2A2=4A3，根据连续性方 程，流速 V1<V2<V3，故静压 P1>P2>P3。" },
  { id: 995, cat: "飞行原理1", q: "飞行速度增大一倍，阻力（）", opts: ["减小为原来的四分之一", "增大为原来的四倍", "增大为原来的二倍"], ans: 1, exp: "根据阻力公式，阻力与速度的平方成正比。因此，当飞行速度增大一倍时，阻力会增 大为原来的四倍。比如，原来速度为 v，阻力为 f，当速度变 2V 时，根据阻力与速度平方的 关系，此时阻力变为原来的（2v）2=v2=4 倍。" },
  { id: 996, cat: "飞行原理1", q: "根据伯努利定律，同一管道中，气流速度增大的地方，压强将（）", opts: ["不变", "增大", "减小"], ans: 2, exp: "伯努利定律表明，在理想流体的流动中，流速大的地方压强小，流速小的地方压强大。 因此，当气流速度增大时，压强会减小。" },
  // ==================== 飞行原理2 ====================
  { id: 997, cat: "飞行原理2", q: "“失速”指的是（）", opts: ["飞机失去速度", "飞机速度太快", "飞机以大于临界迎角飞行"], ans: 2, exp: "“失速”是指飞机的迎角超过了其临界迎角，导致机翼上产生的升力急剧减小，无法 维持飞机的正常飞行状态。这通常发生在飞机的迎角过大，气流无法顺畅流过机翼表面，造 成升力损失和飞机控制能力下降的情况。失速并不是指飞机失去速度或速度太快，而是指飞 机的气动状态发生了变化，导致升力不足。" },
  { id: 998, cat: "飞行原理2", q: "“失速迎角”就是“临界迎角”，指的是（）", opts: ["飞机飞得最高时的迎角", "飞机飞得最快时的迎角", "飞机升力系数最大时的迎角"], ans: 2, exp: "“失速迎角”或“临界迎角”指的是飞机在特定飞行条件下，升力系数达到最大值时 的迎角。超过这个迎角后，飞机的升力不再增加，反而开始急剧下降，导致飞机可能进入失 速状态。" },
  { id: 999, cat: "飞行原理2", q: "表面脏污的机翼与表面光洁的机翼相比（）", opts: ["最大升力系数下降，阻力系数增大", "相同升力系数时其迎角减小", "同迎角下升力系数相同，阻力系数加大"], ans: 0, exp: "当机翼表面脏污时，会破坏机翼表面的气流流动状态。一方面，使得机翼产生升力的 效率降低，所以最大升力系数下降；另一方面，脏污会增加空气流过机翼时的摩擦阻力等，导致阻力系数增大。" },
  { id: 1000, cat: "飞行原理2", q: "伯努利方程的使用条件是（）", opts: ["只要是理想的不可压缩流体", "只要是理想的与外界无能量交换的流体", "必须是理想的、不可压缩、且与外界无能量变换的流体"], ans: 2, exp: "伯努利方程描述了在理想流体（无粘性、不可压缩）沿着流线流动时，流体的总能量 （包括压力能、动能和势能）守恒的条件。这个方程的使用条件是流体必须是理想的、不可 压缩的，并且与外界没有能量交换，即流体在流动过程中没有热量的加入或损失，也没有做 功。" },
  { id: 1001, cat: "飞行原理2", q: "伯努利方程适用于（）", opts: ["低速气流", "高速气流", "适用于各种速度的气流"], ans: 0, exp: "伯努利方程是由瑞士物理学家丹尼尔•伯努利在 1738 年提出的，它描述了理想流体沿 着一条流线作定常流动时，流体的压力、速度和高度之间的关系。伯努利方程主要适用于低 速气流，在低速气流中，空气可以被认为是不可压缩的，此时伯努利方程能够比较准确地描 述气流的特性。而在高速气流中，空气的压缩性不能被忽略，伯努利方程就不再适用了。" },
  { id: 1002, cat: "飞行原理2", q: "不属于影响飞机机体腐蚀的大气因素是（）", opts: ["空气的相对湿度", "空气压力", "空气的温差"], ans: 1, exp: "影响飞机机体腐蚀的大气因素主要包括温度、湿度、氧化、有害气体、化学物质等多 种因素。这些环境因素对飞机遭受腐蚀的易感性起着主要作用，往往是多种因素组合作用的 结果。空气压力并不直接被列为影响飞机机体腐蚀的大气因素之一。" },
  { id: 1003, cat: "飞行原理2", q: "不属于影响机翼升力系数的因素是（）", opts: ["翼剖面形状", "迎角", "空气密度"], ans: 2, exp: "影响机翼升力系数的因素包括飞机速度、气动参数、几何形状等。空气密度作为影响 飞机升力系数的因素之一，与升力系数成正比关系。当空气密度增加时，升力系数也会相应 增加。然而，空气密度的变化通常不是升力系数的主要影响因素，因为它相对于其他因素如 迎角、翼型形状和机翼面积的影响较小。" },
  { id: 1004, cat: "飞行原理2", q: "测量机翼的翼弦是从（）", opts: ["左翼尖到右翼尖", "机身中心线到翼尖", "机翼前缘到后缘"], ans: 2, exp: "翼弦是指机翼横截面的弦长，也就是从机翼的前缘到后缘的直线距离。这个参数对于 计算机翼的面积、展弦比以及气动特性等都是非常重要的。 在航空学中，翼弦是描述机翼形状和大小的一个基本尺寸。" },
  { id: 1005, cat: "飞行原理2", q: "测量机翼的翼展是从（）", opts: ["左翼尖到右翼尖", "机身中心线到翼尖", "机翼前缘到后缘"], ans: 0, exp: "翼展是指飞机机翼左右翼尖之间的距离，即从一侧翼尖到另一侧翼尖的直线长度。这 是衡量飞机机翼尺寸的重要参数，通常用于描述机翼的大小和飞机的整体尺寸。" },
  { id: 1006, cat: "飞行原理2", q: "层流翼型的特点是（）", opts: ["前缘半径大，后部尖的水滴形", "最大厚度靠后", "前缘尖的菱形"], ans: 1, exp: "层流翼型的最大特点就是最大厚度靠后。这样的设计可以使气流在翼型表面尽可能保 持层流状态，减少气流的摩擦阻力，提高飞机的飞行效率。" },
  { id: 1007, cat: "飞行原理2", q: "从原点作极细线的切线，切点所对应的迎角值是（）", opts: ["最大迎角", "有利迎角", "最小迎角"], ans: 1, exp: "极曲线的一个重要特性是，从坐标原点作切线与极曲线相切，切点所对应的迎角值即 为有利迎角。有利迎角是指升力系数与阻力系数的比值最大的迎角，飞机在这个迎角下飞行 时，可以保证在同一高度滑翔得最远。" },
  { id: 1008, cat: "飞行原理2", q: "当飞机减小速度水平飞行时（）", opts: ["增大迎角以提高升力", "减小迎角以减小阻力", "保持迎角不变以防止失速"], ans: 0, exp: "当飞机减小速度水平飞行时，为了维持所需的升力以保持高度，飞行员需要增大迎角。 这是因为升力与迎角和速度的平方成正比，当速度减小时，为了产生足够的升力以支撑飞机 的重量，迎角需要增加。" },
  { id: 1009, cat: "飞行原理2", q: "当空气在管道中低速流动时由伯努利定理可知（）", opts: ["流速大的地方，静压大", "流速大的地方，静压小", "流速大的地方，总压大"], ans: 1, exp: "根据伯努利定理，当空气在管道中低速流动时，流速大的地方压力小，这里的压力指 的是静压。因为流体的能量是一定的，流速大意味着动能大，那么静压能就会减小。而总压 是动压和静压之和，流速变化时总压一般保持不变。" },
  { id: 1010, cat: "飞行原理2", q: "当空气在管道中流动时，由伯努利定理可知（）", opts: ["凡是流速大的地方，压强就大", "凡是流速小的地方，压强就小", "凡是流速大的地方，压强就小"], ans: 2, exp: "根据伯努利定理，当空气在管道中流动时，流速大的地方压强小，流速小的地方压强 大。这是因为流体的动能和压力能、势能在一定条件下可以相互转化。当流速增大时，动能 增加，压力能就会减小，从而导致压强变小。" },
  { id: 1011, cat: "飞行原理2", q: "当迎角达到临界迎角时（）", opts: ["升力突然大大增加，而阻力迅速减小", "升力突然大大降低，而阻力迅速增加", "升力和阻力同时大大增加"], ans: 1, exp: "当迎角达到临界迎角时，飞机的升力会突然大大降低，而阻力会迅速增加。这是因为 在临界迎角之后，机翼上的气流开始分离，导致升力急剧下降，同时由于气流分离引起的阻 力急剧上升，飞机可能会进入失速状态。" },
  { id: 1012, cat: "飞行原理2", q: "对地速气流，由伯努利方程可以得出（）", opts: ["流管内气流速度增加，空气静压也增加", "流管截面积减小，空气静压增加", "流管内气流速度增加，空气静压减小"], ans: 2, exp: "伯努利方程表明，对于低速气流，在同一流管中，流体的流速与静压之间存在一定关 系。当流管内气流速度增加时，意味着动能增大，而总能量是一定的，所以静压就会减小。" },
  { id: 1013, cat: "飞行原理2", q: "对飞机飞行安全性影响最大的阵风是（）", opts: ["上下垂直于飞行方向的阵风", "左右垂直于飞行方向的阵风", "沿着飞行方向的阵风"], ans: 0, exp: "垂直于飞行方向的上下阵风（A）会直接改变飞机的迎角，导致升力突变，对飞行稳 定性影响最大。左右阵风（B）和顺逆风（C）的影响相对较小。" },
  { id: 1014, cat: "飞行原理2", q: "在下述何种情况下容易碰到风切变？（）", opts: ["逆温层附近或靠近雷暴时", "当风速大于 65 千米/小时", "有高气压时"], ans: 0, exp: "逆温层附近和靠近雷暴的时候容易碰到风切变。逆温层会使空气的流动变得不稳定，容易产生风切变；雷暴区域由于强烈的上升和下降气流以及复杂的空气运动，也常常伴随着 风切变。" },
  { id: 1015, cat: "飞行原理2", q: "对起飞降落安全性造成不利影响的是（）", opts: ["稳定的逆风场", "跑道上的微冲气流", "稳定的上升气流"], ans: 1, exp: "对起飞降落安全性造成不利影响的是跑道上的微冲气流。微冲气流是最危险的低空风 变形式，对飞行安全影响较大，尤其以低空风切变危害最大。在起降阶段，无人机可能会遇 到微冲气流，这种气流能够迅速改变飞机的升力和阻力，导致飞机失控，从而对起飞和降落 的安全性构成严重威胁。" },
  { id: 1016, cat: "飞行原理2", q: "对一般翼型来说，下列说法中哪个是正确的？（）", opts: ["当迎角为零时，升力不为零", "当翼剖面有一个正迎角时，上翼面处的流线比下翼面处的流线疏", "当翼剖面有一个正迎角时，上翼面处的流速小于下翼面处的流速"], ans: 0, exp: "对于一般翼型来说，正确的说法是当迎角为零时，升力不为零。这是因为即使在零迎 角下，翼型由于其形状（通常是上凸下平），仍然能够产生升力。这种升力来源于翼型上下 表面的压力差，即使没有迎角，这种压力差依然存在，尽管升力相对较小。" },
  { id: 1017, cat: "飞行原理2", q: "对于非对称翼型的零升迎角是（）", opts: ["一个小的正迎角", "一个小的负迎角", "失速迎角"], ans: 1, exp: "非对称翼型的零升迎角是指升力系数为零时所对应的迎角，对于非对称翼型来说，这 个角度通常是一个较小的负角度。这是因为非对称翼型即使在迎角为零时也会产生升力，因 此零升迎角必然小于零度。" },
  { id: 1018, cat: "飞行原理2", q: "飞机飞行中，机翼升力等于零时的迎角称为（）", opts: ["零升迎角", "失速迎角", "零迎角"], ans: 0, exp: "飞机飞行中，机翼升力等于零时的迎角称为零升迎角。这个迎角是指在特定的飞行条 件下，机翼产生的升力为零的角度。在实际飞行中，零升迎角是一个重要的参考值，因为它 与飞机的失速迎角有关，了解零升迎角有助于飞行员控制飞机，避免失速。" },
  { id: 1019, cat: "飞行原理2", q: "飞机前缘结冰对飞行的主要影响（）", opts: ["增大了飞机重量，便起飞困难", "增大了临界攻角，使飞机易失速", "相同迎角，升力系数下降"], ans: 2, exp: "飞机前缘结冰后，会改变机翼的形状和气流的流动状态。由于结冰使得机翼表面变得 粗糙不光滑，气流在机翼上的流动受到干扰，在相同的迎角下，升力系数会下降。" },
  { id: 1020, cat: "飞行原理2", q: "飞机上不同部件的连接处装有整流包皮，它的主要作用是（）", opts: ["减小摩擦阻力", "减小干扰阻力", "减小诱导阻力"], ans: 1, exp: "飞机上不同部件的连接处装有整流包皮，主要是为了减少部件间连接处的气流干扰，从而减少由于气流分离和湍流造成的干扰阻力。" },
  { id: 1021, cat: "飞行原理2", q: "飞机上产生的摩擦阻力与大气的哪种物理性质有关？（）", opts: ["可压缩性", "粘性", "温度"], ans: 1, exp: "飞机上产生的摩擦阻力与大气的粘性有关。摩擦阻力是由于飞机表面与周围空气分子 之间的粘性作用而产生的。当飞机在空中移动时，接触飞机表面的气流会受到粘性的影响，产生摩擦，从而形成阻力。这种阻力与空气的粘性直接相关，而与空气的可压缩性和温度关 系不大。" },
  { id: 1022, cat: "飞行原理2", q: "飞机上产生的摩擦力与什么因素有关？（）", opts: ["与大气可压缩性有关", "与大气的粘性、飞机表面状况及周围气流接触的飞机表面面积有关", "仅与大气的温度有关"], ans: 1, exp: "飞机上产生的摩擦阻力与大气的粘性、飞机表面状况及周围气流接触的飞机表面面积 有关。大气的粘性决定了空气与飞机表面之间的摩擦程度，飞机表面状况（如粗糙度）影响 摩擦力的大小，而接触气流的飞机表面面积则决定了摩擦力作用的区域大小。这些因素共同 影响飞机的摩擦阻力。" },
  { id: 1023, cat: "飞行原理2", q: "飞机上的总空气动力的作用线与飞机纵轴的交点称为（）", opts: ["全机重心", "全机的压力中心", "机体坐标的原点"], ans: 1, exp: "飞机上的总空气动力的作用线与飞机纵轴的交点称为全机的压力中心。压力中心是飞 机上受到气动力作用的集中点，它对于飞机的稳定性和操控性有重要影响。" },
  { id: 1024, cat: "飞行原理2", q: "飞机升力的大小与空气密度的关系是（）", opts: ["空气密度成正比", "空气密度无关", "空气密度成反比"], ans: 0, exp: "飞机升力的产生主要是由于机翼上下表面的压力差。空气密度越大，在相同的速度和 机翼形状等条件下，机翼上下表面的压力差就会越大，从而升力也越大。所以飞机升力的大 小与空气密度成正比。" },
  { id: 1025, cat: "飞行原理2", q: "飞机升力的大小与空速的关系是（）", opts: ["与空速成正比", "与空速无关", "与空速的平方成正比"], ans: 2, exp: "L=1/2ρCSV²，即：升力 L=1/2 空气密度*速度的平方*机翼面积*升力系数。飞机升力 的大小与空速的关系是与空速的平方成正比。机翼的升力来自流过其上下表面气流的速度差，空速决定了这一速度差，从而影响升力的大小。空速越大，升力也随之增大，且增大的比例 与空速的平方成正比。（口诀：空速带平方）" },
  { id: 1026, cat: "飞行原理2", q: "飞机升阻比值的大小主要随下列哪项因素变化（）", opts: ["飞行速度", "飞行迎角", "机翼面积"], ans: 1, exp: "飞机升阻比值的大小主要随飞行迎角变化。迎角是固定翼飞机机翼弦线和气流速度的 夹角，也是确定机翼在气流中姿态的基准。在飞行过程中，改变迎角会导致升力和阻力的变 化，进而影响升阻比。迎角的增加会使得升力增加，但超过临界迎角后，升力会迅速减小，同时阻力剧增，导致升阻比急剧下降。" },
  { id: 1027, cat: "飞行原理2", q: "飞机在飞行时，升力方向是（）", opts: ["与相对气流速度垂直", "与地面垂直", "与翼弦垂直"], ans: 0, exp: "飞机在飞行时，升力的方向与相对气流速度垂直。升力是作用在飞机机翼上，垂直于 机翼相对气流方向的力。这个力是由机翼的形状和气流速度产生的，它使飞机得以克服重力，保持在空中。" },
  { id: 1028, cat: "飞行原理2", q: "飞机在平飞时载重量越大其失速速度（）", opts: ["越大", "角愈大", "与重量无关"], ans: 0, exp: "飞机在平飞时，载重量越大其失速速度越大。这是因为载重量的增加意味着飞机需要 更多的升力来保持在空中，而失速速度是飞机能够产生足够升力以维持飞行的最小速度。因 此，当飞机的载重量增加时，为了在相同的迎角下产生更多的升力，飞机的失速速度也会相 应增加。" },
  { id: 1029, cat: "飞行原理2", q: "飞行中操作扰流板伸出（）", opts: ["增加机翼上翼面的面积以提高升力", "阻挡气流的流动，增大阻力", "增加飞机抬头力矩，辅助飞机爬升"], ans: 1, exp: "扰流板的主要作用是在飞行中伸出时，会破坏机翼上表面的气流，阻挡气流的流动，从而增大飞机的阻力。" },
  { id: 1030, cat: "飞行原理2", q: "关于动压和静压的方向，以下哪一个是正确的？（）", opts: ["动压和静压的方向都是与运动的方向一致", "动压和静压都作用在任意方向", "动压作用在流体的流动方向，静压作用在任意方向"], ans: 2, exp: "动压和静压是描述流体中压力状态的两个重要概念。动压，也称为速度压，是由于流 体运动而产生的压力，其方向与流体流动的方向一致。静压，也称为静态压力，是在流体中 任意点测量到的压力，其作用方向是向所有方向均匀分布的。" },
  { id: 1031, cat: "飞行原理2", q: "关于升阻比下列哪个说法正确？（）", opts: ["在最大升力系数时阻力一定最小", "最大升阻比时，一定是达到临界攻角", "升阻比随迎角的改变而改变"], ans: 2, exp: "升阻比随迎角的改变而改变，因为升力系数和阻力系数都是迎角的函数。在一定范围 内，迎角越大，升力系数与阻力系数也越大。但是，当迎角超过某一数值（称为临界迎角），升力系数反而开始减小，同时阻力系数急剧增大，导致升阻比急剧减小。因此，升阻比随迎 角的改变而改变是正确的。" },
  { id: 1032, cat: "飞行原理2", q: "国际标准大气的物理参数的相互关系是（）", opts: ["温度不变时，压力与体积成正比", "体积不变时，压力和温度成正比", "压力不变时，体积和温度成反比"], ans: 1, exp: "当体积不变时，根据理想气体状态方程，压力和温度成正比是正确的。因为在体积不 变的情况下，温度升高，分子运动加剧，对容器壁的撞击力增大，从而压力增大；温度降低，分子运动减弱，压力减小。" },
  { id: 1033, cat: "飞行原理2", q: "合理布局飞机结构的位置，是为了减小（）", opts: ["摩擦阻力", "压差阻力", "干扰阻力"], ans: 2, exp: "合理布局飞机结构的位置主要是为了减小干扰阻力。干扰阻力是由于飞机各部分之间 由于气流相互干扰而产生的一种额外阻力。" },
  { id: 1034, cat: "飞行原理2", q: "机翼 1/4 弦线与垂直机身中心的直线之间的夹角称为机翼的（）", opts: ["安装角", "上反角", "后掠角"], ans: 2, exp: "机翼的后掠角是指机翼 1/4 弦线与垂直于机身中心线的直线之间的夹角。后掠角是描 述机翼形状的一个重要参数，它影响着飞机的高速飞行性能，包括减少波阻和提高飞机的机 动性。后掠角越大，飞机在高速飞行时受到的波阻越小，但同时也会增大飞机的诱导阻力。" },
  { id: 1035, cat: "飞行原理2", q: "机翼的安装角是（）", opts: ["翼弦与相对气流速度的夹角", "翼弦与机身纵轴之间所夹锐角", "翼弦与水平面之间所夹的锐角"], ans: 1, exp: "机翼的安装角是指翼弦与机身纵轴之间所夹的锐角。这个角度影响飞机的气动特性和 飞行性能，包括升力、阻力和飞机的稳定性。安装角的不同设置可以调整飞机的俯仰力矩，进而影响飞机的平衡和操纵性。" },
  { id: 1036, cat: "飞行原理2", q: "机翼的弦线与相对气流速度之间的夹角称为（）", opts: ["机翼的安装角", "机翼的上反角", "迎角"], ans: 2, exp: "这个夹角就是迎角。迎角大小直接影响机翼产生的升力和阻力，对飞机飞行状态有重 要作用。" },
  { id: 1037, cat: "飞行原理2", q: "机翼的压力中心（）", opts: ["迎角改变时升力增量作用线与翼弦的交点", "翼弦与机翼空气动力作用线的交点", "翼弦与最大厚度线的交点"], ans: 1, exp: "机翼的压力中心是指翼弦与机翼空气动力作用线的交点。压力中心是机翼上所有压力 作用的集中点，它的位置对于飞机的稳定性和操控性有重要影响。当迎角改变时，压力中心 的位置也会随之改变，但通常它位于机翼的某个固定位置，与翼弦和空气动力作用线的交点 相对应。" },
  { id: 1038, cat: "飞行原理2", q: "机翼的翼弦比（展弦比）是（）", opts: ["展长与机翼最大厚度之比", "展长与翼尖弦长之比", "展长与平均几何弦长之比"], ans: 2, exp: "机翼的展弦比是指机翼的展长（即机翼从一端到另一端的直线距离）与机翼的平均几 何弦长（即机翼的平均宽度）之比。" },
  { id: 1039, cat: "飞行原理2", q: "机翼空气动力受力最大的是（）", opts: ["机翼下表面压力", "机翼上表面负压", "机翼上表面压力"], ans: 1, exp: "机翼空气动力受力最大的是机翼上表面的负压。 在飞行中，机翼上表面的空气流速快于下表面，根据伯努利原理，流速增加导致压力降低，因此机翼上表面产生负压（即低于自由流的压力）。 这个负压是机翼产生升力的主要原因之一，因为它与下表面的正压形成压力差，从而产生升 力。" },
  { id: 1040, cat: "飞行原理2", q: "机翼升力系数与哪些因素有关？（）", opts: ["仅与翼剖面形状有关", "与翼剖面形状和攻角有关", "仅与攻角有关"], ans: 1, exp: "机翼升力系数与多个因素相关，包括翼剖面形状和攻角。翼剖面形状是指机翼横截面 的形状，它直接影响空气流动的特性和升力的产生。攻角，也称为迎角，是机翼弦线与相对 风向之间的夹角，它决定了机翼上下方的压力差，进而影响升力的大小。因此，升力系数不 仅与翼剖面形状有关，也与攻角有关。" },
  { id: 1041, cat: "飞行原理2", q: "计算机动压时需要哪些数据？（）", opts: ["大气压力和速度", "空气密度和阻力", "空气密度和速度"], ans: 2, exp: "动压的计算公式为q=1/2ρv²，其中（q）是动压，（rho）是空气密 度，（v）是速度。所以计算动压时需要空气密度和速度这两个数据。" },
  { id: 1042, cat: "飞行原理2", q: "当气温高于标准大气温度时，飞机载重量要（）", opts: ["增加", "减小", "保持不变"], ans: 1, exp: "当气温高于标准大气温度时，飞机的载重量会减少。这是因为气温升高会导致空气密 度减小，根据空气动力学原理，飞机升力与空气密度成正比。因此，在较高的气温下，飞机 为了保持相同的升力，需要更大的速度或更大的迎角，这会增加燃油消耗和操作难度，从而 限制了飞机的载重量。" },
  { id: 1043, cat: "飞行原理2", q: "减少飞机摩擦阻力的措施是（）", opts: ["保持飞机表面光洁度", "减小迎风面积", "增大后掠角"], ans: 0, exp: "减少飞机摩擦阻力的措施是保持飞机表面光洁度。飞机表面的光洁度直接影响到飞机 与空气之间的摩擦阻力。光滑的表面能够减少空气流动时的摩擦，从而降低摩擦阻力。" },
  { id: 1044, cat: "飞行原理2", q: "减小飞机外形的迎风面积，目的是减小飞机的（）", opts: ["摩擦阻力", "压差阻力", "诱导阻力"], ans: 1, exp: "减小飞机外形的迎风面积，目的是减小飞机的压差阻力。压差阻力是由于机表面前后 压力不同而产生的阻力，迎风面积越大，前后压力差也就越大，从而产生的压差阻力也越大。 因此，通过减小迎风面积可以减少压差阻力，提高飞机的气动效率。" },
  { id: 1045, cat: "飞行原理2", q: "减小干扰阻力的主要措施是（）", opts: ["把机翼表面做得很光滑", "部件连接处采取整流措施", "把暴露的部件做成流线型"], ans: 1, exp: "减小干扰阻力的主要措施是在部件连接处采取整流措施。干扰阻力是由于飞行器各部 件之间的交汇、连接和间隙等造成的阻力，通过在部件连接处采取整流措施，可以减少空气 流动的干扰，从而降低干扰阻力。" },
  { id: 1046, cat: "飞行原理2", q: "具有后掠角的飞机有侧滑角时，会产生（）", opts: ["滚转力矩", "俯仰力矩", "不产生任何力矩"], ans: 0, exp: "具有后掠角的飞机在有侧滑角时，会产生滚转力矩。这是因为侧滑导致飞机左右两翼 的相对气流速度不一致，从而引起两翼升力不同，进而产生滚转力矩。" },
  { id: 1047, cat: "飞行原理2", q: "具有上反角的飞机有侧滑角时，会产生（）", opts: ["偏航力矩", "俯仰力矩", "不产生任何力矩"], ans: 0, exp: "具有上反角的飞机在有侧滑角时，会产生偏航力矩。上反角的设计使得飞机在侧滑时，一侧机翼的迎角增大，另一侧机翼的迎角减小，导致两侧机翼升力不同，从而产生偏航力矩，帮助飞机恢复到原来的飞行姿态。这种设计有助于提高飞机的横向稳定性。" },
  { id: 1048, cat: "飞行原理2", q: "空气的密度（）", opts: ["与压力成正比", "与压力成反比", "与压力无关"], ans: 0, exp: "根据物理学知识，在一定温度下，空气的密度与压力成正比。当压力增大时，空气分 子被压缩得更紧密，单位体积内的分子数量增多，从而导致密度增大；反之，当压力减小时，空气分子间的距离增大，单位体积内的分子数量减少，密度减小。" },
  { id: 1049, cat: "飞行原理2", q: "利用风可以得到飞机气动参数，其基本依据是（）", opts: ["连续性假设", "相对性原理", "牛顿定理"], ans: 1, exp: "利用风可以得到飞机气动参数，其基本依据是相对性原理。相对性原理是指在流体力 学中，流体的运动状态相对于一个固定的参考系来描述。" },
  { id: 1050, cat: "飞行原理2", q: "流管中空气的动压（）", opts: ["仅与空气密度成正比", "与空气速度和空气密度成正比", "与空气速度平方和空气密度成正比"], ans: 2, exp: "动压即单位体积空气所具有的动能，其计算公式为动压=1/2×空气密度×空气速度。 可以看出，流管中空气的动压与空气速度的平方和空气密度成正比。空气速度越大，动压越 大；空气密度越大，动压也越大。" },
  { id: 1051, cat: "飞行原理2", q: "流体的伯努利定理（）", opts: ["适用于不可压缩的理想流体", "适用于粘性的理想流体", "适用于不可压缩的粘性流体"], ans: 0, exp: "伯努利定理适用于不可压缩的理想流体。这个定理描述了在稳定流动中，流体的总能 量（包括压力能、动能和势能）沿流线是守恒的。对于理想流体，意味着流体是无粘性的，因此不会产生由于粘性引起的能量损失。" },
  { id: 1052, cat: "飞行原理2", q: "流体的连续性方程（）", opts: ["只适用于理想流动", "适用于可压缩和不可压缩流体的稳定管流", "只适用于不可压缩流体的稳定管流"], ans: 0, exp: "流体的连续性方程是基于理想流动的假设推导出来的。它假设流体是无粘性、不可压 缩的，并且流动是稳定的。在理想流动的条件下，连续性方程描述了流体在管道中流动时，通过不同截面的质量流量是相等的。" },
  { id: 1053, cat: "飞行原理2", q: "流体在管道中以稳定的速度流动时，如果管道由粗变细，则流体的流速（）", opts: ["增大", "减小", "保持不变"], ans: 0, exp: "根据流体连续性原理，在稳定流动的情况下，单位时间内流过管道各个截面的流体体积是相等的。当管道由粗变细时，横截面积变小，为了保证单位时间内流过的流体体积不变，流体的流速就必须增大。" },
  { id: 1054, cat: "飞行原理2", q: "没有保护好飞机表面的光洁度，将增加飞机的哪种阻力？（）", opts: ["压差阻力", "摩擦阻力", "干扰阻力"], ans: 1, exp: "没有保护好飞机表面的光洁度，将增加飞机的摩擦阻力。摩擦阻力是由于空气黏性作 用产生，与飞机表面状况有直接关系。飞机表面越光滑，摩擦阻力越小；反之，表面粗糙会 增加摩擦阻力。 因此，保持飞机表面的光洁度对于减小摩擦阻力至关重要。" },
  { id: 1055, cat: "飞行原理2", q: "气流产生下洗是由于（）", opts: ["分离点后出现旋涡的影响", "转折点后紊流的影响", "机翼上下表面存在压力差的影响"], ans: 2, exp: "气流产生下洗是由于机翼上下表面存在压力差的影响。在飞行中，机翼上表面的空气 流速快于下表面，导致上表面的压力低于下表面的压力，形成压力差。这个压力差使得空气 向下和后流动，产生所谓的“下洗”现象，即气流向下偏转。" },
  { id: 1056, cat: "飞行原理2", q: "气流沿机翼表面附面层类型的变化是（）", opts: ["可由紊流变为层流", "可由层流变为紊流", "一般不发生变化"], ans: 1, exp: "在气流沿机翼表面流动时，附面层在一般情况下是从层流状态开始的。随着气流速度 的增加、距离的加长等因素影响，附面层逐渐变得不稳定，进而从层流状态转变为紊流状态。" },
  { id: 1057, cat: "飞行原理2", q: "气流沿机翼表面流动，影响由层流变为紊流的原因不包括（）", opts: ["空气的流速", "在翼表面流动长度", "空气比重"], ans: 2, exp: "影响气流沿机翼表面由层流变为紊流的因素主要包括空气的流速和在翼表面流动的长 度。流速的增加会导致边界层内部的剪切力增加，进而可能引发转捩。同样，流动长度的增 加也可能导致边界层变得更厚，增加了转捩的可能性。而空气的比重（密度）并不直接影响 层流到紊流的转变。" },
  { id: 1058, cat: "飞行原理2", q: "气体的伯努利定理是哪个定律在空气流动过程中的应用？（）", opts: ["能量守恒定律", "牛顿第一定律", "质量守恒定律"], ans: 0, exp: "气体的伯努利定理实际上是能量守恒定律在空气流动过程中的应用。伯努利定理表明，在理想流体稳定流动中，流体的静压与动压之和为一常数。这意味着流体的压力能、动能和 势能在流动过程中可以相互转化，但总和保持不变，体现了能量守恒的原理。" },
  { id: 1059, cat: "飞行原理2", q: "气体的连续性定理是哪个定律在空气流动过程中的应用？（）", opts: ["能量守恒定律", "牛顿第一定律", "质量守恒定律"], ans: 2, exp: "气体的连续性定理是质量守恒定律在空气流动过程中的应用。连续性定理表明，在没 有质量源或汇的情况下，流体流动的体积流量在任何流线上都是恒定的。这意味着流体在流 动过程中，流经任何横截面的质量流量都是相同的，即质量守恒。" },
  { id: 1060, cat: "飞行原理2", q: "气体的压力 P 密度ρ温度 T 三者之间的变化关系是（R 为理想气体常数），（）", opts: ["T=PRρ", "P=Rρ/T", "P=RρT"], ans: 2, exp: "对于理想气体，根据理想气体状态方程： PV=nRT（P 是压强，V 是体积，n 是物质的量，R 是理想气体常数，T 是温度）。而密度 ρ=m/V （m 是质量），且 n=m/M（M 是摩尔质量），所以 P=nRT/V=mRT/（MV）=pRT/M，对于空气等单 一组分气体，可近似认为 M 为常数，那么 P=RρT." },
  { id: 1061, cat: "飞行原理2", q: "随着飞行速度的提高，下列关于阻力的哪种说法是正确的？（）", opts: ["诱导阻力增大，废阻力增大", "诱导阻力减小，废阻力减小", "诱导阻力减小，废阻力增大"], ans: 2, exp: "随着飞行速度的提高，废阻力会增大，而诱导阻力也会因为速度的增加而增大，但由 于升力系数的增加，诱导阻力的增加相对较小。所以，正确的说法是诱导阻力减小，废阻力 增大。" },
  { id: 1062, cat: "飞行原理2", q: "为了飞行安全。飞机飞行时的升力系数和迎角一般为（）", opts: ["最大升力系数和临界迎角最大", "最大升力系数和小于临界迎角的迎角限定值", "小于最大升力系数和临界迎角的两个限定值"], ans: 2, exp: "飞机在飞行时的升力系数和迎角一般会保持在小于最大升力系数和临界迎角的两个限 定值以内，以确保飞机的飞行安全。" },
  { id: 1063, cat: "飞行原理2", q: "下列关于动压的哪种说法是正确的？（）", opts: ["总压与静压之和", "总压与静压之差", "动压和速度成正比"], ans: 1, exp: "动压是指流体单位体积的动能，它是由流体的速度产生的。在流体力学中，动压是总 压（即流体的总能量）与静压（即流体的静态压力）之差。 因此，正确的表述是动压等于总压与静压之差。" },
  { id: 1064, cat: "飞行原理2", q: "下列关于升阻比的哪种说法是不正确的？（）", opts: ["升力系数达到最大时，升阻比也达到最大", "升力和阻力之比升阻比达到最大之前，随迎角增加", "升阻比成线性增加"], ans: 0, exp: "升阻比（升力系数与阻力系数的比值）描述了飞机单位阻力所能获得的升力大小。升 力系数达到最大时，并不意味着升阻比也达到最大。实际上，升阻比在达到一个最大值后会 随着迎角的继续增加而减小。这是因为超过一定迎角后，虽然升力系数可能继续增加，但阻 力系数增加得更快，导致升阻比下降。升阻比的最大值通常出现在迎角的一个特定值，而不 是升力系数最大的迎角。" },
  { id: 1065, cat: "飞行原理2", q: "下列关于压差阻力哪种说法是正确的？（）", opts: ["物体的最大迎风面积越大，压差阻力越小", "物体形状越接近流线型，压差阻力越大", "物体的最大迎风面积越大，压差阻力越大"], ans: 2, exp: "压差阻力是由物体在流体中运动时前后压力差异引起的阻力。物体的最大迎风面积越 大，意味着物体前面受到的压力和后面的压力差越大，因此产生的压差阻力也越大。所以，正确的表述是物体的最大迎风面积越大，压差阻力越大。" },
  { id: 1066, cat: "飞行原理2", q: "下列关于诱导阻力的哪种说法是正确的？（）", opts: ["增大机翼的展弦比可以减小诱导阻力", "把暴露在气流中的所有部件和零件都做成流线型，可以减小诱导阻力", "在飞机各部件之间加装整流包皮，可以减小诱导阻力"], ans: 0, exp: "展弦比是机翼展长与平均几何弦长之比。增大机翼展弦比，机翼下洗流的影响会减小，从而诱导阻力减小。这是基于诱导阻力产生原理的，诱导阻力与机翼下洗流密切相关，展弦 比改变会影响下洗流强度，进而影响诱导阻力大小。" },
  { id: 1067, cat: "飞行原理2", q: "下列关于阻力的哪种说法是正确的？（）", opts: ["干扰阻力是由于气流的下洗而引起的", "在飞机各部件之间加装整流包皮可以减小诱导阻力", "干扰阻力是下飞机各部件之间由于气流相互干扰而产生的一种额外阻力"], ans: 2, exp: "干扰阻力是飞机各部件之间由于气流相互干扰而产生的一种额外阻力。例如，飞机的 机翼、机身、尾翼等部件在气流中时，它们之间的气流相互影响，会产生额外的阻力，这个 就是干扰阻力。" },
  { id: 1068, cat: "飞行原理2", q: "下列哪项飞机阻力大小影响不大？（）", opts: ["飞行速度、空气密度、机翼面积", "飞机的翼型和平面形状", "飞机的安装角和上反角"], ans: 2, exp: "飞机的安装角主要影响飞机的俯仰姿态和升力等，上反角主要影响飞机的横向稳定性，它们对飞机阻力大小的影响相对较小。 飞机的阻力大小主要受飞行速度、空气密度、机翼面积、飞机的翼型和平面形状等因素影响。 飞行速度越快、空气密度越大、机翼面积越大，通常阻力也会相应增大。而飞机的翼型和平 面形状会直接影响空气流过飞机时的流动情况，从而影响阻力大小。" },
  { id: 1069, cat: "飞行原理2", q: "下列哪项与飞机诱导阻力大小无关？（）", opts: ["机翼的平面形状", "机翼的翼型", "机翼的根尖比"], ans: 1, exp: "飞机的诱导阻力主要与机翼产生的升力和翼尖涡流有关。机翼的平面形状（如展弦比）和根尖比（即机翼的翼根和翼尖之间的相对大小）都会影响翼尖涡流的强度和分布，从而影 响诱导阻力的大小。而机翼的翼型主要影响的是机翼表面的压力分布和摩擦阻力，对诱导阻 力的影响相对较小。" },
  { id: 1070, cat: "飞行原理2", q: "下列哪种说法是正确的？（）", opts: ["物体的最大迎风面积越大，压差阻力越小", "物体形状越接近流线型，压差阻力越大", "物体的最大迎风面积越大，压差阻力越大"], ans: 2, exp: "压差阻力是由于物体前后压力差产生的阻力，与物体的形状和迎风面积有关。物体的 最大迎风面积越大，意味着与气流接触的面积越大，气流在物体表面的分离点越靠前，导致 物体后部的压力降低更多，从而产生更大的压力差，使得压差阻力增大。因此，物体的最大 迎风面积越大，压差阻力越大。" },
  { id: 1071, cat: "飞行原理2", q: "下列叙述不属于平流层的特点是？（）", opts: ["空气中的风向、风速不变", "温度大体不变，平均在-56.5°C", "空气上下对流激烈"], ans: 2, exp: "平流层的特点包括稳定的大气条件和相对较低的风速，以及温度大体不变。平流层中 空气的垂直对流非常弱，这与对流层中空气上下对流激烈的情况不同。因此，选项“空气上 下对流激烈”不属于平流层的特点，是正确的答案。" },
  { id: 1072, cat: "飞行原理2", q: "下列叙述属于平流层的特点是？（）", opts: ["空气中几乎没有水蒸气", "空气没有上下对流", "高度升高气温下降"], ans: 1, exp: "平流层的特点包括空气没有上下对流，这是因为平流层中的大气运动主要是水平方向 的，垂直方向上的对流非常弱。此外，平流层的温度相对恒定，不会像对流层那样随着高度 升高而下降。因此，选项“空气没有上下对流”是平流层的一个正确特点。" },
  { id: 1073, cat: "飞行原理2", q: "下列叙述与伯努利定理无关的是（）", opts: ["流体流速大的地方压力小，流速小的地方压力大", "气流沿流管稳定流动过程中，气流的动压和静压之和等于常数", "气流低速流动时，流速与流管横截面积成正比"], ans: 2, exp: "伯努利定理指出流体流速大的地方压力小，流速小的地方压力大，同时气流沿流管稳 定流动过程中，气流的动压和静压之和等于常数。而“气流低速流动时，流速与流管横截面 积成正比”这句话与伯努利定理无关，伯努利定理体现的是流速与压力的关系以及动压、静 压之间的关系。" },
  { id: 1074, cat: "飞行原理2", q: "下列正确的是（）", opts: ["飞机的升阻比越大，飞机的空气动力特性越差", "飞机的升阻比越小，飞机的空气动力特性越好", "飞机的升阻比越大，飞机的空气动力特性越好"], ans: 2, exp: "升阻比是衡量飞行器性能的重要指标，它表示单位阻力所能获得的升力大小。飞机的 升阻比越大，意味着在相同阻力下能够产生更大的升力，这直接关系到飞机的爬升性能、续 航能力和燃油效率。因此，飞机的升阻比越大，飞机的空气动力特性越好。" },
  { id: 1075, cat: "飞行原理2", q: "现代民航客机一般巡航的大气层是（）", opts: ["对流层顶层、平流层底层", "平流层顶层", "对流层底层"], ans: 0, exp: "现代民航客机一般巡航的大气层是对流层顶层和平流层底层。这是因为在这个高度范 围内，飞机可以避免对流层中常见的恶劣天气和湍流，同时享有更稳定的大气条件和较低的 空气密度，这有助于提高燃油效率和飞行安全。" },
  { id: 1076, cat: "飞行原理2", q: "亚音速气流流过收缩管道，其流速参数如何变化？（）", opts: ["流速增加，压强增大", "速度降低，压强下降", "流速增加，压强下降"], ans: 2, exp: "亚音速气流流过收缩管道时，根据流体力学原理，流速会增加而压强会下降。这一现 象可以通过连续性方程和能量方程来解释。在亚音速流动条件下，管道截面面积的减小导致 流速增加，同时由于流体的可压缩性较低，密度变化不大，因此压力也随之下降。" },
  { id: 1077, cat: "飞行原理2", q: "一定体积的容器中，空气压力（）", opts: ["与空气密度和空气温度乘积成正比", "与空气密度和空气温度乘积成反比", "与空气密度和空气绝对温度乘积成正比"], ans: 2, exp: "根据理想气体状态方程，在一定体积的容器中，空气压力与空气密度和空气绝对温度 的乘积成正比。空气密度越大、绝对温度越高，压力就会越大。" },
  { id: 1078, cat: "飞行原理2", q: "翼型的最大厚度与弦长的比值称为（）", opts: ["相对弯度", "相对厚度", "最大弯度"], ans: 1, exp: "翼型的最大厚度与弦长的比值称为相对厚度。相对厚度是用来描述翼型形状的重要参 数，通常以百分比的形式表示。它反映了机翼的气动特性，影响升力、阻力和飞行性能。相 对厚度越大，通常意味着机翼的升力特性越好，但也可能增加阻力。" },
  { id: 1079, cat: "飞行原理2", q: "翼型的最大弯度与弦长的比值称为（）", opts: ["相对弯度", "相对厚度", "最大厚度"], ans: 0, exp: "翼型的最大弯度与弦长的比值被定义为相对弯度。相对弯度反映了翼型弯曲的程度。 相对弯度的大小会影响翼型的空气动力性能。较大的相对弯度通常会增加升力，但也可能增 加阻力。" },
  { id: 1080, cat: "飞行原理2", q: "影响翼型性能的最主要的参数是（）", opts: ["前缘和后缘", "翼型的厚度和弯度", "弯度和前缘"], ans: 1, exp: "影响翼型性能的最主要的参数是翼型的厚度和弯度。翼型的厚度决定了翼型的相对厚 度，影响机翼的结构特性和气动效率。弯度则是指翼型的形状，特别是翼型的最大弯度，它 直接影响升力系数和阻力系数。这两个参数共同决定了翼型在不同迎角下的气动特性，包括 升力、阻力和失速特性。" },
  { id: 1081, cat: "飞行原理2", q: "有些飞机的翼尖部位安装了翼梢小翼，它的功用是（）", opts: ["减小摩擦阻力", "减小压差阻力", "减小诱导阻力"], ans: 2, exp: "翼尖小翼功能强，减小诱导阻力量。翼尖小翼的主要作用是减小飞机的诱导阻力。翼 尖小翼通过阻挡机翼下表面的气流绕到上表面，削弱翼尖涡强度，从而有效增大机翼的有效 展弦比。" },
  { id: 1082, cat: "飞行原理2", q: "在大气层内，大气压强（）", opts: ["随高度增加而增加", "随高度增加而减小", "在同温层内随高度增加保持不变"], ans: 1, exp: "在大气层内，随着高度的增加，大气压强会逐渐降低。这是因为大气压力是由大气柱 的重量产生的，而大气柱的重量随着高度的增加而减少。因此，大气压强随高度的增加而递 减。" },
  { id: 1083, cat: "飞行原理2", q: "在机翼表面附面层由层流状态转变为紊流状态的转折点的位置（）", opts: ["将随着飞行速度的提高而后移", "将随着飞行速度的提高而前移 <", "在飞行 M 数小于一定值时保持不变"], ans: 1, exp: "随着飞行速度的提高，机翼表面附面层由层流状态转变内紊流状态的转折点的位置会 前移。这是因为速度提高，气流受到的扰动增强，更容易使层流变为紊流。当飞行速度较低 时，转折点相对靠后，随着速度增加逐渐前移。" },
  { id: 1084, cat: "飞行原理2", q: "在温度不变的情况下，空气的密度与压力的关系（）", opts: ["与压力成正比", "与压力成反比", "与压力无关"], ans: 0, exp: "根据理想气体状态方程，在温度不变的情况下，压强和密度成正比关系。当压力增大 时，分子间的距离会被压缩，单位体积内的分子数量增多，从而导致密度增大；反之，压力 减小时，密度也会减小。" },
  { id: 1085, cat: "飞行原理2", q: "在相同飞行速度和迎角情况下，翼面不清洁或前缘结冰的机翼升力（）", opts: ["大于基本翼型升力", "等于基本翼型升力", "小于基本翼型升力"], ans: 2, exp: "翼面不洁或结冰，升力小于基本型。当翼面不清洁或前缘结冰时，会破坏机翼表面的 气流状态，使气流的流动变得不顺畅，从而减小升力。" },
  { id: 1086, cat: "飞行原理2", q: "在翼型后部产生涡流，会造成（）", opts: ["摩擦阻力增加", "压差阻力增加", "升力增加"], ans: 1, exp: "在翼型后部产生涡流，会造成压差阻力增加。这是因为涡流会导致气流分离，增加气 流的湍流度，从而增加翼型表面的压差阻力。压差阻力是由于翼型上下表面压力差产生的阻 力，涡流的产生使得气流在翼型表面的分离更加剧烈，导致压差阻力增加。" },
  { id: 1087, cat: "飞行原理2", q: "增大飞机机翼的展弦比，目的是减小飞机的（）", opts: ["摩擦阻力", "压差阻力", "诱导阻力"], ans: 2, exp: "展弦比是机翼展长与平均几何弦长之比。增大飞机机翼的展弦比，会使机翼形状变得 更加细长。这样可以减小翼尖涡的强度，从而减小诱导阻力。" },
  { id: 1088, cat: "飞行原理2", q: "增大翼型最大升力系数的两个因素是（）", opts: ["厚度和机翼面积", "弯度和翼展", "厚度和弯度"], ans: 2, exp: "增大翼型最大升力系数的两个因素是厚度和弯度。翼型的最大升力系数受到其厚度和 弯度的影响。厚度较大的翼型通常具有更大的升力系数，因为它们能够产生更大的升力。同 时，翼型的弯度也对最大升力系数有重要影响，适当的弯度可以增加翼型的最大升力系数。" },
  { id: 1089, cat: "飞行原理2", q: "民航飞机常用翼型的特点（）", opts: ["相对厚度 20％到 30％", "相对厚度 10％到 15％", "相对厚度 5%到 10%"], ans: 1, exp: "题目考察民航飞机常用翼型的相对厚度（翼型最大厚度与弦长的比值）。民航翼型设 计需兼顾升力、阻力、结构强度和燃油效率，其相对厚度范围：10%~15%，主流民航飞机（如 波音 737、空客 A320）的机翼相对厚度通常在此范围内。" },
  { id: 1090, cat: "飞行原理2", q: "飞机平飞遇到上升气流，超额负载，下列哪种方式是正确的？（）", opts: ["加速离开", "加大油门", "减少空速"], ans: 2, exp: "遇到上升气流时，飞机的升力会增加，可能导致飞机爬升。减少空速可以降低升力，从而减少飞机的爬升趋势，避免超额负载。" },
  { id: 1091, cat: "飞行原理2", q: "飞机以一定速度逆风起飞时（）", opts: ["升力将减小", "升力将增大", "阻力增大升力减小"], ans: 1, exp: "飞机在一定速度下逆风起飞时，升力会增大。这是因为飞机的升力主要由机翼与空气 相对运动产生，逆风增加了这种相对速度，从而提高了升力。" },
  { id: 1092, cat: "飞行原理2", q: "飞机的最大起飞重量指（）", opts: ["飞机离地时的重量", "飞机开始滑行时的重量（地面上从 A 点移动到 B 点）", "飞机开始起飞滑跑的重量（起飞前加速滑跑）"], ans: 2, exp: "最大起飞重量是指飞机在开始起飞滑跑时的重量，这是飞机在起飞前加速滑跑时的最 大允许重量。" },
  { id: 1093, cat: "飞行原理2", q: "增大飞机机翼的翼弦比，目的是减小飞机的（）", opts: ["压差阻力", "摩擦阻力", "诱导阻力"], ans: 2, exp: "增大飞机机翼的展弦比可以有效减小诱导阻力。诱导阻力是由于机翼产生升力时，翼 尖处的气流绕过翼尖形成涡流，导致能量损失而产生的阻力。增大展弦比可以使机翼更细长，从而减少翼尖涡流的影响，降低诱导阻力。" },
  { id: 1094, cat: "飞行原理2", q: "旋翼无人机一边向前飞，一边爬升，升限会（）", opts: ["上升", "下降", "不变"], ans: 0, exp: "旋翼无人机一边向前飞，一边爬升时，其升限会增加。这是因为升限是指无人机在垂 直方向上能够到达的最大高度，当无人机一边向前飞一边爬升时，其相对高度在增加，因此 升限也会相应增加。" },
  { id: 1095, cat: "飞行原理2", q: "偏转副翼使飞机转弯时，机翼阻力（）", opts: ["使飞机向转弯内侧偏转", "使飞机向转弯外侧偏转", "对飞机的转弯没有影响"], ans: 1, exp: "当偏转副翼使飞机转弯时，升力的水平分量会产生向心力，使飞机向转弯方向偏转。 然而，机翼阻力的方向与飞机的运动方向相反，因此会产生一个向外的力，使飞机有向外侧 偏转的趋势。" },
  { id: 1096, cat: "飞行原理2", q: "飞机接近失速，会（）", opts: ["出现操纵迟钝和操纵效率降低的现象", "出现机头上仰的现象", "出现机翼自转现象"], ans: 0, exp: "飞机接近失速时，会出现操纵迟钝和操纵效率降低的现象。这是因为当飞机接近失速 临界点时，机翼的气流分离可能会导致操纵性能下降，飞机变得不敏感。" },
  { id: 1097, cat: "飞行原理2", q: "飞机离地面（）时，地面效应的影响开始体现出来", opts: ["低于半个翼展", "低于两个翼展", "低于一个翼展"], ans: 0, exp: "地面效应（GroundEffect）是指飞机在接近地面（约低于半个翼展高度）时，机翼下 表面的气流受到地面阻碍，导致升力增加、诱导阻力减小的现象。因此，地面效应的影响通 常在飞机低于半个翼展高度时开始显现。" },
  { id: 1098, cat: "飞行原理2", q: "飞机的焦点位置（）", opts: ["随迎角变化而改变", "不随迎角变化而改变", "随滚转角变化而改变"], ans: 1, exp: "飞机的焦点位置是指飞机上产生升力的点，通常位于机翼的四分之一弦长处。焦点位 置是固定的，不随迎角变化而改变。 其他选项分析如下： 1、随迎角变化而改变：错误。焦点位置是固定的，不会因迎角变化而改变。 2、随滚转角变化而改变：错误。焦点位置是固定的，不会因滚转角变化而改变。" },
  // ==================== 飞行原理3 ====================
  { id: 1099, cat: "飞行原理3", q: "常规布局飞机的主要舵面指的是（）", opts: ["升降舵、方向舵、襟翼", "方向舵、襟翼、缝翼", "升降舵、方向舵、副翼"], ans: 2, exp: "常规布局三舵面，升降方向副翼全。常规布局飞机的主要舵面有升降舵、方向舵和副 翼。升降舵主要控制飞机的俯仰运动，即上升和下降；方向舵控制飞机的偏航运动，也就是 左右转向；副翼控制飞机的滚转运动，使飞机绕机身纵轴旋转。 而襟翼和缝翼主要是用来增加升力和改善起飞着陆性能的，不是主要的控制舵面。" },
  { id: 1100, cat: "飞行原理3", q: "超音速气流经过收缩管道后（）", opts: ["速度增加，压强增大", "速度增加，压强下降", "速度降低，压强增大"], ans: 2, exp: "超音速气流经过收缩管道后，其特性会发生显著变化。原本以超过音速的速度流动，经过管道收缩，气流被迫减速。这种速度的降低导致了一个重要的物理效应，即压强的增大。 因此，正确的描述是速度降低，压强增大。" },
  { id: 1101, cat: "飞行原理3", q: "打开后缘襟翼既能增大机翼切面的弯曲度，又能增加机翼的面积，继而提高飞机的升力 系数，这种襟翼被叫作（）", opts: ["分裂式襟翼", "简单式襟翼", "后退式襟翼"], ans: 2, exp: "后退式襟翼（也称后退开缝襟翼）是一种特殊类型的襟翼，它在展开时不仅增加了机 翼的面积，还通过后退的动作增加了机翼切面的弯曲度。这种设计可以显著提高机翼的升力 系数，因为它同时增加了机翼的弯度和面积，从而在相同的迎角下产生更大的升力。" },
  { id: 1102, cat: "飞行原理3", q: "当后缘襟翼放下时，下述哪项说法正确？（）", opts: ["只增大升力", "只增大阻力", "既增大升力又增大阻力"], ans: 2, exp: "后缘襟翼放下时，同时增加机翼弯度和面积，既增大升力（提高低速操控性）又增大 阻力（降低速度），便于起降。故选 C。" },
  { id: 1103, cat: "飞行原理3", q: "对飞机方向稳定性影响最大的是？（）", opts: ["飞机的最大迎风面积", "水平尾翼", "垂直尾翼"], ans: 2, exp: "对飞机方向稳定性影响最大的是垂直尾翼。垂直尾翼，也称为尾鳍，主要负责提供偏 航稳定性，即控制飞机的左右转向和防止飞机发生偏航摇摆。垂直尾翼的设计和大小直接影 响飞机对侧风的反应以及飞机的航向稳定性。" },
  { id: 1104, cat: "飞行原理3", q: "对于进行定常飞行的飞机来说（）", opts: ["升力一定等于重力", "作用在飞机上的外载荷必定是平衡力系", "发动机推力一定等于阻力"], ans: 1, exp: "对于进行定常飞行的飞机来说，作用在飞机上的外载荷必定是平衡力系。这意味着飞 机上的所有力（包括升力、重力、推力和阻力等）在任意方向上的合力必须为零，以保持飞 机的定常飞行状态，即飞机的速度和高度保持不变。" },
  { id: 1105, cat: "飞行原理3", q: "对于具有静稳定性的飞机，向左侧滑时其机头会（）", opts: ["保持不变", "向左转", "向右转"], ans: 1, exp: "对于具有静稳定性的飞机，当飞机向左侧滑时，飞机的机头会向左转以恢复原来的飞 行姿态。这是因为飞机的静稳定性使得飞机具有自我修正的能力，当飞机偏离原来的飞行轨 迹时，飞机会自动产生恢复力矩，使飞机回到原来的飞行状态。" },
  { id: 1106, cat: "飞行原理3", q: "对于正常布局的飞机，下列叙述正确的是？（）", opts: ["飞机全机的焦点在机翼焦点的前面", "飞机全机的焦点在机翼焦点的后面", "飞机全机的焦点和机翼焦点始终重合"], ans: 1, exp: "对于正常布局的飞机，全机的焦点通常位于机翼焦点的后面。这是因为焦点（气动中 心）是攻角变化时升力增量作用点，而压力中心是升阻力共同的作用点。在飞行中，焦点位 置对于飞行器纵向稳定性至关重要，它决定了飞行器的静稳定性。根据气动原理，焦点在机 翼焦点后面有助于提供飞机的纵向稳定性。" },
  { id: 1107, cat: "飞行原理3", q: "飞机的方向阻尼力矩主要由（）", opts: ["水平尾翼产生", "垂直尾翼产生", "机身产生"], ans: 1, exp: "飞机的方向阻尼力矩主要来源于垂直尾翼（也称为方向舵）。当飞机在飞行中遇到侧 风或进行转弯时，垂直尾翼能够产生相应的阻力，帮助飞机恢复到原来的航向，从而提供方 向稳定性。垂直尾翼的设计和大小直接影响飞机的方向稳定性和操纵性。" },
  { id: 1108, cat: "飞行原理3", q: "飞机的航向稳定性是指飞机绕下列哪个轴线的稳定性？（）", opts: ["横轴", "立轴", "纵轴"], ans: 1, exp: "飞机的航向稳定性是指飞机绕立轴（垂直轴）的稳定性。根据飞行动力学的原理，飞 机在空中飞行时，可以产生俯仰运动、偏航运动和滚转运动。其中，飞机绕立轴的运动为偏 航运动。因此，飞机的航向稳定性是指飞机在受到侧向扰动后，能够自动恢复到原来航向平 衡状态的特性。" },
  { id: 1109, cat: "飞行原理3", q: "飞机的横向和航向稳定性之间（）", opts: ["互相独立", "必须匹配适当", "横向稳定性好，航向稳定性就差"], ans: 1, exp: "飞机的横向稳定性（控制滚转运动）和航向稳定性（控制偏航运动）之间必须匹配适 当。飞机设计时需要确保这两个稳定性之间相互协调，以保证飞机在飞行过程中既能够稳定 地维持其飞行姿态，又能对飞行员的操纵输入做出适当的响应。 横向稳定性过强可能导致飞机过于迟钝，而航向稳定性过强可能导致飞机对偏航控制过于敏 感。" },
  { id: 1110, cat: "飞行原理3", q: "飞机的横向稳定性是指飞机绕下列哪个轴线的稳定性？（）", opts: ["横轴", "纵轴", "偏航轴"], ans: 1, exp: "飞机的横向稳定性是指飞机绕纵轴的稳定性，纵轴是飞机从前到后的轴线。横向稳定 性涉及飞机的滚转运动，即飞机机翼左右倾斜的程度。如果横向稳定性好，飞机在受到扰动 后能够自动恢复到原来的飞行姿态。" },
  { id: 1111, cat: "飞行原理3", q: "飞机的横向阻力力矩主要由（）", opts: ["水平尾翼产生", "垂直尾翼产生", "机翼产生"], ans: 2, exp: "飞机的横向阻尼力矩主要由机翼产生。在飞行中，当飞机发生滚转运动时，机翼的气 流动力会发生变化，产生阻止飞机继续滚转的力矩，这种力矩称为横向阻尼力矩。虽然垂直 尾翼和水平尾翼也对飞机的稳定性有所贡献，但机翼是产生横向阻尼力矩的主要来源。" },
  { id: 1112, cat: "飞行原理3", q: "飞机的爬升角是指（）", opts: ["飞机上升轨迹与水平线之间的夹角", "飞机立轴与水平线之间的夹角", "飞机横轴与水平线之间的夹角"], ans: 0, exp: "飞机的爬升角是指飞机上升轨迹与水平线之间的夹角。可以想象一下，当飞机在爬升 时，它的飞行轨迹不是完全水平的，而是有一定的倾斜角度向上飞行，这个倾斜的角度就是 爬升角。" },
  { id: 1113, cat: "飞行原理3", q: "飞机的重心位置对飞机的（）", opts: ["纵向稳定性产生影响", "方向稳定性产生影响", "横向稳定性产生影响"], ans: 0, exp: "飞机的重心位置对飞机的纵向稳定性产生影响。 具体分析如下： 1、纵向稳定性：飞机的重心位置主要影响其纵向稳定性。重心位置过前或过后都会改变飞 机的俯仰平衡和稳定性。例如，重心过前可能导致飞机过于稳定，难以操纵；重心过后可能 导致飞机不稳定，容易失速。 2、方向稳定性：主要与飞机的垂直尾翼设计有关，重心位置对其影响较小。 3、横向稳定性：主要与飞机的机翼设计和横向控制面（如副翼）有关，重心位置对其影响 也较小。" },
  { id: 1114, cat: "飞行原理3", q: "飞机的重心位置对飞机的哪个稳定性有影响？（）", opts: ["纵向稳定性和航向稳定性", "只对纵向稳定性", "横向稳定性"], ans: 0, exp: "飞机的重心位置对飞机的稳定性有重要影响。根据飞行原理，飞机的重心必须位于焦 点之前以保持纵向静稳定性。此外，飞机的重心位置也会影响航向稳定性，因为重心位置的 变化会影响「飞机对侧风的反应和方向舵的效率。因此，飞机的重心位置同时影响着飞机的 纵向稳定性和航向稳定性。" },
  { id: 1115, cat: "飞行原理3", q: "飞机的重心位置影响飞机的（）", opts: ["纵向稳定性", "方向稳定性", "横向稳定性"], ans: 0, exp: "飞机的重心位置对飞机的纵向稳定性有直接影响。纵向稳定性涉及飞机的俯仰运动，即飞机围绕横轴的稳定性。重心位置靠前会增加飞机的纵向稳定性，使飞机更倾向于自动恢 复到水平飞行状态，但可能会降低飞机的操纵性。相反，重心位置靠后会降低飞机的纵向稳 定性，使得飞机更容易受到扰动影响，需要飞行员更多的操纵来维持稳定。" },
  { id: 1116, cat: "飞行原理3", q: "飞机的纵向和航向稳定性之间（）", opts: ["互相独立", "必须匹配适当", "纵向稳定性好，航向稳定性就差"], ans: 0, exp: "飞机的纵向稳定性（俯仰）和航向稳定性（偏航）由不同气动面和控制系统独立控制，两者互不影响，因此互相独立。" },
  { id: 1117, cat: "飞行原理3", q: "飞机的纵向稳定性是指飞机绕下列哪个轴线的稳定性？（）", opts: ["横轴", "立轴", "纵轴"], ans: 0, exp: "飞机的纵向稳定性是指飞机绕横轴的稳定性。横轴是飞机从一侧到另一侧的轴线，纵 向稳定性涉及飞机的俯仰运动，即飞机机头的上下运动。" },
  { id: 1118, cat: "飞行原理3", q: "飞机飞行的俯仰角为（）", opts: ["飞机纵轴与飞行速度向量的夹角", "飞机纵轴与水平面的夹角", "飞行速度与水平面的夹角"], ans: 1, exp: "飞机飞行的俯仰角是指飞机纵轴与水平面的夹角。这个角度描述了飞机在垂直方向上 的倾斜程度，是飞行姿态的一个重要参数。俯仰角的大小直接影响飞机的升力和阻力，以及 飞机的爬升和下降。" },
  { id: 1119, cat: "飞行原理3", q: "飞机飞行中，空气表现出来的可压缩程度（）", opts: ["只取决于飞机的飞行速度（空速）", "只取决于飞机飞行当地的音速", "和飞机飞行的速度（空速）以及当地的音速有关"], ans: 2, exp: "飞机飞行中空气表现出来的可压缩程度与飞机的飞行速度（空速）以及当地的音速有 关。当飞机的飞行速度接近或超过音速时，空气的可压缩性变得显著，对飞机的气动特性产 生重要影响。因此，飞机设计和飞行中必须考虑空气的可压缩性，尤其是在高速飞行时。" },
  { id: 1120, cat: "飞行原理3", q: "飞机航向稳定性是指飞机受到侧风扰动后（）", opts: ["产生绕立轴转动，扰动消失后转角自动回到零", "产生绕立轴转动，扰动消失后自动恢复原飞行姿态", "产生绕横轴转动，扰动消失后转角自动回到零"], ans: 1, exp: "飞机航向稳定性是指飞机在受到侧风扰动后，会产生绕立轴（即飞机的垂直轴）的转 动。如果飞机具有良好的航向稳定性，那么在扰动消失后，飞机能够自动恢复到原来的飞行 姿态，不需要额外的操纵输入。这意味着飞机能够抵抗侧风的影响，并在扰动过后自动回到 原来的航向。" },
  { id: 1121, cat: "飞行原理3", q: "飞机横向平衡中的滚转力矩主要包括（）", opts: ["机翼阻力力矩", "机翼升力力矩", "水平尾翼力矩"], ans: 1, exp: "横向平衡看滚转，升力不同力矩变。飞机横向平衡中的滚转力矩主要包括机翼升力力 矩。这是因为飞机的滚转力矩主要由两侧机翼产生的升力差异引起，当一侧机翼的升力大于 另一侧时，就会产生滚转力矩，导致飞机绕纵轴旋转。因此，正确答案是机翼升力力矩。" },
  { id: 1122, cat: "飞行原理3", q: "飞机横向稳定性是指飞机受到扰动后（）", opts: ["产生绕纵轴转动，扰动消失后转角自动回到零", "产生绕纵轴转动，扰动消失后自动恢复原飞行姿态", "产生绕横轴转动，扰动消失后转角自动回到零"], ans: 1, exp: "飞机横向稳定性是指飞机受到扰动后产生绕纵轴转动的情况，当扰动消失后，飞机能 够自动恢复原飞行姿态。" },
  { id: 1123, cat: "飞行原理3", q: "飞机机翼的焦点指的是（）", opts: ["升力的着力点", "附加升力的着力点", "重力的着力点"], ans: 1, exp: "飞机机翼的焦点指的是在一定雷诺数下，当翼型迎角改变时，翼型所受到的空气动力 对于此点的合力矩不变的点。因此，正确答案是附加升力的着力点。这个焦点位置对于飞行 器纵向稳定性至关重要，它决定了飞机气动力增量的作用点。" },
  { id: 1124, cat: "飞行原理3", q: "飞机焦点的位置（）", opts: ["随仰角变化而改变", "不随仰角变化而改变", "随滚转角变化而改变"], ans: 1, exp: "飞机焦点的位置不随仰角变化而改变。焦点是飞机气动中心的一个特性点，它的位置 相对于机翼或其他气动面是固定的，不会因为飞机的仰角或滚转角的变化而改变。这个固定 的位置对于飞机的稳定性和操控性分析非常重要。" },
  { id: 1125, cat: "飞行原理3", q: "飞机进行匀速俯冲拉起飞行，则（）", opts: ["速度不发生变化", "是在平衡外载荷作用下进行的飞行", "飞行速度方向的变化是由于存在着向心力"], ans: 2, exp: "飞机进行匀速俯冲拉起飞行时，其速度的大小可能保持不变，但方向会发生变化，这 是因为飞机在进行圆周运动时需要向心力来维持其沿曲线路径的飞行。在拉起过程中，飞机 的速度方向改变，而向心力正是导致这种方向变化的原因。" },
  { id: 1126, cat: "飞行原理3", q: "飞机离地速度越小，则（）", opts: ["滑跑距离越短，飞机的起飞性能越好", "滑跑距离越短，飞机的起飞性能越差", "滑跑距离越长，飞机的起飞性能越好"], ans: 0, exp: "飞机离地速度越小，意味着飞机在起飞过程中需要的滑跑距离越短，这通常表示飞机 的起飞性能越好。起飞性能好意味着飞机能够在更短的时间内达到足够的升力，从而更安全、更有效地离开地面。" },
  { id: 1127, cat: "飞行原理3", q: "飞机爬升角的大小取决于（）", opts: ["剩余推力", "飞机重量", "剩余推力和飞机重量"], ans: 2, exp: "飞机爬升角的大小取决于多个因素，其中包括剩余推力和飞机重量。剩余推力指的是 飞机发动机产生的推力与飞机阻力之间的差值，这个差值越大，飞机的爬升性能越好。同时，飞机的重量也直接影响爬升角，重量越轻，飞机爬升时需要克服的重力越小，因此爬升角也 越大。因此，飞机爬升角的大小是由剩余推力和飞机重量共同决定的。" },
  { id: 1128, cat: "飞行原理3", q: "飞机平飞航程的长短（）", opts: ["决定于平飞可用燃油量多少", "决定于平飞的高度", "决定于发动机小时耗油量的大小"], ans: 0, exp: "飞机平飞航程的长短主要取决于平飞可用燃油量多少。这是因为飞机的航程直接与携 带的燃油量和发动机的耗油率相关。" },
  { id: 1129, cat: "飞行原理3", q: "飞机平飞时保持等速飞行的平衡条件是（）", opts: ["升力等于重力，推力等于重力", "升力等于重力，推力等于阻力", "升力等于阻力，推力等于重力"], ans: 1, exp: "飞机在平飞时要保持等速飞行，需要满足两个平衡条件：一是升力等于重力，以保持 飞机在空中的垂直位置；二是推力等于阻力，以保持飞机在水平方向上的速度不变。这样，飞机既不上升也不下降，既不加速也不减速，实现等速平飞。" },
  { id: 1130, cat: "飞行原理3", q: "飞机平飞要有足够的升力来平衡飞机的重力，产生该升力所需的速度叫作（）", opts: ["飞机平飞所需速度", "飞机平飞有利速度", "飞机平最大速度"], ans: 0, exp: "飞机平飞时需要足够的升力来平衡其重力，以保持飞机在空中的稳定位置。产生这个 所需升力的速度被称为飞机平飞所需速度。这个速度确保飞机在水平飞行时，升力与重力相 等，从而使飞机能够维持在一个稳定的飞行高度。" },
  { id: 1131, cat: "飞行原理3", q: "飞机起飞时后缘襟翼放下的角度小于着陆时放下的角度是因为（）", opts: ["后缘襟翼放下角度比较小时，机翼的升力系数增加，阻力系数不增加", "后缘襟翼放下角度比较大时，机翼的阻力系数增加，升力系数不增加", "后缘襟翼放下角度比较小时，机翼的升力系数增加的效果大于阻力系数增加的效果"], ans: 2, exp: "飞机起飞时后缘襟翼放下的角度小于着陆时放下的角度是因为在起飞过程中，襟翼主 要起到增加升力的作用，而不需要像着陆时那样同时增加升力和阻力以减速。起飞时襟翼放 下角度较小，可以减少阻力，避免影响飞机起飞滑跑时的加速。 因此，起飞时襟翼放下角度小于着陆时放下的角度，是为了优化起飞性能，减少起飞距离。" },
  { id: 1132, cat: "飞行原理3", q: "飞机绕横轴的稳定性为（）", opts: ["纵向稳定性", "航向稳定性", "横向稳定性"], ans: 0, exp: "飞机绕横轴的稳定性称纵向稳定性。横轴是飞机从机头到机尾的轴线，纵向稳定性涉 及飞机的俯仰运动，即飞机机头的上下运动。如果飞机具有良好的纵向稳定性，那么在受到 扰动后，飞机能够自动恢复到原来的飞行姿态。" },
  { id: 1133, cat: "飞行原理3", q: "飞机绕立轴的稳定性称为（）", opts: ["纵向稳定性", "航向稳定性", "横向稳定性"], ans: 1, exp: "飞机绕立轴的稳定性称为航向稳定性。航向稳定性是指飞机受到侧滑扰动后，如果能 产生使机头指向原来方向的力矩，抵消侧滑，则称为航向静稳定性。飞机的航向稳定性等于 各独立部件的贡献和，包括机翼、机身和尾翼等。" },
  { id: 1134, cat: "飞行原理3", q: "飞机绕纵轴的稳定性称为（）", opts: ["纵向稳定性", "航向稳定性", "横向稳定性"], ans: 2, exp: "飞机绕纵轴的稳定性称为横向稳定性。纵轴是飞机从一侧到另一侧的轴线，横向稳定 性涉及飞机的滚转运动，即飞机左右翼的倾斜程度。如果飞机具有良好的横向稳定性，那么 在受到扰动后，飞机能够自动恢复到原来的飞行姿态，维持水平飞行。" },
  { id: 1135, cat: "飞行原理3", q: "飞机下滑距离（）", opts: ["与下滑高度有关", "与下滑角无关", "与下滑高度无关"], ans: 0, exp: "飞机的下滑距离与其下滑高度有直接关系。下滑高度越高，飞机在下滑过程中可以飞 行的水平距离就越远。这是因为飞机在下滑过程中遵循能量守恒定律，下滑高度转换为水平 飞行的动能，从而影响飞机的下滑距离。" },
  { id: 1136, cat: "飞行原理3", q: "飞机在 Y 方向上“过载”是指（）", opts: ["机升力与机重力的比值", "飞机升力与飞机阻力的比值", "飞机推力与飞机阻力的比值"], ans: 0, exp: "飞机在 y 方向上的“过载”通常指的是飞机升力与飞机重力的比值。过载是描述飞机 受到的加速度与重力加速度之比的物理量，它反映了飞机在垂直方向上的受力情况。当飞机 升力大于其重力时，会产生正过载；反之，如果飞机受到的向下的力大于其重力，会产生负 过载。" },
  { id: 1137, cat: "飞行原理3", q: "飞机在对流层中匀速爬升时，随着飞行高度的增加，飞机飞行马赫数（）", opts: ["保持不变", "逐渐增加", "逐渐减小"], ans: 1, exp: "飞机在对流层中匀速爬升时，随着飞行高度的增加，飞机飞行马赫数会逐渐增加。这 是因为马赫数是飞机速度与该高度远前方未受扰动的空气中的音速的比值。随着高度的增加，大气压力和温度降低，导致该高度的音速降低。由于飞机保持匀速爬升，其速度相对于音速 的比例（即马赫数）会随着音速的降低而增加。" },
  { id: 1138, cat: "飞行原理3", q: "飞机在飞行中出现的失速现象的原因是（）", opts: ["翼梢出现较强的旋涡，产生很大的诱导阻力", "由于迎角达到临界迎角，造成机翼上表面附面层大部分分离", "由于机翼表面粗糙，使附面层由层流变 紊流"], ans: 1, exp: "飞机失速现象的原因是因为迎角超过临界迎角，导致机翼上表面附面层大部分分离，从而造成升力急剧下降而不能保持正常飞行的现象。这种现象通常发生在飞机的迎角过大时，气流无法平滑地流过机翼表面，导致机翼失去升力。" },
  { id: 1139, cat: "飞行原理3", q: "飞机在空中飞行时，如果飞机处于平衡状态，那么（）", opts: ["作用在飞机上的所有外力平衡，所有外力矩也平衡", "作用在飞机上的所有外力不平衡，所有外力矩平衡", "作用在飞机上的所有外力平衡，所有外力矩不平衡"], ans: 0, exp: "飞机在空中飞行时，如果飞机处于平衡状态，那么作用在飞机上的所有外力平衡，所 有外力矩也平衡。这意味着飞机所受的合外力为零，合外力矩也为零，飞机既不加速也不减 速，不发生旋转或改变飞行姿态。这是飞机进行稳定飞行的基本条件。" },
  { id: 1140, cat: "飞行原理3", q: "飞机着陆的过程是（）", opts: ["减速下滑、拉平接地和减速滑跑三个阶段", "下滑、拉平、平飘、接地和着陆滑跑五个阶段", "下滑、拉平、接地、着陆滑跑和刹车五个阶段"], ans: 1, exp: "飞机着陆的过程通常包括五个阶段：下滑、拉平、平飘、接地和着陆滑跑。这个过程 确保飞机从空中安全地降落到跑道上，并最终停下来。" },
  { id: 1141, cat: "飞行原理3", q: "飞机着陆时使用后缘襟翼的作用是（）", opts: ["提高飞机的操纵灵敏性", "增加飞机的稳定性", "增加飞机的升力"], ans: 2, exp: "飞机着陆时使用后缘襟翼的作用是增加飞机的升力。后缘襟翼通过增加机翼的弯度，从而增加机翼上下表面的压力差，进而增加升力。这样可以在较低的速度下保持飞机的升力，帮助飞机更平稳地降落。" },
  { id: 1142, cat: "飞行原理3", q: "飞机重心位置的表示方法是（）", opts: ["用重心到平均气动力弦前缘的距离和平均气动力弦长之比的百分数来表示", "用重心到平均几何弦后缘的距离和平均几何弦长之比的百分数来表示", "用重心到机体基准面的距离和平均气动力弦长之比的百分数来表示"], ans: 0, exp: "飞机重心位置的表示方法是用重心到平均气动力弦前缘的距离和平均气动力弦长之比 的百分数来表示。这种方法可以精确地确定飞机重心相对于机翼的位置，对于飞机设计和性 能分析非常重要。" },
  { id: 1143, cat: "飞行原理3", q: "飞机纵稳定性是指飞机受到上下对流扰动后（）", opts: ["产生绕立轴转动，扰动消失后转角自动回到零", "产生绕横轴转动，扰动消失后俯仰角自动回到零", "产生绕横轴转动，扰动消失后自动恢复原飞行姿态"], ans: 2, exp: "飞机纵稳定性是指飞机在受到上下对流扰动后，能够自动恢复到原来的飞行姿态的能 力。这种稳定性涉及飞机绕横轴的转动，即飞机的俯仰运动。如果飞机具有良好的纵稳定性，那么在扰动消失后，飞机不需要额外的操纵输入就能自动恢复到原来的俯仰角，维持稳定的 飞行。" },
  { id: 1144, cat: "飞行原理3", q: "飞机纵向阻尼力矩的产生主要（）", opts: ["由后掠机翼产生的", "由垂直尾翼产生的", "由水平尾翼产生的"], ans: 2, exp: "飞机纵向阻尼力矩的产生主要来源于水平尾翼。在飞机的俯仰运动中，水平尾翼上的 气动力变化会产生与飞机俯仰运动方向相反的力矩，这个力矩起到阻尼飞机俯仰摆动的作用，帮助飞机恢复到原来的平衡状态。" },
  { id: 1145, cat: "飞行原理3", q: "飞机做等速直线水平飞行时，作用在飞机上的外载荷应满足（）", opts: ["升力等于重力，推力等于阻力", "升力等于重力，抬头力矩等于低头力矩", "升力等于重力，推力等于阻力，抬头力矩等于低头力矩"], ans: 2, exp: "飞机在进行等速直线水平飞行时，作用在飞机上的外载荷需要满足三个条件以保持飞 机的平衡状态。首先，升力必须等于重力以保持飞机在空中的垂直位置不变；其次，推力必 须等于阻力以保持飞机在水平方向上的速度不变；最后，抬头力矩必须等于低头力矩以保持 飞机的俯仰平衡。这三个条件共同确保了飞机能够稳定地进行等速直线水平飞行。" },
  { id: 1146, cat: "飞行原理3", q: "飞行侧滑角为（）", opts: ["飞机纵轴与水平面的夹角", "飞行速度与水平面的夹角", "空速向量与飞机对称面的夹角"], ans: 2, exp: "飞行侧滑角是指飞机的空速向量与飞机对称面（通常是飞机的纵轴）之间的夹角。这 个角度反映了飞机在水平面上的侧向位移，是飞行中的一个重要参数，特别是在进行精确导 航和控制时。" },
  { id: 1147, cat: "飞行原理3", q: "根据机翼升力和阻力计算机公式可以得出，通过增大机翼面积来增大升力的同时（）", opts: ["阻力不变", "阻力减小", "阻力也随着增大"], ans: 2, exp: "根据机翼升力和阻力的计算公式，升力和阻力都与机翼面积成正比。因此，通过增大 机翼面积来增大升力的同时，阻力也会随之增大。这是因为机翼面积的增加会导致与空气接 触的表面积增加，从而增加了空气对机翼的阻力。" },
  { id: 1148, cat: "飞行原理3", q: "关于飞机失速下列说法哪些是正确的？（）", opts: ["飞机失速是通过加大发动机动力就可以克服的飞行障碍", "亚音速飞行只会出现大迎角失速", "在大迎角或高速飞行状态下都可能出现飞机失速现象"], ans: 2, exp: "飞机失速是指飞机或机翼的迎角大于最大升力的迎角时飞机状态，所产生的最直接后 果就是机翼无法再继续产生升力，导致飞机失控。失速并非仅由单一因素引起，它可以在大 迎角或高速飞行状态下出现，且不仅限于亚音速飞行中的大迎角失速。因此，飞机失速是一 个复杂的飞行现象，需要飞行员具备专业的知识和技能来预防和处理。" },
  { id: 1149, cat: "飞行原理3", q: "焦点在重心之后，焦点位置向后移（）", opts: ["增加纵向稳定性", "提高纵向操纵性", "减小纵向稳定性"], ans: 0, exp: "焦点后移稳增强，纵向稳定会变好。焦点在重心之后意味着飞机的气动中心位于重心 的后面。在这种情况下，飞机的纵向稳定性会增加。这是因为当飞机受到扰动导致机头上扬 时，气动中心在重心之后的布局会使得飞机产生一个低头的力矩，帮助飞机恢复到原来的平 衡状态。因此，焦点位置向后一挥增加飞机的纵向稳定性。" },
  { id: 1150, cat: "飞行原理3", q: "焦点在重心之后，向后移焦点，飞机的（）", opts: ["操纵性与此无关", "操纵性增强", "操纵性减弱"], ans: 2, exp: "焦点在重心之后，如果焦点位置向后移动，飞机的操纵性会减弱。这是因为焦点位置 对飞机的纵向稳定性有重要影响。焦点靠后会增加飞机的纵向稳定性，但同时也会降低飞机 对操纵输入的响应速度，使得飞机的操纵性变差。飞机变得更加稳定，但相对不那么灵敏。" },
  { id: 1151, cat: "飞行原理3", q: "利用增大机翼弯度来提高机翼的升力系数，会导致（）", opts: ["机翼上表面最低压力点前移，减小临界迎角", "机翼上表面最低压力点后移，减小临界迎角", "机翼上表面最低压力点前移，加大临界迎角"], ans: 0, exp: "利用增大机翼弯度来提高机翼的升力系数，会导致机翼上表面最低压力点前移，减小 临界迎角。这是因为机翼弯度的增加使得机翼上表面的气流速度更快，压力更低，从而使得 气流更容易在机翼上表面分离，导致临界迎角减小。" },
  { id: 1152, cat: "飞行原理3", q: "描述飞机在空间姿态的姿态角有（）", opts: ["迎角，偏航角，滚转角", "滚转角，偏航角，俯仰角", "俯仰角，侧滑角，滚转角"], ans: 1, exp: "飞机姿态角描述其在空间的旋转状态，滚转角（绕纵轴）、偏航角（绕立轴）、俯仰角 （绕横轴）分别对应左右倾斜、方向改变和抬头低头运动。侧滑角与迎角属于气流参数，非 姿态角。" },
  { id: 1153, cat: "飞行原理3", q: "前缘缝翼的功用有（）", opts: ["增大机翼的安装角", "增加飞机的稳定性", "增大最大升力系数"], ans: 2, exp: "前缘缝翼主要是在飞机起飞和降落等低速飞行阶段使用。它的作用是通过改变机翼的 气流状况，延缓气流分离，从而增大机翼的升力系数，使飞机在较低的速度下也能获得足够 的升力。" },
  { id: 1154, cat: "飞行原理3", q: "前缘缝翼的主要作用是（）", opts: ["放出前缘缝翼，可增大飞机的临界迎角", "增大机翼升力", "减小阻力"], ans: 0, exp: "前缘缝翼的主要作用是放出前缘缝翼，可增大飞机的临界迎角。前缘缝翼是一种安装 在机翼前缘的小翼面，它通过增加机翼表面的气流附着性，延迟气流分离，从而提高飞机的 临界迎角。这意味着飞机可以在更大的迎角下飞行而不会失速，提高了飞机的机动性和安全 性。" },
  { id: 1155, cat: "飞行原理3", q: "使飞机绕横轴转动的力矩称为（）", opts: ["倾斜力矩", "俯仰力矩", "滚转力矩"], ans: 1, exp: "使飞机绕横轴转动的力矩称为俯仰力矩。俯仰力矩是指飞机在飞行过程中，因升降舵 的操作或气流变化而导致的机头上下运动的力矩。俯仰力矩的大小与飞机的重心位置、升力 的分布以及舵面的偏转角度等因素有关。" },
  { id: 1156, cat: "飞行原理3", q: "使飞机绕立轴作旋转运动的力矩称为（）", opts: ["俯仰力矩", "纵向力矩", "偏航力矩"], ans: 2, exp: "使飞机绕立轴作旋转运动的力矩称为偏航力矩。立轴是垂直通过飞机重心的轴，飞机 绕这个轴的旋转运动称为偏航或航向旋转。偏航力矩是由飞机的垂直尾翼产生的，它控制飞 机的航向，使飞机能够向左或向右转弯。" },
  { id: 1157, cat: "飞行原理3", q: "使飞机绕纵轴产生侧倾的力矩称为（）", opts: ["俯仰力矩", "偏航力矩", "滚转力矩"], ans: 2, exp: "使飞机绕纵轴产生侧倾的力矩称为滚转力矩。滚转力矩是指飞机在飞行过程中，因副 翼的操作或气流变化而导致的左右翼尖上下运动的力矩。这种力矩会使飞机发生滚转运动，即飞机沿着纵轴旋转，一侧翼尖抬起而另一侧翼尖下降。" },
  { id: 1158, cat: "飞行原理3", q: "使用机翼后缘襟翼提高升力系数的同时临界迎角减小的主要原因是（）", opts: ["放下后缘襟翼时，增大了机翼的弯度", "放下后缘襟翼时、增大了机翼的面积", "放下后缘襟翼时，在上下翼面之间形成了缝隙"], ans: 0, exp: "当放下机翼后缘襟翼时，会增大机翼的弯度。机翼弯度增加后，上表面气流流速加快，下表面气流流速相对变慢，从而使上下表面压力差增大，升力系数提高。但同时，由于机翼 弯度增大，气流在机翼上表面更容易分离，所以临界迎角会减小。增大机翼面积主要是增加 升力的大小，但对临界迎角的影响相对较小；上下翼面之间形成缝隙不是临界迎角减小的主 要原因。" },
  { id: 1159, cat: "飞行原理3", q: "使用扰流板操纵飞机向左盘旋时，下述哪项说法正确？（）", opts: ["左机翼飞行扰流板向上打开，右机翼飞行扰流板向上打开", "左机翼飞行扰流板向上打开，右机翼飞行扰流板不动", "左机翼飞行扰流板不动，右机翼飞行扰流板向上打开"], ans: 1, exp: "使用扰流板操纵飞机向左盘旋时，正确的做法是左机翼的飞行扰流板向上打开，而右 机翼的飞行扰流板保持不动。飞行扰流板（也称为减速板或破坏板）的主要作用是增加阻力 和减少升力，从而帮助飞机减速和下降。在进行盘旋机动时，通过在转弯方向的机翼上打开 扰流板，可以增加该侧的阻力，使飞机向该方向倾斜，实现转弯。" },
  { id: 1160, cat: "飞行原理3", q: "属于减升装置的辅助操纵面是（）", opts: ["扰流扳", "副翼", "前缘缝翼"], ans: 0, exp: "属于减升装置的辅助操纵面是扰流板。扰流板的主要作用是在飞机降落或减速时，增 加阻力并减少升力，从而帮助飞机降低速度和高度，确保安全着陆。与此相对，副翼和前缘 缝翼主要用于增加升力和改善飞机的操控性能。" },
  { id: 1161, cat: "飞行原理3", q: "属于增升装置的辅助操纵面是（）", opts: ["扰流板", "副翼", "前缘襟翼"], ans: 2, exp: "增升装置是指在飞机飞行中用于增加升力的装置。前缘襟翼是典型的增升装置，通过 改变机翼的气动特性，增加机翼的升力系数，使飞机在低速飞行或高迎角飞行时能够保持稳 定的升力。" },
  { id: 1162, cat: "飞行原理3", q: "同架同样重量的飞机（）", opts: ["在高原机场降落比在平原机场降落需要的跑道短", "在高原机场降落比在平原机场降落需要的跑道长", "在高原机场降落和在平原机场降落需要的跑道一样长"], ans: 1, exp: "同架同样重量的飞机在高原机场降落比在平原机场降落需要的跑道长。这是因为高原 地区空气稀薄，空气密度低，导致飞机升力降低，需要更好的跑道来确保飞机能够安全降落。" },
  { id: 1163, cat: "飞行原理3", q: "无人机能获得平飞航程最长的速度是（）", opts: ["飞机平飞有利速度", "飞机平最大速度", "飞机平飞远航速度"], ans: 2, exp: "无人机能获得平飞航程最长的速度是飞机平飞远航速度。这是因为在特定的飞行速度 下，无人机的燃油效率最高，能够实现最远的航程。这个速度通常低于飞机的最大速度，但 高于飞机的巡航速度，是飞机在长时间飞行时为了节省燃油和延长航程而选择的最佳速度。" },
  { id: 1164, cat: "飞行原理3", q: "无人机能获得平飞航时最长的速度是（）", opts: ["飞机平飞所需速度", "飞机平飞有利速度", "飞机平飞最大速度"], ans: 1, exp: "无人机能获得平飞航程最长的速度是飞机平飞有利速度。这个速度也被称为经济速度 或最佳 L/D（升阻比）速度，是指在给定的飞行条件下，无人机能够实现最大航程的速度。 在这个速度下，无人机的升力与阻力之比达到最优，从而使得燃油效率最高，航程最远。" },
  { id: 1165, cat: "飞行原理3", q: "下列关于扰流板的叙述哪项说法是错误的？（）", opts: ["扰流板可作减速板缩短飞机滑跑距离", "可辅助副翼实现飞机横向操纵", "可代替副翼实现飞机横向操纵"], ans: 2, exp: "扰流板不能代替副翼实现飞机横向操纵。副翼主要是通过改变机翼的升力分布来实现 飞机的横向操纵，而扰流板只是起到辅助和增加阻力等作用，不能完全替代副翼的功能，这 个说法是错误的。" },
  { id: 1166, cat: "飞行原理3", q: "下列哪项不是飞机飞行时所受的外载荷？（）", opts: ["重力", "气动力", "惯性力"], ans: 2, exp: "惯性力并不是飞机飞行时所受的外载荷，而是机内部物体由于其质量而具有的抵抗加 速度变化的性质，它是由飞机的运动状态变化引起的内部力。飞机飞行时所受的外载荷主要 包括重力和气动力。重力是地球对飞机的吸引力，而气动力包括升力和阻力，是飞机与空气 相对运动时空气对飞机的作用力。" },
  { id: 1167, cat: "飞行原理3", q: "下列哪种变化情况肯定会增加飞机方向的稳定性？（）", opts: ["增加机翼面积", "增加垂直尾翼面积", "增加水平尾翼面积"], ans: 1, exp: "飞机的方向静稳定性主要由垂直尾翼来保证。增加垂直尾翼的面积可以增加飞机垂直 尾部受到的气流影响，从而增强其绕垂直轴的稳定性，使飞机更能保持飞行方向。因此，增 加垂直尾翼面积肯定会增加飞机的方向静稳定性。" },
  { id: 1168, cat: "飞行原理3", q: "下列哪种变化情况肯定会增加飞机纵向的稳定性？（）", opts: ["增加机翼面积", "增加垂直尾翼面积", "增加水平尾翼面积"], ans: 2, exp: "飞机的纵向静稳定性主要与水平尾翼的面积和位置有关。水平尾翼的作用是提供俯仰 力矩，帮助飞机恢复到原来的俯仰姿态。增加水平尾翼的面积可以增强这种恢复力矩，从而 提高飞机的纵向静稳定性。" },
  { id: 1169, cat: "飞行原理3", q: "下列叙述错误的是（）", opts: ["飞机焦点位于飞机重心之后有利于飞机的纵向安定性", "飞机焦点位于飞机重心之前有利于飞机的纵向安定性", "飞机的重心位置与飞机的装载情况有关，与飞机的飞行状态无关"], ans: 1, exp: "飞机的焦点（气动中心）相对于重心的位置对飞机的纵向稳定性有重要影响。如果焦 点位于重心之后，飞机的纵向稳定性会增加，因为这样会使得飞机在遇到扰动时产生一个恢 复原状的力矩。相反，如果焦点位于重心之前，飞机的纵向稳定性会降低，因这样会使得飞 机在遇到扰动时产生一个远离原状的力矩。因此，选项“飞机焦点位于飞机重心之前有利于 飞机的纵向安定性”是错误的。" },
  { id: 1170, cat: "飞行原理3", q: "下列叙述与飞机的正常盘旋飞行无关的是（）", opts: ["保持飞行高度不变", "保持飞机作圆周飞行", "保持飞机等速直线飞行"], ans: 2, exp: "飞机正常盘旋飞行时，是在做圆周飞行，同时通常要保持飞行高度不变。而保持飞机 等速直线飞行与盘旋飞行的状态完全不同，因此盘旋飞行不是等速直线飞行状态。" },
  { id: 1171, cat: "飞行原理3", q: "亚音速气流经过收缩管道后（）", opts: ["速度增加，压强增大", "速度降低，压强下降", "速度增加，压强下降"], ans: 2, exp: "亚音速气流经过收缩管道后，根据流体力学中的连续性原理和伯努利方程，管道收缩 处横截面积减小会导致气流速度增加，同时压力下降。这是因为在没有质量添加或损失的理 想流体流动中，流速的增加必须伴随着压力的降低，以保持能量守恒。" },
  { id: 1172, cat: "飞行原理3", q: "研究飞机运动时选用的机体坐标，其（）", opts: ["以飞机重心为原点，纵轴和横轴确定的平面为对称面", "以全机焦点为原点，纵轴和立轴确定的平面为对称面", "以飞机重心为原点，纵轴和立轴确定的平面为对称面"], ans: 2, exp: "在研究机运动时，通常使用机体坐标系，这个坐标系的原点位于飞机的重心。飞机的 纵轴（也称为 x 轴）通常是从前往后的轴线，而立轴（也称为 z 轴）是从下往上的轴线。横 轴（也称为 y 轴）则垂直于纵轴和立轴，构成一个右手坐标系。因此，正确的选项：以飞机 重心为原点，纵轴和立轴确定的平面为对称面。" },
  { id: 1173, cat: "飞行原理3", q: "影响飞机方向稳定力矩的因素主要是？（）", opts: ["飞机重心位置和飞行 M 数", "飞机焦点位置和飞行高度", "飞机迎角、机身和垂尾面积"], ans: 2, exp: "影响飞机方向稳定力矩的因素主要是飞机迎角、机身和垂尾面积。飞机的方向稳定性 主要取决于飞机的垂尾设计和飞机的飞行状态，其中垂尾面积的大小直接影响到飞机的方向 稳定性。飞机迎角的变化会影响飞机的侧滑力和力矩，而机身的形状和结构也会影响飞机的 气动特性和方向稳定性。" },
  { id: 1174, cat: "飞行原理3", q: "影响飞机俯仰平衡的力矩主要是（）", opts: ["机身力矩和机翼力矩", "机翼力矩和垂尾力矩", "机翼力矩和水平尾翼力矩"], ans: 2, exp: "影响飞机俯仰平衡的力矩主要是机翼力矩和水平尾翼力矩。机翼产生的升力在飞机重 心处产生一个力矩，而水平尾翼（特别是升降舵）的偏转能够产生额外的俯仰力矩，帮助飞 机保持或改变俯仰姿态。这两个力矩共同作用，决定了飞机的俯仰平衡状态。" },
  { id: 1175, cat: "飞行原理3", q: "在飞机进行俯冲拉起过程中，飞机的升力（）", opts: ["为飞机的曲线运动提供向心力", "等于飞机的重量", "大于飞机的重量并一直保持不变"], ans: 0, exp: "在飞机进行俯冲拉起过程中，飞机执行的是曲线运动，需要一个向心力来保持飞机沿 曲线路径飞行。这个向心力是由飞机的升力提供的，因为飞机在俯冲拉起过程中，其飞行路 径不是直线，而是一条曲线，所以升力不仅要抵消飞机的重量，还要提供必要的向心力以维 持飞机的圆周运动。" },
  { id: 1176, cat: "飞行原理3", q: "在平衡外载荷的作用下，飞机飞行的轨迹（）", opts: ["一定是直线的", "一定是水平直线的", "是直线的或是水平曲线的"], ans: 0, exp: "在平衡外载荷的作用下，飞机飞行的轨迹一定是直线的。这是因为在受平衡力作用时，飞机所受的合力内零，根据牛顿第一定律（惯性定律），飞机将保持其当前的运动状态，即 如果飞机原本在直线飞行，它将继续沿直线飞行；如果飞机原本静止，它将保持静止。因此，在没有非平衡力作用的情况下，飞机的轨迹将是直线。" },
  { id: 1177, cat: "飞行原理3", q: "增大机翼弯度可以增大机翼升力的原理是（）", opts: ["使附面层保持层流状态", "加快机翼前缘上表面气流的流速", "加快机翼后缘气流的流速"], ans: 1, exp: "弯度增大升力涨，只因前缘流速强。增大机翼弯度可以增大机翼升力的原理是加快机 翼前缘上表面气流的流速。这是因为机翼的弯度改变了气流沿机翼表面的流动特性，使得上 表面的气流流速增加，根据伯努利定理，流速增加导致压力降低，从而在机翼上下表面之间 产生压力差，形成升力。" },
  { id: 1178, cat: "飞行原理3", q: "增加垂直安定面面积产生的影响将（）", opts: ["增加升力", "增加横向稳定性", "增加纵向静稳定性"], ans: 1, exp: "增加垂直安定面面积产生的影响是增加横向稳定性。垂直安定面主要负责提供飞机的 横向稳定性，即控制飞机的偏航运动。增加垂直安定面的面积可以增强飞机的横向稳定性，使飞机在受到侧风或其他扰动时能够更好地维持航向平衡。" },
  { id: 1179, cat: "飞行原理3", q: "影响有用意识时间的三个主要因素是（）", opts: ["身体健康情况，注意力是否集中，情绪是否紧张", "飞机上升的速率，是否有身体活动，是否吸烟", "飞行高度，飞行速度，判断能力"], ans: 1, exp: "影响有用意识时间的主要因素包括飞机上升的速率（快速上升会更快耗尽氧气）、是 否有身体活动（活动会增加氧气消耗）、是否吸烟（吸烟会降低血液中的氧气携带能力）。" },
  { id: 1180, cat: "飞行原理3", q: "当飞机受微小扰动而偏离原来纵向平衡状态（俯仰状态），并在扰动消失后，飞机能自 动恢复到原来纵向平衡状态的特性，叫作飞机的纵向稳定性，下列说法错误的是（）", opts: ["当飞机受到扰动而机头下俯时，机翼和水平尾翼的迎角减小，会产生向 上的附加升力", "飞机的重心位于焦点之后，飞机则是纵向不稳定的", "当重心位置后移时，将削弱飞机的纵向稳定性"], ans: 0, exp: "1.当飞机受到扰动而机头下俯时，机翼和水平尾翼的迎角减小，会产生向上的附加升力：错 误。当飞机机头下俯时，机翼和水平尾翼的迎角实际上会增加，而不是减小。这会导致升力 增加，但由于飞机的重心位置，这种升力增加通常会使飞机进一步下俯，而不是恢复平衡。 2.飞机的重心位于焦点之后，飞机则是纵向不稳定的：正确。如果飞机的重心位于焦点之后，任何扰动都会导致飞机不稳定，因为它会倾向于继续偏离原来的平衡状态。 3.当重心位置后移时，将削弱飞机的纵向稳定性：正确。重心位置越靠后，飞机的稳定性越 差，因为重心后移会减少飞机的纵向稳定性。" },
  { id: 1181, cat: "飞行原理3", q: "内侧滑转弯时，飞机转弯的快慢和所倾斜的角度不对应，然后飞机会偏航到转弯航迹的 内侧，下列说法正确的是（）", opts: ["飞机以一定的角速度转弯而倾斜过多时水平升力分量小于离心力", "升力的水平分量和离心力的平衡只能通过降低倾斜度建立", "升力的水平分量和离心力的平衡可以通过降低倾斜度建立"], ans: 2, exp: "当飞机进行内侧滑转弯时，倾斜角度过大会导致水平升力分量小于离心力，飞机会偏 航到转弯航迹的内侧。要纠正这种情况，可以通过降低倾斜度来增加水平升力分量，使其平 衡离心力。 其他选项分析如下： 1.飞机以一定的角速度转弯而倾斜过多时，水平升力分量小于离心力：错误。这个说法描述 的是内侧滑转弯的现象，而不是纠正方法。 2.升力的水平分量和离心力的平衡只能通过降低倾斜度建立：错误。虽然降低倾斜度是纠正 内侧滑的一种方法，但不是唯一的方法，还可以通过其他方式（如调整速度）来平衡。" },
  { id: 1182, cat: "飞行原理3", q: "高度增加，最佳爬升角度（），最佳爬升率速度（）", opts: ["增大、减小", "减小、增大", "增大、增大"], ans: 0, exp: "当飞机高度增加时，最佳爬升角速度（Vx）会增大，而最佳爬升率速度（Vy）会减小。 这是因为随着高度的增加，空气密度降低，飞机需要更高的速度来产生足够的升力，从而导 致最佳爬升角速度增加。同时，由于空气密度的降低，发动机的推力也会减小，这使得飞机 的最大爬升率降低，因此最佳爬升率速度也会相应减小。" },
  { id: 1183, cat: "飞行原理3", q: "为使下降时的空速和平飞时相同，下列说法错误的是（）", opts: ["功率必然降低", "重力的分量沿航迹向前作用将随迎角的下降率增加而增加", "迎角的下降率降低时重力的向前分量增加变快"], ans: 2, exp: "1.迎角的下降率降低时重力的向前分量增加变快：错误。迎角的下降率降低时，重力的向前 分量不会增加变快。实际上，迎角的下降率降低意味着飞机的下降角度变小，重力的向前分 量会减少。 2.功率必然降低：正确。为了保持相同的空速，下降时飞机需要减少功率，因为重力的分量 会帮助飞机前进，减少所需的推力。 3.重力的分量沿航迹向前作用将随迎角的下降率增加而增加：正确。当迎角的下降率增加时，飞机的下降角度变大，重力的向前分量会增加，从而帮助飞机前进。" },
  { id: 1184, cat: "飞行原理3", q: "飞机在飞的时候迎角多少度？（）", opts: ["10 度", "20 度", "120 度"], ans: 0, exp: "一般而言，飞机在起飞瞬间的迎角通常为 10 度左右。因此，正确答案是：10 度。" },
  { id: 1185, cat: "飞行原理3", q: "垂直爬升时升限为海拔 1000 米的多轴飞行器，如果在性能范围内前飞中爬升，其升限 （）", opts: ["将升高", "将降低", "将保持不报"], ans: 0, exp: "垂直爬升时升限为海拔 1000 米的多轴飞行器，如果在 10km/h 的前飞中爬升，其升限 将升高。" },
  { id: 1186, cat: "飞行原理3", q: "失速时机翼（）", opts: ["升力的向上力和尾部向下的力降低", "升力的向上力和尾部向下的力增加", "升力的向上力和尾部向下的力恒为零"], ans: 0, exp: "当飞机失速时，机翼的升力会急剧下降，同时尾部向下的力也会减少。 其他选项分析如下： 1.升力的向上力和尾部向下的力增加：错误。失速时，升力和尾部向下的力都会降低，而不 是增加。 2.升力的向上力和尾部向下的力恒为零：错误。失速时，升力和尾部向下的力会显著降低，但不会完全为零。" },
  { id: 1187, cat: "飞行原理3", q: "无人机在最大升阻比飞行时的性能特点是（）", opts: ["最大航程", "最大升力系数和最小阻力系数", "最大爬升角和最大滑翔距离"], ans: 0, exp: "当无人机在最大升阻比飞行时，其燃油效率最高，因此可以实现最大航程。 其他选项分析如下： 1.最大升力系数和最小阻力系数：错误。虽然最大升阻比时升力系数和阻力系数的比值最大，但这并不意味着升力系数最大或阻力系数最小。 2.最大爬升角和最大滑翔距离：错误。最大升阻比飞行时，虽然滑翔距离可能增加，但爬升 角并不一定最大。" },
  { id: 1188, cat: "飞行原理3", q: "在实际运用中，通常使用气温的垂直递减率单位是：（）", opts: ["°C/1000m", "°C/500m", "°C/100m"], ans: 2, exp: "气温的垂直递减率通常用°C/100m 表示，即每上升 100 米，气温下降的摄氏度数。" },
  { id: 1189, cat: "飞行原理3", q: "关于音速，以下说法正确的是（）", opts: ["音速是空气可压缩性的标志", "音速是空气压力大小的标志", "空气速度是空气可压缩性的标志"], ans: 0, exp: "音速是声波在介质中传播的速度，它反映了介质的可压缩性。在空气中，音速约为 340 米/秒，这个速度与空气的密度和弹性模量有关，因此可以作为空气可压缩性的标志。 其他选项分析如下： 1.音速是空气压力大小的标志：错误。音速与空气压力大小没有直接关系，而是与空气的密 度和弹性模量有关。 2.空气速度是空气可压缩性的标志：错误。空气速度是指空气流动的速度，与空气的可压缩 性没有直接关系。" },
  { id: 1190, cat: "飞行原理3", q: "对流层顶至 55km 以下为（）", opts: ["平流层", "中间层", "热层"], ans: 0, exp: "平流层位于对流层顶至约 50-55km 的高度范围内，是大气层的一个重要层次。 其他选项分析如下： 1.中间层：错误。中间层位于平流层之上，大约在 50-85km 的高度范围内。 2.热层：错误。热层位于中间层之上，大约在 85km 以上的高度范围内。" },
  { id: 1191, cat: "飞行原理3", q: "对于音速，以下说法正确的是（）", opts: ["只要空气密度大，音速就大", "只要空气压力大，音速就大", "只要空气温度高，音速就大"], ans: 2, exp: "音速与空气温度的关系是正相关的。温度越高，空气分子的运动越快，声波传播的速 度也越快。从音速的计算公式可以看出，温度增加时，音速也会增加。" },
  { id: 1192, cat: "飞行原理3", q: "中纬度地区对流层上界的高度通常是（）", opts: ["8 到 9 千米", "10 到 12 千米", "15 到 17 千米"], ans: 1, exp: "中纬度地区对流层上界的高度通常是 10 到 12 千米。" },
  { id: 1193, cat: "飞行原理3", q: "推算实际大气情况下的飞行性能，将基于下列哪条基准，对飞行手册查出的性能数据进 行换算？（）", opts: ["温度偏差", "压力偏差", "密度偏差"], ans: 0, exp: "推算实际大气情况下的飞行性能时，通常基于温度偏差进行换算。这是因为温度对空 气密度和发动机性能有显著影响，从而影响飞机的飞行性能。" },
  { id: 1194, cat: "飞行原理3", q: "对流层分三层，中层特点是（）", opts: ["气流很乱", "气流相对平稳", "空气密度大"], ans: 1, exp: "对流层的中层通常位于对流层的中部，气流相对平稳，没有低层的强烈对流和高层的 剧烈变化。 其他选项分析如下： 1.气流很乱：错误。气流很乱通常是对流层低层的特点，因为低层受到地面加热和地形的影 响，对流活动较为剧烈。 2.空气密度大：错误。空气密度大通常是对流层低层的特点，因为低层的空气压力较高，密 度较大。" },
  { id: 1195, cat: "飞行原理3", q: "不属于飞机机体腐蚀的大气因素是（）", opts: ["空气相对湿度", "空气压力", "空气温差"], ans: 1, exp: "空气压力对飞机机体腐蚀的影响相对较小，不属于主要的大气腐蚀因素。 其他选项分析如下： 1.空气相对湿度：错误。高湿度环境会加速金属的腐蚀，因为空气中的水分会与金属表面发 生化学反应，形成腐蚀产物。 2.空气温差：错误。温差会导致冷凝现象，使水汽凝结在金属表面，从而加速腐蚀。" },
  // ==================== 起降操纵1 ====================
  { id: 1196, cat: "起降操纵1", q: "当前国内民用无人机的主要控制方式不包括（）", opts: ["自主控制", "人工遥控", "人工智能"], ans: 2, exp: "目前国内民用无人机主要有自主控制和人工遥控两种控制方式。自主控制是指无人机 按照预先设定的程序和任务进行飞行操作；人工遥控则是通过遥控器等设备由操作人员进行 控制。而人工智能在民用无人机领域虽然有一定的研究和发展，但目前还不是主要的控制方 式。" },
  { id: 1197, cat: "起降操纵1", q: "对于无人机关键性能，无人机驾驶员（）", opts: ["不必了解", "视情况了解", "必须了解"], ans: 2, exp: "无人机驾驶员在操作无人机时，必须了解无人机的关键性能。只有了解关键性能，才 能更好地操控无人机，确保飞行安全，合理安排任务，应对各种突发情况。如果不了解关键 性能，可能会在飞行中出现错误操作，导致危险发生。" },
  { id: 1198, cat: "起降操纵1", q: "据统计，无人机系统事故 60%以上发生在（）", opts: ["起降阶段", "巡航阶段", "滑跑阶段"], ans: 0, exp: "无人机系统事故 60%以上发生在起降阶段。这是因为在起飞和降落阶段，无人机需要 进行复杂的操作，包括获得足够的升力、控制高度和速度等，这些操作对飞行控制系统的要 求较高，稍有不慎就可能导致事故发生。因此，起降阶段是无人机飞行中最容易发生事故的 阶段之一。" },
  { id: 1199, cat: "起降操纵1", q: "起落航线（五边航线）组成内容不包括（）", opts: ["起飞、建立航线", "着陆目测、着陆", "任务飞行"], ans: 2, exp: "任务飞行，不包括在起落航线中。任务飞行是指飞机执行特定任务时的飞行，如侦察、运输或作战任务，与起落航线无关。 起落航线，通常称为五边航线，是飞机起飞和着陆过程中的飞行路径。包括以下几个部分： 起飞：飞机从跑道上加速并离地。 建立航线：飞机起飞后，调整航向和高度，进入预定的航路。 着陆目测：飞机在下降过程中对准跑道，准备着陆。 着陆：飞机接触跑道并减速至停止。" },
  { id: 1200, cat: "起降操纵1", q: "起落航线的重要组成部分应急航线相关内容不包括（）", opts: ["检查飞行平台、发动机、机上设备的故障状态、油量、电量", "决定着陆场或迫降场", "任务执行情况"], ans: 2, exp: "应急航线是起落航线的重要组成部分，主要是为了应对突发情况。 检查飞行平台、发动机、机上设备的故障状态、油量、电量是非常必要的，以便确定飞机是 否能够继续安全飞行或者需要采取紧急措施。 决定着陆场或迫降场是应急情况下的关键决策，要根据飞机的状态和周围环境选择合适的地 点进行着陆或迫降。 而任务执行情况与应急航线并无直接关系，应急航线主要关注的是飞机的安全和紧急处置，而不是任务的执行情况。" },
  { id: 1201, cat: "起降操纵1", q: "无人机定高平飞时，驾驶员面对地面站界面（）", opts: ["切至自主控制模式，尽可放松休息", "短暂休息，偶尔关注一下飞机状态", "密切判断飞机的俯仰状态和有无坡度"], ans: 2, exp: "无人机在定高平飞时，驾驶员需要密切关注无人机的状态，以确保飞行安全。 驾驶员在无人机定高平飞时，应当不断检查空速、高度和航向指示，以确保无人机在飞行中 保持稳定的飞行状态。这是因为无人机在飞行过程中可能会受到风速、风向等因素的影响，导致航迹偏离预定航线，因此需要驾驶员及时调整，确保飞行安全。" },
  { id: 1202, cat: "起降操纵1", q: "无人机定高平飞时，驾驶员面对地面站界面（）", opts: ["切至自主控制模式，尽可放松休息", "短暂休息，偶尔关注一下飞机状态", "根据目标点方向，密切判断飞行方向"], ans: 2, exp: "在无人机定高平飞时，驾驶员面对地面站界面的主要任务是密切监控飞机的状态，并 根据飞行条件进行必要的调整。这包括但不限于监控飞机的俯仰状态、有无坡度、空速、高 度和航向指示，以及发动机的工作情况。" },
  { id: 1203, cat: "起降操纵1", q: "无人机定高平飞时，驾驶员面对地面站界面（）", opts: ["切至自主控制模式，尽可放松休息", "短暂休息，偶尔关注一下飞机状态", "不断检查空速、高度和航向指示"], ans: 2, exp: "无人机在执行定高平飞任务时，虽然可能已经设定在自主控制模式，但驾驶员仍然需 要保持警觉，持续监控无人机的状态。这是因为飞行环境是动态变化的，可能会有风速风向 的变化、气温变化、信号干扰等因素影响无人机的飞行。因此，驾驶员需要不断地检查空速、高度和航向指示，以确保无人机按照预定的航线安全飞行，及时调整以应对任何突发情况。" },
  { id: 1204, cat: "起降操纵1", q: "无人机定高平飞时，驾驶员面对地面站界面（）", opts: ["切至自主控制模式，尽可放松休息", "短暂休息，偶尔关注一下飞机状态", "不断观察发动机指示，了解发动机工作情况"], ans: 2, exp: "驾驶员在面对地面站界面时，应当不断检查空速、高度和航向指示，同时观察发动机 指示，了解发动机工作情况。这是因为无人机的飞行状态可能会受到多种因素的影响，如风 速、风向变化等，驾驶员需要及时调整以保持无人机的稳定飞行。" },
  { id: 1205, cat: "起降操纵1", q: "无人机定速遥控飞行时放下襟翼，驾驶员需（）", opts: ["增加油门以保持空速", "减小油门以保持空速", "针对此情况，无需做相关动作"], ans: 0, exp: "无人机在定速遥控飞行时放下襟翼，会增加机翼的升力和阻力，从而使飞机在低速飞 行时更加稳定，并且能够在着陆时提供更好的减速效果。因此，当放下襟翼时，为了保持空 速，驾驶员需要增加油门以抵消增加的阻力。这是因为襟翼放下会增加飞机的阻力，为了保 持原有的空速，需要通过增加油门来提供更多的推力。" },
  { id: 1206, cat: "起降操纵1", q: "无人机定速遥控飞行时放下起落架，驾驶员需（）", opts: ["增加油门以保持空速", "减小油门以保持空速", "针对此情况，无需做相关动作"], ans: 0, exp: "无人机在定速遥控飞行时放下起落架，会增加飞机的气动阻力，因为起落架放下后会 破坏飞机的流线型，增加空气阻力。为了保持原有的空速，驾驶员需要增加油门，以提供更 多的推力来抵消增加的阻力。因此，正确答案是增加油门以保持空速。" },
  { id: 1207, cat: "起降操纵1", q: "无人机定速遥控飞行时收起襟翼，驾驶员需（）", opts: ["增加油门以保持空速", "减小油门以保持空速", "针对此情况，无需做相关动作"], ans: 1, exp: "在无人机定速遥控飞行时，如果收起襟翼，驾驶员需要减小油门以保持空速。这是因 为襟翼通常用于增加升力和减速，当襟翼被收起时，飞机的阻力会减小，如果没有相应的油 门调整，飞机的速度会增加。因此，为了保持预定的空速，驾驶员需要适当减小油门。" },
  { id: 1208, cat: "起降操纵1", q: "无人机定速遥控飞行时收起起落架，驾驶员需（）", opts: ["增加油门以保持空速", "减小油门以保持空速", "针对此情况，无需做相关动作"], ans: 1, exp: "无人机在定速遥控飞行时收起起落架，会减少飞机的气动阻力，因为收起起落架后，飞机的流线型更加优化，空气流动更加顺畅。为了保持原有的空速，驾驶员需要减小油门，因为减少阻力意味着所需的推力也会减少。因此，正确的操作是减小油门以保持空速。" },
  { id: 1209, cat: "起降操纵1", q: "无人机飞行时放下襟翼，会使飞机（）", opts: ["飞行速度减小", "飞行速度增大", "飞行速度无明显变化"], ans: 0, exp: "无人机飞行时放下襟翼会改变机翼的升力分布，增加机翼的弯度，从而增加升力。这 种增加的升力通常用于在较低的速度下获得更多的升力，比如在起飞和着陆阶段。因此，当 无人机在飞行中放下襟翼时，为了保持相同的升力，飞机需要以较低的速度飞行，这会导致 飞行速度减小。" },
  { id: 1210, cat: "起降操纵1", q: "无人机飞行时放下起落架，会使飞机（）", opts: ["全机阻力减小", "全机阻力增大", "全机阻力无明显变化"], ans: 1, exp: "无人机飞行时放下起落架，会使飞机的全机阻力增大。这是因为起落架在放下时增加 了飞机与空气接触的面积，破坏了飞机的流线型，从而增加了空气阻力。这种阻力的增加对 于无人机的性能和燃油效率都有影响，尤其是在高速飞行时更为明显。" },
  { id: 1211, cat: "起降操纵1", q: "无人机飞行时收起襟翼，会使飞机（）", opts: ["飞行速度减小", "飞行速度增大", "飞行速度无明显变化"], ans: 1, exp: "无人机在飞行时收起襟翼，会减少机翼的弯度和升力，同时降低飞机的阻力。襟翼通 常用于增加升力，特别是在起飞和降落时，以帮助飞机在较低的速度下飞行。当襟翼收起，飞机的气动阻力减小，飞机可以在相同的推力下达到更高的速度，因此飞行速度会增大。" },
  { id: 1212, cat: "起降操纵1", q: "无人机飞行时收起起落架，会使飞机（）", opts: ["全机阻力减小", "全机阻力增大", "全机阻力无明显变化"], ans: 0, exp: "无人机在飞行时收起起落架，主要是为了减少飞行过程中的阻力。起落架在放下状态 时，会增加飞机与空气接触的面积，从而增加阻力。当起落架收起时，飞机的外形更加流线 型，空气阻力会相应减小，这有助于提高飞行效率和速度。" },
  { id: 1213, cat: "起降操纵1", q: "无人机飞行摇杆常规操作方式是（）", opts: ["姿态遥控和舵面遥控", "自主控制", "人工修正"], ans: 0, exp: "无人机飞行摇杆的常规操作方式有姿态遥控和舵面遥控。姿态遥控是通过操纵杆控制 无人机的俯仰、横滚和偏航等姿态角度；舵面遥控则是通过控制无人机的各个控制面（如升 降舵、副翼、方向舵等）来实现对无人机的飞行控制。" },
  { id: 1214, cat: "起降操纵1", q: "无人机驾驶员进行起飞前动力装置检查内容不必包括（）", opts: ["发动机油量检查", "发动机启动后怠速转速、震动、稳定性检查", "发动机生产厂家检查"], ans: 2, exp: "无人机驾驶员在进行起飞前的动力装置检查时，需要确保油量充足、发动机启动后的 各项性能指标正常，包括怠速转速、震动和稳定性等。这些检查项目对于确保无人机安全飞 行至关重要。而发动机生产厂家的信息虽然对于了解发动机的性能和维护历史很重要，但它 不是起飞前必须检查的内容。发动机生产厂家的检查通常在采购、维护和修理时考虑，而不 是在每次起飞前的检查中。" },
  { id: 1215, cat: "起降操纵1", q: "无人机驾驶员进行起飞前飞行器检查内容不必包括（）", opts: ["舵面结构及连接检查", "起飞（发射）、降落（回收）、装置检查", "飞行器涂装"], ans: 2, exp: "无人机驾驶员在起飞前的飞行器检查中，需要确保舵面结构及连接的完整性和安全性，以及起飞和降落装置的正常工作，这些都是关乎飞行安全的重要环节。而飞行器的涂装主要 是为了美观或者标识，并不直接影响飞行器的飞行性能和安全，因此不是起飞前必须检查的 内容。" },
  { id: 1216, cat: "起降操纵1", q: "无人机驾驶员进行起飞前控制站检查内容不必包括（）", opts: ["控制站软件检查", "控制站操作系统检查", "预规划航线及航点检查"], ans: 1, exp: "无人机驾驶员在起飞前对控制站进行检查时，需要确保控制站软件和预规划航线及航 点设置正确无误，这些是飞行安全和任务执行的关键因素。而控制站操作系统通常指的是控 制站软件运行的底层系统，它不是由无人机驾驶员在每次起飞前检查的内容，因为操作系统 的检查更多是软件开发商和维护人员的责任，而不是飞行操作人员的任务。" },
  { id: 1217, cat: "起降操纵1", q: "无人机驾驶员进行起飞前通讯链路检查内容不必包括（）", opts: ["链路设备型号", "飞行摇杆舵面及节风门反馈检查", "外部控制盒舵面及节风门反馈检查"], ans: 0, exp: "无人机驾驶员在起飞前进行通讯链路检查时，需要确保飞行控制系统的摇杆舵面及节 风门（油门）反馈正常，以及外部控制盒（如适用）的舵面及节风门反馈正常。而链路设备 的型号并不是每次起飞前必须检查的内容，因为设备型号是固定的，不会因每次飞行而改变，且型号信息与通讯链路的功能性和稳定性无直接关系。" },
  { id: 1218, cat: "起降操纵1", q: "无人机爬升时，油门较大，螺旋桨左偏力矩较大，需适当操纵方向舵（）", opts: ["左偏", "右偏", "不必干涉"], ans: 1, exp: "当无人机爬升时，油门较大，螺旋桨左偏力矩较大，这会使无人机有向左偏转的趋势。 为了抵消这种左偏力矩，需要适当操纵方向舵向右偏，产生一个向右的力矩来平衡螺旋桨的 左偏力矩，从而保持无人机的飞行方向稳定。" },
  { id: 1219, cat: "起降操纵1", q: "无人机系统中，起降驾驶员一般不参与哪个阶段控制？（）", opts: ["起飞阶段", "降落阶段", "巡航阶段"], ans: 2, exp: "在无人机系统中，起降驾驶员主要负责无人机的起飞和降落阶段，这两个阶段对飞行 安全至关重要，需要精确的操控和即时的干预以确保顺利执行。巡航阶段通常是指无人机在 起飞后和降落前的稳定飞行状态，这个阶段无人机可以自主飞行，或者按照预设的航线自动 巡航，一般不需要起降驾驶员的直接控制。" },
  { id: 1220, cat: "起降操纵1", q: "无人机在遥控下降时，驾驶员应注意（）", opts: ["飞机下降时，油门收小，螺旋桨扭转气流减弱，飞机有右偏趋势，须抵住左舵", "飞机下降时，油门收小，螺旋桨扭转气流减弱，飞机有左偏趋势，须抵住右舵", "飞机状态不会发生变化，不需做任何准备"], ans: 0, exp: "无人机在遥控下降时，驾驶员应注意飞机下降时，油门收小，螺旋桨扭转气流减弱，飞机有右偏趋势，须抵住左舵。这是因为在下降过程中，油门减小会导致螺旋桨提供的升力 降低，同时螺旋桨对空气的扭转作用也会减弱，这可能会导致飞机出现向右的偏转趋势。为 了保持飞机的航向稳定，驾驶员需要适当地操纵方向舵向左偏转，以抵消这种偏转趋势。" },
  { id: 1221, cat: "起降操纵1", q: "无人机遥控下降时，速度过大时，驾驶员应（）", opts: ["适当减小带杆量，增大下滑角", "适当增加带杆量，减小下滑角", "顺其自然，让其自动恢复状态"], ans: 1, exp: "无人机在遥控下降中，如果速度过大，驾驶员应该适当增加带杆量，减小下滑角。这 是因为增加带杆量可以帮助无人机减少下降的速度，而减小下滑角则有助于控制无人机的下 降轨迹，使其更加平稳。这样的操作可以确保无人机安全、稳定地降落。" },
  { id: 1222, cat: "起降操纵1", q: "无人机着陆目测须重点判断着陆方向和（）", opts: ["一转弯位置", "二转弯位置", "三四转弯位置"], ans: 2, exp: "无人机在进行着陆目测时，需要重点决断着陆方向和三四转弯位置。这是因为在着陆 前，无人机需要进行一系列的转弯操作以对准跑道，而选择适当的转弯位置对于确保着陆的 稳定性和准确性至关重要。在三四转弯位置的决断，可以帮助无人机飞行员更好地控制飞机 的下降路径，确保飞机能够安全、准确地降落在预定的位置。" },
  { id: 1223, cat: "起降操纵1", q: "无人机着陆目测与有人机相比不同之处为（）", opts: ["有人机是从飞机观察着陆场，无人机是从着陆场观察飞机", "有人机为第三视角，无人机为第一视角", "有人机驾驶员通过地面人员通告仪表参考值，无人机起降驾驶员可自行观察仪表参考值"], ans: 0, exp: "无人机着陆与有人机着陆的主要不同之处在于观察的位置和视角。有人机的飞行员是 在飞机内部，从飞机上观察着陆场，而无人机的驾驶员则通常在地面，从着陆场观察无人机 的接近和着陆过程。这种差异意味着无人机驾驶员需要依赖于遥控器、摄像头和其他地面控 制站设备来监控无人机的状态，而不是像有人机飞行员那样直接从飞机内部观察外部环境。" },
  { id: 1224, cat: "起降操纵1", q: "遥控无人机复飞后，襟翼收起时描述正确的操纵动作是（）", opts: ["升力系数下降，飞机要下沉，应适当地拉杆", "升力系数增大，飞机要上升，应适当地推杆", "对飞机几乎没有影响"], ans: 0, exp: "遥控无人机在复飞后，襟翼的收起会减少机翼的升力系数，因为襟翼通常用于增加升 力，尤其是在起飞和降落阶段。当襟翼收起时，飞机的升力减少，可能会导致「飞机下沉。 因此，为了维持或恢复飞机的高度，驾驶员需要适当地拉杆（即操纵升降舵向上），以增加 飞机的迎角，从而增加升力，抵消因襟翼收起导致的升力减少。" },
  { id: 1225, cat: "起降操纵1", q: "遥控无人机复飞时，正确的操纵方式是（）", opts: ["迅速推满油门，同时快速拉杆转入爬升", "保持油门，快速拉杆转入爬升", "柔和地加满油门，保持好方向，同时柔和拉杆使飞机逐渐转入爬升，保持好爬升状态"], ans: 2, exp: "遥控无人机复飞时，正确的操纵方式是柔和地加满油门，保持好方向，同时柔和拉杆 使飞机逐渐转入爬升，保持好爬升状态。这种操作可以确保无人机在复飞过程中的稳定性和 安全性。" },
  { id: 1226, cat: "起降操纵1", q: "遥控无人机进入四转弯时（）", opts: ["如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入早，应立即协调地减 小坡度和转弯角速度", "如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入晚，应立即协调地增 大坡度和转弯角速度", "如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入晚，应立即协调地减 小坡度和转弯角速度"], ans: 1, exp: "四转看线和角，快近慢减进入晚，增大坡度角速度。当遥控无人机进入四转弯时，如 果飞机接近跑道延长线较快，而转弯剩余角减小较慢，这意味着飞机进入转弯的时机晚了。 此时应立即协调地增大坡度，这样可以使飞机更快地转向跑道方向；同时增大转弯角速度，以便更快地完成转弯，调整到合适的着陆姿态和位置。" },
  { id: 1227, cat: "起降操纵1", q: "遥控无人机进入下滑后（）", opts: ["当下滑线正常时，如速度大，表明目测高，应适当收小油门", "当下滑线正常时，如速度大，表明目测低，应适当增加油门", "当下滑线正常时，如速度小，表明目测高，应适当收小油门"], ans: 0, exp: "下滑快，收油门；稳速度，准备着。在遥控无人机进入下滑阶段时，如果飞机的速度 过大，这通常意味着飞机的动能较多，需要适当减少速度以匹配下滑道的要求。此时，正确 的操作是适当收小油门，以减小飞机的速度，使其适应下滑道的要求。这是因为在下滑阶段，飞机需要以较为稳定的速度进行下降，以确保着陆的准确性和安全性。" },
  { id: 1228, cat: "起降操纵1", q: "遥控无人机平飞、爬升和下降转换时产生偏差的主要原因不包括（）", opts: ["动作粗，操纵量大，造成飞行状态不稳定", "平飞、爬升、下降三种飞行状态变换时，推杆、拉杆方向不正，干扰其他通道", "天气状况不佳"], ans: 2, exp: "状态转换偏差因，人为操作是关键，天气不佳非主因。遥控无人机在平飞、爬升和下 降转换时产生偏差的主要原因通常与操纵技巧和飞机的控制有关。而天气状况不佳虽然是飞 行中可能遇到的问题，但它不是飞机在平飞、爬升和下降转换时产生偏差的直接原因。天气 状况不佳可能会影响整个飞行过程的稳定性，但它不是由于飞行状态转换操作不当而直接引 起的偏差。" },
  { id: 1229, cat: "起降操纵1", q: "遥控无人机平飞转弯过程中（）", opts: ["注视地平仪，协调地向转弯方向压杆扭舵，形成一定坡度后，稳杆保持", "注视地平仪，协调地向转弯反方向压杆扭舵，形成一定坡度后，稳杆保持", "注视地平仪，向转弯方向压杆，同时反方向扭舵"], ans: 0, exp: "在遥控无人机进行平飞转弯的过程中，正确的操作是注视地平仪，协调地向转弯方向 压杆扭舵，形成一定坡度后，稳杆保持。这样做可以确保飞机在转弯过程中保持稳定的飞行 姿态和高度，避免因操作不当导致的失速或过度倾斜。" },
  { id: 1230, cat: "起降操纵1", q: "遥控无人机平飞转弯过程中（）", opts: ["转弯中，如果坡度过大，应协调地适当增加压杆扭舵量", "转弯中，如果坡度过大，应协调地适当回杆回舵", "转弯中，如果坡度过小，应协调地适当回杆回舵"], ans: 1, exp: "在遥控无人机平飞转弯过程中，如果出现坡度过大的情况，说明飞机的转弯半径过小，可能需要更平缓的转弯路径。这时，驾驶员应该协调地适当回杆（减少副翼输入，使飞机的 滚转角度减小）和回舵（减少方向舵输入，使飞机的偏航角度减小），以减小坡度，使飞机 的转弯更加平稳，避免过度倾斜导致的风险。" },
  { id: 1231, cat: "起降操纵1", q: "遥控无人机平飞转弯后段（）", opts: ["当飞机轨迹方向离目标方向 10 度-15 度时，注视地平仪，根据接近 目标方向的快慢，逐渐回杆", "当飞机轨迹方向到达目标方向时，注视地平仪，逐渐回杆", "当飞机轨迹方向超过目标方向 10 度-15 度时，注视地平仪，逐渐回杆"], ans: 0, exp: "在遥控无人机平飞转弯的后段，正确的操作是当飞机轨迹方向离目标方向大约 10 度 到 15 度时，注视地平仪，根据飞机接近目标方向的快慢，逐渐回杆。这样做可以确保飞机 平稳地退出转弯并回到直飞航线上，避免过度转弯或修正过度。" },
  { id: 1232, cat: "起降操纵1", q: "遥控无人机平飞转弯前（）", opts: ["根据转弯坡度大小，减油门 5%-10%，保持好平飞状态", "根据转弯坡度大小，加油门 5%-10%，保持好平飞状态", "保持当前平飞状态"], ans: 1, exp: "在遥控无人机平飞转弯前，正确的操作是根据转弯坡度的大小，适当增加油门，以保 持无人机的速度和飞行状态。这是因为在转弯过程中，无人机会因为侧向力的作用而倾向于 减速，因此需要适当增加油门来补偿这种速度的损失，确保无人机能够平稳地完成转弯动作。" },
  { id: 1233, cat: "起降操纵1", q: "遥控无人机四转弯后（）", opts: ["目测过高时，应在加大油门的同时适当增加带杆量，减小下滑角，必要时可平飞一段", "目测过低时，应在加大油门的同时适当增加带杆量，减小下滑角，必要时可平飞一段", "等飞机降到较低高度时再做偏差调整"], ans: 1, exp: "无人机在四转弯后，如果目测过低，意味着飞机可能会提前接地，这时候应该加大油 门以增加飞机的升力，同时适当增加带杆量以减小下滑角，确保飞机能够维持在正确的下滑 轨迹上。必要时，可以让飞机平飞一段，以调整到正确的下滑路径。因此，正确的操作是目 测过低时，应在加大油门的同时适当增加带杆量，减小下滑角，必要时可平飞一段。" },
  { id: 1234, cat: "起降操纵1", q: "遥控无人机下滑中，估计到第四转弯时的高度将高于预定的高度（）", opts: ["应及时地收小油门，必要时可收至 20%，增大下滑角", "应适当地加大油门，减小下滑角", "转为平飞进行修正"], ans: 0, exp: "在遥控无人机下滑过程中，如果估计到第四转弯时的高度将高于预定的高度，这意味 着无人机下滑的路径过于陡峭，需要调整以确保机能够以正确的下滑角接近跑道。为了降低 飞机的高度并增加下滑角度，驾驶员应该及时收小油门，减少发动机的推力，这样飞机就会 因为重力的作用而增加下滑的角度。必要时，油门可以收至 20%，以进一步增大下滑角。这 样做可以帮助无人机调整到正确的下滑轨迹，避免因高度过高而影响着陆。" },
  { id: 1235, cat: "起降操纵1", q: "遥控无人机由爬升转为平飞时（）", opts: ["到达预定高度时，开始改平飞", "超过预定高度 10-20 米时，开始改平飞", "下降至预定高度前 10-20 米时，开始改平飞"], ans: 2, exp: "遥控无人机在由爬升转为平飞的过程中，需要在到达预定高度之前进行调整，以确保 飞机能够平稳地过渡到平飞状态。如果等到飞机到达或超过预定高度才开始改平飞，可能会 导致飞机出现突然的俯冲或需要额外的拉升来纠正高度，这会影响飞行的平稳性。因此，正 确的做法是在上升至预定高度前 10-20 米时开始改平飞，这样可以有足够的时间来调整飞机 的姿态和动力，确保平稳过渡。" },
  { id: 1236, cat: "起降操纵1", q: "遥控无人机由下降转为平飞时（）", opts: ["到达预定高度时，开始改平飞", "超过预定高度 20-30 米时，开始改平飞", "下降至预定高度前 20-30 米时，开始改平飞"], ans: 2, exp: "在遥控无人机由下降转为平飞的过程中，正确的操作是在接近预定高度前 20-30 米时 开始进行平飞的操作。这是因为无人机在下降过程中速度会逐渐增加，为了确保平稳过渡到 平飞状态，需要提前进行油门和操纵杆的调整。这样做可以帮助无人机平稳地达到预定高度，并维持稳定的平飞姿态。" },
  { id: 1237, cat: "起降操纵1", q: "遥控无人机在预定高度由平飞转爬升时（）", opts: ["注视地平仪，柔和地加油门至 100%，同时稍拉杆转为爬升", "注视地平仪，快速加油门至 100%，同时快速拉杆转为爬升", "注视地平仪，快速加油门至 100%，同时快速顶杆"], ans: 0, exp: "遥控无人机在预定高度由平飞转为爬升时，需要平稳地增加动力并调整飞机的姿态。 这个过程要求驾驶员注视地平仪，以保持飞机水平，同时柔和地加油门至 100%，增加发动 机的推力，提供足够的升力来克服重力，使飞机开始爬升。同时，稍拉杆可以增加飞机的迎 角，帮助飞机抬头，进一步协助爬升动作。柔和地操作可以避免飞机突然的俯冲或过快的爬 升，确保飞行的平稳性。" },
  { id: 1238, cat: "起降操纵1", q: "遥控无人机在预定高度由平飞转为下降时（）", opts: ["注视地平仪，稍顶杆，收油门", "注视地平仪，稍拉杆，收油门", "注视地平仪，稍拉杆，推油门"], ans: 0, exp: "遥控无人机在预定高度由平飞转为下降时，应注视地平仪，稍顶杆以减小迎角，同时 收油门以降低动力，使无人机平稳地由平飞转为下降。" },
  { id: 1239, cat: "起降操纵1", q: "遥控无人机在预定高度由下降转平飞时（）", opts: ["注视地平仪，柔和地加油门，同时拉杆", "注视地平仪，快速加油门，同时拉杆", "注视地平仪，柔和地加油门，同时顶杆"], ans: 0, exp: "在遥控无人机从下降转为平飞的操作中，正确的做法是注视地平仪，柔和地加油门，同时拉杆。这样的操作有助于平滑地从下降状态过渡到平飞状态，避免因操作过猛导致飞机 突然上升或失速。" },
  { id: 1240, cat: "起降操纵1", q: "遥控无人机着陆到平飘阶段（）", opts: ["平飘前段，速度较大，下沉较慢，拉杆量应小一些", "平飘前段，速度较大，下沉较慢，拉杆量应大一些", "平飘后段，速度较小，下沉较快，拉杆量应适当减小"], ans: 0, exp: "在遥控无人机着陆的平飘阶段，特别是在平飘前段，如果速度较大而下沉较慢，意味 着飞机的升力相对较高，因此需要较小的拉杆量来保持飞机的平飘姿态。拉杆量过大可能会 导致飞机过早地进入下沉状态，从而影响着陆的平稳性。因此，正确的操作是平飘前段，速 度较大，下沉较慢时，拉杆量应小一些。" },
  { id: 1241, cat: "起降操纵1", q: "遥控无人机着陆的过程不包括（）", opts: ["下滑和拉平", "平飘接地和着陆滑跑", "下降和定高"], ans: 2, exp: "遥控无人机着陆的过程主要包括下滑和拉平、平飘接地和着陆滑跑。而下降和定高并 不是着陆的特定过程，下降只是一个宽泛的动作，定高通常在飞行过程中进行调整，不属于 着陆过程。" },
  { id: 1242, cat: "起降操纵1", q: "遥控无人机着陆拉平时，对拉平操作描述不恰当的是（）", opts: ["正确的拉平动作，必须按照实际情况", "主动地、有预见地、机动灵活地去操纵飞机", "严格按高度值执行动作"], ans: 2, exp: "在遥控无人机着陆拉平阶段，正确的操作需要根据实际情况进行调整，而不是机械地 按照固定的高度值执行。拉平操作要求驾驶员主动、有预见性地进行，并且能够机动灵活地 操纵飞机，以适应不同的飞行条件和环境变化。 因此，描述不恰当的是“严格按高度值执行动作”，因为这样的操作缺乏灵活性，可能无法 适应实际飞行中的变量。" },
  { id: 1243, cat: "起降操纵1", q: "遥控无人机着陆拉平时，拉杆的快慢和下降速度的关系是（）", opts: ["下降快，拉杆应慢一些", "下降快，拉杆应快一些", "还按正常时机"], ans: 1, exp: "在遥控无人机着陆拉平的过程中，拉杆的快慢需要与下降速度相匹配。如果无人机的 下降速度快，这意味着飞机需要更快地从下降姿态转变为水平飞行姿态，以避免过快接近地 面。因此，此时拉杆应该快一些，以迅速减少飞机的下沉速率并开始平飘。" },
  { id: 1244, cat: "起降操纵1", q: "遥控无人机着陆拉平时，拉杆的快慢和下降的速度的关系是（）", opts: ["下降慢，拉杆应慢一些", "下降慢，拉杆应快一些", "还按正常时机"], ans: 0, exp: "在遥控无人机进行着陆拉平的过程中，拉杆的快慢需要与飞机的下降速度相协调。如 果无人机的下降速度较慢，这意味着飞机有足够的时间来完成从下降到平飞的过渡，因此拉 杆的动作可以相对慢一些，以确保飞机平稳地过渡到平飞状态，避免因为拉杆过快导致飞机 抬头过度或者失速。" },
  { id: 1245, cat: "起降操纵1", q: "遥控无人机着陆时，（）", opts: ["逆风对着陆没有影响", "逆风较大时，目测容易低（即提前接地）", "逆风较大时，目测容易高（即推迟接地）"], ans: 1, exp: "逆风地速减，目测易偏低；延迟收油门，高度略提高。逆风会显著减小无人机的地速 （对地速度），导致飞行员或飞控系统误判下降速率，提前收油门或降低高度，最终造成目 测低（提前接地）。大逆风条件下，无人机实际下滑角比目视判断更陡，需延迟下滑时机并 保持略高的第四转弯高度以补偿。" },
  { id: 1246, cat: "起降操纵1", q: "遥控无人机着陆时，（）", opts: ["机场气温较高时，跑道上升气流明显，会导致下滑距离增长", "机场气温较高时，跑道下降气流明显，会导致下滑距离增长", "机场气温较高时，跑道下降气流明显，会导致下滑距离减小"], ans: 0, exp: "遥控无人机着陆时，机场气温较高时，跑道上升气流明显，会导致下滑距离增长。这 是因为高温下，空气变得稀薄，容易形成上升气流。这会导致无人机在着陆时受到上升气流 的影响，使得下滑距离增加，即无人机的着陆距离会增长。" },
  { id: 1247, cat: "起降操纵1", q: "遥控无人机着陆时，产生着陆偏差的主要原因不包括（）", opts: ["精神过分紧张，对着陆存有顾虑，因而注意力分配不当，操纵动作犹豫不适量", "着陆条件不好", "飞机型号不同"], ans: 2, exp: "遥控无人机着陆时产生偏差的原因通常与操作者的技巧、环境条件以及操作者的心理 状态有关。 而飞机型号不同虽然是操作者在飞行时需要考虑的因素，因为它会影响无人机的飞行特性和 操作方法，但它不是产生着陆偏差的直接原因。操作者在飞行前应熟悉不同型号飞机的操作 特点，并根据飞机的具体性能进行相应的操作调整。" },
  { id: 1248, cat: "起降操纵1", q: "遥控无人机着陆时，风速大或气温低时，（）", opts: ["如目测低，加油门量相应小些", "如目测高，收油门量相应大些", "如目测低，加油门量相应大些"], ans: 2, exp: "在风速大或气温低的条件下进行无人机着陆时，由于目测高度容易偏低，应该适时增 加油门量，以确保无人机能够安全着陆。" },
  { id: 1249, cat: "起降操纵1", q: "遥控无人机着陆时，关于收油门描述正确的是（）", opts: ["收油门时机不要早，晚一些比较主动，可以快速收", "收油门时机不要早，收早了势必造成动作粗，影响着陆动作", "收油门时机不要晚，早一些比较主动，可以慢慢收，也可停一停再收"], ans: 2, exp: "遥控无人机着陆时，关于收油门的正确操作是时机不要晚，早一些比较主动，可以慢 慢收，也可以停一停再收。这是因为如果收油门过晚，飞机的速度减小过慢，可能导致拉平 时的速度过大，飞机下沉慢，从而影响着陆动作的平稳性。因此，正确的做法是提前收油门，以更主动地控制飞机的下降速度，确保着陆的平稳。" },
  { id: 1250, cat: "起降操纵1", q: "遥控无人机着陆时，关于收油门描述正确的是（）", opts: ["收油门的过程要拉长一些，拉长了可以柔和，使速度减小均匀，有利于做好着陆", "收油门的过程要尽量短，短了可以柔和，使速度减小均匀，有利于做好着陆", "收油门的过程可以随意些，跟着感觉就好"], ans: 0, exp: "遥控无人机着陆时，正确的收油门操作是将过程拉长一些，这样可以更柔和地减少油 门，使速度减小得更均匀。这种操作有助于飞行员更好地控制无人机的下降速度和姿态，从 而实现平稳着陆。如果收油门的过程太短，速度可能会过快减小，导致飞机下沉速度过大，影响着陆的平稳性。" },
  { id: 1251, cat: "起降操纵1", q: "遥控无人机着陆时，接地后跳跃的修正方法是（）", opts: ["飞机跳离地面时，应迅速推杆，压住飞机状态", "飞机跳离地面时，应迅速拉杆，避免再次坠落弹起", "飞机跳离地面时，应稳住杆，迅速判明离地的高度和飞机状态"], ans: 2, exp: "在遥控无人机着陆时，如果飞机接地后发生跳跃，这通常是由于飞机在接地时的下沉 速度过快或者接地点不准确导致的。在这种情况下，正确的修正方法是飞机跳离地面时，应 稳住杆，迅速判明离地的高度和飞机状态。这样可以避免因过度推杆或拉杆导致飞机再次跳 跃或失控。通过稳住杆，可以更好地控制飞机的姿态，使其重新获得稳定的接地状态。" },
  { id: 1252, cat: "起降操纵1", q: "遥控无人机着陆时，拉飘的修正方法是（）", opts: ["发现拉飘时，应立即继续拉杆", "发现拉飘时，应立即柔和推杆制止飞机继续上飘", "发现拉飘时，稳住并保持杆量"], ans: 1, exp: "正确的修正方法是在发现拉飘时立即柔和推杆，以增加飞机的下降速度，制止飞机继 续上飘。这样的操作可以帮助飞行员重新控制飞机的下降轨迹，避免飞机因上飘而偏离预定 的着陆点或导致着陆不稳定。" },
  { id: 1253, cat: "起降操纵1", q: "遥控无人机着陆时，拉平低的修正方法是（）", opts: ["发现有拉低的趋势，应适当地增大拉杆量", "发现有拉低的趋势，应停止拉杆或减小拉杆量", "发现有拉低的趋势，应推杆"], ans: 0, exp: "遥控无人机着陆时，拉平低的修正方法是发现有拉低的趋势，应适当地增大拉杆量。 这样可以增加飞机的升力，帮助飞机恢复到正确的下滑轨迹。" },
  { id: 1254, cat: "起降操纵1", q: "遥控无人机着陆时，拉平高的修正方法是（）", opts: ["发现有拉高的趋势，应停止拉杆或减小拉杆量，让飞机下沉", "发现有拉高的趋势，应停止拉杆或增加拉杆量，让飞机上升", "发现有拉高的趋势，应停止继续拉杆"], ans: 0, exp: "在遥控无人机着陆时，如果发现飞机有拉平高的趋势，即飞机的下降轨迹过高，可能 会导致飞机错过着陆点或者着陆不稳定。为了修正这种情况，需要减少飞机的升力，让飞机 下沉至正确的下降轨迹。正确的做法是停止拉杆或减小拉杆量，这样可以减少飞机的迎角，降低升力，使飞机下沉至正确的高度。" },
  { id: 1255, cat: "起降操纵1", q: "遥控无人机着陆时，面对拉平低正确的操纵方式是（）", opts: ["如结束拉平过低且速度较大时，应适当地多拉一点杆，避免三点接地", "如结束拉平过低且速度较大时，应适当地少拉一点杆，避免三点接地", "如结束拉平过低且速度较大时，应停止继续拉杆"], ans: 0, exp: "在遥控无人机着陆时，如果出现拉平过低的情况，且此时飞机的速度仍然较大，正确 的操作方式是适当地多拉一点杆，以避免飞机的三点（即前轮和两个主轮）同时接地，这可 能会导致飞机跳跃或者不稳定。因此，需要通过增加拉杆量来提升飞机的俯仰角度，从而减 缓机的下沉速度，确保飞机能够平稳着陆。" },
  { id: 1256, cat: "起降操纵1", q: "遥控无人机着陆时，面对拉平高正确的操纵方式是（）", opts: ["拉平高时，如果飞机随即下沉，应稳住杆，待飞机下沉到一定高度时，再柔和拉杆", "拉平高时，如果飞机不下沉，应稍拉杆，使飞机下沉到预定高度", "发现有拉高的趋势，应推杆"], ans: 0, exp: "在遥控无人机着陆时，如果出现拉平高的情况，即飞机的下降轨迹过高，需要进行修 正以确保飞机能够平稳着陆。正确的操作方式是稳住杆，等待飞机自然下沉到一定高度后再 柔和地拉杆，这样可以避免因过度操作而导致飞机突然下沉过多。选项 A 描述了这种正确 的操作方式，即在飞机下沉时稳住杆，然后在适当的时机柔和拉杆，以确保飞机能够平稳地 下降到预定高度。" },
  { id: 1257, cat: "起降操纵1", q: "遥控无人机着陆时，如果飞机处于逆侧风时（）", opts: ["地速增大，收油门下滑和四转弯时机均应适当提前", "地速减小，收油门下滑和四转弯时机均应适当延后", "地速增大，收油门下滑和四转弯时机均应适当延后"], ans: 1, exp: "在遥控无人机着陆时，如果飞机处于逆侧风条件，这会影响飞机的地速。逆侧风意味 着风是从飞机的侧后方吹来，这会减小飞机的地速，因为飞机需要逆风飞行。因此，如果目 测飞机高度偏低且速度较大时，这表明飞机受到逆侧风的影响，需要适当延后收油门下滑和 四转弯的时机，以确保飞机能够在正确的位置和速度下进行着陆操作。" },
  { id: 1258, cat: "起降操纵1", q: "遥控无人机着陆时，如果飞机处于顺侧风时（）", opts: ["地速增大，收油门下滑和四转弯时机均应适当提前", "地速减小，收油门下滑和四转弯时机均应适当延后", "地速增大，收油门下滑和四转弯时机均应适当延后"], ans: 0, exp: "遥控无人机着陆时，如果飞机处于顺侧风时，地速会增大，因此收油门下滑和四转弯 时机均应适当提前。这是因为顺侧风会增加无人机相对于地面的速度，导致无人机下降和转 弯的时机需要提前以适应增加的地速，确保着陆的准确性和安全性。" },
  { id: 1259, cat: "起降操纵1", q: "遥控无人机着陆时，如果拉平前飞机的俯角较大下降快，应（）", opts: ["拉杆稍早些", "拉杆稍晚些", "还按正常时机拉杆"], ans: 0, exp: "遥控无人机着陆时，如果拉平前飞机的俯角较大且下降快，这意味着飞机的下降速率 超过了正常着陆所需的下降速率。为了调整飞机的下降轨迹，使其更加平稳，避免因下降过 快而导致的硬着陆或提前接地，应该稍早一些拉杆，以减小飞机的俯角，从而减缓下降速率。 因此，正确的操作是拉杆稍早些。" },
  { id: 1260, cat: "起降操纵1", q: "遥控无人机着陆时，收油门的基本要领是（）", opts: ["适时、柔和", "适时、快速", "跟着感觉操作"], ans: 0, exp: "在遥控无人机着陆时，收油门是一个需要细致操作的步骤。正确的做法是适时且柔和 地收油门，以确保飞机平稳减速并着陆。" },
  { id: 1261, cat: "起降操纵1", q: "遥控无人机着陆时，收油门过晚、过细，速度减小慢，使拉平的速度大，飞机下沉慢，（）", opts: ["容易拉平高或者进入平飘时仰角较小", "容易拉平低或者进入平飘时仰角较大", "对飞机无影响"], ans: 0, exp: "遥控无人机着陆时，如果收油门过晚且动作过于细腻，会导致飞机速度减小缓慢，在 拉平阶段仍保持较高速度，从而使得飞机下沉过程变得迟缓，容易导致拉平高或者进入平飘 时仰角较小，影响着陆安全。" },
  { id: 1262, cat: "起降操纵1", q: "遥控无人机着陆时，收油门过早、过粗，速度减小快，使拉平的速度小，飞机下沉快，（）", opts: ["容易拉平高或者进入平飘时仰角较小", "容易拉平低或者进入平飘时仰角较大", "对飞机无影响"], ans: 1, exp: "遥控无人机在着陆时，如果收油门过早或动作过粗，会导致飞机的速度过快减小，使 得拉平时的速度偏小，飞机下沉速度加快。这种情况下，飞机在拉平时容易出现拉平高度过 低，或者进入平飘阶段时飞机的仰角过大，这可能会导致飞机在着陆时接地过猛，或者无法 实现平稳的着陆。" },
  { id: 1263, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况，收油门的时机应适当提前，收油门的动作适当加快？ （）", opts: ["实际下滑点在预定下滑点前面", "实际下滑点在预定下滑点后面", "实际下滑点与预定下滑点吻合"], ans: 0, exp: "在遥控无人机着陆时，油门的控制对于飞机的速度和下沉速率至关重要。如果飞机的 实际下滑点在预定下滑点的前面，这意味着飞机相对于预定的下滑路径飞得过远，此时飞机 的地速可能偏大，下沉速度偏慢。为了调整飞机回到正确的下滑轨迹，需要适当提前收油门，同时加快收油门的动作，以减少飞机的速度，加快下沉速度，确保飞机能够在正确的位置和 速度下进行着陆。" },
  { id: 1264, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况，收油门的时机应适当提前，收油门的动作适当加快？ （）", opts: ["当时的高度低于预定高度", "当时的高度高于预定高度", "当时的高度与预定高度吻合"], ans: 1, exp: "遥控无人机着陆时，如果飞机的高度高于预定高度，为了使无人机能够在合适的着陆 点降落，需要更快地减小高度。因此，收油门的时机应适当提前，以便更快地减小垂直速度，从而控制下降并达到预定着陆点。同时，收油门的动作也应适当加快，以确保飞机能够及时 减速并安全着陆。 所以，正确的答案是“当时的高度高于预定高度”。" },
  { id: 1265, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况，收油门的时机应适当提前，收油门的动作适当加快？ （）", opts: ["速度小、下沉快", "速度大、下沉慢", "下沉速度与预定速度符合"], ans: 1, exp: "当速度大、下沉慢时，说明飞机当前状态比正常着陆状态速度快且下沉不够快，如果 不及时调整，可能会导致飞机越过预定着陆点或者着陆时速度过大造成危险。所以在这种情 况下，收油门的时机应适当提前，并且收油门的动作适当加快，以尽快降低速度，让飞机能 正常下沉进行着陆。" },
  { id: 1266, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况，收油门的时机应适当提前，收油门的动作适当加快？ （）", opts: ["顺风较大", "逆风较大", "无风情况"], ans: 0, exp: "在遥控无人机着陆时，如果遇到顺风较大的情况，飞机的地速会增大。因为顺风会增 加飞机的空速，使得飞机相对于地面的速度增加，导致飞机在下滑过程中的下沉速度减慢。" },
  { id: 1267, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况，收油门的时机应适当延迟，收油门的动作适当减慢？ （）", opts: ["实际下滑点在预定下滑点前面", "实际下滑点在预定下滑点后面", "实际下滑点与预定下滑点吻合"], ans: 1, exp: "在无人机着陆时如果实际下滑点在预定下滑点后面，需要延迟收油门并减缓收油门的 动作，以防止飞机失速或下沉过快。" },
  { id: 1268, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况，收油门的时机应适当延迟，收油门的动作适当减慢？ （）", opts: ["当时高度低于预定高度", "当时高度高于预定高度", "当时高度与预定高度吻合"], ans: 0, exp: "当遥控无人机着陆时，当时的高度低于预定高度，意味着飞机离地面更近，但是还没 到达预定的着陆位置。如果此时过早收油门或者快速收油门，会让飞机下沉速度过快，可能 导致重着陆或者无法到达预定着陆点。所以在这种情况下，收油门的时机应适当延迟，收油 门的动作适当减慢，让飞机有更多时间调整高度和位置，平稳地到达预定着陆点。" },
  { id: 1269, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况，收油门的时机应适当延迟，收油门的动作适当减慢？ （）", opts: ["速度小、下沉快", "速度大、下沉慢", "下沉速度与预定速度符合"], ans: 0, exp: "遥控无人机着陆时，如果遇到速度小、下沉快的情况，这意味着无人机的下降速度超 过了正常着陆所需的下降速度。为了调整飞机的下降轨迹，使其更加平稳，避免因下降过快 而导致的硬着陆或提前接地，收油门的时机应适当延迟，收油门的动作也应适当减慢，以柔 和地减少飞机的下降速度。" },
  { id: 1270, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况，收油门的时机应适当延迟，收油门的动作适当减慢？ （）", opts: ["顺风较大", "逆风较大", "无风情况"], ans: 1, exp: "遥控无人机着陆时，如果遇到逆风较大的情况，由于逆风会减小飞机的地速，导致飞 机下沉速度变慢，因此需要适当延迟收油门的时机，并且减慢收油门的动作，以保持飞机的 下降速度和姿态，确保安全着陆。" },
  { id: 1271, cat: "起降操纵1", q: "遥控无人机着陆时，下列哪种情况需要复飞？（）", opts: ["飞机稍稍偏离期望下滑线", "飞机油料不足", "跑道上有飞机或其他障碍物影响着陆安全时"], ans: 2, exp: "遥控无人机着陆时需要复飞的情况是跑道上有飞机或其他障碍物影响着陆安全时。这 是因为在着陆过程中，确保跑道的清洁和安全是至关重要的，任何障碍物都可能导致着陆事 故。因此，一旦发现跑道上有障碍物，必须放弃着陆，执行复飞程序，以确保飞行安全。" },
  { id: 1272, cat: "起降操纵1", q: "遥控无人机着陆时，修正目测偏差，（）", opts: ["偏差大，加、收油门量相应大一些", "偏差大，加、收油门量相应小一些", "不必调整"], ans: 0, exp: "当遥控无人机着陆时，如果目测偏差大，说明飞机实际位置与理想着陆位置差距较大。 如果偏差大且飞机位置偏高或者速度偏快，需要加大收油门量，以更快地降低高度和速度； 如果偏差大且飞机位置偏低或者速度偏慢，需要加大加油门量，以提升高度和速度，从而调 整飞机位置，使飞机能够准确地降落到预定着陆点。" },
  { id: 1273, cat: "起降操纵1", q: "遥控无人机转弯时产生偏差的主要原因不包括（）", opts: ["进入和退出转弯时，动作不协调，产生侧滑", "转弯中，未保持好机头与天地线的关系位置，以致速度增大或减小", "天气状况不佳"], ans: 2, exp: "遥控无人机在转弯时产生偏差的原因通常与操纵者的控制技巧和飞行条件有关。而天 气状况不佳虽然是飞行中可能遇到的挑战，但它不是直接导致转弯偏差的原因。天气状况不 佳可能会影响飞行的安全性和稳定性，但它不是直接导致转弯偏差的操作因素。" },
  { id: 1274, cat: "起降操纵1", q: "着陆目测驾驶员对飞机飞行高度和降落点进行目视判断，对于目测质量的评判为（）", opts: ["机没有达到目测接地范围就接地的，叫目测低", "飞机没有达到目测接地范围就接地的，叫目测高", "飞机超过目测接地范围才接地的，叫目测低"], ans: 0, exp: "着陆目测主要是驾驶员凭借目视判断飞机飞行高度和降落点。如果飞机没有达到目测 接地范围就接地了，说明驾驶员判断的高度偏高，实际接地过早，这种情况叫目测低。" },
  { id: 1275, cat: "起降操纵1", q: "只有一条航道时，起飞和降落最好是什么风？（）", opts: ["逆风", "顺丰", "侧风"], ans: 0, exp: "只有一条航道时，起飞和降落最好是逆风。逆风条件下，飞机在起飞时可以利用迎面 而来的气流增加升力，从而减少所需的滑行距离。同时，逆风有助于降低着陆速度，使飞行 员有更多时间进行操作调整，增强飞行安全。" },
  // ==================== 起降操纵2 ====================
  { id: 1276, cat: "起降操纵2", q: "操纵无人机，起飞前需要了解的无人机的基本性能不包括（）", opts: ["无人机着陆性能", "无人机速度范围", "无人机升限"], ans: 2, exp: "操纵无人机，起飞前了解无人机着陆性能很重要，包括着陆速度、下滑角度等，这样 才能确保安全着陆；了解无人机速度范围可以帮助驾驶员在飞行过程中合理控制速度，避免 超出安全范围。而无人机升限一般在起飞前不是必须要了解的基本性能，因为在大多数常规 飞行中不太会接近升限飞行。因此，正确答案是：无人机升限。" },
  { id: 1277, cat: "起降操纵2", q: "操纵无人机起飞前，动力装置不需要检查的是（）", opts: ["发动机稳定性检查", "发动机生产日期", "发动机油路检查"], ans: 1, exp: "操纵无人机起飞前，对动力装置的检查主要是为了确保飞行安全和正常运行。发动机 稳定性检查非常重要，不稳定的发动机在飞行中可能出现故障，影响飞行安全。发动机油路 检查可以确保燃油正常供应，避免因油路问题导致发动机故障。 而发动机生产日期通常与当前飞行的安全性和正常运行没有直接关系，所以起飞前不需要检 查发动机生产日期。" },
  { id: 1278, cat: "起降操纵2", q: "操纵无人机长时间爬升，发动机温度容易升高，下列正确的操作是（）", opts: ["适时定高飞行，待各指标正常后再继续爬升", "发现发动机各参数不正常时迅速转下降", "不必操纵，信任发动机自身性能"], ans: 0, exp: "爬升发动机热，定高缓一缓。在操纵无人机进行长时间爬升时，由于发动机持续高负 荷工作，可能会导致发动机温度升高。为了确保发动机不过热并保持在安全的工作状态，正 确的做法是适时将无人机调整到定高飞行模式，这样可以让发动机暂时减轻负荷，待温度和 其他指标恢复正常后再继续爬升。这种做法有助于避免因发动机过热而引发的潜在故障或损 坏。" },
  { id: 1279, cat: "起降操纵2", q: "飞行驾驶员操纵无人机定高平飞时，下列正确的操纵是（）", opts: ["不断检查空速、高度和航向指示", "定高平飞结束前可以休息", "偶尔关注一下空速、高度和航向指示"], ans: 0, exp: "在飞行驾驶员操纵无人机定高平飞时，需要不断检查空速、高度和航向指示。因为即 使是定高平飞，也可能受到气流等因素的影响而出现偏差，只有不断检查这些关键参数，才 能及时发现问题并进行调整，确保飞行安全和稳定。" },
  { id: 1280, cat: "起降操纵2", q: "飞行驾驶员操纵无人机坡度转弯时，同时操纵方向舵的作用是（）", opts: ["进行协调转弯，可有效减小转弯半径并减少侧滑", "进行协调转弯，可有效增大转弯半径并减少侧滑", "进行协调转弯，可有效减小转弯半径并增大侧滑"], ans: 0, exp: "当飞行驾驶员操纵无人机坡度转弯时，同时操纵方向舵可以进行协调转弯。在协调转 弯中，飞机的横向力和偏航力相互平衡，这样可以有效减小转弯半径，使得转弯更加灵活。 同时，由于力的平衡，也能减少侧滑的发生，侧滑会影响飞行的稳定性和安全性。如果不进 行协调转弯，一方面转弯半径会较大，另一方面侧滑可能会导致飞机失去控制。" },
  { id: 1281, cat: "起降操纵2", q: "飞行驾驶员操纵无人机无坡度转弯，正确的操纵方式是（）", opts: ["向转弯方向压方向舵，副翼同方向打以保证坡度水平", "向转弯方向压方向舵，副翼反打以保证坡度水平", "转弯方向压方向舵，副翼同方向打以形成坡度"], ans: 1, exp: "在操纵无人机进行无坡度转弯时，正确的做法是向转弯方向压方向舵，同时副翼反打 以保证飞机的坡度保持水平。这是因为在转弯过程中，如果只压方向舵，飞机会产生坡度，导致一侧机翼比另一侧低，形成转弯坡度。为了保持坡度水平，需要通过副翼反打来抵消因 方向舵操作而产生的坡度，使飞机在转弯时保持水平飞行。" },
  { id: 1282, cat: "起降操纵2", q: "飞行驾驶员操纵无人机转弯时，可能出现的情况是（）", opts: ["在一定条件下的转弯中，坡度增大，机头会下俯，速度随即增大", "在一定条件下的转弯中，坡度增大，机头会上仰，速度随即减小", "在一定条件下的转弯中，坡度增大，机头会上仰，速度随即增大"], ans: 0, exp: "在飞行驾驶员操纵无人机进行转弯时，为了维持平衡和控制，无人机需要增加倾斜角 度（坡度），这通常会导致机头下俯，进而可能增加速度。因此“在一定条件下的转弯中，坡度增大，机头会下俯，速度随即增大”该选项正确。" },
  { id: 1283, cat: "起降操纵2", q: "飞行驾驶员操纵无人机转弯时，下列错误的过程描述是（）", opts: ["坡度形成，飞机即进入转弯", "改平坡度，飞机转弯即停止", "可以在只操纵方向舵不形成坡度的情况下实现快速高效转弯"], ans: 2, exp: "飞行驾驶员在操纵无人机进行转弯操作时，需要遵循一定的飞行动力学原理： 1.坡度形成，飞机即进入转弯：这是正确的。 当飞机形成一定的坡度时，由于重力和升力的合力产生向心力，飞机开始转弯。 2.改平坡度，飞机转弯即停止：这也是正确的。当飞机的坡度被改平时，向心力消失，飞机 将停止转弯并开始直飞。 3.可以在只操纵方向舵不形成坡度的情况下实现快速高效转弯：这是错误的。如果只操纵方 向舵而不形成坡度，飞机将会出现侧滑，因为飞机没有足够的升力分量来提供转弯所需的向 心力。 正确的转弯需要适当的坡度配合方向舵的使用，以实现协调转弯，避免侧滑。" },
  { id: 1284, cat: "起降操纵2", q: "飞行驾驶员操纵无人机转弯时，下列描述正确的操纵方式是（）", opts: ["机头过高时，应向转弯一侧的斜后方适当推杆并稍扭舵", "机头过高时，应向转弯一侧的斜前方适当推杆并稍扭舵", "机头过高时，应向转弯一侧的斜前方适当拉杆并稍扭舵"], ans: 1, exp: "当机头过高时，说明飞机姿态上扬，此时需要降低机头。向转弯一侧的斜前方适当推 杆可以使飞机低头，降低高度，同时稍扭舵可以协调转弯，保持飞机的转弯姿态稳定。" },
  { id: 1285, cat: "起降操纵2", q: "飞行驾驶员操纵无人机转弯时，下列描述正确的操纵方式是（）", opts: ["机头过低时，应向转弯一侧的斜后方适当拉杆并稍回舵", "机头过低时，应向转弯一侧的斜前方适当推杆并稍扭舵", "机头过低时，应向转弯一侧的斜前方适当拉杆并稍扭舵"], ans: 0, exp: "在操纵无人机转弯时，如果机头过低，说明飞机的俯仰姿态需要调整以增加一些上 升的力量，同时需要调整方向舵来控制飞机的机头方向。正确的操作是向转弯一侧的斜后方 适当拉杆，这样可以增加飞机的升力，帮助机头抬起，并且稍回舵以保持飞机在转弯中的 机头方向控制。这样的操作可以帮助飞机在转弯过程中保持良好的姿态和轨迹。" },
  { id: 1286, cat: "起降操纵2", q: "飞行驾驶员姿态遥控模式下操纵无人机下降，速度过大时，下列正确的操纵是（）", opts: ["适当减小带杆量，增大下滑角", "适当减小带杆量，减小下滑角", "适当增加带杆量，减小下滑角"], ans: 2, exp: "速度过大时应增加带杆量（拉杆）使机头上仰，减小下滑角以降低下降速度，避免俯 冲风险。" },
  { id: 1287, cat: "起降操纵2", q: "飞行驾驶员姿态遥控模式下操纵无人机下降时，下列正确的操纵是（）", opts: ["如俯角过小，应柔和地向前顶杆", "如俯角过小，应柔和地向后带杆", "如俯角过小，应柔和地向左压杆"], ans: 0, exp: "俯角小要下降，向前顶杆柔和。在姿态遥控模式下操纵无人机下降时，如果俯角过小，意味着机的机头相对于地面的角度不够，飞机可能会开始爬升而不是下降。为了增加俯角，使飞机正确下降，驾驶员应该柔和地向前顶杆，即推动操纵杆向前，以增加飞机的俯角，使 其正确下降。" },
  { id: 1288, cat: "起降操纵2", q: "飞行任务完成后不需要做的工作是（）", opts: ["检讨飞行执行过程", "填写飞行日志或记录本", "评价记录机组人员表现"], ans: 2, exp: "飞行任务完成后，通常需要检讨飞行执行过程，这样可以总结经验教训，以便在后续 飞行中改进。填写飞行日志或记录本是必要的工作，可以记录飞行的关键信息，为后续的分 析和查询提供依据。而评价并记录机组人员表现一般不是每次飞行任务完成后必须立即做的 工作，可能会在特定的阶段或按照一定的周期来进行。" },
  { id: 1289, cat: "起降操纵2", q: "通过地面站界面、控制台上的鼠标、按键、飞行摇杆操纵无人机的驾驶员称为（）", opts: ["飞行员", "起降驾驶员", "飞行驾驶员"], ans: 2, exp: "通过地面站界面、控制台上的鼠标、按键、飞行摇杆操纵无人机的驾驶员，通常称为 飞行驾驶员。这个称呼涵盖了操作无人机进行飞行任务的所有专业人员，无论他们操作的是 有人驾驶飞机还是无人机。" },
  { id: 1290, cat: "起降操纵2", q: "通过专用的遥控器外部控制盒操纵无人机的驾驶员称为（）", opts: ["飞行员", "起降驾驶员", "飞行驾驶员"], ans: 1, exp: "在无人机操作中，通过专用的遥控器外部控制盒操纵无人机的驾驶员通常被称为起降 驾驶员。这是因为这类驾驶员主要负责无人机的起飞和降落阶段，这些阶段对无人机的飞行 安全至关重要。飞行员、飞行驾驶员这样的称呼可能更广泛地用于指代操作飞机或无人机的 人员，但在这里特指使用外部控制盒进行起降操作的驾驶员。" },
  { id: 1291, cat: "起降操纵2", q: "无人机积水道面上起飞，其起飞距离比正常情况下（）", opts: ["长", "短", "相等"], ans: 0, exp: "当无人机在积水道面上起飞时，由于积水会减小轮胎与地面之间的摩擦力，导致飞机 在加速滑跑过程中容易出现打滑等不稳定情况，需要更长的滑跑距离才能达到起所需的速度，所以起飞距离比正常情况下长。" },
  { id: 1292, cat: "起降操纵2", q: "无人机驾驶员操纵无人机地面滑行时，下列描述正确的是（）", opts: ["主要通过控制方向舵杆量操纵", "主要通过控制副翼杆量操纵", "主要通过控制升降舵杆量操纵"], ans: 0, exp: "无人机驾驶员操纵无人机地面滑行时，主要是通过控制方向舵来调整无人机的滑行方 向。方向舵杆量的控制可以使无人机在地面上左右转向。" },
  { id: 1293, cat: "起降操纵2", q: "无人机驾驶员操纵无人机定高平飞航迹偏离时，下列描述正确的是（）", opts: ["如果轨迹方向偏离目标 5°以内，应柔和地向偏转的反方向适当扭舵杆", "如果轨迹方向偏离目标 5°以内，应柔和地向偏转的方向适当扭舵杆", "如果轨迹方向偏离目标 5°以内，应快速大幅度地向偏转的反方向适当扭舵杆"], ans: 0, exp: "当无人机在定高平飞时航迹偏离目标，正确的操作方法是柔和地向偏转的反方向适当 扭舵杆，以纠正航向。这是因为在飞行中，任何突然或大幅度的操作都可能导致无人机失控 或过度反应，从而增加飞行风险。因此，对于轻微的航迹偏离，应采取柔和且适当的调整。" },
  { id: 1294, cat: "起降操纵2", q: "无人机驾驶员操纵无人机定高平飞时，下列操纵正确的是（）", opts: ["如航迹方向偏离目标超过 5°，应缓慢地向偏转的反方向适当扭舵杆", "如航迹方向偏离目标超过 5°°，应协调地压杆扭舵，使飞机对正目标，然后改平坡度", "如航迹方向偏离目标超过 5°，应柔和地向偏转的方向适当扭舵杆"], ans: 1, exp: "在无人机定高平飞时，如果航迹方向偏离目标超过 5°，正确的操作方法是协调地压 杆扭舵，使飞机对正目标，然后改平坡度。这是因为当航迹偏离较大时，需要更积极地调整 飞机的姿态和航向，以确保「飞机能够准确返回到预定的航迹上。压杆可以改变飞机的坡度，扭舵可以调整飞机的航向，两者协调操作可以实现精准的航迹修正。" },
  { id: 1295, cat: "起降操纵2", q: "无人机驾驶员操纵无人机复飞时，油门状态描述正确的是（）", opts: ["逐渐推至大车状态", "保持小油门", "逐渐收至小车状态"], ans: 0, exp: "当无人机驾驶员操纵无人机复飞时，需要有足够的动力来重新获得高度和速度。逐渐 推至大车状态（即加大油门）可以使发动机输出更大的功率，为无人机提供更强的上升动力。" },
  { id: 1296, cat: "起降操纵2", q: "无人机驾驶员操纵无人机拉平时，下列描述正确的是（）", opts: ["小偏差时不必修正，待形成一定偏差时修正即可", "快速根据飞机偏差大力度修正", "正确的拉平动作，必须按照实际情况，主动地、有预见地、机动灵活地去操纵飞机"], ans: 2, exp: "在无人机驾驶员操纵无人机拉平时，正确的做法是根据实际情况，主动地、有预见地、机动灵活地去操纵飞机。这是因为拉平是一个需要精确控制的过程，任何过度或不足的操纵 都可能导致飞机姿态不稳定或偏离预定的飞行路径。因此，驾驶员需要根据飞机的实际飞行 状态和偏差，灵活调整操纵量，确保飞机平稳地过渡到平飞状态。" },
  { id: 1297, cat: "起降操纵2", q: "无人机驾驶员操纵无人机平飞转爬升时，下列操纵易产生偏差的是（）", opts: ["及时检查地平仪位置关系，及时修正偏差", "平飞、爬升飞行状态变换时，推杆、拉杆方向不正，干扰其他通道", "动作柔和，且有提前量"], ans: 1, exp: "在无人机平飞转爬升的过程中，如果推杆、拉杆方向不正，可能会干扰飞机的其他控 制通道，导致飞机的飞行状态出现偏差。这是因为在飞行状态变换时，需要精确协调各个 控制面的动作，以确保飞机平稳地从平飞过渡到爬升状态。如果方向控制不准确，可能会 导致飞机产生不必要的滚转或偏航，从而影响爬升的质量和安全性。" },
  { id: 1298, cat: "起降操纵2", q: "无人机驾驶员操纵无人机刹车时机，描述正确的是（）", opts: ["飞机接地后，马上刹车", "飞机接地后，待速度降到安全范围内刹车", "飞机接地后，待飞机滑停后再刹车"], ans: 1, exp: "在无人机着陆后，驾驶员需要等待飞机的速度降低到一个安全的范围内再进行刹车操 作。这是为了确保飞机在刹车时不会因为速度过快而导致失控或者损害。" },
  { id: 1299, cat: "起降操纵2", q: "无人机驾驶员操纵无人机下降到 10 米以下时，应重点关注的信息是（）", opts: ["飞机下降速度、姿态和空速", "飞机剩余油量", "飞机航行灯开闭状态"], ans: 0, exp: "无人机驾驶员在操纵无人机下降到 10 米以下时，应重点关注飞机的下降速度、姿态 和空速。这些信息对于确保无人机安全着陆至关重要。在低高度飞行时，飞机的下降速度需 要控制得当，以避免过快下降导致硬着陆或过慢下降影响着陆点的准确性。同时，飞机的姿 态和空速也是保证飞机稳定下降的关键因素。" },
  { id: 1300, cat: "起降操纵2", q: "无人机驾驶员操纵无人机下降时，油门状态描述正确的是（）", opts: ["大油门保证飞机速度", "小油门便于飞机下降", "油门置于中间状态留足操纵空间"], ans: 1, exp: "在无人机下降过程中，正确的油门状态应该是小油门，这样便于飞机下降。因为减 小油门可以减少发动机推力，降低飞机的空速，使飞机能够更平稳地下降。在下降过程中，通常不需要大油门来保持速度，而是需要适当减少推力，以便更好地控制飞机的下降速度和 姿态。" },
  { id: 1301, cat: "起降操纵2", q: "无人机驾驶员操纵无人机着陆滑跑时，油门状态描述正确的是（）", opts: ["飞机接地后，为保证安全一般将油门收为零", "飞机接地后，将油门保持大车状态，准备随时复飞", "飞机接地后，着陆滑跑一段距离再收油门"], ans: 0, exp: "在无人机着陆滑跑阶段，为了确保安全，通常的做法是在飞机接地后将油门收为零。 这样做可以防止因为油门过大而导致飞机重新离地或者在地面上滑行过快，从而失去控制。" },
  { id: 1302, cat: "起降操纵2", q: "无人机驾驶员关于无人机发动机不需要了解的是（）", opts: ["大车状态的连续工作时间", "稳定怠速", "发动机生产日期"], ans: 2, exp: "无人机驾驶员需要了解发动机的性能参数和操作特性，以确保飞行安全和发动机的正 确使用。大车状态的连续工作时间和稳定怠速是发动机操作中的重要参数，它们关系到发动 机的性能和飞行安全。而发动机的生产日期虽然对于维护和记录保持有一定的意义，但对于 驾驶员在实际操作中并不需要特别关注，因为它不影响发动机的操作和性能。" },
  { id: 1303, cat: "起降操纵2", q: "无人机驾驶员关于无人机飞定速度范围不需要了解的是（）", opts: ["海平面不同重量下的速度范围", "极限高度内的速度范围", "极限高度外的速度范围"], ans: 2, exp: "无人机驾驶员需要了解无人机在不同条件下的飞行速度范围，这包括在海平面不同重 量下的速度范围和在极限高度内的速度范围。这些信息对于确保无人机在各种飞行条件下的 安全和性能至关重要。极限高度外的速度范围对于无人机驾驶员来说并不是必须了解的，因 为无人机的设计和操作通常限定在一定的飞行包线内，超出这个范围的操作是不被允许的。" },
  { id: 1304, cat: "起降操纵2", q: "无人机驾驶员关于无人机飞行速度限制不需要了解的是（）", opts: ["俯冲最大速度", "不同高度、重量下的失速速度", "静止时飞机零漂速度"], ans: 2, exp: "无人机驾驶员需要了解无人机的俯冲最大速度和不同高度、重量下的失速速度，因这 些速度限制直接关系到飞行安全和飞机的性能。俯冲最大速度是无人机在俯冲时不能超过的 速度，以避免结构损坏或失控。失速速度是无人机在特定高度和重量下失去升力的最低速度，了解这个速度可以防止飞机失速。而静止时飞机零漂速度通常指的是飞机在地面静止时的移 动速度，这在飞行操作中并不重要，因此不是驾驶员需要了解的速度限制。" },
  { id: 1305, cat: "起降操纵2", q: "无人机驾驶员遥控无人机起飞滑跑描述正确的是（）", opts: ["迅速将油门推至大车并快速拉杆起飞", "逐渐将油门推至大车并在速度达到起飞速度时柔和拉杆起飞", "将油门迅速推至大车，等飞机速度积累到足够使其自动起飞"], ans: 1, exp: "无人机驾驶员在遥控无人机起飞滑跑时，正确的操作是逐渐将油门推至最大（大车），并在速度达到起飞速度时柔和拉杆起飞。这种操作可以确保无人机平稳地加速至起飞速度，并在适当的时刻通过柔和拉杆来实现起飞，避免因操作过急导致飞机失控或损坏。" },
  { id: 1306, cat: "起降操纵2", q: "无人机前轮偏转的目的，（）", opts: ["主要是为了地面拖飞机", "保证飞机滑行转弯和修正滑跑方向", "前轮摆振时减小受力"], ans: 1, exp: "无人机前轮偏转可以保证飞机在滑行过程中顺利转弯，并且可以修正滑跑方向，确保 飞机在地面滑行时的稳定性和安全性。" },
  { id: 1307, cat: "起降操纵2", q: "下列不属于对无人机机长训练要求的是（）", opts: ["在模拟器实施系统检查程序，不少于 1 小时", "在实物训练系统实施系统检查程序，不少于 3 小时", "取得仪表资格"], ans: 2, exp: "无人机机长的训练要求通常包括对无人机系统的熟悉程度、操作技能以及对飞行程序 的掌握。这通常涉及到在模拟器或实物训练系统中进行系统检查程序的训练，以确保机长能 够熟练地操作无人机并执行各种飞行任务。 而取得仪表资格，通常与有人驾驶飞机的飞行员相关，对于无人机机长而言，虽然他们需要 掌握如何在复杂气象条件下飞行，但“取得仪表资格”这一说法并不适用于无人机机长的训 练要求。" },
  { id: 1308, cat: "起降操纵2", q: "下列不属于对无人机机长训练要求的是（）", opts: ["有参与研制飞行模拟器经历", "在实物训练系统实施正常飞行程序指挥，不少于 10 小时", "在模拟器实施正常飞行程序指挥，不少于 3 小时"], ans: 0, exp: "无人机机长的训练要求包括在实物训练系统和模拟器中实施飞行程序指挥，而参与研 制飞行模拟器的经历并不是必需的。" },
  { id: 1309, cat: "起降操纵2", q: "下列不属于对无人机驾驶员训练要求的是（）", opts: ["在模拟器实施飞行前检查，不少于 1 小时", "在实物训练系统实施飞行前检查，不少于 3 小时", "在实物训练系统实施应急飞行程序指挥，包括规避航空器、发动机故障、链路丢失、应 急回收、迫降等，不少于 10 小时"], ans: 2, exp: "无人机驾驶员的训练要求通常包括在模拟和实物训练系统中进行飞行前检查、正常飞 行程序以及应急飞行程序的训练。而选项中在实物训练系统实施应急飞行程序指挥，包括规 避航空器、发动机故障、链路丢失、应急回收、迫降等不少于 10 小时是对无人机机长的训 练要求，而非驾驶员。" },
  { id: 1310, cat: "起降操纵2", q: "下列不属于对无人机视距内驾驶员训练要求的是（）", opts: ["在模拟器实施正常飞行程序操作，不少于 3 小时", "在实物训练系统实施正常飞行程序操作，不少于 10 小时", "在模拟器实施应急飞行程序指挥，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 3 小时"], ans: 2, exp: "视距内练正常，不涉复杂应急。无人机视距内驾驶员的训练要求包括在模拟器实施正 常飞行程序操作不少于 3 小时，以及在实物训练系统实施正常飞行程序操作不少于 10 小时。 而对于模拟器实施应急飞行程序指挥的训练要求，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 3 小时，这是针对超视距驾驶员的训练要求。因此，不属于对无 人机视距内驾驶员训练要求的是“在模拟器实施应急飞行程序指挥”。" },
  { id: 1311, cat: "起降操纵2", q: "下列不属于飞行后进行的内容是（）", opts: ["检讨飞行执行过程", "填写飞行日志或记录本", "规划飞行航线"], ans: 2, exp: "飞行后通常会对整个飞行执行过程进行检讨，总结经验教训，属于飞行后进行的内容； 填写飞行日志或记录本，记录飞行的相关信息，为后续飞行提供参考，也是飞行后做的事情。 而规划飞行航线是在飞行前进行的准备工作，不属于飞行后进行的内容。" },
  { id: 1312, cat: "起降操纵2", q: "下列不属于转弯时易产生的偏差描述和原因的是（）", opts: ["进入和退出转弯时，动作不协调，产生侧滑", "转弯中，未保持好机头与天地线的关系位置，以致速度增大或减小", "发动机推力不足，导致形成高度偏差"], ans: 2, exp: "在无人机转弯时，产生偏差的描述和原因通常涉及飞行操作技巧和飞行条件。而发动 机推力不足，导致形成高度偏差通常不是转弯时直接产生的偏差描述和原因。发动机推力不 足可能导致飞机无法维持当前高度或爬升，但这与转弯操作本身不直接相关，更多是与飞机 的动力系统和飞行路径控制相关。" },
  { id: 1313, cat: "起降操纵2", q: "下列属于对无人机机长训练要求的是（）", opts: ["在模拟器实施应急飞行程序指挥，包括规避航空器、发动机故障、链路丢失、应急回收、迫降等，不少于 3 小时", "在模拟器实施正常飞行程序操作，不少于 3 小时", "实物训练系统实施正常飞行程序操作，不少于 10 小时"], ans: 0, exp: "对于无人机机长来说，需要具备应对各种紧急情况的能力。在模拟器上实施应急飞行 程序指挥，如规避航空器、处理发动机故障、应对链路丢失、进行应急回收和迫降等情况，可以让机长在安全的环境下模拟真实的紧急场景，积累处理突发情况的经验，不少于 3 小时 的训练时间可以确保机长对这些应急程序有较为充分的熟悉和掌握。" },
  { id: 1314, cat: "起降操纵2", q: "下列属于对无人机驾驶员训练要求的是（）", opts: ["在模拟器实施应急飞行程序操作，包括发动机故障、链路丢失、应急回收、迫降等，不 少于 3 小时", "在模拟器实施正常飞行程序指挥，不少于 3 小时", "在实物训练系统实施正常飞行程序指挥，不少于 10 小时"], ans: 0, exp: "对于无人机驾驶员来说，需要掌握在紧急情况下的操作能力。在模拟器上实施应急飞 行程序操作，如应对发动机故障、链路丢失、应急回收和迫降等情况，可以让驾驶员在相对 安全的环境中熟悉紧急情况的处理流程，不少于 3 小时的训练可以确保有一定的熟练度。" },
  { id: 1315, cat: "起降操纵2", q: "遥控无人机着陆时，对用侧滑的方法修正侧风影响的正确描述是（）", opts: ["判明偏流的方向及影响大小，适量向侧风方向压杆形成坡度，并反扭舵抵制飞机转弯", "判明偏流的方向及影响大小，适量向侧风反方向压杆形成坡度，并反扭舵抵制飞机转弯", "判明偏流的方向及影响大小，适量向侧风方向压杆形成坡度，并同向扭舵抵制飞机转弯"], ans: 0, exp: "当遥控无人机着陆时遇到侧风影响，首先要判明偏流的方向及影响大小。适量向侧风 方向压杆可以形成坡度，这样能让飞机的运动方向与侧风方向有一定的夹角，从而抵消部分 侧风的影响。同时，由于压杆形成坡度会使飞机有转弯的趋势，所以要反扭舵来抵制飞机转 弯，保持飞机的正确航向和姿态进行着陆。" },
  { id: 1316, cat: "起降操纵2", q: "遥控无人机着陆时，对用侧滑的方法修正风影响描述正确的是（）", opts: ["下降率增大，目测容易低，应适当加油门修正", "下降率增大，目测容易高，应适当减油门修正", "下降率减小，目测容易低，应适当加油门修正"], ans: 0, exp: "在遥控无人机着陆时，使用侧滑方法修正侧风影响的正确描述是：下降率增大，目测 容易低，应适当加油门修正。这是因为在侧风条件下，无人机可能会因为侧风的推动而出现 下降率增大的情况，导致无人机相对于地面的位置看起来比实际低。为了修正这种偏差，需 要适当增加油门，以增加升力，抵消侧风的影响，确保无人机能够平稳着陆。" },
  { id: 1317, cat: "起降操纵2", q: "遥控无人机着陆时，对用侧滑与改变航向相结合的方法修正侧风影响描述正确的是（）", opts: ["退出第四转弯的时机应根据风向适当提前或延迟", "退出第四转弯的时机一律适当提前", "退出第四转弯的时机一律适当延迟"], ans: 0, exp: "在遥控无人机着陆时，用侧滑与改变航向相结合的方法修正侧风影响，需要根据风向 来调整退出第四转弯的时机。如果是顺风，飞机地速会增加，可能需要适当提前退出第四转 弯以保证正常的下滑线和着陆点；如果是逆风，飞机地速会减小，可能需要适当延迟退出第 四转弯。所以退出第四转弯的时机应根据风向适当提前或延迟。" },
  { id: 1318, cat: "起降操纵2", q: "遥控无人机着陆时，关于大逆风着陆描述正确的是（）", opts: ["第三转弯时机应适当延后，以便第四转弯点距降落点比正常略近一些", "第三转弯时机应适当提前，以便第四转弯点距降落点比正常略近一些", "第三转弯时机应适当提前，以便第四转弯点距降落点比正常略远一些"], ans: 1, exp: "在遥控无人机大逆风着陆时，由于风的阻力较大，飞机地速减小，飞行距离缩短。为 了确保能在合适的位置着陆，第三转弯时机应适当提前，这样可以使第四转弯点距降落点比 正常情况略近一些，以便更好地调整下滑航线和着陆位置。" },
  { id: 1319, cat: "起降操纵2", q: "遥控无人机着陆时，关于大逆风着陆描述正确的是（）", opts: ["第三转弯后，适当提前下滑时机，进入第四转弯的高度应比正常风速时略低", "第三转弯后，适当延迟下滑时机，进入第四转弯的高度应比正常风速时略高", "第三转弯后，适当提前下滑时机，进入第四转弯的高度应比正常风速时略高"], ans: 1, exp: "在大逆风情况下着陆，飞机的地速会减小，需要更多的时间和距离来完成着陆过程。 所以第三转弯后，要适当延迟下滑时机，让飞机有足够的时间和距离来克服逆风的影响。同 时，进入第四转弯的高度应比正常风速时略高，这样可以在下滑过程中有更多的余量来调整 飞机的姿态和高度，确保安全着陆。" },
  { id: 1320, cat: "起降操纵2", q: "遥控无人机着陆时，关于大逆风着陆描述正确的是（）", opts: ["四转弯后，地速减小，下滑角增大，下滑点应适当前移，并及时减小油门保持相应的速 度下滑", "四转弯后，地速增加，下滑角减小，下滑点应适当后移，并及时减小油门保持相应的速 度下滑", "四转弯后，地速减小，下滑角增大，下滑点应适当前移，并及时加大油门保持相应的速 度下滑"], ans: 2, exp: "在大逆风着陆时，四转弯后，由于逆风的影响，地速会减小。而地速减小会导致下滑 角增大，为了保持合适的下滑轨迹，下滑点应适当前移。同时，为了保持相应的速度下滑，需要及时加大油门来克服逆风的阻力，确保飞机有足够的动能安全着陆。" },
  { id: 1321, cat: "起降操纵2", q: "遥控无人机着陆时，关于大逆风着陆描述正确的是（）", opts: ["下滑空速度较大，舵面效用较强，开始拉平的时机应比正常稍晚", "下滑空速度较大，舵面效用较强，开始拉平的时机应比正常稍早", "下滑空速度较小，舵面效用较弱，开始拉平的时机应比正常稍早"], ans: 0, exp: "大逆风时，无人机地速减小但空速增大，舵面效应增强，需更多时间减速。因此拉平 时机应比正常稍晚，避免过早拉平导致重着陆或复飞。" },
  { id: 1322, cat: "起降操纵2", q: "遥控无人机着陆时，关于大逆风着陆描述正确的是（）", opts: ["拉平后，速度减小加快，平飘距离缩短", "拉平后，速度减小加快，平飘距离增长", "拉平后，速度增大加快，平飘距离缩短"], ans: 0, exp: "在遥控无人机大逆风着陆时，拉平后，风的阻力会使飞机速度减小加快。由于逆风的 影响，飞机的地速降低，平飘距离也会相应缩短。如果不考虑逆风的影响，按照正常情况操 作，可能会导致飞机飞过着陆点或者着陆时速度较大。" },
  { id: 1323, cat: "起降操纵2", q: "遥控无人机着陆时，关于大逆风着陆描述正确的是（）", opts: ["平飘前段，速度较大，飞机下沉较慢，拉杆的动作应快速，防止拉飘", "平飘前段，速度较大，飞机下沉较慢，拉杆的动作应柔和，防止拉飘", "平飘前段，速度小，飞机下沉较快，拉杆的动作应快速，防止下沉过快"], ans: 1, exp: "在大逆风着陆时，平飘前段，由于逆风影响，速度较大，此时飞机下沉相对较慢。如 果拉杆动作快速，很容易使飞机过度上升导致拉飘，所以拉杆的动作应柔和，慢慢调整飞机 姿态，防止拉飘。" },
  { id: 1324, cat: "起降操纵2", q: "遥控无人机着陆时，关于大逆风着陆描述正确的是（）", opts: ["着陆后，立即刹车", "着陆后，地速减小快，刹车不要太早", "着陆后，地速减小慢，刹车不要太晚"], ans: 1, exp: "在大逆风着陆时，飞机着陆后，由于逆风的作用，地速减小快。如果刹车太早，可能 会导致飞机出现不稳定的情况甚至侧滑等危险。所以刹车不要太早，应先让飞机在逆风的作 用下自然减速一段时间，待速度降低到较为合适的时候再刹车。" },
  { id: 1325, cat: "起降操纵2", q: "遥控无人机着陆时，关于顺风着陆描述正确的是（）", opts: ["进入三转弯的时机应适当延迟，转弯的角度应适当减小，使第四转弯点距着陆点的距离 适当远一些", "进入三转弯的时机应适当提前，转弯的角度应适当增大，使第四转弯点距着陆点的距离 适当近一些", "正常时机三转弯即可，四转弯点距着陆点距离远近不影响安全着陆"], ans: 0, exp: "在遥控无人机顺风着陆时，由于顺风会使飞机地速增加，下滑角变小，飞机前进的距 离变长。为了确保能在合适的位置着陆，进入三转弯的时机应适当延迟，这样可以让飞机在 空中多飞行一段时间以抵消顺风带来的影响。同时，转弯的角度应适当减小，使第四转弯点 距着陆点的距离适当远一些，以便有足够的距离来调整飞机的下滑航线和速度。" },
  { id: 1326, cat: "起降操纵2", q: "遥控无人机着陆时，关于顺风着陆描述正确的是（）", opts: ["进入四转弯的高度应比正常稍低，收油门下滑和进入时机应适当提前", "进入四转弯的高度应比正常稍高，收油门下滑和进入时机应适当延后", "进入四转弯的高度应比正常稍低，收油门下滑和进入时机应适当延后"], ans: 0, exp: "在遥控无人机顺风着陆时，由于顺风会使飞机地速增加，下滑距离变长，飞机下沉变 慢。所以进入四转弯的高度应比正常稍低，以便更早地开始下滑。同时，收油门下滑和进入 时机应适当提前，这样可以确保飞机在合适的位置着陆，避免飞过着陆点。" },
  { id: 1327, cat: "起降操纵2", q: "遥控无人机着陆时，关于顺风着陆描述正确的是（）", opts: ["四转弯后，地速减小，下滑角增大，下滑点应适当前移，下滑速度比正常大一些", "四转弯后，地速增大，下滑角减小，下滑点应适当后移，下滑速度比正常小一些", "四转弯后，地速增大，下滑角减小，下滑点应适当前移，下滑速度比正常大一些"], ans: 1, exp: "顺风着陆时，四转弯后，由于顺风的作用，地速会增大。地速增大使得飞机相对空气 的运动速度变化，从而导致下滑角减小。下滑点应适当后移，因为地速大了，飞机向前运动 的距离会增加，如果下滑点不后移容易飞过预定着陆点。同时，下滑速度比正常小一些，因 为顺风使飞机相对地面的速度增加，相对空气的下滑速度就会比正常小。" },
  { id: 1328, cat: "起降操纵2", q: "遥控无人机着陆时，关于顺风着陆描述正确的是（）", opts: ["下滑空速度较大，舵面效用较强，在拉平过程中，拉杆动作应及时、适量，防止拉平高", "下滑空速度较小，舵面效用较弱，在拉平过程中，拉杆动作应及时、适量，防止拉平低", "跟无风情况下一样，不需特别操作"], ans: 1, exp: "顺风着陆时，由于顺风影响，飞机的下滑空速度较小。下滑空速度小会导致舵面效用 减弱，也就是操纵飞机的反应会变慢、效果变弱。在拉平过程中，为了保证飞机能平稳着陆，拉杆动作应及时、适量。如果拉杆不及时或者拉杆量不够，飞机可能拉平低，导致重着陆等 情况。" },
  { id: 1329, cat: "起降操纵2", q: "遥控无人机着陆时，关于顺风着陆描述正确的是（）", opts: ["地速较大，平飘距离较长", "地速较小，平飘距离较短", "地速正常，平飘距离正常"], ans: 0, exp: "在遥控无人机顺风着陆时，风与飞机运动方向相同，会使飞机的地速较大。地速大意 味着飞机在空中的水平移动速度快，在相同的下降率情况下，平飘距离会较长。因为飞机需 要更长的距离来逐渐降低速度，实现平稳着陆。" },
  { id: 1330, cat: "起降操纵2", q: "遥控无人机着陆时，关于顺风着陆描述正确的是（）", opts: ["着陆滑跑中，应及时刹车，以免滑跑距离过长", "着陆滑跑中，应延后刹车，以免滑跑距离过短", "着陆滑跑中，按正常时机刹车即可"], ans: 0, exp: "遥控无人机顺风着陆时，由于顺风会使飞机地速较大，在着陆滑跑过程中飞机的前进 速度快，滑跑距离会变长。所以应及时刹车，以防止滑跑距离过长超出安全范围。如果不及 时刹车，可能会导致飞机无法在预定区域内停下来，增加发生事故的风险。" },
  { id: 1331, cat: "起降操纵2", q: "以下哪一种情景容易引起飞行员产生飞机比实际位置高的错觉？（）", opts: ["常规跑道", "向上带斜坡的地形", "向下带斜坡的地形"], ans: 1, exp: "当飞行员在进场时遇到向上带斜坡的地形，即离跑道起跑线较远处的地表海拔较低，越靠近跑道边呈渐渐升高的情况，飞行员将产生进场角度看似较高的错觉。这种情况下，飞 行员可能会认为飞机比实际位置偏高，因此选项“向上带斜坡的地形”是正确描述。" },
  { id: 1332, cat: "起降操纵2", q: "着陆后检查内容不包括（）", opts: ["飞行外观检查", "燃油动力飞行器需要称重检查", "气象检查"], ans: 2, exp: "无人机着陆后的检查内容通常包括对飞行器的各个系统和部件进行检查，以确保飞行 器的状态良好，为下一次飞行做好准备。而气象检查通常是在飞行前进行的，以获取飞行区 域的气象信息，如风速、风向、温度、湿度、能见度等，从而评估飞行条件是否适合飞行。 气象检查对于飞行安全至关重要，但它不是着陆后的检查内容。" },
  { id: 1333, cat: "起降操纵2", q: "姿态遥控模式下操纵无人机爬升，飞机带右坡度时，下列正确的操纵是（）", opts: ["应柔和地向前顶杆", "应柔和地回杆或向左压杆", "应柔和地向右压杆"], ans: 1, exp: "在姿态遥控模式下，飞机带右坡度时需要进行修正。柔和地回杆可以减少飞机的上升 趋势，向左压杆可以使飞机向左倾斜，从而抵消右坡度，让飞机恢复平稳的飞行姿态。" },
  { id: 1334, cat: "起降操纵2", q: "姿态遥控模式下操纵无人机爬升，飞机带左坡度时，下列正确的操纵是（）", opts: ["应柔和地向前顶杆", "应柔和地向左压杆", "应柔和地回杆或向右压杆"], ans: 2, exp: "在姿态遥控模式下，飞机带左坡度时需要进行修正。柔和地回杆可以减少飞机的上升 趋势，向右压杆可以使飞机向右倾斜，从而抵消左坡度，让飞机恢复平稳的飞行姿态。" },
  { id: 1335, cat: "起降操纵2", q: "姿态遥控模式下操纵无人机爬升，飞机航向向右偏离时，下列正确的操纵是（）", opts: ["应柔和地向前顶杆", "应柔和地向左扭舵", "应柔和地向右扭舵"], ans: 1, exp: "在姿态遥控模式下操纵无人机爬升时，如果飞机的航向向右偏离，这意味着飞机 需要向左修正航向。在姿态遥控模式下，无人机的偏航控制通常由方向舵（或相应的控制面）来实现。因此，为了减少向右的偏航，驾驶员需要柔和地向左扭舵，以对抗向右的偏航趋势。" },
  { id: 1336, cat: "起降操纵2", q: "姿态遥控模式下操纵无人机爬升，飞机航向向左偏离时，下列正确的操纵是（）", opts: ["应柔和地向前顶杆", "应柔和地向左扭舵", "应柔和地向右扭舵"], ans: 2, exp: "在姿态遥控模式下操纵无人机爬升时，如果飞机航向向左偏离，正确的操纵是应柔 和地向右扭舵。这是因为在姿态模式下，驾驶员的操纵直接控制飞机的副翼和方向舵，而扭 舵控制的是飞机的偏航运动，即左右转向。向右扭舵会增加飞机右侧方向舵的舵量，使飞机 的机头向右转动，从而纠正向左的偏离。" },
  { id: 1337, cat: "起降操纵2", q: "姿态遥控模式下操纵无人机爬升，飞机爬升率过小时，下列正确的操纵是（）", opts: ["柔和减小俯仰角", "柔和增大俯仰角", "迅速停止爬升"], ans: 1, exp: "在姿态遥控模式下操纵无人机爬升时，如果飞机爬升率过小，意味着飞机向上的倾 斜角度不够。柔和增大俯仰角，也就是让飞机机头向上抬得更高一些，这样会增加飞机的爬 升角度，从而增大爬升率。" },
  { id: 1338, cat: "起降操纵2", q: "姿态遥控模式下操纵无人机爬升，飞机速度减小太多时，下列正确的操纵是（）", opts: ["迅速减小俯仰角", "迅速增大俯仰角", "迅速关闭发动机"], ans: 0, exp: "在姿态遥控模式下操纵无人机爬升时，如果飞机速度减小太多，说明飞机的俯仰角 可能过大，导致飞机爬升角度过于陡峭，损失了水平速度。为了增加飞机的速度，需要减 少俯仰角，使飞机的机头向下一些，以增加水平速度。因此，正确的操纵是迅速减小俯仰角。" },
  { id: 1339, cat: "起降操纵2", q: "姿态遥控模式下操纵无人机爬升，俯仰角偏低时，下列正确的操纵是（）", opts: ["应柔和地向前顶杆", "应柔和地向后带杆", "应柔和地向右扭舵"], ans: 1, exp: "在姿态遥控模式下操纵无人机爬升时，如果俯仰角偏低，意味着飞机的机头相对于水 平面的角度不够，飞机无法有效地爬升。为了增加飞机的俯仰角，帮助其爬升，正确的操纵 是应柔和地向后带杆，这样可以增加飞机的俯仰角度，使其能够顺利爬升。" },
  { id: 1340, cat: "起降操纵2", q: "姿态遥控模式下操纵无人机爬升，俯仰角偏高时，下列正确的操纵是（）", opts: ["应柔和地向前顶杆", "应柔和地向后带杆", "应柔和地向右扭舵"], ans: 0, exp: "在姿态遥控模式下操纵无人机爬升时，如果俯仰角偏高，意味着飞机的机头相对于水 平面抬得太高，可能会导致飞机超过所需的爬升角度，增加失速的风险。为了减小俯仰角，使飞机达到一个更安全的爬升姿态，驾驶员需要柔和地向前顶杆，这样可以减小飞机的迎角，从而降低俯仰角。" },
  // ==================== 综合问答 ====================
  { id: 1341, cat: "综合问答", q: "（电台、接收机、调速器、电池、GPS、电机）多旋翼无人机，以下哪个组设备连接是正 确的？（）", opts: ["调速-电机-GPS-接收机", "接收机-调速器-电池-电台", "电池-调速器-电机"], ans: 2, exp: "在多旋翼无人机的系统中，电池提供电力，调速器（ESC, Electronic Speed Controller）用于控制电机的速度，电机则是无人机的动力来源。因此，正确的连接顺序是电池连接到调 速器，调速器再连接到电机。" },
  { id: 1342, cat: "综合问答", q: "10000mAh/6S/15C 的电池充电，设置安全电流多少安？（）", opts: ["150A", "10A", "60A"], ans: 1, exp: "首先明确电池参数的含义，10000mAh 是电池容量，6S 表示 6 节电池串联，15C 是放 电倍率。安全电流等于电池容量乘以充电倍率，一般充电倍率取 1C 较为安全。10000mAh=10Ah，1C 即 10A。" },
  { id: 1343, cat: "综合问答", q: "10000mAh 电池 1A 充电，充电倍率是多少？（）", opts: ["1.0C", "0.1C", "10C"], ans: 1, exp: "电池的充电倍率（C-rate）是指电池在 1 小时内能够接受或放出的电量。对于 10000mAh 的电池，其 1C 的电流为 10000mAh，即 10A。如果以 1A 的电流充电，则充电倍率为 1A/10A=0.1C。 因此，正确答案是 0.1C。" },
  { id: 1344, cat: "综合问答", q: "1045 CCW 其含义是（）", opts: ["桨叶直径 10in，螺距 45in，顺时针", "桨叶直径 10mm，螺距 4.5mm，逆时针", "桨叶直径 10in，螺距 4.5in，逆时针"], ans: 2, exp: "螺旋桨型号 1045CCW 的含义是桨叶直径为 10 英寸，螺距为 4.5 英寸，且螺旋桨的旋 转方向为逆时针。这个型号的表示方法中，数字“10”代表桨叶的直径，单位是英寸；数字 “45”中的“4”代表螺距，单位同样是英寸；“CCW”是“CounterClockwise”的缩写，表 示逆时针旋转。" },
  { id: 1345, cat: "综合问答", q: "1865 桨 300KV 电机，2045 桨 500KV 电机同一架多轴，如果在高海拔地区飞行，应该选择 哪种桨和电机的组合？（）", opts: ["2045 桨 500KV 电机", "1865 桨 300KV 电机", "都可以"], ans: 0, exp: "高海拔地区空气稀薄，需要更大的拉力。电机的 KV 值越低，在相同电压下转速越低； 桨叶尺寸越大、电机 KV 值越高，一般产生的拉力越大。 2045 桨尺寸大于 1865 桨，500KV 电机的 KV 值大于 300KV，所以在高海拔地区飞行应选择 2045 桨 500KV 电机的组合。" },
  { id: 1346, cat: "综合问答", q: "1 英寸等于多少厘米？（）", opts: ["2.54cm", "25.4cm", "254cm"], ans: 0, exp: "1 英寸等于 2.54 厘米，这是国际单位制中长度单位的换算关系。英寸是英制单位，而厘米是公制单位，它们之间的换算关系是 1 英寸=2.54 厘米。" },
  { id: 1347, cat: "综合问答", q: "4S，16000 毫安时电池 1.5C 充电，充电器应设置充电电流多少安培？（）", opts: ["12", "18", "24"], ans: 2, exp: "首先明确电池容量单位毫安时（mAh）与安培（A）的关系，1 安=1000 毫安。4S 表示 电池由四节单体电池串联而成。1.5C 表示充电倍率，即充电电流为电池容量的 1.5 倍。16000 毫安时换算安培为 16 安，1.5 倍容量即 16×1.5=24 安培。在无人机使用中，正确设置充电 电流对于电池的安全和性能至关重要。" },
  { id: 1348, cat: "综合问答", q: "4S 5000mAh，2C 充电，多久充满？（）", opts: ["1 小时", "2 小时", "0.5 小时"], ans: 2, exp: "首先，4S 表示由四节单体电池串联。5000mAh（毫安时）是电池容量。2C 充电表示充 电电流是电池容量的 2 倍。5000mAh 换算为 5Ah（安时），2C 充电电流为 2×5=10A（安培）。 根据公式充电时间=电池容量：充电电流，即 5 除以 10=0.5 小时。" },
  { id: 1349, cat: "综合问答", q: "6S 30000mAh 电池它驱动电机的功率怎么算？（）", opts: ["6*30000mAh", "25.2*30mAh", "25.2*30A"], ans: 2, exp: "6S 电池的标准电压约为 25.2V（单节电池约 4.2V×6）。电池容量为 30000mAh 即 30Ah。 功率=电压×电流，所以驱动电机的功率=25.2×30A。" },
  { id: 1350, cat: "综合问答", q: "6S 15000mAh 电池，0.5C 充电，应该调成几安充电？（）", opts: ["30A", "15A", "7.5A"], ans: 2, exp: "6S 电池标准电压约为 25.2V 左右，电池容量为 15000mAh 即 15Ah。0.5C 充电意味着充电电流为 0.5×15=7.5A。 使用以下公式： 充电电流=容量×C 率 其中容量是电池的 mAh 值，C 率是充电倍率。对于这个电池，容量是 15000mAh，C 率是 0.5C。 充电电流=15000mAh×0.5C=7500mA=7.5A 因此，应该调成 7.5 安充电。" },
  { id: 1351, cat: "综合问答", q: "6S1P 10000mAh 20C 电池，当两块电池并联，最大放电电流多少安？（）", opts: ["200A", "120A", "400A"], ans: 2, exp: "6S1P 表示 6 节串联 1 并，电池容量为 10000mAh 即 10Ah,20C 放电意味着单块电池放 电电流为 20×10=200A。两块电池并联，最大放电电流为 2×200=400A。" },
  { id: 1352, cat: "综合问答", q: "CW1545 和 CCW14X6 螺旋桨，哪个螺距大？（）", opts: ["CW1545", "CCW14X6", "一样大"], ans: 1, exp: "螺旋桨的命名规则一般为数字 Ax 数字 B 的形式，其中数字 B 代表螺距。CW1545 中螺 距为 4.5 英寸，CCW14X6 中螺距为 6 英寸。所以 CCW14X6 的螺距大。在无人机的组装和调试 中，正确选择螺旋桨对于飞行性能和稳定性至关重要。" },
  { id: 1353, cat: "综合问答", q: "飞机飞行中通过什么与地面站连接？（）", opts: ["飞控、GPS", "WIFI 模块，电台", "接收机、遥控器"], ans: 1, exp: "飞机飞行中，通常是通过 WIFI 模块或者电台与地面站进行连接，实现数据的传输和 对飞机的远程控制。飞控和 GPS 主要是用于飞机自身的飞行控制和定位，接收机和遥控器是 用于飞机与操控者在较近距离内的控制，而不是与地面站连接。" },
  { id: 1354, cat: "综合问答", q: "飞行前检查的第一项是（）", opts: ["重心", "紧固件", "电压"], ans: 1, exp: "在飞行前进行检查时，首先应检查紧固件是否牢固。如果紧固件不牢固，在飞行过程 中可能会出现部件松动甚至脱落的情况，严重危及飞行安全。重心问题可以在组装和调试阶 段进行确认和调整，一般不是飞行前检查的第一项。电压通常在准备起飞前的最后阶段检查，确保电池电量充足。" },
  { id: 1355, cat: "综合问答", q: "飞行中地面站里显示滚转角为零，目视飞机有明显的坡度，原因是什么？（）", opts: ["GPS 故障", "磁罗盘故障", "陀螺仪故障"], ans: 2, exp: "陀螺仪主要用于测量机的姿态角度，包括滚转角、俯仰角和偏航角等。如果地面站显 示滚转角为零，但目视飞机有明显坡度，说明陀螺仪未能正确测量飞机的滚转姿态，很可能 是陀螺仪故障。而 GPS 主要用于定位，与飞机的姿态显示无关。磁罗盘主要用于指示方向，也与滚转角的测量无关。" },
  { id: 1356, cat: "综合问答", q: "把无人机螺旋桨换成小桨，做同样的动作，角速度怎么变化？（）", opts: ["角速度转数减小", "角速度转数增加", "角速度转速不变"], ans: 1, exp: "当无人机的螺旋桨换成小桨时，为了产生相同的推力，电机需要以更高的转速来驱动 更小的螺旋桨，因为较小的桨叶面积需要更高的角速度来产生足够的升力以抵消无人机的重 量。因此，角速度转数会增加。" },
  { id: 1357, cat: "综合问答", q: "保持油门不变飞机匀速上升，螺旋桨转速怎么变化？（）", opts: ["增加", "不变", "减小"], ans: 0, exp: "该题主要争议源于对现代电控系统补偿机制的认知差异。在保持油门不变的情况下，飞机匀速上升时，螺旋桨转速会增加。这是因为： 1.油门不变意味着发动机输出功率恒定； 2.匀速上升需要更大的升力来克服重力； 3.为了产生更大的升力，螺旋桨需要提高转速以增加空气推力； 4.螺旋桨拉力与转速的平方成正比，转速增加会显著提升拉力； 因此，在题目描述的条件下，螺旋桨转速会增加。 排除其他选项的原因： （不变）：仅适用于恒速螺旋桨的特定工况（如低空飞行），但题目未限定此条件。 （减小）：完全违背物理原理，推力不足会导致飞机无法维持上升。" },
  { id: 1358, cat: "综合问答", q: "保持油门持续爬升，电机功率会增加还是减小？（）", opts: ["增加", "减小", "不变"], ans: 2, exp: "在保持油门不变的情况下，电机提供的功率也保持不变。因为电机的功率是由油门控 制的，如果油门没有变化，那么电机的输入功率也不会变化。尽管随着高度的增加，空气密 度会降低，这可能会影响螺旋桨的效率，但是在油门不变的情况下，电机的输出功率仍然保 持恒定。" },
  { id: 1359, cat: "综合问答", q: "扁粗电机和细长电机的特点是（）", opts: ["扁粗电机扭矩大，转速高；细长电机扭矩相对较小，转速小", "扁粗电机扭矩小，转速低；细长电机扭矩相对较高，转速高", "扁粗电机扭矩大，转速低；细长电＜机扭矩相对较小，转速高"], ans: 2, exp: "扁粗电机因为槽面积相对较大、线负荷较大，从而转矩大，转动惯量大，电机动态性 能响应慢，电机速度不会太高；而细长电机的转矩相对较小，转动惯量小，电机动态性能响 应快，易于高速运行。因此，正确答案是扁粗电机扭矩大，转速低；细长电机扭矩相对较小，转速高。" },
  { id: 1360, cat: "综合问答", q: "标有 4S-6S 的电调，最大允许多大电压？（）", opts: ["22.2V", "25.2V", "44.4V"], ans: 1, exp: "一般情况下，单节锂电池的标称电压是 3.7V，充满电时的电压是 4.2V。4S 即 4 节锂 电池串联，满电电压为 4.2×4=16.8V；6S 即 6 节锂电池串联，满电电压为 4.2×6=25.2V。 标有 4S-6S 的电调，最大允许电压为 6S 满电时的电压 25.2V。" },
  { id: 1361, cat: "综合问答", q: "伯努利定理，指的是（）", opts: ["由于能量守恒定律，同一流管内横截面积大的地方静压更小", "由于能量守恒定律，同一流管内流速快的地方静压大", "由于能量守恒定律，同一流管内流速快的地方静压小"], ans: 2, exp: "伯努利定理是流体力学中的一个定理，它指出在没有粘性的理想流体中，沿着流线的 流体元素的能量是守恒的。这个能量包括流体的动能、势能和压强能。根据伯努利定理，流 速增加时，压强能（静压）会减少，反之亦然。因此，同一流管内流速快的地方静压小。" },
  { id: 1362, cat: "综合问答", q: "常规布局直升机尾桨的作用不包括（）", opts: ["抵消反扭矩", "改变航向", "较少噪音"], ans: 2, exp: "减少噪声并不是尾桨的直接作用。常规布局直升机的尾桨主要作用是抵消主旋翼产生 的反扭矩，以保持直升机机身的稳定，同时尾桨也可用于改变航向，通过调整尾桨的推力来 实现直升机的偏航控制。" },
  { id: 1363, cat: "综合问答", q: "常用电调线的数量不包括（）", opts: ["8 根", "7 根", "6 根"], ans: 2, exp: "电调线的数量通常包括输入线（电源线），输出线（电机线），以及信号输入线。对于 有刷电调，需要 2 根连接线来控制电机；对于无刷电调，输出端需要 3 根线，将直流电源转 为三相交流电。因此，电调线的数量不包括 6 根，因为无论是有刷还是无刷电调，其连接线 的数量都不会达到 6 根。" },
  { id: 1364, cat: "综合问答", q: "常用地面站卡尔曼滤波正常值是多少？（）", opts: ["正负 5 以内", "正负 10 以上", "正负 10 以内"], ans: 2, exp: "常用地面站卡尔曼滤波的正常值是正负 10 以内。 卡尔曼滤波是一种最优线性状态估计方法，它通过数学方法寻求与观测数据最佳拟合的状态 向量。在无人机地面站中，卡尔曼滤波被用于处理传感器数据，以提供更准确的飞行状态估 计。正常值范围表示卡尔曼滤波器在处理数据时的误差范围，正负 10 以内的值被认为是在 可接受的误差范围内。" },
  { id: 1365, cat: "综合问答", q: "成品 LiPo 6S 1P 12000mAh 30C 电池，该电池单片电芯容量多少 mAh，该电池电压多少 适合存放？（）", opts: ["12000mAh, 22.8V-23.4V", "12000mAh, 22.2V-25.2V", "12000mAh, 21.6V-22.8V"], ans: 0, exp: "成品 LiPo 6S 1P 12000mAh 30C 电池，其中“6S”表示电池由 6 个电芯串联组成，“12000mAh” 表示总容量为 12000 毫安时，“30C”表示电池的放电倍率为 30C。对于单片电芯容量，由于 是 6S 配置，因此每片电芯的容量也是 12000mAh。至于电池的存放电压，一般推荐的电压范 围是每片电芯 3.8V 至 3.9V，因此对于 6S 电池，存放电压应为 22.8V 至 23.4V。" },
  { id: 1366, cat: "综合问答", q: "成品 LiPo 6S 1P 12000mAh 30C 电池，该电池单片电芯容量是（）", opts: ["12000mAh", "72000mAh", "24000mAh"], ans: 0, exp: "成品 LiPo 6S 1P 12000mAh 30C 电池，这里的“6S”表示电池由 6 个电芯串联组成，“1P” 表示电池的并联数为 1，即没有并联电芯，只有串联电芯。 “12000mAh”是整个电池包的总容量，因此每片电芯的容量也是 12000mAh。所以，单片电芯 的容量是 12000mAh。" },
  { id: 1367, cat: "综合问答", q: "成品 LiPo 1P 10000mAh 25C（3C）电池，请问该电池可设定的最大充电电流为多少安？（）", opts: ["20A", "30A", "40A"], ans: 1, exp: "成品 LiPo 1P 10000mAh 25C（3C）电池中，“25C”表示电池的放电倍率为 25C，而“（3C）” 表示电池的最大充电倍率为 3C。根据这个信息，我们可以计算出该电池可设定的最大充电 电流。电池的容量是 10000mAh，即 10Ah，所以最大充电电流为 10Ah 乘以 3C，等于 30A。" },
  { id: 1368, cat: "综合问答", q: "伺服舵机由哪几部分组成？（）", opts: ["外壳，控制电路，电机，减速齿轮组，电位器", "外壳，控制电路，减速齿轮组，电位器", "控制电路，电机，减速齿轮组，电位器"], ans: 0, exp: "伺服舵机是无人机中用于执行控制指令、实现精准运动的部件。它由以下几个主要部 分组成： 外壳：保护内部组件，通常由金属或塑料制成。 控制电路：负责接收控制信号并指挥电机的转动。 电机：通常是一个小型的直流电机，提供动力。 减速齿轮组：将电机的高速转动转换为输出轴的低速转动，同时增加扭矩。 电位器：用于反馈舵机的实际位置，确保控制的精确性。" },
  { id: 1369, cat: "综合问答", q: "单块电池容量为 6000mAh，3S4P 电池组满电下提供的电压和容量分别为多少？（）", opts: ["电压：12.6V，容量：24000mAh", "电压：12.6V，容量：6000mAh", "电压：11.1V，容量：24000mAh"], ans: 0, exp: "3S4P 电池组表示 3 块电池串联，4 组这样的串联电池并联。单块电池容量为 6000mAh，因此 4 组并联的电池总容量为 6000mAh×4=24000mAh。每块电池的电压为 3.7V（满电时为 4.2V），3 块电池串联的电压为 4.2V×3=12.6V。因此，3S4P 电池组满电下提供的电压为 12.6V，容量为 24000mAh。" },
  { id: 1370, cat: "综合问答", q: "单旋翼带尾桨直升机典型尾桨构造是（）", opts: ["无轴承式", "多叶铰接式、多叶万向接头式", "以上都是"], ans: 2, exp: "单旋翼带尾桨直升机的典型尾桨构造包括无轴承式和多叶铰接式、多叶万向接头式。 无轴承式尾桨结构简单，维护方便；多叶铰接式和多叶万向接头式尾桨则可以提供更好的效 率和稳定性，但结构相对复杂。因此，选项“以上都是”是正确的。" },
  { id: 1371, cat: "综合问答", q: "地面站链路属于（）", opts: ["上行", "下行", "上下行"], ans: 2, exp: "地面站链路既有地面站向无人机发送指令、任务规划这类上行数据的功能，比如操控 者发出起飞、悬停、返航等指令；同时也肩负无人机向地面站回传飞行参数、实时画面等下 行数据的任务，以此实现双向信息交互，所以是上下行链路。" },
  { id: 1372, cat: "综合问答", q: "地面站中无线电波长越长，绕射能力越（）", opts: ["强", "弱", "没变化"], ans: 0, exp: "地面站中无线电波长越长，绕射能力越强。这是因为波长较长的无线电波在遇到障碍 物时，更容易绕过障碍物继续传播。绕射能力与波长的长短有关，波长越长，波的衍射现象 越明显，因此绕射能力越强。" },
  { id: 1373, cat: "综合问答", q: "地面站中无线电频率越小，穿透能力（）", opts: ["强", "弱", "没变化"], ans: 1, exp: "地面站中无线电频率越小，穿透能力越弱。这是因为无线电波的频率越低，波长越长，而波长越长的无线电波在穿透物体时的能力越弱。长波长的无线电波更容易被物体吸收或被 其表面反射，因此它们不适合用于需要较强穿透能力的应用场景。" },
  { id: 1374, cat: "综合问答", q: "地面站，飞机电，遥控器，哪个是检查程序中最后一项？（）", opts: ["地面站", "飞机电", "遥控器"], ans: 1, exp: "在无人机的检查程序中，通常会按照一定的顺序进行检查，以确保所有设备正常工作。 一般来说，检查的顺序是先检查地面站，然后检查遥控器，最后检查飞行器的电机（飞机电）。 这是因为在进行飞行前，确保飞行器的电机和动力系统正常是至关重要的，确保飞行可以安 全起飞和操作。" },
  { id: 1375, cat: "综合问答", q: "典型的无人直升机由哪几部分组成？（）", opts: ["旋翼系统、传动系统、发动机、尾桨系统", "旋翼系统、传动系统、发动机、尾桨翼", "旋翼系统、传动系统、发动机、副翼"], ans: 0, exp: "典型的无人直升机由以下几个主要部分组成： 旋翼系统：负责提供升力，使直升机能够在空中悬停或移动。 传动系统：将发动机的动力传递给旋翼系统，以驱动旋翼旋转。 发动机：提供动力来源，可以是内燃机或电动机。 尾桨系统：用于抵消旋翼产生的反扭矩，保持直升机机身稳定，并帮助控制直升机的航向。" },
  { id: 1376, cat: "综合问答", q: "电池放在机体哪里方式飞行更灵活？（）", opts: ["中间", "上面", "下面"], ans: 1, exp: "电池放在机体上方可以使得无人机的重心保持在机体的中心位置，这有助于提高飞行 的灵活性和稳定性。当电池放置在机体中间时，虽然也能保持重心居中，但可能会影响其他 设备的布局和散热。而将电池放在机体下方可能会增加机体的阻力，并且不利于电池的散热 和保护。" },
  { id: 1377, cat: "综合问答", q: "电调的作用不包括（）", opts: ["改变电机转速", "直流电变交流电", "改变电流大小"], ans: 2, exp: "电调，全称电子调速器（Electronic Speed Controller,ESC），在无人机和遥控模型中 起到至关重要的作用。它的主要功能包括： 1.改变电机转速：通过接收遥控器或飞控系统的信号，电调可以控制电机的转速，实现对无 人机速度和姿态的调整。 2.直流电变交流电：对于无刷电机而言，电调将电池提供的直流电（DC）转换为三相交流电 （AC），以驱动无刷电机的运转。 电调本身并不直接改变电流的大小，而是通过调整电机的转速来间接影响电流的变化。" },
  { id: 1378, cat: "综合问答", q: "电调杜邦线连接什么？（）", opts: ["接收机", "飞控", "电机"], ans: 1, exp: "电调（ESC,Electronic Speed Controller）的杜邦线连接飞控（FlightController）。 飞控是无人机的“大脑”，负责处理飞行数据和控制指令，而电调则根据飞控的指令来调整 电机的转速，以控制无人机的飞行动作。因此，电调的杜邦线需要与飞控相连，以接收控制 信号。" },
  { id: 1379, cat: "综合问答", q: "电调上的两根线，三根线，杜邦线分别连接（）", opts: ["电源，电机，飞控", "电机，电源，飞控", "飞控，电机，电源"], ans: 0, exp: "电调（ESC）上的两根线通常指的是电源线，用于连接电池，为电调和电机提供电力。 三根线指的是电机线，用于连接电机，使电调能够控制电机的转速。杜邦线则是用来连接飞 控，传输控制信号，使飞控能够向电调发送指令，控制电机的运行状态。" },
  { id: 1380, cat: "综合问答", q: "电调最粗的两根硅胶线连接什么？（）", opts: ["电池", "电机", "飞控"], ans: 0, exp: "电调（ESC, Electronic Speed Controller）是无人机动力系统中的重要组成部分，负责调节电机转速和控制电机运转。电调最粗的两根硅胶线是电源输入线，它们连接电池，负责为电调和电机提供电力。这两根线通常区分正负极，红正黑负。" },
  { id: 1381, cat: "综合问答", q: "电动多旋翼桨可以做到尽量大，从而可以用最少的旋翼数实现最大载荷。（）", opts: ["正确", "不正确", "不一定"], ans: 2, exp: "电动多旋翼的桨并不是可以无限制地做到尽量大。桨叶增大虽然可能在一定程度上提 升升力，从而有可能实现用较少的旋翼数去承担更大的载荷，但桨叶过大也会带来很多问题，比如增加空气阻力、对电机要求更高、操作灵活性降低、便携性变差等。所以不能简单地说 电动多旋翼桨可以做到尽量大，从而用最少的旋翼数实现最大载荷，其结果是不一定的。" },
  { id: 1382, cat: "综合问答", q: "定向性天线的优点是（）", opts: ["覆盖范围广", "辐射距离远", "绕射能力强"], ans: 1, exp: "定向性天线，顾名思义，它的信号像是朝着特定方向发射的“聚光灯”。把能量集中 朝一个方向传输，不像全向天线四面八方分散能量，如此一来，信号强度在目标方向上就得 到极大强化，辐射距离自然远了。不过，正因为朝特定方向聚焦，它覆盖范围就比较窄，不 是广撒网式覆盖；绕射能力也不强，遇到障碍物时，由于能量集中在固定方向，很难像波长 长的信号那样绕过去。" },
  { id: 1383, cat: "综合问答", q: "对于混合燃油发动机，冬天的燃油、机油混合比针对夏天应如何调整？（）", opts: ["燃油机油混合比适当减小", "燃油机油混合比适当增大", "燃油机油混合比不变"], ans: 1, exp: "冬天机油要多加（混合比增大），夏天可少加（混合比减小）。在冬天，由于气温较低，机油的流动性变差，润滑效果降低。因此，需要适当增加机油的比例（即混合比增大，例如 从夏天的 50:1 调整为 40:1），以确保发动机在低温环境下仍能得到充分润滑，减少磨损。" },
  { id: 1384, cat: "综合问答", q: "对于直升机，多旋翼无人机的旋翼或固定翼无人机的螺旋桨，保持角速度一定，更换直 径较小的旋翼或螺旋桨，会导致（）", opts: ["桨尖速度变大", "桨尖速度不变", "桨尖速度减小"], ans: 2, exp: "角速度一定时，桨尖速度等于角速度乘以半径（桨的半径与直径成正比）。更换直径 较小的旋翼或螺旋桨，相当于半径减小，而角速度不变，根据公式可知桨尖速度会减小。" },
  { id: 1385, cat: "综合问答", q: "多旋翼 1.1 米轴距代表什么意思？（）", opts: ["对角电机之间的直径距离为 1.1 米", "相邻电机之间的直径距离为 1.1 米", "对角电机之间的半径距离为 1.1 米"], ans: 0, exp: "多旋翼的轴距通常是指对角电机之间的直线距离，也就是对角电机之间的直径距离。 1.1 米轴距就代表对角电机之间的直径距离为 1.1 米。而不是相邻电机之间的距离，也不是 对角电机之间的半径距离。" },
  { id: 1386, cat: "综合问答", q: "多旋翼飞行器如果重新组装后，必须校准哪些传感器？（）", opts: ["磁罗盘，陀螺仪", "电调，GPS", "接收机，IMU"], ans: 0, exp: "多旋翼飞行器在重新组装后，需要校准的传感器主要是磁罗盘和陀螺仪。磁罗盘用于 确定无人机的航向，而陀螺仪用于感知无人机的角速度和姿态变化。这两个传感器对于无人 机的飞行控制至关重要，任何物理上的改变都可能影响它们的读数，因此需要重新校准以确 保飞行的安全性和准确性。" },
  { id: 1387, cat: "综合问答", q: "多旋翼的桨叶为（）", opts: ["数目不固定", "2", "3"], ans: 0, exp: "多旋翼的桨叶数目是不固定的，可以是 2、3、4、6、8 等，这取决于无人机的设计和 用途。常见的多旋翼无人机有四旋翼（四桨）、六旋翼（六桨）和八旋翼（八桨）等。桨叶 的数量会影响无人机的升力、稳定性和机动性。" },
  { id: 1388, cat: "综合问答", q: "多旋翼电调与电机如何匹配？（）", opts: ["电调的极限电流值越大越好根据电机巡航功率推算出单个支臂巡航电流，根据电流的 3 到 5 倍以上选取电调", "电调的极限电流值留有足够裕度即可根据电机巡航功率推算出单个支臂巡航电流，根据 电流的 3 到 5 倍以上选取电调", "电调的极限电流值越大越好根据电机最大功率推算出单个支臂最大电流，根据电流的 3 到 5 倍以上选取电调"], ans: 1, exp: "多旋翼电调与电机匹配时，电调极限电流值无需越大越好，留有足够裕度即可。需先 根据电机巡航功率计算单个支臂的巡航电流，再按该电流的 3-5 倍以上选取电调，以应对启 动、姿态变化等场景下的瞬间大电流，确保电调可靠工作。" },
  { id: 1389, cat: "综合问答", q: "多旋翼动力系统由哪几部分组成？每部分有几根线？（）", opts: ["电池（两根动力线），电调（八根线），电机（两根线）", "电池（两根动力线），电调（八根线），电机（三根线）", "电池（两根动力线），电调（三根线），电机（三根线）"], ans: 1, exp: "多旋翼无人机的动力系统主要由三部分组成：电池、电调和电机。 电池：为整个动力系统提供电力，通常有两根动力线，一根正极和一根负极。 电调：电子调速器，负责将电池的直流电转换为电机所需的交流电，并控制电机的转速。电 调通常有三根线连接到电机，分别是三相交流电的三个相位。 电机：将电能转换为机械能，驱动螺旋桨旋转，产生推力。对于无刷电机，通常有三根线连 接到电调，对应三个相位。 因此，正确答案是：电池（两根动力线），电调（八根线），电机（三根线）。这里的“八根 线”是指电调通常会有四根信号输入线（用于接收飞控的控制信号）和四根电机输出线。" },
  { id: 1390, cat: "综合问答", q: "多旋翼飞行器如果重新组装后，不需要校准哪些传感器？（）", opts: ["GPS", "磁罗盘", "气压计"], ans: 2, exp: "多旋翼飞行器重新组装后，GPS 和磁罗盘的位置和方向可能会发生变化，需要重新校 准以确保其准确性和可靠性。而气压计主要是通过测量大气压力来确定高度，通常不受飞行 器重新组装的影响，一般不需要校准。" },
  { id: 1391, cat: "综合问答", q: "多旋翼飞行器上各种天线设备布置有什么要求？（）", opts: ["GPS 接收天线安装在机腹", "数传天线布置于机腹", "数传天线，图传天线尽量靠近布置"], ans: 1, exp: "多旋翼飞行器上各种天线设备布置的要求中，GPS 接收天线应安装在机身顶端，数传 天线应布置于机腹，而数传天线与图传天线不宜过近布置，以避免信号干扰。因此，正确答 案是：数传天线布置于机腹。" },
  { id: 1392, cat: "综合问答", q: "多旋翼飞行器为什么一般相对的桨旋转方向是不一样的？（）", opts: ["效率更高", "产生更大升力", "抵消反扭矩"], ans: 2, exp: "多旋翼飞行器在工作时，电机带动螺旋桨旋转会产生反扭矩。如果相对的桨旋转方向 一样，那么这些反扭矩会使飞行器难以稳定控制甚至发生自旋。而让相对的桨旋转方向不一 样，就可以相互抵消反扭矩，使飞行器能够平稳飞行。" },
  { id: 1393, cat: "综合问答", q: "多旋翼飞行一段时间后，应对电机安装位置如何检查？（）", opts: ["应用水平尺校准，保证每个电机水平不应该出现倾斜", "让其适当倾斜", "应用垂直尺校准"], ans: 0, exp: "多旋翼飞行器在飞行一段时间后，可能会由于各种原因导致电机安装位置发生变化。 如果电机出现倾斜，会影响飞行器的稳定性和飞行性能。所以需要用水平尺进行校准，保证 每个电机处于水平状态，确保飞行器能正常飞行。" },
  { id: 1394, cat: "综合问答", q: "多旋翼控制前后飞行时，油门需要怎么变化，为什么？（）", opts: ["前后飞行时，飞机会产生倾斜角，导致升力水平分量不足以抵消重力，所以需要适量增 加油门", "前后飞行时，飞机会产生倾斜角，导致升力垂直分量不足以抵消重力，V 所以需要适量 增加油门", "前后飞行时，飞机会产生倾斜角，导致升力垂直分量不足以抵消重力，所以需要适量减 小油门"], ans: 1, exp: "在多旋翼无人机控制前后飞行时，油门需要适量增加。这是因为在前后飞行过程中，飞机会产生倾斜角，导致升力在重力方向的分量减小，如果不增加油门，无人机的高度会降 低。因此，为了保持无人机的高度稳定，需要适量增加油门以补偿升力的减少。" },
  { id: 1395, cat: "综合问答", q: "多旋翼无人机的螺旋桨是（）", opts: ["定距螺旋桨", "变距螺旋桨", "有定距也有变距"], ans: 0, exp: "多旋翼无人机通常采用的是定距螺旋桨。定距螺旋桨的桨叶角度固定，结构相对简单，易于控制和维护。多旋翼无人机的飞行速度相对较为稳定，对于这种相对稳定的飞行状态，定距螺旋桨能够满足其动力需求和飞行控制要求。而变距螺旋桨能够改变桨叶的角度，以适 应不同的飞行速度和工况，但其结构复杂，成本高，控制难度大，一般不用于多旋翼无人机。" },
  { id: 1396, cat: "综合问答", q: "多旋翼无人机要实现在悬停中向右偏航，不同螺旋桨如何变化？（）", opts: ["逆时针桨减速，顺时针桨加速", "机体轴左边螺旋桨加速，右边螺旋桨减速", "逆时针桨加速，顺时针桨减速"], ans: 2, exp: "多旋翼无人机的偏航运动是通过不同螺旋桨的转速变化来实现的。当要实现在悬停中 向右偏航时，逆时针桨加速，顺时针桨减速，这样会产生向右的扭矩，使无人机向右偏航。" },
  { id: 1397, cat: "综合问答", q: "多旋翼无人机以下哪个下降速度较为合理？（）", opts: ["2M/S", "5M/S", "8M/S"], ans: 0, exp: "下降速度过快可能会对多旋翼无人机的结构造成较大冲击，影响其稳定性和安全性。 2M/S 的下降速度相对较为合理，较为平稳，对无人机的影响较小。5M/S 和 8M/S 的下降速度 较快，容易引发意外情况。" },
  { id: 1398, cat: "综合问答", q: "多旋翼无人机在使用地面站超视距飞行时，数传上行链路中断，该如何处理？（）", opts: ["检查上行链路设备恢复通信", "继续飞行，会自动连接", "暂停飞行，尝试重新连接，点击一键返航"], ans: 0, exp: "多旋翼无人机在使用地面站超视距飞行时，数传上行链路中断，正确的处理方法是检 查上行链路设备恢复通信。这是因为上行链路中断会导致地面站无法对飞机发送指令，所以 需要检查并恢复通信。" },
  { id: 1399, cat: "综合问答", q: "多旋翼无人机在使用地面站超视距飞行中，数传下行链路故障中断，该如何处理？（）", opts: ["继续飞行，自动连接", "暂停飞行，尝试重新连接，点击原地悬停", "暂停飞行，尝试重新连接，点击一键返航"], ans: 2, exp: "在多旋翼无人机使用地面站进行超视距飞行中，如果数传下行链路发生故障中断，正 确的处理方法是暂停飞行、尝试重新连接，并点击一键返航。这是因为下行链路中断会导致 地面站无法接收到无人机的飞行状态和数据更新，增加了飞行的风险。在这种情况下，应立 即采取措施以确保无人机的安全返回。" },
  { id: 1400, cat: "综合问答", q: "多旋翼无人机在姿态遥控状态下，如出现动力失效则正确的处理方法是（）", opts: ["遥控器油门保持中间略上位置", "接地瞬间将油门收至最小", "始终保持油门最大位置试图恢复动力"], ans: 1, exp: "多旋翼无人机在姿态遥控状态下，如出现动力失效则正确的处理方法是接地瞬间将油 门收至最小。这是因为在动力失效的情况下，迅速减小油门可以减少对无人机的冲击，降低 损害风险，并有助于防止火灾等安全事故的发生。" },
  { id: 1401, cat: "综合问答", q: "多旋翼遥控状态下，动力失效最合适的处理方法是（）", opts: ["利用旋翼旋转安全降落", "有伞开伞", "落在任意地方"], ans: 1, exp: "在多旋翼遥控状态下动力失效时，有伞的情况下应开伞，以尽可能保证安全降落。利 用旋翼旋转安全降落通常比较困难，难以实现平稳着陆。落在任意地方具有很大的不确定性 和危险性。" },
  { id: 1402, cat: "综合问答", q: "多旋翼有几个自由度，滚转运动是绕哪个轴？（）", opts: ["6 个，横轴", "6 个，纵轴", "3 个，纵轴"], ans: 1, exp: "多旋翼飞行器通常具有 6 个自由度，包括沿三个坐标轴的平移（前后、左右、上下）和绕这三个轴的旋转（滚转、俯仰、偏航）。滚转运动是指飞行器绕纵轴（即飞行器从前到 后的那个轴）的旋转。" },
  { id: 1403, cat: "综合问答", q: "多旋翼有三轴布局的形式，这种布局中间轴多了一个舵机，这个舵机的作用是什么？（）", opts: ["抵消反扭矩", "收起起落架", "改变旋翼螺距"], ans: 0, exp: "多旋翼三轴布局中间轴的舵机主要作用是抵消反扭矩。在多旋翼飞行器中，电机带动 螺旋桨旋转会产生反扭矩，影响飞行器的稳定性。通过中间轴的舵机进行相应的调整，可以 有效地抵消反扭矩，保证飞行器的稳定飞行。" },
  { id: 1404, cat: "综合问答", q: "多旋翼在测试电机转动方向最重要的安全措施是（）", opts: ["拆卸螺旋桨", "拆卸机臂", "拆卸电机"], ans: 0, exp: "在测试多旋翼电机转动方向时，若不拆卸螺旋桨，电机一旦转动，高速旋转的螺旋桨 可能会对人员造成严重伤害或对周围物品造成损坏。而拆卸机臂和拆卸电机并不能有效防止 在测试过程中可能出现的安全风险。" },
  { id: 1405, cat: "综合问答", q: "多轴飞行器飞行平台由哪些设备组成？（）", opts: ["飞控、电调、电机、螺旋桨、机架、接收机", "飞控、电调、电机、螺旋桨、机架、倾斜盘", "飞控、电调、电机、螺旋桨、机架、遥控器"], ans: 0, exp: "多轴飞行器飞行平台主要由以下设备组成：飞控系统、电子调速器（电调）、电机、螺旋桨、机架以及接收机。这些是构成多轴飞行器基本飞行能力的核心组件。 飞控系统是无人机的“大脑”，负责处理飞行数据和控制无人机的飞行行为。 电调用于控制电机的转速，从而调整螺旋桨的推力。 电机是提供动力，通过旋转螺旋桨产生推力的部件。 螺旋桨与电机配合，产生无人机所需的升力。 机架是支撑整个无人机结构的基础。 接收机用于接收遥控器发出的信号，以实现远程控制。 倾斜盘是某些直升机用于控制桨叶角度的设备，而遥控器是地面控制人员用来向无人机发送 指令的设备，它们不是多轴飞行器飞行平台的组成部分，而是控制环节的一部分。" },
  { id: 1406, cat: "综合问答", q: "多轴在测试电机，电调时最重要的安全措施是？（）", opts: ["卸下螺旋桨", "卸下电机", "不接动力电"], ans: 0, exp: "多轴在测试电机，电调时最重要的安全措施是卸下螺旋桨。这样可以防止在测试过程 中电机突然启动造成螺旋桨损坏或者人员伤害。在进行电机和电调的测试时，确保螺旋桨被 卸下是基本的安全操作，因为电机和电调的测试可能会涉及到电机的突然启动，如果螺旋桨 安装在电机上，可能会因为高速旋转造成危险。" },
  { id: 1407, cat: "综合问答", q: "多轴无人机各种天线设备位置有什么要求？（）", opts: ["GPS 天线要高出机体竖直向上，WIFI 模块天线要垂直向上，接收机两根天线互相垂直", "GPS 天线要高出机体竖直向上，WIFI 模块天线要垂直向下，接收机两 根天线互相垂直", "GPS 天线要低出机体竖直向下，WIFI 模块天线要垂直向下，接收机两根天线互相垂直"], ans: 1, exp: "对于多轴无人机，GPS 天线要高出机体竖直向上，这样能更好地接收卫星信号，减少 机体对信号的遮挡；WIFI 模块天线垂直向下可以更好地与地面设备进行通信；接收机两根 天线互相垂直可以确保在不同方向上都能良好地接收信号，提高信号的稳定性和可靠性。" },
  { id: 1408, cat: "综合问答", q: "多轴无人机一般以双数螺旋桨配置，可否有奇数的配置，怎么配？（）", opts: ["可以", "不可以", "可以，但需要加个矢量舵机"], ans: 2, exp: "重点：奇数配置需要加矢量舵机来实现稳定控制。多轴无人机一般以双数螺旋桨配置 以实现较好的平衡和控制。但也可以有奇数的配置，不过奇数配置时需要加个矢量舵机来帮 助调整和控制无人机的姿态，以弥补奇数配置在平衡和控制上可能出现的问题。" },
  { id: 1409, cat: "综合问答", q: "舵面操控是什么控制量？（）", opts: ["开关控制量", "模拟控制量", "模拟控制量也叫比例控制量"], ans: 2, exp: "舵面操控通常是通过模拟控制量来实现的，也被称为比例控制量。这种控制方式可以 根据控制信号的大小来调整舵面的偏转角度，实现对飞行器姿态和运动的精确控制。而开关 控制量只有开和关两种状态，无法实现对舵面的精细调整。这个问题考察了对无人机或飞机 飞控系统中舵面操控类型的理解。了解不同类型的控制量对于理解飞行器的飞行动力学和控 制系统的工作原理非常重要。" },
  { id: 1410, cat: "综合问答", q: "发动机燃油在哪里喷射？（）", opts: ["进气口", "点火位置", "排气口"], ans: 0, exp: "发动机燃油在进气口喷射。在大多数现代内燃机中，燃油是通过喷油器直接喷射到进 气口或进气歧管中，与空气混合形成油气混合物，然后被吸入发动机的燃烧室进行燃烧。这 种方法被称为燃油直喷技术，有助于提高燃烧效率和发动机性能。因此，正确答案是进气口。" },
  { id: 1411, cat: "综合问答", q: "飞机上的 GPS/COMPSS 模块不能给无人机提供哪些数据？（）", opts: ["方向", "位置", "加速度"], ans: 2, exp: "GPS/COMPASS 模块主要提供位置信息和方向信息。GPS 可以确定无人机的经纬度位置，COMPASS（指南针）可以提供方向。而加速度通常是由加速度计等其他传感器提供的，GPS/COMPASS 模块不能提供加速度数据。" },
  { id: 1412, cat: "综合问答", q: "飞控中的气压高度传感器经过修正参数以后所获得的高度数据是（）", opts: ["相对高度", "海拔高度", "真实高度"], ans: 0, exp: "飞控中的气压高度传感器经过修正参数后获得的是相对高度。气压高度传感器通常是 通过测量大气压力的变化来确定高度的变化，但它不能直接确定绝对的海拔高度或真实高度。 相对高度是相对于某一参考平面的高度，在飞控中一般是相对于起飞点或特定的参考高度。" },
  { id: 1413, cat: "综合问答", q: "飞行器检查时，多旋翼电机震动，在排除电机故障后，检查动力电路，应检查（）", opts: ["输入端", "输出端", "不用检查"], ans: 1, exp: "多旋翼电机震动，在排除电机故障后，检查动力电路应从电机连接端即动力电路的输 出端开始检查，因为输出端直接连接电机，更有可能出现接触不良、短路等问题导致电机震 动。而输入端相对来说出现问题影响电机震动的可能性较小。" },
  { id: 1414, cat: "综合问答", q: "飞行中地面站显示滚转角度为零，目视飞机有明显的坡度，不太可能的原因是（）", opts: ["传感器故障", "上行链路中断", "飞控故障"], ans: 1, exp: "上行链路中断与地面站显示错误数据无直接关系，因此是最不可能的原因。因为上行 链路主要用于地面站向飞行器发送控制指令。如果上行链路中断，地面站无法向飞行器发送 指令，但飞行器本身的姿态数据仍然可以通过下行链路传输到地面站。 因此，上行链路中断不会导致地面站显示的滚转角度异常。" },
  { id: 1415, cat: "综合问答", q: "高海拔地区，以下哪个尺寸的螺旋桨更适用？（）", opts: ["1835", "1855", "1035"], ans: 0, exp: "高海拔地区的空气稀薄，这会影响飞机的性能。在高海拔地区，需要使用更大尺寸的 螺旋桨来提高飞机的推力，以确保飞机能够正常起飞和飞行。1835 尺寸的螺旋桨更适用于 高海拔地区，因为相比于 1035 尺寸的螺旋桨，1835 尺寸的螺旋桨可以提供更大的推力。同 时，1855 尺寸可能过大，会增加飞机的阻力。" },
  { id: 1416, cat: "综合问答", q: "高海拔地区选用什么样的桨叶效率最高？（）", opts: ["二叶桨", "三叶桨", "多叶桨"], ans: 0, exp: "在高海拔地区，空气稀薄，需要更高的转速来产生足够的升力。二叶桨相对较轻，转 动时空气阻力较小，在高海拔地区更容易达到较高的转速，效率更高。三叶桨和多叶桨通常 较重，在高海拔地区转动起来需要更多的动力，效率相对较低。" },
  { id: 1417, cat: "综合问答", q: "各长度鞭状天线架设方式必须和通讯方向（）", opts: ["垂直", "平行", "相同方向"], ans: 0, exp: "各长度鞭状天线架设方式必须和通讯方向垂直，这样可以确保天线能够有效地接收和 发射信号，减少信号干扰和衰减。如果天线与通讯方向平行或处于相同方向，可能会导致信 号接收不良。" },
  { id: 1418, cat: "综合问答", q: "共轴直升机通过改变什么改变航向？（）", opts: ["上下旋翼转速", "上下旋翼桨距", "倾斜盘倾斜方向"], ans: 1, exp: "共轴直升机通过改变上下旋翼桨距来改变航向。在共轴直升机中，两个旋翼反向旋转，通过调整上下旋翼的桨距（即改变旋翼的攻角），可以产生不平衡的升力，从而使直升机在 垂直平面内旋转，实现航向的改变。" },
  { id: 1419, cat: "综合问答", q: "关于升阻比和载荷因数，以下说法错的是（）", opts: ["载荷因数与升阻比成正比", "在最小阻力迎角下飞行，可以获得最大的升阻比", "升力与重力的比值称为载荷因数"], ans: 0, exp: "请注意：题目要求选出说法错误的选项。载荷因数（LoadFactor）是指飞机所受的升 力与重力的比值，而升阻比 （Lift-to-DragRatio）是升力与阻力的比值。载荷因数的增加 通常会导致阻力的增加，从而降低升阻比。因此，载荷因数与升阻比并不成正比。" },
  { id: 1420, cat: "综合问答", q: "关于失速，下列说法正确的是（）", opts: ["失速会导致升力系数急剧减小，阻力系数缓慢减小", "机翼迎角超过临界迎角，导致升力急剧降低的飞行状态", "旋翼无人机前飞速度快，可能导致后行旋翼出现失速"], ans: 1, exp: "失速是指机翼迎角超过临界迎角后，气流在机翼上表面分离，导致升力急剧下降的飞 行状态。" },
  { id: 1421, cat: "综合问答", q: "关于失速，下面说法不正确的是什么？（）", opts: ["失速会导致升力系数急剧减小，阻力系数缓慢减小", "机翼迎角超过临界迎角，导致升力急剧降低的飞行状态称为失速", "旋翼类无人机前飞速度过快，可能导致后行旋翼出现失速"], ans: 0, exp: "失速是指当机翼的迎角增加到一定程度，超过了临界迎角后，机翼上表面的气流分离，导致升力急剧减小，飞机无法维持正常的飞行状态。在这个过程中，阻力系数实际上会因为 气流分离而急剧增加，而不是缓慢减小。" },
  { id: 1422, cat: "综合问答", q: "关于无人机 GPS 天线与遥控接收机天线的说法错误的是（）", opts: ["GPS 卫星位置信号（一般为顶端蘑菇头）", "地面遥控发射机遥控信号（一般内 90 度布置）", "GPS 天线一般为定向天线，位于机体下方"], ans: 2, exp: "这道题主要考察对无人机 GPS 天线与遥控接收机天线的相关知识的理解。GPS 天线一 般为全向天线，用于接收来自各个方向的 GPS 卫星信号，并非定向天线且不一定位于机体下 方。GPS 天线接收 GPS 卫星位置信号，通常为顶端蘑菇头状；地面遥控发射机通过遥控信号 控制无人机，遥控接收机天线一般为 90 度布置以更好地接收信号。" },
  { id: 1423, cat: "综合问答", q: "关于诱导阻力，以下说法错误的是（）", opts: ["滑翔机为了减小诱导阻力，常将机翼设计成又长又窄的高展弦比机翼", "有的机翼上加装了翼梢小翼，目的是增强气流的下洗以增大升力，从而＜减小诱导阻力", "飞行速度越快，诱导阻力越小"], ans: 1, exp: "诱导阻力是由于机翼产生升力而诱导出来的一种阻力。滑翔机采用长而窄的高展弦比 机翼可以减小诱导阻力；飞行速度越快，诱导阻力越小。而机翼上加装翼梢小翼的目的是减 小翼尖涡的强度，从而减小诱导阻力，不是增强气流下洗以增大升力来减小诱导阻力。" },
  { id: 1424, cat: "综合问答", q: "结合遥控器说说民用无人机系统有哪几条链路？（）", opts: ["遥控器下行，图传下行，数传上下行", "遥控器上行，图传下行，数传上下行", "遥控器上行，图传上下行，数传下行"], ans: 1, exp: "民用无人机系统主要有三条链路： 遥控器上行链路：用于将地面控制站（遥控器）的指令发送到无人机，实现对无人机的远程 控制。 图传下行链路：用于将无人机拍摄的图像或视频数据传输到地面站或遥控器，便于操作员实 时监控。 数传上下链路：用于双向传输飞行参数、遥测数据等信息，包括从地面上传的控制指令和从 无人机下传的状态信息。 因此，正确答案是：遥控器上行，图传下行，数传上下行。" },
  { id: 1425, cat: "综合问答", q: "空速明显大于地速的原因是（）", opts: ["逆风", "顺风", "无风"], ans: 0, exp: "空速明显大于地速的原因是逆风。空速是指飞行器相对于空气的速度，而地速是指飞 行器相对于地面的速度。当有逆风时，飞行器相对于空气的速度（空速）会比相对于地面的 速度（地速）大，因为逆风会减慢飞行器相对于地面的移动速度，但不影响飞行器相对于空 气的移动速度。这个问题考察了对飞行器速度概念的理解，特别是空速和地速的区别以及风 对这两种速度的影响。" },
  { id: 1426, cat: "综合问答", q: "连接电机的三根线是以（）方式给无刷电机供电的？", opts: ["直流", "交流", "交流、直流都可以"], ans: 1, exp: "无刷电机通常需要通过电子调速器（ESC）来控制。连接电机的三根线传输的是交流 电，其频率和电压会根据控制信号不断变化，以实现电机的调速和转向控制。所以是以交流 方式给无刷电机供电的。" },
  { id: 1427, cat: "综合问答", q: "连接无人机电机为什么是三根线？（）", opts: ["三相交流电，变换任意两根线电机会发生反转", "三相直流电，变换任意两根线电机会发生反转", "两相直流电，变换任意两根线电机会发生反转"], ans: 0, exp: "无人机电机连接三根线的原因是因为无人机电机通常采用三相交流电供电，并且通过 改变任意两根线的连接方式可以改变电机的旋转方向（反转）。这是因为三相电系统的特性，所以正确答案为：三相交流电，变换任意两根线电机会发生反转。" },
  { id: 1428, cat: "综合问答", q: "连续性定理，指的是（）", opts: ["由于质量守恒定律同一流管单位时间内流经不同横截面的流体质量一定", "由于质量守恒定律，同一流管横截面积大的地方流速更快", "由于质量守恒定律，同一流管横截面积大的地方静压小"], ans: 0, exp: "连续性定理指的是由于质量守恒定律，同一流管单位时间内流经不同横截面的流体质 量一定。这个定理是流体力学中的一个基本原理，它表明在没有质量增加或减少的情况下，流经管道的流体流量在任何横截面上都是相同的。" },
  { id: 1429, cat: "综合问答", q: "两块 16000mAh 6S 25C 电池，一种方式串联，一种方式并联，哪种方式能输出电流更大？ （）", opts: ["不联", "并联", "串联"], ans: 1, exp: "电池并联电流大。两块电池并联时，电压不变，容量相加，根据欧姆定律 I=U/R，在 相同负载下，由于容量增大，能够提供的电流也会增大。而串联时，电压相加，容量不变，虽然电压升高了，但不一定能使输出电流比并联时更大。" },
  { id: 1430, cat: "综合问答", q: "两块电池 6S 5000mAh 的电池并联，用 2C 充电，充电的功率是多少？（）", opts: ["202W", "504W", "404W"], ans: 1, exp: "步骤一：计算电池电压“6S”表示电池由 6 片电芯串联，每片电芯满电电压约为 4.2V，所以电池组电压 U=6×4.2V=25.2V。 步骤二：计算电池容量两块 5000mAh 电池并联，并联后容量相加，即 mAh 容量 C=5000mAh+5000mAh=10000mAh=10Ah • 步骤二：计算充电电流充电倍率为 2C，根据充电电流 I=充电倍率×电池容量，可得 I=2C× 10Ah=20A。 步骤四：计算充电功率根据功率公式 P-UI，将 U=25.2V，I=20A 代入可得 P=25.2V×20A=504W。" },
  { id: 1431, cat: "综合问答", q: "螺旋桨 1045 CCW，其含义是什么？（）", opts: ["桨叶直径 10mm，桨叶宽度 4.5mm，逆时针旋转的螺旋桨", "桨叶直径 10 英寸，螺距 4.5 英寸，逆时针旋转的螺旋桨", "桨叶直径 10 英寸，螺距 45 英寸，顺时针旋转的螺旋桨"], ans: 1, exp: "这道题主要考查对螺旋桨规格表示方式及旋转方向的理解在螺旋桨的标注中，“1045” 通常表示桨叶直径为 10 英寸，螺距为 4.5 英寸。“CCW”是 counterclockwise 的缩写，即逆 时针旋转。了解螺旋桨的标注方式对于正确选择和使用螺旋桨非常重要。" },
  { id: 1432, cat: "综合问答", q: "螺旋桨的螺距是什么？（）", opts: ["螺距是指螺旋桨旋转一周所上升或前进的距离", "螺距是指螺旋桨旋转一周所上升的距离", "螺距是指螺旋桨旋转一周所前进的距离"], ans: 0, exp: "螺旋桨的螺距是指螺旋桨旋转一周所上升或前进的距离。这个距离是理论上的，它表 示如果螺旋桨是一个完美的螺丝形状，那么它旋转一周所能够推进或提升的距离。在实际应 用中，螺距影响着螺旋桨的拉力和效率。" },
  { id: 1433, cat: "综合问答", q: "螺旋桨的主要技术参数有哪些？（）", opts: ["直径，螺距，材料", "直径，螺距，桨叶数", "直径，螺距，桨叶数，材料"], ans: 2, exp: "螺旋桨的主要技术参数包括直径、螺距、桨叶数和材料。 直径：螺旋桨的直径决定了其产生的推力和扭矩的大小。 螺距：螺距类似于齿轮的齿数，影响螺旋桨的升力和效率。 桨叶数：桨叶的数量会影响螺旋桨的效率和产生的噪音。 材料：螺旋桨的材料决定了其强度和重量，进而影响性能。 因此，正确答案是直径，螺距，桨叶数，材料。" },
  { id: 1434, cat: "综合问答", q: "每到一个新的地方必须校准什么传感器？（）", opts: ["GPS", "气压计", "地磁传感器"], ans: 2, exp: "每到一个新的地方必须校准的传感器是地磁传感器，即磁罗盘传感器。这是因为地磁 传感器用于确定无人机的飞行方向，而不同地理位置的磁场可能会有所差异，因此每次变换 无人机飞行地点时，都需要重新对指南针进行校准，这一点非常重要。" },
  { id: 1435, cat: "综合问答", q: "民用无人机调整中的基本感度是（）", opts: ["飞控 PID 调节中的比例项 P 的系数", "飞控 PID 调节中的 I 积分系数", "飞控 PID 调节中的", "微分系数"], ans: 0, exp: "在无人机飞控系统中，PID 调节是用来控制飞行器姿态和稳定性的重要方法。PID 调 节中的比例项 P 的系数被称为基本感度，它决定了飞行器对于偏差的响应程度。增大 P 系数 会增加飞行器对偏差的敏感性，从而使得飞行器的调整更加灵敏。因此，基本感度与飞行器 的调整灵敏度密切相关。" },
  { id: 1436, cat: "综合问答", q: "民用无人机运行多处于低空速环境下，主要受到的阻力有（）：1.摩擦阻力；2.循环阻力；3.干扰阻力；4.激波阻力；5.诱导阻力；6.压差阻力。", opts: ["1234", "1256", "1356"], ans: 2, exp: "在低空速环境下，民用无人机主要受到的阻力包括摩擦阻力、压差阻力、干扰阻力和 诱导阻力。 这些阻力类型与无人机的气动特性和飞行环境密切相关。 摩擦阻力：由于空气粘性产生的阻力，与飞行器的浸湿面积、表面光洁度有关。 压差阻力：飞行器前后产生压力差形成的阻力，与飞行器的长细比等几何外形有关。 干扰阻力：飞行器各部分之间由于气流相互干扰而产生的额外阻力。 诱导阻力：与翼尖涡流和下洗流有关，与升力的产生有关。" },
  { id: 1437, cat: "综合问答", q: "目前常用的无人机常用什么类型电机？（）", opts: ["外转子三相交流无刷同步电机", "外转子三相交流无刷异步电机", "内转子直流有刷电机"], ans: 0, exp: "本题主要考核对无人机常用电机类型的了解。目前常用的无人机多采用外转子三相交 流无刷同步电机。这种电机具有效率高、功率密度大、可靠性好等优点。外转子结构使得电 机在相同功率下可以提供更大的扭矩。三相交流无刷设计减少了电刷的磨损和维护成本，同 时提高了电机的寿命和性能。" },
  { id: 1438, cat: "综合问答", q: "目前无人机平台常用动力电池类型为锂聚电池，关于其特点错误的是（）", opts: ["无记忆效应", "标称电压一般为 3.7v", "充满电压一般为 4.7v"], ans: 2, exp: "本题主要考核对无人机常用动力电池锂聚电池特点的了解。锂聚合物电池无记忆效应，标称电压一般为 3.7V。充满电压一般为 4.2V 左右，而不是 4.7V。" },
  { id: 1439, cat: "综合问答", q: "哪个可以设定教练主控，学员副控？（）", opts: ["Trainer", "Display", "METRIC"], ans: 0, exp: "“Trainer”通常是训练模式的设置选项，在该模式下可以设定教练主控，学员副控，方便进行教学训练。“Display”一般是与显示相关的设置，“METRIC”可能是与度量单位等 相关的设置。" },
  { id: 1440, cat: "综合问答", q: "哪种电池能量密度最大？（）", opts: ["锂聚合物电池", "镍氢电池", "铅酸电池"], ans: 0, exp: "能量密度最大的电池是锂聚合物电池。锂聚合物电池通过增加正极材料和电解液的导 电性，提高了能量密度和电流输出，适应小型无人机的需求，同时具有高安全性能。锂聚合 物电池具有更高能量密度、小型化、薄型化、轻量化、高安全性、长循环寿命与低成本的特 点。因此，正确答案是锂聚合物电池。" },
  { id: 1441, cat: "综合问答", q: "能否使用高 KV 电机带动远大于适配桨大小的桨？（）", opts: ["能", "不能", "无所谓"], ans: 1, exp: "不能。因为高 KV 值电机通常转速较高，使用远大于适配桨大小的桨会导致电机负载 过大，可能会使电机过热、效率降低甚至损坏电机，同时也会影响飞行性能和安全性。" },
  { id: 1442, cat: "综合问答", q: "起飞前无人机、遥控器、地面控制站正确安全的通电顺序应是（）", opts: ["地面站、遥控器、无人机", "遥控器、无人机、地面站", "无人机、地面站、遥控器"], ans: 0, exp: "起飞前先开启地面站，地面站可以进行飞行前的各种参数设置和监测准备。接着开启 遥控器，确保遥控器与地面站及无人机的通信连接正常。最后开启无人机，这样可以保证整 个系统的有序启动和安全运行，避免出现通信混乱等问题。" },
  { id: 1443, cat: "综合问答", q: "气压传感器测的是以下哪个高度？（）", opts: ["相对高度", "海拔高度", "无线电高度"], ans: 1, exp: "气压传感器是通过测量大气压力来确定高度的。它测量的是相对于海平面的高度，也 就是海拔高度。而相对高度通常是通过测量与某个参考点的垂直距离得到，无线电高度是通 过无线电波反射原理测量飞机与地面之间的实际高度。" },
  { id: 1444, cat: "综合问答", q: "汽油机随着高度的增加，功率会增大还是减小？（）", opts: ["增大", "不变", "减小"], ans: 2, exp: "这个问题考察了发动机性能与环境因素之间的关系。随着高度的增加，汽油机的功率 会减小。这是因为随着海拔的升高，大气压力降低，空气变得稀薄，含氧量减少。汽油机的 燃烧效率依赖于空气和燃料的混合，稀薄的空气会导致燃烧不充分，从而降低发动机的功率 输出。" },
  { id: 1445, cat: "综合问答", q: "倾斜盘是 CCPM 的直升机，当飞机往后飞时，多少个舵机在动？（）", opts: ["3", "1", "2"], ans: 0, exp: "本题考查了对于倾斜盘是 CCPM 的直升机飞行原理的理解。对于采用 CCPM 系统的直升 机，当飞机往后飞时，通常会有 3 个舵机在动。这是因为 CCPM 系统通过 3 个舵机协同控制 倾斜盘的俯仰、横滚和总距变化，每个舵机都会参与动作，以实现直升机的后飞。" },
  { id: 1446, cat: "综合问答", q: "倾斜盘是 CCPM 的直升机有几个舵机？（）", opts: ["5", "6", "4"], ans: 2, exp: "倾斜盘是 CCPM 的直升机通常使用 4 个舵机。这种设计通过多个舵机协同工作，实现 对直升机姿态的精确控制，这是现代直升机中最常见的设计。 【拓展知识】 CCPM（CyclicCollectivePitchMixing，周期变距-总距混合控制）是一种直升机控制系统，用于通过倾斜盘控制主旋翼的俯仰、横滚和总距变化。" },
  { id: 1447, cat: "综合问答", q: "请将多旋翼无人机以下部件正确连接：IMU、ESC、起落架、电机、螺旋桨。（）", opts: ["ESC-IMU-螺旋桨", "IMU-ESC-螺旋桨", "ESC-电机-螺旋桨"], ans: 2, exp: "在多旋翼无人机中，各个部件的正确连接关系如下： IMU（惯性测量单元）：用于测量无人机的姿态和运动参数，通常连接到飞控系统，不直接连 接到其他硬件部件。 ESC（电子调速器）：负责控制电机的转速，直接连接到电机。 起落架：是无人机的支撑结构，用于在地面上移动和停放无人机，不直接连接到其他部件。 电机：由 ESC 控制，用于提供无人机所需的升力。 螺旋桨：安装在电机上，由电机驱动，产生推力或升力。 因此，正确的连接是 ESC-电机-螺旋桨。" },
  { id: 1448, cat: "综合问答", q: "请将固定翼无人机以下部件正确用线连接：发动机，IMU，起落架，螺旋桨，水平尾翼 （）", opts: ["IMU-发动机", "发动机-螺旋桨", "起落架-水平尾翼"], ans: 1, exp: "在固定翼无人机中，各个部件的连接关系如下： IMU（惯性测量单元）：通常安装在无人机的中心位置，用于测量无人机的姿态、速度和位置，不直接连接到其他部件。 发动机：直接驱动螺旋桨，提供推力，使无人机能够在空中飞行。 起落架：是无人机的支撑结构，用于在地面上移动和停放无人机，不直接连接到水平尾翼。 水平尾翼：是无人机的稳定面，用于控制无人机的俯仰和保持水平飞行，不直接连接到起落 架。 因此，正确的连接是发动机-螺旋桨" },
  { id: 1449, cat: "综合问答", q: "若一架无人机在飞行中可以进行舵面遥控，但无实时图像信号，地面站有各类仪表信 息，但无法编辑航点航线，请问该无人机的遥控器（）正常，图传（）故障，数传电台（）正常，（）故障。", opts: ["下行链路、上行链路、下行链路、上行链路", "上行链路、下行链路、下行链路、上行链路", "上行链路、上行链路、下行链路、下行链路"], ans: 1, exp: "这道题主要考查对无人机遥控、图传和数传电台上下行链路工作状态的理解。 首先，无人机能进行舵面遥控，说明遥控器发出的指令能被无人机接收并执行，即遥控器的 上行链路正常。 其次，无实时图像信号，意味着无人机拍摄的图像无法传输回地面站，即图传的下行链路故 障。 然后，地面站有各类仪表信息，表明无人机的状态信息能传输到地面站，所以数传电台的下 行链路正常。 最后，地面站无法编辑航点航线，说明地面站发出的编辑指令无法传输到无人机，即数传电 台的上行链路故障。" },
  { id: 1450, cat: "综合问答", q: "设置遥控器的某一开关键为飞行模式的切换，主要通过哪个功能菜单实现？（）", opts: ["End Point", "Condition", "Function"], ans: 2, exp: "设置遥控器的某一开关键为飞行模式的切换，主要通过“Function”功能菜单实现。 这是因为在遥控器的设置中，“Function”菜单允许用户为不同的开关和拨杆分配特定的功 能，包括飞行模式的切换。" },
  { id: 1451, cat: "综合问答", q: "什么电池记忆能力最强？（）", opts: ["镍氢电池", "镍铬电池", "锂电池"], ans: 1, exp: "镍铬电池具有较强的记忆效应，即电池在不完全放电的状态下充电，容易使电池过度 充电，久而久之会使电池容量降低，记忆能力最强。镍氢电池的记忆效应相对较弱，而锂电 池基本没有记忆效应。" },
  { id: 1452, cat: "综合问答", q: "升力公式 CL=1/2p V2 S 中，各字母的含义分别是（）", opts: ["CL 为升力系数，p 是运行环境大气密度，V 是地速，S 是机体迎风面积", "CL 为升力系数，P 是机体材密度，v 是真空速，S 是机体迎风面积", "QL 为升力系数，P 是运行环境大气密度，v 是真空速，S 是机翼面积"], ans: 2, exp: "在升力公式 L=1/2pvCLS 中，CL 为升力系数，它是一个无量纲的数值，反映了机翼等 产生升力的效率；p 是运行环境大气密度，不同的高度和天气条件下大气密度会有所不同； v 是真空速，即飞机相对于空气的速度；S 是机翼面积，机翼面积越大，在其他条件相同的 情况下，产生的升力也会相应增大。" },
  { id: 1453, cat: "综合问答", q: "使用独立电调的无人机，ESC 上一般共有几根线？最粗的两根线连接的是（），最细的 三根杜邦线连接的是（）", opts: ["7 或 8；电源；飞控", "7 或 8；电源；电机", "5；电源；电机"], ans: 0, exp: "使用独立电调的无人机，ESC（电子调速器）相关知识是无人机原理中的重要部分。 从线的数量看，一般是 7 或 8 根。最粗的两根线连接电源，这是因为需要较大的电流传输能 力，所以线粗；最细的三根杜邦线连接飞控，是用于信号传输等功能。而电机与 ESC 连接不 是通过这最细的三根线。这样设计是为了实现飞控对 ESC 的控制，进而控制电机的运转，这 是整个无人机动力和控制体系中的关键环节。" },
  { id: 1454, cat: "综合问答", q: "使用遥控器遥控飞行时，如果无人机反应时断时续或无反应，不可能的原因是（）", opts: ["遥控器电力不足", "磁场干扰", "动力电池电量不够"], ans: 2, exp: "动力电池电量不够通常影响的是无人机的飞行能力，而不是遥控器与无人机之间的信 号传输。因此，如果无人机反映时断时续或无反应，不太可能是由于动力电池电量不够。" },
  { id: 1455, cat: "综合问答", q: "四轴飞行器和八轴飞行器的区别是（）", opts: ["四轴飞行时间短，效率高，八轴更稳", "四轴飞行时间久，效率高，八轴更稳", "八轴飞行时间久，效率高，四轴更稳"], ans: 1, exp: "在相同条件下，四轴飞行器结构简单、重量轻，桨叶尺寸通常更大，升力效率更高，能耗更低，所以飞行时间更久；而八轴飞行器由于旋翼更多，机身重量增加，需要分配更多 能量来维持飞行，效率相对较低，续航时间较短。同时，八轴飞行器因有更多的旋翼提供动 力和控制，在稳定性方面更有优势。" },
  { id: 1456, cat: "综合问答", q: "外转子电机规格 2208；9T；KV1000 分别代表什么含义？（）", opts: ["定子线圈直径 22 英寸，定子线圈高度 8 英寸，每分钟转速为 1000 转", "定子线圈直径 22 英寸，定子线圈高度 8 英寸，每伏特电压能达到的每分钟转速为 1000 转", "定子线圈直径 22 毫米，定子线圈高度 8 毫米，每伏特电压能达到的每分钟转速为 1000 转"], ans: 2, exp: "外转子电机的规格 2208；9T；KV1000 的含义如下： 22：定子线圈直径为 22 毫米（非英寸）。 08：定子线圈高度为 8 毫米（非英寸） 9T：代表较低匝数，通常对应高 KV 值、高转速、低扭矩的特性（与高匝数电机相反）。 KV1000=每 1V 电压提供 1000 转/分钟（无负载时）。" },
  { id: 1457, cat: "综合问答", q: "外转子电机和内转子电机，在相同电压，相同电流下，哪个转速快？（）", opts: ["外转子电机", "内转子电机", "一样大"], ans: 1, exp: "内转子电机的转速通常比外转子电机快。这是因为内转子电机的转动惯量较小，在相 同的电压和电流下，能够更快速地响应并达到较高的转速。而外转子电机由于转子在外部且 通常质量较大，转动惯量较大，导致其转速相对较慢。" },
  { id: 1458, cat: "综合问答", q: "无人机 GPS 模式下人工管（）", opts: ["姿态和位置", "位置", "位置修正量"], ans: 2, exp: "在无人机 GPS 模式下，姿态和位置主要由系统自动控制，人工主要负责管位置修正量。 当无人机受干扰或存在定位偏差时，操作人员可通过遥控器输入指令微调，使其精准定位或 保持飞行路径。" },
  { id: 1459, cat: "综合问答", q: "旋翼飞行器可以在距离障碍物 10 米以外，1~10 米的高度上飞移，速度不得大于（）", opts: ["20 公里/小时", "15 公里/小时", "10 公里/小时"], ans: 1, exp: "根据《民用无人驾驶航空器系统安全管理规定》及相关飞行标准：旋翼飞行器（如无 人机）在距离障碍物 10 米以外、高度 1~10 米范围内飞移时，速度不得超过 15 公里/小时。" },
  { id: 1460, cat: "综合问答", q: "无人机系统中的 GPS 模块为飞控提供了哪些信息？（）", opts: ["位置，高度与地速", "传感器。姿态与加速度", "经纬度，高度与空速"], ans: 0, exp: "无人机系统中的 GPS 模块为飞控提供的信息包括位置、高度与地速。这些信息对于无 人机的导航和定位至关重要，使无人机能够沿指定航线安全、准时、准确地飞行。因此，正 确答案是：位置，高度与地速。" },
  { id: 1461, cat: "综合问答", q: "无人机用无刷电机的主要技术参数有哪些？（）", opts: ["转子直径，转子高度，kv 值，功率 W", "定子直径，转子高度，kv 值，功率 W", "定子直径，定子高度，kv 值，功率 W"], ans: 2, exp: "无人机用无刷电机的主要技术参数包括定子直径、定子高度、kv 值和功率 w。定子直 径和定子高度决定了电机的尺寸和结构，kv 值反映了电机在特定电压下的转速特性，功率 则表示电机的输出能力。转子直径和转子高度通常不是无刷电机的主要技术参数表述内容。" },
  { id: 1462, cat: "综合问答", q: "无人机在姿态模式下（）", opts: ["飞控参与外回路", "飞控参与内回路", "内外均参与"], ans: 1, exp: "在无人机的飞行模式中，姿态模式（AttitudeMode）是指飞控系统主要参与内回路控 制，即直接控制无人机的姿态，但不直接控制无人机的位置或高度。在这种模式下，无人机 的稳定性和响应性较高，但需要飞行员有较好的操作技巧来维持无人机的飞行状态。" },
  { id: 1463, cat: "综合问答", q: "无人直升机遥控状态下动力失效最恰当的处置方式是？（）", opts: ["势能转换动能，打负总螺距使旋翼高速下降，在离地面数米高时，将总距变最大，迅速 制止快速下沉，缓慢着陆", "无法安全降落，让其降落在人员稀少的地方", "开启降落伞"], ans: 0, exp: "无人直升机在遥控状态下遇到动力失效的情况时，最恰当的处置方式是利用势能转换 为动能，通过打负总螺距使旋翼高速下降，在离地面数米高时，将总距变最大，迅速制止快 速下沉，缓慢着陆。这种方法可以最大限度地利用旋翼的自转来减缓下降速度，增加着陆的 安全性。" },
  { id: 1464, cat: "综合问答", q: "无刷电机如果遇到旋转方向相反，需要换方向是如何处理？（）", opts: ["电调与飞控的连线进行对换", "电调与电源的连线进行对换", "电调与电机的连线 3 根任意对换 2 根"], ans: 2, exp: "无刷电机的旋转方向由电机与电调之间的 3 根连线的连接顺序决定。当电机旋转方向 相反需要换向时，可以将电调与电机的 3 根连线中的任意 2 根对换，这样就可以改变电机的 旋转方向。而电调与飞控的连线对换以及电调与电源的连线对换都不能改变电机的旋转方向。" },
  { id: 1465, cat: "综合问答", q: "下列属于定向天线的是？（）", opts: ["各长度鞭状天线", "蘑菇头天线", "八木天线"], ans: 2, exp: "八木天线是具有较强方向性的定向天线，它可以将信号集中在特定的方向上发射和接 收。而鞭状天线和蘑菇头天线通常是全向天线，信号在各个方向上的辐射较为均匀。" },
  { id: 1466, cat: "综合问答", q: "现有两组 10000mAh/6S/15C 的电池，将两组电池并联后使用 1C 充电，充满电后电源组 的电压是多少？（）", opts: ["25.2v", "22.2v", "11.1v"], ans: 0, exp: "一块 6S 电池是由 6 节锂电池串联组成，单节锂电池标称电压为 3.7V，充满电时电压 为 4.2V，所以 6S 电池充满电后的电压为 4.2V×6=25.2V。当两组相同的 6S 电池并联后，电 压不变，所以充满电后电源组的电压是 25.2V。" },
  { id: 1467, cat: "综合问答", q: "现有螺旋桨 1845，1555 和电机 5035，4012，请写出最优组合，（）", opts: ["1845 和 4012，1555 和 4012", "1845 和 5035，1555 和 4012", "1845 和 4012，1555 和 5035"], ans: 1, exp: "一般来说，螺旋桨的尺寸需要与电机的尺寸相匹配，以达到最佳的性能和效率。1845 螺旋桨尺寸相对较大，与 5035 电机搭配较为合适，可以提供足够的动力输出；1555 螺旋桨 尺寸较小，与 4012 电机搭配较为合理。这样的组合可以确保电机能够有效地驱动螺旋桨，同时也能保证系统的稳定性和可靠性。" },
  { id: 1468, cat: "综合问答", q: "现有一块聚合物锂电池可能会长时间不使用，充放电至电量多少，电压多少储存合适？ （）", opts: ["80%；4.7v", "20%；3.2v", "40%至 50%；3.8v"], ans: 2, exp: "聚合物锂电池如果长时间不使用，充放电至 40%至 50%的电量，电压为 3.8V 左右储存 比较合适。这样可以减少电池的自放电损耗，同时也能避免电池过充或过放对电池性能和寿 命造成的不良影响。" },
  { id: 1469, cat: "综合问答", q: "现在常见的直升机中，平衡周期变距，克服挥舞的部件是（）", opts: ["电子陀螺仪", "机械陀螺仪", "副翼"], ans: 0, exp: "在直升机中，平衡周期变距和克服挥舞的部件是电子陀螺仪。电子陀螺仪的作用是感 知直升机的姿态变化，并自动调整桨叶的桨距，以保持直升机的稳定飞行。它通过检测直升 机的旋转运动并提供反馈信号，帮助控制系统调整桨叶的角度，从而抵消挥舞现象并保持周 期变距的稳定。" },
  { id: 1470, cat: "综合问答", q: "需要灵活操控性能的飞机，选用（）电机。", opts: ["高直径", "高转速", "高扭矩"], ans: 1, exp: "选择需要灵活操控性能的无人机时，应该选用高转速（HighSpeed）电机。这是因为 高转速电机能够提供更快的响应速度，使得无人机在进行快速机动和调整时更为敏捷。在无 人机飞行中，尤其是需要快速反应和高度机动性的场景下，高转速电机可以提供更好的操控 性能。" },
  { id: 1471, cat: "综合问答", q: "旋翼飞行器从悬停到高速前飞的增速过程中，需用功率如何变化？（）", opts: ["一直增大", "一直减小", "先减小后增大"], ans: 2, exp: "在旋翼飞行器从悬停到高速前飞的增速过程中，开始阶段随着前飞速度增加，诱导功 率减小，需用功率也减小；但当速度继续增大到一定程度后，型阻功率等其他功率因素开始 占主导，需用功率又会增大。" },
  { id: 1472, cat: "综合问答", q: "选择哪一个功能选项，在手动遥控飞行时，可以改变各通道的操作灵敏度？（）", opts: ["微调比例", "行程比例", "通道比例"], ans: 1, exp: "在手动遥控飞行时，“行程比例”功能选项可以改变各通道的操作灵敏度。通过调整 行程比例，可以使遥控器对飞行器的控制更加精细或更加灵敏，以适应不同的飞行需求和操 作习惯。" },
  { id: 1473, cat: "综合问答", q: "遥控器、图传、地面站与飞行器之间数据链路分别是（）", opts: ["上行链路、下行链路、上行链路", "上行链路、下行链路、上下行链路并存", "下行链路、下行链路、上行链路"], ans: 1, exp: "遥控器向飞行器发送控制指令，是上行链路；图传是将飞行器上拍摄的图像等信息传 输到地面，属于下行链路；地面站与飞行器之间既有地面站向飞行器发送的指令等信息（上 行链路），也有飞行器向地面站回传的状态等信息（下行链路），所以是上下行链路并存。" },
  { id: 1474, cat: "综合问答", q: "遥控器菜单中 FAIL SAFE 代表什么意思？（）", opts: ["飞行模式切换", "失控保护", "通道反向"], ans: 1, exp: "在遥控器菜单中，“FAILSAFE”代表失控保护。当遥控器与飞行器之间的信号丢失或 出现异常情况时，失控保护功能会启动，使飞行器执行预设的安全动作，以降低意外发生的 风险。" },
  { id: 1475, cat: "综合问答", q: "遥控器菜单中 SUB TRIM 代表什么意思？（）", opts: ["通道反向", "中立微调", "失控保护"], ans: 1, exp: "在遥控器菜单中，“SUBTRIM”代表中立微调。它可以用来对各个通道的中立位置进行 微小调整，以确保在未进行操作时飞行器的各个控制面处于合适的初始位置。" },
  { id: 1476, cat: "综合问答", q: "遥控器设置菜单中 REV 是设置什么的？（）", opts: ["通道行程", "通道反向", "失控保护"], ans: 1, exp: "这道题目考察了对遥控器设置菜单中“REV”功能的理解。“REV”是遥控器设置中的 一个常用术语，代表“Reverse”，即反向。在遥控器的通道设置中，“REV”选项允许用户改 变通道的响应方向，即当遥控器的操纵杆或旋钮向一个方向移动时，对应的无人机控制舵面 向相反方向响应。这对于某些特定的飞行操作或个人的操作习惯可能是必要的。" },
  { id: 1477, cat: "综合问答", q: "遥控器中升降舵、副翼、方向舵、油门的英文简称是什么？（）", opts: ["ELE、THR、RUD、AIL", "RUD, AlL, ELE, THR", "ELE , AIL, RUD , THR"], ans: 2, exp: "这道题目考察了无人机遥控器上各个控制舵面的英文简称。在无人机飞行控制中，了 解这些简称是非常重要的，因为它们是飞行员与无人机之间通信的基础。这些简称分别对应 于： 升降舵（Elevator）的简称是 ELE，控制无人机的上下运动。 副翼（Aileron）的简称是 AIL，控制无人机的左右滚转。 方向舵（Rudder）的简称是 RUD，控制无人机的左右转向。 油门（Throttle）的简称是 THR，控制无人机的动力输出，即速度。" },
  { id: 1478, cat: "综合问答", q: "一般不用来给无人机提供高度信息的传感器是（）", opts: ["GPS、气压计", "温度传感器、大气温度传感器", "无线电高度表、超声波传感器"], ans: 1, exp: "温度传感器和大气湿度传感器一般不用来给无人机提供高度信息。GPS、气压计、无 线电高度表、超声波传感器等可以用于获取无人机的高度信息。" },
  { id: 1479, cat: "综合问答", q: "一般情况下，无人机使用电机 5022 和 4025 哪个电机的 KV 值大些？（）", opts: ["5022", "4025", "一样快"], ans: 1, exp: "电机型号中的数字一般前两位表示电机定子直径，后两位表示电机定子高度。通常情 况下，定子尺寸较小的电机 KV 值相对较大。4025 电机的定子尺寸小于 5022 电机，所以一 般情况下 4025 电机的 KV 值大些。" },
  { id: 1480, cat: "综合问答", q: "一般情况下，要增加直升机最大负载，最合适的办法是（）", opts: ["增大转速，增大桨距", "增大转速，减小桨距", "减小转速，增大桨距"], ans: 1, exp: "增加直升机最大负载需要考虑升力的变化。增加转速可以提高旋翼产生的升力，同时 减小桨距可以在一定程度上控制升力的增加幅度，避免过度上升而不稳定。如果增大桨距，虽然升力会增加，但可能会导致发动机负荷过大等问题。而减小转速并增大桨距会使升力减 小，不利于增加最大负载。" },
  { id: 1481, cat: "综合问答", q: "已知某锂电池标记为 6S 2P 3C，单片锂电池容量为 16000mAh，则该电池最大放电电流 是（）", opts: ["16A", "96A", "48A"], ans: 1, exp: "首先明确标记含义，6S 表示 6 个电芯串联，2P 表示 2 组电芯并联，所以总容量为 16000mAh×2=32000mAh。3C 表示放电倍率为 3 倍。1C 的放电电流等于电池容量数值，32000mAh=32A，3C 的放电电流为 32AX3=96A。" },
  { id: 1482, cat: "综合问答", q: "以 6S 5000mAh 20C（3C）锂电池为例子，最大放电电流是多少？（）", opts: ["30A", "15A", "100A"], ans: 2, exp: "对于锂电池，放电电流可以通过电池容量和放电倍率来计算。已知该电池为 6S（即 由 6 个电芯串联）5000mAh20C（3C），这里取较大的放电倍率 20C。1C 的放电电流等于电池 容量数值，即 5000mAh=5A，20C 的放电电流为 5A×20=100A。" },
  { id: 1483, cat: "综合问答", q: "以下不属于直升机的是？（）", opts: ["四轴飞行器", "倾转旋翼机", "共轴旋翼机"], ans: 1, exp: "倾转旋翼机是一种介于直升机和固定翼飞机之间的混合型飞行器。它通过倾转旋翼来 实现垂直起降和水平飞行。在垂直起降时，旋翼像直升机一样提供升力；在水平飞行时，旋 翼倾转为固定翼飞行模式，提供推进力。因此，倾转旋翼机既具有直升机的特点，也具有固 定翼飞机的特点，但它并不属于传统意义上的直升机。" },
  { id: 1484, cat: "综合问答", q: "以下关于舵面遥控（纯手动）、姿态遥控、人工修正（即 GPS 模式）说法不正确的是？ （）", opts: ["人工修正模式下，飞控内外回路都参与工作", "姿态遥控模式下，飞控内回路不参与工作，外回路参与工作提供位置信息", "舵面遥控模式下，飞控内外回路都不参与工作"], ans: 1, exp: "舵面遥控（纯手动）在舵面遥控模式下，飞控内外回路都不参与工作，飞行器的操控完全依赖手动操作，操纵手 杆量对应舵面偏转量。 姿态遥控 姿态遥控时飞控内回路参与工作，主要负责控制飞机姿态，而外回路不提供位置信息，操 纵杆量对应飞机姿态，由飞控保持姿态。 人工修正（GPS 模式）此模式下飞控内外回路都参与工作，飞控对姿态和位置都进行管控，操纵手杆量作为叠加量 或遥控指令处理。 因此，不正确的说法是“姿态遥控模式下，飞控内回路不参与工作，外回路参与工作提供位 置信息”。" },
  { id: 1485, cat: "综合问答", q: "题以下哪一只螺旋桨升力最大？（）", opts: ["18*7（两叶螺旋桨）", "16*4.5（三叶螺旋桨）", "15*4（四叶螺旋桨）"], ans: 0, exp: "升力与螺旋桨的直径、螺距和叶片数量有关。以下是每种螺旋桨的一些关键参数： 18×7（两叶螺旋桨）：较大的直径和螺距，两叶设计，通常能提供较大的升力。 16×4.5（三叶螺旋桨）：较小的直径和螺距，三叶设计，升力较两叶螺旋桨小，但效率可能 更高。 15×4（四叶螺旋桨）：最小的直径和螺距，四叶设计，升力通常小于两叶和三叶螺旋桨。 综合考虑，18×7（两叶螺旋桨）由于其较大的直径和螺距，通常能提供最大的升力。" },
  { id: 1486, cat: "综合问答", q: "以下哪种多旋翼是 H 型机架？（）", opts: ["悟", "经纬 M600", "MAVIC"], ans: 0, exp: "“悟”是 H 型机架，其外形结构呈现较为明显的 H 型。" },
  { id: 1487, cat: "综合问答", q: "以下是共轴双旋翼直升机的优点的是（）", opts: ["操作结构简单", "自转下滑性能优异", "纵向尺寸小"], ans: 2, exp: "共轴双旋翼直升机的优点之一是纵向尺寸小。这是因为共轴双旋翼直升机的两个旋翼 上下排列在同一轴线上，这样可以减少直升机的总体长度，使得纵向尺寸较小。这种设计也 有助于提高直升机的机动性和在狭小空间的操控性。" },
  { id: 1488, cat: "综合问答", q: "以下无人机相关部件，数传电台，飞控，电子调速器，OSD，5.8G 图传，电机，摄像 头等，连接方式正确的是？（）", opts: ["OSD--5.8G 图传--电机", "电机--电子调速器--数传电台--飞控", "电机--电子调速器--飞控--数传电台"], ans: 2, exp: "电机是动力来源，首先与电子调速器相连，电子调速器可控制电机转速，然后它们连 接到飞控，飞控如同无人机的大脑，协调各部件工作，数传电台主要用于数据传输，连接在 飞控之后，完成整个控制链路的连接。 因此，正确的连接顺序是电机-电子调速器-飞控-数传电台。" },
  { id: 1489, cat: "综合问答", q: "用于起降的遥控器中的 AIL，RUD，分别控制多旋翼无人机，（）", opts: ["AIL（左、右移动），RUD（左、右水平旋转）", "AIL（前、后移动），RUD（上、下移动）", "AIL（左、右水平旋转），RUD（左、右移动）"], ans: 0, exp: "（AIL 左、右移，RUD 左、右转）飞行器遥控器各操作通道的功能说明： AIL（Aileron）-副翼控制：控制飞行器左右滚转（横滚）。 ELE（Elevator）-升降舵控制：控制飞行器俯仰（前后运动）。 THR（Throttle）-油门控制：调节发动机或电机推力（上下运动）。 RUD（RUDder）-方向舵控制：控制飞行器偏航（左右水平旋转）。 因此，正确答案是：AIL（左、右移动），RUD（左、右水平旋转" },
  { id: 1490, cat: "综合问答", q: "有三种规格的电机：（1）3S 30000mAh 400kv；（2）4S 20000mAh 600kv；（3）6S 10000mAh 800kv，哪个转速高？（）", opts: ["第（1）种", "第（2）种", "第（3）种"], ans: 2, exp: "电机转速与电压和 kv 值有关。电压乘以 kv 值可大致得出转速。根据公式计算出三种 电机的转速： 第（1）种电机，电压为 3×3.7=11.1 伏，转速约为 11.1×400=4440 转。 第（2）种电机，电压为 4×3.7=14.8 伏，转速约为 14.8×600=8880 转。 第（3）种电机，电压为 6×3.7=22.2 伏，转速约为 22.2×800=17760 转。 所以第（3）种电机转速最高。" },
  { id: 1491, cat: "综合问答", q: "在自主飞行过程中，遥控器油门的位置应处于（）", opts: ["油门处于中间略上", "油门处于最下方", "油门处于最上方"], ans: 0, exp: "在自主飞行过程中，遥控器油门的位置应处于中间略上。这是因为在自主飞行模式下，无人机通常会自动保持其高度和位置，而不需要遥控器的持续输入。将油门设置在中间略上 的位置可以确保无人机保持稳定的飞行状态，同时允许进行微小的高度调整。" },
  { id: 1492, cat: "综合问答", q: "直升机的重心位置在（）", opts: ["直升机主轴后处", "直升机主轴前处", "直升机发动机处"], ans: 1, exp: "直升机的重心位置通常位于直升机主轴的前处。这是因为直升机的设计需要确保在飞 行中保持平衡，而重心位于主轴前部有助于实现这种平衡。重心位于主轴前部还可以帮助抵 消主旋翼产生的扭矩，因为直升机的发动机和传动系统通常位于主轴的后方，这些重量需要 被平衡。" },
  { id: 1493, cat: "综合问答", q: "直升机旋翼头有几种结构形式？（）", opts: ["铰链式旋翼星型柔性桨毂", "无铰链式旋翼万向接头式", "以上都是"], ans: 2, exp: "直升机旋翼头有多种结构形式。铰链式旋翼星型柔性桨毂是一种常见结构，通过铰链 和柔性部件实现桨叶的运动和受力传递。无铰式旋翼万向接头式也是一种结构形式，减少了 传统铰链结构，提高了可靠性和稳定性。所以答案是以上都是。" },
  { id: 1494, cat: "综合问答", q: "直升机在飞行过程中，若尾旋翼失效，飞机将（）", opts: ["继续保持原来飞行姿态", "自旋", "自旋几圈后恢复原来的状态"], ans: 1, exp: "直升机在飞行过程中，尾旋翼（尾桨）的主要作用是抵消主旋翼产生的反扭矩，以保 持直升机的稳定，并控制方向。若尾旋翼失效，直升机将因无法抵消反扭矩而开始自旋。这 是因为尾桨的推力是由一个独立的动力系统提供的，通常是直升机的发动机，飞行员可以通 过调整油门来改变尾桨的推力。当尾桨失效时，这种推力的调整变得不可能，导致直升机失 去平衡并开始旋转。" },
  { id: 1495, cat: "综合问答", q: "众所周知，物体运动的速度是一个矢量，关于飞行过程中空速与地速的关系，下列正 确的是？（）", opts: ["正侧风时，空速=地速", "无论何时，空速+风速=地速", "逆风时，空速<地速"], ans: 1, exp: "空速是指飞行器相对于空气的运动速度，地速是指飞行器相对于地面的运动速度。风 的存在会影响地速。在飞行过程中，无论风向如何，都是空速与风速共同作用决定地速。" },
  { id: 1496, cat: "综合问答", q: "自动定高飞行时，飞行器持续升高或下降，不可能的原因是（）", opts: ["角速度故障", "动力系统故障", "高度传感器故障"], ans: 0, exp: "在自动定高飞行时，如果飞行器持续升高或下降，这通常与高度控制相关的问题有关。 角速度故障通常影响的是飞行器的姿态和方向控制，而不是高度控制。因此，飞行器持续升 高或下降不可能是由于角速度故障引起的。" },
  { id: 1497, cat: "综合问答", q: "自动驾驶仪中的陀螺是用来测量哪些物理量的？（）", opts: ["角速度", "加速度", "方向"], ans: 0, exp: "自动驾驶仪中的陀螺主要用来测量飞机的角速度。陀螺仪是一种传感器，能够检测和 维持物体的旋转状态，通过测量绕其轴的旋转速率，即角速度，来帮助无人机感知其姿态变 化。这对于飞行控制系统来说至关重要，因为它可以据此调整飞机的姿态以保持稳定飞行。" },
  { id: 1498, cat: "综合问答", q: "自动驾驶仪中的陀螺是用来测量哪些物理量？（）", opts: ["飞机角速度或飞行姿态", "飞机角速率或飞机姿态角", "飞机角速度或飞机姿态角"], ans: 2, exp: "自动驾驶仪中的陀螺主要用来测量无人机的角速度和姿态角。陀螺仪是一种能够测量 和维持方向的设备，它能够感应无人机绕其轴的旋转速度，即角速度，同时通过积分角速度 信号，可以得出无人机相对于起始位置的姿态角。这对于维持无人机的稳定飞行和正确导航 至关重要。" },
  { id: 1499, cat: "综合问答", q: "一般冬天和夏天相比，我们返航电压应该怎么设置？为什么？（）", opts: ["冬天要高于夏天，冬天温度低，锂离子活性变低，持续放电时间短", "冬天要低于夏天。冬天温度低，锂离子活性变低，持续放电时间短", "冬天要高于夏天。冬天温度低，锂离子活性变高，持续放电时间短"], ans: 0, exp: "冬天和夏天相比，无人机的返航电压应该设置得更高。这是因为冬天气温低，锂电池 的活性及放电能力会降低，如果返航电压过低，有可能导致突然降压引发飞行事故。因此，正确答案是冬天要高于夏天。冬天温度低，锂电池活性变低，持续放电时间短。" },
  { id: 1500, cat: "综合问答", q: "无人机的基本感度是什么感度？（）", opts: ["磁罗盘的感度", "姿态角的感度", "陀螺仪的感度"], ans: 2, exp: "陀螺仪主要用于测量无人机的角速度，对无人机的姿态稳定起着关键作用。基本感度 通常指的是陀螺仪的感度，它决定了无人机对姿态变化的响应程度。而磁罗盘主要用于确定 方向，姿态角是由陀螺仪等多种传感器共同作用得出的结果，它们都不是基本感度的代表。" },
  { id: 1501, cat: "综合问答", q: "无人机过于灵敏，应该调整遥控器上的什么感度？（）", opts: ["IMU 感度", "飞控感度", "姿态感度"], ans: 2, exp: "当无人机过于灵敏时，主要表现为姿态变化过于迅速，调整姿态感度可以降低无人机 对操控输入的响应速度，使其飞行更加平稳。 其他选项分析如下： 1.IMU（惯性测量单元）感度主要与无人机的惯性测量相关，一般不直接影响无人机的灵敏 程度。 2.飞控感度较为宽泛，而具体针对无人机过于灵敏的问题主要调整姿态感度更为准确。" },
  { id: 1502, cat: "综合问答", q: "无人机视距外飞行丢星怎么办？（）", opts: ["自动悬停", "降高度", "升高度"], ans: 2, exp: "在无人机视距外飞行丢星时，升高高度可以减少周围建筑物、地形等对卫星信号的遮 挡，更有可能重新接收到卫星信号。 而自动悬停可能会因为没有足够的卫星定位信号而无法稳定保持位置，且不一定能解决丢星 问题。降低高度可能会使无人机处于更多的信号遮挡区域，不利于重新获取卫星信号。" },
  { id: 1503, cat: "综合问答", q: "无人机怎么飞最省油或最省电？（）", opts: ["匀速", "高速", "低速"], ans: 0, exp: "无人机在飞行时，最省油或最省电的方式是保持匀速飞行。这是因为在匀速飞行状态 下，无人机的发动机或电机工作在稳定的状态，不需要额外的动力来加速或减速，从而可以 更有效地使用能量。相比之下，高速或低速飞行都需要更多的能量来克服空气阻力或提供额 外的动力。" },
  { id: 1504, cat: "综合问答", q: "高海拔下航时及载重能力将大大缩短，此时应如何配置螺旋桨及电机？（）", opts: ["高 KV，小直径，小螺距", "低 KV，大直径，大螺距", "高 KV，大直径，小螺距"], ans: 2, exp: "在高海拔地区，由于空气稀薄，无人机的航时和载重能力会受到影响。为了适应这种 情况，需要选择高 KV 值、大直径、小螺距的螺旋桨和电机配置。高 KV 值电机可以在相同电 压下提供更高的转速，而大直径和小螺距的螺旋桨可以在较低的转速下提供足够的升力，从 而适应高海拔地区的飞行条件。因此，正确答案是高 KV，大直径，小螺距。" },
  { id: 1505, cat: "综合问答", q: "高原地区 16*8 两叶，17*6 两叶，15*5 三叶，灵活性最好的是哪一个？最省电是哪一 个？（）", opts: ["灵活 15*5 三叶，最省 17*6 两叶", "灵活 16*8 两叶，最省 17*6 两叶", "灵活 15*5 三叶，最省 16*8 两叶"], ans: 0, exp: "首先分析灵活性，叶片的尺寸和数量会影响其灵活性。一般来说，叶片尺寸越小、数 量越多，灵活性越好。15×5 三叶的叶片尺寸相对较小且叶片数量为三，相比 16×8 两叶和 17×6 两叶，其在转动和改变方向时更加灵活。其次分析省电情况，通常叶片尺寸较小、转 动阻力较小的会更省电。17×6 两叶的叶片尺寸相对较小，转动时消耗的能量相对较少，所 以更省电。 综上所述，灵活性最好的是 15×5 三叶，最省电的是 17×6 两叶。" },
  { id: 1506, cat: "综合问答", q: "GPS 提供哪些信息？（）", opts: ["经纬度、高度、空速", "位置、高度、地速", "坡度、空速"], ans: 1, exp: "GPS（全球定位系统）是一种卫星导航系统，可以提供精确的位置（包括经纬度）、高 度以及地速（飞行器相对于地面的速度）。这些信息是通过接收卫星信号并计算得出的。" },
  { id: 1507, cat: "综合问答", q: "内、外转子无刷电机的特点、区别和应用领域是？（）", opts: ["外转子扭矩大，适合带大桨，效率高，广泛应用于各种电动无人机上；内转子转速高，适合用于电涵道航空模型上", "外转子扭矩大，适合带小桨，效率高，广泛应用于各种电动无人机上；内转子转速高，适合用于电涵道航空模型上", "外转子扭矩大，适合带大桨，效率高，适合用于电涵道航空模型上；内转子转速高，广 泛应用于各种电动无人机上"], ans: 0, exp: "外转子无刷电机的扭矩较大，适合带动较大的桨叶，效率较高，因此广泛应用于各种 电动无人机上。内转子无刷电机的转速较高，适合用于电涵道航空模型。" },
  { id: 1508, cat: "综合问答", q: "放电倍率为 10C，电池容量 1000mAh，最大放电电流为（）", opts: ["10A", "100A", "1000A"], ans: 0, exp: "放电倍率 10C 表示最大放电电流是电池容量的 10 倍。因此，1000mAh 的电池，最大 放电电流为 1000mAh×10=10000mA=10A." },
  { id: 1509, cat: "综合问答", q: "用于起降的遥控器中在 THR、ELE 通道分别控制多旋翼无人机的（）", opts: ["THR（上升、下降）ELE（前后、俯仰）", "THR（前后、俯仰）ELE（上升、下降）", "THR（上升、前后）ELE（下降、俯仰）"], ans: 0, exp: "在多旋翼无人机的遥控器中，THR（油门）通道通常用于控制无人机的上升和下降，而 ELE（升降舵）通道用于控制无人机的前后移动和俯仰角度。" },
  { id: 1510, cat: "综合问答", q: "遥控器菜单中 REVERSE 代表（）？", opts: ["中立微调", "失控保护", "通道反向"], ans: 2, exp: "遥控器菜单中的“REVERSE”功能代表通道反向设置。这一选项允许用户调整遥控器 各通道的输出方向，确保其与模型的动作需求相匹配。" },
  { id: 1511, cat: "综合问答", q: "多轴单个桨叶旋转锥面是（）", opts: ["正锥面", "倒锥面", "平面"], ans: 1, exp: "多轴单个桨叶旋转时形成的锥面是倒锥面。这是因为桨叶在旋转过程中，由于离心力 的作用，桨叶会向外倾斜，形成一个倒锥形结构。" },
  { id: 1512, cat: "综合问答", q: "多旋翼无人机如何实现左转弯，螺旋桨转速如何变化？（）", opts: ["（顶视）顺时针减速，逆时针加速", "（顶视）顺时针加速，逆时针加速", "（顶视）顺时针加速，逆时针减速"], ans: 2, exp: "多旋翼无人机实现左转弯的原理是通过调整螺旋桨的转速来产生机身旋转的动作。具 体来说，左转弯需要使机身向左旋转，因此需要将顺时针方向的螺旋桨加速，逆时针方向的 螺旋桨减速。" },
  { id: 1513, cat: "综合问答", q: "飞机着陆时，在什么情况下选择宽一些的跑道？（）", opts: ["顺风", "逆风", "侧风"], ans: 2, exp: "侧风着陆时，由于风从侧面吹过跑道，会给飞机施加巨大的侧向力，使其难以保持水 平飞行姿态，并可能导致偏离跑道或过度接地，增加着陆失事的风险。因此，在侧风条件下 着陆时，为了增加安全余度，通常会选择宽一些的跑道。" },
  { id: 1514, cat: "综合问答", q: "风矢杆上的两横，长横代表（）m/s，短横代表（）m/s.", opts: ["长横 4m/s，短横 2m/s", "长横 2m/s，短横 4m/s", "长横 2m/s，短横 2m/s"], ans: 0, exp: "风矢杆 F 上的两横，长横代表 4 米/秒，短横代表 2 米/秒。这种标记方式常用于天气 图中，以直观展示风力大小。" },
  { id: 1515, cat: "综合问答", q: "请将多旋翼无人机以下部件正确用线连接：IMU、ESC、起落架、电机、螺旋桨。（）", opts: ["ESC-IMU-螺旋桨，其余不连", "IMU-ESC-螺旋桨，其余不连", "ESC-电机-螺旋桨，其余不连"], ans: 2, exp: "在多旋翼无人机中，电子调速器（ESC）直接连接到电机，电机再连接到螺旋桨。IMU （惯性测量单元）通常连接到飞行控制器，而不是直接连接到电机或螺旋桨。" },
  { id: 1516, cat: "综合问答", q: "执行飞行任务前，对无人机的检查准备工作包括哪些？①检查电池电量；②飞行器外 观检查，各机载设备零部件外观及连接，螺旋桨是否安装正确；③检查遥控器与地面站，遥 控器各开关位置是否正确，遥杆位置是否正确，地面站电量是否充足，软件是否完备，地面 设备连接是否可靠④开机顺序是否正确；控制站→遥控器→无人机⑤遥控器开机，所选模型 是否正确，飞行模式是否正确（）", opts: ["①②③④⑤", "②③④⑤", "①②③④"], ans: 0, exp: "执行飞行任务前，需要进行以下检查准备工作： 检查电池电量：确保电池电量充足，避免因电量不足导致飞行中断。 飞行器外观检查：检查飞行器的外观，包括各机载设备零部件的外观及连接，螺旋桨是否安 装正确。 检查遥控器与地面站：检查遥控器各开关位置是否正确，遥杆位置是否正确，地面站电量是 否充足，软件是否完备，地面设备连接是否可靠。 开机顺序：确保开机顺序正确，通常是控制站一遥控器一无人机。 遥控器开机：检查遥控器开机后所选模型是否正确，飞行模式是否正确。 因此，正确答案是①②③④⑤。" },
  { id: 1517, cat: "综合问答", q: "无人机在飞行中晃动过大或反应滞后，除了飞控感度的原因，还有可能是什么原因？ ①多旋翼飞行器机臂刚度不够，或有安装旷量②多旋翼机体太大致使转动惯量太大③多旋翼 螺旋桨太重，加速减速致使操纵响应慢④固定翼机体或舵面刚度不够，连杆、摇臂或舵机本 身有旷量（）", opts: ["①②③", "②③④", "①②③④"], ans: 2, exp: "无人机在飞行中晃动过大或反应滞后，除了飞控感度的原因，还可能有以下原因： 多旋翼飞行器机臂刚度不够，或有安装旷量。 多旋翼机体太大致使转动惯量太大。 多旋翼螺旋桨太重，加减速慢致使操纵响应慢。 固定翼机体或舵面刚度不够，连杆、摇臂或舵机本身有旷量。 因此，①②③④全正确。" },
  { id: 1518, cat: "综合问答", q: "Model Type 什么意思？（）", opts: ["模型选择", "模型类型", "模型设置"], ans: 1, exp: "ModelType 通常指的是模型的类型，例如固定翼、多旋翼、直升机等。 其他选项分析如下： 1、模型选择：错误。虽然 ModelType 可以用于选择模型，但其更准确的含义是模型的类型。 2、模型设置：错误。ModelType 不是指模型的设置，而是指模型的类型。" },
  { id: 1519, cat: "综合问答", q: "在高原飞行时，应该选择哪种桨？（）", opts: ["16*55", "18*52", "18*44"], ans: 2, exp: "在高原飞行时，空气稀薄，桨叶需要更大的螺距和直径来获得足够升力。但同时，由 于空气密度低，电机负载相对减小，转速会升高。 选项逐项分析： “16*55”桨叶直径相对较小，在高原稀薄空气环境下，产生的升力相对有限，不太适合高 原飞行。 “18*52”桨叶螺距较大，在高原空气稀薄情况下，电机可能难以驱动达到合适转速，导致 效率降低。 “18*44”桨叶直径较大可保证一定升力，相对较小的螺距使电机在高原空气稀薄时能更好 驱动，更适合高原飞行。 因此，答案选：18*44。" },
  { id: 1520, cat: "综合问答", q: "6S 电池一共有几根线？（）", opts: ["8 根", "7 根", "9 根"], ans: 2, exp: "6S 电池的接线逻辑是主电源线（2 根）：正极（红色）和负极（黑色）输出线，提供 电池总电压（6S 满电 25.2V）。平衡线（7 根）： 6S 电池由 6 个电芯串联组成，平衡线需连接每两节电芯之间的节点，共需 6+1=7 根线（含 首尾极）。 平衡头通常为 JST-XH 接口，排列顺序为：总负极一第 1-2 节间-一第 5-6 节间一总正极。 因此，总接线数：主电源线 2 根+平衡线 7 根=9 根。" },
  { id: 1521, cat: "综合问答", q: "飞行在运行过程中，总是往一个方向运动，请问需要设置遥控器哪个菜单？（）", opts: ["大小舵", "中立微调", "微调"], ans: 1, exp: "如果飞行器在运行过程中总是往一个方向运动，这通常意味着遥控器的中立点需要调 整。中立微调（Trim）功能可以调整遥控器的中立点，使飞行器在无输入时保持平衡。" },
  { id: 1522, cat: "综合问答", q: "开关自定义怎么设置，找一下开关自定义的功能是下面哪一个菜单？（）", opts: ["FUNCTION", "REVERSE", "SERVO"], ans: 0, exp: "遥控器的“开关自定义”功能通常位于 FUNCTION 菜单中。这一设置允许用户将特定 操作或模式切换绑定到遥控器上的物理按钮，以提高飞行效率和便捷性。" },
  { id: 1523, cat: "综合问答", q: "16000mAh 和 22000mAh 的电池都用 0.5C 充电，从空点到满电，分别用多长时间充满？ （）", opts: ["都是一个小时", "都是两个小时", "16000mAh 一个小时，22000mAh 两个小时"], ans: 1, exp: "16000mAh 电池：使用 0.5C 充电，充电电流为 16000mAh×0.5=8000mA=8A。根据公式：充电时间=电池容量/充电电流，所以充电时间为 16000mAh/8000mA=2 小时。 22000mAh 电池：使用 0.5C 充电，充电电流为 22000mAh×0.5=11000mA=11A。根据公式：充电时间=电池容量/充电电流，所以充电时间为 22000mAh/11000mA=2 小时。 因此，16000mAh 和 22000mAh 的电池都用 0.5C 充电，从空点到满电，分别需要 2 小时充满。" },
  { id: 1524, cat: "综合问答", q: "当你在地面调试飞机，发现你推前进（俯仰）时，飞机的反应和你打杆的方向是相反 的，请问你应该在遥控器上的哪个设置里面调整？（）", opts: ["FUNCTION", "REVERSE", "SERVO"], ans: 1, exp: "当在地面调试飞机时，如果发现推前进（俯仰）时飞机的反应与打杆方向相反，应该 在遥控器的 REVERSE 菜单中进行调整。" },
  { id: 1525, cat: "综合问答", q: "你手头有一块 6000mAh 的电池，用一个标准充电电流 3A 的充电器充电，理论上电池多长时间能够充满，那么它是多少 C 充电的呢？（）", opts: ["2h，0.5C", "1h，1C", "0.5h，2C"], ans: 0, exp: "充电时间：根据公式，充电时间=电池容量/充电电流。所以，6000mAh/3000mA=2 小 时。充电倍率：充电倍率 C 是指充电电流与电池容量的比值。所以，3000mA/6000mAh=0.5C。" },
  { id: 1526, cat: "综合问答", q: "你在外场飞行时飞机（四轴）的一个螺旋桨损坏，你发现它周边的桨叶为 15*5CW 桨，这时你手头有 15*5CW 桨、14*4.8CCW 桨、21*5CCW 三支桨，你最好更换哪一支桨？（）", opts: ["21*5CCW", "14*4.8CCW", "15*5CW"], ans: 1, exp: "更换原则： 旋转方向必须匹配（四轴飞行器必须保持 CW/CCW 交替对称，否则会导致扭矩失衡）。 尺寸尽量接近（直径和螺距差异过大会影响动力平衡）。 应急情况下可调整电机转向（若无法匹配旋转方向，可通过飞控软件反转电机）。 因此，14×4.8CCW 尺寸最接近（直径小 6.7%，螺距小 4%），动力影响较小。旋转方向不同，但可通过反转电机转向适配，是最佳应急选择。" },
  { id: 1527, cat: "综合问答", q: "如果在机场中只有一条跑道，其跑道使用方向应保证航空器能够（）", opts: ["逆风起降", "侧风起降", "顺风起降"], ans: 0, exp: "跑道方向应优先保障逆风起降。逆风起降可以增加飞机的升力，使离地速度或着陆速 度减少，从而缩短起飞或着陆的滑跑距离。同时，逆风起降也有利于飞机运动中的方向稳定 性和操纵性，避免因强劲侧风而发生倾斜。 其他选项分析如下： 1、顺风起降：顺风使飞机与空气相对速度减小，升力不足，起飞滑跑距离长，降落易冲 出跑道，不符合要求。 2、侧风起降：侧风致飞机偏离跑道中心线，虽可修正，但跑道设计不会以此为基本准则，是极端时的被动选择。 综上，机场单跑道方向优先满足逆风条件，能够提高飞行安全性和效率。" },
  { id: 1528, cat: "综合问答", q: "（）定义为：在跑道中线，航空器上的飞行员能看到跑道面上的标志或跑道边界灯或 中线灯的距离。", opts: ["跑道视宽", "跑道视程", "跑道视距"], ans: 1, exp: "跑道视程（Runway VisualRange,RVR）是指在跑道中线，航空器上的飞行员能看到跑 道面上的标志或跑道边界灯或中线灯的距离。" },
  { id: 1529, cat: "综合问答", q: "提高夜间视力的一种方法是（）", opts: ["提高座舱内部的照明强度", "眼睛偏离物体中心 5-10 度做缓慢扫视", "直视物体"], ans: 1, exp: "夜间视力较差时，可以尝试以下方法来提高视觉效果：1、偏离中心扫视：将眼睛偏离物体中心 5-10 度，进行缓慢扫视。 2、利用视杆细胞：通过这种方式，使物体投射在视网膜的中央周缘区域，充分发挥视杆细胞 的夜视功能。" },
  { id: 1530, cat: "综合问答", q: "酒精对睡眠的影响是（）？", opts: ["促进作用", "对快波睡眠具有强烈抑制作用", "延长睡眠时间，加深睡眠深度"], ans: 1, exp: "酒精对睡眠的影响是对快波睡眠具有强烈抑制作用：1、破坏睡眠结构：酒精会减少深度睡眠（慢波睡眠）和 REM 睡眠（与记忆、情绪调节相关），导 致夜间频繁醒来或早醒。 2、短期麻痹效应：酒精通过抑制中枢神经系统使人犯困，但这种作用随身体耐受性增强而减 弱，可能导致“越喝越难睡”的恶性循环。" },
  { id: 1531, cat: "综合问答", q: "飞行中的夜间盲点是指（）？", opts: ["视神经出入视网膜处", "晶状体的功能性障碍", "视网膜的中央凹"], ans: 2, exp: "夜间盲点是指在低光照条件下，视网膜中央凹（黄斑区）对光线的敏感度下降，导致飞 行员在夜间飞行时难以看清正前方的物体。这是因为中央凹主要由视锥细胞组成，而视锥细 胞在低光照条件下功能较差。" },
  { id: 1532, cat: "综合问答", q: "以下关于视网膜上视细胞功能特点的描述哪一项是正确的？（）", opts: ["视锥细胞具有感受色光，明光和分辨物体细节的能力", "视杆细胞具有感受色光，明光和分辨物体细节的能力", "视杆细胞不但具有夜视功能，而且还具有远视功能"], ans: 0, exp: "感光细胞分为视锥细胞和视杆细胞。视锥细胞主要分布在视网膜中央凹，数量密集，而在周边区域较少。它们的功能是感受白昼光和色光，对光的敏感度较低，但具有分辨颜色 的能力。视杆细胞则主要分布在视网膜周边部，中央凹处几乎没有。它们的功能是感知弱光，使人眼能够察觉到光线的存在，但无法分辨颜色。" },
  { id: 1533, cat: "综合问答", q: "航空器在飞行中，若需改变高度层时，通常情况下机长应.（）？", opts: ["决定后立即改变", "主动与空军管制部门联系，经其同意后方可改变", "经有关空管部门许可后方可改变"], ans: 2, exp: "根据《飞行基本规则》的规定，航空器在飞行中，若需改变高度层时，机长应经有关 空管部门许可后方可改变。" },
  { id: 1534, cat: "综合问答", q: "以下关于酒精对人体影响的陈述哪一项？（）", opts: ["酒精使飞行员对缺氧的易患性增强", "少量的酒精不会损害飞行技术", "咖啡有助于酒精新陈代谢，并减轻由过量饮酒产生的连续效应"], ans: 0, exp: "酒精会抑制中枢神经系统，使人体对氧气的利用效率降低。飞行员在高空飞行时，本 身就处于相对缺氧的环境，酒精的作用会进一步削弱其对缺氧的耐受能力，增加缺氧的风险。 例如，酒精会使飞行员的反应时间延长，判断能力下降，容易在缺氧状态下出现意识模糊或 操作失误。" },
  { id: 1535, cat: "综合问答", q: "过长时间的凝视物体会使（）", opts: ["物象逐渐变暗淡", "物象逐渐变清晰", "出现幻觉"], ans: 0, exp: "长时间凝视一个物体时，人眼的视觉感受器（视锥细胞和视杆细胞）会因持续受到相 同刺激而逐渐疲劳，导致传入大脑的信号减弱，从而使物体看起来逐渐变得暗淡。这种现象 称为“视觉疲劳”或“视觉适应”。" },
  { id: 1536, cat: "综合问答", q: "闪光性眩晕是指（）", opts: ["每秒 4-20 次的闪烁光所引起的眩晕、恶心以及痉挛等现象", "由晕机病引起的眩晕、恶心以及呕吐现象", "由于贫血所引起的头晕、恶心以及晕厥等现象"], ans: 0, exp: "闪光性眩晕是指由于特定频率的闪烁光线（通常每秒 4-20 次）刺激眼睛，引发的眩 晕、恶心以及肌肉痉挛等现象。这种现象与大脑对光刺激的过度反应有关。" },
  // ==================== 直升机综合 ====================
  { id: 1537, cat: "直升机综合", q: "单旋翼带尾桨式无人直升机旋翼的旋转方向（）", opts: ["俯视顺时针", "俯视逆时针", "均有"], ans: 2, exp: "单旋翼带尾桨式无人直升机的旋翼旋转方向既有俯视顺时针的，也有俯视逆时针的，具体的旋转方向取决于不同的设计和制造商。这种设计的多样性使得在实际应用中需要根据 具体的机型来确定旋翼的旋转方向。" },
  { id: 1538, cat: "直升机综合", q: "地面效应对飞行性能的影响不包括（）", opts: ["保持拉力不变的条件下所需要的功率减小", "直升机有地效悬停升限小于无地效悬停的升限", "在保持功率不变的条件下拉力要增加"], ans: 0, exp: "地面效应会使飞机在接近地面飞行时受到地面的影响，产生一些变化。地面效应会使 在保持功率不变的条件下拉力增加，同时直升机有地效悬停升限大于无地效悬停升限，而不 是选项中所说的小于。因此选项保持拉力不变的条件下所需功率减小并不是地面效应对飞行 性能的影响。" },
  { id: 1539, cat: "直升机综合", q: "地面效应对直升机飞行性能的影响说法不正确的是（）", opts: ["直升机有地效悬停升限小于无地效悬停升限", "在保持功率不变的条件下拉力会增加", "在保持拉力不变的条件下所需功率减小"], ans: 0, exp: "地面效应会对直升机飞行性能产生多方面影响。 在地面效应作用下，在保持功率不变的条件下，由于空气被压缩等原因，拉力会增加；同时 在保持拉力不变的条件下，所需功率减小。而直升机有地效悬停升限是大于无地效悬停升限 的，此，选项“直升机有地效悬停升限小于无地效悬停升限”是不正确的说法。" },
  { id: 1540, cat: "直升机综合", q: "俄罗斯研制的单旋翼直升机的旋翼旋转方向一般为（）", opts: ["俯视顺时针旋翼", "俯视逆时针旋翼", "没有规律"], ans: 0, exp: "俄罗斯研制的单旋翼直升机通常采用俯视顺时针旋翼的设计。这可能与俄罗斯在直升 机设计方面的传统和技术选择有关。了解不同国家直升机旋翼旋转方向的特点有助于更好地 识别和理解不同类型的直升机。" },
  { id: 1541, cat: "直升机综合", q: "改变旋翼拉力大小的方法不包括（）", opts: ["操纵总距杆", "操纵油门环", "操纵方向舵"], ans: 2, exp: "改变旋翼拉力大小的方法主要包括操纵总距杆和操纵油门环。操纵总距杆可以改变旋 翼的桨距角，从而改变旋翼的拉力；操纵油门环可以改变发动机的功率输出，进而影响旋翼 的拉力。而操纵方向舵主要用于改变飞机的航向，并不直接影响旋翼拉力的大小。" },
  { id: 1542, cat: "直升机综合", q: "高度超过（）米后，没有地面效应的影响", opts: ["20", "25", "30"], ans: 0, exp: "一般来说，当高度超过 20 米后，直升机基本就没有地面效应的影响了。地面效应是 由于直升机接近地面时，地面影响空气流动而产生的一种效应，在一定高度范围内对直升机 的性能有影响，超过特定高度后该效应消失。" },
  { id: 1543, cat: "直升机综合", q: "共轴式无人直升机的航向操纵系统方案不包括（）", opts: ["半差动操纵方案", "全差动操纵方案", "周期变距操纵方案"], ans: 2, exp: "共轴式无人直升机的航向操纵系统主要有半差动操纵方案和全差动操纵方案。而周期 变距操纵主要是用来控制直升机的俯仰、滚转和前后左右运动，不是用于航向操纵。" },
  { id: 1544, cat: "直升机综合", q: "共轴式直升机的航向操纵是如何实现的？（）", opts: ["通过操纵上下旋翼的自动倾斜器", "通过分别改变上下旋翼的总距", "通过自动倾斜器和总距的联合操纵"], ans: 1, exp: "共轴式直升机的航向操纵是通过分别改变上下旋翼的总距来实现的。改变上下旋翼总 距会使上下旋翼的拉力产生差异，从而产生使直升机转向的力矩，实现航向操纵。操纵上下 旋翼的自动倾斜器主要是用来控制直升机的俯仰和滚转运动。自动倾斜器和总距的联合操纵 一般不适用于共轴式直升机的航向操纵。" },
  { id: 1545, cat: "直升机综合", q: "共轴式直升机的纵横向操纵是操纵何处得以实现的？（）", opts: ["下旋翼自动倾斜器的不动环", "下旋翼自动倾斜器的可动环", "上旋翼自动倾斜器的可动环"], ans: 0, exp: "共轴式直升机的废阻面积（即直升机不产生升力的面积）一般大于单旋翼直升机，这 是因为共轴式直升机需要在其两副旋翼之间保持一定的距离以确保操作系统的正常工作。这 种设计要求是为了使得两副旋翼可以独立或同时变化桨距角，实现直升机的垂直起降、前后 左右移动等控制，而这样的机械结构导致了共轴式直升机的废阻面积相对较大。" },
  { id: 1546, cat: "直升机综合", q: "共轴式直升机废阻面积一般大于单旋翼直升机，这是因为（）", opts: ["共轴式直升机的纵向尺寸较大", "结构重量与载重均集中在重心附近", "其特殊的操作系统要求两旋翼之间保持一定的距离"], ans: 2, exp: "共轴式直升机的废阻面积（即直升机不产生升力的面积）一般大于单旋翼直升机，这 是因为共轴式直升机需要在其两副旋翼之间保持一定的距离以确保操作系统的正常工作。这 种设计要求是为了使得两副旋翼可以独立或同时变化桨距角，实现直升机的垂直起降、前后 左右移动等控制，而这样的机械结构导致了共轴式直升机的废阻面积相对较大。" },
  { id: 1547, cat: "直升机综合", q: "共轴式直升机的旋翼旋转方向为（）", opts: ["一正一逆", "俯视顺时针旋翼", "俯视逆时针旋翼"], ans: 0, exp: "共轴直升机的旋翼旋转方向为一正一逆，即上下两副旋翼绕同一理论轴线旋转，但是 旋转方向相反。这样的设计可以使得两副旋翼产生的扭矩相互平衡，从而减少或消除直升机 的航向稳定性问题，同时也省去了尾桨的需要。" },
  { id: 1548, cat: "直升机综合", q: "共轴直升机上下旋翼的自动倾斜器有何位置关系？（）", opts: ["上旋翼自动倾斜器领先下旋翼自动倾斜器 90 度", "下旋翼自动倾斜器领先上旋翼自动倾斜器 90 度", "上下旋翼自动倾斜器始终保持平行"], ans: 2, exp: "在共轴直升机中，上下旋翼的自动倾斜器始终保持平行。这是因为共轴直升机的设计 特点决定了上下旋翼需要协同工作，保持自动倾斜器平行可以确保在操纵过程中上下旋翼的 桨叶角度变化同步，从而实现稳定的飞行控制。如果自动倾斜器不保持平行，会导致上下旋 翼的作用力不协调，影响直升机的飞行性能和稳定性。" },
  { id: 1549, cat: "直升机综合", q: "关于摆振运动说法正确的是（）", opts: ["桨叶绕垂直铰的前后摆动，就称为桨叶的摆振运动", "桨叶上挥时，哥氏力欲使桨叶加速旋转，桨叶可绕垂直铰向后摆动一个角度", "桨叶下挥时，哥氏力欲使桨叶减速旋转，桨叶可绕垂直铰向前摆动一个角度"], ans: 0, exp: "摆振运动是指桨叶在旋转过程中，由于科氏力的作用，桨叶会绕垂直铰（摆振铰）进 行前后摆动的现象。这种运动有助于缓解科氏力对桨叶的影响，减少桨叶的疲劳损伤，并改 善直升机的飞行性能。" },
  { id: 1550, cat: "直升机综合", q: "关于桨叶的剖面形状说法错误的是（）", opts: ["桨叶的剖面形状称为桨叶翼型", "桨叶翼型常见的有平凸型、双凸型和非对称型", "一般用相对厚度、最大厚度位置、相对弯度、最大弯度位置等参数来说明桨叶翼型"], ans: 1, exp: "桨叶的剖面形状称为桨叶翼型，一般用相对厚度、最大厚度位置、相对弯度、最大弯 度位置等参数来说明桨叶翼型。桨叶翼型常见的有平凸型、双凸型和对称型，而非对称型。" },
  { id: 1551, cat: "直升机综合", q: "关于无地效垂直起飞正确的是（）", opts: ["风起飞，旋翼相对气流速度增大，单位时间内流过旋翼的空气质量增加，旋翼产生的拉 力小，则起飞载重量减小", "顺风起飞，为了避免尾桨打地，悬停高度较高，地面效应减弱，所以载重量将增大", "起飞场地的标高高、气温高，则空气密度小，发动机功率降低，同时，单位时间内流过 旋翼的空气质量减小，旋翼效能降低。因此，起飞最大载重量要减小"], ans: 2, exp: "在高标高和高气温的条件下，空气密度会降低，导致发动机的进气量减少，发动机功 率下降。同时，空气密度的减小也意味着单位时间内流过旋翼的空气质量减少，这会降低旋 翼的效能，进而影响到直升机的起飞载重量。" },
  { id: 1552, cat: "直升机综合", q: "关于无地效垂直下降正确的是（）", opts: ["在离地 0.5 米以下，应以不大于 0.25 米/秒的下降率下降接地", "在离地 1 米以下，应以不大于 0.5 米/秒的下降率下降接地", "在离地 1.5 米以下，应以不大于 0.25 米/秒的下降率下降接地"], ans: 0, exp: "无地效垂直下降时需要确保安全平稳接地。如果下降率过大，可能会对无人机造成损 伤。在离地 0.5 米以下，以不大于 0.25 米/秒的下降率下降接地，这个距离较近，下降率较 小，能最大程度保证无人机安全平稳地接地。" },
  { id: 1553, cat: "直升机综合", q: "关于旋翼的反扭矩说法正确的是（）", opts: ["旋翼的反扭矩会迫使直升机向旋翼旋转的反方向偏转", "旋翼反扭矩的大小取决于发动机输入功率的大小", "发动机带动旋翼旋转时，旋翼诱导阻力力矩发动机传递给旋翼轴的扭矩所平衡"], ans: 0, exp: "当直升机的旋翼旋转时，由于牛顿第三定律，即作用力和反作用力的原理，会产生反 扭矩。这个反扭矩会使直升机机身向旋翼旋转的反方向偏转。" },
  { id: 1554, cat: "直升机综合", q: "关于旋翼桨穀的说法正确的是（）", opts: ["毂在承受由桨叶传来的很大离心力的同时，在挥舞面及摆振面都要承受较小的交变载荷", "桨毂的各个铰都必须带有轴承，轴承的工作条件良好", "桨穀将传递和承受旋翼的拉力、离心力及挥舞、摆振、变距的交变力矩"], ans: 2, exp: "旋翼桨毂是连接旋翼桨叶和直升机或无人机发动机的重要部件。它不仅要承受由桨叶 传来的离心力，还要传递和承受旋翼的拉力、挥舞、摆振、变距的交变力矩。桨毂的设计必 须能够承受这些力和力矩，以确保旋翼系统的稳定和可靠运行。因此，选项“桨毂将传递和 承受旋翼的拉力、离心力及挥舞、摆振、变距的交变力矩”是正确的描述。" },
  { id: 1555, cat: "直升机综合", q: "关于直升机如何实现俯仰和滚转，以下正确的是（）", opts: ["自动倾斜器运动，通过周期变距实现主旋翼在旋转面不同位置拉力不同，实现俯仰与滚 转", "自动倾斜器运动，通过周期变距实现主旋翼在旋转面不同位置阻力不同，实现俯仰与滚 转", "自动倾斜器运动，通过周期变距实现主旋翼在桨盘前后左右桨距的不同，进而形成一个 圆面上前后左右升力的不同，实现俯仰与滚转操纵"], ans: 2, exp: "直升机的自动倾斜器运动，通过周期变距来改变主旋翼在桨盘前后左右的桨距，使得 在一个圆面上前后左右的升力不同。例如，向前倾斜时，后面桨叶升力增大，前面桨叶升力 减小，从而实现俯仰；向一侧倾斜时，一侧桨叶升力增大，另一侧桨叶升力减小，实现滚转 操纵。" },
  { id: 1556, cat: "直升机综合", q: "关于直升机贴地飞行正确的是（）", opts: ["直升机近地飞行时，飞行高度约为 5-10 米，飞行速度通常不大于 10 公里/小时", "直升机近地飞行时，飞行高度约为 1-10 米，飞行速度通常不大于 10 公里/小时", "直升机近地飞行时，飞行高度约为 1-10 米，飞行速度通常不大于 20 公里/小时"], ans: 2, exp: "直升机在进行贴地飞行时，通常是指在非常接近地面的高度上进行的飞行，这种飞行 方式可以用于隐蔽接近目标或避开敌方雷达探测。直升机在进行贴地飞行时，飞行高度一般 不超过 10 米，飞行速度通常不大于 20 公里/小时。这种飞行方式对飞行员的操作技能要求 较高，因为需要时刻准确判断直升机与地面之间的距离，并及时改变飞行高度与速度。" },
  { id: 1557, cat: "直升机综合", q: "关于自动倾斜器说法错误的是（）", opts: ["旋翼的总距和周期变距操纵都是靠自动倾斜器来完成", "直升机旋翼的挥舞控制机构称自动倾斜器", "动倾斜器由内轴、外轴、导筒、内环、外环、旋转环、操纵摇臂、变距拉杆等组成"], ans: 2, exp: "1.自动倾斜器确实是用来完成旋翼的总距和周期变距操纵的，通过自动倾斜器的运动 可以改变旋翼桨叶的角度，从而实现不同的飞行状态控制。 2.直升机旋翼的挥舞控制机构就是自动倾斜器，它在直升机的飞行控制中起着关键作用。 3.选项中对自动倾斜器的组成描述不准确，自动倾斜器主要由不旋转环、旋转环、变距拉杆 等组成，题干中的内轴、外轴、导筒等不是自动倾斜器的典型组成部分。" },
  { id: 1558, cat: "直升机综合", q: "挥舞运动指的是（）", opts: ["桨叶绕水平铰可以上下活动", "桨叶绕垂直饺可以前后活动", "桨叶轴向饺的转动"], ans: 0, exp: "挥舞运动是指直升机桨叶在旋转过程中，由于气动力、离心力、惯性力等作用而上下 偏离构造旋转平面的运动。桨叶与构造旋转平面之间夹角称为挥舞角，以向上为正。" },
  { id: 1559, cat: "直升机综合", q: "桨叶“上反效应”引起锥体向方位侧倒（）", opts: ["0°", "90°", "180°"], ans: 1, exp: "桨叶的“上反效应”会导致旋翼锥体向 90°方位侧倒。这是因为在飞行中，桨叶的 上反效应会产生一个扭矩，使得旋翼锥体向一侧倾倒，通常这个角度大约是 90 度。" },
  { id: 1560, cat: "直升机综合", q: "桨叶的挥舞调节作用使旋翼锥体方向侧倒（）", opts: ["90°", "180°", "270°"], ans: 2, exp: "桨叶的挥舞调节作用使旋翼锥体向方位侧倒的正确角度是：270°。这是因为桨叶在 挥舞运动中，由于前行侧和后行侧的相对气流速度不同，导致桨叶在不同方位的挥舞角度不 同，进而使得旋翼锥体向方位侧倒 270°。" },
  { id: 1561, cat: "直升机综合", q: "铰接式旋翼在吹风挥舞时，旋翼每转一周，桨叶挥舞速度和挥舞角分别出现一次周期性 变化。下面正确的是（）", opts: ["舞角的变化比挥舞速度的变化滞后 90 度", "桨叶在 90 度方位下挥速度最大，在 270 度方位上挥速度最大", "桨叶在 180 度方位挥舞最低，在 360 度方位挥舞最高"], ans: 0, exp: "铰接式旋翼在吹风挥舞时，由于空气动力等因素的影响，桨叶每转一周，挥舞速度和 挥舞角会出现周期性变化。挥舞角的变化比挥舞速度的变化滞后 90 度，这是由于空气动力 作用的时间先后以及桨叶运动的特性所决定的。" },
  { id: 1562, cat: "直升机综合", q: "近地飞行特点正确的是（）", opts: ["直升机在自转着陆时，地面效应可以减小垂直着陆速度。此外，地面效应能增加直升机 的稳定性", "近地飞行时，如果遇到突然下凹的地形，地面效应迅速消失，会引起旋翼拉力突然增大，直升机就有掉入凹坑的危险", "直升机近地飞行时，飞行高度一般都在 10 米以下，大于旋翼直径"], ans: 0, exp: "地面效应（GroundEffect）是指飞行器在接近地面时，由于地面的阻碍作用，气流流 经飞行器下方时受到压缩，导致飞行器下方的气压增加，从而产生额外的升力。这种现象在 直升机自转着陆时尤为明显，可以有效地减小直升机的垂直着陆速度，提高着陆的安全性。 同时，地面效应还能增加直升机的稳定性，因为它减少了旋翼的诱导阻力。" },
  { id: 1563, cat: "直升机综合", q: "美国研制的单旋翼直升机的旋翼旋转方向一般为（）", opts: ["俯视顺时针旋翼", "俯视逆时针旋翼", "没有规律"], ans: 1, exp: "美国研制的单旋翼直升机通常采用俯视逆时针旋翼旋转方向设计。这主要是基于其在 空气动力学、机械结构设计以及操纵特性等方面的综合考虑和长期的技术发展传统。" },
  { id: 1564, cat: "直升机综合", q: "爬升的注意事项（）", opts: ["飞行员不应以垂直上升作为主要的飞行方式", "垂直上升中，保持直升机状态比较容易", "要进入回避区"], ans: 0, exp: "飞行员不应以垂直上升作为主要的飞行方式是正确的。因为垂直上升需要消耗大量的 功率，并且直升机在垂直上升状态下稳定性较差，操纵难度大，也不利于观察周围环境和保 持安全。" },
  { id: 1565, cat: "直升机综合", q: "平飞可用燃油量与所装总燃油量有关，然而，每次飞行，所装总燃油量并不完全一样，也不可能完全用于平飞。起飞前发动机地面工作、离地并增速爬升至预定高度、下滑着陆等，都要消耗燃油。还要扣除存留在油箱和管道中的不可用油量，还要留出（）的备份燃油量，以备特殊情况的需要。", opts: ["5%-10%", "10%-15%", "5%-15%"], ans: 1, exp: "在计算总燃油量时，需要考虑到平飞使用的燃油量，并且要预留 10%-15%的燃油作为 备份，以应对可能的紧急情况。这个比例是根据航空业的通用安全标准和实践得出的，它确 保了即使在最坏情况下，飞行器也能安全着陆或到达备降机场。" },
  { id: 1566, cat: "直升机综合", q: "如果采用并列式双驾驶员座舱，并指定左座为机长位置，则旋翼的旋转方向（）", opts: ["采用俯视顺时针旋翼好一些", "采用俯视逆时针旋翼好一些", "没有区别"], ans: 0, exp: "如果采用并列式双驾驶员座舱，并指定左座为机长位置，采用俯视顺时针旋翼好一些。 这是因为从机长的视角和操作习惯考虑，当旋翼为顺时针旋转时，机长在左座能更好地观察 前方及周围情况，同时在进行一些操作时也更为便利。" },
  { id: 1567, cat: "直升机综合", q: "上下旋翼的自动倾斜器有何位置关系？（）", opts: ["上旋翼自动倾斜器领先下旋翼自动倾斜器 90 度", "下旋翼自动倾斜器领先上旋翼自动倾斜器 90 度", "上下旋翼自动倾斜器始终保持平行"], ans: 2, exp: "在共轴式直升机中，上下旋翼的自动倾斜器（也称为旋翼倾斜盘或倾斜器）是相互连 接的，它们始终保持平行。这是因为共轴式直升机的设计要求上下旋翼的旋转平面在任何时 刻都保持相同的倾斜角度，以实现直升机的纵、横向操纵。自动倾斜器的作用是改变旋翼桨 叶的桨距角，从而控制直升机的姿态，而上下旋翼自动倾斜器的平行关系确保了直升机的对 称性和平衡性。" },
  { id: 1568, cat: "直升机综合", q: "四轴飞行器如何实现控制？（）", opts: ["通过调整不同旋翼之间的总距", "通过调整不同旋翼之间相对转速", "通过调整不同旋翼之间倾斜角度"], ans: 1, exp: "四轴飞行器的控制主要是通过调整不同旋翼之间的相对转速来实现的。每个旋翼的转 速变化会影响飞行器的升力和推力，从而实现对飞行器的俯仰、滚转和偏航控制。" },
  { id: 1569, cat: "直升机综合", q: "推式尾桨和拉式尾桨哪个效率更高？（）", opts: ["推式尾桨", "拉式尾桨", "若其他参数没有区别则没有区别"], ans: 0, exp: "推式尾桨的效率通常更高。推式尾桨在工作时，气流相对比较顺畅，受到主旋翼下洗 气流的影响较小，能够更有效地产生侧向力来平衡主旋翼的反扭力，从而提高了效率。而拉 式尾桨容易受到主旋翼下洗气流的干扰，效率相对较低。" },
  { id: 1570, cat: "直升机综合", q: "尾桨的功能是（）", opts: ["在单旋翼直升机上，尾桨主要功能是提供纵向稳定性", "在单旋翼直升机上，能对直升机航向起到操纵和稳定作用", "在单旋翼直升机上，尾桨主要功能是提供升力"], ans: 1, exp: "尾桨在单旋翼直升机上的功能是对直升机航向起到操纵和稳定作用。尾桨产生的推力 或拉力可以抵消主旋翼旋转产生的反扭矩，从而使直升机保持航向稳定，并允许飞行员进行 航向操纵。" },
  { id: 1571, cat: "直升机综合", q: "为了解决大速度下空气压缩性的影响和噪音问题，可以对桨叶进行何种处理？（）", opts: ["把桨叶尖部作成后掠形", "采用矩形桨叶", "采用尖削桨叶"], ans: 0, exp: "为了解决大速度下空气压缩性的影响和噪音问题，可以对桨叶进行的处理是把桨叶尖 部做成后掠形。这种设计可以减少桨尖处的气流速度，从而降低由于超音速气流产生的激波 和噪音，同时也有助于提高桨叶的气动效率。" },
  { id: 1572, cat: "直升机综合", q: "无人直升机遥控状态下动力失效最恰当的处置方式是？（）", opts: ["势能转换动能，打负总螺距使旋翼高速下降，在离地面数米高时，将总距变最大，迅速 制止快速下沉，缓慢着陆", "无法安全降落，让其降落在人员稀少的地方", "开启降落伞"], ans: 0, exp: "在无人直升机遥控状态下动力失效时，选择势能换动能，打负总螺距使旋翼高速下降，在离地面数米高时，将总距变最大，这样可以迅速制止快速下沉，实现缓慢着陆。这是因为 通过这种方式可以利用直升机的势能转化为动能，在接近地面时增加升力以实现较为安全的 着陆。" },
  { id: 1573, cat: "直升机综合", q: "下降的注意事项，错误的是（）", opts: ["要严格防止下降率过大", "飞行员应把垂直下降作为主要飞行方式", "在海上或低能见度条件下作垂直下降，操纵要格外谨慎"], ans: 1, exp: "垂直下降不是主要飞行方式，因为垂直下降存在较大风险，如下降率难以控制、可能 遭遇下沉气流等。要严格防止下降率过大以确保安全下降；在海上或低能见度条件下作垂直 下降，由于缺乏明显参照物且环境复杂，操纵要格外谨慎。" },
  { id: 1574, cat: "直升机综合", q: "下列关于共轴双旋翼直升机旋翼的说法正确的是（）", opts: ["旋翼只起升力面的作用", "旋翼只充当纵横向和航向的操纵面", "旋翼既是升力面又是纵横向和航向的操纵面"], ans: 2, exp: "共轴双旋翼直升机的旋翼不仅起到产生升力的作用，同时通过改变上下旋翼的总距、周期变距等方式可以实现对直升机纵横向和航向的操纵。所以旋翼既是升力面又是纵横向和 航向的操纵面。" },
  { id: 1575, cat: "直升机综合", q: "下列关于尾桨的安装低可能带来的好处的说法，错误的是（）", opts: ["有助于提高尾桨效率", "有助于减轻结构重量", "有助于减小传动系统的复杂性"], ans: 0, exp: "尾桨安装位置低并不能有助于提高尾桨效率。尾桨安装位置低可能会使结构设计相对 更简单，从而有助于减轻结构重量，并且在一定程度上可能会使传动系统的布局更容易，有 助于减小传动系统的复杂性。" },
  { id: 1576, cat: "直升机综合", q: "下列关于尾桨的安装位置高可能带来的好处的说法，错误的是（）", opts: ["有助于提高尾桨效率", "有助于减小传动系统的复杂性", "有助于提高前飞的稳定性"], ans: 1, exp: "关于尾桨的安装位置高可能带来的好处，正确的观点包括有助于提高尾桨效率和有助 于提高前飞的稳定性。然而，尾桨安装位置高并不一定有助于减小传动系统的复杂性。实际 上，尾桨安装位置高可能会增加传动系统的复杂性，因为需要更长的传动轴和更多的传动部 件来将动力传递到较高的位置。因此，选项“有助于减小传动系统的复杂性”是错误的。" },
  { id: 1577, cat: "直升机综合", q: "下列关于旋翼直径过啊可能带来的坏处的说法，错误的是（）", opts: ["直升机重量增加", "使直升机在丛林等复杂地貌条件机动能力差", "增大旋翼诱阻功率"], ans: 2, exp: "旋翼直径过大并不会直接导致增大旋翼诱阻功率。旋翼的诱阻功率主要与旋翼的面积 和飞行速度有关，而与旋翼直径的大小没有直接关系。相反，大直径旋翼可以有效地提高旋 翼拉力，因为旋翼拉力同旋翼半径的四次方成正比，旋翼直径大，则旋翼的桨盘载荷小，这 样可以有效地降低旋翼诱阻功率。" },
  { id: 1578, cat: "直升机综合", q: "下列哪种尾桨旋转方向效率较高？（）", opts: ["底部向前的旋转方向", "顶部向前的旋转方向", "旋转方向对效率没有影响"], ans: 0, exp: "尾桨的旋转方向对其效率有显著影响。根据搜索结果，底部向前的旋转方向（即推式 尾桨）效率较高。这是因为推式尾桨推动的气流不会受到尾撑的阻挡，气流损失动量小，因 此效率更高。此外，从气动干扰的角度来看，尾桨采用底部向前的旋转方向较为有利，可以 减弱旋翼与尾桨之间的气动干扰，从而提高尾桨效率。" },
  { id: 1579, cat: "直升机综合", q: "下列哪种形式的旋翼飞行器不是直升机？（）", opts: ["单旋翼带尾桨式", "共轴式双旋翼", "自传旋翼式"], ans: 2, exp: "单旋翼带尾桨式和共轴双旋翼式都是典型的直升机构型，通过发动机驱动旋翼产生升 力和控制飞行。而自转旋翼式飞行器通常是依靠前进时气流吹动旋翼自转产生升力，其动力 系统不直接驱动旋翼旋转，与直升机的工作原理不同。" },
  { id: 1580, cat: "直升机综合", q: "下列说法错误的是（没有提到的条件则视为相同）？（）", opts: ["旋翼直径越大则拉力越大", "旋翼直径越大则悬停诱导速度越大", "旋翼直径越大则桨盘载荷越小"], ans: 1, exp: "旋翼直径的大小对直升机的性能有重要影响。 1、旋翼直径越大则拉力越大。这是正确的，因为旋翼的拉力与其面积成正比，而旋翼面积 与直径的平方成正比，所以直径越大，拉力越大。 2、旋翼直径越大则悬停诱导速度越大。这是错误的，实际上，旋翼直径越大，悬停诱导速 度会越小。因为悬停诱导速度与旋翼产生的升力以及旋翼面积有关，旋翼直径越大，相同的 升力需要更小的诱导速度来维持平衡。 3、旋翼直径越大则桨盘载荷越小。这是正确的，桨盘载荷定义为旋翼的拉力与旋翼桨盘面 积之比，旋翼直径越大，桨盘面积越大，在相同的拉力下，桨盘载荷越小。" },
  { id: 1581, cat: "直升机综合", q: "下列著名直升机，采用共轴双旋翼布局的是（）", opts: ["阿帕奇", "Ka-50", "海豚"], ans: 1, exp: "Ka-50 武装直升机采用共轴双旋翼布局，这种布局使得直升机具有结构紧凑、机动性 强等特点。而“阿帕奇”即 AH-64 武装直升机为单旋翼带尾桨布局；“海豚”即 SA365/EC155 直升机也是单旋翼带尾桨布局。" },
  { id: 1582, cat: "直升机综合", q: "下面关于桨叶的挥舞调节说法正确的是（）", opts: ["桨叶角的大小随桨叶挥舞角的改变而变化的这一特点，称为桨叶的上反效应", "直升机的旋翼的桨叶上挥时，变距拉杆拉住变距摇臂使桨叶角增大", "直升机的旋翼的桨叶下挥时，变距拉杆顶住变距摇臂使桨叶角增大"], ans: 2, exp: "直升机的旋翼的桨叶下挥时，变距拉杆顶住变距摇臂使桨叶角增大。这是因为在直升 机旋翼系统中，桨叶的挥舞运动是由桨叶的挥舞铰和挥舞调节机构控制的。当桨叶下挥时，由于挥舞铰的作用，桨叶的攻角（桨叶角）会增大，以保持桨叶产生的升力与飞行速度和姿 态变化相匹配。" },
  { id: 1583, cat: "直升机综合", q: "下面关于盘旋错误的是（）", opts: ["飞行速度达到盘旋速度时（通常取 200 公里/小时），应协调一致地向盘旋方向压杆、蹬 舵", "在盘旋中保持好高度有助于保持盘旋速度，若高度升高，为了保持等高就要向前顶杆，这样就会使速度增大", "改出盘旋，首先要消除向心力，故应向盘旋方向压杆，减小坡度，使旋翼拉力的水平分 力减小"], ans: 2, exp: "盘旋是直升机或飞机在一定高度上绕着一个点或轴进行圆周运动的飞行动作。在盘旋 过程中，保持正确的飞行速度和高度是至关重要的。 1.在飞行速度达到盘旋速度时，飞行员需要协调一致地向盘旋方向压杆、蹬舵，以保持飞机 的坡度和航向，实现稳定的盘旋。该选项正确。 2.在盘旋中保持好高度有助于保持盘旋速度。 如果高度升高，为了保持等高盘旋，飞行员需要向前顶杆，增加迎角，这通常会使得速度增 大，因为飞机需要更多的升力来抵消高度的增加。该选项正确。 3.改出盘旋时，正确的操作是向盘旋的反方向压杆，以减小坡度，从而减少旋翼拉力的水平 分力，使飞机逐渐退出盘旋状态。而不是向盘旋方向压杆。该选项错误。" },
  { id: 1584, cat: "直升机综合", q: "下面关于悬停操纵说法错误的是（）", opts: ["停时的姿态是各气动力和力矩以及重量、重心配平的结果，是唯一的", "在悬停中，要保持直升机没有前后移位，必须使纵向力和俯仰力矩平衡", "悬停时气动力自动保持平衡，无需频繁操纵"], ans: 2, exp: "在悬停状态下，直升机的姿态需要通过飞行员的操纵来维持，而不是完全自动保持平 衡。因此，选项“悬停时气动力自动保持平衡，无需频繁操纵”是错误的。" },
  { id: 1585, cat: "直升机综合", q: "下面关于旋翼的说法错误的是（）", opts: ["本质上讲旋翼是一个能量转换部件，它把发动机通过旋翼轴传来的旋转动能转换成旋翼 拉力", "旋翼的基本功能是产生旋翼拉力", "旋翼的基本功能是产生前进推力"], ans: 2, exp: "旋翼是直升机的核心部件，其主要功能是产生升力，使直升机能够垂直起降和悬停。 而“产生前进推力”并不是旋翼的基本功能，前进推力通常是由固定翼飞机的机翼产生的，直升机的前进动力通常来自于尾部的推进器或者旋翼的倾斜来提供。" },
  { id: 1586, cat: "直升机综合", q: "下面哪种直升机采用了无轴承旋翼？（）", opts: ["S-76 直升机", "苏制米-8 直升机", "UH-60A 直升机"], ans: 0, exp: "S-76 直升机采用了无轴承旋翼设计，这种设计可以减轻重量、降低维护成本和提高可 靠性。苏制米-8 直升机和 UH-60A 直升机未采用无轴承旋翼。" },
  { id: 1587, cat: "直升机综合", q: "下面说法正确的是（）", opts: ["一般来讲，尾桨反扭矩的数值是比较大的", "如果尾桨桨毂中心位于直升机重心之上或重心之下，则不会产生滚转力矩", "尾桨主要用于平衡旋翼的反扭矩，在有些场合也可以改变直升机的侧向平衡状态"], ans: 2, exp: "尾桨的主要功能是平衡旋翼产生的反扭矩，同时也参与直升机的航向控制。尾桨的位 置相对于直升机重心的位置会影响其产生的力矩，特别是滚转力矩。" },
  { id: 1588, cat: "直升机综合", q: "下面说法正确的是（）", opts: ["主减速器的特点是传递的功率大和减速比小", "主减速器的功能是将发动机功率传递给旋翼轴，应满足传动比及换向要求", "尾减速器的输出轴是尾桨轴、输入轴与尾传动轴相连，一般由一对伞齿轮构成，输入轴 与输出轴夹角一般为 45°"], ans: 1, exp: "直升机的主减速器是连接发动机和旋翼系统的关键部件，其主要功能是将发动机的功 率传递给旋翼轴，并满足一定的传动比及换向要求。因此，选项“主减速器的功能是将发动 机功率传递给旋翼轴，应满足传动比及换向要求”是正确的。" },
  { id: 1589, cat: "直升机综合", q: "下面说法正确的是（）", opts: ["“跷跷板”尾桨一般安排结构锥度角，这是因为使拉力与离心力平衡所需的结构锥度角 很小", "无轴承旋翼带有挥舞铰、变距铰，致使结构重量难以减轻，而且维护工作量大、寿命低", "“跷跷板”旋翼有 2 片桨叶共用一个挥舞铰，无摆振铰"], ans: 2, exp: "在直升机旋翼的设计中，“跷跷板”旋翼（半刚性旋翼）是一种常见的旋翼形式，它 具有一些独特的特点。“跷跷板”旋翼有 2 片桨叶共用一个挥舞铰，无摆振铰。这个说法是 正确的，“跷跷板”旋翼的特点是两片桨叶共用一个挥舞铰，没有单独的摆振铰，因此也被 称为半刚性旋翼。" },
  { id: 1590, cat: "直升机综合", q: "下面直升机旋翼的结构形式是无铰式旋翼的是（）", opts: ["法国的松鼠直升机", "BO-105 直升机", "直-11 型直升机"], ans: 1, exp: "BO-105 直升机采用了无铰式旋翼。无铰式旋翼取消了水平铰和垂直铰，但仍有轴向 铰，桨叶在挥舞方向和摆振方向相对于桨毂是固定的，桨叶的挥舞运动和摆振运动表现为桨 叶根部（或桨毂支臂）的弯曲变形。这种设计简化了结构，减少了维护工作量，并提高了直 升机的操纵功效及角速度阻尼。" },
  { id: 1591, cat: "直升机综合", q: "小型无人直升机的操纵系统（）", opts: ["总距、纵向、横向及航向操纵通道相互独立", "总距与航向，纵向操纵运动协调工作，横向操纵通道独立", "总距与航向，横向操纵运动协调工作，纵向操纵通道独立"], ans: 0, exp: "小型无人直升机的操纵系统中，总距、纵向、横向及航向操纵通道相互独立。总距操 纵主要控制直升机的上升和下降；纵向操纵控制直升机的前进和后退；横向操纵控制直升机 的左右移动；航向操纵控制直升机的转向。这四个操纵通道各自独立工作，互不干扰，这样 可以更精确地控制直升机的飞行姿态和位置。" },
  { id: 1592, cat: "直升机综合", q: "悬停时的平衡不包括（）", opts: ["俯仰平衡", "方向平衡", "前飞废阻力平衡"], ans: 2, exp: "悬停时主要考虑的平衡状态包括俯仰平衡、方向平衡等，以确保直升机在静止悬停状 态下的稳定。而前飞废阻力平衡是在直升机前飞状态下需要考虑的，不是悬停时的平衡内容。" },
  { id: 1593, cat: "直升机综合", q: "悬停状态下，旋翼形成（）", opts: ["正锥体", "平面", "到锥体"], ans: 0, exp: "在悬停状态下，旋翼旋转产生升力，由于升力方向垂直于桨盘平面且向上，使得旋翼 形成正锥体形状。桨叶在离心力和升力的共同作用下，呈现出向上逐渐向外扩展的形态，类 似一个正锥体。" },
  { id: 1594, cat: "直升机综合", q: "旋翼水平铰的作用是（）", opts: ["自动调节桨叶升力变化，消除倾斜力矩", "使桨叶拉力发生周期性变化，也会使桨叶根部受到的弯矩发生周期性变化", "产生自下而上的挥舞相对气流，这会使桨叶迎角减小，拉力减小"], ans: 0, exp: "旋翼水平铰可以使桨叶在一定范围内上下挥舞，当直升机飞行状态变化导致桨叶升力 变化时，水平铰可自动调节桨叶的挥舞角度，从而消除侧倾力矩，保持直升机的平衡和稳定。" },
  { id: 1595, cat: "直升机综合", q: "以下不属于常规直升机的尾桨的作用的是（）", opts: ["实现偏航", "实现方向平衡", "实现俯仰平衡"], ans: 2, exp: "常规直升机的尾桨主要用于实现偏航和方向平衡。当直升机需要改变航向时，通过改 变尾桨的推力大小和方向来实现偏航操作，从而保持直升机在飞行中的方向稳定。而实现俯 仰平衡主要是通过主旋翼的前后倾斜等方式来实现，尾桨在这方面不起作用。" },
  { id: 1596, cat: "直升机综合", q: "影响地面效应的因素不包括（）", opts: ["地表环境", "下滑速度和风", "高度"], ans: 1, exp: "影响地面效应的主要因素包括地表环境、高度和飞行速度。地表环境会影响气流的流 动特性，高度决定了地面效应的作用范围，而飞行速度则影响地面效应的强弱。下滑速度和 风虽然会影响飞行器的飞行状态，但它们并不是地面效应的直接因素。" },
  { id: 1597, cat: "直升机综合", q: "影响平飞性能的因素，错误的是（）", opts: ["在小速度平飞时，高度增加，诱阻功率增大较多，而废阻功率减小较少，因此，平飞所 需功率增大。在大速度平飞时，高度增加，诱阻功率增大程度减小，而废阻功率减小程度增 大，平飞所需功率有所减小", "直升机废阻力面积越大，飞行速度越快", "随飞行重量的增大，平飞速度范围缩小"], ans: 1, exp: "1.在小速度平飞时，高度增加确实会使诱阻功率增大较多，废阻功率减小较少，从而 平飞所需功率增大；在大速度平飞时，高度增加，诱阻功率增大程度减小，废阻功率减小程 度增大，平飞所需功率有所减小，这个说法是正确的。 2.直升机废阻力面积越大，会阻碍飞机的飞行，飞行速度会减慢而不是越快，这个说法是错 误的。 3.随着飞行重量的增大，飞机需要更大的升力，而升力和速度有一定关系，所以平飞速度范 围会缩小，这个说法是正确的。" },
  { id: 1598, cat: "直升机综合", q: "影响起飞载重量的主要因素不包括（）", opts: ["机场标高和空气温度", "风速和风向", "上反效应、场地面积和周围障碍物高度"], ans: 2, exp: "影响起飞载重量的主要因素包括机场标高和空气温度、风速和风向等。这些因素会直 接影响飞机的性能和升力。而上反效应、场地面积和周围障碍物高度并不直接影响飞机的起 飞载重量。" },
  { id: 1599, cat: "直升机综合", q: "有地效垂直起飞的定义是（）", opts: ["直升机从垂直离地到 1-3 米高度上悬停，然后保持一定的状态沿预定轨迹增速，并爬升 到一定高度的过程", "直升机从垂直离地到 3-5 米高度上悬停，然后保持一定的状态沿预定轨迹增速，并爬升 到一定高度的过程", "直升机从垂直离地到 1-3 米高度上悬停，然后保持一定的状态沿预定轨迹增速，并爬升 到 20 米高度的过程"], ans: 0, exp: "有地效垂直起飞的定义是指直升机从垂直离地到 1-3 米高度上悬停，然后保持一定的 状态沿预定轨迹增速，并爬升到一定高度的过程。这个定义涉及到直升机利用地面效应，在 近地面的一定高度内进行悬停和增速，以便完成起飞过程。" },
  { id: 1600, cat: "直升机综合", q: "直升机的操纵不包括（）", opts: ["总距操纵", "周期变距", "副翼操纵"], ans: 2, exp: "直升机的操纵主要包括总距操纵和周期变距操纵。总距操纵用于控制直升机的上升和 下降，通过改变旋翼的总距（即桨叶攻角）来调整旋翼产生的升力。周期变距操纵则用于控 制直升机的俯仰和横滚，通过改变旋翼桨叶的周期性变距来实现。而副翼操纵是固定翼飞机 的操纵面之一，用于控制飞机的横滚运动，直升机并不使用副翼进行操纵。" },
  { id: 1601, cat: "直升机综合", q: "直升机的地面效应，是指直升机在接近地面的高度工作时，被旋翼排向地面的气流受到 地面阻挡，从而影响旋翼空气动力的一种现象。影响地面效应的因素包括（）", opts: ["湿度、飞行速度和风、地表环境", "温度、飞行速度和风、地表环境", "高度、飞行速度和风、地表环境"], ans: 2, exp: "直升机的地面效应是指直升机在接近地面的高度工作时，被旋翼排向地面的气流受到 地面阻挡，从而影响旋翼空气动力的一种现象。影响地面效应的因素包括高度、飞行速度和 风、地表环境等。湿度并不是影响地面效应的主要因素之一。" },
  { id: 1602, cat: "直升机综合", q: "直升机的跃升需要注意事项不包括（）", opts: ["直升机可以以高桨距作跃升，也可以以低桨距作跃升，这同固定翼飞机不一样，飞机一 般是在加满油门进入跃升的，这主要是由于不同的跃升目的决定的", "直升机在跃升中，杆力变化明显，这主要是直升机的操纵品质决定的，直升机的单位载 荷杆力比较大", "直升机在跃升过程中，严禁提放总距杆，主要是因为，跃升中拉杆量很小，如果下放总 距可能造成旋翼桨叶同尾梁的危险接近或碰撞"], ans: 2, exp: "直升机在跃升过程中严禁提放总距杆主要是因为跃升中拉杆量很小，下放总距可能造 成旋翼桨叶同尾梁危险接近或碰撞表述不准确。直升机在跃升过程中需要谨慎操作总距杆，但不是绝对严禁提放，应根据实际情况合理调整总距以保持稳定的飞行状态。" },
  { id: 1603, cat: "直升机综合", q: "直升机机体和力矩不包括（）", opts: ["自身重力", "旋翼桨叶的铰链力矩", "旋翼、尾桨的反扭矩和桨毂力矩"], ans: 1, exp: "旋翼桨叶的铰链力矩并不是作用在直升机机体上的力矩，而是指旋翼桨叶与桨毂连接 处的铰链所产生的局部力矩，它主要影响的是旋翼桨叶的挥舞、摆振等运动，并不直接构成 对整个直升机机体的力和力矩。 直升机机体的力和力矩主要包括： 1、自身重力：直升机机体由于地球引力作用而产生的力。 2、旋翼、尾桨的反扭矩和桨毂力矩：旋翼旋转产生的反扭矩需要通过尾桨来平衡，同时旋 翼和尾桨的旋转也会产生力矩作用于直升机机体。" },
  { id: 1604, cat: "直升机综合", q: "直升机实施悬停回转的高度一般不低于（）米", opts: ["3", "4", "5"], ans: 0, exp: "直升机实施悬停回转的高度一般不低于 3 米。这是为了保证在悬停回转过程中的安全，避免因操作失误或突发情况导致直升机与地面障碍物发生碰撞。" },
  { id: 1605, cat: "直升机综合", q: "直升机在风中悬停时下列影响正确的是（）", opts: ["与无风悬停相比，逆风悬停机头稍低，且逆风速越大，机头越低", "一般情况下，直升机应尽量在顺风中悬停", "侧风的作用还将使直升机沿风的去向移位，因此，侧风悬停时应向风来反方向压杆"], ans: 0, exp: "当直升机在风中悬停时，逆风悬停会受到风的阻力，为保持悬停状态，直升机需要增 加一定的功率和调整姿态。由于逆风的作用，机头会稍低，且逆风速越大，机头越低的程度 也会更明显。" },
  { id: 1606, cat: "直升机综合", q: "直升机左、右回转的特点，（）", opts: ["回转时，蹬右舵，尾桨桨距增大，尾桨拉力增大，尾桨所需功率也增大，在发动机功率 不变的条件下，旋翼功率要减小，直升机有下降高度的趋势，应适当地下放总距杆", "左回转时，蹬左舵，尾桨桨距减小，尾桨所需功率减小，功率重新分配的结果，使旋翼 功率增大，直升机有上升高度的趋势，应适当下放总距杆", "左回转时，蹬左舵，尾桨桨距增大，尾桨所需功率增大，功率重新分配的结果，使旋翼 功率减小，直升机有下降高度的趋势，应适当上提总距杆"], ans: 1, exp: "在直升机左回转时，蹬左舵，尾桨桨距减小，尾桨拉力减小，所需功率也减小。由于 发动机功率不变，功率重新分配后，旋翼功率增大，直升机有上升高度的趋势，为保持高度 稳定，应适当下放总距杆以减小旋翼拉力，防止直升机过度上升。" },
  { id: 1607, cat: "直升机综合", q: "自动倾斜器，有多种不同结构形式，但控制机理都是一样的。它们在构造上都应满足要 求（）", opts: ["其动环与旋翼同步旋转，并可绕球铰转动", "能沿旋翼轴方向上下移动，以实现周期变距操纵", "能够向任何方向倾斜，以实现总距操纵"], ans: 0, exp: "自动倾斜器是直升机操纵系统中的关键部件。其动环与旋翼同步旋转，这样才能保证 在旋翼旋转过程中实现对旋翼的操纵。同时可绕球铰转动，使得能够在不同方向上改变旋翼 的桨叶角度，实现对直升机的姿态控制。" },
  { id: 1608, cat: "直升机综合", q: "无人直升机在姿态遥控状态下，如出现动力失效则正确的处理方法是（）", opts: ["保持主旋翼总距不变", "主旋翼总距先提到最大，接地前总距降低到最低", "主旋翼总距先降低到最低，接地前提高到最大"], ans: 2, exp: "无人直升机在姿态遥控状态下出现动力失效时，主旋翼总距先降到最低可以减少旋翼 的阻力，使直升机在无动力状态下下降得相对较为平稳，避免因总距较大而导致下降速度过 快难以控制。在接地前提高到最大是为了尽量减少接地瞬间的冲击力，起到一定的缓冲作用。 选项 A 保持主旋翼总距不变不利于应对动力失效的情况。" },
  { id: 1609, cat: "直升机综合", q: "（）采用上下共轴反转的两组旋翼用来平衡旋翼反扭矩。", opts: ["共轴式直升机", "单旋翼带尾桨直升机", "单旋翼无尾桨直升机"], ans: 0, exp: "共轴式直升机采用上下共轴反转的两组旋翼来平衡旋翼反扭矩，这种设计通过两副旋 翼相反方向旋转产生的扭矩相互抵消，从而实现机身稳定。" },
  { id: 1610, cat: "直升机综合", q: "小型无人直升机的主流操纵系统不包括（）", opts: ["总距、纵向、横向及航向操纵通道相互独立", "总距和纵向、横向操纵运动协调工作，航向操纵通道独立", "总距和纵向、横向操纵运动协调工作，纵向操纵独立"], ans: 2, exp: "小型无人直升机的主流操纵系统通常包括以下两种配置： 1、总距、纵向、横向及航向操纵通道相互独立：这种设计下，每个操纵通道负责特定的飞 行控制功能，互不干扰，便于精确操控。 2、总距与纵向、横向操纵运动协调工作，航向操纵通道独立：在这种配置中，总距与纵向、横向操纵协同作用，提升整体稳定性，而航向操纵保持独立以确保灵活性。 因此，不属于主流操纵系统的是：总距和航向、横向操纵运动协调工作，纵向操纵通道独立。" },
  { id: 1611, cat: "直升机综合", q: "共轴式直升机的主要气动特点不包括（）？", opts: ["具有较高的悬停效率", "废阻面积小于单旋翼直升机", "具有较大的俯仰、横滚控制力度"], ans: 1, exp: "题目考察的是共轴式直升机（Coaxial Rotor Helicopter）的气动特性，各选项 分析如下： 1、具有较高的悬停效率：正确。共轴式直升机由于双旋翼的协同作用，可以提高悬停效率，使得直升机更加稳定地悬停在空中。 2、废阻面积小于单旋翼直升机：错误。共轴式直升机的废阻面积大于单旋翼直升机，因为 其操纵系统部分和上下旋翼桨毂这些非流线形状部件的数量和体积较大。 3、具有较大的俯仰、横滚控制力矩：正确。共轴式直升机的机身较短，且其结构重量和载 重集中在直升机的重心处，因而减少了直升机的俯仰和偏航的转动惯量，从而提供更大的俯 仰和横滚操纵力矩。" },
  { id: 1612, cat: "直升机综合", q: "直升机飞行中需要的操纵是（）", opts: ["需要三个操纵就可以改变俯仰、横测和航向姿态", "需要四个操作才能改变与保持所需姿态", "需要六个，因为直升机空中有六个自由度"], ans: 0, exp: "直升机的飞行操纵主要通过三个主要的操纵面来实现：总距操纵（控制升力）、周期 变距（控制俯仰和横滚）和尾桨操纵（控制航向）。这三个操纵系统可以实现直升机的俯仰、横滚和航向姿态的改变。" },
  { id: 1613, cat: "直升机综合", q: "直升机旋翼拉力的方向为（）？", opts: ["与桨盘平面垂直", "与桨毂旋转面垂直", "与运动方向垂直"], ans: 0, exp: "直升机旋翼拉力的方向与桨盘平面垂直。桨盘平面是指旋翼桨叶旋转形成的平面，拉 力方向垂直于这个平面，提供升力。" },
  { id: 1614, cat: "直升机综合", q: "直升机高度越低，地面效应（），直升机速度越大，地面效应，（）", opts: ["越大、越小", "越小、越大", "越大、越大"], ans: 0, exp: "直升机高度越低，地面效应越大；直升机高度越高，地面效应越小。" },
  { id: 1615, cat: "直升机综合", q: "直升机在（）状态下消耗功率最大", opts: ["前飞", "悬停", "侧飞"], ans: 1, exp: "直升机在悬停状态下消耗功率最大。这是因为悬停时，直升机需要产生足够的升力来 抵消其重力，同时由于没有水平运动，没有额外的气流帮助产生升力，因此发动机需要输出 最大功率来维持悬停。" },
  { id: 1616, cat: "直升机综合", q: "直升机在前飞时桨叶在（）迎角最大", opts: ["90°方位", "180°方位", "270°方位"], ans: 2, exp: "在直升机前飞时，桨叶的迎角会随着桨叶的旋转位置而变化。根据搜索结果，桨叶在 2700 方位时，迎角最大。这是因为在 270°方位时，桨叶的相对气流速度最小，而迎角是相 对气流方向与桨叶弦线之间的夹角，因此在 2700 方位时，迎角达到最大值。" },
  { id: 1617, cat: "直升机综合", q: "直升机在前飞时桨叶在（）迎角最小", opts: ["90°方位", "180°方位", "270°方位"], ans: 0, exp: "在直升机前飞时，桨叶的迎角会随着桨叶的旋转位置而变化。根据搜索结果，桨叶在 90°方位时迎角最小。这是因为在 90°方位时，桨叶的相对气流速度最大，迎角最小，从 而减少了产生阻力的可能性，有助于减小飞行阻力，提高效率。" },
  { id: 1618, cat: "直升机综合", q: "单旋翼直升机主旋翼顶视旋转方向是（）", opts: ["顺时针旋转", "逆时针旋转", "两种都有"], ans: 2, exp: "单旋翼直升机主旋翼顶视选装方向有顺时针和逆时针两种情况。" },
  { id: 1619, cat: "直升机综合", q: "共轴双桨的直升机（）", opts: ["上旋翼是平衡扭矩的，下旋翼是操纵面", "上旋翼是平衡操纵面的，下旋翼是平衡扭矩的", "上下旋翼均为操纵面"], ans: 2, exp: "共轴双桨直升机的上下旋翼均承担着重要的功能，不仅用于产生升力，还用于平衡反 扭矩和进行操纵。因此，上下旋翼在共轴双桨直升机中既是升力面，也是纵横向和航向的操 纵面。" },
  { id: 1620, cat: "直升机综合", q: "共轴双桨直升机错误的是（）", opts: ["全差动", "半差动", "无差动"], ans: 2, exp: "共轴双桨直升机的航向操纵方式包括全差动、半差动、桨尖制动和磁粉制动，不存在 “无差动”这种说法。" },
  { id: 1621, cat: "直升机综合", q: "直升机按起飞重量大致可分为轻型、中型、重型、巨型直升机四种类型，以下哪一项为 中型直升机？（）", opts: ["米-6", "米-8", "米-26"], ans: 1, exp: "直升机按起飞重量大致可分为轻型、中型、重型、巨型直升机四种类型。中型直升机 的起飞重量范围为 4~10 吨。根据这一分类标准，米-8 直升机属于中型直升机，而米-6 直升 机的最大起飞重量为 41700 千克，米-26 直升机的最大起飞重量为 56000 千克，均超出了中 型直升机的重量范围。因此，正确答案是：米-8" },
  // ==================== 农业植保 ====================
  { id: 1622, cat: "农业植保", q: "根据CAAC规定，从事植保无人机作业的人员应当年满多少周岁？", opts: ["16周岁", "18周岁", "20周岁", "22周岁"], ans: 0, exp: "CAAC规定从事植保无人机作业人员需年满16周岁，且经过专业培训取得相应资质。" },
  { id: 1623, cat: "农业植保", q: "植保无人机超视距运行（BVLOS）作业时，操作员应持有哪种执照？", opts: ["Ⅲ类多旋翼视距内执照", "Ⅲ类多旋翼超视距执照", "Ⅱ类多旋翼视距内执照", "无需执照"], ans: 1, exp: "超视距运行需持有对应类别及等级的超视距驾驶员执照，Ⅲ类多旋翼超视距执照是植保无人机常用资质。" },
  { id: 1624, cat: "农业植保", q: "根据《无人驾驶航空器飞行管理暂行条例》，植保无人机最大起飞重量不超过多少千克时，无需申请飞行计划？", opts: ["25kg", "30kg", "15kg", "50kg"], ans: 0, exp: "条例规定最大起飞重量不超过25千克的微型无人机在适飞空域内飞行无需申请飞行计划。" },
  { id: 1625, cat: "农业植保", q: "植保无人机在人口密集区域作业时，飞行高度不得超过多少米？", opts: ["15m", "20m", "30m", "50m"], ans: 0, exp: "根据规定，植保无人机在人口密集区上方作业时，飞行高度不得超过15米，且需避开人员活动区域。" },
  { id: 1626, cat: "农业植保", q: "植保无人机操作员在作业前需要确认的保险类型是？", opts: ["机身险", "第三者责任险", "操作员意外险", "三者险和操作员意外险均需确认"], ans: 3, exp: "植保作业涉及公共安全，操作员需确认购买了第三者责任险和操作员意外险，确保人机双保险。" },
  { id: 1627, cat: "农业植保", q: "植保无人机作业时，与周边高压线的安全距离应至少保持多少米？", opts: ["5m", "10m", "15m", "20m"], ans: 1, exp: "植保无人机飞行时应至少远离高压线10米以上，防止电磁干扰和碰撞事故。" },
  { id: 1628, cat: "农业植保", q: "根据CAAC规定，植保无人机操作员需经过多少学时的专业培训？", opts: ["20学时", "40学时", "56学时", "80学时"], ans: 2, exp: "CAAC要求植保无人机操作员需完成56学时的专业培训课程，包括理论和实操。" },
  { id: 1629, cat: "农业植保", q: "植保无人机在夜间作业时，必须配备的设备是？", opts: ["高亮度遥控器", "防雾摄像头", "航行灯和防撞灯", "降落伞"], ans: 2, exp: "夜间作业需配备航行灯和防撞灯，确保飞行器在空中能被识别，降低碰撞风险。" },
  { id: 1630, cat: "农业植保", q: "植保无人机作业时，操作员与飞行器之间的最大视距距离是多少？", opts: ["300m", "500m", "800m", "1000m"], ans: 1, exp: "视距内运行要求操作员与无人机保持500米以内的可视距离，确保能实时观察飞行状态。" },
  { id: 1631, cat: "农业植保", q: "植保无人机作业完毕后，应如何记录作业信息？", opts: ["口头记录即可", "在飞行日志中记录作业时间、地点和用药量", "仅在手机备忘录记录", "不需要记录"], ans: 1, exp: "法规要求作业完毕后需在飞行日志中详细记录作业时间、地点、农药种类和用量等信息，留存备查。" },
  { id: 1632, cat: "农业植保", q: "农药的pH值对药效的影响主要体现在哪方面？", opts: ["颜色变化", "药液稳定性与分解速率", "气味变化", "包装腐蚀"], ans: 1, exp: "pH值影响药液稳定性，过酸或过碱会导致农药有效成分分解，影响药效和喷洒效果。" },
  { id: 1633, cat: "农业植保", q: "以下哪种农药剂型最适合植保无人机低容量喷洒？", opts: ["可湿性粉剂（WP）", "乳油（EC）", "水剂（AS）", "悬浮剂（SC）"], ans: 3, exp: "悬浮剂（SC）粒径细、不堵塞喷头、兑水稀释后稳定性好，最适合植保无人机低容量喷洒。" },
  { id: 1634, cat: "农业植保", q: "农药安全间隔期是指什么？", opts: ["两次喷洒之间的间隔天数", "最后一次施药到收获之间的天数", "农药开封后的存放天数", "农药与肥料混合后可使用天数"], ans: 1, exp: "安全间隔期指最后一次施药到作物收获之间的天数，在此期限内残留量降至安全标准以下。" },
  { id: 1635, cat: "农业植保", q: "植保无人机喷洒农药时，每亩用水量通常为多少？", opts: ["0.5-2升", "5-10升", "15-30升", "30-50升"], ans: 0, exp: "植保无人机采用超低容量喷洒技术，每亩用水量通常为0.5-2升，远低于传统人工喷雾。" },
  { id: 1636, cat: "农业植保", q: "两种农药混合使用时，最容易出现的问题是？", opts: ["颜色变深", "产生沉淀或分层", "温度升高", "粘度降低"], ans: 1, exp: "混用农药时，酸碱反应或成分不兼容易产生沉淀或分层，堵塞喷头且影响药效。" },
  { id: 1637, cat: "农业植保", q: "农药按毒性分为几个等级？", opts: ["2个等级", "3个等级", "4个等级", "5个等级"], ans: 1, exp: "农药按毒性分为高毒、中毒和低毒三个等级，植保无人机作业应优先选用低毒农药。" },
  { id: 1638, cat: "农业植保", q: "使用植保无人机喷洒除草剂时，最需要注意的问题是？", opts: ["飞行速度过快", "雾滴漂移到邻近敏感作物", "电池续航不足", "遥控器信号干扰"], ans: 1, exp: "除草剂对敏感作物危害大，无人机喷洒时务必注意雾滴漂移，避免对邻近作物造成药害。" },
  { id: 1639, cat: "农业植保", q: "植保无人机作业中，农药稀释倍数计算正确的是？", opts: ["农药原药量÷加水量", "加水量÷农药原药量", "农药原药量×加水量", "加水量×稀释倍数"], ans: 1, exp: "稀释倍数=加水量÷农药原药量，正确计算稀释倍数可确保药液浓度符合植保要求。" },
  { id: 1640, cat: "农业植保", q: "飞防作业中，农药助剂的主要作用是？", opts: ["增加农药成本", "改善雾滴沉积、抗蒸发和抗漂移", "改变农药颜色便于观察", "增加农药毒性"], ans: 1, exp: "飞防助剂通过降低表面张力、抗蒸发、抗漂移等作用，提高雾滴在叶面的沉积效果。" },
  { id: 1641, cat: "农业植保", q: "植保无人机喷洒油剂农药时，应特别注意什么？", opts: ["油剂粘度大易堵塞管路", "油剂对无人机塑料件有腐蚀作用", "油剂易挥发", "油剂毒性更大"], ans: 1, exp: "油剂农药中的有机溶剂对无人机药箱、管路等塑料件有腐蚀作用，使用后需及时清洗。" },
  { id: 1642, cat: "农业植保", q: "植保无人机常用的离心喷头与压力喷头相比，优势是什么？", opts: ["成本更低", "雾滴粒径更均匀可控", "重量更轻", "无需清洗"], ans: 1, exp: "离心喷头通过离心力将药液雾化，雾滴粒径均匀且可调，优于压力喷头的雾化效果。" },
  { id: 1643, cat: "农业植保", q: "植保无人机喷洒作业中，雾滴粒径通常控制在哪个范围？", opts: ["10-50μm", "50-250μm", "300-500μm", "500-1000μm"], ans: 1, exp: "飞防作业雾滴粒径通常控制在50-250μm，过小易漂移，过大则沉积效果差、覆盖率低。" },
  { id: 1644, cat: "农业植保", q: "植保无人机喷洒时，影响雾滴沉积效果的主要因素是？", opts: ["无人机颜色", "风速、温度和湿度", "操作员年龄", "电池品牌"], ans: 1, exp: "风速、温度和湿度直接影响雾滴蒸发速率和飘移方向，是决定沉积效果的关键气象因素。" },
  { id: 1645, cat: "农业植保", q: "植保无人机常用的喷头类型不包括以下哪种？", opts: ["离心喷头", "压力喷头", "超声喷头", "滴灌喷头"], ans: 3, exp: "滴灌喷头用于地面灌溉系统，不适用于无人机空中喷洒。飞防常用的是离心喷头和压力喷头。" },
  { id: 1646, cat: "农业植保", q: "植保无人机喷洒系统中，流量计的作用是？", opts: ["测量飞行速度", "实时监测药液流量并反馈给飞控", "测量电池电压", "检测喷头温度"], ans: 1, exp: "流量计实时监测药液流量，飞控根据流量数据动态调节喷洒量，确保均匀喷洒。" },
  { id: 1647, cat: "农业植保", q: "植保无人机作业时，喷头距离作物冠层的最佳高度是？", opts: ["0.3-0.5m", "1-2m", "2-3m", "3-5m"], ans: 1, exp: "喷头距作物冠层1-2米时雾滴沉积效果最佳，过高雾滴漂移严重，过低则覆盖不均匀。" },
  { id: 1648, cat: "农业植保", q: "植保无人机喷洒时，雾滴覆盖密度（个/cm²）的要求一般是多少？", opts: ["5-10个/cm²", "20-30个/cm²", "50-80个/cm²", "100-200个/cm²"], ans: 1, exp: "飞防作业要求雾滴覆盖密度为20-30个/cm²，低于此标准会影响防治效果。" },
  { id: 1649, cat: "农业植保", q: "植保无人机双向喷洒（AB点模式）相比单向喷洒的优势是？", opts: ["节省农药", "减少雾滴重叠和漏喷", "飞行速度更快", "电池续航更长"], ans: 1, exp: "双向喷洒模式沿AB点往返喷洒，可有效减少雾滴重叠和漏喷区域，提高喷洒均匀性。" },
  { id: 1650, cat: "农业植保", q: "植保无人机喷头堵塞时，正确的处理方法是？", opts: ["用嘴吹通", "用针或专用工具清理后用清水冲洗", "直接更换喷头", "加大水泵压力冲开"], ans: 1, exp: "喷头堵塞应用专用工具清理并清水冲洗，避免用嘴吹以防农药入口中毒。" },
  { id: 1651, cat: "农业植保", q: "植保无人机作业中，RTK定位系统的主要作用是？", opts: ["提高飞行速度", "实现厘米级精准定位和航线规划", "增强遥控器信号", "延长电池续航"], ans: 1, exp: "RTK（实时动态差分定位）提供厘米级定位精度，确保植保无人机精准沿航线飞行。" },
  { id: 1652, cat: "农业植保", q: "植保无人机操作员作业时，必须穿戴的个人防护装备不包括？", opts: ["防护服", "防毒面具或口罩", "防护手套", "安全帽"], ans: 3, exp: "安全帽通常用于建筑工地，植保作业主要防护农药接触，需穿戴防护服、口罩和手套。" },
  { id: 1653, cat: "农业植保", q: "喷洒农药时如遇阵风风速超过多少级应立即停止作业？", opts: ["2级", "3级", "4级", "5级"], ans: 2, exp: "超过3级风（风速4-5m/s）时雾滴漂移严重，应立即停止作业，避免药害和药效下降。" },
  { id: 1654, cat: "农业植保", q: "植保无人机作业时，操作员误触农药喷洒开关导致地面人员被喷，应急处置顺序是？", opts: ["继续作业", "立即停止喷洒、无人机降落、携带农药标签送医", "关闭无人机电源", "调高飞行高度"], ans: 1, exp: "误喷人员应立即停止作业、降落无人机，并携带农药标签送医，便于医生对症治疗。" },
  { id: 1655, cat: "农业植保", q: "植保无人机作业时，油箱（药箱）泄露的应急处理措施是？", opts: ["继续作业等喷完再处理", "立即降落、关闭喷洒系统、用吸附材料处理泄露药液", "用水冲洗无人机即可", "直接返航"], ans: 1, exp: "药箱泄露应立即降落并关闭喷洒系统，用沙土或吸附材料处理泄露药液，防止污染环境。" },
  { id: 1656, cat: "农业植保", q: "植保无人机作业中，饮用水源周边多少米范围内禁止喷洒农药？", opts: ["50m", "100m", "200m", "500m"], ans: 2, exp: "饮用水源周边200米范围内禁止喷洒农药，防止农药污染水源，保障饮水安全。" },
  { id: 1657, cat: "农业植保", q: "植保无人机操作员在作业前应做的健康自查不包括？", opts: ["确认无感冒发烧", "确认无皮肤破损", "确认已饮酒提神", "确认无过度疲劳"], ans: 2, exp: "操作员严禁酒后作业，饮酒会严重影响判断力和反应速度，增加作业风险。" },
  { id: 1658, cat: "农业植保", q: "植保无人机作业时，发现蜜蜂养殖场应如何处理？", opts: ["正常作业无需理会", "调整航线避开养蜂场50米以上", "降低飞行高度快速通过", "加大农药浓度快速喷完"], ans: 1, exp: "农药对蜜蜂有剧毒，需调整航线避开养蜂场至少50米，防止农药漂移毒杀蜜蜂。" },
  { id: 1659, cat: "农业植保", q: "植保无人机作业中，遥控器信号丢失的应急处理是？", opts: ["等待无人机自行坠落", "无人机自动执行失控保护（返航或悬停）", "关闭遥控器重新开机", "拔掉电池"], ans: 1, exp: "信号丢失时，无人机自动触发失控保护机制，按预设程序执行返航或悬停，等待信号恢复。" },
  { id: 1660, cat: "农业植保", q: "植保无人机电池发生鼓包时，正确的处理方式是？", opts: ["继续使用", "用针放气", "停止使用并妥善处置报废", "放入冰箱降温"], ans: 2, exp: "电池鼓包表明内部损坏，存在起火爆炸风险，应立即停止使用并按规定回收处置。" },
  { id: 1661, cat: "农业植保", q: "植保无人机作业时，操作员之间应保持的最小安全距离是？", opts: ["2m", "5m", "10m", "20m"], ans: 1, exp: "操作员间应保持5米以上安全距离，避免多机同时作业时发生碰撞或相互干扰。" },
  { id: 1662, cat: "农业植保", q: "植保无人机药箱通常采用什么材料制造？", opts: ["普通塑料", "不锈钢", "抗腐蚀PE或PP材料", "玻璃纤维"], ans: 2, exp: "药箱采用抗腐蚀的聚乙烯（PE）或聚丙烯（PP）材料，耐酸碱腐蚀且重量轻。" },
  { id: 1663, cat: "农业植保", q: "植保无人机的水泵类型通常采用哪种？", opts: ["离心泵", "隔膜泵或蠕动泵", "齿轮泵", "柱塞泵"], ans: 1, exp: "隔膜泵或蠕动泵具有自吸能力强、流量稳定、耐腐蚀等优点，是植保无人机最常用的水泵类型。" },
  { id: 1664, cat: "农业植保", q: "植保无人机的喷洒系统由哪些主要部件组成？", opts: ["电机、螺旋桨、电池", "药箱、水泵、管路、喷头和流量计", "飞控、GPS、IMU", "遥控器、接收机、天线"], ans: 1, exp: "喷洒系统包括药箱、水泵、输液管路、喷头和流量计，负责药液的储存、输送和喷洒。" },
  { id: 1665, cat: "农业植保", q: "植保无人机药箱的液位传感器故障会导致什么后果？", opts: ["无人机无法起飞", "无法准确监测剩余药量，可能空泵运行损坏水泵", "飞行速度变慢", "遥控器报警"], ans: 1, exp: "液位传感器故障时无法准确获知剩余药量，空泵运行会导致水泵过热损坏。" },
  { id: 1666, cat: "农业植保", q: "植保无人机机身结构通常采用什么材料？", opts: ["碳纤维复合材料", "纯铝合金", "木材", "普通塑料"], ans: 0, exp: "碳纤维复合材料具有强度高、重量轻、耐腐蚀等优点，是植保无人机机臂和机身的主流材料。" },
  { id: 1667, cat: "农业植保", q: "植保无人机飞控系统的主要功能不包括？", opts: ["姿态稳定控制", "航线规划与自主飞行", "药液成分分析", "喷洒联动控制"], ans: 2, exp: "飞控负责姿态控制、航线规划和喷洒联动，但不具备药液成分分析功能。" },
  { id: 1668, cat: "农业植保", q: "植保无人机的水泵过滤器堵塞时，应如何处理？", opts: ["加大水泵功率强制通过", "拆下过滤器用清水冲洗干净", "直接拆除过滤器", "更换整条管路"], ans: 1, exp: "过滤器堵塞后应拆下并用清水冲洗干净，清除杂质后重新安装，不可暴力强排或拆除。" },
  { id: 1669, cat: "农业植保", q: "植保无人机喷洒系统中，单向阀的作用是？", opts: ["调节流量", "防止药液倒流回药箱", "增加压力", "过滤杂质"], ans: 1, exp: "单向阀确保药液只能从药箱流向喷头，防止药液倒流损坏水泵或造成药箱污染。" },
  { id: 1670, cat: "农业植保", q: "植保无人机作业时，降低飞行速度会导致什么变化？", opts: ["雾滴穿透力下降", "单位面积药液沉积量增加", "续航时间延长", "喷幅变窄"], ans: 1, exp: "飞行速度降低后，单位面积上喷洒的药液量增加，沉积密度提高，但作业效率下降。" },
  { id: 1671, cat: "农业植保", q: "植保无人机作业高度升高时，对喷洒效果的影响是？", opts: ["雾滴覆盖更均匀", "雾滴漂移增加、沉积量下降", "药液蒸发减少", "喷洒压力增大"], ans: 1, exp: "作业高度升高使雾滴飞行距离增加，受风影响更大，漂移加剧且作物表面沉积量减少。" },
  { id: 1672, cat: "农业植保", q: "植保无人机在水稻田作业时，推荐飞行高度为多少？", opts: ["0.5-1m", "1.5-2.5m", "3-4m", "4-5m"], ans: 1, exp: "水稻田作业推荐高度1.5-2.5m，利用旋翼下洗气流将雾滴压入水稻中下部，提高穿透性。" },
  { id: 1673, cat: "农业植保", q: "植保无人机在果树（如柑橘、苹果）作业时，推荐飞行速度是多少？", opts: ["1-2m/s", "3-5m/s", "6-8m/s", "8-10m/s"], ans: 1, exp: "果树冠层茂密，推荐3-5m/s的中低速飞行，确保雾滴有足够时间穿透树冠。" },
  { id: 1674, cat: "农业植保", q: "植保无人机喷幅是指什么？", opts: ["无人机翼展宽度", "喷洒作业中有效覆盖的宽度", "药箱长度", "喷头之间的间距"], ans: 1, exp: "喷幅指无人机飞行时有效雾滴覆盖的宽度，是规划航线行距的重要参数。" },
  { id: 1675, cat: "农业植保", q: "植保无人机作业时，航线间距通常设置为喷幅的多少倍？", opts: ["0.5倍", "0.8-1.0倍", "1.5-2.0倍", "2.5-3.0倍"], ans: 1, exp: "航线间距通常设为喷幅的0.8-1.0倍，保证相邻航线的雾滴有一定重叠，避免漏喷。" },
  { id: 1676, cat: "农业植保", q: "植保无人机在高温（35°C以上）天气作业时，应如何调整参数？", opts: ["提高飞行高度", "增加飞行速度减少药液蒸发", "适当降低飞行速度和高度，或在早晚温度较低时作业", "加大农药浓度"], ans: 2, exp: "高温下雾滴蒸发快，应降低飞行高度和速度，选择早晚凉爽时段作业，减少蒸发损失。" },
  { id: 1677, cat: "农业植保", q: "植保无人机作业时，每亩喷洒量（流量）与飞行速度的关系是？", opts: ["流量=速度×喷幅×每亩喷洒量", "每亩喷洒量=总流量÷（飞行速度×喷幅）", "流量与速度无关", "速度越快每亩喷洒量越大"], ans: 1, exp: "每亩喷洒量=总流量÷（飞行速度×喷幅），速度越快则单位面积喷洒量越少。" },
  { id: 1678, cat: "农业植保", q: "植保无人机在坡地（坡度＞15°）作业时，应如何调整航线？", opts: ["沿等高线飞行", "垂直等高线上下飞行", "随意飞行", "只在坡顶飞行"], ans: 0, exp: "坡地作业应沿等高线飞行，保持无人机与作物冠层高度一致，确保喷洒均匀。" },
  { id: 1679, cat: "农业植保", q: "植保无人机作业时，地头转弯处应如何处理喷洒开关？", opts: ["保持喷洒状态", "在转弯前关闭喷洒，转弯后重新开启", "加大喷洒量", "全程关闭喷洒"], ans: 1, exp: "转弯处无人机速度变化且航向改变，关闭喷洒可避免药液堆积造成药害和浪费。" },
  { id: 1680, cat: "农业植保", q: "植保无人机作业后，喷洒系统的日常清洗方法是？", opts: ["仅用清水冲洗外观", "用清水循环冲洗药箱、管路和喷头至无残留", "用酒精浸泡", "不需要清洗"], ans: 1, exp: "作业后需用清水循环冲洗整个喷洒系统，包括药箱、管路和喷头，防止农药残留腐蚀设备。" },
  { id: 1681, cat: "农业植保", q: "植保无人机电池的日常保养中，存储电压应为多少？", opts: ["充满电存储（4.2V/节）", "3.7-3.85V/节（50%-60%电量）", "放空电存储", "任意电压均可"], ans: 1, exp: "锂电池长期存储应保持在3.7-3.85V/节（50%-60%电量），满电或亏电存储都会缩短电池寿命。" },
  { id: 1682, cat: "农业植保", q: "植保无人机电机轴承的日常维护周期是？", opts: ["每次作业后", "每飞行50小时加注轴承润滑油", "每月更换一次", "无需维护"], ans: 1, exp: "电机轴承每飞行50小时应加注适量专用润滑油，保持转动顺畅，延长电机寿命。" },
  { id: 1683, cat: "农业植保", q: "植保无人机螺旋桨出现裂纹时应如何处理？", opts: ["用胶水粘合继续使用", "立即更换新螺旋桨", "打磨裂纹表面", "继续使用不影响"], ans: 1, exp: "螺旋桨裂纹会导致空中断裂风险，必须立即更换，不可修补后继续使用。" },
  { id: 1684, cat: "农业植保", q: "植保无人机长时间停用（超过1个月）时，正确的存放方法是？", opts: ["整机露天存放", "清洗干燥后存放在阴凉干燥处，电池取下单独存放", "加满药液防干裂", "折叠后随意堆放"], ans: 1, exp: "长时间停用应先清洗干燥，存放在阴凉干燥处，电池取下单独存放并定期检查电压。" },
  { id: 1685, cat: "农业植保", q: "植保无人机喷洒系统使用后，若长时间不维护最可能发生的问题是？", opts: ["电机锈蚀", "喷头和管路干结堵塞", "GPS信号丢失", "遥控器失灵"], ans: 1, exp: "药液残留干结后会堵塞喷头和管路，因此每次作业后必须彻底清洗喷洒系统。" },
  { id: 1686, cat: "农业植保", q: "植保无人机的IMU（惯性测量单元）需要定期校准，主要原因是？", opts: ["电池电量下降", "温度变化和振动导致传感器漂移", "GPS信号减弱", "螺旋桨磨损"], ans: 1, exp: "温度变化和长期振动会导致IMU传感器数据漂移，定期校准可确保姿态控制精度。" },
  { id: 1687, cat: "农业植保", q: "植保无人机水泵的日常维护要点是？", opts: ["定期更换水泵电机", "检查泵体密封性、清洗过滤器、防止干转", "每天更换水泵", "不需要维护"], ans: 1, exp: "水泵维护重点包括检查密封性、清洗过滤器、防止空转干烧，确保使用寿命。" },
  { id: 1688, cat: "农业植保", q: "植保无人机RTK天线损坏时，会直接影响什么？", opts: ["飞行速度", "喷洒流量", "定位精度和航线执行精度", "电池续航"], ans: 2, exp: "RTK天线损坏后无法接收差分信号，定位精度从厘米级降至米级，严重影响航线精度。" },
  { id: 1689, cat: "农业植保", q: "植保无人机作业后，充电器散热风扇不转时应如何处理？", opts: ["继续使用不影响", "立即停止使用并送修或更换", "拍打风扇使其转动", "降低充电电流即可"], ans: 1, exp: "充电器散热风扇不转会导致过热，存在火灾隐患，必须停止使用并维修更换。" },
  { id: 1690, cat: "农业植保", q: "植保无人机机臂折叠机构松动时，最可能造成什么后果？", opts: ["无人机飞行不稳、振动加剧甚至失控", "电池续航下降", "喷洒流量增大", "遥控器信号变差"], ans: 0, exp: "机臂折叠机构松动会导致飞行器结构刚度下降，飞行中振动加剧，严重时可能失控。" },
  { id: 1691, cat: "农业植保", q: "植保无人机各部件中，最需要定期更换的易损件是？", opts: ["飞控主板", "螺旋桨、喷头、密封圈", "GPS模块", "碳纤维机臂"], ans: 1, exp: "螺旋桨（磨损裂纹）、喷头（堵塞磨损）和密封圈（老化）是消耗最频繁的易损件，需定期检查更换。" },
];
